/* Banco NUEVO de Biblionario (2026-10-26): preguntas producidas por libro para el Camino.
   Formato idéntico al banco actual; la correcta es siempre opciones[0].
   ES: RV1909 / EN: WEB (dominio público). Generado desde banco-produccion/. */
var BANCO_NUEVO_ES = {"Éxodo":[{"pregunta":"¿Cómo se llamaban las dos parteras hebreas que se negaron a obedecer la orden del faraón de matar a los niños varones?","opciones":["Sifra y Fúa","María y Séfora","Débora y Jael","Ana y Penina"],"dato":"El faraón ordenó a las parteras matar a los varones hebreos al nacer, pero ellas temieron a Dios y dejaron vivir a los niños.","cita":"Éxodo 1:15","versiculo":"Y habló el rey de Egipto á las parteras de las hebreas, una de las cuales se llamaba Sifra, y otra Fúa.","vcita":"Éxodo 1:15","pista":"«Eran dos mujeres valientes que atendían a las madres hebreas.»"},{"pregunta":"¿Qué recogían los israelitas el sexto día respecto al maná?","opciones":["Doble porción, porque al día siguiente era reposo","Nada, porque ese día ayunaban","Solo la mitad, para compartirla con los egipcios","El triple, para guardar para todo el mes"],"dato":"El sexto día recogían dos gomores por persona, porque el séptimo día, el día de reposo, no caía maná en el campo.","cita":"Éxodo 16:22","versiculo":"En el sexto día recogieron doblada porción de comida, dos gomores para cada uno: y todos los príncipes de la congregación vinieron á Moisés, y se lo hicieron saber.","vcita":"Éxodo 16:22","pista":"«Piensa en el día de reposo: ese día no había maná en el campo.»"},{"pregunta":"¿El consejo de quién siguió Moisés para nombrar ayudantes que juzgaran al pueblo y le quitaran carga?","opciones":["El de Jetro, su suegro","El de Aarón, su hermano","El de Josué, su servidor","El de Coré y los ancianos"],"dato":"Jetro, suegro de Moisés y sacerdote de Madián, vio que Moisés se agotaba juzgando solo de mañana a tarde y le aconsejó poner cabezas sobre el pueblo.","cita":"Éxodo 18:24","versiculo":"Y oyó Moisés la voz de su suegro, é hizo todo lo que él le dijo.","vcita":"Éxodo 18:24","pista":"«Era el suegro de Moisés, sacerdote de Madián.»"}],"Levítico":[{"pregunta":"¿Qué gran mandamiento, citado siglos después por Jesús, aparece ya en Levítico?","opciones":["Amarás a tu prójimo como a ti mismo","Honra a tu padre y a tu madre","No codiciarás la casa de tu prójimo","Acuérdate del día de reposo"],"dato":"Levítico 19:18 ordena no guardar rencor y amar al prójimo como a uno mismo; Jesús lo puso junto al amor a Dios como resumen de la Ley.","cita":"Levítico 19:18","versiculo":"No te vengarás, ni guardarás rencor á los hijos de tu pueblo: mas amarás á tu prójimo como á ti mismo. Yo Jehová.","vcita":"Levítico 19:18","pista":"«Es el mandamiento que mira hacia el prójimo, no hacia uno mismo.»"},{"pregunta":"¿Por qué debían ser santos los israelitas, según Levítico 19?","opciones":["Porque santo es Dios, su Señor","Para lucir distintos con sus ropas","Porque el sacerdote así lo prefería","Para poder comerciar con las naciones"],"dato":"La razón de la santidad del pueblo no es su mérito, sino el carácter de Dios: «santo soy yo Jehová vuestro Dios».","cita":"Levítico 19:2","versiculo":"Habla á toda la congregación de los hijos de Israel, y diles: Santos seréis, porque santo soy yo Jehová vuestro Dios.","vcita":"Levítico 19:2","pista":"«La respuesta está en quién es Dios, no en quiénes eran ellos.»"},{"pregunta":"En el Día de la Expiación, ¿qué animal era enviado vivo al desierto cargando simbólicamente los pecados del pueblo?","opciones":["El macho cabrío para Azazel","Un cordero sin defecto","Un toro joven","Dos palominos"],"dato":"De dos machos cabríos, uno era ofrecido por el pecado y el otro, sobre el que se confesaban las iniquidades del pueblo, era soltado vivo en el desierto.","cita":"Levítico 16:22","versiculo":"Y aquel macho cabrío llevará sobre sí todas las iniquidades de ellos á tierra inhabitada; y dejará ir el macho cabrío por el desierto.","vcita":"Levítico 16:22","pista":"«Se iba caminando al desierto con todos los pecados encima.»"},{"pregunta":"¿Cada cuántos años se celebraba el año de jubileo, cuando se proclamaba libertad en la tierra?","opciones":["Cada 50 años","Cada 7 años","Cada 40 años","Cada 100 años"],"dato":"Tras siete ciclos de siete años llegaba el año cincuenta: se proclamaba libertad, cada uno volvía a su posesión y a su familia.","cita":"Levítico 25:10","versiculo":"Y santificaréis el año cincuenta, y pregonaréis libertad en la tierra á todos sus moradores: este os será jubileo.","vcita":"Levítico 25:10","pista":"«Siete veces siete años... y uno más.»"},{"pregunta":"¿Qué debía pasar con la tierra de cultivo en el séptimo año?","opciones":["Descansar: no se sembraba ni se podaba","Ser vendida a los más pobres","Ser quemada por completo","Ser arada el doble que de costumbre"],"dato":"El año sabático era un sábado de reposo para la tierra misma: un año sin siembra ni poda, confiando en la provisión de Dios.","cita":"Levítico 25:4","versiculo":"Mas el séptimo año la tierra tendrá sábado de reposo para Jehová: no sembrarás tu tierra, ni podarás tu viña.","vcita":"Levítico 25:4","pista":"«Hasta la tierra tenía su día de reposo... pero de un año entero.»"},{"pregunta":"¿Qué fiesta se celebraba el día catorce del mes primero?","opciones":["La Pascua de Jehová","La fiesta de los Tabernáculos","El Día de la Expiación","La fiesta de las Semanas"],"dato":"El calendario de fiestas de Levítico 23 abre con el sábado semanal y luego la Pascua, el catorce del primer mes, «entre las dos tardes».","cita":"Levítico 23:5","versiculo":"En el mes primero, á los catorce del mes, entre las dos tardes, pascua es de Jehová.","vcita":"Levítico 23:5","pista":"«Es la fiesta que recuerda la salida de Egipto.»"},{"pregunta":"¿Dónde debían habitar los israelitas durante los siete días de la fiesta de los Tabernáculos?","opciones":["En cabañas","En el atrio del tabernáculo","En tiendas de campaña de pieles","En las casas de los sacerdotes"],"dato":"Vivir una semana en cabañas recordaba a cada generación que Israel habitó en cabañas cuando Dios lo sacó de Egipto.","cita":"Levítico 23:42","versiculo":"En cabañas habitaréis siete días: todo natural de Israel habitará en cabañas.","vcita":"Levítico 23:42","pista":"«El nombre de la fiesta ya te lo dice.»"},{"pregunta":"Según Levítico, ¿dónde está la vida de la carne?","opciones":["En la sangre","En el corazón","En el hígado","En el aliento de los huesos"],"dato":"Por eso la sangre no se comía y era la que hacía expiación sobre el altar: «la misma sangre expiará la persona».","cita":"Levítico 17:11","versiculo":"Porque la vida de la carne en la sangre está: y yo os la he dado para expiar vuestras personas sobre el altar; por lo cual la misma sangre expiará la persona.","vcita":"Levítico 17:11","pista":"«Por eso estaba prohibido comerla.»"},{"pregunta":"¿Por qué el puerco era contado entre los animales inmundos?","opciones":["Tiene pezuña hendida pero no rumia","Porque vive revolcándose en el barro","Porque es un animal nocturno","Porque no tiene escamas"],"dato":"La regla de los animales limpios de Levítico 11 combinaba señales: el animal terrestre debía rumiar y tener la pezuña hendida; al puerco le falta una de las dos.","cita":"Levítico 11:7","versiculo":"Y el puerco, porque tiene pezuñas, y es de pezuñas hendidas, mas no rumia, tendréislo por inmundo.","vcita":"Levítico 11:7","pista":"«Tenía una señal de las dos que pedía la ley.»"},{"pregunta":"Si alguien no tenía lo suficiente para ofrecer un cordero, ¿qué podía ofrecer en su lugar?","opciones":["Dos tórtolas o dos palominos","Solo un puñado de harina, sin animales","Nada: quedaba fuera del culto","Un cabrito de dos años"],"dato":"La ley graduaba las ofrendas según los recursos de cada uno: hasta el más pobre tenía una ofrenda a su alcance.","cita":"Levítico 12:8","versiculo":"Y si no alcanzare su mano lo suficiente para un cordero, tomará entonces dos tórtolas ó dos palominos, el uno para holocausto, y el otro para expiación.","vcita":"Levítico 12:8","pista":"«María ofreció exactamente esto al presentar a Jesús en el templo.»"},{"pregunta":"¿Cuántos días se contaban hasta la fiesta de las Semanas, la fiesta de la siega?","opciones":["Cincuenta días","Cuarenta días","Siete días","Cien días"],"dato":"Se contaban siete sábados completos desde las primicias y al día siguiente, el día cincuenta, se ofrecía el nuevo presente; de ahí el nombre griego «Pentecostés».","cita":"Levítico 23:16","versiculo":"Hasta el siguiente día del séptimo sábado contaréis cincuenta días; entonces ofreceréis nuevo presente á Jehová.","vcita":"Levítico 23:16","pista":"«De esa cuenta viene el nombre «Pentecostés».»"},{"pregunta":"¿A quién pertenecía el diezmo de la tierra y del fruto de los árboles?","opciones":["A Jehová: era cosa consagrada a él","Al rey de Israel","A los mercaderes del templo","A cada familia, para guardarlo en casa"],"dato":"El diezmo no se describe como una cuota para la institución, sino como propiedad de Dios mismo: «de Jehová son; es cosa consagrada».","cita":"Levítico 27:30","versiculo":"Y todas las décimas de la tierra, así de la simiente de la tierra como del fruto de los árboles, de Jehová son; es cosa consagrada á Jehová.","vcita":"Levítico 27:30","pista":"«La décima parte ya tenía dueño antes de cosecharse.»"}],"Números":[{"pregunta":"¿Cómo comienza la bendición con que Aarón y sus hijos debían bendecir al pueblo?","opciones":["«Jehová te bendiga, y te guarde»","«La paz sea con vosotros»","«Oye, Israel: Jehová uno es»","«Bendito el que viene en el nombre de Jehová»"],"dato":"Dios mismo le dio a Moisés las palabras exactas de la bendición sacerdotal con que Aarón pondría el nombre de Jehová sobre el pueblo.","cita":"Números 6:24","versiculo":"Jehová te bendiga, y te guarde: Haga resplandecer Jehová su rostro sobre ti, y haya de ti misericordia.","vcita":"Números 6:24-25","pista":"«Es la bendición más famosa del libro de Números.»"},{"pregunta":"¿Cómo dijeron los espías que se veían a sí mismos junto a los gigantes de Canaán?","opciones":["Como langostas","Como hormigas entre el polvo","Como niños pequeños","Como ovejas sin pastor"],"dato":"El informe de los diez espías exageró así el peligro y desanimó a todo el pueblo, mientras Josué y Caleb confiaban en Dios.","cita":"Números 13:33","versiculo":"También vimos allí gigantes, hijos de Anac, raza de los gigantes: y éramos nosotros, á nuestro parecer, como langostas; y así les parecíamos á ellos.","vcita":"Números 13:33","pista":"«Se compararon con un insecto.»"},{"pregunta":"¿Qué le sucedió a la vara de Aarón dentro del tabernáculo para confirmar su sacerdocio?","opciones":["Brotó, echó flores y produjo almendras","Se partió en dos pedazos","Se convirtió en una serpiente","Se cubrió de oro de la noche a la mañana"],"dato":"De las doce varas de las tribus, solo la de Aarón reverdeció en una noche; se guardó en el tabernáculo como señal contra los rebeldes.","cita":"Números 17:8","versiculo":"Y aconteció que el día siguiente vino Moisés al tabernáculo del testimonio; y he aquí que la vara de Aarón de la casa de Leví había brotado, y echado flores, y arrojado renuevos, y producido almendras.","vcita":"Números 17:8","pista":"«Un palo seco no da fruto... salvo este.»"},{"pregunta":"¿Qué hizo Moisés con la serpiente de bronce para que sanaran los israelitas mordidos?","opciones":["La puso sobre un asta para que la miraran","La quemó en el altar del holocausto","La enterró junto al campamento","La guardó dentro del arca del pacto"],"dato":"El que era mordido y miraba la serpiente de bronce, vivía; Jesús comparó esa escena con su propia crucifixión en Juan 3.","cita":"Números 21:8","versiculo":"Y Jehová dijo á Moisés: Hazte una serpiente ardiente, y ponla sobre la bandera: y será que cualquiera que fuere mordido y mirare á ella, vivirá.","vcita":"Números 21:8","pista":"«Había que mirar hacia arriba para sanar.»"},{"pregunta":"¿Qué animal le habló a Balaam, reprochándole que lo hubiera golpeado tres veces?","opciones":["Su asna","Un caballo del séquito","Un camello del desierto","Una oveja de su rebaño"],"dato":"El asna veía al ángel de Jehová con la espada en el camino, mientras Balaam, ciego por la codicia, solo veía un animal «terco».","cita":"Números 22:28","versiculo":"Entonces Jehová abrió la boca al asna, la cual dijo á Balaam: ¿Qué te he hecho, que me has azotado estas tres veces?","vcita":"Números 22:28","pista":"«Es el animal de carga más humilde del relato.»"},{"pregunta":"¿Cuántos hombres envió Moisés a reconocer la tierra de Canaán?","opciones":["Doce, uno por cada tribu","Setenta ancianos","Solamente dos","Cuarenta exploradores"],"dato":"Fueron doce príncipes, uno por tribu; entre ellos iban Caleb, de Judá, y Oseas hijo de Nun, a quien Moisés llamó Josué.","cita":"Números 13:2","versiculo":"Envía tú hombres que reconozcan la tierra de Canaán, la cual yo doy á los hijos de Israel: de cada tribu de sus padres enviaréis un varón, cada uno príncipe entre ellos.","vcita":"Números 13:2","pista":"«Uno por cada tribu de Israel.»"},{"pregunta":"¿Cuántos años anduvo Israel por el desierto como consecuencia de su incredulidad ante el informe de los espías?","opciones":["Cuarenta años","Siete años","Veinte años","Un solo año"],"dato":"Por cada día que duró la exploración de la tierra, un año de desierto: aquella generación moriría sin entrar en Canaán.","cita":"Números 14:33","versiculo":"Y vuestros hijos andarán pastoreando en el desierto cuarenta años, y ellos llevarán vuestras fornicaciones, hasta que vuestros cuerpos sean consumidos en el desierto.","vcita":"Números 14:33","pista":"«Un año de desierto por cada día de exploración.»"},{"pregunta":"¿Qué les sucedió a Coré y a los que se rebelaron con él contra Moisés y Aarón?","opciones":["La tierra se abrió y los tragó vivos","Fueron apedreados fuera del campamento","Huyeron de noche hacia Egipto","Un rayo quemó solo sus tiendas"],"dato":"Coré, levita, acusó a Moisés de exaltarse; la tierra se rompió bajo sus tiendas y descendieron vivos al Seol.","cita":"Números 16:32","versiculo":"Y abrió la tierra su boca, y tragólos á ellos, y á sus casas, y á todos los hombres de Coré, y á toda su hacienda.","vcita":"Números 16:32","pista":"«El suelo mismo fue el juez de la rebelión.»"},{"pregunta":"¿A causa de qué murmuraron María y Aarón contra Moisés en Números 12?","opciones":["De la mujer cusita que había tomado","De que no repartió el maná con ellos","De que Josué sería su sucesor","De que el pueblo pidió carne en el desierto"],"dato":"María y Aarón cuestionaron si Dios hablaba solo por Moisés; María quedó leprosa «blanca como la nieve» por una semana.","cita":"Números 12:1","versiculo":"Y hablaron María y Aarón contra Moisés á causa de la mujer etíope que había tomado: porque él había tomado mujer etíope.","vcita":"Números 12:1","pista":"«La queja empezó por la esposa de Moisés.»"},{"pregunta":"¿Qué pidieron las hijas de Zelofehad, de modo que Dios dijo que pedían justamente?","opciones":["Recibir la heredad de su padre, que no tuvo hijos varones","Servir como sacerdotisas en el tabernáculo","Cruzar el Jordán al frente del pueblo","Guardar el maná del día de reposo"],"dato":"Su caso cambió la ley de herencia en Israel: sin hijos varones, la heredad del padre pasaba a las hijas.","cita":"Números 27:7","versiculo":"Bien dicen las hijas de Zelofehad: les darás posesión de una heredad entre los hermanos de su padre; y traspasarás la heredad de su padre á ellas.","vcita":"Números 27:7","pista":"«Su padre murió sin hijos varones, solo hijas.»"},{"pregunta":"¿Cuántas ciudades de refugio debían apartarse para quien hubiera matado a alguien sin intención?","opciones":["Seis ciudades","Tres ciudades","Doce ciudades","Una sola ciudad"],"dato":"De las cuarenta y ocho ciudades de los levitas, seis eran de refugio: tres a este lado del Jordán y tres en Canaán.","cita":"Números 35:6","versiculo":"Y de las ciudades que daréis á los Levitas, seis ciudades serán de refugio, las cuales daréis para que el homicida se acoja allí.","vcita":"Números 35:6","pista":"«Tres a un lado del Jordán y tres al otro.»"}],"Deuteronomio":[{"pregunta":"¿Cómo sigue la gran confesión de fe de Israel que comienza con «Oye, Israel»?","opciones":["Jehová nuestro Dios, Jehová uno es","Jehová es mi pastor, nada me falta","Santo, santo, santo es Jehová","Bendito el que viene en el nombre de Jehová"],"dato":"El Shemá («Oye») es la declaración central del judaísmo: Dios es uno, y debía repetirse en casa, en el camino, al acostarse y al levantarse.","cita":"Deuteronomio 6:4","versiculo":"Oye, Israel: Jehová nuestro Dios, Jehová uno es.","vcita":"Deuteronomio 6:4","pista":"«Todo Israel lo recitaba de memoria, dos veces al día.»"},{"pregunta":"¿Cómo debe el hombre amar a Dios según el gran mandamiento de Deuteronomio?","opciones":["De todo corazón, de toda alma y con todo su poder","Con ayunos cada semana","Solo en el día de reposo","En silencio y sin testigos"],"dato":"Este es el mandamiento que Jesús llamó el primero y más grande; en hebreo se pide corazón, alma y «mucho» (fuerzas).","cita":"Deuteronomio 6:5","versiculo":"Y amarás á Jehová tu Dios de todo tu corazón, y de toda tu alma, y con todo tu poder.","vcita":"Deuteronomio 6:5","pista":"«Corazón, alma y fuerzas: no se guarda nada.»"},{"pregunta":"¿Qué aprendió Israel en el desierto acerca de lo que sostiene la vida del hombre?","opciones":["Que no solo de pan vive el hombre, sino de toda palabra que sale de la boca de Dios","Que el maná basta sin necesidad de obedecer","Que el oro compra años de vida","Que el agua de la peña nunca se agota"],"dato":"Jesús citó exactamente esta frase en el desierto cuando el diablo lo tentó a convertir las piedras en pan.","cita":"Deuteronomio 8:3","versiculo":"Y te afligió, y te hizo tener hambre, y te sustentó con maná, comida que no conocías tú, ni tus padres la habían conocido; para hacerte saber que no con solo el pan vivirá el hombre, mas con todo lo que sale de la boca de Jehová vivirá el hombre.","vcita":"Deuteronomio 8:3","pista":"«Jesús la citó contra el diablo en el desierto.»"},{"pregunta":"¿Qué promesa acompaña el mandato «Esforzaos y cobrad ánimo» antes de entrar en la tierra?","opciones":["Que Dios va contigo; no te dejará ni te desamparará","Que el Jordán se secará para siempre","Que nunca habrá guerra en la tierra","Que los enemigos huirán ese mismo día"],"dato":"Moisés la repitió al pueblo y luego a Josué en su instalación: la valentía de Israel se apoyaba en la presencia de Dios, no en su fuerza.","cita":"Deuteronomio 31:6","versiculo":"Esforzaos y cobrad ánimo; no temáis, ni tengáis miedo de ellos: que Jehová tu Dios es el que va contigo; no te dejará ni te desamparará.","vcita":"Deuteronomio 31:6","pista":"«La valentía venía de no ir solos.»"},{"pregunta":"¿De qué edad era Moisés cuando murió, según el final de Deuteronomio?","opciones":["De ciento veinte años","De noventa años","De ochenta años","De cuarenta años"],"dato":"El relato añade que a los 120 años «sus ojos nunca se oscurecieron, ni perdió su vigor», y que Dios mismo lo sepultó en Moab.","cita":"Deuteronomio 34:7","versiculo":"Y era Moisés de edad de ciento y veinte años cuando murió: sus ojos nunca se oscurecieron, ni perdió su vigor.","vcita":"Deuteronomio 34:7","pista":"«Su vida se divide en tres etapas de cuarenta años.»"},{"pregunta":"¿Qué prometió Moisés que Dios levantaría de entre los hermanos de Israel?","opciones":["Un profeta como Moisés","Un rey como David","Un sacerdote como Aarón","Un juez como Sansón"],"dato":"Pedro y Esteban citaron esta profecía en Hechos aplicándola a Jesucristo: «á él oiréis».","cita":"Deuteronomio 18:15","versiculo":"Profeta de en medio de ti, de tus hermanos, como yo, te levantará Jehová tu Dios: á él oiréis.","vcita":"Deuteronomio 18:15","pista":"«Los apóstoles lo aplicaron a Jesús en el libro de Hechos.»"},{"pregunta":"¿Qué pide Dios de Israel en Deuteronomio 10: temerle, andar en sus caminos, amarlo y...?","opciones":["Servirle con todo el corazón y con toda el alma","Ofrecerle diezmos cada semana","Levantar altares en cada ciudad","Guardar silencio durante un año"],"dato":"La lista de Dios es sorprendentemente corta: temer, andar, amar y servir; y el versículo siguiente añade guardar sus mandamientos «para que tengas prosperidad».","cita":"Deuteronomio 10:12","versiculo":"Ahora pues, Israel, ¿qué pide Jehová tu Dios de ti, sino que temas á Jehová tu Dios, que andes en todos sus caminos, y que lo ames, y sirvas á Jehová tu Dios con todo tu corazón, y con toda tu alma?","vcita":"Deuteronomio 10:12","pista":"«Son cuatro verbos: temer, andar, amar y...»"},{"pregunta":"¿Entre qué dos caminos puso Dios a Israel para que escogiera, llamando por testigos al cielo y la tierra?","opciones":["La vida y la muerte, la bendición y la maldición","El mar y el desierto","La guerra y la paz","El destierro y el regreso"],"dato":"El consejo de Dios es explícito: «escoge pues la vida, porque vivas tú y tu simiente»; la elección tenía consecuencias generacionales.","cita":"Deuteronomio 30:19","versiculo":"A los cielos y la tierra llamo por testigos hoy contra vosotros, que os he puesto delante la vida y la muerte, la bendición y la maldición: escoge pues la vida, porque vivas tú y tu simiente.","vcita":"Deuteronomio 30:19","pista":"«Y el consejo divino fue: escoge la primera.»"},{"pregunta":"¿Por qué era Israel un pueblo especial para Dios, según Deuteronomio 7?","opciones":["Porque Dios lo escogió para ser su pueblo especial","Porque era el pueblo más numeroso de la tierra","Porque jamás le había desobedecido","Porque era el ejército más temido"],"dato":"El capítulo aclara lo contrario a la soberbia: no por grandes ni por justos fueron escogidos, sino por el amor y el juramento de Dios a los patriarcas.","cita":"Deuteronomio 7:6","versiculo":"Porque tú eres pueblo santo para Jehová tu Dios: Jehová tu Dios te ha escogido para serle un pueblo especial, más que todos los pueblos que están sobre la haz de la tierra.","vcita":"Deuteronomio 7:6","pista":"«No por grandes, sino por amados y escogidos.»"},{"pregunta":"¿Cuándo debía pagarse el jornal del trabajador pobre, según la ley de Deuteronomio?","opciones":["El mismo día, antes de que se pusiera el sol","Al final de cada mes","En la fiesta de la cosecha","Cuando el patrón reuniera el dinero"],"dato":"Retener el salario era clamor que llegaba a Dios: el jornalero «con él sustenta su vida», y atrasarlo se contaba como pecado.","cita":"Deuteronomio 24:15","versiculo":"En su día le darás su jornal, y no se pondrá el sol sin dárselo; pues es pobre, y con él sustenta su vida: para que no clame contra ti á Jehová, y sea en ti pecado.","vcita":"Deuteronomio 24:15","pista":"«El sol no debía ponerse sobre un salario sin pagar.»"},{"pregunta":"¿Qué prohibición dio Moisés respecto a la palabra que Dios mandaba?","opciones":["No añadir a ella ni disminuir de ella","Escribirla solamente en piedra","Leerla en público una vez al año","Guardarla en secreto hasta el jubileo"],"dato":"La misma advertencia cierra toda la Biblia en Apocalipsis 22: no añadir ni quitar, para guardar íntegro lo que Dios mandó.","cita":"Deuteronomio 4:2","versiculo":"No añadiréis á la palabra que yo os mando, ni disminuiréis de ella, para que guardéis los mandamientos de Jehová vuestro Dios que yo os ordeno.","vcita":"Deuteronomio 4:2","pista":"«La misma advertencia reaparece al final de Apocalipsis.»"}],"Mateo":[{"pregunta":"Antes de ascender al cielo, ¿qué mandó Jesús a sus discípulos respecto a todas las naciones?","opciones":["Id y haced discípulos de todas las naciones, bautizándolos en el nombre del Padre, del Hijo y del Espíritu Santo","Id y edificad un templo en cada ciudad","Id y recoged ofrendas de todos los pueblos","Id y escribid la ley en tablas nuevas"],"dato":"Es la Gran Comisión, las últimas instrucciones del Jesús resucitado en Mateo, acompañadas de la promesa «yo estoy con vosotros todos los días».","cita":"Mateo 28:19","versiculo":"Por tanto, id, y doctrinad á todos los Gentiles, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo.","vcita":"Mateo 28:19","pista":"«Incluye una promesa: «yo estoy con vosotros todos los días».»"}],"Marcos":[{"pregunta":"¿Qué prometió Jesús hacer de Simón y Andrés si lo seguían junto al mar de Galilea?","opciones":["Pescadores de hombres","Reyes sobre Galilea","Maestros de la ley","Guardianes del templo"],"dato":"Eran pescadores de oficio; Jesús cambió el objeto de su pesca, y ellos, «dejando luego sus redes, le siguieron».","cita":"Marcos 1:17","versiculo":"Y les dijo Jesús: Venid en pos de mí, y haré que seáis pescadores de hombres.","vcita":"Marcos 1:17","pista":"«La misma red, pero otra clase de pesca.»"},{"pregunta":"¿Qué dijo la voz de los cielos cuando Jesús salió del agua en su bautismo?","opciones":["Tú eres mi Hijo amado; en ti tomo contentamiento","Este es el profeta que había de venir","Escuchadle todos los días","He aquí el Cordero de Dios"],"dato":"En el bautismo se manifestó la Trinidad: el Hijo en el agua, el Espíritu descendiendo como paloma y la voz del Padre desde el cielo.","cita":"Marcos 1:11","versiculo":"Y hubo una voz de los cielos que decía: Tú eres mi Hijo amado; en ti tomo contentamiento.","vcita":"Marcos 1:11","pista":"«Tres palabras clave: Hijo, amado, contentamiento.»"},{"pregunta":"¿A quiénes dijo Jesús que había venido a llamar, al comer con publicanos y pecadores?","opciones":["A los pecadores, no a los justos","Solamente a los fariseos","A los sacerdotes del templo","A los niños de Belén"],"dato":"Su ilustración fue médica: «Los sanos no tienen necesidad de médico, sino los enfermos».","cita":"Marcos 2:17","versiculo":"Y oyéndolo Jesús, les dice: Los sanos no tienen necesidad de médico, sino los enfermos: no he venido á llamar justos, sino pecadores.","vcita":"Marcos 2:17","pista":"«Usó el ejemplo de un médico y sus pacientes.»"},{"pregunta":"Según Jesús, ¿de qué le sirve al hombre ganar todo el mundo si pierde...?","opciones":["Su alma","Su familia","Su buena salud","Su buen nombre"],"dato":"La pregunta sigue a la del precio del alma: «¿qué dará el hombre en rescate por su alma?»; no hay riqueza que la pague.","cita":"Marcos 8:36","versiculo":"Porque ¿qué aprovechará al hombre, si granjeare todo el mundo, y pierde su alma?","vcita":"Marcos 8:36","pista":"«Es lo único que no se puede comprar de vuelta.»"},{"pregunta":"¿Qué dijo Jesús cuando los discípulos reprendían a los que le traían niños?","opciones":["Dejad a los niños venir a mí, porque de los tales es el reino de Dios","Llevadlos primero a la sinagoga","Que vengan cuando sean mayores","Dadles de comer antes de acercarlos"],"dato":"Marcos dice que Jesús se indignó con los discípulos, tomó a los niños en brazos y los bendijo imponiéndoles las manos.","cita":"Marcos 10:14","versiculo":"Dejad los niños venir á mí, y no se lo estorbéis; porque de los tales es el reino de Dios.","vcita":"Marcos 10:14","pista":"«Los pequeños llegaron a ser el ejemplo del reino.»"},{"pregunta":"«Para los hombres es imposible; mas para Dios, no». ¿A qué pregunta respondía Jesús con esa frase?","opciones":["A quién puede ser salvo","A quién entrará primero en Jerusalén","A quién heredará la tierra de Canaán","A quién verá el templo reconstruido"],"dato":"La conversación venía del joven rico: humanamente nadie puede salvarse a sí mismo, «porque todas las cosas son posibles para Dios».","cita":"Marcos 10:27","versiculo":"Entonces Jesús, mirándolos, dice: Para los hombres es imposible; mas para Dios, no; porque todas las cosas son posibles para Dios.","vcita":"Marcos 10:27","pista":"«Venía hablando de un rico y de un camello por el ojo de una aguja.»"},{"pregunta":"Según Jesús en Marcos 11, ¿qué hay que hacer con lo que se pide en oración?","opciones":["Creer que ya se ha recibido","Pedirlo en voz muy alta","Repetirlo tres veces seguidas","Pedirlo únicamente dentro del templo"],"dato":"La enseñanza sigue al episodio de la higuera seca: «todo lo que orando pidiereis, creed que lo recibiréis, y os vendrá».","cita":"Marcos 11:24","versiculo":"Por tanto os digo que todo lo que orando pidiereis, creed que lo recibiréis, y os vendrá.","vcita":"Marcos 11:24","pista":"«La fe se adelanta a la respuesta.»"},{"pregunta":"¿Cuál es el primer y principal mandamiento según Jesús en el evangelio de Marcos?","opciones":["Amarás al Señor tu Dios de todo tu corazón, alma, mente y fuerzas","No matarás","Honra a tu padre y a tu madre","Acuérdate del día de reposo para santificarlo"],"dato":"Un escriba le preguntó cuál era el primer mandamiento de todos; Jesús citó el Shemá y añadió el segundo: amar al prójimo como a uno mismo.","cita":"Marcos 12:30","versiculo":"Y amarás al Señor tu Dios de todo tu corazón, y de toda tu alma, y de toda tu mente, y de todas tus fuerzas: este es el principal mandamiento.","vcita":"Marcos 12:30","pista":"«Empieza con las palabras del Shemá de Deuteronomio.»"},{"pregunta":"Según Jesús, ¿qué pasará un día, aunque sus palabras no pasarán?","opciones":["El cielo y la tierra","El templo y la ciudad","El mar y las estrellas","Los reinos de este mundo"],"dato":"Lo dijo en el discurso del monte de los Olivos, hablando de las señales antes del fin y de su venida.","cita":"Marcos 13:31","versiculo":"El cielo y la tierra pasarán, mas mis palabras no pasarán.","vcita":"Marcos 13:31","pista":"«Lo más grande y estable que ves... también pasará.»"},{"pregunta":"Según el final de Marcos, ¿qué ordenó el Jesús resucitado a sus discípulos?","opciones":["Id por todo el mundo y predicad el evangelio a toda criatura","Quedaos en Jerusalén para siempre","Volved a vuestras redes en Galilea","Guardad en secreto todo lo que visteis"],"dato":"Es la versión de Marcos de la Gran Comisión, dicha a los once mientras comían, después de reprender su incredulidad.","cita":"Marcos 16:15","versiculo":"Y les dijo: Id por todo el mundo; predicad el evangelio á toda criatura.","vcita":"Marcos 16:15","pista":"«El encargo no conoce fronteras: todo el mundo.»"}],"Lucas":[{"pregunta":"¿Qué le dijo el ángel Gabriel a María para cerrar su anuncio sobre el nacimiento de Jesús?","opciones":["Que ninguna cosa es imposible para Dios","Que debía huir a Egipto esa noche","Que guardara silencio hasta el parto","Que el niño sería un sacerdote más"],"dato":"Gabriel le acababa de decir que su parienta Elisabet, estéril y anciana, también estaba embarazada: el ejemplo vivo de esa frase.","cita":"Lucas 1:37","versiculo":"Porque ninguna cosa es imposible para Dios.","vcita":"Lucas 1:37","pista":"«El ejemplo era Elisabet, embarazada en su vejez.»"},{"pregunta":"¿Qué anunció el ángel a los pastores la noche del nacimiento de Jesús?","opciones":["Que había nacido un Salvador, que es Cristo el Señor","Que Herodes había abdicado del trono","Que debían partir hacia Egipto","Que los magos ya habían llegado a Belén"],"dato":"El anuncio fue «nuevas de gran gozo» para todo el pueblo, y la señal era un niño envuelto en pañales, acostado en un pesebre.","cita":"Lucas 2:11","versiculo":"Que os ha nacido hoy, en la ciudad de David, un Salvador, que es CRISTO el Señor.","vcita":"Lucas 2:11","pista":"«La señal: un niño en un pesebre, en la ciudad de David.»"},{"pregunta":"En la sinagoga de Nazaret, ¿para qué dijo Jesús que el Espíritu del Señor lo había ungido?","opciones":["Para dar buenas nuevas a los pobres","Para juzgar a los fariseos de la ciudad","Para construir una nueva sinagoga","Para escribir el libro de Isaías"],"dato":"Jesús leyó de Isaías 61, enrolló el libro y declaró: «Hoy se ha cumplido esta Escritura en vuestros oídos».","cita":"Lucas 4:18","versiculo":"El Espíritu del Señor es sobre mí, Por cuanto me ha ungido para dar buenas nuevas á los pobres: me ha enviado para sanar á los quebrantados de corazón.","vcita":"Lucas 4:18","pista":"«Estaba leyendo del profeta Isaías... y el texto hablaba de él.»"},{"pregunta":"¿Cómo resume Jesús la manera de tratar a los demás en la llamada «regla de oro»?","opciones":["Como queréis que os hagan los hombres, así hacedles también vosotros","Ojo por ojo y diente por diente","Cada uno mire solamente por lo suyo","Tratad bien únicamente a los amigos"],"dato":"En Lucas forma parte del mismo discurso que manda amar a los enemigos y prestar sin esperar nada a cambio.","cita":"Lucas 6:31","versiculo":"Y como queréis que os hagan los hombres, así hacedles también vosotros.","vcita":"Lucas 6:31","pista":"«Ponte en el lugar del otro... y actúa primero.»"},{"pregunta":"¿Qué hizo el padre cuando vio venir de lejos a su hijo pródigo?","opciones":["Corrió hacia él, se echó sobre su cuello y lo besó","Esperó en la puerta a que pidiera perdón","Le envió un siervo con una capa nueva","Le cerró la puerta hasta que trabajara un año"],"dato":"El padre lo vio «como aun estuviese lejos»: llevaba tiempo mirando el camino; corrió movido a misericordia, algo indigno para un patriarca de la época.","cita":"Lucas 15:20","versiculo":"Y levantándose, vino á su padre. Y como aun estuviese lejos, vióle su padre, y fué movido á misericordia, y corrió, y echóse sobre su cuello, y besóle.","vcita":"Lucas 15:20","pista":"«El padre no esperó en casa: salió corriendo.»"},{"pregunta":"¿Para qué vino el Hijo del hombre, según su propia declaración en casa de Zaqueo?","opciones":["A buscar y a salvar lo que se había perdido","A juzgar a los publicanos de Jericó","A coronarse rey en Jerusalén","A abolir la ley de Moisés"],"dato":"Lo dijo tras entrar en casa de Zaqueo, el publicano que se había subido a un sicómoro para verlo pasar.","cita":"Lucas 19:10","versiculo":"Porque el Hijo del hombre vino á buscar y á salvar lo que se había perdido.","vcita":"Lucas 19:10","pista":"«Dos verbos: buscar y salvar. Y un anfitrión bajito.»"}],"Juan":[{"pregunta":"Según Juan 3:16, ¿qué dio Dios al mundo por su gran amor?","opciones":["A su Hijo unigénito, para que todo el que cree en él tenga vida eterna","La ley grabada en tablas de piedra","El maná que bajó del cielo","Un reino terrenal e inmediato"],"dato":"Es quizá el versículo más citado de la Biblia; Jesús lo dijo de noche, conversando con Nicodemo, un principal de los judíos.","cita":"Juan 3:16","versiculo":"Porque de tal manera amó Dios al mundo, que ha dado á su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.","vcita":"Juan 3:16","pista":"«La conversación era con Nicodemo, y de noche.»"}],"Josué":[{"pregunta":"¿Qué debía hacer Josué con el libro de la ley para que su camino prosperara?","opciones":["Meditar en él de día y de noche","Guardarlo en el arca sin abrirlo jamás","Leerlo en voz alta solo una vez al año","Enseñarlo únicamente a los sacerdotes"],"dato":"Dios le mandó a Josué no apartarse de la ley: meditar en ella de día y de noche y guardarla; esa era la clave de su éxito en la conquista de Canaán.","cita":"Josué 1:8","versiculo":"El libro de aquesta ley nunca se apartará de tu boca: antes de día y de noche meditarás en él, para que guardes y hagas conforme a todo lo que en él está escrito: porque entonces harás prosperar tu camino, y todo te saldrá bien.","vcita":"Josué 1:8","pista":"«La orden viene al comienzo del libro: la ley siempre en la boca y en la mente.»"},{"pregunta":"¿Qué confesión hicieron los habitantes de Jericó, según contó Rahab a los espías?","opciones":["Que Jehová es Dios arriba en los cielos y abajo en la tierra","Que los dioses de Canaán eran más fuertes que Jehová","Que Israel sería derrotado a las puertas de Jericó","Que el río Jordán jamás podría cruzarse"],"dato":"Rahab contó que el corazón de los cananeos había desmayado al oír lo que Dios hizo por Israel en el mar Rojo y contra los reyes amorreos, y confesó que Jehová es Dios en el cielo y en la tierra.","cita":"Josué 2:11","versiculo":"Oyendo esto, ha desmayado nuestro corazón; ni ha quedado más espíritu en alguno por causa de vosotros: porque Jehová vuestro Dios es Dios arriba en los cielos y abajo en la tierra.","vcita":"Josué 2:11","pista":"«Lo dijo la mujer que escondió a los espías bajo manojos de lino en su terrado.»"},{"pregunta":"¿Dónde permanecieron firmes los sacerdotes que llevaban el arca mientras todo Israel cruzaba en seco?","opciones":["En medio del río Jordán","En la orilla junto a Jericó","En la cumbre del monte Nebo","En el campamento de Gilgal"],"dato":"Cuando los pies de los sacerdotes tocaron el agua, el Jordán se detuvo como un muro; ellos quedaron firmes en seco, en medio del río, hasta que todo el pueblo acabó de pasar.","cita":"Josué 3:17","versiculo":"Mas los sacerdotes que llevaban el arca del pacto de Jehová, estuvieron en seco, firmes en medio del Jordán, hasta que todo el pueblo hubo acabado de pasar el Jordán; y todo Israel pasó en seco.","vcita":"Josué 3:17","pista":"«El pueblo cruzó como por tierra seca, al igual que en el mar Rojo una generación antes.»"},{"pregunta":"¿Para qué mandó Josué sacar doce piedras del Jordán y levantarlas en Gilgal?","opciones":["Para que fueran señal y los hijos preguntaran por su significado","Para edificar un altar de holocaustos","Para marcar el lugar de la tumba de Moisés","Para contar a los hombres de guerra de Israel"],"dato":"Las doce piedras, una por cada tribu, serían un memorial permanente: cuando los hijos preguntaran qué significaban, los padres les contarían cómo Dios detuvo las aguas del Jordán.","cita":"Josué 4:6","versiculo":"Para que esto sea señal entre vosotros; y cuando vuestros hijos preguntaren a sus padres mañana, diciendo: ¿Qué os significan estas piedras?","vcita":"Josué 4:6","pista":"«Cada piedra representaba a una de las doce tribus.»"},{"pregunta":"¿Qué leyó Josué delante de todo Israel en el monte Ebal, tras la victoria sobre Hai?","opciones":["Todas las palabras de la ley, las bendiciones y las maldiciones","Solamente los Diez Mandamientos","Un salmo que él mismo había compuesto","El censo de los varones de cada tribu"],"dato":"Fiel a lo ordenado por Moisés, Josué leyó íntegra la ley ante hombres, mujeres y niños, con el arca y los levitas en medio, entre el monte Gerizim y el monte Ebal.","cita":"Josué 8:34","versiculo":"Después de esto, leyó todas las palabras de la ley, las bendiciones y las maldiciones, conforme a todo lo que está escrito en el libro de la ley.","vcita":"Josué 8:34","pista":"«La mitad del pueblo estaba frente a un monte y la otra mitad frente al otro.»"},{"pregunta":"¿Qué hizo Josué con toda la tierra que había conquistado?","opciones":["La entregó a los israelitas por herencia, repartida por tribus","La dejó sin repartir hasta nacer la siguiente generación","La consagró entera como un único santuario","La devolvió a los cananeos a cambio de tributo"],"dato":"Josué tomó la tierra conforme a todo lo que Dios había dicho a Moisés y la repartió por sorteo entre las tribus; entonces la tierra reposó de la guerra.","cita":"Josué 11:23","versiculo":"Tomó pues Josué toda la tierra, conforme a todo lo que Jehová había dicho a Moisés; y entrególa Josué a los israelitas por herencia, conforme a sus repartimientos por sus tribus. Y la tierra reposó de la guerra.","vcita":"Josué 11:23","pista":"«Con el reparto termina la etapa de la conquista en el libro.»"},{"pregunta":"¿Qué pidió Caleb a Josué como heredad, aun teniendo ya 85 años?","opciones":["El monte donde vivían los gigantes anaceos","La llanura costera de los filisteos","El valle del Jordán junto a Jericó","La ciudad amurallada de Jerusalén"],"dato":"Caleb, uno de los dos espías fieles, pidió el monte habitado por los anaceos, confiando en echarlos con la ayuda de Dios; Josué se lo bendijo y le dio Hebrón por heredad.","cita":"Josué 14:12","versiculo":"Dame ahora pues este monte, del cual habló Jehová aquel día: porque tú oíste en aquel día que los Anaceos están allí, y que hay ciudades grandes y fortificadas: quizá Jehová estará conmigo, y los echaré como Jehová ha dicho.","vcita":"Josué 14:12","pista":"«Era el territorio de los gigantes que cuarenta años antes habían asustado a los demás espías.»"},{"pregunta":"¿Qué se afirma de las buenas palabras que Jehová había hablado a la casa de Israel?","opciones":["Ninguna faltó: todo se cumplió","La mitad quedó para cumplirse en el futuro","Solo se cumplieron las dichas a Moisés","Se cumplieron únicamente las de la tribu de Judá"],"dato":"Al concluir el relato de la conquista, el libro subraya la fidelidad absoluta de Dios: ni una sola de sus buenas promesas quedó sin cumplirse.","cita":"Josué 21:45","versiculo":"Ninguna palabra faltó de todas las buenas palabras que Jehová habló a la casa de Israel; todo se cumplió.","vcita":"Josué 21:45","pista":"«Es la frase de cierre sobre las promesas de Dios: ni una sola falló.»"},{"pregunta":"¿Qué decisión puso Josué delante del pueblo reunido en Siquem al final de su vida?","opciones":["Escoger a quién servir: a Jehová o a los otros dioses","Elegir un rey de entre las tribus","Regresar a Egipto en busca de alimentos","Levantar un templo permanente en Silo"],"dato":"Josué renovó el pacto en Siquem y declaró su propia decisión con la frase más célebre del libro: «Yo y mi casa serviremos a Jehová». El pueblo respondió que también serviría a Dios.","cita":"Josué 24:15","versiculo":"Y si mal os parece servir a Jehová, escogeos hoy a quién sirváis; si a los dioses a quienes sirvieron vuestros padres, cuando estuvieron de la otra parte del río, o a los dioses de los Amorreos en cuya tierra habitáis: que yo y mi casa serviremos a Jehová.","vcita":"Josué 24:15","pista":"«Su respuesta se resume en una frase: él y su casa servirían a Jehová.»"}],"Jueces":[{"pregunta":"¿A quiénes suscitaba Jehová para librar a Israel de mano de los que lo despojaban?","opciones":["Jueces","Reyes herederos","Gobernadores extranjeros","Capitanes de mercenarios"],"dato":"El libro muestra un ciclo repetido: Israel pecaba, era oprimido, clamaba a Dios, y Jehová levantaba jueces que lo salvaban de sus enemigos.","cita":"Jueces 2:16","versiculo":"Y Jehová suscitó jueces que los librasen de mano de los que los despojaban.","vcita":"Jueces 2:16","pista":"«De ahí toma su nombre todo este libro de la Biblia.»"},{"pregunta":"¿Con qué instrumento hirió Samgar a seiscientos hombres de los filisteos?","opciones":["Con una aguijada de bueyes","Con una quijada de asno recién muerto","Con una honda y cinco piedras lisas","Con la espada de un capitán filisteo"],"dato":"Samgar, uno de los jueces menores, derrotó a seiscientos filisteos con una aguijada de bueyes, la vara puntiaguda usada para arrear el ganado: también él salvó a Israel.","cita":"Jueces 3:31","versiculo":"Después de él fue Samgar hijo de Anath, el cual hirió a seiscientos hombres de los Filisteos con una aguijada de bueyes; y él también salvó a Israel.","vcita":"Jueces 3:31","pista":"«Era una herramienta del campo, no un arma de guerra.»"},{"pregunta":"¿Cómo saludó el ángel de Jehová a Gedeón cuando este trillaba el trigo a escondidas de los madianitas?","opciones":["«Jehová es contigo, varón esforzado y valiente»","«La paz sea contigo, futuro rey de Israel»","«Levántate, profeta entre las naciones»","«Bienaventurado seas, juez de las tribus»"],"dato":"El ángel llamó «varón esforzado y valiente» a Gedeón, aunque él se escondía para trillar y se consideraba el menor de la casa de su padre; Dios lo escogió para librar a Israel.","cita":"Jueces 6:12","versiculo":"Y el ángel de Jehová se le apareció, y díjole: Jehová es contigo, varón esforzado y valiente.","vcita":"Jueces 6:12","pista":"«Gedeón estaba trillando en el lagar para esconder el grano.»"},{"pregunta":"¿Qué voto hizo Jefté a Jehová antes de salir a pelear contra los hijos de Amón?","opciones":["Ofrecer en holocausto a quien saliera de su casa a recibirle al volver en paz","No cortarse el cabello hasta terminar la guerra","Levantar un altar de doce piedras en Mizpa","Ayunar con todo su ejército durante siete días"],"dato":"Jefté prometió que, si Dios entregaba a los amonitas en sus manos, lo primero que saliera de las puertas de su casa a recibirle sería de Jehová; a su regreso triunfal salió su única hija, y el voto le costó un dolor inmenso.","cita":"Jueces 11:30","versiculo":"Y Jefté hizo voto a Jehová, diciendo: Si entregares a los Ammonitas en mis manos, cualquiera que me saliere de las puertas de mi casa a recibirme, cuando volviere de los Ammonitas en paz, será de Jehová, y lo ofreceré en holocausto.","vcita":"Jueces 11:30-31","pista":"«El voto se volvió trágico cuando su única hija salió a recibirlo con panderos y danzas.»"},{"pregunta":"¿Qué hijo le nació a la mujer de Manoa, anunciado antes por el ángel, y fue bendecido por Jehová al crecer?","opciones":["Sansón","Samuel","Abdón","Elón"],"dato":"La esposa de Manoa era estéril, pero el ángel le anunció un hijo nazareo desde el vientre; nació Sansón, y el niño creció y Jehová lo bendijo, y su Espíritu comenzó a manifestarse en él.","cita":"Jueces 13:24","versiculo":"Y la mujer parió un hijo, y llamóle por nombre Sansón. Y el niño creció, y Jehová lo bendijo.","vcita":"Jueces 13:24","pista":"«Su nacimiento fue anunciado a una mujer estéril del pueblo de Zora.»"},{"pregunta":"¿Qué animal despedazó Sansón con sus propias manos, sin llevar nada en la mano?","opciones":["Un león joven que salió rugiendo contra él","Un oso que atacaba el rebaño de su padre","Un lobo que rondaba los viñedos de Timnat","Un toro bravo de los filisteos"],"dato":"Bajando a Timnat, un cachorro de león salió rugiendo contra Sansón; el Espíritu de Jehová vino sobre él con poder y lo despedazó como a un cabrito, sin decir nada a sus padres.","cita":"Jueces 14:6","versiculo":"Y el espíritu de Jehová cayó sobre él, y despedazólo como quien despedaza un cabrito, sin tener nada en su mano: y no dio a entender a su padre ni a su madre lo que había hecho.","vcita":"Jueces 14:6","pista":"«Días después halló miel en el cuerpo de ese mismo animal, y de ahí nació su enigma.»"},{"pregunta":"¿Qué pidió Sansón a Dios en su última oración, en el templo de Dagón?","opciones":["Que le fortaleciera solo esa vez para vengarse de los filisteos por sus dos ojos","Que le devolviera la vista antes de morir","Que enviara un terremoto sobre toda Gaza","Que perdonara a Dalila y a los de su casa"],"dato":"Ciego, rapado y atado entre las columnas, Sansón clamó: «Señor Jehová, acuérdate ahora de mí», pidiendo fuerzas una vez más para vengarse de los filisteos por sus dos ojos; y Dios le oyó.","cita":"Jueces 16:28","versiculo":"Entonces Sansón clamó a Jehová, y dijo: Señor Jehová, acuérdate ahora de mí, y esfuérzame ahora solamente esta vez, oh Dios, para que de una vez tome venganza de los Filisteos por mis dos ojos.","vcita":"Jueces 16:28","pista":"«Oró apoyado entre las dos columnas centrales del templo.»"},{"pregunta":"¿Qué se dice de los filisteos que Sansón mató al morir, en comparación con los que mató durante su vida?","opciones":["Fueron más los que mató al morir que en toda su vida","Fueron exactamente el mismo número","Al morir no alcanzó a matar a ninguno","Solo murieron los cinco príncipes de los filisteos"],"dato":"Al empujar las columnas, el templo de Dagón cayó sobre los príncipes y todo el pueblo reunido en la fiesta; así Sansón mató al morir a más filisteos que en toda su vida.","cita":"Jueces 16:30","versiculo":"Y dijo Sansón: Muera mi alma con los Filisteos. Y empujó con toda su fuerza, y la casa cayó sobre los príncipes, y sobre todo el pueblo que estaba en ella. Y fueron muchos más los que mató al morir que los que había muerto en su vida.","vcita":"Jueces 16:30","pista":"«Antes de empujar pronunció: muera mi alma con los filisteos.»"},{"pregunta":"¿Qué frase, repetida al final del libro, resume la anarquía espiritual de la época de los jueces?","opciones":["«No había rey en Israel: cada uno hacía lo recto delante de sus ojos»","«Y la tierra reposó de la guerra cuarenta años»","«El pueblo sirvió a Jehová todos los días de los ancianos»","«Y hubo paz entre Israel y los filisteos»"],"dato":"Sin rey y sin dirección firme, cada israelita hacía lo que bien le parecía: esa frase explica el ciclo de pecado, opresión, clamor y liberación que recorre todo el libro.","cita":"Jueces 21:25","versiculo":"En estos días no había rey en Israel: cada uno hacía lo recto delante de sus ojos.","vcita":"Jueces 21:25","pista":"«Es literalmente el último versículo del libro.»"}],"Rut":[{"pregunta":"¿Por qué salió Elimelec de Belén con su mujer y sus dos hijos hacia los campos de Moab?","opciones":["Porque hubo hambre en la tierra","Porque un juez lo desterró de Israel","Para vender trigo a los moabitas","Para huir de una invasión filistea"],"dato":"En los días en que gobernaban los jueces hubo hambre en la tierra, y Elimelec, de Belén de Judá, se fue a peregrinar a Moab con Noemí y sus hijos Mahlón y Quelión.","cita":"Rut 1:1","versiculo":"Y aconteció en los días que gobernaban los jueces, que hubo hambre en la tierra. Y un varón de Beth-lehem de Judá fue a peregrinar en los campos de Moab, él y su mujer, y dos hijos suyos.","vcita":"Rut 1:1","pista":"«Belén significa «casa del pan», y sin embargo faltó el pan.»"},{"pregunta":"¿Qué nombre pidió Noemí que le dieran al volver a Belén, en lugar de Noemí?","opciones":["Mara, porque el Todopoderoso la había puesto en grande amargura","Sara, porque Dios se había reído con ella","Raquel, porque había llorado por sus hijos","Dina, porque había sido juzgada por las mujeres"],"dato":"Noemí significa «placentera», pero ella pidió llamarse Mara, que suena a «amarga»: había salido llena de Belén y Jehová la había hecho volver vacía, sin esposo y sin hijos.","cita":"Rut 1:20","versiculo":"Y ella les respondía: No me llaméis Noemí, sino llamadme Mara: porque en grande amargura me ha puesto el Todopoderoso.","vcita":"Rut 1:20","pista":"«El nuevo nombre expresa amargura, lo contrario de la dulzura de Noemí.»"},{"pregunta":"¿En qué temporada de cosecha llegaron Noemí y Rut a Belén?","opciones":["A principios de la siega de las cebadas","En plena vendimia de las uvas","Al final de la trilla del trigo","En la recogida de las aceitunas"],"dato":"Volvieron de los campos de Moab justo al comenzar la cosecha de la cebada; por eso Rut pudo salir enseguida a espigar detrás de los segadores.","cita":"Rut 1:22","versiculo":"Así volvió Noemí, y Ruth la Moabita su nuera con ella; la cual había vuelto de los campos de Moab: y llegaron a Beth-lehem a principios de la siega de las cebadas.","vcita":"Rut 1:22","pista":"«Llegaron justo cuando empezaba la primera cosecha de granos del año.»"},{"pregunta":"¿Qué permiso pidió Rut a Noemí para salir al campo?","opciones":["Ir a recoger espigas en pos de aquel a cuyos ojos hallara gracia","Trabajar como cocinera en la casa de Booz","Vender cebada en la puerta de la ciudad","Cosechar una parcela propia de Elimelec"],"dato":"La ley de Dios permitía a los pobres recoger las espigas caídas tras los segadores; Rut pidió ir, y por providencia llegó al campo de Booz, pariente de Elimelec.","cita":"Rut 2:2","versiculo":"Y Ruth la Moabita dijo a Noemí: Ruégote que me dejes ir al campo, y recogeré espigas en pos de aquel a cuyos ojos hallare gracia. Y ella le respondió: Ve, hija mía.","vcita":"Rut 2:2","pista":"«Era el derecho que la ley reservaba a los pobres, las viudas y los extranjeros.»"},{"pregunta":"¿Qué preguntó Rut a Booz, inclinándose hasta tierra, cuando él la trató con bondad?","opciones":["Por qué había hallado gracia en sus ojos, siendo ella extranjera","Si podía recoger también en los campos vecinos","Cuánta cebada podría llevar a Noemí","Si Booz conocía a su difunto marido"],"dato":"Booz la invitó a espigar solo en su campo y a beber del agua de sus criados; Rut, sorprendida y humilde, reconoció que no tenía derecho alguno, pues era extranjera.","cita":"Rut 2:10","versiculo":"Ella entonces, bajando su rostro, inclinóse a tierra, y díjole: ¿Por qué he hallado gracia en tus ojos para que me reconozcas, siendo yo extranjera?","vcita":"Rut 2:10","pista":"«Su sorpresa era no tener ningún derecho: venía de Moab.»"},{"pregunta":"¿Con qué imagen bendijo Booz a Rut por haber venido a refugiarse en el Dios de Israel?","opciones":["Las alas de Jehová, bajo las cuales había venido a ampararse","La sombra de un cedro plantado junto a las aguas","Las murallas de Belén en tiempo de guerra","El manto de los sacerdotes en el santuario"],"dato":"Booz pidió que Jehová le diera a Rut su remuneración cumplida, pues había dejado su tierra y a su familia para ampararse bajo las alas del Dios de Israel, como un polluelo bajo las alas de su madre.","cita":"Rut 2:12","versiculo":"Jehová galardone tu obra, y tu remuneración sea cumplida de parte de Jehová Dios de Israel, bajo cuyas alas has venido a ampararte.","vcita":"Rut 2:12","pista":"«La imagen es la de un ave que cobija a sus polluelos.»"},{"pregunta":"¿Qué pidió Rut a Booz en la era, presentándose de noche como su sierva?","opciones":["Que extendiera el borde de su capa sobre ella, por ser su pariente cercano","Que le regalara diez medidas de cebada para Noemí","Que la presentara ante los ancianos esa misma noche","Que le permitiera dormir junto a las gavillas todo el invierno"],"dato":"Extender la capa sobre alguien era un gesto de cobertura y de compromiso; con esas palabras Rut le pidió a Booz ejercer su papel de pariente redentor y tomarla por mujer.","cita":"Rut 3:9","versiculo":"Entonces él dijo: ¿Quién eres? Y ella respondió: Yo soy Ruth tu sierva: extiende el borde de tu capa sobre tu sierva, por cuanto eres pariente cercano.","vcita":"Rut 3:9","pista":"«El gesto de la capa era una petición de redención y de matrimonio.»"},{"pregunta":"¿Qué reputación tenía Rut entre todo el pueblo de Belén, según las palabras de Booz?","opciones":["Todos sabían que era una mujer virtuosa","La llamaban la moabita afortunada","Decían que era profetisa como Débora","La conocían solo como la viuda de Mahlón"],"dato":"Booz le prometió no temer y hacer cuanto ella dijera, porque toda la puerta de su pueblo sabía que Rut era una mujer virtuosa: su fidelidad a Noemí la había acreditado ante todos.","cita":"Rut 3:11","versiculo":"Ahora pues, no temas, hija mía: yo haré contigo lo que tú dijeres, pues que toda la puerta de mi pueblo sabe que eres mujer virtuosa.","vcita":"Rut 3:11","pista":"«Su fama no era de riqueza, sino de virtud y fidelidad.»"},{"pregunta":"¿Por qué el pariente más cercano renunció ante los ancianos a redimir la heredad de Elimelec?","opciones":["Porque redimir la heredad dañaría su propia heredad","Porque no tenía con qué pagar el precio del campo","Porque ya estaba casado con una mujer de Judá","Porque vivía muy lejos, en tierra de Moab"],"dato":"El pariente primero aceptó redimir el campo, pero al saber que también debía tomar a Rut por mujer para levantar nombre al difunto, se echó atrás para no dañar su propia heredad, y cedió su derecho a Booz quitándose el zapato.","cita":"Rut 4:6","versiculo":"Y respondió el pariente: No puedo redimir por mí, no sea que dañe mi heredad: redime tú, usando de mi derecho, porque yo no podré redimir.","vcita":"Rut 4:6","pista":"«La condición que lo hizo desistir fue tener que casarse con la viuda moabita.»"},{"pregunta":"¿Qué don le concedió Jehová a Rut después de que Booz la tomó por mujer?","opciones":["Que concibiera y diera a luz un hijo","Que volviera a ver a su madre en Moab","Que su nombre se escribiera en el templo","Que heredara todos los campos de Booz"],"dato":"Booz tomó a Rut, y Jehová le dio que concibiese y pariese un hijo; el nacimiento llenó de gozo a Noemí y a las mujeres de Belén.","cita":"Rut 4:13","versiculo":"Booz pues tomó a Ruth, y ella fue su mujer; y luego que entró a ella, Jehová le dio que concibiese y pariese un hijo.","vcita":"Rut 4:13","pista":"«El hijo devolvió la alegría a Noemí, que lo tomó en su regazo.»"},{"pregunta":"¿Qué nombre pusieron las vecinas al hijo de Rut, y de qué gran rey fue antepasado?","opciones":["Obed, abuelo de David","Salomón, padre de Roboam","Isaí, abuelo de Saúl","Booz, padre de los jueces"],"dato":"Las vecinas lo llamaron Obed; él fue padre de Isaí, e Isaí padre de David. Así, la fiel moabita Rut quedó en la genealogía del rey David y, siglos después, en la del Mesías.","cita":"Rut 4:17","versiculo":"Y las vecinas le pusieron nombre, diciendo: Le ha nacido un hijo a Noemí; y llamáronle Obed. Este es padre de Isaí, padre de David.","vcita":"Rut 4:17","pista":"«Del niño se dice: es padre de Isaí, padre de David.»"}],"1 Samuel":[{"pregunta":"¿Qué proclamó Ana acerca de Jehová en su canto de acción de gracias?","opciones":["Que no hay santo como Jehová, ni ninguno fuera de él, ni refugio como nuestro Dios","Que Jehová hiere con espada y con lanza","Que los cielos de los cielos no pueden contenerle","Que él levanta reyes y abate montañas solamente"],"dato":"Al llevar al pequeño Samuel al templo de Silo, Ana cantó que no hay santo como Jehová, ni roca ni refugio como nuestro Dios, el que humilla y exalta.","cita":"1 Samuel 2:2","versiculo":"No hay santo como Jehová: porque no hay ninguno fuera de ti; y no hay refugio como el Dios nuestro.","vcita":"1 Samuel 2:2","pista":"«Su canto empieza declarando que no hay santo como él.»"},{"pregunta":"¿Qué respondió Samuel cuando por fin entendió que era Jehová quien lo llamaba de noche?","opciones":["«Habla, que tu siervo oye»","«Heme aquí, envíame a mí»","«Señor, heme aquí para la batalla»","«Tu siervo dormirá y velará tu casa»"],"dato":"Tres veces corrió Samuel a Elí creyendo que él lo llamaba; a la cuarta, instruido por el sacerdote, respondió: «Habla, que tu siervo oye», y recibió el mensaje de Dios contra la casa de Elí.","cita":"1 Samuel 3:10","versiculo":"Y vino Jehová, y púsose, y llamó como las otras veces: ¡Samuel, Samuel! Entonces Samuel dijo: Habla, que tu siervo oye.","vcita":"1 Samuel 3:10","pista":"«Primero creyó tres veces que quien lo llamaba era el anciano Elí.»"},{"pregunta":"¿Qué le explicó Jehová a Samuel cuando el pueblo pidió tener un rey?","opciones":["Que no lo desechaban a él, sino a Dios mismo, para que no reinara sobre ellos","Que el rey debía salir de la tribu de Leví","Que primero debían edificar un palacio en Ramá","Que él mismo, Samuel, debía aceptar la corona"],"dato":"Samuel se afligió por la petición, pero Jehová le aclaró que el rechazo no era contra el profeta, sino contra Él como Rey de Israel; aun así, les advirtió lo que un rey humano les costaría.","cita":"1 Samuel 8:7","versiculo":"Y dijo Jehová a Samuel: Oye la voz del pueblo en todo lo que te dijeren: porque no te han desechado a ti, sino a mí me han desechado, para que no reine sobre ellos.","vcita":"1 Samuel 8:7","pista":"«El pueblo quería ser «como todas las naciones».»"},{"pregunta":"¿Qué le dijo Samuel a Saúl que vale más que los holocaustos y los sacrificios?","opciones":["Obedecer a las palabras de Jehová","Ofrecer diez mil corderos en Gilgal","Ayunar tres días antes de la batalla","Multiplicar los altares en todo Israel"],"dato":"Saúl desobedeció al perdonar lo mejor del ganado de Amalec para «sacrificarlo»; Samuel le sentenció: el obedecer es mejor que los sacrificios, y el prestar atención, que el sebo de los carneros.","cita":"1 Samuel 15:22","versiculo":"Y Samuel dijo: ¿Tiene Jehová tanto contentamiento en los holocaustos y víctimas, como en obedecer a las palabras de Jehová? Ciertamente el obedecer es mejor que los sacrificios; y el prestar atención que el sebo de los carneros.","vcita":"1 Samuel 15:22","pista":"«La sentencia compara obedecer con el sebo de los carneros.»"},{"pregunta":"¿Qué mira Jehová en el hombre, a diferencia de lo que mira el ser humano?","opciones":["El corazón","La estatura y el parecer","La fuerza de los brazos","La riqueza de su casa"],"dato":"Samuel quiso ungir al imponente Eliab, el mayor de los hijos de Isaí, pero Dios le enseñó que Él no mira lo que mira el hombre —lo que está delante de los ojos—, sino el corazón; por eso fue escogido David, el menor.","cita":"1 Samuel 16:7","versiculo":"Y Jehová respondió a Samuel: No mires a su parecer, ni a lo grande de su estatura, porque yo lo desecho; porque Jehová mira no lo que el hombre mira; pues que el hombre mira lo que está delante de sus ojos, mas Jehová mira el corazón.","vcita":"1 Samuel 16:7","pista":"«Por esta regla no fue elegido el hermano mayor, sino el pastorcito.»"},{"pregunta":"¿En nombre de quién declaró David a Goliat que venía contra él?","opciones":["En el nombre de Jehová de los ejércitos","En nombre del rey Saúl y de su corona","En nombre de los tres mil hombres de Judá","En nombre de su padre Isaí de Belén"],"dato":"El filisteo venía con espada, lanza y escudo; David, un pastor sin armadura, respondió que venía en el nombre de Jehová de los ejércitos, el Dios de los escuadrones de Israel, a quien el gigante había provocado.","cita":"1 Samuel 17:45","versiculo":"Entonces dijo David al Filisteo: Tú vienes a mí con espada y lanza y escudo; mas yo vengo a ti en el nombre de Jehová de los ejércitos, el Dios de los escuadrones de Israel, que tú has provocado.","vcita":"1 Samuel 17:45","pista":"«El gigante traía tres armas; David traía un Nombre.»"},{"pregunta":"¿Qué gran verdad proclamó David ante toda la congregación antes de enfrentar a Goliat?","opciones":["Que de Jehová es la guerra y él no salva con espada y lanza","Que Israel tenía el ejército más numeroso de la región","Que la armadura de Saúl estaba bendecida por Samuel","Que el valle de Ela pertenecía a su familia por herencia"],"dato":"David declaró que Jehová no salva con espada ni con lanza, porque la batalla es suya; así toda la congregación sabría que hay Dios en Israel.","cita":"1 Samuel 17:47","versiculo":"Y sabrá toda esta congregación que Jehová no salva con espada y lanza; porque de Jehová es la guerra, y él os entregará en nuestras manos.","vcita":"1 Samuel 17:47","pista":"«Su confianza no estaba en el arma, sino en de quién es la guerra.»"},{"pregunta":"¿Qué cantaban las mujeres de Israel cuando David volvía de vencer al filisteo?","opciones":["«Saúl hirió sus miles, y David sus diez miles»","«David reinará sobre todo Israel»","«El Señor ha puesto corona sobre el pastor»","«Cayó el gigante y huyó Filistea»"],"dato":"Las mujeres salieron danzando de todas las ciudades cantando que Saúl hirió a sus miles y David a sus diez miles; ese cántico encendió los celos de Saúl, que desde ese día miró a David con sospecha.","cita":"1 Samuel 18:7","versiculo":"Y cantaban las mujeres que danzaban, y decían: Saúl hirió sus miles, y David sus diez miles.","vcita":"1 Samuel 18:7","pista":"«El estribillo comparaba miles con diez miles, y eso dolió al rey.»"}],"2 Samuel":[{"pregunta":"¿Cómo iba David delante del arca cuando esta subía a Jerusalén?","opciones":["Saltando con todas sus fuerzas, vestido con un efod de lino","En silencio, con la cabeza cubierta y ceniza sobre ella","Montado en el carro nuevo tirado por bueyes","Llevando la corona y el cetro que fueron de Saúl"],"dato":"David danzaba con todas sus fuerzas delante de Jehová, vestido solo con un efod de lino; Mical lo despreció por ello, pero él respondió que su gozo era delante de Dios, no para lucirse ante los hombres.","cita":"2 Samuel 6:14","versiculo":"Y David saltaba con todas sus fuerzas delante de Jehová; y tenía vestido David un efod de lino.","vcita":"2 Samuel 6:14","pista":"«Su esposa Mical lo miró por la ventana y lo menospreció en su corazón.»"},{"pregunta":"¿Qué prometió Jehová a David, por medio de Natán, acerca de su descendencia?","opciones":["Que establecería a su simiente después de él y afirmaría su reino","Que su hijo mayor reinaría solamente siete años","Que el reino pasaría para siempre a la tribu de Benjamín","Que ningún descendiente suyo volvería a pecar"],"dato":"David quiso edificar casa a Dios, pero Dios le anunció que Él le edificaría casa a David: levantaría a su descendiente después de él, salido de sus entrañas, y afirmaría su reino. Es la gran promesa del pacto davídico.","cita":"2 Samuel 7:12","versiculo":"Y cuando tus días fueren cumplidos, y durmieres con tus padres, yo estableceré tu simiente después de ti, la cual procederá de tus entrañas, y afirmaré su reino.","vcita":"2 Samuel 7:12","pista":"«El rey quiso hacerle una casa a Dios, y Dios le prometió una casa a él.»"},{"pregunta":"¿Qué confesó David en su oración de gratitud tras recibir el pacto?","opciones":["Que no hay nadie como Jehová, ni Dios fuera de él","Que Israel era el pueblo más numeroso de la tierra","Que el templo quedaría terminado en un año","Que jamás volvería a salir a la guerra"],"dato":"Asombrado, David entró y se sentó delante de Jehová preguntando «¿Quién soy yo?», y confesó: «No hay como tú, ni hay Dios fuera de ti», según todo lo que había oído.","cita":"2 Samuel 7:22","versiculo":"Por tanto tú te has engrandecido, Jehová Dios: por cuanto no hay como tú, ni hay Dios fuera de ti, conforme a todo lo que hemos oído con nuestros oídos.","vcita":"2 Samuel 7:22","pista":"«Su oración empieza preguntando: ¿quién soy yo, y qué es mi casa?»"},{"pregunta":"¿Qué solían hacer los reyes en la época del año en que David envió a Joab contra los amonitas… y qué hizo David?","opciones":["Salían a la guerra; pero David se quedó en Jerusalén","Celebraban la fiesta de la pascua en Silo","Contaban el censo de todos los varones","Repartían las tierras entre las tribus"],"dato":"A la vuelta del año, el tiempo en que los reyes salen a campaña, David envió a Joab y al ejército contra Rabá, pero él se quedó en Jerusalén; de aquel paseo ocioso por el terrado nació su caída con Betsabé.","cita":"2 Samuel 11:1","versiculo":"Y aconteció a la vuelta del año, en el tiempo que salen los reyes a la guerra, que David envió a Joab, y a sus siervos con él, y a todo Israel; y destruyeron a los Ammonitas, y pusieron cerco a Rabba: mas David se quedó en Jerusalem.","vcita":"2 Samuel 11:1","pista":"«La frase clave del relato es: mas David se quedó en Jerusalén.»"},{"pregunta":"¿Qué confesó David al profeta Natán después de ser confrontado por su pecado?","opciones":["«Pequé contra Jehová»","«El pueblo es culpable de haberme tentado»","«Urías merecía morir en el frente»","«Dejaré el trono y volveré a Belén»"],"dato":"David no se excusó: confesó «Pequé contra Jehová». Natán le anunció que Dios había remitido su pecado y que no moriría, aunque el niño nacido moriría y la espada no se apartaría de su casa.","cita":"2 Samuel 12:13","versiculo":"Entonces dijo David a Nathán: Pequé contra Jehová. Y Nathán dijo a David: También Jehová ha remitido tu pecado: no morirás.","vcita":"2 Samuel 12:13","pista":"«Su confesión fueron solo dos palabras en hebreo, pero cambiaron su historia.»"},{"pregunta":"¿Por dónde subió David huyendo de su hijo Absalón, llorando, con la cabeza cubierta y los pies descalzos?","opciones":["Por la cuesta de las Olivas","Por el camino de Jericó al Jordán","Por la bajada del monte Gilboa","Por el valle de Cedrón hacia el desierto de En-gadi solamente a caballo"],"dato":"Durante la rebelión de Absalón, David cruzó el torrente de Cedrón y subió llorando la cuesta del monte de los Olivos, descalzo y con la cabeza cubierta, en señal de duelo y humillación, y todo el pueblo subía llorando con él.","cita":"2 Samuel 15:30","versiculo":"Y David subió la cuesta de las Olivas; y subióla llorando, llevando la cabeza cubierta, y los pies descalzos. También todo el pueblo que tenía consigo cubrió cada uno su cabeza, y subieron llorando así como subían.","vcita":"2 Samuel 15:30","pista":"«Siglos después, su mayor Descendiente también oró y lloró en ese mismo monte.»"},{"pregunta":"¿Qué deseó David, llorando en la sala de la puerta, al saber que Absalón había muerto?","opciones":["Haber muerto él en lugar de su hijo","Que Joab fuera ejecutado esa misma noche","Que el reino pasara enseguida a Adonías","Ser ungido de nuevo en Hebrón ante el pueblo"],"dato":"El rey se turbó y subió a llorar repitiendo: «¡Hijo mío Absalom, hijo mío, hijo mío Absalom! ¡Quién me diera que muriera yo en lugar de ti!»; su luto fue tan grande que la victoria se volvió tristeza para el ejército.","cita":"2 Samuel 18:33","versiculo":"Entonces el rey se turbó, y subióse a la sala de la puerta, y lloró; y yendo, decía así: ¡Hijo mío Absalom, hijo mío, hijo mío Absalom! ¡Quién me diera que muriera yo en lugar de ti, Absalom, hijo mío, hijo mío!","vcita":"2 Samuel 18:33","pista":"«Repetía una y otra vez: hijo mío, hijo mío.»"},{"pregunta":"¿Con qué tres títulos llamó David a Jehová al abrir su cántico de liberación?","opciones":["Mi roca, mi fortaleza y mi libertador","Mi pastor, mi luz y mi salvación","Mi escudo, mi bandera y mi torre fuerte","Mi padre, mi juez y mi corona"],"dato":"En el cántico de 2 Samuel 22 —prácticamente el mismo texto del Salmo 18— David celebra el día en que Jehová lo libró de Saúl y de todos sus enemigos, llamándolo su roca, su fortaleza y su libertador.","cita":"2 Samuel 22:2","versiculo":"Y dijo: Jehová es mi roca, y mi fortaleza, y mi libertador.","vcita":"2 Samuel 22:2","pista":"«Este cántico aparece también, casi idéntico, como un salmo muy conocido.»"},{"pregunta":"¿Qué deseo expresó David que llevó a tres de sus valientes a romper el campamento filisteo arriesgando la vida?","opciones":["Beber agua de la cisterna de Belén que está junto a la puerta","Comer del pan de la proposición en Nob","Escuchar una vez más las canciones de su juventud","Contemplar el arca antes de morir"],"dato":"David suspiró por el agua de su Belén natal, ocupada por los filisteos; tres valientes se la trajeron, pero David no quiso beberla y la derramó ante Jehová, llamándola la sangre de aquellos hombres que fueron con peligro de sus vidas.","cita":"2 Samuel 23:15","versiculo":"Y David tuvo deseo, y dijo: ¡Quién me diera a beber del agua de la cisterna de Belén, que está a la puerta!","vcita":"2 Samuel 23:15","pista":"«Al recibirla, no la bebió: la derramó como ofrenda ante Jehová.»"}],"1 Reyes":[{"pregunta":"¿Qué reconoció Salomón en su oración de dedicación del templo acerca de los cielos de los cielos?","opciones":["Que ni ellos pueden contener a Dios, cuánto menos la casa edificada","Que Dios habitaría para siempre solo en el lugar santísimo","Que el templo jamás sufriría daño alguno","Que los cielos son el estrado de los pies del rey"],"dato":"Salomón oró con humildad: si ni los cielos, ni los cielos de los cielos pueden contener a Dios, ¿cómo lo contendría la casa que él había edificado? Pidió que Dios oyera desde el cielo, su morada, y perdonara.","cita":"1 Reyes 8:27","versiculo":"Empero ¿es verdad que Dios haya de morar sobre la tierra? He aquí que los cielos, los cielos de los cielos no te pueden contener: ¿cuánto menos esta casa que yo he edificado?","vcita":"1 Reyes 8:27","pista":"«El templo era grandioso, pero el rey admitió que Dios es incontenible.»"},{"pregunta":"¿Qué anunció Elías a Acab la primera vez que se presentó ante el rey de Israel?","opciones":["Que no habría lluvia ni rocío en esos años, sino por su palabra","Que un fuego consumiría el palacio de Samaria esa noche","Que Jezabel moriría antes de terminar el mes","Que Siria entregaría sus ciudades sin pelear"],"dato":"Elías el tisbita irrumpió ante Acab jurando por Jehová, el Dios de Israel, que no habría rocío ni lluvia en aquellos años sino por su palabra; así comenzó la gran sequía de tres años y medio.","cita":"1 Reyes 17:1","versiculo":"Entonces Elías Thisbita, que era de los moradores de Galaad, dijo a Achâb: Vive Jehová Dios de Israel, delante del cual estoy, que no habrá lluvia ni rocío en estos años, sino por mi palabra.","vcita":"1 Reyes 17:1","pista":"«Su anuncio cerró los cielos sobre Israel por años.»"},{"pregunta":"¿Qué exclamó todo el pueblo, cayendo sobre su rostro, cuando el fuego de Jehová consumió el holocausto en el Carmelo?","opciones":["«¡Jehová es el Dios! ¡Jehová es el Dios!»","«¡Grande es Baal, señor de la lluvia!»","«¡El profeta sea rey sobre nosotros!»","«¡Huyamos, que el monte se quema!»"],"dato":"Al caer el fuego y consumir el holocausto, la leña, las piedras y hasta el agua de la zanja, el pueblo se postró y confesó dos veces: «¡Jehová es el Dios!», volviendo su corazón al Señor.","cita":"1 Reyes 18:39","versiculo":"Y viéndolo todo el pueblo, cayeron sobre sus rostros, y dijeron: ¡Jehová es el Dios! ¡Jehová es el Dios!","vcita":"1 Reyes 18:39","pista":"«La exclamación se repite dos veces en el mismo versículo.»"},{"pregunta":"¿En qué se le manifestó Jehová a Elías en el monte Horeb, después del viento, el terremoto y el fuego?","opciones":["En un silbo apacible y delicado","En el fuego que descendió sobre la peña","En el terremoto que hendió las rocas","En el viento recio que rompía los montes"],"dato":"Jehová no estaba en el viento recio, ni en el terremoto, ni en el fuego; habló en el silbo apacible y delicado, y Elías, al oírlo, cubrió su rostro con el manto y salió a la puerta de la cueva.","cita":"1 Reyes 19:12","versiculo":"Y tras el terremoto un fuego: mas Jehová no estaba en el fuego. Y tras el fuego un silbo apacible y delicado.","vcita":"1 Reyes 19:12","pista":"«No fue un estruendo, sino un susurro suave y apacible.»"}],"2 Reyes":[{"pregunta":"¿Qué pidió Eliseo a Elías cuando supo que su maestro sería quitado de él?","opciones":["Que las dos partes de su espíritu fueran sobre él","Que le dejara escrito el futuro de Israel","Que le entregara las llaves del río Jordán","Que le permitiera quedarse en Bet-el"],"dato":"Eliseo pidió la porción del primogénito: el doble del espíritu de Elías. El maestro respondió que pedía cosa difícil, pero que si lo veía cuando fuera quitado, así se haría; y lo vio subir en el torbellino.","cita":"2 Reyes 2:9","versiculo":"Y cuando hubieron pasado, Elías dijo a Eliseo: Pide lo que quieres que haga por ti, antes que sea quitado de ti. Y dijo Eliseo: Ruégote que las dos partes de tu espíritu sean sobre mí.","vcita":"2 Reyes 2:9","pista":"«Pidió la herencia del hijo mayor: una doble porción.»"},{"pregunta":"¿Qué hizo el hijo de la sunamita justo antes de abrir los ojos cuando Eliseo lo resucitó?","opciones":["Estornudó siete veces","Llamó a su madre en voz alta","Pidió un poco de agua","Se sentó y abrazó al profeta"],"dato":"Eliseo oró y se tendió sobre el niño dos veces; a la segunda, el muchacho estornudó siete veces y abrió los ojos, vivo, y el profeta lo entregó a su madre, que se postró a sus pies.","cita":"2 Reyes 4:35","versiculo":"Volviéndose luego, paseóse por la casa a una parte y a otra, y después subió, y tendióse sobre él: y el muchacho estornudó siete veces, y abrió sus ojos.","vcita":"2 Reyes 4:35","pista":"«Siete veces hizo algo muy común antes de abrir los ojos.»"},{"pregunta":"¿Qué objeto perdido hizo flotar Eliseo en el agua con un palo que cortó y echó allí?","opciones":["El hierro de un hacha prestada","Una espada de bronce de un capitán","La piedra de un molino de mano","Un anillo de oro del mayordomo"],"dato":"Uno de los hijos de los profetas perdió en el Jordán el hacha que le habían prestado; Eliseo cortó un palo, lo echó en el lugar y hizo nadar el hierro hasta la superficie, y el hombre alargó la mano y lo tomó.","cita":"2 Reyes 6:6","versiculo":"Y el varón de Dios dijo: ¿Dónde cayó? Y él le mostró el lugar. Entonces cortó él un palo, y echólo allí; e hizo nadar el hierro.","vcita":"2 Reyes 6:6","pista":"«El dueño estaba afligido porque el hacha no era suya, sino prestada.»"},{"pregunta":"¿Qué vio el criado de Eliseo cuando Jehová le abrió los ojos en Dotán?","opciones":["El monte lleno de gente de a caballo y de carros de fuego alrededor de Eliseo","Un ejército de diez mil israelitas bajando del cielo","Al rey de Siria huyendo con su ejército","Una muralla de fuego rodeando su propia casa"],"dato":"El ejército sirio rodeaba la ciudad para prender a Eliseo; el profeta oró por su criado aterrado, y este vio que los que estaban con ellos eran muchos más: el monte estaba lleno de caballos y carros de fuego.","cita":"2 Reyes 6:17","versiculo":"Y oró Eliseo, y dijo: Ruégote, oh Jehová, que abras sus ojos para que vea. Entonces Jehová abrió los ojos del mozo, y miró: y he aquí que el monte estaba lleno de gente de a caballo, y de carros de fuego alrededor de Eliseo.","vcita":"2 Reyes 6:17","pista":"«El profeta le había dicho: no temas, porque más son los que están con nosotros.»"},{"pregunta":"¿Qué milagro sucedió cuando un hombre muerto tocó los huesos de Eliseo en su sepulcro?","opciones":["Revivió y se levantó sobre sus pies","El sepulcro se abrió y salió luz de él","Los moabitas que venían huyeron despavoridos","La tierra tembló y se partió la peña"],"dato":"Unos israelitas que iban a sepultar a un hombre vieron una banda de moabitas y arrojaron el cadáver en el sepulcro de Eliseo; en cuanto tocó los huesos del profeta, revivió y se levantó: el poder de Dios siguió obrando aun después de la muerte de su siervo.","cita":"2 Reyes 13:21","versiculo":"Y aconteció que al sepultar unos a un hombre, súbitamente vieron una banda de gentes, y arrojaron al hombre en el sepulcro de Eliseo: y cuando llegó a tocar el muerto los huesos de Eliseo, revivió, y se levantó sobre sus pies.","vcita":"2 Reyes 13:21","pista":"«El muerto volvió a la vida por el simple contacto con los huesos del profeta.»"},{"pregunta":"¿Qué hizo el rey de Asiria con los israelitas después de tomar Samaria en el año nueve de Oseas?","opciones":["Los transportó a Asiria y los puso en Hala, en Habor y en las ciudades de los medos","Los vendió como esclavos a los fenicios","Los dejó en Samaria pagando un tributo anual","Los llevó cautivos a Babilonia junto al río Quebar"],"dato":"Así terminó el reino del norte tras años de idolatría: Samaria cayó y su pueblo fue deportado a tierras lejanas de Asiria, y gentes extranjeras fueron traídas a habitar sus ciudades.","cita":"2 Reyes 17:6","versiculo":"En el año nueve de Oseas tomó el rey de Asiria a Samaria, y trasportó a Israel a Asiria, y púsolos en Hala, y en Habor, junto al río de Gozán, y en las ciudades de los Medos.","vcita":"2 Reyes 17:6","pista":"«Fue el fin del reino de las diez tribus del norte.»"},{"pregunta":"¿A cuántos hombres del campamento asirio hirió el ángel de Jehová en una sola noche, librando a Jerusalén?","opciones":["A ciento ochenta y cinco mil","A exactamente cien mil","A cincuenta mil jinetes","A diez mil de la guardia del rey"],"dato":"Ezequías había orado extendiendo ante Jehová la carta amenazante de Senaquerib; aquella misma noche salió el ángel de Jehová e hirió a ciento ochenta y cinco mil asirios, y el rey enemigo se retiró avergonzado a su tierra.","cita":"2 Reyes 19:35","versiculo":"Y aconteció que aquella misma noche salió el ángel de Jehová, e hirió en el campo de los Asirios ciento ochenta y cinco mil: y cuando se levantaron por la mañana, he aquí los cuerpos de los muertos.","vcita":"2 Reyes 19:35","pista":"«La cifra supera los ciento ochenta mil, en una sola noche.»"},{"pregunta":"¿Qué señal obtuvo Ezequías en el reloj de Acaz como confirmación de que sanaría y viviría quince años más?","opciones":["La sombra retrocedió diez grados","El sol se detuvo en mitad del cielo","Cayó lluvia en pleno verano sobre Jerusalén","El Jordán corrió hacia atrás por una hora"],"dato":"El rey pidió señal, e Isaías clamó a Jehová: la sombra que ya había descendido en el reloj de Acaz volvió diez grados atrás, confirmando que Dios lo sanaría y añadiría quince años a su vida.","cita":"2 Reyes 20:11","versiculo":"Entonces el profeta Isaías clamó a Jehová; e hizo volver la sombra por los grados que había descendido en el reloj de Acaz, diez grados atrás.","vcita":"2 Reyes 20:11","pista":"«Ezequías escogió que la sombra volviera atrás, lo más difícil.»"},{"pregunta":"¿Qué fue quemado cuando Jerusalén cayó en manos de los caldeos?","opciones":["La casa de Jehová, la casa del rey y todas las casas de Jerusalén","Solamente el palacio de Sedecías","Únicamente las puertas y murallas de la ciudad","Los huertos y viñas de los alrededores"],"dato":"Nabuzaradán, capitán de la guardia de Nabucodonosor, quemó el templo, el palacio real y todas las casas de la ciudad, derribó los muros y llevó cautivo al remanente: así terminó el reino de Judá, como los profetas habían anunciado.","cita":"2 Reyes 25:9","versiculo":"Y quemó la casa de Jehová, y la casa del rey, y todas las casas de Jerusalem; y toda casa grande quemó al fuego.","vcita":"2 Reyes 25:9","pista":"«Con el incendio del templo cayó también el reino de Judá, como antes el del norte.»"}],"1 Crónicas":[{"pregunta":"¿Qué pidió Jabes a Dios en su famosa oración?","opciones":["Que lo bendijera, ensanchara su territorio y lo librara del mal","Que le diera muchos hijos y grandes riquezas","Que lo hiciera rey sobre Israel","Que destruyera a todos sus enemigos"],"dato":"Jabes oró pidiendo bendición y protección, y Dios le concedió lo que pidió.","cita":"1 Crónicas 4:10","versiculo":"E invocó Jabes al Dios de Israel, diciendo: ¡Oh si me dieras bendición, y ensancharas mi término, y si tu mano fuera conmigo, y me libraras de mal, que no me dañe! E hizo Dios que le viniese lo que pidió.","vcita":"1 Crónicas 4:10","pista":"«Su oración es de las más famosas de la Biblia: empieza pidiendo bendición.»"},{"pregunta":"¿Qué le sucedió a Uza cuando tocó el arca de Dios?","opciones":["Murió al instante por el furor de Jehová","Quedó ciego para siempre","Fue desterrado de Israel","Se convirtió en sacerdote"],"dato":"Uza extendió su mano al arca cuando los bueyes tropezaron, y Dios lo hirió allí mismo.","cita":"1 Crónicas 13:10","versiculo":"Y el furor de Jehová se encendió contra Uza, y lo hirió, porque había extendido su mano al arca: y murió allí delante de Dios.","vcita":"1 Crónicas 13:10","pista":"«El arca no se tocaba: ni con buena intención.»"},{"pregunta":"¿Con qué tres nombres comienza la genealogía de 1 Crónicas?","opciones":["Adán, Set y Enós","Noé, Sem y Cam","Abraham, Isaac y Jacob","Saúl, David y Salomón"],"dato":"El libro abre con la genealogía desde Adán, recorriendo toda la historia de Israel.","cita":"1 Crónicas 1:1","versiculo":"Adam, Seth, Enós,","vcita":"1 Crónicas 1:1","pista":"«El primer hombre, su hijo y su nieto: así arranca el libro.»"},{"pregunta":"¿Quién incitó a David a hacer el censo de Israel?","opciones":["Satanás","Joab","Saúl","Absalón"],"dato":"El censo trajo graves consecuencias para Israel, y David reconoció su pecado.","cita":"1 Crónicas 21:1","versiculo":"Y Satanás se levantó contra Israel, e incitó a David a que contase a Israel.","vcita":"1 Crónicas 21:1","pista":"«No fue un general ni un enemigo visible quien lo empujó.»"},{"pregunta":"¿Cuánto pagó David a Ornán por la era donde levantó altar a Jehová?","opciones":["Seiscientos siclos de oro","Cincuenta siclos de plata","Mil siclos de oro","Treinta piezas de plata"],"dato":"David no quiso ofrecer a Dios algo que no le costara nada, y pagó el precio completo.","cita":"1 Crónicas 21:25","versiculo":"Y dio David a Ornán por el lugar seiscientos siclos de oro por peso.","vcita":"1 Crónicas 21:25","pista":"«No aceptó el terreno regalado: lo que se ofrece a Dios debe costar.»"},{"pregunta":"¿Por qué Dios no permitió que David edificara el templo?","opciones":["Porque había derramado mucha sangre en guerras","Porque era demasiado viejo","Porque no era sacerdote","Porque vivía en Jerusalén"],"dato":"La tarea de edificar la casa quedó para Salomón, hijo de David.","cita":"1 Crónicas 22:8","versiculo":"Mas vino a mí palabra de Jehová, diciendo: Tú has derramado sangre en abundancia, y has hecho grandes guerras: no edificarás casa a mi nombre, porque has derramado mucha sangre en la tierra delante de mí.","vcita":"1 Crónicas 22:8","pista":"«El guerrero preparó todo, pero el constructor sería su hijo.»"},{"pregunta":"¿Quiénes eran los únicos que debían cargar el arca de Dios, según David?","opciones":["Los levitas","Solo los hijos de Aarón","Los valientes de David","Los ancianos de Israel"],"dato":"Después de lo sucedido con Uza, David ordenó que solo los levitas llevaran el arca.","cita":"1 Crónicas 15:2","versiculo":"Entonces dijo David: El arca de Dios no debe ser traída sino por los Levitas; porque a ellos ha elegido Jehová para que lleven el arca de Jehová, y le sirvan perpetuamente.","vcita":"1 Crónicas 15:2","pista":"«La lección se aprendió de forma dolorosa: el arca tiene sus portadores señalados.»"},{"pregunta":"¿Qué hizo David antes de subir contra los filisteos?","opciones":["Consultó a Dios","Contó sus soldados","Envió espías","Ofreció sacrificios"],"dato":"David buscaba la dirección de Dios antes de cada batalla.","cita":"1 Crónicas 14:10","versiculo":"Entonces David consultó a Dios, diciendo: ¿Subiré contra los Filisteos? ¿Los entregarás en mi mano? Y Jehová le dijo: Sube, que yo los entregaré en tus manos.","vcita":"1 Crónicas 14:10","pista":"«Antes de la espada, la pregunta.»"},{"pregunta":"¿Por qué se debe alabar a Jehová, según 1 Crónicas 16:34?","opciones":["Porque él es bueno y su misericordia es eterna","Porque da riquezas a sus siervos","Porque destruye a los enemigos","Porque habita en el templo"],"dato":"El canto de acción de gracias de David celebra la bondad y la misericordia eterna de Dios.","cita":"1 Crónicas 16:34","versiculo":"Alabad a Jehová, porque él es bueno; porque su misericordia es eterna.","vcita":"1 Crónicas 16:34","pista":"«Dos razones bastan: su bondad y una misericordia que no se acaba.»"},{"pregunta":"¿Quién reinó en Israel después de la muerte de David?","opciones":["Salomón su hijo","Joab","Absalón","Natán"],"dato":"David murió en buena vejez, lleno de días, de riquezas y de gloria.","cita":"1 Crónicas 29:28","versiculo":"Y murió en buena vejez, lleno de días, de riquezas, y de gloria: y reinó en su lugar Salomón su hijo.","vcita":"1 Crónicas 29:28","pista":"«El hijo de la promesa tomó el trono en paz.»"},{"pregunta":"¿Qué hijos apartó David para el ministerio de la música en el templo?","opciones":["Los de Asaf, Hemán y Jedutún","Los de Aarón, Moisés y Josué","Los de Judá, Benjamín y Leví","Los de Samuel, Natán y Gad"],"dato":"Los músicos profetizaban con arpas, salterios y címbalos.","cita":"1 Crónicas 25:1","versiculo":"Asimismo David y los príncipes del ejército apartaron para el ministerio a los hijos de Asaph, y de Hemán, y de Jeduthún, para que profetizasen con arpas, salterios, y címbalos.","vcita":"1 Crónicas 25:1","pista":"«Tres familias, tres directores de alabanza.»"},{"pregunta":"Según la oración de David en 1 Crónicas 29:12, ¿de quién proceden las riquezas y la gloria?","opciones":["De Dios, que domina sobre todo","Del esfuerzo del rey","De los tributos de las naciones","De las minas de Ofir"],"dato":"David reconoció que todo lo que Israel tenía venía de la mano de Dios.","cita":"1 Crónicas 29:12","versiculo":"Las riquezas y la gloria proceden de ti, y tú dominas sobre todo; en tu mano está la fuerza y el poder, y en tu mano el hacer grande y el dar fortaleza a todos.","vcita":"1 Crónicas 29:12","pista":"«Ni la corona ni el oro son del rey: todo viene de arriba.»"}],"2 Crónicas":[{"pregunta":"¿Qué pidió Salomón a Dios al comenzar su reinado?","opciones":["Sabiduría y ciencia para gobernar al pueblo","Riquezas y larga vida","Victoria sobre todos sus enemigos","Un templo más grande que el tabernáculo"],"dato":"Salomón no pidió riquezas ni vida larga, sino sabiduría para gobernar a un gran pueblo.","cita":"2 Crónicas 1:10","versiculo":"Dame ahora sabiduría y ciencia, para salir y entrar delante de este pueblo: porque ¿quién podrá juzgar este tu pueblo tan grande?","vcita":"2 Crónicas 1:10","pista":"«Lo que pidió no era para él, sino para su pueblo.»"},{"pregunta":"¿Qué impidió a los sacerdotes ministrar en la dedicación del templo?","opciones":["La nube de la gloria de Jehová que llenó la casa","El humo del sacrificio","La multitud que cantaba","Un fuerte viento"],"dato":"La gloria de Dios se manifestó en la casa, y los sacerdotes no podían permanecer de pie para servir.","cita":"2 Crónicas 5:14","versiculo":"Y no podían los sacerdotes estar para ministrar, por causa de la nube; porque la gloria de Jehová había llenado la casa de Dios.","vcita":"2 Crónicas 5:14","pista":"«El templo se llenó: ni los sacerdotes cabían en servicio.»"},{"pregunta":"Según 2 Crónicas 7:14, ¿qué debe hacer el pueblo para que Dios sane su tierra?","opciones":["Humillarse, orar, buscar el rostro de Dios y apartarse del mal","Ofrecer mil holocaustos","Ayunar durante cuarenta días","Reconstruir el templo"],"dato":"Es la promesa de Dios tras la dedicación del templo: humildad y oración preceden al perdón.","cita":"2 Crónicas 7:14","versiculo":"Si se humillare mi pueblo, sobre los cuales mi nombre es invocado, y oraren, y buscaren mi rostro, y se convirtieren de sus malos caminos; entonces yo oiré desde los cielos, y perdonaré sus pecados, y sanaré su tierra.","vcita":"2 Crónicas 7:14","pista":"«Cuatro pasos: humildad, oración, búsqueda y conversión.»"},{"pregunta":"¿Cuántos talentos de oro dio la reina de Sabá a Salomón?","opciones":["Ciento veinte talentos","Sesenta talentos","Trescientos talentos","Mil talentos"],"dato":"La reina de Sabá llegó con especias aromáticas y piedras preciosas como nunca antes se vieron.","cita":"2 Crónicas 9:9","versiculo":"Y dio al rey ciento veinte talentos de oro, y gran cantidad de especias aromáticas, y piedras preciosas: nunca hubo tales especias aromáticas como las que dio la reina de Seba al rey Salomón.","vcita":"2 Crónicas 9:9","pista":"«Más de cien: un regalo digno de la fama de Salomón.»"},{"pregunta":"¿Qué ocurrió con Israel después de la dureza de Roboam?","opciones":["Se apartó de la casa de David","Se unió a Egipto","Destruyó el templo de Jerusalén","Coronó a Roboam por la fuerza"],"dato":"La respuesta áspera de Roboam provocó la división del reino.","cita":"2 Crónicas 10:19","versiculo":"Así se apartó Israel de la casa de David hasta hoy.","vcita":"2 Crónicas 10:19","pista":"«Diez tribus tomaron otro camino.»"},{"pregunta":"¿Qué mensaje dio el profeta Azarías al rey Asa?","opciones":["Que se esforzara, porque su obra tendría recompensa","Que huyera a Egipto","Que destruyera Jerusalén","Que volviera a contar al pueblo"],"dato":"Animado por ese mensaje, Asa quitó la idolatría y renovó el altar de Jehová.","cita":"2 Crónicas 15:7","versiculo":"Esforzáos vosotros, y no desfallezcan vuestras manos; pues hay recompensa para vuestra obra.","vcita":"2 Crónicas 15:7","pista":"«Un empujón divino: no suelten las manos.»"},{"pregunta":"¿De quién dijo Dios que era la guerra contra la gran multitud enemiga?","opciones":["De Dios, no de Judá","Del rey Josafat","De los levitas","De Moab y Amón"],"dato":"Josafat solo tuvo que presenciar la salvación de Jehová: la batalla no era suya.","cita":"2 Crónicas 20:15","versiculo":"No temáis ni os amedrentéis delante de esta multitud tan grande; porque no es vuestra la guerra, sino de Dios.","vcita":"2 Crónicas 20:15","pista":"«Hay guerras que no peleas tú: las pelea Dios.»"},{"pregunta":"¿Qué puso Josafat al frente del ejército para enfrentar al enemigo?","opciones":["Cantores que alababan a Jehová","Los mejores arqueros","Carros de guerra","El arca del pacto"],"dato":"Los cantores iban delante del ejército dando gracias a Jehová, y Dios puso emboscadas contra los enemigos.","cita":"2 Crónicas 20:21","versiculo":"Y habido consejo con el pueblo, puso a algunos que cantasen y alabasen a Jehová, vestidos de ornamentos sagrados, mientras salía la gente armada, y dijesen: Glorificad a Jehová, porque su misericordia es para siempre.","vcita":"2 Crónicas 20:21","pista":"«En vez de vanguardia armada: un coro.»"},{"pregunta":"¿Cómo reinó Ezequías, según 2 Crónicas 29:2?","opciones":["Hizo lo recto ante Jehová, como David su padre","Adoró en los lugares altos","Se alió con Asiria contra Dios","Cerró las puertas del templo"],"dato":"Ezequías abrió las puertas de la casa de Jehová y restauró el culto que su padre había abandonado.","cita":"2 Crónicas 29:2","versiculo":"E hizo lo recto en ojos de Jehová, conforme a todas las cosas que había hecho David su padre.","vcita":"2 Crónicas 29:2","pista":"«El mejor elogio para un rey: como David.»"},{"pregunta":"¿Qué dijo Ezequías al pueblo frente al ejército de Senaquerib?","opciones":["Que con Asiria había un brazo de carne, pero con Judá estaba Dios","Que Jerusalén debía rendirse","Que el pueblo huyera al desierto","Que se pagara un gran tributo"],"dato":"Las palabras de Ezequías dieron confianza al pueblo ante la amenaza asiria.","cita":"2 Crónicas 32:8","versiculo":"Con él está el brazo de carne, mas con nosotros está Jehová nuestro Dios para ayudarnos, y pelear nuestras batallas. Y el pueblo tuvo confianza en las palabras de Ezequías rey de Judá.","vcita":"2 Crónicas 32:8","pista":"«Fuerza humana de un lado; Dios del otro.»"},{"pregunta":"¿A qué edad comenzó Josías a buscar al Dios de David?","opciones":["A los ocho años","A los doce años","A los dieciséis años","A los veinte años"],"dato":"Siendo aún muchacho, Josías buscó a Dios y luego limpió a Judá de la idolatría.","cita":"2 Crónicas 34:3","versiculo":"A los ocho años de su reinado, siendo aún muchacho, comenzó a buscar al Dios de David su padre; y a los doce años comenzó a limpiar a Judá y a Jerusalem de los altos, bosques, esculturas, e imágenes de fundición.","vcita":"2 Crónicas 34:3","pista":"«No esperó a ser adulto para buscar a Dios.»"},{"pregunta":"¿Qué halló el sacerdote Hilcías en la casa de Jehová en tiempos de Josías?","opciones":["El libro de la ley","El arca del pacto","El tesoro del templo","Las tablas de piedra de Moisés"],"dato":"El hallazgo del libro de la ley provocó la gran reforma de Josías.","cita":"2 Crónicas 34:15","versiculo":"Y Hilcías, hablando, dijo a Saphán escriba: Yo he hallado el libro de la ley en la casa de Jehová. Y dio Hilcías el libro a Saphán.","vcita":"2 Crónicas 34:15","pista":"«Estaba perdido en la propia casa de Dios.»"}],"Esdras":[{"pregunta":"¿Qué invitó Ciro, rey de Persia, a hacer a los judíos en su decreto?","opciones":["Subir a Jerusalén y edificar la casa de Jehová","Quedarse en Babilonia sirviendo al imperio","Edificar un templo en Persia","Regresar solo a los sacerdotes"],"dato":"El decreto de Ciro cumplió la palabra de Jehová por boca de Jeremías y abrió la vuelta del cautiverio.","cita":"Esdras 1:3","versiculo":"¿Quién hay entre vosotros de todo su pueblo? Sea Dios con él, y suba a Jerusalem que está en Judá, y edifique la casa a Jehová Dios de Israel, (él es el Dios,) la cual está en Jerusalem.","vcita":"Esdras 1:3","pista":"«Un rey pagano tocó la trompeta del regreso a casa.»"},{"pregunta":"¿Cuántas personas sumaba la congregación que volvió del cautiverio?","opciones":["Cuarenta y dos mil trescientos sesenta","Diez mil exactos","Cien mil personas","Veinticuatro mil quinientas"],"dato":"La lista de Esdras 2 registra familias, sacerdotes, levitas y siervos que regresaron con Zorobabel.","cita":"Esdras 2:64","versiculo":"Toda la congregación, unida, como un solo hombre, era de cuarenta y dos mil trescientos sesenta,","vcita":"Esdras 2:64","pista":"«Más de cuarenta mil volvieron como un solo hombre.»"},{"pregunta":"¿Cuántos cantores, hijos de Asaf, se registraron entre los que volvieron?","opciones":["Ciento veintiocho","Doscientos","Setenta y cinco","Trescientos"],"dato":"Hasta los cantores fueron contados en la lista del regreso: la alabanza volvía al templo.","cita":"Esdras 2:41","versiculo":"Los cantores: los hijos de Asaph, ciento veintiocho.","vcita":"Esdras 2:41","pista":"«Más de cien voces traían la música de vuelta.»"},{"pregunta":"¿Qué cantaba el pueblo cuando se echaban los cimientos del templo?","opciones":["Que Dios es bueno y su misericordia es para siempre","Un cántico nuevo de guerra","El salmo de Moisés","La bendición de Aarón"],"dato":"Al ver los cimientos puestos, todo el pueblo aclamaba con gran júbilo.","cita":"Esdras 3:11","versiculo":"Y cantaban, alabando y confesando a Jehová: Porque es bueno, porque para siempre es su misericordia sobre Israel. Y todo el pueblo aclamaba con gran júbilo, alabando a Jehová, porque se echaban los cimientos de la casa de Jehová.","vcita":"Esdras 3:11","pista":"«Apenas era el cimiento, y ya sonaban los címbalos.»"},{"pregunta":"¿Qué hacía el pueblo de la tierra para frenar la obra del templo?","opciones":["Debilitaba las manos del pueblo y lo arredraba de edificar","Robaba los materiales por la noche","Quemó los cimientos","Sobornó al rey de Persia"],"dato":"La oposición local consiguió incluso que la obra se detuviera por un tiempo.","cita":"Esdras 4:4","versiculo":"Entonces el pueblo de la tierra debilitaba las manos del pueblo de Judá, y los arredraba de edificar.","vcita":"Esdras 4:4","pista":"«El desánimo también se usa para detener obras de Dios.»"},{"pregunta":"¿Quiénes comenzaron a edificar la casa de Dios cuando la obra se reanudó?","opciones":["Zorobabel y Jesúa, animados por los profetas","Nehemías y Esdras","Los reyes de Persia","Los samaritanos arrepentidos"],"dato":"Los profetas Hageo y Zacarías alentaron el reinicio de la construcción.","cita":"Esdras 5:2","versiculo":"Levantáronse entonces Zorobabel hijo de Sealthiel, y Jesúa hijo de Josadec, y comenzaron a edificar la casa de Dios que está en Jerusalem; y con ellos los profetas de Dios que les ayudaban.","vcita":"Esdras 5:2","pista":"«Un gobernador y un sacerdote, con profetas al lado.»"},{"pregunta":"¿En qué reinado se terminó de edificar la casa de Dios?","opciones":["En el reinado de Darío, en su sexto año","En el reinado de Ciro","En el reinado de Artajerjes, año veinte","En el reinado de Asuero"],"dato":"La casa se acabó el tercer día del mes de Adar, tras los mandamientos de Ciro, Darío y Artajerjes.","cita":"Esdras 6:15","versiculo":"Y esta casa fue acabada al tercer día del mes de Adar, que era el sexto año del reinado del rey Darío.","vcita":"Esdras 6:15","pista":"«Tres reyes persas firmaron, pero el que terminó la casa fue Dios.»"},{"pregunta":"¿Cómo prosperó la edificación del templo, según Esdras 6:14?","opciones":["Conforme a la profecía de Hageo y de Zacarías","Gracias al oro de Egipto","Por el ejército de Persia","Por la ayuda de los samaritanos"],"dato":"Los ancianos de los judíos edificaban y prosperaban bajo la palabra de los profetas.","cita":"Esdras 6:14","versiculo":"Y los ancianos de los Judíos edificaban y prosperaban, conforme a la profecía de Haggeo profeta, y de Zacarías hijo de Iddo. Edificaron pues, y terminaron, por el mandamiento del Dios de Israel, y por el mandamiento de Ciro, y de Darío, y de Artajerjes rey de Persia.","vcita":"Esdras 6:14","pista":"«Ladrillo a ladrillo, profecía en mano.»"},{"pregunta":"¿Cómo describe el libro a Esdras cuando subió de Babilonia?","opciones":["Escriba diligente en la ley de Moisés","Príncipe de los sacerdotes","Capitán del ejército","Copero del rey"],"dato":"La mano de Jehová estaba sobre Esdras, y el rey le concedió todo lo que pidió.","cita":"Esdras 7:6","versiculo":"Este Esdras subió de Babilonia, y era escriba diligente en la ley de Moisés, que Jehová Dios de Israel había dado; y le concedió el rey todo lo que pidió, porque la mano de Jehová su Dios era sobre Esdras.","vcita":"Esdras 7:6","pista":"«Un experto en la ley con la mano de Dios sobre él.»"},{"pregunta":"¿Dónde publicó Esdras un ayuno para pedir camino derecho a Dios?","opciones":["Junto al río Ahava","En el desierto de Judá","A las puertas del templo","En el monte Moriah"],"dato":"Esdras se avergonzó de pedir escolta al rey: el ayuno fue su declaración de confianza en Dios.","cita":"Esdras 8:21","versiculo":"Y publiqué ayuno allí junto al río Ahava, para afligirnos delante de nuestro Dios, para solicitar de él camino derecho para nosotros, y para nuestros niños, y para toda nuestra hacienda.","vcita":"Esdras 8:21","pista":"«Sin escolta armada: ayuno a la orilla de un río.»"},{"pregunta":"¿Cómo se sentía Esdras al orar por los pecados del pueblo?","opciones":["Confuso y avergonzado para levantar su rostro a Dios","Seguro de la inocencia del pueblo","Enojado con los enemigos","Cansado del viaje"],"dato":"Esdras confesó que las iniquidades del pueblo se habían multiplicado sobre su cabeza.","cita":"Esdras 9:6","versiculo":"Y dije: Dios mío, confuso y avergonzado estoy para levantar, oh Dios mío, mi rostro a ti: porque nuestras iniquidades se han multiplicado sobre nuestra cabeza, y nuestros delitos han crecido hasta el cielo.","vcita":"Esdras 9:6","pista":"«La intercesión verdadera carga con el pecado ajeno como propio.»"},{"pregunta":"¿Qué esperanza señaló Secanías cuando se descubrieron los matrimonios mixtos?","opciones":["Que aun así había esperanza para Israel","Que el rey anularía la ley","Que el pueblo partiría otra vez a Babilonia","Que el templo sería cerrado"],"dato":"Secanías reconoció la prevaricación del pueblo y aun así animó a Esdras a actuar.","cita":"Esdras 10:2","versiculo":"Y respondió Sechânías hijo de Jehiel, de los hijos de Elam, y dijo a Esdras: Nosotros hemos prevaricado contra nuestro Dios, pues tomamos mujeres extranjeras de los pueblos de la tierra: mas hay aún esperanza para Israel sobre esto.","vcita":"Esdras 10:2","pista":"«Aun en el peor diagnóstico, dejó una puerta abierta.»"}],"Nehemías":[{"pregunta":"¿Qué noticia recibió Nehemías sobre los que volvieron a Jerusalén?","opciones":["Que estaban en gran mal y afrenta, con el muro derribado","Que el templo ya estaba terminado","Que el rey los había hecho gobernadores","Que habían vencido a los samaritanos"],"dato":"El informe quebrantó a Nehemías: el muro estaba derribado y las puertas quemadas a fuego.","cita":"Nehemías 1:3","versiculo":"Y dijéronme: El resto, los que quedaron de la cautividad, allí en la provincia, están en gran mal y afrenta, y el muro de Jerusalem derribado, y sus puertas quemadas a fuego.","vcita":"Nehemías 1:3","pista":"«Una noticia que produce llanto, no indiferencia.»"},{"pregunta":"¿Qué oficio tenía Nehemías en la corte del rey?","opciones":["Copero del rey","Escriba principal","Capitán de la guardia","Mayordomo del palacio"],"dato":"Nehemías servía de copero al rey Artajerjes, y aun así su corazón estaba en Jerusalén.","cita":"Nehemías 1:11","versiculo":"Te ruego, oh Jehová, esté ahora atento tu oído a la oración de tu siervo, y a la oración de tus siervos, quienes desean reverenciar tu nombre: concede ahora buen suceso a tu siervo, y dale gracia delante de aquel varón. Porque yo servía de copero al rey.","vcita":"Nehemías 1:11","pista":"«Servía la copa del rey más poderoso de la época.»"},{"pregunta":"¿Qué hizo Nehemías cuando el rey le preguntó qué pedía?","opciones":["Oró al Dios de los cielos","Lloró delante del rey","Pidió consejo a la reina","Guardó silencio un día"],"dato":"Su oración fue breve y silenciosa, en el mismo instante de la conversación con el rey.","cita":"Nehemías 2:4","versiculo":"Díjome el rey: ¿Qué cosa pides? Entonces oré al Dios de los cielos,","vcita":"Nehemías 2:4","pista":"«Una oración-relámpago entre pregunta y respuesta.»"},{"pregunta":"¿Qué hizo Nehemías de noche al llegar a Jerusalén?","opciones":["Salió a observar los muros derribados y las puertas quemadas","Convocó una asamblea pública","Comenzó a edificar solo","Durmió en el templo"],"dato":"Nehemías inspeccionó en secreto la ruina antes de anunciar su plan al pueblo.","cita":"Nehemías 2:13","versiculo":"Y salí de noche por la puerta del Valle hacia la fuente del Dragón y a la puerta del Muladar; y observé los muros de Jerusalem que estaban derribados, y sus puertas que estaban consumidas del fuego.","vcita":"Nehemías 2:13","pista":"«Primero ver el muro con los propios ojos.»"},{"pregunta":"¿Qué respondió el pueblo cuando Nehemías les declaró la mano de Dios sobre él?","opciones":["Levantémonos, y edifiquemos","Hay que esperar un año más","No tenemos materiales","Volvamos a Persia"],"dato":"El pueblo esforzó sus manos para bien: la visión compartida encendió la obra.","cita":"Nehemías 2:18","versiculo":"Entonces les declaré cómo la mano de mi Dios era buena sobre mí, y asimismo las palabras del rey, que me había dicho. Y dijeron: Levantémonos, y edifiquemos. Así esforzaron sus manos para bien.","vcita":"Nehemías 2:18","pista":"«Tres palabras bastaron para mover a una ciudad entera.»"},{"pregunta":"¿Qué hicieron Sanbalat, Tobías y Gesem al oír de la obra del muro?","opciones":["Hicieron escarnio y despreciaron a los judíos","Ofrecieron su ayuda","Atacaron esa misma noche","Escribieron al rey en su favor"],"dato":"Los enemigos acusaron a los judíos de rebelarse contra el rey para intentar detenerlos.","cita":"Nehemías 2:19","versiculo":"Mas habiéndolo oído Sanballat Horonita, y Tobías el siervo Ammonita, y Gesem el Arabe, hicieron escarnio de nosotros, y nos despreciaron, diciendo: ¿Qué es esto que hacéis vosotros? ¿Os rebeláis contra el rey?","vcita":"Nehemías 2:19","pista":"«Cuando falta fuerza, sobra burla.»"},{"pregunta":"¿A quién mandó recordar Nehemías al pueblo antes del enfrentamiento?","opciones":["Al Señor grande y terrible","A Moisés y su vara","A David y su ejército","A los muros de Persia"],"dato":"Nehemías animó al pueblo a pelear por sus hermanos, hijos, hijas, mujeres y casas.","cita":"Nehemías 4:14","versiculo":"Después miré, y levantéme y dije a los principales y a los magistrados, y al resto del pueblo: No temáis delante de ellos: acordaos del Señor grande y terrible, y pelead por vuestros hermanos, por vuestros hijos y vuestras hijas, por vuestras mujeres y vuestras casas.","vcita":"Nehemías 4:14","pista":"«La memoria de quién es Dios vence el miedo.»"},{"pregunta":"¿Cómo trabajaban los que edificaban el muro bajo amenaza?","opciones":["Con una mano en la obra y la otra en la espada","Solo de noche","Cantando salmos sin herramientas","Protegidos por soldados persas"],"dato":"Cada obrero cargaba y trabajaba sin soltar el arma: la obra avanzaba bajo guardia permanente.","cita":"Nehemías 4:17","versiculo":"Los que edificaban en el muro, y los que acarreaban, y los que cargaban, con la una mano trabajaban en la obra, y en la otra tenían la espada.","vcita":"Nehemías 4:17","pista":"«Paleta en una mano, defensa en la otra.»"},{"pregunta":"¿En cuántos días fue terminado el muro de Jerusalén?","opciones":["En cincuenta y dos días","En un año completo","En cien días","En siete meses"],"dato":"El muro quedó terminado el veinticinco del mes de Elul, asombrando a los enemigos.","cita":"Nehemías 6:15","versiculo":"Fue, pues, terminado el muro el veinticinco del mes de Elul, en cincuenta y dos días.","vcita":"Nehemías 6:15","pista":"«Menos de dos meses para cerrar toda una ciudad.»"},{"pregunta":"¿Dónde se leyó el libro de la ley ante todo el pueblo?","opciones":["En la plaza delante de la puerta de las Aguas","En el monte de los Olivos","En el aposento alto del palacio","En la puerta del Valle"],"dato":"Esdras leyó la ley desde el alba hasta el mediodía, y los oídos del pueblo estaban atentos.","cita":"Nehemías 8:3","versiculo":"Y leyó en el libro delante de la plaza que está delante de la puerta de las Aguas, desde el alba hasta el mediodía, en presencia de hombres y mujeres y entendidos; y los oídos de todo el pueblo estaban atentos al libro de la ley.","vcita":"Nehemías 8:3","pista":"«Seis horas de lectura pública, y nadie se movía.»"},{"pregunta":"Según Nehemías 8:10, ¿qué es la fortaleza del pueblo de Dios?","opciones":["El gozo de Jehová","El muro recién edificado","La abundancia de comida","El ejército de voluntarios"],"dato":"En vez de tristeza por la ley oída, el pueblo recibió gozo: era día santo a su Señor.","cita":"Nehemías 8:10","versiculo":"Luego les dijo: Id, comed grosuras, y bebed vino dulce, y enviad porciones a los que no tienen prevenido; porque día santo es a nuestro Señor: y no os entristezcáis, porque el gozo de Jehová es vuestra fortaleza.","vcita":"Nehemías 8:10","pista":"«No es el muro ni la espada: es el gozo.»"}],"Ester":[{"pregunta":"¿Por qué enojó el rey contra la reina Vasti?","opciones":["Porque no quiso venir a su orden enviada por los eunucos","Porque llegó tarde al banquete","Porque defendió a los judíos","Porque se negó a usar la corona"],"dato":"Vasti rehusó presentarse ante el rey y sus príncipes, y su ira se encendió.","cita":"Ester 1:12","versiculo":"Mas la reina Vasthi no quiso venir a la orden del rey, enviada por mano de los eunucos; y enojóse el rey mucho, y encendióse en él su ira.","vcita":"Ester 1:12","pista":"«Una negativa en pleno banquete cambió la historia.»"},{"pregunta":"¿Qué hizo el rey con Ester al amarla más que a las demás jóvenes?","opciones":["Puso la corona real en su cabeza y la hizo reina","Le regaló una provincia entera","La envió de vuelta a su casa","Le dio la mitad del reino"],"dato":"Ester halló gracia y benevolencia delante del rey más que todas las demás vírgenes.","cita":"Ester 2:17","versiculo":"Y el rey amó a Esther sobre todas las mujeres, y halló ella gracia y benevolencia delante de él más que todas las demás vírgenes; y puso la corona real en su cabeza, y la hizo reina en lugar de Vasthi.","vcita":"Ester 2:17","pista":"«De huérfana judía a la corona de Persia.»"},{"pregunta":"¿Qué NO hacía Mardoqueo delante de Amán, a pesar de la orden del rey?","opciones":["No se arrodillaba ni se humillaba","No le pagaba el tributo","No asistía a los banquetes","No le entregaba sus cartas"],"dato":"La negativa de Mardoqueo llenó de ira a Amán y desató su plan contra todos los judíos.","cita":"Ester 3:2","versiculo":"Y todos los siervos del rey que estaban a la puerta del rey, se arrodillaban y adoraban a Amán, porque así lo había mandado el rey; pero Mardochêo ni se arrodillaba ni se humillaba.","vcita":"Ester 3:2","pista":"«Uno solo se quedó de pie a la puerta del rey.»"},{"pregunta":"¿Qué ordenaban las cartas enviadas por Amán a todas las provincias?","opciones":["Destruir, matar y exterminar a todos los judíos en un mismo día","Expulsar a los judíos del reino en un año","Quemar las sinagogas de cada ciudad","Confiscar la mitad de sus bienes"],"dato":"El día señalado era el trece del mes duodécimo, el mes de Adar.","cita":"Ester 3:13","versiculo":"Y fueron enviadas cartas por medio de correos a todas las provincias del rey, con la orden de destruir, y matar, y exterminar a todos los Judíos, jóvenes y viejos, niños y mujeres, en un mismo día, en el día trece del mes duodécimo, que es el mes de Adar, y de apoderarse de sus bienes.","vcita":"Ester 3:13","pista":"«Un edicto con fecha de muerte para todo un pueblo.»"},{"pregunta":"¿Qué pregunta famosa hizo Mardoqueo a Ester en su mensaje?","opciones":["¿Y quién sabe si para esta hora has llegado al reino?","¿Por qué no le dijiste al rey que eres judía?","¿Vendrás con nosotros a Susa?","¿Has olvidado a tu pueblo?"],"dato":"Mardoqueo le advirtió que si callaba, la liberación vendría de otra parte, pero ella y su casa perecerían.","cita":"Ester 4:14","versiculo":"Porque si absolutamente callas en este tiempo, respiro y libertación tendrán los Judíos de otra parte; mas tú y la casa de tu padre pereceréis. ¿Y quién sabe si para esta hora has llegado al reino?","vcita":"Ester 4:14","pista":"«Quizás la corona no era un premio, sino una misión.»"},{"pregunta":"¿Qué palabras dijo Ester antes de entrar al rey sin ser llamada?","opciones":["Si perezco, que perezca","Dios me ha abandonado","Que venga Mardoqueo conmigo","Esperaré un año más"],"dato":"Antes de arriesgar su vida, Ester pidió tres días de ayuno a todos los judíos de Susa.","cita":"Ester 4:16","versiculo":"Ve, y junta a todos los Judíos que se hallan en Susa, y ayunad por mí, y no comáis ni bebáis en tres días, noche ni día: yo también con mis doncellas ayunaré igualmente, y así entraré al rey, aunque no sea conforme a la ley; y si perezco, que perezca.","vcita":"Ester 4:16","pista":"«Primero ayuno; después, a enfrentar la ley de la corte.»"},{"pregunta":"¿Qué hizo el rey cuando vio a Ester en el atrio?","opciones":["Le extendió el cetro de oro que tenía en la mano","La mandó salir del palacio","Llamó a los guardias","Se levantó y se retiró"],"dato":"Extender el cetro era la señal de perdón: Ester tocó su punta y su vida quedó a salvo.","cita":"Ester 5:2","versiculo":"Y fue que, cuando vio a la reina Esther que estaba en el atrio, ella obtuvo gracia en sus ojos; y el rey extendió a Esther el cetro de oro que tenía en la mano. Entonces vino Esther, y tocó la punta del cetro.","vcita":"Ester 5:2","pista":"«Un cetro extendido valía una vida.»"},{"pregunta":"¿Cómo terminó Amán, el enemigo de los judíos?","opciones":["Colgado en la horca que había preparado para Mardoqueo","Desterrado a una isla lejana","Encerrado en la cárcel de Susa","Muerto en batalla contra los judíos"],"dato":"La horca de cincuenta codos que Amán levantó para Mardoqueo se volvió su propio fin.","cita":"Ester 7:10","versiculo":"Así colgaron a Amán en la horca que él había hecho preparar para Mardochêo; y la ira del rey se apaciguó.","vcita":"Ester 7:10","pista":"«La trampa que preparó se cerró sobre él.»"},{"pregunta":"¿Cómo debían celebrar los judíos los días de su liberación, según Ester 9:22?","opciones":["Como días de banquete y regocijo, enviando porciones y dádivas a los pobres","Con ayuno y silencio total","Quemando las cartas de Amán","Viajando a Jerusalén cada año"],"dato":"Así nació la fiesta de Purim: de tristeza a alegría, y de luto a día bueno.","cita":"Ester 9:22","versiculo":"Como días en que los Judíos tuvieron reposo de sus enemigos, y como el mes que de tristeza se les volvió en alegría, y de luto en día bueno; que los hiciesen días de banquete y de regocijo, y de enviar porciones cada uno a su vecino, y dádivas a los pobres.","vcita":"Ester 9:22","pista":"«La alegría se celebra compartiendo, también con los pobres.»"},{"pregunta":"¿Qué lugar ocupó Mardoqueo en el reino al final del libro?","opciones":["El segundo después del rey Asuero","Gobernador de Susa solamente","Sumo sacerdote de los judíos","Juez sobre la provincia de Judá"],"dato":"Mardoqueo fue grande entre los judíos, procurando el bien de su pueblo y hablando paz a toda su descendencia.","cita":"Ester 10:3","versiculo":"Porque Mardochêo judío fue el segundo después del rey Asuero, y grande entre los Judíos, y acepto a la multitud de sus hermanos, procurando el bien de su pueblo, y hablando paz para toda su simiente.","vcita":"Ester 10:3","pista":"«Del portón del rey a su mano derecha.»"}],"Job":[{"pregunta":"¿En qué tierra vivía Job, el hombre perfecto y recto que temía a Dios?","opciones":["Hus","Ur de los caldeos","La tierra de Moab","El país de Edom"],"dato":"Job vivía en la tierra de Hus; la Biblia lo presenta como hombre perfecto y recto, temeroso de Dios y apartado del mal.","cita":"Job 1:1","versiculo":"Hubo un varón en tierra de Hus, llamado Job; y era este hombre perfecto y recto, y temeroso de Dios, y apartado del mal.","vcita":"Job 1:1","pista":"«Es una tierra de nombre cortito: empieza con H.»"},{"pregunta":"¿Cuántos hijos e hijas tenía Job al principio de su historia?","opciones":["Siete hijos y tres hijas","Tres hijos y siete hijas","Diez hijos y dos hijas","Cinco hijos y cinco hijas"],"dato":"Antes de la prueba, Job tenía siete hijos y tres hijas, y era el hombre más grande de todos los orientales.","cita":"Job 1:2","versiculo":"Y naciéronle siete hijos y tres hijas.","vcita":"Job 1:2","pista":"«Siete más tres: una familia de diez.»"},{"pregunta":"¿Quién se presentó entre los hijos de Dios y desafió la fidelidad de Job?","opciones":["Satán","El ángel Gabriel","Un querubín llamado Azazel","El rey de Tiro"],"dato":"Un día los hijos de Dios se presentaron ante Jehová, y entre ellos vino también Satán, que acusó a Job de servir a Dios solo por lo que recibía.","cita":"Job 1:6","versiculo":"Y un día vinieron los hijos de Dios a presentarse delante de Jehová, entre los cuales vino también Satán.","vcita":"Job 1:6","pista":"«El adversario, el acusador de los hermanos.»"},{"pregunta":"¿Qué dijo Job después de perder sus bienes y a sus hijos en un solo día?","opciones":["«Jehová dio, y Jehová quitó; sea el nombre de Jehová bendito»","«Maldigo mi suerte y dejo de orar»","«Pido a Dios que me quite la vida»","«Dios ha sido injusto conmigo»"],"dato":"Job se postró en tierra, adoró, y bendijo el nombre de Jehová sin atribuirle ningún despropósito.","cita":"Job 1:21","versiculo":"Y dijo: Desnudo salí del vientre de mi madre, y desnudo tornaré allá. Jehová dio, y Jehová quitó: sea el nombre de Jehová bendito.","vcita":"Job 1:21","pista":"«Ni maldijo ni renunció: bendijo.»"},{"pregunta":"¿Qué le aconsejó la esposa de Job cuando él quedó enfermo y en la ruina?","opciones":["Que renegara de Dios y se muriera","Que huyera a casa de sus padres","Que vendiera lo poco que quedaba","Que buscara a un sacerdote en Jerusalén"],"dato":"Desesperada, le dijo: «¿Aún retienes tú tu simplicidad? Bendice a Dios, y muérete»; Job la reprendió por hablar como una insensata.","cita":"Job 2:9","versiculo":"Díjole entonces su mujer: ¿Aún retienes tú tu simplicidad? Bendice a Dios, y muérete.","vcita":"Job 2:9","pista":"«Un consejo desesperado que Job rechazó enseguida.»"},{"pregunta":"¿Cómo se llamaba el amigo de Job que venía de Temán?","opciones":["Elifaz","Bildad","Zofar","Eliú"],"dato":"Los tres amigos fueron Elifaz temanita, Bildad suhita y Zofar naamatita; vinieron a condolerse de Job y a consolarlo.","cita":"Job 2:11","versiculo":"Y tres amigos de Job, Elifaz temanita, y Bildad suhita, y Zofar naamatita, luego que oyeron todo este mal que le había sobrevenido, vinieron cada uno de su lugar; porque habían concertado de venir juntos a condolecerse de él, y a consolarle.","vcita":"Job 2:11","pista":"«El trío es E-B-Z: el primero es Elifaz.»"},{"pregunta":"¿Quién es el hombre joven que habló después de que los tres amigos de Job callaron?","opciones":["Eliú","Barac","Eliab","Eliseo"],"dato":"Eliú, hijo de Baraquel el buzita, era menor en días y había esperado por respeto a los mayores; al fin habló porque los amigos no lograron responder a Job.","cita":"Job 32:6","versiculo":"Y respondió Eliú hijo de Baraquel, buzita, y dijo: Yo soy menor de días, y vosotros viejos; he tenido por tanto miedo, y temido declararos mi opinión.","vcita":"Job 32:6","pista":"«El más joven de los que hablaron; su padre era Baraquel.»"},{"pregunta":"Completa la declaración de fe de Job en medio de su dolor: «Yo sé que mi ______ vive, y al fin se levantará sobre el polvo».","opciones":["Redentor","Defensor","Consolador","Salvador"],"dato":"En su peor momento, Job confesó que su Redentor vive y que al final se levantaría sobre el polvo: una de las grandes declaraciones de esperanza del Antiguo Testamento.","cita":"Job 19:25","versiculo":"Yo sé que mi Redentor vive, y al fin se levantará sobre el polvo:","vcita":"Job 19:25","pista":"«Es el título de quien nos rescata; empieza con R.»"},{"pregunta":"Según Job 28, ¿qué es la sabiduría?","opciones":["El temor del Señor","Conocer toda la ciencia","Tener muchos años","Hallar oro y plata en la tierra"],"dato":"Tras buscar la sabiduría como un tesoro escondido, Job concluye que ella no se compra con oro: el temor del Señor es la sabiduría, y apartarse del mal, la inteligencia.","cita":"Job 28:28","versiculo":"Y dijo al hombre: He aquí que el temor del Señor es la sabiduría, y el apartarse del mal la inteligencia.","vcita":"Job 28:28","pista":"«No está en las minas: está en el corazón que teme a Dios.»"},{"pregunta":"¿Desde dónde le respondió Jehová a Job cuando por fin le habló?","opciones":["Desde un torbellino","Desde una nube en el monte Sinaí","Desde el santuario del templo","En un sueño de noche"],"dato":"Tras capítulos de silencio, Jehová respondió a Job desde un torbellino, mostrándole su grandeza en la creación.","cita":"Job 38:1","versiculo":"Y respondió Jehová a Job desde un torbellino, y dijo:","vcita":"Job 38:1","pista":"«Dios habló desde el viento que gira, no desde un templo.»"},{"pregunta":"¿Qué criatura poderosa describe Dios en Job 41, imposible de sacar con anzuelo?","opciones":["El leviatán","El behemot","El unicornio","La serpiente del Edén"],"dato":"Dios describe al leviatán, criatura de escamas impenetrables, para mostrar a Job que hay cosas muy por encima de su fuerza y de su juicio.","cita":"Job 41:1","versiculo":"¿Sacarás tú al leviatán con el anzuelo, o con la cuerda que le echares en su lengua?","vcita":"Job 41:1","pista":"«La criatura del capítulo 41, de escamas impenetrables.»"},{"pregunta":"¿Cuánto le devolvió Dios a Job al final de su prueba, después de que oró por sus amigos?","opciones":["El doble de lo que tenía","Exactamente lo mismo","Diez veces más","Solo la salud, sin bienes"],"dato":"Cuando Job oró por sus amigos, Jehová mudó su aflicción y le aumentó al doble todo lo que había perdido; y vivió ciento cuarenta años más.","cita":"Job 42:10","versiculo":"Y mudó Jehová la aflicción de Job, orando él por sus amigos: y aumentó al doble todas las cosas que habían sido de Job.","vcita":"Job 42:10","pista":"«Ni lo mismo ni la mitad: ¡el doble!»"}],"Salmos":[{"pregunta":"¿A quién llama «bienaventurado» el Salmo 1, el primero de los salmos?","opciones":["Al varón que no anduvo en consejo de malos","Al rey que vence en la batalla","Al sacerdote que ofrece sacrificios","Al hombre rico y poderoso"],"dato":"El libro de los Salmos abre llamando bienaventurado a quien no sigue el consejo de los malos ni se sienta con los escarnecedores, sino que medita en la ley de Jehová.","cita":"Salmos 1:1","versiculo":"Bienaventurado el varón que no anduvo en consejo de malos, ni estuvo en camino de pecadores, ni en silla de escarnecedores se ha sentado;","vcita":"Salmos 1:1","pista":"«Es el varón que no se sienta con los escarnecedores.»"},{"pregunta":"¿Qué cuentan la gloria de Dios, según el Salmo 19?","opciones":["Los cielos","Los montes","Los ríos","Las estrellas fugaces"],"dato":"David dice que los cielos cuentan la gloria de Dios y que la expansión anuncia la obra de sus manos: la creación entera habla de su Creador.","cita":"Salmos 19:1","versiculo":"Los cielos cuentan la gloria de Dios, y la expansión denuncia la obra de sus manos.","vcita":"Salmos 19:1","pista":"«Mira hacia arriba en una noche despejada.»"},{"pregunta":"Completa el Salmo 23: «Jehová es mi ______; nada me faltará».","opciones":["pastor","rey","escudo","juez"],"dato":"David compara a Jehová con un pastor que guía, alimenta y protege a sus ovejas: con él, nada falta.","cita":"Salmos 23:1","versiculo":"Jehová es mi pastor; nada me faltará.","vcita":"Salmos 23:1","pista":"«Es quien guía a las ovejas: el p…»"},{"pregunta":"En el valle de sombra de muerte, ¿qué dos cosas del pastor infunden aliento al salmista?","opciones":["Su vara y su cayado","Su manto y su sandalia","Su honda y su zurrón","Su trompeta y su arpa"],"dato":"La vara defiende de los peligros y el cayado guía y rescata a las ovejas; por eso, aun en el valle más oscuro, el salmista no teme mal alguno.","cita":"Salmos 23:4","versiculo":"Aunque ande en valle de sombra de muerte, no temeré mal alguno; porque tú estarás conmigo: tu vara y tu cayado me infundirán aliento.","vcita":"Salmos 23:4","pista":"«Una defiende y la otra guía: vara y c…»"},{"pregunta":"Completa el Salmo 46: «Dios es nuestro amparo y ______, nuestro pronto auxilio en las tribulaciones».","opciones":["fortaleza","esperanza","gozo","refugio"],"dato":"Este salmo de los hijos de Coré confiesa que Dios es amparo y fortaleza: ayuda siempre presente en medio de la tribulación.","cita":"Salmos 46:1","versiculo":"Dios es nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones.","vcita":"Salmos 46:1","pista":"«Amparo y f…: la fuerza de Dios.»"},{"pregunta":"¿Qué le pide David a Dios en el Salmo 51, tras reconocer su pecado?","opciones":["Que cree en él un corazón limpio","Que lo haga invisible a sus enemigos","Que le devuelva su reino enseguida","Que borre el recuerdo de todos"],"dato":"Arrepentido, David ora: «Crea en mí, oh Dios, un corazón limpio; y renueva un espíritu recto dentro de mí». Es el gran salmo de arrepentimiento.","cita":"Salmos 51:10","versiculo":"Crea en mí, oh Dios, un corazón limpio; y renueva un espíritu recto dentro de mí.","vcita":"Salmos 51:10","pista":"«Un corazón nuevo y limpio, no un reino nuevo.»"},{"pregunta":"¿Con qué debemos entrar por las puertas de la casa de Dios, según el Salmo 100?","opciones":["Con reconocimiento (acción de gracias)","Con ofrendas de oro","Con silencio absoluto","Con tambores y armas"],"dato":"El Salmo 100 invita a entrar por sus puertas con reconocimiento —esto es, con acción de gracias— y por sus atrios con alabanza.","cita":"Salmos 100:4","versiculo":"Entrad por sus puertas con reconocimiento, por sus atrios con alabanza: alabadle, bendecid su nombre.","vcita":"Salmos 100:4","pista":"«Se entra dando gracias, no de puntillas.»"},{"pregunta":"Completa el Salmo 118: «Este es el día que hizo Jehová; nos ______ y alegraremos en él».","opciones":["gozaremos","descansaremos","lamentaremos","esconderemos"],"dato":"El salmista celebra el día que hizo Jehová como un regalo para gozarse y alegrarse en él.","cita":"Salmos 118:24","versiculo":"Este es el día que hizo Jehová: nos gozaremos y alegraremos en él.","vcita":"Salmos 118:24","pista":"«Nos g… en él: pura alegría.»"},{"pregunta":"¿De dónde viene el socorro del salmista en el Salmo 121?","opciones":["De Jehová, que hizo los cielos y la tierra","De los montes altos","Del ejército de Israel","De los viajeros del camino"],"dato":"El salmista alza sus ojos a los montes y responde: su socorro viene de Jehová, el Creador de los cielos y de la tierra.","cita":"Salmos 121:2","versiculo":"Mi socorro viene de Jehová, que hizo los cielos y la tierra.","vcita":"Salmos 121:2","pista":"«No de los montes: del que hizo los montes.»"},{"pregunta":"Completa el Salmo 122: «Yo me alegré con los que me decían: A la ______ de Jehová iremos».","opciones":["casa","montaña","ciudad","tienda"],"dato":"Es la alegría del peregrino que sube a Jerusalén: «A la casa de Jehová iremos».","cita":"Salmos 122:1","versiculo":"Yo me alegré con los que me decían: A la casa de Jehová iremos.","vcita":"Salmos 122:1","pista":"«A la c… de Jehová iremos.»"}],"Proverbios":[{"pregunta":"¿Cuál es el principio de la sabiduría, según Proverbios?","opciones":["El temor de Jehová","La mucha lectura","La larga experiencia","El consejo de los ricos"],"dato":"Proverbios abre afirmando que el temor de Jehová es el principio de la sabiduría, y que los insensatos desprecian la sabiduría y la enseñanza.","cita":"Proverbios 1:7","versiculo":"El principio de la sabiduría es el temor de Jehová: los insensatos desprecian la sabiduría y la enseñanza.","vcita":"Proverbios 1:7","pista":"«Todo empieza por el temor de Jehová.»"},{"pregunta":"¿En qué no debes apoyarte, según Proverbios 3:5?","opciones":["En tu propia prudencia","En el consejo de tu padre","En la enseñanza de los sabios","En la fuerza de tus amigos"],"dato":"La instrucción es fiarse de Jehová de todo corazón y no estribar en la propia prudencia, reconociéndolo en todos los caminos.","cita":"Proverbios 3:5","versiculo":"Fíate de Jehová de todo tu corazón, y no estribes en tu prudencia.","vcita":"Proverbios 3:5","pista":"«No en tu prudencia: fíate de Jehová.»"},{"pregunta":"Completa el proverbio: «Sobre toda cosa guardada guarda tu ______; porque de él mana la vida».","opciones":["corazón","tesoro","palabra","casa"],"dato":"El corazón es la fuente de la vida: de él manan las decisiones y el carácter, por eso hay que guardarlo sobre todas las cosas.","cita":"Proverbios 4:23","versiculo":"Sobre toda cosa guardada guarda tu corazón; porque de él mana la vida.","vcita":"Proverbios 4:23","pista":"«Guarda tu c…: de él mana la vida.»"},{"pregunta":"¿A qué criatura manda Proverbios al perezoso para que aprenda a ser sabio?","opciones":["A la hormiga","A la abeja","Al buey","A la paloma"],"dato":"La hormiga, sin tener capitán ni gobernador, prepara su comida en el verano: un ejemplo de diligencia para el perezoso.","cita":"Proverbios 6:6","versiculo":"Ve a la hormiga, oh perezoso, mira sus caminos, y sé sabio;","vcita":"Proverbios 6:6","pista":"«La que trabaja sin jefe, preparando el verano.»"},{"pregunta":"¿Qué cubrirá todas las faltas, según Proverbios 10?","opciones":["La caridad (el amor)","El silencio","El olvido","El dinero"],"dato":"El odio despierta rencillas, pero la caridad —el amor— cubre todas las faltas en lugar de exponerlas.","cita":"Proverbios 10:12","versiculo":"El odio despierta rencillas: mas la caridad cubrirá todas las faltas.","vcita":"Proverbios 10:12","pista":"«Lo contrario del odio que despierta rencillas.»"},{"pregunta":"¿Qué quita la ira, según Proverbios 15?","opciones":["La blanda respuesta","El grito más fuerte","La amenaza","El silencio orgulloso"],"dato":"La blanda respuesta quita la ira, mas la palabra áspera hace subir el furor: la mansedumbre apaga el conflicto.","cita":"Proverbios 15:1","versiculo":"La blanda respuesta quita la ira: mas la palabra áspera hace subir el furor.","vcita":"Proverbios 15:1","pista":"«Respuesta blanda, no palabra áspera.»"},{"pregunta":"¿Qué va antes del quebrantamiento y de la caída, según Proverbios 16?","opciones":["La soberbia y la altivez de espíritu","La pobreza","La enfermedad","La vejez"],"dato":"Antes del quebrantamiento es la soberbia, y antes de la caída la altivez de espíritu: el orgullo anuncia la ruina.","cita":"Proverbios 16:18","versiculo":"Antes del quebrantamiento es la soberbia; y antes de la caída la altivez de espíritu.","vcita":"Proverbios 16:18","pista":"«Soberbia primero… caída después.»"},{"pregunta":"Completa el proverbio: «En todo tiempo ama el ______; y el hermano para la angustia es nacido».","opciones":["amigo","vecino","rey","siervo"],"dato":"El amigo ama en todo tiempo, no solo en la prosperidad; y el hermano muestra su valor en la angustia.","cita":"Proverbios 17:17","versiculo":"En todo tiempo ama el amigo; y el hermano para la angustia es nacido.","vcita":"Proverbios 17:17","pista":"«El que ama en todo tiempo: el a…»"},{"pregunta":"¿A qué se compara el nombre de Jehová en Proverbios 18?","opciones":["A una torre fuerte","A un río caudaloso","A una roca en el desierto","A un escudo de bronce"],"dato":"Torre fuerte es el nombre de Jehová: a él corre el justo y queda a salvo, como quien se refugia en una fortaleza.","cita":"Proverbios 18:10","versiculo":"Torre fuerte es el nombre de Jehová: a él correrá el justo, y será levantado.","vcita":"Proverbios 18:10","pista":"«El justo corre a ella como a una fortaleza.»"},{"pregunta":"Completa el proverbio: «Instruye al ______ en su carrera: aun cuando fuere viejo no se apartará de ella».","opciones":["niño","discípulo","pueblo","aprendiz"],"dato":"La formación temprana marca el rumbo de la vida: instruye al niño en su camino y, aun cuando fuere viejo, no se apartará de él.","cita":"Proverbios 22:6","versiculo":"Instruye al niño en su carrera: aun cuando fuere viejo no se apartará de ella.","vcita":"Proverbios 22:6","pista":"«Al n… en su camino, desde pequeño.»"},{"pregunta":"¿Con qué se aguza el hierro, según Proverbios 27?","opciones":["Con hierro","Con piedra","Con fuego","Con agua"],"dato":"Hierro con hierro se aguza; y así el hombre aguza el rostro de su amigo: los amigos se perfeccionan mutuamente.","cita":"Proverbios 27:17","versiculo":"Hierro con hierro se aguza; y el hombre aguza el rostro de su amigo.","vcita":"Proverbios 27:17","pista":"«Hierro con h… se aguza.»"},{"pregunta":"El valor de la mujer fuerte de Proverbios 31 sobrepasa largamente al de…","opciones":["Las piedras preciosas","El oro fino","Las perlas del mar","Los tesoros de Egipto"],"dato":"El capítulo final de Proverbios describe a la mujer fuerte y temerosa de Dios: su estima sobrepuja largamente a las piedras preciosas.","cita":"Proverbios 31:10","versiculo":"Mujer fuerte, ¿quién la hallará? porque su estima sobrepuja largamente a las piedras preciosas.","vcita":"Proverbios 31:10","pista":"«Más valiosa que las piedras preciosas.»"}],"Eclesiastés":[{"pregunta":"¿Cómo se llama a sí mismo el autor de Eclesiastés, hijo de David y rey en Jerusalén?","opciones":["El Predicador","El Profeta","El Cantor","El Escriba"],"dato":"El libro abre con las palabras del Predicador, hijo de David, rey en Jerusalén: tradicionalmente, Salomón reflexionando sobre el sentido de la vida.","cita":"Eclesiastés 1:1","versiculo":"Palabras del Predicador, hijo de David, rey en Jerusalem.","vcita":"Eclesiastés 1:1","pista":"«Se llama a sí mismo 'el P…'.»"},{"pregunta":"¿Cuál es la frase que el Predicador repite al abrir su discurso?","opciones":["Vanidad de vanidades; todo es vanidad","El tiempo vuela y no vuelve","Come, bebe y gózate","Acuérdate de tu Criador"],"dato":"«Vanidad de vanidades» es el latido de todo el libro: sin Dios, todo esfuerzo humano es humo que se disipa.","cita":"Eclesiastés 1:2","versiculo":"Vanidad de vanidades, dijo el Predicador; vanidad de vanidades, todo vanidad.","vcita":"Eclesiastés 1:2","pista":"«Todo es v…: su frase bandera.»"},{"pregunta":"Completa Eclesiastés 1: «…y nada hay ______ debajo del sol».","opciones":["nuevo","eterno","oculto","perfecto"],"dato":"Lo que fue, eso será; lo que se hizo, eso se hará: la historia humana gira en círculos debajo del sol.","cita":"Eclesiastés 1:9","versiculo":"¿Qué es lo que fue? Lo mismo que será. ¿Qué es lo que ha sido hecho? Lo mismo que se hará: y nada hay nuevo debajo del sol.","vcita":"Eclesiastés 1:9","pista":"«Nada hay n… debajo del sol.»"},{"pregunta":"Completa Eclesiastés 3: «Para todas las cosas hay sazón, y todo lo que se quiere debajo del cielo tiene su ______».","opciones":["tiempo","premio","dueño","final"],"dato":"El famoso poema de los tiempos: cada cosa debajo del cielo tiene su sazón y su momento señalado.","cita":"Eclesiastés 3:1","versiculo":"Para todas las cosas hay sazón, y todo lo que se quiere debajo del cielo, tiene su tiempo:","vcita":"Eclesiastés 3:1","pista":"«Todo tiene su t…»"},{"pregunta":"Según el poema de Eclesiastés 3, hay «tiempo de nacer, y tiempo de ______».","opciones":["morir","plantar","llorar","callar"],"dato":"El poema recorre la vida en pares: tiempo de nacer y tiempo de morir, tiempo de plantar y tiempo de arrancar lo plantado.","cita":"Eclesiastés 3:2","versiculo":"Tiempo de nacer, y tiempo de morir; tiempo de plantar, y tiempo de arrancar lo plantado;","vcita":"Eclesiastés 3:2","pista":"«Nacer… y m…: el par de la vida.»"},{"pregunta":"Completa Eclesiastés 4: «Mejores son ______ que uno; porque tienen mejor paga de su trabajo».","opciones":["dos","tres","muchos","diez"],"dato":"Dos valen más que uno: se ayudan a levantarse y se defienden mutuamente; la compañía multiplica la recompensa del trabajo.","cita":"Eclesiastés 4:9","versiculo":"Mejores son dos que uno; porque tienen mejor paga de su trabajo.","vcita":"Eclesiastés 4:9","pista":"«Mejores son d… que uno.»"},{"pregunta":"¿Qué no se rompe pronto, según Eclesiastés 4?","opciones":["El cordón de tres dobleces","La cadena de hierro","La cuerda de lino","El arco del valiente"],"dato":"Si uno es vencido, dos resisten; y cordón de tres dobleces no presto se rompe: una imagen de la fuerza de la unidad.","cita":"Eclesiastés 4:12","versiculo":"Y si alguno prevaleciere contra el uno, dos estarán contra él; y cordón de tres dobleces no presto se rompe.","vcita":"Eclesiastés 4:12","pista":"«Tres dobleces: casi imposible de romper.»"},{"pregunta":"¿Qué es mejor que el buen ungüento, según Eclesiastés 7?","opciones":["La buena fama","El mucho oro","La larga vida","El palacio hermoso"],"dato":"Mejor es la buena fama que el buen ungüento: el buen nombre perfuma la vida entera y permanece aun después de la muerte.","cita":"Eclesiastés 7:1","versiculo":"Mejor es la buena fama que el buen ungüento; y el día de la muerte que el día del nacimiento.","vcita":"Eclesiastés 7:1","pista":"«La buena f… vale más que el perfume.»"},{"pregunta":"¿Cómo debemos hacer todo lo que venga a nuestra mano, según Eclesiastés 9?","opciones":["Con todas nuestras fuerzas","Sin prisa ni afán","Solo si hay testigos","Esperando mejor tiempo"],"dato":"Todo lo que te viniere a la mano para hacer, hazlo según tus fuerzas, porque en el sepulcro no hay obra, ni industria, ni ciencia, ni sabiduría.","cita":"Eclesiastés 9:10","versiculo":"Todo lo que te viniere a la mano para hacer, hazlo según tus fuerzas; porque en el sepulcro, adonde tú vas, no hay obra, ni industria, ni ciencia, ni sabiduría.","vcita":"Eclesiastés 9:10","pista":"«Hazlo según tus f…: con todo tu empeño.»"},{"pregunta":"¿De quién debemos acordarnos en los días de la juventud, según Eclesiastés 12?","opciones":["De nuestro Criador","Solo de nuestros padres","De los días de fiesta","De nuestros enemigos"],"dato":"El consejo final a los jóvenes: acuérdate de tu Criador en los días de tu juventud, antes que vengan los malos días.","cita":"Eclesiastés 12:1","versiculo":"Y acuérdate de tu Criador en los días de tu juventud, antes que vengan los malos días, y lleguen los años, de los cuales digas: No tengo en ellos contentamiento;","vcita":"Eclesiastés 12:1","pista":"«De tu C…: acuérdate de él siendo joven.»"},{"pregunta":"¿Cuál es la conclusión de todo el discurso en Eclesiastés?","opciones":["Teme a Dios, y guarda sus mandamientos","Disfruta la vida sin pensar en nada","Busca riquezas y honor","Apartarse de todo el mundo"],"dato":"El fin de todo el discurso oído es este: teme a Dios y guarda sus mandamientos, porque esto es el todo del hombre.","cita":"Eclesiastés 12:13","versiculo":"El fin de todo el discurso oído es este: Teme a Dios, y guarda sus mandamientos; porque esto es el todo del hombre.","vcita":"Eclesiastés 12:13","pista":"«Teme a Dios y guarda sus m…»"}],"Cantares":[{"pregunta":"¿A quién se atribuye el Cantar de los Cantares, «la canción de canciones»?","opciones":["A Salomón","A David","A Asaf","A Moisés"],"dato":"El libro se presenta como la canción de canciones de Salomón: el más hermoso de los cantos, dedicado al amor.","cita":"Cantares 1:1","versiculo":"Canción de canciones, la cual es de Salomón.","vcita":"Cantares 1:1","pista":"«El rey sabio, hijo de David.»"},{"pregunta":"¿Cómo se describe a sí misma la amada en Cantares 1?","opciones":["Morena soy, mas codiciable","Blanca como la luna llena","Rubia como el trigo maduro","Alta como las palmeras"],"dato":"La amada dice a las hijas de Jerusalén: «Morena soy, mas codiciable», como las cabañas de Cedar y las tiendas de Salomón.","cita":"Cantares 1:5","versiculo":"Morena soy, oh hijas de Jerusalem, mas codiciable; como las cabañas de Cedar, como las tiendas de Salomón.","vcita":"Cantares 1:5","pista":"«Morena… mas codiciable.»"},{"pregunta":"¿Cómo se describe la amada en Cantares 2:1?","opciones":["La rosa de Sarón y el lirio de los valles","La paloma de las hendiduras","La torre de marfil","La estrella de la mañana"],"dato":"«Yo soy la rosa de Sarón, y el lirio de los valles»: la amada se presenta con la belleza sencilla de las flores del campo.","cita":"Cantares 2:1","versiculo":"Yo soy la rosa de Sarón, y el lirio de los valles.","vcita":"Cantares 2:1","pista":"«Una flor de Sarón y un lirio.»"},{"pregunta":"¿Qué no se debe despertar ni hacer velar «hasta que quiera», según el estribillo de Cantares?","opciones":["Al amor","Al rey","A las doncellas","Al invierno"],"dato":"Tres veces se repite el estribillo: «No despertéis ni hagáis velar al amor, hasta que quiera»: el amor tiene su propio tiempo.","cita":"Cantares 2:7","versiculo":"Yo os conjuro, oh doncellas de Jerusalem, por las gamas y por las ciervas del campo, que no despertéis ni hagáis velar al amor, hasta que quiera.","vcita":"Cantares 2:7","pista":"«No despiertes al a… hasta que quiera.»"},{"pregunta":"¿Qué ha pasado ya, según el amado cuando invita a salir a su amada en Cantares 2?","opciones":["El invierno","La noche","La siega","El exilio"],"dato":"«He aquí ha pasado el invierno, la lluvia se fue»: llegó la primavera, el tiempo de los cantos y de las flores.","cita":"Cantares 2:11","versiculo":"Porque he aquí ha pasado el invierno, se ha mudado, la lluvia se fue;","vcita":"Cantares 2:11","pista":"«Pasó el i…: llegó la primavera.»"},{"pregunta":"¿Qué animales pequeños echan a perder las viñas en flor, en Cantares 2?","opciones":["Las zorras pequeñas","Las langostas","Los cuervos","Las hormigas"],"dato":"«Cazadnos las zorras, las zorras pequeñas, que echan a perder las viñas»: los pequeños descuidos arruinan el amor que florece.","cita":"Cantares 2:15","versiculo":"Cazadnos las zorras, las zorras pequeñas, que echan a perder las viñas; pues que nuestras viñas están en cierne.","vcita":"Cantares 2:15","pista":"«Zorras p…: pequeñas pero dañinas.»"},{"pregunta":"Completa Cantares 2: «Mi amado es mío, y yo ______; él apacienta entre lirios».","opciones":["suya","su sierva","su corona","su viña"],"dato":"Es la declaración de pertenencia mutua: «Mi amado es mío, y yo suya», mientras él apacienta entre los lirios.","cita":"Cantares 2:16","versiculo":"Mi amado es mío, y yo suya; él apacienta entre lirios.","vcita":"Cantares 2:16","pista":"«Mi amado es mío, y yo s…»"},{"pregunta":"¿A quién buscó la amada en su lecho por las noches, sin hallarlo?","opciones":["Al que ama su alma","A su hermano menor","Al rey en su palacio","A las guardas de la ciudad"],"dato":"«Por las noches busqué en mi lecho al que ama mi alma: busquélo, y no lo hallé»; entonces se levantó a buscarlo por la ciudad.","cita":"Cantares 3:1","versiculo":"Por las noches busqué en mi lecho al que ama mi alma: busquélo, y no lo hallé.","vcita":"Cantares 3:1","pista":"«Al que ama su a…»"},{"pregunta":"¿Qué afirma el amado de su amada en Cantares 4:7?","opciones":["Toda tú eres hermosa, y en ti no hay mancha","Eres fuerte como un ejército","Eres sabia como una reina","Eres alta como los cedros"],"dato":"El amado la contempla entera: «Toda tú eres hermosa, amiga mía, y en ti no hay mancha».","cita":"Cantares 4:7","versiculo":"Toda tú eres hermosa, amiga mía, y en ti no hay mancha.","vcita":"Cantares 4:7","pista":"«Sin mancha: toda h…»"},{"pregunta":"¿Cómo llama el amado a su amada, única para él, en Cantares 6?","opciones":["Mi paloma, mi perfecta","Mi rosa, mi estrella","Mi torre, mi escudo","Mi viña, mi huerto"],"dato":"Entre reinas y concubinas, una sola es su paloma y su perfecta, la única de su madre, y todas la llaman bienaventurada.","cita":"Cantares 6:9","versiculo":"Mas una es la paloma mía, la perfecta mía; única es a su madre, escogida a la que la engendró.","vcita":"Cantares 6:9","pista":"«Su paloma, su p…»"},{"pregunta":"¿Como qué pide la amada ser puesta sobre el corazón y el brazo de su amado?","opciones":["Como un sello","Como una joya","Como una corona","Como un anillo de oro"],"dato":"«Ponme como un sello sobre tu corazón, como una marca sobre tu brazo: porque fuerte es como la muerte el amor».","cita":"Cantares 8:6","versiculo":"Ponme como un sello sobre tu corazón, como una marca sobre tu brazo: porque fuerte es como la muerte el amor; duro como el sepulcro el celo: sus brasas, brasas de fuego, fuerte llama.","vcita":"Cantares 8:6","pista":"«Como un s… sobre el corazón.»"},{"pregunta":"¿Qué no podrán apagar las muchas aguas, según Cantares 8?","opciones":["El amor","La fe","La esperanza","La alegría"],"dato":"Las muchas aguas no podrán apagar el amor, ni lo ahogarán los ríos: el amor verdadero no se compra ni se destruye.","cita":"Cantares 8:7","versiculo":"Las muchas aguas no podrán apagar el amor, ni lo ahogarán los ríos.","vcita":"Cantares 8:7","pista":"«Ni los ríos lo ahogan: el a…»"}],"Isaías":[{"pregunta":"¿Con qué tocó el serafín los labios de Isaías para quitar su culpa en la visión del templo?","opciones":["Con un carbón encendido tomado del altar","Con ceniza mezclada con agua bendita","Con una piedra caliente del incensario","Con el borde de su manto"],"dato":"Uno de los serafines voló a Isaías con un carbón encendido en la mano, tomado del altar con unas tenazas, y al tocar su boca declaró quitada su culpa.","cita":"Isaías 6:6–7","versiculo":"Y tocando con él sobre mi boca, dijo: He aquí que esto tocó tus labios, y es quitada tu culpa, y limpio tu pecado.","vcita":"Isaías 6:7","pista":"«Vino volando desde el altar, con tenazas en la mano.»"},{"pregunta":"Según Isaías 7, ¿qué nombre se le daría al hijo que nacería de la virgen?","opciones":["Emmanuel","Maher-salal-hash-baz","Príncipe de paz","Lo-ammi"],"dato":"La señal dada al rey Acaz: la virgen concebiría y daría a luz un hijo llamado Emmanuel, que significa «Dios con nosotros».","cita":"Isaías 7:14","versiculo":"Por tanto el mismo Señor os dará señal: He aquí que la virgen concebirá, y parirá hijo, y llamará su nombre Emmanuel.","vcita":"Isaías 7:14","pista":"«Su nombre significa: Dios con nosotros.»"},{"pregunta":"¿Cómo mandó Dios llamar al hijo que le nació a Isaías con la profetisa?","opciones":["Maher-salal-hash-baz","Sear-jasub","Emmanuel","Jezreel"],"dato":"El nombre era una señal profética: Maher-salal-hash-baz significa «el despojo se apresura, la presa se precipita», anunciando la pronta caída de Damasco y Samaria.","cita":"Isaías 8:3","versiculo":"Y juntéme con la profetisa, la cual concibió, y parió un hijo. Y díjome Jehová: Ponle por nombre Maher-salal-hash-baz.","vcita":"Isaías 8:3","pista":"«Es casi un trabalenguas: habla de un botín que vuela.»"},{"pregunta":"¿Cuál de estos títulos dio Isaías al niño que nacería, en el capítulo 9?","opciones":["Príncipe de paz","Rey de reyes","Buen Pastor","Estrella resplandeciente de la mañana"],"dato":"Admirable, Consejero, Dios fuerte, Padre eterno y Príncipe de paz: los títulos del niño de Isaías 9, cuyo principado y paz no tendrían fin.","cita":"Isaías 9:6","versiculo":"Porque un niño nos es nacido, hijo nos es dado; y el principado sobre su hombro: y llamaráse su nombre Admirable, Consejero, Dios fuerte, Padre eterno, Príncipe de paz.","vcita":"Isaías 9:6","pista":"«Su gobierno trae lo que el mundo más busca: termina en paz.»"},{"pregunta":"En el cántico de Isaías 14, ¿contra quién va dirigido el dicho del «Lucero, hijo de la mañana» que cayó del cielo?","opciones":["Contra el rey de Babilonia","Contra el faraón de Egipto","Contra el rey de Tiro","Contra Senaquerib de Asiria"],"dato":"El capítulo 14 es una burla profética contra el rey de Babilonia: el «Lucero» que quiso subir sobre las estrellas de Dios. La tradición lo ha leído también como figura de la caída de Satanás.","cita":"Isaías 14:12","versiculo":"¡Cómo caíste del cielo, oh Lucero, hijo de la mañana! Cortado fuiste por tierra, tú que debilitabas las gentes.","vcita":"Isaías 14:12","pista":"«El capítulo empieza diciendo: «dirás este refrán contra el rey de…».»"},{"pregunta":"¿Cuántos años añadió Dios a la vida del rey Ezequías después de su oración con lágrimas?","opciones":["Quince años","Diez años","Siete años","Veinte años"],"dato":"Ezequías enfermó de muerte, oró y lloró con gran llanto; Dios le añadió quince años y le dio por señal que la sombra del reloj retrocedería diez grados.","cita":"Isaías 38:5","versiculo":"Ve, y di a Ezequías: Jehová Dios de David tu padre dice así: Tu oración he oído, y visto tus lágrimas: he aquí que yo añado a tus días quince años.","vcita":"Isaías 38:5","pista":"«Diez grados retrocedió la sombra; los años fueron diez más cinco.»"},{"pregunta":"Según Isaías 40, ¿como qué animales levantarán las alas los que esperan a Jehová?","opciones":["Como las águilas","Como las palomas","Como los cuervos","Como las golondrinas"],"dato":"Los que esperan a Jehová tendrán nuevas fuerzas: correrán sin cansarse y caminarán sin fatigarse.","cita":"Isaías 40:31","versiculo":"Mas los que esperan a Jehová tendrán nuevas fuerzas; levantarán las alas como águilas; correrán, y no se cansarán; caminarán, y no se fatigarán.","vcita":"Isaías 40:31","pista":"«El ave que vuela más alto sin batir casi las alas.»"}],"Jeremías":[{"pregunta":"¿Qué hizo Dios cuando llamó a Jeremías, para darle autoridad a su palabra?","opciones":["Le tocó la boca y puso sus palabras en ella","Le entregó un rollo para que se lo comiera","Lo ungió con aceite delante de los ancianos","Le dio una vara de hierro"],"dato":"Jeremías se excusaba diciendo que era un niño y no sabía hablar; Jehová extendió su mano, tocó su boca y puso en ella sus palabras.","cita":"Jeremías 1:9","versiculo":"Y extendió Jehová su mano, y tocó sobre mi boca; y díjome Jehová: He aquí he puesto mis palabras en tu boca.","vcita":"Jeremías 1:9","pista":"«El profeta decía: “no sé hablar, porque soy un niño”.»"},{"pregunta":"¿Qué fue lo primero que vio Jeremías en visión al comenzar su ministerio?","opciones":["Una vara de almendro","Una vara de olivo en flor","Una higuera con dos cestos","Un rollo escrito por ambos lados"],"dato":"Dios le mostró una vara de almendro y explicó el juego de palabras: «Bien has visto; porque yo apresuro mi palabra para ponerla por obra».","cita":"Jeremías 1:11","versiculo":"Y la palabra de Jehová fue a mí, diciendo: ¿Qué ves tú, Jeremías? Y dije: Yo veo una vara de almendro.","vcita":"Jeremías 1:11","pista":"«Es el árbol que florece primero, como si “velara” sobre la palabra.»"},{"pregunta":"¿A la casa de quién envió Dios a Jeremías para enseñarle la lección del barro echado a perder y vuelto a hacer?","opciones":["A la casa del alfarero","A la casa del herrero","A la casa del tejedor","A la casa del escriba"],"dato":"En la rueda del alfarero, la vasija de barro se echó a perder y él la volvió a hacer: así es Israel en la mano de Dios, dice Jehová.","cita":"Jeremías 18:3","versiculo":"Y descendí a casa del alfarero, y he aquí que él hacía obra sobre la rueda.","vcita":"Jeremías 18:3","pista":"«Trabaja con barro y una rueda que gira.»"},{"pregunta":"¿Por cuánta plata compró Jeremías el campo de su primo Hanameel en Anatot, estando Jerusalén sitiada?","opciones":["Por diecisiete siclos de plata","Por treinta piezas de plata","Por diez siclos de oro","Por cien siclos de plata"],"dato":"Preso en el patio de la cárcel y con la ciudad a punto de caer, Jeremías compró el campo como señal de que «aún se comprarán casas y campos en esta tierra».","cita":"Jeremías 32:9","versiculo":"Y compré la heredad de Hanameel, hijo de mi tío, la cual estaba en Anatot, y peséle el dinero: diecisiete siclos de plata.","vcita":"Jeremías 32:9","pista":"«Diez más siete: se pesó en balanza, moneda por moneda.»"},{"pregunta":"¿Qué se negaban a hacer los recabitas, por el mandato que su antepasado Jonadab les había dejado?","opciones":["Beber vino, ellos y sus hijos, para siempre","Comer pan durante el sitio de la ciudad","Vivir dentro de Jerusalén","Cortarse el cabello como los nazareos"],"dato":"Durante generaciones los recabitas obedecieron a Jonadab hijo de Recab: no bebían vino ni sembraban ni edificaban casas. Dios los puso de ejemplo frente a la desobediencia de Judá.","cita":"Jeremías 35:6","versiculo":"Mas ellos dijeron: No beberemos vino; porque Jonadab hijo de Recab nuestro padre nos mandó, diciendo: No beberéis jamás vino vosotros ni vuestros hijos.","vcita":"Jeremías 35:6","pista":"«Ni una copa, ni ellos ni sus hijos, por generaciones.»"},{"pregunta":"¿Quién escribió en un rollo, al dictado de Jeremías, las palabras que luego el rey Joacim quemó poco a poco?","opciones":["Baruc, hijo de Nerías","Gemarías, hijo de Safán","Elisama, el escriba del rey","Pasur, el sacerdote"],"dato":"Baruc escribió de boca de Jeremías y leyó el rollo en el templo. El rey lo cortó con un cortaplumas y lo fue echando al fuego, pero Jeremías dictó otro rollo con aún más palabras.","cita":"Jeremías 36:4","versiculo":"Y llamó Jeremías a Baruc hijo de Nerías, y escribió Baruc de boca de Jeremías, en un rollo de libro, todas las palabras que Jehová le había hablado.","vcita":"Jeremías 36:4","pista":"«El fiel secretario del profeta llorón.»"},{"pregunta":"¿Quién intercedió ante el rey Sedequías y logró que sacaran a Jeremías de la cisterna donde se hundía en el lodo?","opciones":["Ebed-melec, el etíope","Baruc, hijo de Nerías","Gedalías, el gobernador","Hanameel, el primo del profeta"],"dato":"Ebed-melec, eunuco etíope de la casa del rey, habló por Jeremías y volvió con treinta hombres y trapos viejos para subirlo de la cisterna sin lastimarlo.","cita":"Jeremías 38:7","versiculo":"Y oyendo Ebed-melec, hombre etíope, eunuco que estaba en casa del rey, que habían puesto a Jeremías en la cisterna, y estando sentado el rey a la puerta de Benjamín,","vcita":"Jeremías 38:7","pista":"«Un extranjero de la corte, con nombre que empieza por E.»"},{"pregunta":"La promesa «pensamientos de paz, y no de mal, para daros el fin que esperáis» estaba en una carta de Jeremías dirigida ¿a quiénes?","opciones":["A los israelitas ya deportados en Babilonia","A los sacerdotes que quedaban en Jerusalén","Al rey Ezequías y su corte","A los judíos que huyeron a Egipto"],"dato":"Jeremías escribió desde Jerusalén a los cautivos que Nabucodonosor había llevado a Babilonia, mandándoles edificar casas, plantar huertos y procurar la paz de la ciudad.","cita":"Jeremías 29:11","versiculo":"Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.","vcita":"Jeremías 29:11","pista":"«Los destinatarios ya vivían lejos, junto a los ríos de Babilonia.»"}],"Lamentaciones":[{"pregunta":"¿Cómo describe el primer poema a Jerusalén, la ciudad que antes estaba llena de gente?","opciones":["Como una viuda, sentada sola","Como una reina coronada de oro","Como una novia que espera al esposo","Como una paloma sin nido"],"dato":"«La grande entre las naciones se ha vuelto como viuda»: la ciudad populosa quedó sola y tributaria tras la caída en manos de Babilonia.","cita":"Lamentaciones 1:1","versiculo":"¡Cómo está sentada sola la ciudad populosa! La grande entre las naciones se ha vuelto como viuda, la señora de provincias es hecha tributaria.","vcita":"Lamentaciones 1:1","pista":"«Quedó sola, como quien perdió a su marido.»"},{"pregunta":"«Mirad, y ved si hay dolor como…» ¿qué pregunta la ciudad doliente a todos los que pasan por el camino?","opciones":["Si hay dolor como su dolor","Si hay ciudad más rica que ella","Si alguien recuerda su gloria","Si Dios ya la perdonó"],"dato":"El lamento de Lamentaciones 1 presenta a Jerusalén hablando en primera persona, sin consuelo, en el día de la ira de Jehová.","cita":"Lamentaciones 1:12","versiculo":"¿No os conmueve a cuantos pasáis por el camino? Mirad, y ved si hay dolor como mi dolor que me ha venido; porque Jehová me ha angustiado en el día de la ira de su furor.","vcita":"Lamentaciones 1:12","pista":"«Compara su sufrimiento y no encuentra otro igual.»"},{"pregunta":"¿Quiénes desfallecían en las plazas de la ciudad, según el llanto del capítulo 2?","opciones":["El niño y el que aún mamaba","Los ancianos y las viudas","Los sacerdotes y los levitas","Los soldados heridos en la muralla"],"dato":"El profeta dice que sus ojos desfallecieron de lágrimas por el quebrantamiento de su pueblo: hasta los niños pequeños se desmayaban de hambre en las calles.","cita":"Lamentaciones 2:11","versiculo":"Mis ojos desfallecieron de lágrimas, rugieron mis entrañas, mi hígado se derramó por tierra por el quebrantamiento de la hija de mi pueblo, cuando desfallecía el niño y el que mamaba, en las plazas de la ciudad.","vcita":"Lamentaciones 2:11","pista":"«Los más pequeños, los que todavía tomaban el pecho.»"},{"pregunta":"El capítulo 3 es un acróstico triple — cada letra del alfabeto hebreo abre tres versículos — y es el más largo del libro. ¿Cuántos versículos tiene?","opciones":["66 versículos","22 versículos","44 versículos","50 versículos"],"dato":"Casi todo Lamentaciones está ordenado por las 22 letras hebreas; el capítulo 3 las recorre tres veces: 22 × 3 = 66 versículos, y justo en su centro están las palabras de esperanza más famosas del libro.","cita":"Lamentaciones 3:1","versiculo":"Yo soy el hombre que ha visto aflicción en la vara de su enojo.","vcita":"Lamentaciones 3:1","pista":"«Veintidós letras por tres vueltas: multiplica.»"},{"pregunta":"Según Lamentaciones 3, ¿qué es «grande» y se renueva cada mañana?","opciones":["La fidelidad de Jehová","La paciencia de los sitiados","El número de los sobrevivientes","La muralla reconstruida"],"dato":"En el centro del libro más triste de la Biblia brilla esta confesión: las misericordias de Jehová nunca decayeron; nuevas son cada mañana, y grande es su fidelidad.","cita":"Lamentaciones 3:23","versiculo":"Nuevas son cada mañana; grande es tu fidelidad.","vcita":"Lamentaciones 3:23","pista":"«Empieza con N: nuevas son cada mañana.»"},{"pregunta":"«Mi parte es Jehová, dijo mi alma; por tanto en él esperaré.» ¿Qué dice el profeta que es Jehová para él?","opciones":["Su porción, su parte y herencia","Su juez y su verdugo","Su corona de oro","Su memoria y su olvido"],"dato":"En medio de la ruina, el profeta declara que Jehová mismo es su porción — su herencia — y por eso pone en él su esperanza.","cita":"Lamentaciones 3:24","versiculo":"Mi parte es Jehová, dijo mi alma; por tanto en él esperaré.","vcita":"Lamentaciones 3:24","pista":"«En la versión antigua dice “mi parte”; hoy leemos “mi porción”.»"},{"pregunta":"Según el capítulo 3, ¿qué es «bueno» hacer mientras llega la salvación de Jehová?","opciones":["Esperar callando, en silencio","Gritar contra los enemigos día y noche","Vengarse de los que destruyeron la ciudad","Abandonar la tierra y huir"],"dato":"«Bueno es esperar callando en la salud de Jehová»: en el español antiguo, «salud» significa salvación. La esperanza silenciosa sustituye al lamento desesperado.","cita":"Lamentaciones 3:26","versiculo":"Bueno es esperar callando en la salud de Jehová.","vcita":"Lamentaciones 3:26","pista":"«Sin ruido, sin reclamos: esperar.»"},{"pregunta":"¿A qué invita el profeta a su pueblo en medio del luto, en Lamentaciones 3:40?","opciones":["A escudriñar sus caminos y volverse a Jehová","A contar a los muertos de la ciudad","A jurar venganza contra Babilonia","A dejar de cantar para siempre"],"dato":"El camino de salida del lamento es el arrepentimiento: examinar nuestros caminos, buscar y volvernos a Jehová, levantando corazón y manos hacia Dios.","cita":"Lamentaciones 3:40","versiculo":"Escudriñemos nuestros caminos, y busquemos, y volvámonos a Jehová.","vcita":"Lamentaciones 3:40","pista":"«Primero examinarse por dentro, después regresar.»"},{"pregunta":"¿A qué son comparados los preciosos hijos de Sion después de la caída, según el capítulo 4?","opciones":["A vasos de barro, obra de alfarero","A copas de madera quemada","A piedras rodadas del camino","A cántaros de bronce sin valor"],"dato":"Los hijos de Sion, estimados más que el oro puro, pasaron a ser tenidos por vasijas de barro: la caída cambió por completo su honra.","cita":"Lamentaciones 4:2","versiculo":"Los hijos de Sión, preciados y estimados más que el oro puro, ¡cómo son tenidos por vasos de barro, obra de manos de alfarero!","vcita":"Lamentaciones 4:2","pista":"«De valer más que el oro, a ser frágiles como el barro cocido.»"},{"pregunta":"¿Qué afirma el último poema que «permanecerá para siempre», de generación en generación?","opciones":["Jehová y su trono","El templo de Salomón","La muralla de Jerusalén","El reino de la casa de David"],"dato":"Aunque todo lo demás cayó, el libro termina mirando hacia arriba: «Mas tú, Jehová, permanecerás para siempre: tu trono de generación en generación».","cita":"Lamentaciones 5:19","versiculo":"Mas tú, Jehová, permanecerás para siempre: tu trono de generación en generación.","vcita":"Lamentaciones 5:19","pista":"«La ciudad cayó; el trono de arriba, no.»"},{"pregunta":"¿Cuál es la petición con la que el libro cierra su oración final?","opciones":["«Vuélvenos, oh Jehová, a ti, y nos volveremos»","«Destruye a nuestros enemigos para siempre»","«Olvida nuestros pecados y no nos mires»","«Devuélvenos el reino en este año»"],"dato":"El último capítulo es una oración: pide que Dios los vuelva a él y renueve sus días como al principio, reconociendo que solo Dios puede restaurarlos.","cita":"Lamentaciones 5:21","versiculo":"Vuélvenos, oh Jehová, a ti, y nos volveremos: renueva nuestros días como al principio.","vcita":"Lamentaciones 5:21","pista":"«No piden cosas: piden volver ellos mismos.»"}],"Ezequiel":[{"pregunta":"¿Qué cuatro rostros tenían los seres vivientes de la primera visión de Ezequiel junto al río Quebar?","opciones":["De hombre, de león, de buey y de águila","De hombre, de león, de caballo y de paloma","De león, de buey, de serpiente y de águila","De hombre, de toro, de águila y de querubín alado"],"dato":"Cada ser viviente tenía cuatro rostros y cuatro alas, junto a ruedas llenas de ojos: la visión de la gloria de Jehová que llamó a Ezequiel entre los cautivos de Babilonia.","cita":"Ezequiel 1:10","versiculo":"Y la figura de sus rostros era rostro de hombre; y rostro de león a la parte derecha en los cuatro; y a la izquierda rostro de buey en los cuatro; asimismo había en los cuatro rostro de águila.","vcita":"Ezequiel 1:10","pista":"«Un rey de la selva, un rey del campo y un rey del cielo acompañan al hombre.»"},{"pregunta":"¿A qué le supo a Ezequiel el rollo escrito por ambos lados que Dios le mandó comer?","opciones":["Dulce como miel","Amargo como la hiel","Agrio como el vinagre","Seco como el polvo"],"dato":"El rollo estaba escrito por delante y por detrás con endechas, lamentaciones y ayes; sin embargo, en la boca del profeta fue dulce como la miel.","cita":"Ezequiel 3:3","versiculo":"Y díjome: Hijo de hombre, haz a tu vientre que coma, y llena tus entrañas de este rollo que yo te doy. Y comílo, y fue en mi boca dulce como miel.","vcita":"Ezequiel 3:3","pista":"«Contenía lamentos, pero sabía a panal.»"},{"pregunta":"¿Con qué oficio comisionó Dios a Ezequiel sobre la casa de Israel?","opciones":["Atalaya, el centinela que avisa del peligro","Sumo sacerdote del templo","Escriba mayor del rey","Capitán de la guardia de Jerusalén"],"dato":"Como atalaya, Ezequiel debía oír la palabra de la boca de Dios y amonestar al pueblo: si no avisaba al impío, su sangre sería demandada de su mano.","cita":"Ezequiel 3:17","versiculo":"Hijo de hombre, yo te he puesto por atalaya a la casa de Israel: oirás pues tú la palabra de mi boca, y amonestarlos has de mi parte.","vcita":"Ezequiel 3:17","pista":"«El que vigila desde la torre y toca la alarma.»"},{"pregunta":"¿Cuántos días estuvo Ezequiel acostado sobre su lado izquierdo, llevando simbólicamente la maldad de Israel?","opciones":["390 días","40 días","300 días","430 días"],"dato":"Dios convirtió los años de la maldad de Israel en días para el profeta: 390 sobre el lado izquierdo por Israel, y después 40 por Judá.","cita":"Ezequiel 4:5","versiculo":"Yo te he dado los años de su maldad por el número de los días, trescientos y noventa días: y llevarás la maldad de la casa de Israel.","vcita":"Ezequiel 4:5","pista":"«Casi trece meses: trescientos más noventa. Los 40 eran por Judá.»"},{"pregunta":"¿A quiénes se debía poner la señal en la frente para protegerlos del juicio sobre Jerusalén?","opciones":["A los que gemían y clamaban por las abominaciones de la ciudad","A todos los sacerdotes y levitas","A los niños menores de siete años","A los que ofrecieran sacrificio esa mañana"],"dato":"Antes de que salieran los destructores, un varón con tintero de escribano marcó la frente de los que se dolían por el pecado de la ciudad: solo ellos serían guardados.","cita":"Ezequiel 9:4","versiculo":"Y díjole Jehová: Pasa por medio de la ciudad, por medio de Jerusalén, y pon una señal en la frente a los hombres que gimen y que claman a causa de todas las abominaciones que se hacen en medio de ella.","vcita":"Ezequiel 9:4","pista":"«No los poderosos: los que lloraban por el pecado ajeno.»"},{"pregunta":"¿Qué le anunció Dios a Ezequiel que le quitaría «de golpe», ordenándole no hacer duelo público?","opciones":["El deleite de sus ojos: su esposa","A su hijo primogénito","Su casa junto al río Quebar","El rollo de sus profecías"],"dato":"La esposa de Ezequiel murió al atardecer y a la mañana él hizo como se le mandó, sin llorar ni cubrirse: era una señal para Israel de que Dios profanaría el santuario, el deleite de sus ojos, sin que pudieran lamentarse.","cita":"Ezequiel 24:16","versiculo":"Hijo de hombre, he aquí que yo te quito de golpe el deseo de tus ojos: no endeches, ni llores, ni corran tus lágrimas.","vcita":"Ezequiel 24:16","pista":"«Lo más amado que tenía en casa.»"},{"pregunta":"En el capítulo contra los pastores infieles, ¿qué promete hacer Dios mismo con la oveja perdida y la quebrada?","opciones":["Buscar a la perdida y ligar a la perniquebrada","Dejarla hasta que aprenda a volver sola","Entregarla a otros pastores humanos","Marcarla y apartarla del rebaño"],"dato":"Los pastores de Israel se apacentaban a sí mismos; por eso Dios anuncia que él mismo buscará a la perdida, traerá a la descarriada, vendará a la quebrada y fortalecerá a la enferma.","cita":"Ezequiel 34:16","versiculo":"Yo buscaré la perdida, y tornaré la amontada, y ligaré la perniquebrada, y corroboraré la enferma: mas a la gruesa y a la fuerte destruiré. Yo las apacentaré en juicio.","vcita":"Ezequiel 34:16","pista":"«El Pastor verdadero hace el turno que los otros no hicieron.»"},{"pregunta":"¿Qué corazón promete quitar Dios y qué corazón promete dar en Ezequiel 36?","opciones":["Quita el corazón de piedra y da uno de carne","Quita el de carne y da uno de piedra","Quita el de barro y da uno de oro","Quita el de niño y da uno de anciano"],"dato":"Junto al corazón nuevo, Dios promete poner su Espíritu dentro de su pueblo y rociar agua limpia sobre ellos: es la gran promesa de renovación de Ezequiel 36.","cita":"Ezequiel 36:26","versiculo":"Y os daré corazón nuevo, y pondré espíritu nuevo dentro de vosotros; y quitaré de vuestra carne el corazón de piedra, y os daré corazón de carne.","vcita":"Ezequiel 36:26","pista":"«Fuera lo duro e insensible; dentro, uno vivo que siente.»"},{"pregunta":"¿Qué enseña Ezequiel 18, contra el refrán de que los hijos pagan por los pecados de los padres?","opciones":["Que el alma que pecare, esa morirá: cada quien responde por su propio pecado","Que los hijos siempre pagan por los padres","Que el justo salva automáticamente a toda su casa","Que el pecado se hereda por tres generaciones"],"dato":"Israel repetía: «Los padres comieron las uvas agrias, y los dientes de los hijos tienen la dentera». Dios responde que todas las almas son suyas y que el hijo no llevará el pecado del padre.","cita":"Ezequiel 18:20","versiculo":"El alma que pecare, esa morirá: el hijo no llevará por el pecado del padre, ni el padre llevará por el pecado del hijo: la justicia del justo será sobre él, y la impiedad del impío será sobre él.","vcita":"Ezequiel 18:20","pista":"«Nada de culpas heredadas: cuentas personales.»"},{"pregunta":"¿Qué sucede dondequiera que llega el río que sale del santuario, en la visión del capítulo 47?","opciones":["Todo vive: hasta las aguas del mar reciben sanidad","Las aguas se secan y queda sal","El río se divide en siete brazos secos","Los peces mueren por la corriente"],"dato":"El arroyo que nace bajo el umbral del templo crece hasta ser un río que no se puede vadear; donde entra, el mar se sana y se llena de peces, y a sus orillas crecen árboles cuyas hojas son medicina.","cita":"Ezequiel 47:9","versiculo":"Y será que toda alma viviente que nadare por dondequiera que entraren estos dos arroyos, vivirá: y habrá muy muchos peces por haber entrado allá estas aguas, y recibirán sanidad; y vivirá todo lo que entrare en este arroyo.","vcita":"Ezequiel 47:9","pista":"«Llega hasta el mar Muerto… y lo vuelve vivo.»"}],"Daniel":[{"pregunta":"¿Qué nombre nuevo puso el príncipe de los eunucos a Daniel en Babilonia?","opciones":["Beltsasar","Sadrac","Mesac","Abed-nego"],"dato":"A los cuatro jóvenes hebreos les cambiaron los nombres: Daniel recibió Beltsasar; Ananías, Sadrac; Misael, Mesac; y Azarías, Abed-nego.","cita":"Daniel 1:7","versiculo":"A los cuales el príncipe de los eunucos puso nombres: y puso a Daniel, Beltsasar; y a Ananías, Sadrac; y a Misael, Mesac; y a Azarías, Abed-nego.","vcita":"Daniel 1:7","pista":"«El suyo empieza con B, parecido a un rey de Babilonia.»"},{"pregunta":"¿Qué dieta pidió Daniel para él y sus amigos en la prueba de diez días en el palacio?","opciones":["Legumbres para comer y agua para beber","Solo pan sin levadura y frutas","Pescado y miel una vez al día","La misma comida del rey, pero en ayunas"],"dato":"Daniel propuso no contaminarse con la comida del rey: diez días de legumbres y agua. Al final, su semblante era mejor y más robusto que el de los demás jóvenes.","cita":"Daniel 1:12","versiculo":"Prueba, te ruego, tus siervos diez días, y dennos legumbres a comer, y agua a beber.","vcita":"Daniel 1:12","pista":"«Nada de la mesa del rey: lo sencillo del campo y agua clara.»"},{"pregunta":"¿Qué parte de la gran estatua del sueño de Nabucodonosor representaba al propio rey, según Daniel?","opciones":["La cabeza de oro","El pecho de plata","El vientre de bronce","Los pies de hierro y barro cocido"],"dato":"Daniel le dijo cara a cara: «tú eres aquella cabeza de oro». La estatua anunciaba una sucesión de reinos, cada metal menos valioso que el anterior.","cita":"Daniel 2:38","versiculo":"Y todo lo que habitan hijos de hombres, bestias del campo, y aves del cielo, él ha entregado en tu mano, y te ha hecho enseñorear sobre todo ello: tú eres aquella cabeza de oro.","vcita":"Daniel 2:38","pista":"«El metal más valioso, en lo más alto de la estatua.»"},{"pregunta":"Cuando Nabucodonosor miró dentro del horno de fuego, ¿cómo describió al cuarto varón que caminaba con los tres jóvenes?","opciones":["Semejante a un hijo de los dioses","Como un anciano de días sentado en un trono","Como un ángel con una espada de fuego","Como un cuarto prisionero que pedía auxilio"],"dato":"Solo tres hombres habían sido echados amarrados al horno, pero el rey vio a cuatro sueltos y sin daño; por eso mandó salir a Sadrac, Mesac y Abed-nego y bendijo a su Dios.","cita":"Daniel 3:25","versiculo":"Respondió él y dijo: He aquí que yo veo cuatro varones sueltos, que se pasean en medio del fuego, y ningún daño hay en ellos: y el parecer del cuarto es semejante a hijo de los dioses.","vcita":"Daniel 3:25","pista":"«Echaron a tres… y el rey contó cuatro.»"},{"pregunta":"En la visión del carnero y el macho cabrío, ¿qué rey representa el macho cabrío, según la explicación de Gabriel?","opciones":["El rey de Grecia (Javán)","El rey de Persia","El rey de Babilonia","El rey de Egipto"],"dato":"Javán es el nombre hebreo de Grecia: el carnero de dos cuernos eran los reyes de Media y Persia, y el macho cabrío que lo derribó, el reino griego cuyo cuerno grande sería su primer rey.","cita":"Daniel 8:21","versiculo":"Y el macho cabrío es el rey de Javán: y el cuerno grande que tenía entre sus ojos es el rey primero.","vcita":"Daniel 8:21","pista":"«Javán, en la Biblia, es el nombre de Grecia.»"}],"Oseas":[{"pregunta":"¿Cómo se llamaba la mujer con la que Dios mandó casarse a Oseas como señal para Israel?","opciones":["Gomer","Jezabel","Atalía","Vasti"],"dato":"Dios ordenó a Oseas tomar por esposa a Gomer, hija de Diblaim, como señal viviente de la infidelidad de Israel y del amor persistente de Dios.","cita":"Oseas 1:2–3","versiculo":"Fué pues, y tomó á Gomer hija de Diblaim, la cual concibió y le parió un hijo.","vcita":"Oseas 1:3","pista":"«Su historia está en el primer capítulo; su esposo tuvo que ir a buscarla otra vez.»"},{"pregunta":"¿Qué nombre puso Oseas a su primer hijo, por orden de Dios?","opciones":["Jezreel","Lo-ammi","Maher-salal-hasbaz","Sear-jasub"],"dato":"El primogénito se llamó Jezreel: Dios anunció que castigaría la casa de Jehú por las sangres derramadas en Jezreel y haría cesar el reino de la casa de Israel.","cita":"Oseas 1:4","versiculo":"Y díjole Jehová: Ponle por nombre Jezreel; porque de aquí á poco yo visitaré las sangres de Jezreel sobre la casa de Jehú, y haré cesar el reino de la casa de Israel.","vcita":"Oseas 1:4","pista":"«Lleva el nombre de un valle famoso por las batallas de Israel.»"},{"pregunta":"¿Qué significa el nombre «Lo-ammi», que Oseas puso a su tercer hijo?","opciones":["«No pueblo mío»","«No compadecida»","«Dios siembra»","«El Señor juzga»"],"dato":"Lo-ammi significa literalmente «no mi pueblo»: era la sentencia de Dios sobre Israel, que había roto el pacto. Su hermana se llamó Lo-ruhama, «no compadecida».","cita":"Oseas 1:9","versiculo":"Y dijo [Dios]: Ponle por nombre Lo-ammi: porque vosotros no sois mi pueblo, ni yo seré vuestro [Dios].","vcita":"Oseas 1:9","pista":"«El nombre es una frase hebrea que niega la relación entre Dios y su pueblo.»"},{"pregunta":"¿Con qué compró Oseas de nuevo a su esposa infiel, como símbolo del rescate de Israel?","opciones":["Quince piezas de plata y cebada","Treinta piezas de plata","Un talento de oro","Cien corderos"],"dato":"Oseas la compró por quince piezas de plata y un homer y medio de cebada: una imagen de cómo Dios rescata a su pueblo infiel pagando el precio.","cita":"Oseas 3:2","versiculo":"Compréla entonces para mí por quince [dineros] de plata, y un homer y medio de cebada;","vcita":"Oseas 3:2","pista":"«Pagó mitad en monedas y mitad en grano, como el precio de una esclava.»"},{"pregunta":"Según Oseas 4, ¿por qué fue destruido el pueblo de Dios?","opciones":["Porque le faltó conocimiento","Porque perdió una guerra","Porque no tuvo rey","Porque dejó de ofrecer sacrificios"],"dato":"«Mi pueblo fué talado, porque le faltó sabiduría»: el pueblo rechazó el conocimiento de Dios, y los sacerdotes olvidaron su ley.","cita":"Oseas 4:6","versiculo":"Mi pueblo fué talado, porque le faltó sabiduría. Porque tú desechaste la sabiduría, yo te echaré del sacerdocio: y pues que olvidaste la ley de tu Dios, también yo me olvidaré de tus hijos.","vcita":"Oseas 4:6","pista":"«El problema no era falta de rituales, sino de conocer a Dios.»"},{"pregunta":"¿Qué dice Dios que desea, según Oseas 6:6?","opciones":["Misericordia, y no sacrificio","Ayunos, y no fiestas","Silencio, y no oraciones","Justicia de los reyes, y no culto"],"dato":"«Misericordia quise, y no sacrificio; y conocimiento de Dios más que holocaustos»: Jesús citó esta frase dos veces en los Evangelios.","cita":"Oseas 6:6","versiculo":"Porque misericordia quise, y no sacrificio; y conocimiento de Dios más que holocaustos.","vcita":"Oseas 6:6","pista":"«Jesús la repite en Mateo: Id, y aprended lo que significa.»"},{"pregunta":"¿Qué valle promete Dios convertir en «puerta de esperanza» para Israel?","opciones":["El valle de Achôr","El valle de Jezreel","El valle de Hebrón","El valle del Jordán"],"dato":"El valle de Achor, escenario de la desobediencia de Acán en tiempos de Josué, se convertirá en puerta de esperanza: el lugar del juicio será lugar de nuevo comienzo.","cita":"Oseas 2:15","versiculo":"Y daréle sus viñas desde allí, y el valle de Achôr por puerta de esperanza; y allí cantará como en los tiempos de su juventud, y como en el día de su subida de la tierra de Egipto.","vcita":"Oseas 2:15","pista":"«Es el mismo valle donde Acán fue castigado en el libro de Josué.»"},{"pregunta":"Según Oseas, ¿en qué términos desposará Dios a su pueblo para siempre?","opciones":["En justicia, juicio y misericordia","En poder, riqueza y gloria","En silencio y temor","En holocaustos y ofrendas"],"dato":"Dios promete un desposorio eterno fundado en la justicia y la misericordia, no en la infidelidad del pasado: un nuevo pacto de amor fiel.","cita":"Oseas 2:19","versiculo":"Y te desposaré conmigo para siempre; desposarte he conmigo en justicia, y juicio, y misericordia, y miseraciones.","vcita":"Oseas 2:19","pista":"«Es como una boda nueva, después de la infidelidad: el anillo es la justicia y la misericordia.»"},{"pregunta":"¿A qué animal compara Oseas a Efraín, por andar sin entendimiento entre Egipto y Asiria?","opciones":["A una paloma incauta","A un león joven","A una oveja perdida","A un asno montés"],"dato":"Efraín, como paloma incauta y sin entendimiento, llamaba a Egipto y acudía a Asiria buscando ayuda en vez de volver a Dios.","cita":"Oseas 7:11","versiculo":"Y fué Ephraim como paloma incauta, sin entendimiento: llamarán á Egipto, acudirán al Asirio.","vcita":"Oseas 7:11","pista":"«Vuela de un lado a otro buscando ayuda en los imperios equivocados.»"},{"pregunta":"¿Qué pregunta conmovedora hace Dios, incapaz de abandonar a Efraín, en Oseas 11?","opciones":["«¿Cómo tengo de dejarte, oh Efraín?»","«¿Dónde estás, Efraín?»","«¿Quién como tú, Efraín?»","«¿Hasta cuándo, Efraín?»"],"dato":"Aunque Israel merecía el juicio, el corazón de Dios se revuelve dentro de él: «Mi corazón se revuelve dentro de mí, inflámanse todas mis conmiseraciones».","cita":"Oseas 11:8","versiculo":"¿Cómo tengo de dejarte, oh Ehpraim? ¿he de entregarte yo, Israel? ¿cómo podré yo hacerte como Adma, ni ponerte como á Zeboim? Mi corazón se revuelve dentro de mí, inflámanse todas mis conmiseraciones.","vcita":"Oseas 11:8","pista":"«Es el lamento de un padre que no se resigna a soltar a su hijo.»"},{"pregunta":"¿Qué promete hacer Dios con la rebelión de su pueblo en el capítulo final de Oseas?","opciones":["Sanarla y amarlos de pura voluntad","Olvidarla si pagan tributo","Castigarla con el exilio eterno","Esconderla de las naciones"],"dato":"El libro cierra con esperanza: «Yo medicinaré su rebelión, amarélos de voluntad», porque el furor de Dios se apartó de ellos.","cita":"Oseas 14:4","versiculo":"Yo medicinaré su rebelión, amarélos de voluntad: porque mi furor se apartó de ellos.","vcita":"Oseas 14:4","pista":"«Dios se presenta como el médico de la apostasía de su pueblo.»"}],"Joel":[{"pregunta":"¿Quién era el padre del profeta Joel?","opciones":["Pethuel","Amittai","Beeri","Buzí"],"dato":"El libro comienza así: «Palabra de Jehová que fué á Joel hijo de Pethuel». De Joel apenas sabemos su nombre, que significa «Jehová es Dios».","cita":"Joel 1:1","versiculo":"PALABRA de Jehová que fué á Joel hijo de Pethuel.","vcita":"Joel 1:1","pista":"«Su nombre abre el libro: Joel, hijo de…»"},{"pregunta":"Según Joel 1:4, ¿qué plaga devoró la tierra por etapas, dejando todo arrasado?","opciones":["La langosta en sus fases","El granizo","La sequía","El fuego"],"dato":"Lo que dejó la oruga lo comió la langosta; lo de la langosta, el pulgón; y lo del pulgón, el revoltón: una invasión de langostas en oleadas que dejó la tierra desnuda.","cita":"Joel 1:4","versiculo":"Lo que quedó de la oruga comió la langosta, y lo que quedó de la langosta comió el pulgón; y el revoltón comió lo que del pulgón había quedado.","vcita":"Joel 1:4","pista":"«Cuatro nombres de insectos, una sola catástrofe para los campos de Judá.»"},{"pregunta":"¿Cómo anuncia Joel que está el día de Jehová en su primer capítulo?","opciones":["Cercano, y viene como destrucción del Todopoderoso","Lejano, para dentro de mil años","Ya pasó en tiempos de Moisés","Oculto, y nadie lo conocerá"],"dato":"«¡Ay del día! porque cercano está el día de Jehová»: Joel repite que el día de Jehová es grande, terrible y está a las puertas.","cita":"Joel 1:15","versiculo":"¡Ay del día! porque cercano está el día de Jehová, y vendrá como destrucción por el Todopoderoso.","vcita":"Joel 1:15","pista":"«No es un aviso para un futuro remoto: Joel dice que ya se oye venir.»"},{"pregunta":"¿Qué manda rasgar Joel al pueblo para volver a Dios, en lugar de los vestidos?","opciones":["El corazón","Las redes","El velo del templo","Los libros de la ley"],"dato":"«Lacerad vuestro corazón, y no vuestros vestidos»: Dios no quiere señales externas de luto, sino un arrepentimiento verdadero y profundo.","cita":"Joel 2:13","versiculo":"Y lacerad vuestro corazón, y no vuestros vestidos; y convertíos á Jehová vuestro Dios; porque misericordioso es y clemente, tardo para la ira, y grande en misericordia, y que se arrepiente del castigo.","vcita":"Joel 2:13","pista":"«Rasgar los vestidos era costumbre de duelo; Joel pide algo que no se ve.»"},{"pregunta":"¿Qué debía tocarse en Sion para pregonar ayuno y convocar a la congregación, según Joel?","opciones":["La trompeta","El arpa","Los címbalos","La campana del templo"],"dato":"«Tocad trompeta en Sión, pregonad ayuno, llamad á congregación»: ante el día de Jehová, el pueblo entero debía reunirse en ayuno solemne.","cita":"Joel 2:15","versiculo":"Tocad trompeta en Sión, pregonad ayuno, llamad á congregación.","vcita":"Joel 2:15","pista":"«Era el sonido de alarma y de convocatoria en Israel.»"},{"pregunta":"¿Qué promete restituir Dios a su pueblo, tras la plaga de langostas?","opciones":["Los años que comió la langosta","Las ciudades perdidas","El arca del pacto","Los diezmos robados"],"dato":"Dios promete devolver los años perdidos: «Os restituiré los años que comió la oruga, la langosta, el pulgón, y el revoltón».","cita":"Joel 2:25","versiculo":"Y os restituiré los años que comió la oruga, la langosta, el pulgón, y el revoltón; mi grande ejército que envié contra vosotros.","vcita":"Joel 2:25","pista":"«Dios no solo perdona el futuro: también redime el tiempo perdido.»"},{"pregunta":"¿Qué promete derramar Dios «sobre toda carne» en la profecía de Joel, cumplida en Pentecostés?","opciones":["Su Espíritu","Lluvia temprana","Juicio de fuego","Aceite de la unción"],"dato":"Pedro citó Joel 2 el día de Pentecostés: hijos e hijas profetizarán, los viejos soñarán sueños y los jóvenes verán visiones.","cita":"Joel 2:28","versiculo":"Y será que después de esto, derramaré mi Espíritu sobre toda carne, y profetizarán vuestros hijos y vuestras hijas; vuestros viejos soñarán sueños, y vuestros mancebos verán visiones.","vcita":"Joel 2:28","pista":"«Hechos capítulo 2 lo explica: Esto es lo dicho por el profeta Joel.»"},{"pregunta":"Según Joel, ¿qué señales en el sol y la luna anunciarán el día grande y espantoso de Jehová?","opciones":["El sol se tornará en tinieblas y la luna en sangre","El sol se detendrá y la luna brillará de día","El sol caerá y la luna se partirá","Habrá un arco en las nubes"],"dato":"Antes de que venga el día grande y espantoso de Jehová, habrá prodigios: el sol en tinieblas y la luna en sangre, como citó también Pedro.","cita":"Joel 2:31","versiculo":"El sol se tornará en tinieblas, y la luna en sangre, antes que venga el día grande y espantoso de Jehová.","vcita":"Joel 2:31","pista":"«Son las señales en el cielo que preceden al día de Jehová.»"},{"pregunta":"Según Joel 2:32, ¿quién será salvo?","opciones":["Cualquiera que invocare el nombre de Jehová","Solo los sacerdotes","El que ofrezca más sacrificios","El que suba armado al monte de Sion"],"dato":"«Cualquiera que invocare el nombre de Jehová, será salvo»: Pablo cita esta promesa en Romanos 10:13, abierta a todo el que cree.","cita":"Joel 2:32","versiculo":"Y será que cualquiera que invocare el nombre de Jehová, será salvo: porque en el monte de Sión y en Jerusalem habrá salvación, como Jehová ha dicho, y en los que quedaren, á los cuales Jehová habrá llamado.","vcita":"Joel 2:32","pista":"«Es la misma frase que Pablo usa en Romanos 10.»"},{"pregunta":"En Joel 3:10, ¿en qué deben convertir las naciones sus azadones, preparándose para el juicio?","opciones":["En espadas","En arados","En escudos","En trompetas"],"dato":"Al revés que en Isaías y Miqueas, aquí las naciones son llamadas a la guerra del juicio: «Haced espadas de vuestros azadones, lanzas de vuestras hoces; diga el flaco: Fuerte soy».","cita":"Joel 3:10","versiculo":"Haced espadas de vuestros azadones, lanzas de vuestras hoces; diga el flaco: Fuerte soy.","vcita":"Joel 3:10","pista":"«Es la orden inversa a la de convertir las espadas en arados.»"},{"pregunta":"¿A qué valle subirán las gentes para ser juzgadas por Dios, según Joel?","opciones":["Al valle de Josaphat","Al valle de Jezreel","Al valle de Escol","Al valle de Sitim"],"dato":"En el valle de Josafat —que significa «Jehová juzga»— Dios se sentará para juzgar a todas las gentes que se repartieron su tierra y oprimieron a su pueblo.","cita":"Joel 3:12","versiculo":"Las gentes se despierten, y suban al valle de Josaphat: porque allí me sentaré para juzgar todas las gentes de alrededor.","vcita":"Joel 3:12","pista":"«El nombre del valle significa: Jehová ha juzgado.»"}],"Amós":[{"pregunta":"¿Dos años antes de qué suceso fechó Amós el mensaje que vio acerca de Israel?","opciones":["Del terremoto","De la invasión asiria","De la muerte del rey Uzzías","De un eclipse de sol"],"dato":"Amós sitúa sus palabras «en días de Uzzías rey de Judá, y en días de Jeroboam hijo de Joas rey de Israel, dos años antes del terremoto», un temblor recordado siglos después.","cita":"Amós 1:1","versiculo":"LAS palabras de Amós, que fué entre los pastores de Tecoa, las cuales vió acerca de Israel en días de Uzzía rey de Judá, y en días de Jeroboam hijo de Joas rey de Israel, dos años antes del terremoto.","vcita":"Amós 1:1","pista":"«Zacarías todavía lo menciona como el gran temblor de los días de Uzzías.»"},{"pregunta":"Según Amós, ¿por qué precio miserable vendían al pobre en Israel?","opciones":["Por un par de zapatos","Por un siclo de plata","Por un campo de cebada","Por una medida de trigo"],"dato":"El juicio cae porque «vendieron por dinero al justo, y al pobre por un par de zapatos»: la vida de un necesitado valía menos que unas sandalias.","cita":"Amós 2:6","versiculo":"Así ha dicho Jehová: Por tres pecados de Israel, y por el cuarto, no desviaré su castigo; porque vendieron por dinero al justo, y al pobre por un par de zapatos:","vcita":"Amós 2:6","pista":"«El calzado de un rico valía más que la libertad de un pobre.»"},{"pregunta":"¿Qué pregunta retórica abre las sentencias de causa y efecto en Amós 3?","opciones":["«¿Andarán dos juntos, si no estuvieren de concierto?»","«¿Qué pide Jehová de ti?»","«¿De dónde viene mi socorro?»","«¿Quién es sabio y guardará estas cosas?»"],"dato":"Amós encadena preguntas de sentido común: nada sucede sin causa, y si el profeta anuncia juicio, es porque el juicio viene de verdad.","cita":"Amós 3:3","versiculo":"¿Andarán dos juntos, si no estuvieren de concierto?","vcita":"Amós 3:3","pista":"«Habla de caminar en acuerdo: dos personas, un mismo paso.»"},{"pregunta":"¿Con qué llamado solemne termina Dios su advertencia a Israel en Amós 4?","opciones":["«Aparéjate para venir al encuentro a tu Dios»","«Vuelve a tu tierra»","«Ofrece diezmos en Betel»","«Calla ante el Señor»"],"dato":"Como los castigos no hicieron volver al pueblo, Dios concluye: «Aparéjate para venir al encuentro á tu Dios, oh Israel», un llamado a rendir cuentas.","cita":"Amós 4:12","versiculo":"Por tanto, de esta manera haré á ti, oh Israel: y porque te he de hacer esto, aparéjate para venir al encuentro á tu Dios, oh Israel.","vcita":"Amós 4:12","pista":"«Cinco veces dijo Dios antes: Con todo esto no os volvisteis a mí.»"},{"pregunta":"¿Qué dice Amós que será el día de Jehová para los que lo desean sin arrepentirse?","opciones":["Tinieblas, y no luz","Gozo y fiesta","Descanso de sus enemigos","El día de su coronación"],"dato":"«¡Ay de los que desean el día de Jehová!»: para el Israel impenitente no será luz sino tinieblas, como quien huye de un león y se topa con un oso.","cita":"Amós 5:18","versiculo":"¡Ay de los que desean el día de Jehová! ¿para qué queréis este día de Jehová? [Será de] tinieblas, y no luz:","vcita":"Amós 5:18","pista":"«Esperaban victoria sobre sus enemigos; les espera juicio sobre ellos.»"},{"pregunta":"¿Qué dice Dios de las solemnidades y asambleas de Israel en Amós 5?","opciones":["«Aborrecí, abominé vuestras solemnidades»","«Multiplicad vuestras fiestas»","«Acepto vuestros holocaustos»","«Guardad silencio en mis atrios»"],"dato":"Dios rechaza un culto lleno de fiestas pero vacío de justicia: aborrece las solemnidades de un pueblo que oprime al pobre.","cita":"Amós 5:21","versiculo":"Aborrecí, abominé vuestras solemnidades, y no me darán buen olor vuestras asambleas.","vcita":"Amós 5:21","pista":"«El problema no era la agenda del culto, sino el corazón del pueblo.»"},{"pregunta":"¿Como qué pide Dios que corra el juicio, en la frase más famosa de Amós?","opciones":["Como las aguas, y la justicia como impetuoso arroyo","Como el viento del desierto","Como fuego consumidor","Como un río de aceite"],"dato":"«Antes corra el juicio como las aguas, y la justicia como impetuoso arroyo»: Dios quiere una justicia constante y caudalosa, no ritos vacíos.","cita":"Amós 5:24","versiculo":"Antes corra el juicio como las aguas, y la justicia como impetuoso arroyo.","vcita":"Amós 5:24","pista":"«Es la imagen de un río que nunca se seca, aplicada a la justicia.»"},{"pregunta":"¿Qué sacerdote de Betel acusó a Amós de conspirar contra el rey Jeroboam?","opciones":["Amasías","Jeroboam","Ozías","Joiada"],"dato":"Amasías, sacerdote del santuario real de Betel, envió a decir a Jeroboam: «Amós se ha conjurado contra ti... la tierra no puede sufrir todas sus palabras».","cita":"Amós 7:10","versiculo":"Entonces Amasías sacerdote de Beth-el envió á decir á Jeroboam, rey de Israel: Amós se ha conjurado contra ti en medio de la casa de Israel: la tierra no puede sufrir todas sus palabras.","vcita":"Amós 7:10","pista":"«Era el sacerdote del santuario real de Betel, al servicio del rey.»"},{"pregunta":"¿Qué vio Amós en la visión que anunció el fin de Israel: un canastillo de qué?","opciones":["De fruta de verano","De higos malos","De pan sin levadura","De uvas pisadas"],"dato":"El canastillo de fruta de verano es un juego de sonidos en hebreo: fruta madura suena como «fin»: «Venido ha el fin sobre mi pueblo Israel».","cita":"Amós 8:2","versiculo":"Y dijo: ¿Qué ves, Amós? Y dije: Un canastillo de fruta de verano. Y díjome Jehová: Venido ha el fin sobre mi pueblo Israel; no le pasaré más.","vcita":"Amós 8:2","pista":"«La fruta está madura… y también el juicio: en hebreo suenan parecido.»"},{"pregunta":"¿De qué enviará Dios hambre sobre la tierra, según Amós 8?","opciones":["De oír la palabra de Jehová","De pan y de agua","De aceite y vino","De lluvia temprana"],"dato":"La peor hambre no es la de pan: Dios enviará hambre «de oir palabra de Jehová», y la gente vagará de mar a mar buscándola sin hallarla.","cita":"Amós 8:11","versiculo":"He aquí vienen días, dice el Señor Jehová, en los cuales enviaré hambre á la tierra, no hambre de pan, ni sed de agua, sino de oir palabra de Jehová.","vcita":"Amós 8:11","pista":"«El silencio de Dios es el castigo más temido por el profeta.»"},{"pregunta":"¿Qué promete levantar Dios «en aquel día», según el cierre de Amós?","opciones":["El tabernáculo caído de David","El muro de Jerusalén","El altar de Betel","La torre de Siloé"],"dato":"Dios levantará el tabernáculo de David, cerrará sus portillos y lo edificará como en el tiempo pasado; Santiago citó esta profecía en el concilio de Jerusalén (Hechos 15).","cita":"Amós 9:11","versiculo":"En aquel día yo levantaré el tabernáculo de David, caído, y cerraré sus portillos, y levantaré sus ruinas, y edificarélo como en el tiempo pasado;","vcita":"Amós 9:11","pista":"«El libro termina con restauración, no con ruina: una tienda real caída se vuelve a levantar.»"}],"Abdías":[{"pregunta":"¿Qué distinción tiene el libro de Abdías entre todos los del Antiguo Testamento?","opciones":["Es el libro más corto, con un solo capítulo","Es el único escrito en poesía","Es el último en escribirse","Es el único sin autor conocido"],"dato":"Abdías tiene apenas 21 versículos en un único capítulo: es el libro más breve del Antiguo Testamento, y todo él trata de Edom.","cita":"Abdías 1:1","versiculo":"VISIÓN de Abdías. El Señor Jehová ha dicho así cuanto á Edom: Oído hemos el pregón de Jehová, y mensajero es enviado á las gentes.","vcita":"Abdías 1:1","pista":"«Su nombre significa «siervo de Jehová», y su libro cabe en una página.»"},{"pregunta":"¿De qué hijo de Isaac descendía el pueblo de Edom, contra quien profetiza Abdías?","opciones":["De Esaú","De Jacob","De Ismael","De Lot"],"dato":"Edom es la nación de Esaú, el hermano gemelo de Jacob; por eso Abdías llama a Jacob «tu hermano» al reprochar la violencia de Edom.","cita":"Abdías 1:8","versiculo":"¿No haré que perezcan en aquel día, dice Jehová, los sabios de Edom, y la prudencia del monte de Esaú?","vcita":"Abdías 1:8","pista":"«Era el gemelo que vendió su primogenitura por un guiso de lentejas.»"},{"pregunta":"¿Dónde moraban los edomitas, confiados en su altísima morada, según Abdías?","opciones":["En las hendiduras de las peñas","En tiendas del desierto","En las orillas del mar Muerto","En la llanura de Moab"],"dato":"«La soberbia de tu corazón te ha engañado, tú que moras en las hendiduras de las peñas»: las ciudades excavadas en la roca hacían a Edom sentirse intocable.","cita":"Abdías 1:3","versiculo":"La soberbia de tu corazón te ha engañado, tú que moras en las hendiduras de las peñas, en tu altísima morada; que dices en tu corazón: ¿Quién me derribará á tierra?","vcita":"Abdías 1:3","pista":"«Su capital estaba tallada en acantilados de piedra.»"},{"pregunta":"Aunque Edom pusiera su nido entre las estrellas como el águila, ¿qué dice Dios que hará?","opciones":["«De ahí te derribaré»","«Allí te bendeciré»","«Te daré alas mayores»","«Nadie te encontrará jamás»"],"dato":"Ni la altura ni las fortalezas salvan al orgulloso: «Si te encaramares como águila, y si entre las estrellas pusieres tu nido, de ahí te derribaré, dice Jehová».","cita":"Abdías 1:4","versiculo":"Si te encaramares como águila, y si entre las estrellas pusieres tu nido, de ahí te derribaré, dice Jehová.","vcita":"Abdías 1:4","pista":"«Ni el nido más alto está fuera del alcance de Dios.»"},{"pregunta":"¿Qué les pasará a las cosas escondidas de Esaú, según Abdías 1:6?","opciones":["Serán escudriñadas y buscadas","Quedarán ocultas para siempre","Las heredará Judá en paz","Las guardarán los sabios de Temán"],"dato":"«¡Cómo fueron escudriñadas las cosas de Esaú! sus cosas escondidas fueron buscadas»: ni sus tesoros guardados en las cuevas escaparán del saqueo.","cita":"Abdías 1:6","versiculo":"¡Cómo fueron escudriñadas [las cosas de] Esaú! sus cosas escondidas fueron buscadas.","vcita":"Abdías 1:6","pista":"«Ni el escondite más profundo de la montaña quedará sin registrar.»"},{"pregunta":"¿Quiénes engañaron y prevalecieron contra Edom, según Abdías?","opciones":["Sus propios aliados y pacíficos","Los filisteos","Los hijos de Jacob","Solamente los caldeos"],"dato":"Los pueblos que comían su pan y firmaban paz con Edom pusieron el lazo debajo de él: «te han engañado tus pacíficos, prevalecieron contra ti».","cita":"Abdías 1:7","versiculo":"Hasta el término te hicieron llegar todos tus aliados; te han engañado tus pacíficos, prevalecieron contra ti; [los que comían] tu pan, pusieron el lazo debajo de ti: no hay en él entendimiento.","vcita":"Abdías 1:7","pista":"«La traición vino de la mesa compartida, no del campo de batalla.»"},{"pregunta":"¿Por qué cubrirá vergüenza a Edom y será talado para siempre, según Abdías?","opciones":["Por la injuria de su hermano Jacob","Por adorar a Baal","Por no guardar el sábado","Por vender a sus propios hijos"],"dato":"«Por la injuria de tu hermano Jacob te cubrirá vergüenza»: en vez de defender a su hermano en el día de la caída de Jerusalén, Edom se burló y saqueó.","cita":"Abdías 1:10","versiculo":"Por la injuria de tu hermano Jacob te cubrirá vergüenza, y serás talado para siempre.","vcita":"Abdías 1:10","pista":"«Su pecado no fue contra un extraño, sino contra su propio hermano gemelo.»"},{"pregunta":"¿Qué NO debió hacer Edom en el día en que su hermano fue extrañado, según Abdías?","opciones":["Mirarlo con gusto ni alegrarse de la ruina de Judá","Enviarle mensajeros de paz","Llorar en las puertas de Jerusalén","Ofrecer sacrificios por él"],"dato":"«No debiste tú estar mirando en el día de tu hermano... no te habías de haber alegrado de los hijos de Judá en el día que se perdieron»: alegrarse de la desgracia del hermano también es pecado.","cita":"Abdías 1:12","versiculo":"Pues no debiste tú estar mirando en el día de tu hermano, el día en que fué extrañado: no te habías de haber alegrado de los hijos de Judá en el día que se perdieron, ni habías de ensanchar tu boca en el día de la angustia:","vcita":"Abdías 1:12","pista":"«Dios juzga también la sonrisa ante la caída ajena.»"},{"pregunta":"¿Qué acción cruel reprocha Abdías a Edom en las encrucijadas, en el día de la angustia de Judá?","opciones":["Pararse a matar a los que escapaban y entregar a los que quedaban","Cerrar las fuentes de agua","Robar el arca del pacto","Quemar el templo de Jerusalén"],"dato":"Edom se apostó en las encrucijadas para cortar el paso a los fugitivos de Jerusalén y entregar a los sobrevivientes: complicidad activa con el invasor.","cita":"Abdías 1:14","versiculo":"Tampoco habías de haberte parado en las encrucijadas, para matar los que de ellos escapasen; ni habías tú de haber entregado los que quedaban en el día de angustia.","vcita":"Abdías 1:14","pista":"«No solo miró: bloqueó la única salida de los que huían.»"},{"pregunta":"¿Qué principio de retribución anuncia Abdías para Edom en el día de Jehová?","opciones":["«Como tú hiciste se hará contigo»","«Ojo por ojo y diente por diente»","«El que a hierro mata, a hierro muere»","«Cada uno cargará con su pecado»"],"dato":"«Como tú hiciste se hará contigo: tu galardón volverá sobre tu cabeza»: la medida que Edom usó con Judá será la medida de su propio juicio.","cita":"Abdías 1:15","versiculo":"Porque cercano está el día de Jehová sobre todas las gentes: como tú hiciste se hará contigo: tu galardón volverá sobre tu cabeza.","vcita":"Abdías 1:15","pista":"«Es la regla de la siembra y la cosecha aplicada a las naciones.»"},{"pregunta":"¿Qué habrá en el monte de Sion mientras Edom es juzgado, según Abdías?","opciones":["Salvamento y santidad","Un ejército de caldeos","El arca perdida","Un nuevo rey edomita"],"dato":"«Mas en el monte de Sión habrá salvamento, y será santidad, y la casa de Jacob poseerá sus posesiones»: el monte de Dios y el monte de Esaú tienen destinos opuestos.","cita":"Abdías 1:17","versiculo":"Mas en el monte de Sión habrá salvamento, y será santidad, y la casa de Jacob, poseerá sus posesiones.","vcita":"Abdías 1:17","pista":"«Dos montes frente a frente: Sion y el monte de Esaú.»"},{"pregunta":"¿Cómo termina el libro de Abdías, en su último versículo?","opciones":["«Y el reino será de Jehová»","«Y Edom fue destruido»","«Y Jacob heredó la tierra»","«Y no habrá más profetas»"],"dato":"Vendrán salvadores al monte de Sión para juzgar al monte de Esaú, «y el reino será de Jehová»: la última palabra del libro más corto es el reino de Dios.","cita":"Abdías 1:21","versiculo":"Y vendrán salvadores al monte de Sión para juzgar al monte de Esaú; y el reino será de Jehová.","vcita":"Abdías 1:21","pista":"«El libro más breve cierra con la frase más grande: el reino es de Dios.»"}],"Jonás":[{"pregunta":"¿Quién era el padre del profeta Jonás?","opciones":["Amittai","Pethuel","Beeri","Amoz"],"dato":"El libro abre así: «Fué palabra de Jehová á Jonás, hijo de Amittai»; ese mismo Jonás había profetizado en tiempos de Jeroboam II (2 Reyes 14).","cita":"Jonás 1:1","versiculo":"Y FUÉ palabra de Jehová á Jonás, hijo de Amittai, diciendo:","vcita":"Jonás 1:1","pista":"«Su nombre abre el libro, justo antes de la orden de ir a Nínive.»"},{"pregunta":"¿A qué puerto bajó Jonás para tomar el barco que partía hacia Tarsis?","opciones":["A Joppe","A Tiro","A Sidón","A Cesarea"],"dato":"Jonás descendió a Joppe, halló un navío que partía para Tarsis, pagó su pasaje y entró en él para huir «de delante de Jehová».","cita":"Jonás 1:3","versiculo":"Y Jonás se levantó para huir de la presencia de Jehová á Tarsis, y descendió á Joppe; y halló un navío que partía para Tarsis; y pagando su pasaje entró en él, para irse con ellos á Tarsis de delante de Jehová.","vcita":"Jonás 1:3","pista":"«Es el puerto de Jope, el mismo desde donde siglos después viajaría Pedro.»"},{"pregunta":"¿Cómo descubrieron los marineros que la tempestad venía por causa de Jonás?","opciones":["Echaron suertes, y la suerte cayó sobre Jonás","Jonás lo confesó apenas subió","El capitán lo soñó la noche anterior","Un pez golpeaba el casco del barco"],"dato":"En plena tormenta los marineros dijeron: «Venid, y echemos suertes, para saber por quién nos ha venido este mal. Y echaron suertes, y la suerte cayó sobre Jonás».","cita":"Jonás 1:7","versiculo":"Y dijeron cada uno á su compañero: Venid, y echemos suertes, para saber por quién nos ha venido este mal. Y echaron suertes, y la suerte cayó sobre Jonás.","vcita":"Jonás 1:7","pista":"«Fue como señalar con el dedo… pero con suertes antiguas.»"},{"pregunta":"Cuando los marineros le preguntaron quién era, ¿cómo se presentó Jonás a sí mismo?","opciones":["«Hebreo soy, y temo a Jehová, Dios de los cielos»","«Soy profeta enviado a Tarsis»","«Soy un mercader de Jope»","«Soy siervo del rey de Israel»"],"dato":"Jonás confesó su identidad y su fe en el peor momento: «Hebreo soy, y temo á Jehová, Dios de los cielos, que hizo la mar y la tierra», el mismo mar que bramaba contra ellos.","cita":"Jonás 1:9","versiculo":"Y él les respondió: Hebreo soy, y temo á Jehová, Dios de los cielos, que hizo la mar y la tierra.","vcita":"Jonás 1:9","pista":"«Huyendo de Dios, terminó hablando de Dios a unos marineros paganos.»"},{"pregunta":"¿Qué pidió Jonás a los marineros para que el mar se aquietara?","opciones":["Que lo tomaran y lo echaran a la mar","Que remaran más fuerte hacia la costa","Que echaran también a los demás pasajeros","Que sacrificaran un cordero en la cubierta"],"dato":"«Tomadme, y echadme á la mar, y la mar se os quietará: porque yo sé que por mí ha venido esta grande tempestad sobre vosotros»: Jonás aceptó cargar con la culpa.","cita":"Jonás 1:12","versiculo":"El les respondió: Tomadme, y echadme á la mar, y la mar se os quietará: porque yo sé que por mí ha venido esta grande tempestad sobre vosotros.","vcita":"Jonás 1:12","pista":"«Prefirió el fondo del mar antes que seguir poniendo en peligro a inocentes.»"},{"pregunta":"En su oración desde el vientre del pez, ¿qué dice Jonás que hizo cuando su alma desfallecía?","opciones":["Se acordó de Jehová, y su oración llegó hasta el santo templo","Maldijo el día en que nació","Prometió no volver a profetizar jamás","Se durmió profundamente en el pez"],"dato":"Desde lo más hondo, Jonás oró: «Cuando mi alma desfallecía en mí, acordéme de Jehová; y mi oración entró hasta ti en tu santo templo».","cita":"Jonás 2:7","versiculo":"Cuando mi alma desfallecía en mí, acordéme de Jehová; y mi oración entró hasta ti en tu santo templo.","vcita":"Jonás 2:7","pista":"«Ni el fondo del mar pudo detener una oración.»"},{"pregunta":"¿Qué tamaño tenía Nínive, según el libro de Jonás?","opciones":["Era ciudad sobremanera grande, de tres días de camino","Era una aldea de pescadores","Era tan pequeña que se cruzaba en una hora","Era igual que Jerusalén y Damasco juntas"],"dato":"«Era Nínive ciudad sobremanera grande, de tres días de camino»: recorrerla entera predicando llevaba tres días, y Jonás llevaba solo uno cuando la ciudad ya se arrepentía.","cita":"Jonás 3:3","versiculo":"Y levantóse Jonás, y fué á Nínive, conforme á la palabra de Jehová. Y era Nínive ciudad sobremanera grande, de tres días de camino.","vcita":"Jonás 3:3","pista":"«No se recorría ni en un día entero de predicación callejera.»"},{"pregunta":"¿Cuál fue el mensaje exacto que Jonás pregonó por las calles de Nínive?","opciones":["«De aquí a cuarenta días Nínive será destruida»","«Arrepentíos en siete días, si no, fuego»","«Quemad vuestros ídolos antes del mes»","«El rey de Asiria caerá este mismo año»"],"dato":"Un sermón de pocas palabras y sin promesas: «De aquí á cuarenta días Nínive será destruída». Y los ninivitas creyeron a Dios.","cita":"Jonás 3:4","versiculo":"Y comenzó Jonás á entrar por la ciudad, camino de un día, y pregonaba diciendo: De aquí á cuarenta días Nínive será destruída.","vcita":"Jonás 3:4","pista":"«Cuarenta días de plazo… y ni una palabra de esperanza en el anuncio.»"},{"pregunta":"¿Qué hizo el rey de Nínive cuando le llegó el mensaje de Jonás?","opciones":["Se levantó de su silla, se cubrió de saco y se sentó sobre ceniza","Mandó encarcelar a Jonás","Huyó de la ciudad durante la noche","Ofreció un gran banquete a sus príncipes"],"dato":"El rey se despojó de su vestido real, se cubrió de saco y se sentó sobre ceniza, y luego proclamó ayuno para toda la ciudad, hasta para los animales.","cita":"Jonás 3:6","versiculo":"Y llegó el negocio hasta el rey de Nínive, y levantóse de su silla, y echó de sí su vestido, y cubrióse de saco, y se sentó sobre ceniza.","vcita":"Jonás 3:6","pista":"«El trono se quedó vacío: el rey prefirió el suelo de ceniza.»"},{"pregunta":"¿Por qué no destruyó Dios a Nínive al cumplirse el plazo?","opciones":["Porque vio que se convirtieron de su mal camino","Porque Jonás intercedió por la ciudad","Porque el rey pagó un gran rescate","Porque la ciudad era demasiado grande"],"dato":"«Vió Dios lo que hicieron, que se convirtieron de su mal camino: y arrepintióse del mal que había dicho les había de hacer, y no lo hizo»: el arrepentimiento cambió el destino de la ciudad.","cita":"Jonás 3:10","versiculo":"Y vió Dios lo que hicieron, que se convirtieron de su mal camino: y arrepintióse del mal que había dicho les había de hacer, y no lo hizo.","vcita":"Jonás 3:10","pista":"«El sermón funcionó demasiado bien… y eso enojó al predicador.»"},{"pregunta":"Según Dios, ¿cuántas personas que no conocen su mano derecha de su izquierda vivían en Nínive?","opciones":["Más de ciento veinte mil","Doce mil","Setenta mil","Más de un millón"],"dato":"Dios cierra el libro con una pregunta a Jonás: «¿Y no tendré yo piedad de Nínive, aquella grande ciudad donde hay más de ciento y veinte mil personas... y muchos animales?».","cita":"Jonás 4:11","versiculo":"¿Y no tendré yo piedad de Nínive, aquella grande ciudad donde hay más de ciento y veinte mil personas que no conocen su mano derecha ni su mano izquierda, y muchos animales?","vcita":"Jonás 4:11","pista":"«Dios contó hasta a los animales al hacer las cuentas de su misericordia.»"}],"Miqueas":[{"pregunta":"¿De qué pueblo era el profeta Miqueas?","opciones":["De Morasti","De Tecoa","De Belén","De Anatot"],"dato":"«Palabra de Jehová que fué á Miqueas de Morasti en días de Jotham, Achâz, y Ezechîas»: Miqueas era de un pueblo humilde de Judá, contemporáneo de Isaías.","cita":"Miqueas 1:1","versiculo":"PALABRA de Jehová que fué á Miqueas de Morasti en días de Jotham, Achâz, y Ezechîas, reyes de Judá: lo que vió sobre Samaria y Jerusalem.","vcita":"Miqueas 1:1","pista":"«No era de la capital: venía de un pueblo pequeño del campo de Judá.»"},{"pregunta":"Según Miqueas 2:13, ¿quién subirá delante del remanente de Israel abriéndole paso?","opciones":["El rompedor","El rey de Asiria","Un ángel con espada de fuego","El sumo sacerdote"],"dato":"«Subirá rompedor delante de ellos; romperán y pasarán la puerta... y á la cabeza de ellos Jehová»: Dios mismo abre la brecha para que su pueblo salga.","cita":"Miqueas 2:13","versiculo":"Subirá rompedor delante de ellos; romperán y pasarán la puerta, y saldrán por ella: y su rey pasará delante de ellos, y á la cabeza de ellos Jehová.","vcita":"Miqueas 2:13","pista":"«Es el que derriba el muro para que los demás puedan pasar.»"},{"pregunta":"¿De qué dice Miqueas que está lleno, a diferencia de los profetas mentirosos?","opciones":["De fuerza del Espíritu de Jehová","De visiones y sueños cada noche","De la ley de Moisés solamente","De las riquezas de Judá"],"dato":"«Yo empero estoy lleno de fuerza del espíritu de Jehová, y de juicio, y de fortaleza, para denunciar á Jacob su rebelión»: su autoridad no venía de los reyes sino del Espíritu.","cita":"Miqueas 3:8","versiculo":"Yo empero estoy lleno de fuerza del espíritu de Jehová, y de juicio, y de fortaleza, para denunciar á Jacob su rebelión, y á Israel su pecado.","vcita":"Miqueas 3:8","pista":"«Los otros profetizaban por dinero; él, por el Espíritu.»"},{"pregunta":"¿Qué predijo Miqueas que le pasaría a Sion a causa de los pecados de sus dirigentes?","opciones":["Sería arada como campo","Sería cubierta por el mar","Sería dividida en dos reinos","Sería entregada a los filisteos"],"dato":"Miqueas anunció: «será Sión arada como campo, y Jerusalem será majanos». Un siglo después, los ancianos citaron esta profecía para defender a Jeremías (Jeremías 26).","cita":"Miqueas 3:12","versiculo":"Por tanto, á causa de vosotros será Sión arada como campo, y Jerusalem será majanos, y el monte de la casa como cumbres de breñal.","vcita":"Miqueas 3:12","pista":"«La colina del templo terminará con surcos de labranza.»"},{"pregunta":"En la visión de Miqueas 4, ¿en qué convertirán las naciones sus espadas y sus lanzas?","opciones":["Las espadas en azadones y las lanzas en hoces","Las espadas en trompetas y las lanzas en antorchas","Las lanzas en columnas del templo","Las espadas en coronas de oro"],"dato":"«Martillarán sus espadas para azadones, y sus lanzas para hoces: no alzará espada gente contra gente, ni más se ensayarán para la guerra»: la paz del reino venidero.","cita":"Miqueas 4:3","versiculo":"Y juzgará entre muchos pueblos, y corregirá fuertes gentes hasta muy lejos: y martillarán sus espadas para azadones, y sus lanzas para hoces: no alzará espada gente contra gente, ni más se ensayarán para la guerra.","vcita":"Miqueas 4:3","pista":"«Las armas de guerra se vuelven herramientas de labranza.»"},{"pregunta":"Según Miqueas 5, ¿con qué apacentará el gobernante que saldrá de Belén?","opciones":["Con fortaleza de Jehová y grandeza de su nombre","Con vara de hierro solamente","Con los ejércitos de Judá","Con la sabiduría de Salomón"],"dato":"«Estará, y apacentará con fortaleza de Jehová, con grandeza del nombre de Jehová su Dios»: el pastor-rey será engrandecido hasta los fines de la tierra.","cita":"Miqueas 5:4","versiculo":"Y estará, y apacentará con fortaleza de Jehová, con grandeza del nombre de Jehová su Dios: y asentarán; porque ahora será engrandecido hasta los fines de la tierra.","vcita":"Miqueas 5:4","pista":"«Es el capítulo siguiente al anuncio de Belén: el pequeño pueblo y el gran pastor.»"},{"pregunta":"¿Como qué será el residuo de Jacob en medio de muchos pueblos, según Miqueas?","opciones":["Como el rocío de Jehová","Como la arena del mar","Como cedros del Líbano","Como estrellas del cielo"],"dato":"«Será el residuo de Jacob en medio de muchos pueblos, como el rocío de Jehová, como las lluvias sobre la hierba»: una bendición que viene de Dios y no espera a los hombres.","cita":"Miqueas 5:7","versiculo":"Y será el residuo de Jacob en medio de muchos pueblos, como el rocío de Jehová, como las lluvias sobre la hierba, las cuales no esperan varón, ni aguardan á hijos de hombres.","vcita":"Miqueas 5:7","pista":"«Llega en silencio, de noche, y hace reverdecer todo: viene del cielo.»"},{"pregunta":"¿Con qué pregunta abre Dios su pleito contra su pueblo en Miqueas 6?","opciones":["«Pueblo mío, ¿qué te he hecho?»","«¿Dónde están tus dioses?»","«¿Por qué edificaste altares?»","«¿Quién te enseñó a pecar?»"],"dato":"Dios llama a los montes por testigos y pregunta con dolor: «Pueblo mío, ¿qué te he hecho, ó en qué te he molestado? Responde contra mí».","cita":"Miqueas 6:3","versiculo":"Pueblo mío, ¿qué te he hecho, ó en qué te he molestado? Responde contra mí.","vcita":"Miqueas 6:3","pista":"«Es un juicio donde el Juez pregunta como un padre herido.»"},{"pregunta":"¿Qué afirma Miqueas aunque tenga que morar en tinieblas?","opciones":["«Jehová será mi luz»","«Mis enemigos me dejarán en paz»","«El templo será reedificado»","«Vendrán días de venganza»"],"dato":"«Aunque caí, he de levantarme; aunque more en tinieblas, Jehová será mi luz»: la confesión de fe de Miqueas en medio del juicio anunciado.","cita":"Miqueas 7:8","versiculo":"Tú, enemiga mía, no te huelgues de mí: porque aunque caí, he de levantarme; aunque more en tinieblas, Jehová será mi luz.","vcita":"Miqueas 7:8","pista":"«Caído, pero no apagado: Dios mismo es su lámpara.»"},{"pregunta":"¿Qué pregunta de admiración abre el himno final de Miqueas, y suena como el nombre del profeta?","opciones":["«¿Qué Dios como tú, que perdonas la maldad?»","«¿Qué pueblo como Israel?»","«¿Qué rey como David?»","«¿Qué monte como Sion?»"],"dato":"Miqueas significa «¿Quién como Jehová?», y el libro casi cierra con ese juego de palabras: «¿Qué Dios como tú, que perdonas la maldad... porque es amador de misericordia?».","cita":"Miqueas 7:18","versiculo":"¿Qué Dios como tú, que perdonas la maldad, y olvidas el pecado del resto de su heredad? No retuvo para siempre su enojo, porque es amador de misericordia.","vcita":"Miqueas 7:18","pista":"«La respuesta escondida está en el propio nombre del profeta.»"},{"pregunta":"Según Miqueas 7:19, ¿dónde echará Dios todos los pecados de su pueblo?","opciones":["En los profundos de la mar","Detrás de sus espaldas","En el desierto de Sin","Bajo el altar del templo"],"dato":"«Él tornará, él tendrá misericordia de nosotros; él sujetará nuestras iniquidades, y echará en los profundos de la mar todos nuestros pecados».","cita":"Miqueas 7:19","versiculo":"El tornará, él tendrá misericordia de nosotros; él sujetará nuestras iniquidades, y echará en los profundos de la mar todos nuestros pecados.","vcita":"Miqueas 7:19","pista":"«Tan hondo que nadie podrá pescarlos de vuelta.»"}],"Nahúm":[{"pregunta":"¿A qué ciudad llama Nahúm «ciudad de sangres», llena de mentira y de rapiña?","opciones":["Nínive","Babilonia","Tiro","Damasco"],"dato":"Nahúm profetizó la caída de Nínive, la cruel capital de Asiria, unos cien años después de que Jonás predicara allí.","cita":"Nahúm 3:1","versiculo":"¡AY de la ciudad de sangres, toda llena de mentira y de rapiña, sin apartarse [de ella] el pillaje!","vcita":"Nahúm 3:1","pista":"«Es la misma ciudad adonde Jonás no quería ir a predicar.»"},{"pregunta":"¿De qué lugar era originario el profeta Nahúm?","opciones":["De El-kosh","De Tecoa","De Anatot","De Moreset"],"dato":"El libro se presenta como «la visión de Nahum de El-kosh»; no se conoce con certeza la ubicación de ese pueblo.","cita":"Nahúm 1:1","versiculo":"CARGA de Nínive. Libro de la visión de Nahum de El-kosh.","vcita":"Nahúm 1:1","pista":"«Su gentilicio suena parecido a su nombre: elcosita.»"},{"pregunta":"Según Nahúm, Jehová es fortaleza ¿en qué día?","opciones":["En el día de la angustia","En el día de la fiesta","En el día del reposo","En el día de la cosecha"],"dato":"En medio de un capítulo sobre la ira de Dios contra Nínive, Nahúm consuela a Judá: Dios es refugio para los que confían en él.","cita":"Nahúm 1:7","versiculo":"Bueno es Jehová para fortaleza en el día de la angustia; y conoce á los que en él confían.","vcita":"Nahúm 1:7","pista":"«Es el día en que todo sale mal y más lo necesitas.»"},{"pregunta":"Según Nahúm 1:3, Jehová es tardo para la ira y grande ¿en qué?","opciones":["En poder","En años","En riquezas","En ejércitos"],"dato":"Dios tarda en airarse, pero su poder es inmenso: marcha en la tempestad y las nubes son el polvo de sus pies.","cita":"Nahúm 1:3","versiculo":"Jehová es tardo para la ira, y grande en poder, y no tendrá [al culpado] por inocente. Jehová marcha entre la tempestad y turbión, y las nubes son el polvo de sus pies.","vcita":"Nahúm 1:3","pista":"«No es paciencia débil: es fuerza contenida.»"},{"pregunta":"Según Nahúm 1:15, sobre los montes se ven los pies ¿de quién?","opciones":["Del que trae buenas nuevas y pregona la paz","Del rey de Asiria que huye","De los espías de Judá","De los pastores de Belén"],"dato":"La caída de Nínive era una buena noticia para Judá: el mensajero anuncia que el malvado no pasará más por su tierra.","cita":"Nahúm 1:15","versiculo":"He aquí sobre los montes los pies del que trae buenas nuevas, del que pregona la paz. Celebra, oh Judá, tus fiestas, cumple tus votos: porque nunca más pasará por ti el malvado; pereció del todo.","vcita":"Nahúm 1:15","pista":"«Isaías usa la misma imagen del mensajero que anuncia paz.»"},{"pregunta":"Según la profecía de Nahúm, ¿qué se abriría y el palacio de Nínive sería destruido?","opciones":["Las puertas de los ríos","Las puertas de la ciudad","Las compuertas del cielo","Las puertas del templo"],"dato":"Nínive cayó cuando el río que la cruzaba se desbordó y socavó sus defensas, tal como lo anuncia la profecía.","cita":"Nahúm 2:6","versiculo":"Las puertas de los ríos se abrirán, y el palacio será destruído.","vcita":"Nahúm 2:6","pista":"«El enemigo de Nínive llegaría... ¡por el agua!»"},{"pregunta":"Nahúm pregunta con ironía qué fue de la morada ¿de qué animales, símbolo de los reyes asirios?","opciones":["De los leones","De los osos","De las águilas","De los lobos"],"dato":"Los reyes de Asiria se representaban como leones cazadores; su guarida quedaría vacía y sin cachorros.","cita":"Nahúm 2:11","versiculo":"¿Qué es de la morada de los leones, y de la majada de los cachorros de los leones, donde se recogía el león, y la leona, y los cachorros del león, y no había quien les pusiese miedo?","vcita":"Nahúm 2:11","pista":"«El rey de la selva, que llenaba sus cuevas de presas.»"},{"pregunta":"¿Qué ciudad egipcia, asentada entre ríos, pone Nahúm como ejemplo de que ni ella pudo salvarse?","opciones":["No-amón (Tebas)","Menfis","Alejandría","Tanis"],"dato":"No-amón es Tebas, la poderosa ciudad del Nilo que ya había caído en manos de Asiria; Nínive no sería mejor que ella.","cita":"Nahúm 3:8","versiculo":"¿Eres tú mejor que No-amón, que estaba asentada entre ríos, cercada de aguas, cuyo baluarte era la mar, [y] del mar su muralla?","vcita":"Nahúm 3:8","pista":"«Su baluarte era el agua: ríos por todas partes.»"},{"pregunta":"Según Nahúm 3:4, Nínive, la «ramera de hermosa gala», era maestra ¿de qué?","opciones":["De brujerías","De comercio","De guerra","De música"],"dato":"Con sus hechizos y su seducción política, Nínive vendía naciones enteras; por eso vendría su vergüenza pública.","cita":"Nahúm 3:4","versiculo":"A causa de la multitud de las fornicaciones de la ramera de hermosa gala, maestra de brujerías, que vende las gentes con sus fornicaciones, y los pueblos con sus hechizos.","vcita":"Nahúm 3:4","pista":"«Vendía pueblos enteros con sus hechizos.»"},{"pregunta":"Nahúm termina anunciando que los pastores de ¿qué rey dormirían y su pueblo se derramaría por los montes?","opciones":["Del rey de Asiria","Del rey de Babilonia","Del rey de Egipto","Del rey de Judá"],"dato":"Sin pastores que lo junten, el imperio asirio se dispersaría para siempre: su herida no tendría cura.","cita":"Nahúm 3:18","versiculo":"Durmieron tus pastores, oh rey de Asiria, reposaron tus valientes: tu pueblo se derramó por los montes, y no hay quien lo junte.","vcita":"Nahúm 3:18","pista":"«Es el mismo imperio cuya capital era Nínive.»"},{"pregunta":"En Nahúm 1:13, ¿qué promete Jehová quebrar de sobre Judá?","opciones":["El yugo de Asiria","El arco de Israel","La vara de Moisés","Las tablas de la ley"],"dato":"«Quebraré su yugo de sobre ti, y romperé tus coyundas»: Judá quedaría libre de la opresión asiria para siempre.","cita":"Nahúm 1:13","versiculo":"Porque ahora quebraré su yugo de sobre ti, y romperé tus coyundas.","vcita":"Nahúm 1:13","pista":"«Lo que lleva el buey sobre el cuello para tirar del arado.»"},{"pregunta":"Según Nahúm 2:3, ¿de qué color serían los escudos y los vestidos del ejército que atacaría a Nínive?","opciones":["Rojos, color grana","Blancos como la nieve","Negros como la noche","Azules como el cielo"],"dato":"Los valientes atacantes vestían de grana y sus escudos eran bermejos; sus carros brillaban como antorchas en las calles.","cita":"Nahúm 2:3","versiculo":"El escudo de sus valientes será bermejo, los varones de [su] ejército vestidos de grana: el carro como fuego de hachas; el día que se aparejará, temblarán las hayas.","vcita":"Nahúm 2:3","pista":"«Bermejo y grana son tonos del mismo color.»"}],"Habacuc":[{"pregunta":"¿Cómo vivirá el justo, según la frase célebre de Habacuc 2:4, citada después por Pablo y en Hebreos?","opciones":["Por su fe","Por sus riquezas","Por su fuerza","Por sus muchas obras"],"dato":"«Mas el justo en su fe vivirá» es una de las frases más citadas del Antiguo Testamento: aparece en Romanos, Gálatas y Hebreos.","cita":"Habacuc 2:4","versiculo":"He aquí se enorgullece aquel cuya alma no es derecha en él: mas el justo en su fe vivirá.","vcita":"Habacuc 2:4","pista":"«No es por vista ni por obras: es por creer.»"},{"pregunta":"¿Qué nación anunció Dios que levantaría para castigar a Judá, «gente amarga y presurosa»?","opciones":["Los Caldeos (babilonios)","Los Egipcios","Los Filisteos","Los Sirios"],"dato":"Los caldeos eran el pueblo de Babilonia; su ejército recorrería la tierra poseyendo moradas ajenas, y eso dejó a Habacuc perplejo.","cita":"Habacuc 1:6","versiculo":"Porque he aquí, yo levanto los Caldeos, gente amarga y presurosa, que camina por la anchura de la tierra para poseer las habitaciones ajenas.","vcita":"Habacuc 1:6","pista":"«Su capital era Babilonia, la del rey Nabucodonosor.»"},{"pregunta":"¿Qué le mandó Jehová escribir a Habacuc, y hacerlo en tablas para que corriera el que lo leyera?","opciones":["La visión","Una nueva ley","La lista de los reyes","El censo del pueblo"],"dato":"La visión debía escribirse claramente en tablas, como un anuncio público: aunque tardara, sin duda vendría.","cita":"Habacuc 2:2","versiculo":"Y Jehová me respondió, y dijo: Escribe la visión, y declárala en tablas, para que corra el que leyere en ella.","vcita":"Habacuc 2:2","pista":"«Era lo que Dios le había mostrado al profeta.»"},{"pregunta":"Según Habacuc 2:14, la tierra será llena ¿de qué, como las aguas cubren la mar?","opciones":["Del conocimiento de la gloria de Jehová","De ejércitos enemigos","De trigo y de vino","De ciudades nuevas"],"dato":"En medio de los cinco «ayes» contra el opresor, Dios promete que su gloria será conocida en toda la tierra.","cita":"Habacuc 2:14","versiculo":"Porque la tierra será llena de conocimiento de la gloria de Jehová, como las aguas cubren la mar.","vcita":"Habacuc 2:14","pista":"«No es un bien material: es conocer cuánto vale Dios.»"},{"pregunta":"«Mas Jehová está en su santo templo»: ¿qué debe hacer toda la tierra delante de él, según Habacuc 2:20?","opciones":["Callar","Cantar","Huir","Edificar altares"],"dato":"Frente a los ídolos mudos, que no tienen espíritu, el Dios vivo está en su templo y toda la tierra guarda silencio reverente.","cita":"Habacuc 2:20","versiculo":"Mas Jehová [está] en su santo templo: calle delante de él toda la tierra.","vcita":"Habacuc 2:20","pista":"«Es lo contrario de hacer ruido: reverencia total.»"},{"pregunta":"Aunque la higuera no florezca ni haya fruto en las vides, ¿qué decide hacer Habacuc?","opciones":["Alegrarse en Jehová, el Dios de su salvación","Abandonar su oficio de profeta","Maldicir la tierra estéril","Irse a vivir a Egipto"],"dato":"Habacuc 3:17-18 es una de las declaraciones de fe más grandes de la Biblia: gozo en Dios aun sin cosecha, sin ganado y sin nada.","cita":"Habacuc 3:18","versiculo":"Con todo, yo me alegraré en Jehová, y me gozaré en el Dios de mi salud.","vcita":"Habacuc 3:18","pista":"«Su gozo no dependía de la cosecha, sino de Dios.»"},{"pregunta":"Según Habacuc 3:19, Dios pondrá los pies del profeta como los ¿de qué animal de las alturas?","opciones":["De ciervas","De cabras monteses","De águilas","De gacelas del desierto"],"dato":"La cierva pisa firme en los riscos más peligrosos; así Dios haría andar a su profeta sobre sus alturas.","cita":"Habacuc 3:19","versiculo":"Jehová el Señor es mi fortaleza, el cual pondrá mis pies como de ciervas, y me hará andar sobre mis alturas. Al jefe de los cantores sobre mis instrumentos de cuerdas.","vcita":"Habacuc 3:19","pista":"«Un animal de patas seguras en los peñascos.»"},{"pregunta":"En su oración, Habacuc le pide a Dios: «en la ira acuérdate ¿de qué?»","opciones":["De la misericordia","De los pactos antiguos","De los sacrificios","De los pobres"],"dato":"El profeta temió al oír la fama de Dios y pidió que, aun en medio del juicio, Dios avivara su obra y recordara su misericordia.","cita":"Habacuc 3:2","versiculo":"Oh Jehová, oído he tu palabra, y temí: oh Jehová, aviva tu obra en medio de los tiempos, en medio de los tiempos hazla conocer; en la ira acuérdate de la misericordia.","vcita":"Habacuc 3:2","pista":"«Es lo que todo pecador necesita cuando Dios se enoja.»"},{"pregunta":"¿Con qué nombre llama Habacuc a Dios en su queja: «tú, oh ____, lo fundaste para castigar»?","opciones":["Roca","Pastor","Rey eterno","Alfarero"],"dato":"Habacuc no entiende por qué Dios usa a una nación más impía para castigar a Judá, pero se apoya en que Dios es su Roca y su Santo.","cita":"Habacuc 1:12","versiculo":"¿No eres tú desde el principio, oh Jehová, Dios mío, Santo mío? No moriremos. Oh Jehová, para juicio lo pusiste; y tú, oh Roca, lo fundaste para castigar.","vcita":"Habacuc 1:12","pista":"«Firme, inconmovible, como una piedra gigante.»"},{"pregunta":"¿Dónde se subió Habacuc a atalayar, esperando la respuesta de Dios a su pregunta?","opciones":["Sobre su guarda, sobre la fortaleza","Al monte Carmelo","A la azotea de su casa","Al muro de Jerusalén"],"dato":"Como un centinela en su puesto, Habacuc se quedó vigilando hasta ver qué le hablaría Dios; la respuesta fue la visión de las tablas.","cita":"Habacuc 2:1","versiculo":"SOBRE mi guarda estaré, y sobre la fortaleza afirmaré el pie, y atalayaré para ver qué hablará en mí, y qué tengo de responder á mi pregunta.","vcita":"Habacuc 2:1","pista":"«Hizo lo que hace un vigilante en su torre.»"},{"pregunta":"Según Habacuc 1:5, la obra que Dios haría en sus días sería tan pasmosa que, aun cuando se la contaran, ¿qué pasaría?","opciones":["No la creerían","Todos huirían","Los reyes temblarían","Nadie la entendería jamás"],"dato":"Dios anuncia algo increíble: levantaría a los caldeos como instrumento de juicio, y el pueblo no lo creería ni oyéndolo.","cita":"Habacuc 1:5","versiculo":"Mirad en las gentes, y ved, y maravillaos pasmosamente; porque obra será hecha en vuestros días, que aun cuando se os contare, no la creeréis.","vcita":"Habacuc 1:5","pista":"«Pablo citó este versículo en su sermón de Antioquía.»"},{"pregunta":"¿Qué es el capítulo 3 del libro de Habacuc, «sobre Sigionoth»?","opciones":["Una oración del profeta en forma de salmo","Una carta a los exiliados","La lista de los ayes","Una visión de animales"],"dato":"El libro termina con un cántico-oración que incluso lleva indicaciones musicales: «Al jefe de los cantores sobre mis instrumentos de cuerdas».","cita":"Habacuc 3:1","versiculo":"ORACIÓN de Habacuc profeta, sobre Sigionoth.","vcita":"Habacuc 3:1","pista":"«Empieza el libro quejándose... y lo termina hablando con Dios cantando.»"}],"Sofonías":[{"pregunta":"¿En días de qué rey de Judá profetizó Sofonías, según el primer versículo de su libro?","opciones":["Josías","Ezequías","Manasés","Sedequías"],"dato":"Sofonías profetizó en tiempos de Josías; su genealogía se remonta cuatro generaciones, hasta un tal Ezechîas, quizá el rey Ezequías.","cita":"Sofonías 1:1","versiculo":"PALABRA de Jehová que fué á Sofonías hijo de Cushi, hijo de Gedalías, hijo de Amarías, hijo de Ezechîas, en días de Josías hijo de Amón, rey de Judá.","vcita":"Sofonías 1:1","pista":"«Es el rey niño que luego haría una gran reforma y hallaría el libro de la ley.»"},{"pregunta":"Sofonías describe el día de Jehová como «día de ira, día de angustia y de...» ¿qué más?","opciones":["Aprieto, alboroto y tiniebla","Fiesta y reposo","Cosecha y abundancia","Cántico y danza"],"dato":"El capítulo 1 de Sofonías es el retrato más completo del «día de Jehová»: ira, tiniebla, oscuridad y trompeta de guerra.","cita":"Sofonías 1:15","versiculo":"Día de ira aquel día, día de angustia y de aprieto, día de alboroto y de asolamiento, día de tiniebla y de oscuridad, día de nublado y de entenebrecimiento,","vcita":"Sofonías 1:15","pista":"«Nada de celebración: es el día del juicio.»"},{"pregunta":"Según Sofonías 1:18, ¿qué NO podrá librar a los hombres en el día de la ira de Jehová?","opciones":["Ni su plata ni su oro","Ni sus ejércitos","Ni sus murallas","Ni sus ídolos de madera"],"dato":"Ni todas las riquezas del mundo sirven de rescate cuando llega el fuego del celo de Dios sobre la tierra.","cita":"Sofonías 1:18","versiculo":"Ni su plata ni su oro podrá librarlos en el día de la ira de Jehová; pues toda la tierra será consumida con el fuego de su celo: porque ciertamente consumación apresurada hará con todos los moradores de la tierra.","vcita":"Sofonías 1:18","pista":"«Son los dos metales preciosos de siempre.»"},{"pregunta":"«Buscad a Jehová»: ¿a quiénes se dirige esa orden en Sofonías 2:3, para que quizá sean guardados en el día del enojo?","opciones":["A todos los humildes de la tierra","A los sacerdotes del templo","A los ejércitos de Judá","A los ricos de Jerusalén"],"dato":"La receta de Sofonías para escapar del juicio es triple: buscar a Jehová, buscar justicia y buscar mansedumbre.","cita":"Sofonías 2:3","versiculo":"Buscad á Jehová todos los humildes de la tierra, que pusisteis en obra su juicio; buscad justicia, buscad mansedumbre: quizás seréis guardados en el día del enojo de Jehová.","vcita":"Sofonías 2:3","pista":"«Son los de corazón bajo, no los soberbios.»"},{"pregunta":"Según Sofonías 2:9, Moab sería como Sodoma, ¿y los hijos de Ammón como qué ciudad?","opciones":["Como Gomorra","Como Nínive","Como Tiro","Como Babilonia"],"dato":"Moab y Ammón se burlaron del pueblo de Dios y se engrandecieron contra él; su fin sería como el de las ciudades de la llanura.","cita":"Sofonías 2:9","versiculo":"Por tanto, vivo yo, dice Jehová de los ejércitos, Dios de Israel, que Moab será como Sodoma, y los hijos de Ammón como Gomorra; campo de ortigas, y mina de sal, y asolamiento perpetuo: el resto de mi pueblo los saqueará, y el resto de mi gente los heredará.","vcita":"Sofonías 2:9","pista":"«Es la pareja inseparable de Sodoma desde el Génesis.»"},{"pregunta":"Según Sofonías 3:17, Jehová se regocijará sobre su pueblo con cantar y «callará» ¿de qué?","opciones":["De amor","De gozo","De paciencia","De misericordia"],"dato":"El libro que empezó con el día de ira termina con Dios cantando de alegría sobre su pueblo restaurado: un Dios que salva y se deleita.","cita":"Sofonías 3:17","versiculo":"Jehová en medio de ti, poderoso, él salvará; gozaráse sobre ti con alegría, callará de amor, se regocijará sobre ti con cantar.","vcita":"Sofonías 3:17","pista":"«Es el sentimiento más grande hacia su pueblo.»"},{"pregunta":"Según Sofonías 1:12, Dios escudriñará a Jerusalén ¿con qué, para visitar a los que viven acomodados y despreocupados?","opciones":["Con candiles (lámparas)","Con antorchas de guerra","Con los ojos de los ángeles","Con trompetas"],"dato":"Como quien busca con una lámpara en cada rincón, Dios hallaría a los que, sentados sobre sus heces como el vino asentado, decían: «Jehová ni hará bien ni mal».","cita":"Sofonías 1:12","versiculo":"Y será en aquel tiempo, que yo escudriñaré á Jerusalem con candiles, y haré visitación sobre los hombres que están sentados sobre sus heces, los cuales dicen en su corazón: Jehová ni hará bien ni mal.","vcita":"Sofonías 1:12","pista":"«Lo que se usa para buscar algo en la oscuridad.»"},{"pregunta":"Según Sofonías 2:13, ¿qué ciudad quedaría en asolamiento y en secadal como un desierto?","opciones":["Nínive","Jerusalén","Tiro","Gaza"],"dato":"Dios extendería su mano sobre el norte, destruiría a Asiria y en la orgullosa Nínive harían majada los rebaños y las bestias.","cita":"Sofonías 2:13","versiculo":"Y extenderá su mano sobre el aquilón, y destruirá al Assur, y pondrá á Nínive en asolamiento, y en secadal como un desierto.","vcita":"Sofonías 2:13","pista":"«Nahúm escribió un libro entero sobre la caída de esa ciudad.»"},{"pregunta":"Según Sofonías 3:9, Dios volverá a los pueblos ¿qué cosa, para que todos invoquen su nombre y le sirvan de común acuerdo?","opciones":["El labio limpio","La lengua hebrea","Los sacrificios antiguos","Las fiestas solemnes"],"dato":"Tras el juicio vendría la purificación: labios limpios para invocar a Jehová y servirle «de un consentimiento», hombro a hombro.","cita":"Sofonías 3:9","versiculo":"Por entonces volveré yo á los pueblos el labio limpio, para que todos invoquen el nombre de Jehová, para que de un consentimiento le sirvan.","vcita":"Sofonías 3:9","pista":"«Es lo contrario de la confusión de Babel.»"},{"pregunta":"Según Sofonías 3:12, Dios dejará en medio de Jerusalén un pueblo ¿con qué dos características?","opciones":["Humilde y pobre","Numeroso y rico","Sabio y valiente","Puro y temible"],"dato":"Del juicio quedaría un remanente humilde y pobre que esperaría en el nombre de Jehová y no haría iniquidad ni diría mentira.","cita":"Sofonías 3:12","versiculo":"Y dejaré en medio de ti un pueblo humilde y pobre, los cuales esperarán en el nombre de Jehová.","vcita":"Sofonías 3:12","pista":"«Lo contrario de los soberbios que fueron quitados.»"},{"pregunta":"Según Sofonías 1:4, Dios exterminaría de Jerusalén el remanente ¿de qué dios pagano?","opciones":["De Baal","De Dagón","De Moloc","De Astarté"],"dato":"El juicio caería sobre el resto de Baal, sobre los que adoraban al ejército del cielo en los terrados y juraban por Jehová y por su rey a la vez.","cita":"Sofonías 1:4","versiculo":"Y extenderé mi mano sobre Judá, y sobre todos los moradores de Jerusalem, y exterminaré de este lugar el remanente de Baal, y el nombre de los Chemarim con los sacerdotes;","vcita":"Sofonías 1:4","pista":"«Es el dios cananeo contra el que ya había peleado Elías en el Carmelo.»"},{"pregunta":"«Canta, oh hija de ____; da voces de júbilo, oh Israel»: ¿qué nombre completa el cántico de Sofonías 3:14?","opciones":["Sión","Jacob","Judá","Efraín"],"dato":"El libro termina en fiesta: Jehová, Rey de Israel en medio de su pueblo, apartó los juicios y echó fuera a los enemigos.","cita":"Sofonías 3:14","versiculo":"Canta, oh hija de Sión: da voces de júbilo, oh Israel; gózate y regocíjate de todo corazón, hija de Jerusalem.","vcita":"Sofonías 3:14","pista":"«Es el nombre poético del monte y la ciudad de Dios.»"}],"Hageo":[{"pregunta":"El mensaje de Hageo 1 llegó en el día veinticuatro del mes sexto, en el segundo año ¿de qué rey?","opciones":["Del rey Darío","Del rey Ciro","Del rey Artajerjes","Del rey Nabucodonosor"],"dato":"Hageo es uno de los libros mejor fechados de la Biblia: sus mensajes caen en el segundo año de Darío de Persia, hacia el 520 a. C.","cita":"Hageo 1:15","versiculo":"En el día veinte y cuatro del mes sexto, en el segundo año del rey Darío.","vcita":"Hageo 1:15","pista":"«Un rey persa, no babilonio ni judío.»"},{"pregunta":"¿A qué dos líderes fue dirigida la palabra de Jehová por medio de Hageo?","opciones":["A Zorobabel, gobernador de Judá, y a Josué, el gran sacerdote","A Esdras y a Nehemías","A David y a Salomón","A Elías y a Eliseo"],"dato":"Zorobabel era el gobernador, descendiente de David, y Josué hijo de Josadac era el sumo sacerdote: el poder civil y el religioso recibieron juntos la palabra.","cita":"Hageo 1:1","versiculo":"EN el año segundo del rey Darío en el mes sexto, en el primer día del mes, fué palabra de Jehová, por mano del profeta Haggeo, á Zorobabel hijo de Sealtiel, gobernador de Judá, y á Josué hijo de Josadac, gran sacerdote, diciendo:","vcita":"Hageo 1:1","pista":"«Uno gobernaba al pueblo y el otro servía en el templo.»"},{"pregunta":"«Este pueblo dice: No es aún venido el tiempo»: ¿el tiempo de hacer qué cosa, según Hageo 1:2?","opciones":["De que la casa de Jehová sea reedificada","De volver del cautiverio","De celebrar la pascua","De ungir un rey en Judá"],"dato":"Los judíos volvieron del exilio pero dejaron el templo en ruinas por años, siempre posponiendo la obra con esa excusa.","cita":"Hageo 1:2","versiculo":"Jehová de los ejércitos habla así, diciendo: Este pueblo dice: No es aún venido el tiempo, el tiempo de que la casa de Jehová sea reedificada.","vcita":"Hageo 1:2","pista":"«Para sus propias casas sí había tiempo de sobra.»"},{"pregunta":"Dios les reclama: ustedes moran en casas enmaderadas «y esta casa está...» ¿cómo?","opciones":["Desierta (en ruinas)","Llena de gloria","Sin terminar de pagar","Llena de ídolos"],"dato":"Casas con artesonado para ellos y ruinas para Dios: por eso la cosecha no rendía y nada les alcanzaba.","cita":"Hageo 1:4","versiculo":"¿Es para vosotros tiempo, para vosotros, de morar en vuestras casas enmaderadas, y esta casa está desierta?","vcita":"Hageo 1:4","pista":"«Lo contrario de habitada y cuidada.»"},{"pregunta":"Según Hageo 1:6, el que trabaja a jornal recibe su jornal ¿en qué, por lo que nada le rinde?","opciones":["En un saco roto (trapo horadado)","En monedas falsas","En manos de ladrones","En un pozo sin fondo"],"dato":"Sembrar mucho y cosechar poco, comer sin hartarse y ganar para echarlo en un saco agujereado: así era la vida con el templo abandonado.","cita":"Hageo 1:6","versiculo":"Sembráis mucho, y encerráis poco; coméis, y no os hartáis; bebéis, y no os saciáis; os vestís, y no os calentáis; y el que anda á jornal recibe su jornal en trapo horadado.","vcita":"Hageo 1:6","pista":"«Como guardar monedas en un bolsillo con agujeros.»"},{"pregunta":"«Subid al monte, y traed...» ¿qué debían traer para reedificar la casa de Jehová?","opciones":["Madera","Piedras preciosas","Harina y aceite","Oro y plata"],"dato":"La orden fue práctica: subir al monte, cortar madera y ponerse a edificar; Dios pondría en la casa su voluntad y sería honrado.","cita":"Hageo 1:8","versiculo":"Subid al monte, y traed madera, y reedificad la casa; y pondré en ella mi voluntad, y seré honrado, ha dicho Jehová.","vcita":"Hageo 1:8","pista":"«Sale de los árboles del monte.»"},{"pregunta":"¿Qué mensaje breve llevó Hageo al pueblo de parte de Jehová, según Hageo 1:13?","opciones":["«Yo soy con vosotros»","«Volved a Babilonia»","«Dejad la obra»","«Temed al rey Darío»"],"dato":"Con esas cuatro palabras Dios animó a los líderes y al pueblo, y despertó el espíritu de todos para ponerse a trabajar en su casa.","cita":"Hageo 1:13","versiculo":"Entonces Haggeo, enviado de Jehová, habló por mandado de Jehová, al pueblo, diciendo: Yo soy con vosotros, dice Jehová.","vcita":"Hageo 1:13","pista":"«Es la promesa de compañía que Dios repite en toda la Biblia.»"},{"pregunta":"«Mía es la plata, y mío es...»: ¿qué otro metal declara Dios como suyo en Hageo 2:8?","opciones":["El oro","El bronce","El hierro","El cobre"],"dato":"El templo nuevo parecía pobre comparado con el de Salomón, pero el Dueño de toda la plata y todo el oro llenaría esa casa de gloria.","cita":"Hageo 2:8","versiculo":"Mía es la plata, y mío el oro, dice Jehová de los ejércitos.","vcita":"Hageo 2:8","pista":"«La pareja clásica del metal blanco: el amarillo.»"},{"pregunta":"Según Hageo 2:9, ¿cómo será la gloria de la casa postrera comparada con la de la primera?","opciones":["Mayor que la de la primera","Igual que la de la primera","Menor, pero suficiente","Solo espiritual, sin gloria visible"],"dato":"Aunque el segundo templo parecía nada ante los ancianos que vieron el primero, Dios promete mayor gloria y paz en ese lugar.","cita":"Hageo 2:9","versiculo":"La gloria de aquesta casa postrera será mayor que la de la primera, ha dicho Jehová de los ejércitos; y daré paz en este lugar, dice Jehová de los ejércitos.","vcita":"Hageo 2:9","pista":"«Lo último superará a lo primero.»"},{"pregunta":"Según Hageo 2:7, cuando Dios haga temblar a todas las gentes, ¿quién vendrá y la casa será henchida de gloria?","opciones":["El Deseado de todas las gentes","El rey de Persia","Los exiliados de Egipto","Un ejército del norte"],"dato":"«El Deseado de todas las gentes» es una de las profecías mesiánicas más conocidas de Hageo, ligada a la gloria del templo postrero.","cita":"Hageo 2:7","versiculo":"Y haré temblar á todas las gentes, y vendrá el Deseado de todas las gentes; y henchiré esta casa de gloria, ha dicho Jehová de los ejércitos.","vcita":"Hageo 2:7","pista":"«Todos los pueblos lo anhelan, aunque no lo sepan.»"},{"pregunta":"Al final del libro, Dios promete tomar a Zorobabel y ponerlo ¿como qué, porque lo escogió?","opciones":["Como anillo de sellar","Como corona de oro","Como piedra angular","Como estrella de la mañana"],"dato":"El anillo de sellar era la firma personal del rey; Zorobabel, nieto del rey Jeconías, es restaurado como señal del linaje mesiánico.","cita":"Hageo 2:23","versiculo":"En aquel día, dice Jehová de los ejércitos, te tomaré, oh Zorobabel, hijo de Sealtiel, siervo mío, dice Jehová, y ponerte he como anillo de sellar: porque yo te escogí, dice Jehová de los ejércitos.","vcita":"Hageo 2:23","pista":"«Se lleva en el dedo y sirve para firmar con autoridad.»"},{"pregunta":"En Hageo 2:4, Dios manda «esfuérzate» tres veces: ¿a quiénes se lo dice?","opciones":["A Zorobabel, a Josué y a todo el pueblo de la tierra","A los reyes de las naciones","A los profetas solamente","A los sacerdotes y a los levitas"],"dato":"Gobernador, sumo sacerdote y pueblo entero reciben la misma orden: esforzarse y obrar, porque Jehová está con ellos.","cita":"Hageo 2:4","versiculo":"Pues ahora, Zorobabel, esfuérzate, dice Jehová; esfuérzate también Josué, hijo de Josadac, gran sacerdote; y cobra ánimo, pueblo todo de la tierra, dice Jehová, y obrad: porque yo soy con vosotros, dice Jehová de los ejércitos.","vcita":"Hageo 2:4","pista":"«Son los dos líderes del capítulo 1... más todo el mundo.»"}],"Zacarías":[{"pregunta":"Completa la palabra de Jehová a Zorobabel: «No con ejército, ni con fuerza, sino con...»","opciones":["Mi espíritu","Muchas oraciones","La espada de Judá","La ayuda de Persia"],"dato":"La obra del templo no se terminaría por poder humano, sino por el Espíritu de Dios: es el versículo más famoso de Zacarías.","cita":"Zacarías 4:6","versiculo":"Entonces respondió y hablóme, diciendo: Esta es palabra de Jehová á Zorobabel, en que se dice: No con ejército, ni con fuerza, sino con mi espíritu, ha dicho Jehová de los ejércitos.","vcita":"Zacarías 4:6","pista":"«Ni soldados ni músculo: la tercera Persona de la Trinidad.»"},{"pregunta":"Según Zacarías 9:9, el Rey vendrá justo y salvador, humilde, ¿cabalgando sobre qué animal?","opciones":["Sobre un asno, un pollino hijo de asna","Sobre un caballo blanco","Sobre un carro de guerra","Sobre un camello real"],"dato":"Esta profecía se cumplió cuando Jesús entró en Jerusalén montado en un pollino, y los evangelios la citan directamente.","cita":"Zacarías 9:9","versiculo":"Alégrate mucho, hija de Sión; da voces de júbilo, hija de Jerusalem: he aquí, tu rey vendrá á ti, justo y salvador, humilde, y cabalgando sobre un asno, así sobre un pollino hijo de asna.","vcita":"Zacarías 9:9","pista":"«No es el caballo del guerrero: es la montura humilde del Rey de paz.»"},{"pregunta":"En la actuación profética de Zacarías 11, ¿cuántas piezas de plata pesaron como su salario?","opciones":["Treinta piezas de plata","Cuarenta piezas de plata","Doce piezas de plata","Cien piezas de plata"],"dato":"El profeta echó ese «hermoso precio» en la casa de Jehová, al tesorero; Judas recibiría la misma cantidad por entregar a Jesús.","cita":"Zacarías 11:12","versiculo":"Y díjeles: Si os parece bien, dadme mi salario; y si no, dejadlo. Y pesaron para mi salario treinta [piezas] de plata.","vcita":"Zacarías 11:12","pista":"«Es la misma cantidad por la que Judas entregó a Jesús.»"},{"pregunta":"En la visión de Zacarías 3, Josué el gran sacerdote estaba delante del ángel con ¿qué tipo de vestimentas, que luego le fueron quitadas?","opciones":["Vestimentas viles (sucias)","Vestimentas de luto","Vestimentas de extranjero","Vestimentas rotas de guerra"],"dato":"Satanás lo acusaba a su mano derecha, pero Dios lo defendió: le quitaron las ropas sucias y lo vistieron de gala, símbolo del perdón.","cita":"Zacarías 3:4","versiculo":"Y habló el [ángel], é intimó á los que estaban delante de sí, diciendo: Quitadle esas vestimentas viles. Y á él dijo: Mira que he hecho pasar tu pecado de ti, y te he hecho vestir de ropas de gala.","vcita":"Zacarías 3:4","pista":"«Representan el pecado que Dios le quitó de encima.»"},{"pregunta":"Según Zacarías 2:5, ¿qué sería Jehová para Jerusalén, si la ciudad sería habitada sin muros?","opciones":["Muro de fuego en derredor","Una torre de piedra","Un ejército de ángeles acampado","Un río que la rodea"],"dato":"Jerusalén crecería tanto que no cabría entre murallas; su defensa y su gloria sería el propio Jehová en medio de ella.","cita":"Zacarías 2:5","versiculo":"Yo seré para ella, dice Jehová, muro de fuego en derredor, y seré por gloria en medio de ella.","vcita":"Zacarías 2:5","pista":"«Una muralla que ningún enemigo puede tocar: arde.»"},{"pregunta":"«He aquí el varón cuyo nombre es...»: ¿qué nombre da Zacarías 6:12 al que edificará el templo de Jehová?","opciones":["El Pimpollo","El León de Judá","El Siervo Sufriente","El Hijo del Hombre"],"dato":"El Pimpollo (otras versiones dicen «el Renuevo») germinaría de su lugar, edificaría el templo y sería sacerdote en su trono.","cita":"Zacarías 6:12","versiculo":"Y le hablarás, diciendo: Así ha hablado Jehová de los ejércitos, diciendo: He aquí el varón cuyo nombre es Pimpollo, el cual germinará de su lugar, y edificará el templo de Jehová:","vcita":"Zacarías 6:12","pista":"«Es el brote nuevo que sale del tronco cortado.»"},{"pregunta":"En su primera visión nocturna, Zacarías vio un varón sobre un caballo bermejo que estaba ¿entre qué plantas?","opciones":["Entre los mirtos","Entre las palmeras","Entre los cedros del Líbano","Entre las higueras"],"dato":"Detrás del varón había caballos bermejos, overos y blancos: eran los enviados de Jehová a recorrer la tierra, que estaba reposada y quieta.","cita":"Zacarías 1:8","versiculo":"Vi de noche, y he aquí un varón que cabalgaba sobre un caballo bermejo, el cual estaba entre los mirtos que había en la hondura; y detrás de él había caballos bermejos, overos, y blancos.","vcita":"Zacarías 1:8","pista":"«Unos arbustos fragantes en lo hondo del valle.»"},{"pregunta":"El rollo que volaba en la visión de Zacarías 5, ¿qué medidas tenía?","opciones":["Veinte codos de largo y diez de ancho","Diez codos de largo y cinco de ancho","Cien codos de largo y uno de ancho","Siete codos de largo y siete de ancho"],"dato":"Ese rollo era la maldición que salía sobre la tierra contra el que hurta y el que jura falsamente: sus medidas eran las del pórtico del templo.","cita":"Zacarías 5:2","versiculo":"Y díjome: ¿Qué ves? Y respondí: Veo un rollo que vuela, de veinte codos de largo, y diez codos de ancho.","vcita":"Zacarías 5:2","pista":"«El largo es exactamente el doble del ancho.»"},{"pregunta":"Según Zacarías 14:9, en aquel día Jehová será Rey ¿sobre qué extensión?","opciones":["Sobre toda la tierra","Solo sobre Judá","Sobre las doce tribus","Sobre Jerusalén y sus alrededores"],"dato":"El capítulo 14 cierra con el reino universal: «Jehová será uno, y uno su nombre» sobre toda la tierra.","cita":"Zacarías 14:9","versiculo":"Y Jehová será rey sobre toda la tierra. En aquel día Jehová será uno, y uno su nombre.","vcita":"Zacarías 14:9","pista":"«No un reino local: el planeta entero.»"},{"pregunta":"Según Zacarías 8:23, ¿cuántos hombres de todas las lenguas se agarrarán de la falda de un judío diciendo «iremos con vosotros»?","opciones":["Diez hombres","Setenta hombres","Doce hombres","Tres hombres"],"dato":"Las naciones buscarían a Jehová en Jerusalén y se asirían de un judío porque habían oído que Dios estaba con su pueblo.","cita":"Zacarías 8:23","versiculo":"Así ha dicho Jehová de los ejércitos: En aquellos días [acontecerá] que diez hombres de todas las lenguas de las gentes, trabarán de la falda de un Judío, diciendo: Iremos con vosotros, porque hemos oído que Dios está con vosotros.","vcita":"Zacarías 8:23","pista":"«Es el número de los dedos de las dos manos.»"},{"pregunta":"Según Zacarías 13:9, la tercera parte que quede pasará por el fuego y será probada ¿como qué metal precioso?","opciones":["Como se prueba el oro","Como se funde el bronce","Como se pule el hierro","Como se templa el acero"],"dato":"Dios fundiría al remanente como se funde la plata y lo probaría como el oro; ellos invocarían su nombre y él diría: «Pueblo mío».","cita":"Zacarías 13:9","versiculo":"Y meteré en el fuego la tercera parte, y los fundiré como se funde la plata, y probarélos como se prueba el oro. El invocará mi nombre, y yo le oiré, y diré: Pueblo mío; y él dirá: Jehová es mi Dios.","vcita":"Zacarías 13:9","pista":"«El metal amarillo que sale puro del crisol.»"}],"Malaquías":[{"pregunta":"Al traer todos los diezmos al alfolí, Dios reta a su pueblo: «probadme ahora en esto», ¿y qué promete abrir?","opciones":["Las ventanas de los cielos","Las puertas del templo","Las compuertas de los ríos","Los graneros de Egipto"],"dato":"Es la única vez que Dios invita a ser probado: derramaría bendición hasta que sobreabunde sobre el pueblo fiel en los diezmos.","cita":"Malaquías 3:10","versiculo":"Traed todos los diezmos al alfolí, y haya alimento en mi casa; y probadme ahora en esto, dice Jehová de los ejércitos, si no os abriré las ventanas de los cielos, y vaciaré sobre vosotros bendición hasta que sobreabunde.","vcita":"Malaquías 3:10","pista":"«No llaves ni puertas: lo que se abre está en el cielo.»"},{"pregunta":"«¿Robará el hombre a Dios?» Según Malaquías 3:8, ¿en qué le había robado el pueblo?","opciones":["En los diezmos y las primicias","En los sacrificios de animales","En las fiestas no celebradas","En la madera del templo"],"dato":"La nación entera retenía lo que era de Dios; por eso la maldición pesaba sobre sus cosechas y el devorador arruinaba el fruto.","cita":"Malaquías 3:8","versiculo":"¿Robará el hombre á Dios? Pues vosotros me habéis robado. Y dijisteis: ¿En qué te hemos robado? Los diezmos y las primicias.","vcita":"Malaquías 3:8","pista":"«Es la décima parte... y las ofrendas.»"},{"pregunta":"Según Malaquías 4:2, para los que temen el nombre de Jehová nacerá ¿qué, con salud en sus alas?","opciones":["El Sol de justicia","La estrella de la mañana","La luna llena de la cosecha","El arco iris del pacto"],"dato":"Mientras los soberbios serán estopa en el horno del día venidero, los que temen a Dios saltarán como becerros de la manada bajo ese Sol.","cita":"Malaquías 4:2","versiculo":"Mas á vosotros los que teméis mi nombre, nacerá el Sol de justicia, y en sus alas [traerá] salud: y saldréis, y saltaréis como becerros de la manada.","vcita":"Malaquías 4:2","pista":"«Brilla de día, trae justicia... y cura.»"},{"pregunta":"¿A quién promete Dios enviar antes que venga el día de Jehová, grande y terrible, según Malaquías 4:5?","opciones":["A Elías el profeta","A un nuevo Moisés","Al rey David","A Eliseo, su sucesor"],"dato":"La profecía señala literalmente a Elías; Jesús enseñó que Juan el Bautista vino en el espíritu de Elías para preparar el camino.","cita":"Malaquías 4:5","versiculo":"He aquí, yo os envío á Elías el profeta, antes que venga el día de Jehová grande y terrible.","vcita":"Malaquías 4:5","pista":"«El profeta del Carmelo y del arroyo de Querit.»"},{"pregunta":"Según Malaquías 4:6, ese profeta enviado convertirá el corazón de los padres ¿hacia quién?","opciones":["Hacia los hijos","Hacia el templo","Hacia la ley antigua","Hacia los sacerdotes"],"dato":"El Antiguo Testamento cierra con una promesa de reconciliación familiar: padres e hijos vueltos unos a otros antes del gran día.","cita":"Malaquías 4:6","versiculo":"El convertirá el corazón de los padres á los hijos, y el corazón de los hijos á los padres: no sea que yo venga, y con destrucción hiera la tierra.","vcita":"Malaquías 4:6","pista":"«Es reconciliación entre dos generaciones de la familia.»"},{"pregunta":"¿Qué clase de animales ofrecían los sacerdotes sobre el altar, que Dios rechazó en Malaquías 1:8?","opciones":["El ciego, el cojo y el enfermo","Solo los más gordos","Animales de otros pueblos","Primicias de la cosecha"],"dato":"Dios los retó: «Preséntalo a tu príncipe: ¿acaso se agradará de ti?» Lo defectuoso, lo robado y lo dañado no honra al Gran Rey.","cita":"Malaquías 1:8","versiculo":"Y cuando ofrecéis el [animal] ciego para sacrificar, ¿no es malo? asimismo cuando ofrecéis el cojo ó el enfermo, ¿no es malo? Preséntalo pues á tu príncipe: ¿acaso se agradará de ti, ó le serás acepto? dice Jehová de los ejércitos.","vcita":"Malaquías 1:8","pista":"«Le daban a Dios lo que nadie más querría recibir.»"},{"pregunta":"Según Malaquías 2:7, los labios del sacerdote han de guardar ¿qué cosa?","opciones":["La sabiduría (el conocimiento)","El silencio absoluto","Las ofrendas del pueblo","Los secretos del rey"],"dato":"El sacerdote es mensajero de Jehová de los ejércitos: de su boca el pueblo debía buscar la ley; los de Malaquías, en cambio, hacían tropezar a muchos.","cita":"Malaquías 2:7","versiculo":"Porque los labios de los sacerdotes han de guardar la sabiduría, y de su boca buscarán la ley; porque mensajero es de Jehová de los ejércitos.","vcita":"Malaquías 2:7","pista":"«De su boca el pueblo buscaba la ley.»"},{"pregunta":"Según Malaquías 3:1, el mensajero que Dios envía ¿qué hará delante de él?","opciones":["Preparará el camino","Edificará el templo","Derrotará a los ejércitos","Escribirá un nuevo libro"],"dato":"Esta profecía abre el camino al Nuevo Testamento: el mensajero es Juan el Bautista, y el Señor vendría luego a su templo.","cita":"Malaquías 3:1","versiculo":"HE aquí, yo envío mi mensajero, el cual preparará el camino delante de mí: y luego vendrá á su templo el Señor á quien vosotros buscáis, y el ángel del pacto, á quien deseáis vosotros. He aquí viene, ha dicho Jehová de los ejércitos.","vcita":"Malaquías 3:1","pista":"«Marcos abre su evangelio citando este anuncio.»"},{"pregunta":"Según Malaquías 3:16, ¿qué fue escrito delante de Dios para los que le temen y piensan en su nombre?","opciones":["Un libro de memoria","Una ley nueva","La lista de los sacerdotes","Un canto de victoria"],"dato":"Mientras unos decían que servir a Dios no aprovechaba, los que le temían hablaban entre sí, y Dios escuchó y lo dejó registrado.","cita":"Malaquías 3:16","versiculo":"Entonces los que temen á Jehová hablaron cada uno á su compañero; y Jehová escuchó y oyó, y fué escrito libro de memoria delante de él para los que temen á Jehová, y para los que piensan en su nombre.","vcita":"Malaquías 3:16","pista":"«Dios lleva registro escrito de los suyos.»"},{"pregunta":"Según Malaquías 3:17, los que temen a Jehová serán para él ¿qué cosa especial en el día que él haga?","opciones":["Su especial tesoro","Su ejército escogido","Sus sacerdotes eternos","Su pueblo más numeroso"],"dato":"Dios los perdonará como un padre perdona al hijo que le sirve; entonces se verá la diferencia entre el justo y el malo.","cita":"Malaquías 3:17","versiculo":"Y serán para mí especial tesoro, ha dicho Jehová de los ejércitos, en el día que yo tengo de hacer: y perdonarélos como el hombre que perdona á su hijo que le sirve.","vcita":"Malaquías 3:17","pista":"«Lo más valioso que un rey guarda en su casa.»"},{"pregunta":"El libro abre con Dios diciendo «Yo os he amado». ¿A quién amó y a quién aborreció, según Malaquías 1:2-3?","opciones":["Amó a Jacob y aborreció a Esaú","Amó a Esaú y aborreció a Jacob","Amó a Judá y aborreció a Israel","Amó a Leví y aborreció a Judá"],"dato":"Jacob y Esaú eran hermanos gemelos; Dios escogió a Jacob y la descendencia de Esaú, Edom, quedaría asolada pese a sus esfuerzos por reedificar.","cita":"Malaquías 1:2-3","versiculo":"Yo os he amado, dice Jehová: y dijisteis: ¿En qué nos amaste? ¿No era Esaú hermano de Jacob, dice Jehová, y amé á Jacob, Y á Esaú aborrecí, y torné sus montes en asolamiento, y su posesión para los chacales del desierto?","vcita":"Malaquías 1:2-3","pista":"«Dos gemelos del Génesis: el escogido fue el menor.»"}],"Romanos":[{"pregunta":"Según Romanos 1, ¿de qué dice Pablo que no se avergüenza, porque es poder de Dios para salvación?","opciones":["Del evangelio de Cristo","De sus cadenas en Roma","De su ciudadanía romana","De la ley de Moisés"],"dato":"Pablo abre su carta afirmando que no se avergüenza del evangelio: es el poder de Dios para salvar a todo el que cree, al judío primeramente y también al griego.","cita":"Romanos 1:16","versiculo":"Porque no me avergüenzo del evangelio: porque es potencia de Dios para salud a todo aquel que cree; al Judío primeramente y también al Griego.","vcita":"Romanos 1:16","pista":"«Es la buena noticia que Pablo llevaba por todo el imperio.»"},{"pregunta":"¿Cuál es, según Pablo, la condición de TODOS los hombres delante de Dios?","opciones":["Todos pecaron y están destituidos de la gloria de Dios","Solo los gentiles están destituidos de la gloria de Dios","Los que guardan la ley alcanzan por sí mismos la gloria de Dios","Cada uno será juzgado únicamente por sus buenas obras"],"dato":"Pablo nivela a judíos y gentiles: todos pecaron y están destituidos de la gloria de Dios; nadie puede justificarse por sus propios méritos.","cita":"Romanos 3:23","versiculo":"Por cuanto todos pecaron, y están destituidos de la gloria de Dios;","vcita":"Romanos 3:23","pista":"«Nadie queda fuera: ni el judío ni el griego.»"},{"pregunta":"Según Romanos 4, ¿qué le fue contado a Abraham por justicia?","opciones":["Que creyó a Dios","Que ofreció a su hijo Isaac","Que guardó la ley perfectamente","Que construyó altares en Canaán"],"dato":"Pablo cita Génesis 15:6 para mostrar que Abraham fue justificado por la fe, mucho antes de la ley y de la circuncisión.","cita":"Romanos 4:3","versiculo":"Porque ¿qué dice la Escritura? Y creyó Abraham a Dios, y le fue atribuido a justicia.","vcita":"Romanos 4:3","pista":"«Es el ejemplo del padre de la fe.»"},{"pregunta":"¿Cómo demostró Dios su amor para con nosotros, según Romanos 5?","opciones":["En que siendo aún pecadores, Cristo murió por nosotros","En que nos libra de todo sufrimiento terrenal","En que nos promete riquezas y salud","En que nunca permite que seamos probados"],"dato":"El amor de Dios no esperó a que fuéramos buenos: Cristo murió por nosotros cuando aún éramos pecadores.","cita":"Romanos 5:8","versiculo":"Mas Dios encarece su caridad para con nosotros, porque siendo aún pecadores, Cristo murió por nosotros.","vcita":"Romanos 5:8","pista":"«No esperó a que fuéramos buenos.»"},{"pregunta":"Según Pablo, ¿cuál es la paga del pecado y cuál es la dádiva de Dios?","opciones":["La paga es muerte; la dádiva, vida eterna en Cristo Jesús","La paga es enfermedad; la dádiva, prosperidad","La paga es vergüenza; la dádiva, buena fama","La paga es trabajo; la dádiva, descanso temporal"],"dato":"El pecado paga un salario que se gana: la muerte; Dios, en cambio, regala lo que nadie puede ganar: vida eterna en Cristo Jesús.","cita":"Romanos 6:23","versiculo":"Porque la paga del pecado es muerte: mas la dádiva de Dios es vida eterna en Cristo Jesús Señor nuestro.","vcita":"Romanos 6:23","pista":"«Un salario ganado frente a un regalo inmerecido.»"},{"pregunta":"Según Romanos 8, ¿qué NO hay para los que están en Cristo Jesús?","opciones":["Ninguna condenación","Ninguna prueba","Ninguna debilidad","Ningún enemigo"],"dato":"El capítulo 8 de Romanos abre quitando la sentencia: ninguna condenación hay para los que están en Cristo Jesús.","cita":"Romanos 8:1","versiculo":"Ahora pues, ninguna condenación hay para los que están en Cristo Jesús, los que no andan conforme a la carne, mas conforme al espíritu.","vcita":"Romanos 8:1","pista":"«El capítulo empieza borrando la sentencia.»"},{"pregunta":"Según la promesa de Romanos 8, ¿a quiénes les ayudan todas las cosas a bien?","opciones":["A los que aman a Dios, los llamados conforme a su propósito","A los que nunca sufren pérdidas","Solamente a los apóstoles y profetas","A los que cumplen perfectamente la ley"],"dato":"La promesa no dice que todo lo que pasa sea bueno, sino que Dios hace que todas las cosas ayuden a bien a los que le aman.","cita":"Romanos 8:28","versiculo":"Y sabemos que a los que a Dios aman, todas las cosas les ayudan a bien, es a saber, a los que conforme al propósito son llamados.","vcita":"Romanos 8:28","pista":"«No dice que todo sea bueno, sino que todo ayuda.»"},{"pregunta":"Según Pablo, ¿qué cosas está cierto que NO podrán separarnos del amor de Dios?","opciones":["Ni la muerte, ni la vida, ni ángeles, ni principados","Ni el hambre, ni la sed, ni el frío","Ni los reyes, ni los ejércitos de la tierra","Ni la noche, ni el día, ni las estaciones"],"dato":"Pablo pasa lista en Romanos 8: ni la muerte ni la vida, ni ángeles ni potestades, ni lo presente ni lo por venir podrá separarnos del amor de Dios.","cita":"Romanos 8:38","versiculo":"Por lo cual estoy cierto que ni la muerte, ni la vida, ni ángeles, ni principados, ni potestades, ni lo presente, ni lo por venir,","vcita":"Romanos 8:38","pista":"«Pablo pasa lista y nada logra separarnos.»"},{"pregunta":"Según Romanos 12, ¿cómo debe ser transformado el creyente en vez de conformarse a este siglo?","opciones":["Por la renovación de su entendimiento","Por cambiar de ciudad y de costumbres","Por dejar todo trabajo secular","Por guardar fiestas y sábados"],"dato":"La transformación del creyente empieza por dentro: renovar el entendimiento para experimentar cuál es la buena voluntad de Dios.","cita":"Romanos 12:2","versiculo":"Y no os conforméis a este siglo; mas reformaos por la renovación de vuestro entendimiento, para que experimentéis cuál sea la buena voluntad de Dios, agradable y perfecta.","vcita":"Romanos 12:2","pista":"«La transformación empieza por la mente.»"},{"pregunta":"¿Cómo se llamaba la diaconisa de la iglesia de Cencrea a quien Pablo encomienda al final de Romanos?","opciones":["Febe","Priscila","Lidia","María Magdalena"],"dato":"Febe, hermana y diaconisa de la iglesia de Cencrea, encabeza la lista de saludos de Romanos 16; muchos creen que ella misma llevó la carta hasta Roma.","cita":"Romanos 16:1","versiculo":"Encomiendoos empero a Febe nuestra hermana, la cual es diaconisa de la iglesia que está en Cencreas:","vcita":"Romanos 16:1","pista":"«Probablemente ella misma cargó esta carta hasta Roma.»"}],"1 Corintios":[{"pregunta":"Al principio de 1 Corintios, Pablo reprende las divisiones: además de Pablo y de Cristo, ¿de quiénes decían algunos «yo soy»?","opciones":["De Apolos y de Cefas","De Bernabé y de Silas","De Timoteo y de Tito","De Juan y de Santiago"],"dato":"La iglesia de Corinto se había partido en bandos según el maestro que cada uno admiraba: Pablo, Apolos, Cefas o el propio Cristo.","cita":"1 Corintios 1:12","versiculo":"Quiero decir, que cada uno de vosotros dice: Yo cierto soy de Pablo; pues yo de Apolos; y yo de Cefas; y yo de Cristo.","vcita":"1 Corintios 1:12","pista":"«Uno regaba en Corinto; el otro era Simón Pedro.»"},{"pregunta":"Completa lo que está escrito según 1 Corintios 2: «Cosas que ojo no vio, ni oreja oyó… son las que Dios ha preparado para…»","opciones":["Los que le aman","Los sabios de este mundo","Los que guardan la ley","Los profetas de la antigüedad"],"dato":"Pablo cita este texto para hablar de lo que el Espíritu revela: lo que Dios preparó para los que le aman supera lo que ojo y oído pueden alcanzar.","cita":"1 Corintios 2:9","versiculo":"Antes, como está escrito: Cosas que ojo no vio, ni oreja oyó, ni han subido en corazón de hombre, son las que ha Dios preparado para aquellos que le aman.","vcita":"1 Corintios 2:9","pista":"«La medida no es la sabiduría, sino el amor a Dios.»"},{"pregunta":"Con su figura del campo, ¿quién dice Pablo que REGÓ lo que él había plantado en Corinto?","opciones":["Apolos","Pedro","Timoteo","Aquila"],"dato":"«Yo planté, Apolos regó: mas Dios ha dado el crecimiento»: los dos son servidores; el crecimiento es obra de Dios.","cita":"1 Corintios 3:6","versiculo":"Yo planté, Apolos regó: mas Dios ha dado el crecimiento.","vcita":"1 Corintios 3:6","pista":"«El mismo del que algunos decían «yo soy de…».»"},{"pregunta":"¿Qué usa Pablo como figura de cómo un poco de pecado contamina a toda la iglesia?","opciones":["Un poco de levadura que leuda toda la masa","Una manzana podrida dentro del cesto","Una gota de tinta en el agua limpia","Una zorra pequeña que echa a perder las viñas"],"dato":"Ante un caso grave de inmoralidad, Pablo advierte que un poco de levadura leuda toda la masa; por eso la iglesia debía actuar sin orgullo.","cita":"1 Corintios 5:6","versiculo":"No es buena vuestra jactancia. ¿No sabéis que un poco de levadura leuda toda la masa?","vcita":"1 Corintios 5:6","pista":"«Lo que esponja el pan entero con solo un poquito.»"},{"pregunta":"Según 1 Corintios 6, ¿qué es el cuerpo del creyente?","opciones":["Templo del Espíritu Santo","Una cárcel de la que el alma escapa","Propiedad absoluta de cada uno","Un vaso desechable sin valor"],"dato":"Pablo enseña que el cuerpo del creyente es templo del Espíritu Santo que está en él, y que ya no se pertenece a sí mismo.","cita":"1 Corintios 6:19","versiculo":"¿O ignoráis que vuestro cuerpo es templo del Espíritu Santo, el cual está en vosotros, el cual tenéis de Dios, y que no sois vuestros?","vcita":"1 Corintios 6:19","pista":"«Un santuario que camina.»"},{"pregunta":"En su figura del estadio, ¿qué clase de corona buscan los atletas, frente a la del creyente?","opciones":["Ellos una corruptible; nosotros, incorruptible","Ellos una de oro; nosotros, de plata","Ellos una de olivo; nosotros, de piedras preciosas","Ellos una temporal; nosotros, ninguna corona"],"dato":"Pablo compara la disciplina del atleta con la vida cristiana: ellos se abstienen de todo por una corona que se marchita; el creyente, por una incorruptible.","cita":"1 Corintios 9:25","versiculo":"Y todo aquel que lucha, de todo se abstiene: y ellos, a la verdad, para recibir una corona corruptible; mas nosotros, incorruptible.","vcita":"1 Corintios 9:25","pista":"«Una se marchita en días; la otra dura para siempre.»"},{"pregunta":"Según 1 Corintios 10, ¿qué provee Dios siempre junto con la tentación?","opciones":["La salida, para que podamos aguantar","Una señal visible en el cielo","La visita de un ángel","El fin inmediato de toda dificultad"],"dato":"Dios es fiel: no permitirá que seamos tentados más de lo que podemos llevar, y juntamente con la tentación dará también la salida.","cita":"1 Corintios 10:13","versiculo":"No os ha tomado tentación, sino humana: mas fiel es Dios, que no os dejará ser tentados más de lo que podéis llevar; antes dará también juntamente con la tentación la salida, para que podáis aguantar.","vcita":"1 Corintios 10:13","pista":"«Nunca hay tentación sin puerta de escape.»"},{"pregunta":"Según Pablo, ¿qué hacemos cada vez que comemos del pan y bebemos de la copa en la Cena del Señor?","opciones":["Anunciamos la muerte del Señor hasta que él venga","Recordamos únicamente la salida de Egipto","Celebramos el nacimiento de Cristo","Consagramos los alimentos del día"],"dato":"La Cena del Señor es proclamación: todas las veces que participamos, anunciamos la muerte del Señor hasta que él venga.","cita":"1 Corintios 11:26","versiculo":"Porque todas las veces que comiereis este pan, y bebiereis esta copa, la muerte del Señor anunciáis hasta que venga.","vcita":"1 Corintios 11:26","pista":"«Un sermón que se come y se bebe.»"},{"pregunta":"En la figura del cuerpo, ¿qué miembro dice Pablo que no puede decir a la mano: «No te he menester»?","opciones":["El ojo","El oído","El pie","La boca"],"dato":"Ningún miembro puede despreciar a otro: ni el ojo a la mano, ni la cabeza a los pies; todos son necesarios en el cuerpo de Cristo.","cita":"1 Corintios 12:21","versiculo":"Ni el ojo puede decir a la mano: No te he menester: ni asimismo la cabeza a los pies: No tengo necesidad de vosotros.","vcita":"1 Corintios 12:21","pista":"«Es el que ve, pero sin la mano no puede tomar nada.»"},{"pregunta":"Según 1 Corintios 15, ¿qué es el aguijón de la muerte?","opciones":["El pecado","La enfermedad","La vejez","El temor humano"],"dato":"«El aguijón de la muerte es el pecado, y la potencia del pecado, la ley»: por eso la resurrección de Cristo le quita a la muerte su veneno.","cita":"1 Corintios 15:56","versiculo":"Ya que el aguijón de la muerte es el pecado, y la potencia del pecado, la ley.","vcita":"1 Corintios 15:56","pista":"«Es lo que le da a la muerte su picadura mortal.»"},{"pregunta":"¿Qué palabra usa Pablo al cerrar 1 Corintios, un clamor que significa «¡Ven, Señor!»?","opciones":["Maranatha","Talita cumi","Raca","Effata"],"dato":"Pablo cierra con advertencia y esperanza: quien no amare al Señor Jesucristo, sea anatema; y proclama «Maranatha»: el Señor viene.","cita":"1 Corintios 16:22","versiculo":"El que no amare al Señor Jesucristo, sea anatema. Maranatha.","vcita":"1 Corintios 16:22","pista":"«Era el saludo de esperanza de la iglesia primitiva.»"}],"2 Corintios":[{"pregunta":"¿Con qué doble título bendice Pablo a Dios al abrir 2 Corintios?","opciones":["Padre de misericordias y Dios de toda consolación","Juez de toda la tierra y Rey de reyes","Creador del cielo y de la tierra","El Dios de Abraham, de Isaac y de Jacob"],"dato":"Dios consuela a los suyos en todas sus tribulaciones, para que también ellos puedan consolar a otros con el mismo consuelo recibido.","cita":"2 Corintios 1:3","versiculo":"Bendito sea el Dios y Padre del Señor Jesucristo, el Padre de misericordias, y el Dios de toda consolación,","vcita":"2 Corintios 1:3","pista":"«Su consuelo no es para guardarlo: es para compartirlo.»"},{"pregunta":"Según 2 Corintios 4, ¿dónde llevamos el tesoro del evangelio?","opciones":["En vasos de barro","En cofres de oro","En tablas de piedra","En templos de mármol"],"dato":"El tesoro va en vasos de barro para que la alteza del poder sea de Dios y no de nosotros.","cita":"2 Corintios 4:7","versiculo":"Tenemos empero este tesoro en vasos de barro, para que la alteza del poder sea de Dios, y no de nosotros:","vcita":"2 Corintios 4:7","pista":"«El envase es frágil a propósito.»"},{"pregunta":"Completa la frase de Pablo: «Porque por fe andamos, no por…»","opciones":["Vista","Obras de la ley","Sentimientos","Tradiciones"],"dato":"Mientras estamos ausentes del Señor en el cuerpo, andamos por fe y no por vista, confiando en lo que aún no vemos.","cita":"2 Corintios 5:7","versiculo":"(Porque por fe andamos, no por vista;)","vcita":"2 Corintios 5:7","pista":"«Caminar creyendo lo que los ojos aún no alcanzan.»"},{"pregunta":"Según Pablo, ¿qué es el que está en Cristo?","opciones":["Nueva criatura: las cosas viejas pasaron","Un prosélito más de los judíos","Un esclavo renovado de la ley","Un ciudadano romano con privilegios"],"dato":"Si alguno está en Cristo, nueva criatura es: las cosas viejas pasaron y todas son hechas nuevas.","cita":"2 Corintios 5:17","versiculo":"De modo que si alguno está en Cristo, nueva criatura es: las cosas viejas pasaron; he aquí todas son hechas nuevas.","vcita":"2 Corintios 5:17","pista":"«No es un arreglo del pasado: es un comienzo nuevo.»"},{"pregunta":"En 2 Corintios 5, ¿cómo llama Pablo a los que anuncian la reconciliación con Dios?","opciones":["Embajadores en nombre de Cristo","Heraldos del imperio romano","Escribas expertos en la ley","Guardias del templo de Jerusalén"],"dato":"Dios nos encargó la palabra de la reconciliación; somos embajadores, como si Dios rogase por medio nuestro: «Reconciliaos con Dios».","cita":"2 Corintios 5:20","versiculo":"Así que, somos embajadores en nombre de Cristo, como si Dios rogase por medio nuestro; os rogamos en nombre de Cristo: Reconciliaos con Dios.","vcita":"2 Corintios 5:20","pista":"«Representantes con un mensaje urgente del Rey.»"},{"pregunta":"Según 2 Corintios 7, ¿qué produce el dolor (la tristeza) del mundo?","opciones":["Muerte","Arrepentimiento para salvación","Gozo duradero","Paciencia y sabiduría"],"dato":"Hay dos dolores: el que es según Dios obra arrepentimiento saludable para salvación; el dolor del siglo solo obra muerte.","cita":"2 Corintios 7:10","versiculo":"Porque el dolor que es según Dios, obra arrepentimiento saludable, de que no hay que arrepentirse; mas el dolor del siglo obra muerte.","vcita":"2 Corintios 7:10","pista":"«Una tristeza lleva a la vida; la otra, a lo contrario.»"},{"pregunta":"¿Qué iglesias pusieron el gran ejemplo de dar con liberalidad en medio de su profunda pobreza?","opciones":["Las iglesias de Macedonia","Las iglesias de Galacia","Las siete iglesias de Asia","La iglesia de Antioquía"],"dato":"Los macedonios, en grande prueba de tribulación, abundaron en riquezas de generosidad y rogaron a Pablo que les permitiera participar en la ofrenda.","cita":"2 Corintios 8:2","versiculo":"Que en grande prueba de tribulación, la abundancia de su gozo y su profunda pobreza abundaron en riquezas de su bondad.","vcita":"2 Corintios 8:2","pista":"«Filipos y Tesalónica quedaban en esa región.»"},{"pregunta":"Según 2 Corintios 9, ¿a qué clase de dador ama Dios?","opciones":["Al dador alegre","Al que da la mayor cantidad","Al que da por obligación","Al que da esperando recibir más"],"dato":"Cada uno dé como propuso en su corazón: no con tristeza ni por necesidad, porque Dios ama al dador alegre.","cita":"2 Corintios 9:7","versiculo":"Cada uno dé como propuso en su corazón: no con tristeza, o por necesidad; porque Dios ama el dador alegre.","vcita":"2 Corintios 9:7","pista":"«La actitud del corazón vale más que la cantidad.»"},{"pregunta":"Según 2 Corintios 11, ¿en qué se transfigura el mismo Satanás para engañar?","opciones":["En ángel de luz","En un cordero manso","En un profeta anciano","En una estrella del cielo"],"dato":"Pablo desenmascara a los falsos apóstoles: no es maravilla que sus ministros se disfracen, si el mismo Satanás se transfigura en ángel de luz.","cita":"2 Corintios 11:14","versiculo":"Y no es maravilla, porque el mismo Satanás se transfigura en ángel de luz.","vcita":"2 Corintios 11:14","pista":"«El engaño más peligroso viene disfrazado de brillo.»"},{"pregunta":"¿Qué le fue dado a Pablo para que la grandeza de las revelaciones no lo enalteciera?","opciones":["Un aguijón en su carne, un mensajero de Satanás","Una ceguera permanente desde su conversión","La orden de no salir de Corinto","Un compañero que vigilaba sus escritos"],"dato":"Pablo rogó tres veces que le fuera quitado su aguijón en la carne, un mensajero de Satanás que lo abofeteaba; la respuesta fue gracia suficiente.","cita":"2 Corintios 12:7","versiculo":"Y porque la grandeza de las revelaciones no me levante descomedidamente, me es dado un aguijón en mi carne, un mensajero de Satanás que me abofetee, para que no me enaltezca sobremanera.","vcita":"2 Corintios 12:7","pista":"«Una espina que le recordaba su debilidad cada día.»"},{"pregunta":"¿Qué le respondió el Señor a Pablo cuando rogó que le quitara el aguijón?","opciones":["«Bástate mi gracia; porque mi potencia en la flaqueza se perfecciona»","«Espera, serás sanado dentro de un año»","«Pide a la iglesia que ayune por ti»","«El aguijón se irá cuando termines tu misión»"],"dato":"La respuesta no fue quitar el aguijón, sino prometer gracia suficiente: el poder de Dios se perfecciona en la debilidad humana.","cita":"2 Corintios 12:9","versiculo":"Y me ha dicho: Bástate mi gracia; porque mi potencia en la flaqueza se perfecciona. Por tanto, de buena gana me gloriaré más bien en mis flaquezas, porque habite en mí la potencia de Cristo.","vcita":"2 Corintios 12:9","pista":"«La gracia alcanza aunque la espina se quede.»"}],"Gálatas":[{"pregunta":"Según Gálatas 1, ¿qué debe ser incluso un ángel del cielo si anuncia un evangelio diferente del que fue predicado?","opciones":["Anatema","Escuchado con respeto","Probado con señales nuevas","Perdonado por su ignorancia"],"dato":"Pablo es terminante: si nosotros o un ángel del cielo anunciare otro evangelio del que fue anunciado, sea anatema.","cita":"Gálatas 1:8","versiculo":"Mas aun si nosotros o un ángel del cielo os anunciare otro evangelio del que os hemos anunciado, sea anatema.","vcita":"Gálatas 1:8","pista":"«Ni un mensajero celestial puede cambiar el mensaje.»"},{"pregunta":"¿A qué apóstol resistió Pablo en la cara, en Antioquía, por apartarse de los gentiles?","opciones":["A Pedro (Cefas)","A Juan, hijo de Zebedeo","A Bernabé","A Santiago, el hermano del Señor"],"dato":"Pedro comía con los gentiles, pero al llegar ciertos hombres se retraía por temor; Pablo lo resistió en público porque no andaba rectamente conforme a la verdad del evangelio.","cita":"Gálatas 2:11","versiculo":"Empero viniendo Pedro a Antioquía, le resistí en la cara, porque era de condenar.","vcita":"Gálatas 2:11","pista":"«El mismo al que Jesús llamó Cefas: piedra.»"},{"pregunta":"Completa la confesión de Pablo: «Con Cristo estoy juntamente crucificado, y vivo, no ya yo, mas vive…»","opciones":["Cristo en mí","La ley en mí","Mi vida antigua otra vez","Solo mi espíritu, sin el cuerpo"],"dato":"La vida que Pablo vive en la carne, la vive en la fe del Hijo de Dios, el cual lo amó y se entregó a sí mismo por él.","cita":"Gálatas 2:20","versiculo":"Con Cristo estoy juntamente crucificado, y vivo, no ya yo, mas vive Cristo en mí: y lo que ahora vivo en la carne, lo vivo en la fe del Hijo de Dios, el cual me amó, y se entregó a sí mismo por mí.","vcita":"Gálatas 2:20","pista":"«Ya no es Pablo quien vive su propia vida.»"},{"pregunta":"Según Gálatas 3, ¿de qué nos redimió Cristo haciéndose maldición por nosotros?","opciones":["De la maldición de la ley","Del dominio del imperio romano","De todo dolor físico en esta vida","Del trabajo y del cansancio diarios"],"dato":"Cristo nos redimió de la maldición de la ley hecho por nosotros maldición, pues está escrito: «Maldito cualquiera que es colgado en madero».","cita":"Gálatas 3:13","versiculo":"Cristo nos redimió de la maldición de la ley, hecho por nosotros maldición; (porque está escrito: Maldito cualquiera que es colgado en madero:)","vcita":"Gálatas 3:13","pista":"«Tomó sobre sí la maldición que a nosotros nos tocaba.»"},{"pregunta":"Según Gálatas 3, ¿qué diferencias quedan borradas porque todos somos uno en Cristo Jesús?","opciones":["No hay judío ni griego, ni siervo ni libre, ni varón ni hembra","No hay ricos ni pobres solamente","No hay ancianos ni jóvenes","No hay maestros ni discípulos"],"dato":"Todos los bautizados en Cristo están revestidos de Cristo: en él no hay judío ni griego, siervo ni libre, varón ni hembra.","cita":"Gálatas 3:28","versiculo":"No hay Judío, ni Griego; no hay siervo, ni libre; no hay varón, ni hembra: porque todos vosotros sois uno en Cristo Jesús.","vcita":"Gálatas 3:28","pista":"«Ante Cristo caen las etiquetas de este mundo.»"},{"pregunta":"Según Gálatas 4, ¿cuándo envió Dios a su Hijo, hecho de mujer?","opciones":["Cuando vino el cumplimiento del tiempo","Solo tras la caída del imperio romano","Antes de la creación, en persona visible","Cuando Israel lo eligió por votación"],"dato":"Venido el cumplimiento del tiempo, Dios envió a su Hijo, hecho de mujer, hecho súbdito a la ley, para redimir a los que estaban debajo de la ley.","cita":"Gálatas 4:4","versiculo":"Mas venido el cumplimiento del tiempo, Dios envió su Hijo, hecho de mujer, hecho súbdito a la ley,","vcita":"Gálatas 4:4","pista":"«Ni un día antes ni un día después: en el momento exacto.»"},{"pregunta":"Según Gálatas 4, ¿qué clama el Espíritu del Hijo en nuestros corazones porque somos hijos?","opciones":["«Abba, Padre»","«Santo, santo, santo»","«Heme aquí, envíame»","«Gloria en las alturas»"],"dato":"Por cuanto somos hijos, Dios envió el Espíritu de su Hijo a nuestros corazones, el cual clama con confianza de hijo: Abba, Padre.","cita":"Gálatas 4:6","versiculo":"Y por cuanto sois hijos, Dios envió el Espíritu de su Hijo en vuestros corazones, el cual clama: Abba, Padre.","vcita":"Gálatas 4:6","pista":"«Es la palabra aramea de un hijo que dice «papá».»"},{"pregunta":"¿Cuál de estas virtudes NO forma parte del fruto del Espíritu según la lista de Gálatas 5?","opciones":["La sabiduría","La caridad","La templanza","La mansedumbre"],"dato":"El fruto del Espíritu es: caridad, gozo, paz, tolerancia, benignidad, bondad, fe, mansedumbre y templanza; la sabiduría no aparece en esa lista.","cita":"Gálatas 5:22–23","versiculo":"Mas el fruto del Espíritu es: caridad, gozo, paz, tolerancia, benignidad, bondad, fe, Mansedumbre, templanza: contra tales cosas no hay ley.","vcita":"Gálatas 5:22–23","pista":"«Son nueve marcas, y esa palabra no está entre ellas.»"},{"pregunta":"Completa el principio agrícola de Pablo: «Todo lo que el hombre sembrare, eso también…»","opciones":["Segará","Comerá","Venderá","Regalará"],"dato":"Dios no puede ser burlado: la cosecha corresponde a la siembra; quien siembra para la carne segará corrupción, y quien para el Espíritu, vida eterna.","cita":"Gálatas 6:7","versiculo":"No os engañéis: Dios no puede ser burlado: que todo lo que el hombre sembrare, eso también segará.","vcita":"Gálatas 6:7","pista":"«Si siembras maíz, no cosechas uvas.»"},{"pregunta":"¿En qué dice Pablo que únicamente quiere gloriarse?","opciones":["En la cruz de nuestro Señor Jesucristo","En sus viajes y fundaciones de iglesias","En su dominio de la ley judía","En las visiones que recibió en Arabia"],"dato":"«Lejos esté de mí gloriarme, sino en la cruz de nuestro Señor Jesucristo»: por ella el mundo le es crucificado a Pablo, y él al mundo.","cita":"Gálatas 6:14","versiculo":"Mas lejos esté de mí gloriarme, sino en la cruz de nuestro Señor Jesucristo, por el cual el mundo me es crucificado a mí, y yo al mundo.","vcita":"Gálatas 6:14","pista":"«Su único trofeo tenía forma de cruz.»"}],"Efesios":[{"pregunta":"Según Efesios 1, ¿con qué nos bendijo Dios en los lugares celestiales en Cristo?","opciones":["Con toda bendición espiritual","Con riquezas materiales garantizadas","Con larga vida y sin enfermedad","Con autoridad sobre las naciones"],"dato":"La carta abre bendiciendo al Padre, porque nos bendijo con toda bendición espiritual en los lugares celestiales en Cristo.","cita":"Efesios 1:3","versiculo":"Bendito el Dios y Padre del Señor nuestro Jesucristo, el cual nos bendijo con toda bendición espiritual en lugares celestiales en Cristo:","vcita":"Efesios 1:3","pista":"«La cuenta ya viene llena desde el cielo.»"},{"pregunta":"Según Efesios 1, el Espíritu Santo es las ______ de nuestra herencia.","opciones":["Arras","Escrituras públicas","Llaves doradas","Primicias escritas en piedra"],"dato":"Sellados con el Espíritu Santo de la promesa, que es las arras —la garantía y el anticipo— de nuestra herencia, hasta la redención de la posesión adquirida.","cita":"Efesios 1:14","versiculo":"Que es las arras de nuestra herencia, para la redención de la posesión adquirida para alabanza de su gloria.","vcita":"Efesios 1:14","pista":"«Es el «pago inicial» que garantiza todo lo demás.»"},{"pregunta":"Completa la gran declaración de Efesios 2: «Porque por gracia sois salvos por la fe; y esto no de vosotros, pues es…»","opciones":["Don de Dios","Mérito acumulado del hombre","Obra de la ley cumplida","Fruto del esfuerzo personal"],"dato":"La salvación es por gracia, por medio de la fe; y ni siquiera eso es de nosotros: es don de Dios, no por obras, para que nadie se gloríe.","cita":"Efesios 2:8","versiculo":"Porque por gracia sois salvos por la fe; y esto no de vosotros, pues es don de Dios:","vcita":"Efesios 2:8","pista":"«No se compra ni se gana: se recibe.»"},{"pregunta":"Según Efesios 2, somos «hechura suya», creados en Cristo Jesús ¿para qué?","opciones":["Para buenas obras que Dios preparó de antemano","Para dejar de hacer todo esfuerzo","Para juzgar a los que no creen","Para guardar la ley ceremonial"],"dato":"No somos salvos POR buenas obras, sino PARA buenas obras: Dios las preparó de antemano para que anduviésemos en ellas.","cita":"Efesios 2:10","versiculo":"Porque somos hechura suya, criados en Cristo Jesús para buenas obras, las cuales Dios preparó para que anduviésemos en ellas.","vcita":"Efesios 2:10","pista":"«Las obras no son la raíz: son el destino.»"},{"pregunta":"Según Efesios 2, Cristo es nuestra paz porque derribó ¿qué cosa entre judíos y gentiles?","opciones":["La pared intermedia de separación","La muralla de la ciudad de Jerusalén","El velo de la entrada del santuario","La torre de la fortaleza Antonia"],"dato":"Cristo, de ambos pueblos hizo uno: derribó la pared intermedia de separación y creó en sí mismo un solo y nuevo hombre, haciendo la paz.","cita":"Efesios 2:14","versiculo":"Porque él es nuestra paz, que de ambos hizo uno, derribando la pared intermedia de separación;","vcita":"Efesios 2:14","pista":"«Donde había un muro, Cristo abrió una puerta.»"},{"pregunta":"Según la doxología de Efesios 3, Dios es poderoso para hacer las cosas ¿cómo, respecto a lo que pedimos o entendemos?","opciones":["Mucho más abundantemente de lo que pedimos o entendemos","Exactamente en la medida que pedimos","Solo cuando la iglesia entera ayuna","Un poco menos de lo que imaginamos"],"dato":"Pablo cierra su oración por los efesios mirando a Aquel que es poderoso para hacer todo mucho más abundantemente de lo que pedimos o pensamos.","cita":"Efesios 3:20","versiculo":"Y a Aquel que es poderoso para hacer todas las cosas mucho más abundantemente de lo que pedimos o entendemos, por la potencia que obra en nosotros,","vcita":"Efesios 3:20","pista":"«Su respuesta siempre supera nuestro cálculo.»"},{"pregunta":"Según Efesios 4, ¿para qué fueron dados a la iglesia apóstoles, profetas, evangelistas, pastores y maestros?","opciones":["Para perfeccionar a los santos para la obra del ministerio","Para hacer ellos solos todo el trabajo","Para mandar sobre los santos con señorío","Para sustituir la lectura de la Escritura"],"dato":"Los ministerios fueron dados para perfeccionar a los santos y edificar el cuerpo de Cristo: la obra del ministerio es de todo el pueblo, no de unos pocos.","cita":"Efesios 4:12","versiculo":"Para perfección de los santos, para la obra del ministerio, para edificación del cuerpo de Cristo;","vcita":"Efesios 4:12","pista":"«Son entrenadores de todo un equipo, no los únicos jugadores.»"},{"pregunta":"Según Efesios 4, ¿qué no debe pasar sobre nuestro enojo?","opciones":["Que se ponga el sol","Que llegue el día de reposo","Que termine el año","Que se entere toda la iglesia"],"dato":"«Airaos, y no pequéis; no se ponga el sol sobre vuestro enojo, ni deis lugar al diablo»: el enojo debe resolverse el mismo día.","cita":"Efesios 4:26","versiculo":"Airaos, y no pequéis; no se ponga el sol sobre vuestro enojo;","vcita":"Efesios 4:26","pista":"«El plazo para reconciliarse vence al atardecer.»"},{"pregunta":"Según Efesios 4, ¿cómo debemos tratarnos, imitando lo que Dios hizo con nosotros en Cristo?","opciones":["Benignos y misericordiosos, perdonándonos unos a otros","Exigiendo el pago de cada ofensa","Evitándonos en un silencio cortés","Corrigiéndonos con dureza en público"],"dato":"Dios nos perdonó en Cristo; por eso debemos ser benignos unos con otros, misericordiosos, perdonándonos mutuamente.","cita":"Efesios 4:32","versiculo":"Antes sed los unos con los otros benignos, misericordiosos, perdonándoos los unos a los otros, como también Dios os perdonó en Cristo.","vcita":"Efesios 4:32","pista":"«Perdonamos porque primero fuimos perdonados.»"},{"pregunta":"En vez de embriagarse de vino, ¿de qué manda Pablo ser llenos en Efesios 5?","opciones":["Del Espíritu","De placeres terrenales","De conocimiento humano solamente","De buenas intenciones sin hechos"],"dato":"«No os embriaguéis de vino, en lo cual hay disolución; mas sed llenos de Espíritu»: esa plenitud se expresa con salmos, himnos y cánticos espirituales.","cita":"Efesios 5:18","versiculo":"Y no os embriaguéis de vino, en lo cual hay disolución; mas sed llenos de Espíritu;","vcita":"Efesios 5:18","pista":"«Dos llenuras posibles: una disipa, la otra edifica.»"},{"pregunta":"Según Efesios 5, ¿cómo amó Cristo a la iglesia?","opciones":["Se entregó a sí mismo por ella","Le envió mensajeros desde el cielo","Le exigió perfección antes de amarla","La cubrió de riquezas materiales"],"dato":"El amor de Cristo por la iglesia es la medida del amor en el hogar: él se entregó a sí mismo por ella para santificarla.","cita":"Efesios 5:25","versiculo":"Maridos, amad a vuestras mujeres, así como Cristo amó a la iglesia, y se entregó a sí mismo por ella,","vcita":"Efesios 5:25","pista":"«El amor verdadero se mide por la entrega.»"}],"Filipenses":[{"pregunta":"¿Qué seguridad expresa Pablo sobre la obra que Dios comenzó en los filipenses?","opciones":["Que la perfeccionará hasta el día de Jesucristo","Que depende de que ellos nunca fallen","Que terminó el día en que él salió de Filipos","Que se completó al momento de escribir la carta"],"dato":"Pablo ora por ellos con confianza: el que comenzó en ellos la buena obra, la perfeccionará hasta el día de Jesucristo.","cita":"Filipenses 1:6","versiculo":"Estando confiado de esto, que el que comenzó en vosotros la buena obra, la perfeccionará hasta el día de Jesucristo;","vcita":"Filipenses 1:6","pista":"«Dios no deja sus obras a medias.»"},{"pregunta":"Completa la frase de Pablo entre la vida y la muerte: «Porque para mí el vivir es Cristo, y el morir es…»","opciones":["Ganancia","Pérdida","Una incertidumbre","Un sueño sin despertar"],"dato":"En prisiones, Pablo no pierde con ningún resultado: si vive, es Cristo; si muere, es ganancia, porque partir sería estar con Cristo.","cita":"Filipenses 1:21","versiculo":"Porque para mí el vivir es Cristo, y el morir es ganancia.","vcita":"Filipenses 1:21","pista":"«Un balance donde hasta perder es ganar.»"},{"pregunta":"Según el himno de Filipenses 2, ¿hasta dónde llegó la obediencia de Cristo al humillarse a sí mismo?","opciones":["Hasta la muerte, y muerte de cruz","Hasta el desierto de la tentación","Hasta el bautismo en el Jordán","Hasta su entrada en Jerusalén"],"dato":"Hallado en condición de hombre, Cristo se humilló hecho obediente hasta la muerte, y muerte de cruz: el punto más bajo antes de su exaltación.","cita":"Filipenses 2:8","versiculo":"Y hallado en la condición como hombre, se humilló a sí mismo, hecho obediente hasta la muerte, y muerte de cruz.","vcita":"Filipenses 2:8","pista":"«Descendió hasta lo más humillante: una cruz.»"},{"pregunta":"Según Filipenses 2, ¿qué confesará toda lengua en la exaltación de Cristo?","opciones":["Que Jesucristo es el Señor","Que Roma dominará para siempre","Que la ley salva al hombre","Que Pablo era un apóstol verdadero"],"dato":"Dios le dio un nombre que es sobre todo nombre: ante él se doblará toda rodilla y toda lengua confesará que Jesucristo es el Señor.","cita":"Filipenses 2:11","versiculo":"Y toda lengua confiese que Jesucristo es el Señor, a la gloria de Dios Padre.","vcita":"Filipenses 2:11","pista":"«Rodillas dobladas y una sola confesión universal.»"},{"pregunta":"¿Cómo consideraba Pablo todas sus antiguas ganancias después de conocer a Cristo?","opciones":["Como pérdida, y las tenía por estiércol para ganar a Cristo","Como su mayor orgullo delante de Dios","Como méritos necesarios para su salvación","Como una herencia que repartió a los pobres"],"dato":"Circuncidado, fariseo y perseguidor irreprensible según la ley: Pablo reputó todo eso pérdida por el eminente conocimiento de Cristo Jesús.","cita":"Filipenses 3:8","versiculo":"Y ciertamente, aun reputo todas las cosas pérdida por el eminente conocimiento de Cristo Jesús, mi Señor, por amor del cual lo he perdido todo, y téngolo por estiércol, para ganar a Cristo,","vcita":"Filipenses 3:8","pista":"«Su currículum entero a la basura, por un tesoro mayor.»"},{"pregunta":"Olvidando lo que queda atrás y extendiéndose a lo que está delante, ¿hacia dónde prosigue Pablo?","opciones":["Al blanco, al premio de la soberana vocación de Dios","Hacia Jerusalén para ser juzgado","Hacia su retiro definitivo en Roma","Hacia la sinagoga de su infancia en Tarso"],"dato":"Sin creerse haberlo ya alcanzado, Pablo prosigue a la meta: el premio del supremo llamamiento de Dios en Cristo Jesús.","cita":"Filipenses 3:14","versiculo":"Prosigo al blanco, al premio de la soberana vocación de Dios en Cristo Jesús.","vcita":"Filipenses 3:14","pista":"«Un corredor que no mira hacia atrás.»"},{"pregunta":"Según Filipenses 4, en vez de estar afanosos, ¿cómo debemos dar a conocer nuestras peticiones a Dios?","opciones":["En toda oración y ruego, con hacimiento de gracias","Con quejas repetidas cada hora","Solamente en la reunión dominical","En silencio absoluto y sin palabras"],"dato":"Por nada estéis afanosos: las peticiones se dan a conocer a Dios en oración y ruego con acción de gracias, y la paz de Dios guarda los corazones.","cita":"Filipenses 4:6","versiculo":"Por nada estéis afanosos; sino sean notorias vuestras peticiones delante de Dios en toda oración y ruego, con hacimiento de gracias.","vcita":"Filipenses 4:6","pista":"«La ansiedad se cambia por oración agradecida.»"},{"pregunta":"¿Cuál es la condición que hace posible el famoso «Todo lo puedo» de Pablo?","opciones":["En Cristo, que me fortalece","Con suficiente dinero acumulado","Solo con la ayuda de los filipenses","Por pura fuerza de voluntad"],"dato":"Pablo había aprendido a contentarse en la escasez y en la abundancia: todo lo puede, pero no solo — en Cristo que lo fortalece.","cita":"Filipenses 4:13","versiculo":"Todo lo puedo en Cristo que me fortalece.","vcita":"Filipenses 4:13","pista":"«La frase no termina en «puedo»: sigue con el cómo.»"}],"Colosenses":[{"pregunta":"¿Cómo describe Pablo a Cristo en Colosenses 1:15?","opciones":["Es la imagen del Dios invisible, el primogénito de toda creación","Es el primero de los ángeles creados por Dios","Es un profeta mayor que Moisés y que Elías","Es el sumo sacerdote según el orden de Aarón"],"dato":"Cristo revela perfectamente al Dios que nadie puede ver; como primogénito de toda creación tiene la supremacía sobre todo lo creado.","cita":"Colosenses 1:15","versiculo":"El cual es la imagen del Dios invisible, el primogénito de toda criatura.","vcita":"Colosenses 1:15","pista":"«Habla de cómo Cristo nos deja ver al Dios invisible.»"},{"pregunta":"¿De quién aprendieron los colosenses el evangelio, según el saludo de la carta?","opciones":["De Epafras, consiervo amado y fiel ministro de Cristo","Del propio Pablo, que les predicó en persona","De Timoteo, verdadero hijo en la fe","De Bernabé, compañero de viajes de Pablo"],"dato":"Pablo no había fundado personalmente esa iglesia: fue Epafras quien les llevó el evangelio y le contó a Pablo del amor de ellos en el Espíritu.","cita":"Colosenses 1:7","versiculo":"Como habéis aprendido de Epafras, nuestro consiervo amado, el cual es un fiel ministro de Cristo á favor vuestro;","vcita":"Colosenses 1:7","pista":"«Su nombre reaparece al final de la carta a Filemón.»"},{"pregunta":"¿Qué está escondido en Cristo, según Colosenses 2:3?","opciones":["Todos los tesoros de la sabiduría y del conocimiento","Los nombres escritos en el libro de la vida","El día y la hora de su venida","Las tablas originales de la ley de Moisés"],"dato":"Contra los que buscaban una sabiduría secreta y superior, Pablo afirma que todo tesoro de sabiduría y conocimiento está en Cristo.","cita":"Colosenses 2:3","versiculo":"En el cual están escondidos todos los tesoros de sabiduría y conocimiento.","vcita":"Colosenses 2:3","pista":"«No es oro: son dos tesoros que enriquecen la mente.»"},{"pregunta":"¿Qué quitó Dios de en medio y clavó en la cruz, según Colosenses 2:14?","opciones":["La cédula de los ritos que nos era contraria","Las tablas de piedra entregadas a Moisés","El velo del templo de Jerusalén","El libro de las maldiciones de Deuteronomio"],"dato":"La «cédula» era como un documento de deuda en contra del hombre; Dios lo anuló, lo quitó de en medio y lo clavó en la cruz de Cristo.","cita":"Colosenses 2:14","versiculo":"Rayendo la cédula de los ritos que nos era contraria, que era contra nosotros, quitándola de en medio y enclavándola en la cruz;","vcita":"Colosenses 2:14","pista":"«Piensa en un papel de deuda que queda clavado y anulado.»"},{"pregunta":"¿Dónde manda Pablo poner la mira en Colosenses 3:2?","opciones":["En las cosas de arriba, no en las de la tierra","En el templo y en sus sacrificios","En las promesas de riquezas futuras","En las tradiciones de los padres"],"dato":"Como los creyentes resucitaron con Cristo, su mirada debe estar en las cosas de arriba, donde Cristo está sentado a la diestra de Dios.","cita":"Colosenses 3:2","versiculo":"Poned la mira en las cosas de arriba, no en las de la tierra.","vcita":"Colosenses 3:2","pista":"«Es lo contrario de vivir mirando solo lo terrenal.»"},{"pregunta":"¿Qué debe habitar en abundancia en los creyentes, según Colosenses 3:16?","opciones":["La palabra de Cristo","El temor de los juicios humanos","La sabiduría de los filósofos griegos","El celo por las genealogías"],"dato":"La palabra de Cristo debe morar ricamente en el creyente, expresándose en enseñanza mutua y en canto con salmos, himnos y canciones espirituales.","cita":"Colosenses 3:16","versiculo":"La palabra de Cristo habite en vosotros en abundancia en toda sabiduría, enseñándoos y exhortándoos los unos á los otros con salmos é himnos y canciones espirituales, con gracia cantando en vuestros corazones al Señor.","vcita":"Colosenses 3:16","pista":"«Es lo que enseña y hace cantar al corazón.»"},{"pregunta":"¿Qué no deben hacer los padres con sus hijos, según Colosenses 3:21?","opciones":["Irritarlos, para que no se hagan de poco ánimo","Enseñarles el oficio familiar","Llevarlos a oír la Palabra","Corregirlos cuando hacen lo malo"],"dato":"Pablo equilibra la obediencia de los hijos con la ternura de los padres: la dureza constante desanima y apaga el ánimo de un hijo.","cita":"Colosenses 3:21","versiculo":"Padres, no irritéis á vuestros hijos, porque no se hagan de poco ánimo.","vcita":"Colosenses 3:21","pista":"«El exceso de dureza termina apagando el corazón de un hijo.»"},{"pregunta":"¿Cómo manda Pablo hacer todo lo que hagamos, según Colosenses 3:23?","opciones":["De ánimo, como al Señor, y no a los hombres","Solo cuando alguien importante nos observa","Con rapidez, sin detenernos a pensar","Buscando primero el reconocimiento de todos"],"dato":"El trabajo del creyente cambia de sentido: aunque sirva a amos humanos, en realidad trabaja para el Señor, de quien recibirá la recompensa.","cita":"Colosenses 3:23","versiculo":"Y todo lo que hagáis, hacedlo de ánimo, como al Señor, y no á los hombres;","vcita":"Colosenses 3:23","pista":"«Aunque nadie te vea, hay un Señor para quien lo haces.»"},{"pregunta":"¿A quién llama Pablo «el médico amado» en los saludos finales?","opciones":["A Lucas","A Timoteo","A Demas","A Epafras"],"dato":"Lucas, autor del tercer Evangelio y del libro de los Hechos, acompañaba a Pablo en sus prisiones y es saludado con ese cariñoso título.","cita":"Colosenses 4:14","versiculo":"Os saluda Lucas, el médico amado, y Demas.","vcita":"Colosenses 4:14","pista":"«Escribió un Evangelio y también el libro de los Hechos.»"},{"pregunta":"¿En qué otra iglesia debía leerse también la carta a los colosenses?","opciones":["En la iglesia de los laodicenses","En la iglesia de Éfeso","En la iglesia de Jerusalén","En la iglesia de Antioquía"],"dato":"Pablo ordenó que, tras leerse entre los colosenses, la carta se leyera también en Laodicea, y que ellos leyeran asimismo la carta enviada allá.","cita":"Colosenses 4:16","versiculo":"Y cuando esta carta fuere leída entre vosotros, haced que también sea leída en la iglesia de los Laodicenses; y la de Laodicea que la leáis también vosotros.","vcita":"Colosenses 4:16","pista":"«Es una ciudad vecina, de las siete iglesias del Apocalipsis.»"}],"1 Tesalonicenses":[{"pregunta":"¿Qué tres cosas recuerda Pablo sin cesar de los tesalonicenses en el saludo de la carta?","opciones":["La obra de su fe, el trabajo de su amor y la tolerancia de su esperanza","La abundancia de sus bienes, su fama y su gran número","Sus largos ayunos, sus vigilias y sus muchas limosnas","Su conocimiento de la ley, su elocuencia y sus dones"],"dato":"Pablo abre dando gracias por una iglesia marcada por la fe que obra, el amor que trabaja y la esperanza que soporta con paciencia.","cita":"1 Tesalonicenses 1:3","versiculo":"Sin cesar acordándonos delante del Dios y Padre nuestro de la obra de vuestra fe, y del trabajo de amor, y de la tolerancia de la esperanza del Señor nuestro Jesucristo:","vcita":"1 Tesalonicenses 1:3","pista":"«Son las tres virtudes clásicas: fe, amor y una tercera que mira al futuro.»"},{"pregunta":"¿De qué se convirtieron los tesalonicenses cuando recibieron el evangelio?","opciones":["De los ídolos, para servir al Dios vivo y verdadero","De la vida del campo a la vida de la ciudad","Del judaísmo de Jerusalén al de la dispersión","De sus oficios para vivir solo de la predicación"],"dato":"Su conversión fue un giro completo: dejaron los ídolos y se volvieron a Dios para servirle y esperar a su Hijo desde los cielos.","cita":"1 Tesalonicenses 1:9","versiculo":"Porque ellos cuentan de nosotros cuál entrada tuvimos á vosotros; y cómo os convertisteis de los ídolos á Dios, para servir al Dios vivo y verdadero,","vcita":"1 Tesalonicenses 1:9","pista":"«Dejaron las imágenes muertas para servir a un Dios vivo.»"},{"pregunta":"¿A quién compara Pablo su trato tierno con los tesalonicenses en 2:7?","opciones":["A la que cría y regala con ternura a sus hijos","A un padre que disciplina con vara firme","A un pastor que defiende el rebaño de los lobos","A un maestro que exige a sus discípulos"],"dato":"Lejos de imponer autoridad, Pablo fue blando y cariñoso entre ellos, como la madre que alimenta y abriga a sus propios hijos.","cita":"1 Tesalonicenses 2:7","versiculo":"Antes fuimos blandos entre vosotros como la que cría, que regala á sus hijos:","vcita":"1 Tesalonicenses 2:7","pista":"«Piensa en el cuidado más tierno dentro de una familia.»"},{"pregunta":"¿Por qué trabajaba Pablo de noche y de día mientras predicaba en Tesalónica?","opciones":["Por no ser gravoso a ninguno de ellos","Para enriquecerse con su oficio de tiendas","Porque la ley romana se lo exigía a los judíos","Para huir de las autoridades de la ciudad"],"dato":"Pablo se sostenía con su propio trabajo manual para no cargar económicamente a los nuevos creyentes mientras les anunciaba el evangelio.","cita":"1 Tesalonicenses 2:9","versiculo":"Porque ya, hermanos, os acordáis de nuestro trabajo y fatiga: que trabajando de noche y de día por no ser gravosos á ninguno de vosotros, os predicamos el evangelio de Dios.","vcita":"1 Tesalonicenses 2:9","pista":"«No quería que el evangelio les costara ni una moneda.»"},{"pregunta":"¿A quién envió Pablo de vuelta a Tesalónica para confirmar y exhortar a los creyentes en su fe?","opciones":["A Timoteo, su hermano y colaborador en el evangelio","A Tito, para poner en orden la iglesia","A Lucas, el médico amado","A Juan Marcos, primo de Bernabé"],"dato":"Pablo, sin poder soportar más la incertidumbre, se quedó solo en Atenas y envió a Timoteo a fortalecer a la iglesia perseguida.","cita":"1 Tesalonicenses 3:2","versiculo":"Y enviamos á Timoteo, nuestro hermano, y ministro de Dios, y colaborador nuestro en el evangelio de Cristo, á confirmaros y exhortaros en vuestra fe,","vcita":"1 Tesalonicenses 3:2","pista":"«Es el joven destinatario de dos cartas pastorales.»"},{"pregunta":"¿Qué vida manda Pablo procurar a los tesalonicenses en 4:11?","opciones":["Tener quietud, hacer sus propios negocios y trabajar con sus manos","Apartarse del todo de la ciudad y vivir en el desierto","Dedicar el día entero a discutir en las plazas","Esperar el fin sin trabajar, sostenidos por la iglesia"],"dato":"Contra el ocio inquieto de algunos, Pablo ordena una vida tranquila, ocupada en lo propio y sostenida por el trabajo de las propias manos.","cita":"1 Tesalonicenses 4:11","versiculo":"Y que procuréis tener quietud, y hacer vuestros negocios, y obréis de vuestras manos de la manera que os hemos mandado;","vcita":"1 Tesalonicenses 4:11","pista":"«Tranquilidad, asuntos propios y manos ocupadas.»"},{"pregunta":"Según 1 Tesalonicenses 4:16, ¿quiénes resucitarán primero cuando el Señor descienda del cielo?","opciones":["Los muertos en Cristo","Los que estén vivos en su venida","Los mártires de los últimos días","Los apóstoles y profetas"],"dato":"Con voz de mando, voz de arcángel y trompeta de Dios, el Señor descenderá; primero resucitarán los muertos en Cristo y luego los vivos serán arrebatados con ellos.","cita":"1 Tesalonicenses 4:16","versiculo":"Porque el mismo Señor con aclamación, con voz de arcángel, y con trompeta de Dios, descenderá del cielo; y los muertos en Cristo resucitarán primero:","vcita":"1 Tesalonicenses 4:16","pista":"«Los que duermen en Cristo llevan la delantera.»"},{"pregunta":"¿Cómo vendrá el día del Señor, según 1 Tesalonicenses 5:2?","opciones":["Como ladrón de noche","Anunciado por señales durante cuarenta días","Tras una gran trompeta oída por años","Solo después de que todos lo esperen"],"dato":"La venida será sorpresiva para el mundo que dice «paz y seguridad»; por eso el creyente debe velar y estar sobrio, no dormido.","cita":"1 Tesalonicenses 5:2","versiculo":"Porque vosotros sabéis bien, que el día del Señor vendrá así como ladrón de noche,","vcita":"1 Tesalonicenses 5:2","pista":"«Llega cuando nadie lo está esperando.»"},{"pregunta":"¿Cuál es el mandato brevísimo de 1 Tesalonicenses 5:17?","opciones":["Orad sin cesar","Ayunad cada semana","Cantad en todo tiempo","Leed sin descanso"],"dato":"En medio de una serie de exhortaciones cortas, Pablo resume la vida de oración constante con solo dos palabras.","cita":"1 Tesalonicenses 5:17","versiculo":"Orad sin cesar.","vcita":"1 Tesalonicenses 5:17","pista":"«Es hablar con Dios... siempre, sin parar.»"},{"pregunta":"¿Qué no debemos apagar, según 1 Tesalonicenses 5:19?","opciones":["El Espíritu","La lámpara del santuario","El celo por las tradiciones","La memoria de los mártires"],"dato":"La imagen es la de un fuego que no debe sofocarse: no hay que ahogar la obra ni las manifestaciones del Espíritu Santo.","cita":"1 Tesalonicenses 5:19","versiculo":"No apaguéis el Espíritu.","vcita":"1 Tesalonicenses 5:19","pista":"«Es un fuego que debe seguir ardiendo en la iglesia.»"},{"pregunta":"¿Qué manda Pablo hacer con todo y qué retener, según 5:21?","opciones":["Examinarlo todo y retener lo bueno","Aceptarlo todo sin hacer preguntas","Rechazar todo lo nuevo por sistema","Examinar solo lo que digan los ancianos"],"dato":"Ni credulidad ni desprecio: todo se somete a prueba, y lo que resulta bueno, eso se guarda y se retiene.","cita":"1 Tesalonicenses 5:21","versiculo":"Examinadlo todo; retened lo bueno.","vcita":"1 Tesalonicenses 5:21","pista":"«Primero se prueba... y después se guarda lo que vale.»"}],"2 Tesalonicenses":[{"pregunta":"¿De qué se gloría Pablo acerca de los tesalonicenses en las iglesias de Dios?","opciones":["De su paciencia y fe en todas sus persecuciones y tribulaciones","De la rapidez con que construyeron su templo","De que nunca habían sufrido por el evangelio","De sus aportes para las iglesias de Judea"],"dato":"Pablo presume de ellos ante otras iglesias: perseguidos y atribulados, seguían firmes con paciencia y fe.","cita":"2 Tesalonicenses 1:4","versiculo":"Tanto, que nosotros mismos nos gloriamos de vosotros en las iglesias de Dios, de vuestra paciencia y fe en todas vuestras persecuciones y tribulaciones que sufrís:","vcita":"2 Tesalonicenses 1:4","pista":"«Lo admirable no era su comodidad, sino su firmeza sufriendo.»"},{"pregunta":"Según 2 Tesalonicenses 1:6, ¿qué es justo para Dios hacer con los que atribulan a su pueblo?","opciones":["Pagarles con tribulación","Olvidar por completo su maldad","Enviarlos a predicar a otras tierras","Quitarles solo sus riquezas"],"dato":"La justicia de Dios consuela a los atribulados: Él retribuirá con tribulación a los que hoy los afligen injustamente.","cita":"2 Tesalonicenses 1:6","versiculo":"Porque es justo para con Dios pagar con tribulación á los que os atribulan.","vcita":"2 Tesalonicenses 1:6","pista":"«Es retribución medida con la misma moneda del sufrimiento.»"},{"pregunta":"¿Quién debe manifestarse antes de la venida del Señor, junto con la apostasía, según 2:3?","opciones":["El hombre de pecado, el hijo de perdición","Un nuevo profeta enviado desde Jerusalén","El ángel Miguel con sus ejércitos","El rey del norte con su imperio"],"dato":"Pablo corrige la idea de que el día del Señor ya había llegado: antes vendrán la apostasía y la manifestación del hombre de pecado.","cita":"2 Tesalonicenses 2:3","versiculo":"No os engañe nadie en ninguna manera; porque [no vendrá] sin que venga antes la apostasía, y se manifieste el hombre de pecado, el hijo de perdición,","vcita":"2 Tesalonicenses 2:3","pista":"«Tiene dos títulos siniestros en un solo versículo.»"},{"pregunta":"¿Qué ya está obrando en los días de Pablo, según 2 Tesalonicenses 2:7?","opciones":["El misterio de la iniquidad","La reconstrucción del templo","La marca de la bestia en la frente","El juicio de las naciones"],"dato":"La maldad final no surge de la nada: su «misterio» ya actúa en secreto, aunque contenido por el que ahora lo impide o detiene.","cita":"2 Tesalonicenses 2:7","versiculo":"Porque ya está obrando el misterio de iniquidad: solamente [espera] hasta que sea quitado de en medio el que ahora impide;","vcita":"2 Tesalonicenses 2:7","pista":"«Trabaja en secreto, como un misterio, desde ya.»"},{"pregunta":"¿Cómo destruirá el Señor Jesús al inicuo en su venida, según 2:8?","opciones":["Con el espíritu de su boca y el resplandor de su venida","Con un ejército de diez mil ángeles armados","Con fuego descendido del cielo sobre la tierra","Encerrándolo mil años en un pozo sellado"],"dato":"El inicuo no cae en una batalla pareja: basta el soplo de la boca del Señor y el brillo de su aparición para destruirlo.","cita":"2 Tesalonicenses 2:8","versiculo":"Y entonces será manifestado aquel inicuo, al cual el Señor matará con el espíritu de su boca, y destruirá con el resplandor de su venida;","vcita":"2 Tesalonicenses 2:8","pista":"«No necesita espada: le basta su aliento y su presencia.»"},{"pregunta":"¿Qué deben retener los hermanos, según 2 Tesalonicenses 2:15?","opciones":["La doctrina aprendida, sea por palabra o por carta de Pablo","Las costumbres heredadas de los fariseos","El dinero reunido para los pobres de Jerusalén","Los nombres de los falsos maestros"],"dato":"Frente a la confusión doctrinal, la orden es estar firmes y guardar la enseñanza apostólica recibida de viva voz y por escrito.","cita":"2 Tesalonicenses 2:15","versiculo":"Así que, hermanos, estad firmes, y retened la doctrina que habéis aprendido, sea por palabra, ó por carta nuestra.","vcita":"2 Tesalonicenses 2:15","pista":"«Lo enseñado no se negocia: se queda firme en la mano.»"},{"pregunta":"¿Qué hará el Señor, que es fiel, según 2 Tesalonicenses 3:3?","opciones":["Confirmar a los creyentes y guardarlos del mal","Llevarlos de inmediato fuera de la ciudad","Darles riquezas para no trabajar más","Revelarles el día exacto de su venida"],"dato":"Aunque entre los hombres haya infieles, el Señor es fiel: Él afirma a los suyos y los protege del maligno.","cita":"2 Tesalonicenses 3:3","versiculo":"Mas fiel es el Señor, que os confirmará y guardará del mal.","vcita":"2 Tesalonicenses 3:3","pista":"«Su fidelidad hace dos cosas: afirma y protege.»"},{"pregunta":"¿Hacia qué dos cosas pide Pablo que el Señor enderece el corazón de los tesalonicenses?","opciones":["Al amor de Dios y a la paciencia de Cristo","A la sabiduría griega y a la ley de Moisés","Al temor de los hombres y a la prudencia","A la riqueza espiritual y al descanso total"],"dato":"Pablo pide corazones enderezados, como un camino recto, hacia el amor de Dios y hacia la constancia paciente de Cristo.","cita":"2 Tesalonicenses 3:5","versiculo":"Y el Señor enderece vuestros corazones en el amor de Dios, y en la paciencia de Cristo.","vcita":"2 Tesalonicenses 3:5","pista":"«Un corazón derecho apunta al amor... y a la paciencia de alguien.»"},{"pregunta":"¿Cuál era la regla de Pablo sobre el que no quiere trabajar?","opciones":["Que tampoco coma","Que coma solo la mitad de la ración","Que sea sostenido por los ancianos","Que ayune hasta que cambie"],"dato":"Pablo lo había mandado estando con ellos: quien se niega a trabajar no tiene derecho a exigir la comida del esfuerzo ajeno.","cita":"2 Tesalonicenses 3:10","versiculo":"Porque aun estando con vosotros, os denunciábamos esto: Que si alguno no quisiere trabajar, tampoco coma.","vcita":"2 Tesalonicenses 3:10","pista":"«Es la frase más famosa de esta carta sobre el trabajo.»"},{"pregunta":"¿En qué andaban ocupados algunos tesalonicenses desordenados, según 3:11?","opciones":["En curiosear, sin trabajar en nada","En comerciar por los puertos del norte","En enseñar doctrinas gentiles","En construir una casa de oración"],"dato":"No trabajaban en lo suyo, pero sí andaban metiéndose en lo ajeno: mucha curiosidad y ningún fruto.","cita":"2 Tesalonicenses 3:11","versiculo":"Porque oímos que andan algunos entre vosotros fuera de orden, no trabajando en nada, sino ocupados en curiosear.","vcita":"2 Tesalonicenses 3:11","pista":"«Manos quietas, pero ojos y oídos en casa ajena.»"},{"pregunta":"¿De qué no deben cansarse los hermanos, según 2 Tesalonicenses 3:13?","opciones":["De hacer bien","De corregir a los ociosos","De esperar carta de Pablo","De reunir ofrendas cada semana"],"dato":"Aun rodeados de desorden, los fieles no debían rendirse en la práctica constante del bien.","cita":"2 Tesalonicenses 3:13","versiculo":"Y vosotros, hermanos, no os canséis de hacer bien.","vcita":"2 Tesalonicenses 3:13","pista":"«El cansancio no es excusa para dejar de hacerlo... lo bueno.»"},{"pregunta":"¿Cómo llama Pablo al Señor en la bendición final de 3:16?","opciones":["El Señor de paz","El Señor de los ejércitos celestiales","El Dios de toda venganza","El Señor de la cosecha"],"dato":"La carta que trata de inquietud y desorden cierra con el «Señor de paz» que da paz siempre y en toda manera.","cita":"2 Tesalonicenses 3:16","versiculo":"Y el mismo Señor de paz os dé siempre paz en toda manera. El Señor sea con todos vosotros.","vcita":"2 Tesalonicenses 3:16","pista":"«Su título aquí es justo lo que los inquietos necesitan.»"}],"1 Timoteo":[{"pregunta":"¿Cómo llama Pablo a Timoteo en el saludo de esta carta?","opciones":["Verdadero hijo en la fe","Compañero de milicia","Hermano en la carne","Discípulo desde la niñez"],"dato":"Timoteo no era hijo carnal de Pablo, pero sí su hijo espiritual: lo ganó para el evangelio y lo formó como colaborador cercano.","cita":"1 Timoteo 1:2","versiculo":"A Timoteo, verdadero hijo en la fe: Gracia, misericordia y paz de Dios nuestro Padre, y de Cristo Jesús nuestro Señor.","vcita":"1 Timoteo 1:2","pista":"«No comparten sangre, comparten algo más fuerte: la fe.»"},{"pregunta":"Según la «palabra fiel» de 1 Timoteo 1:15, ¿para qué vino Cristo Jesús al mundo?","opciones":["Para salvar a los pecadores, de los cuales Pablo se llama el primero","Para fundar un reino político en Jerusalén","Para enseñar solo a los judíos piadosos","Para condenar a los pecadores sin remedio"],"dato":"Pablo presenta su propio caso como prueba: si Cristo lo salvó a él, el primero de los pecadores, hay esperanza para cualquiera.","cita":"1 Timoteo 1:15","versiculo":"Palabra fiel y digna de ser recibida de todos: que Cristo Jesús vino al mundo para salvar á los pecadores, de los cuales yo soy el primero.","vcita":"1 Timoteo 1:15","pista":"«Y el apóstol se pone a sí mismo al frente de la fila.»"},{"pregunta":"¿Qué quiere Dios para todos los hombres, según 1 Timoteo 2:4?","opciones":["Que sean salvos y vengan al conocimiento de la verdad","Que se aparten todos a vivir en desiertos","Que guarden las fiestas de Israel","Que paguen primero por sus pecados"],"dato":"La voluntad salvadora de Dios es universal: alcanza a todos los hombres, que deben llegar a conocer la verdad del evangelio.","cita":"1 Timoteo 2:4","versiculo":"El cual quiere que todos los hombres sean salvos, y que vengan al conocimiento de la verdad.","vcita":"1 Timoteo 2:4","pista":"«Son dos deseos unidos: salvación y conocimiento de algo.»"},{"pregunta":"¿Quién es el único mediador entre Dios y los hombres, según 1 Timoteo 2:5?","opciones":["Jesucristo hombre","El sumo sacerdote de Jerusalén","El apóstol Pablo","El ángel Gabriel"],"dato":"Hay un solo Dios y un solo mediador: Jesucristo hombre, que se dio a sí mismo en rescate por todos.","cita":"1 Timoteo 2:5","versiculo":"Porque hay un Dios, asimismo un mediador entre Dios y los hombres, Jesucristo hombre;","vcita":"1 Timoteo 2:5","pista":"«Uno solo está en el medio entre Dios y la humanidad.»"},{"pregunta":"¿Cómo conviene que sea el obispo, según la lista de 1 Timoteo 3:2?","opciones":["Irreprensible, marido de una mujer, templado y apto para enseñar","Rico, de familia noble y buen orador callejero","Soltero, viajero constante y sin casa propia","Anciano de días, aunque no sepa enseñar"],"dato":"Los requisitos del obispo son ante todo de carácter: irreprensible, fiel en su hogar, sobrio, prudente, hospitalario y capaz de enseñar.","cita":"1 Timoteo 3:2","versiculo":"Conviene, pues, que el obispo sea irreprensible, marido de una mujer, solícito, templado, compuesto, hospedador, apto para enseñar;","vcita":"1 Timoteo 3:2","pista":"«La lista empieza por su reputación y su propia casa.»"},{"pregunta":"¿Cuál es el gran misterio de la piedad que confiesa 1 Timoteo 3:16?","opciones":["Dios ha sido manifestado en carne","El lugar secreto del arca del pacto","El nombre oculto de la bestia","La fecha escondida de la resurrección"],"dato":"El himno de 3:16 resume el evangelio: Dios manifestado en carne, justificado en el Espíritu, visto de ángeles, predicado a los gentiles, creído en el mundo y recibido en gloria.","cita":"1 Timoteo 3:16","versiculo":"Y sin contradicción, grande es el misterio de la piedad: Dios ha sido manifestado en carne; ha sido justificado con el Espíritu; ha sido visto de los ángeles; ha sido predicado á los Gentiles; ha sido creído en el mundo; ha sido recibido en gloria.","vcita":"1 Timoteo 3:16","pista":"«Dios mismo se hizo visible... y ese es el misterio grande.»"},{"pregunta":"¿Qué aprovecha para todo y tiene promesa de esta vida y de la venidera, según 4:8?","opciones":["La piedad","El ejercicio corporal","El estudio de los idiomas","La práctica de los ayunos"],"dato":"Pablo no desprecia el ejercicio del cuerpo, pero lo compara: provecha para poco; la piedad, en cambio, aprovecha para todo y tiene doble promesa.","cita":"1 Timoteo 4:8","versiculo":"Porque el ejercicio corporal para poco es provechoso; mas la piedad para todo aprovecha, pues tiene promesa de esta vida presente, y de la venidera.","vcita":"1 Timoteo 4:8","pista":"«Vale para esta vida... y también para la que viene.»"},{"pregunta":"¿Qué le manda Pablo a Timoteo acerca de su juventud en 4:12?","opciones":["Que ninguno la tenga en poco, siendo él ejemplo de los fieles","Que la oculte fingiendo más edad","Que espere a ser anciano para empezar a enseñar","Que la aproveche solo para viajar y conocer iglesias"],"dato":"La autoridad del joven Timoteo no vendría de su edad, sino de su ejemplo: en palabra, conducta, caridad, fe y pureza.","cita":"1 Timoteo 4:12","versiculo":"Ninguno tenga en poco tu juventud; pero sé ejemplo de los fieles en palabra, en conversación, en caridad, en espíritu, en fe, en limpieza.","vcita":"1 Timoteo 4:12","pista":"«La respuesta a los que lo miran por joven es una sola: ser ejemplo.»"},{"pregunta":"¿Qué es raíz de todos los males, según 1 Timoteo 6:10?","opciones":["El amor del dinero","La pobreza extrema","El trabajo con las manos","El deseo de aprender"],"dato":"No es el dinero en sí, sino el amor al dinero: codiciándolo, algunos se apartaron de la fe y fueron traspasados de muchos dolores.","cita":"1 Timoteo 6:10","versiculo":"Porque el amor del dinero es la raíz de todos los males: el cual codiciando algunos, se descaminaron de la fe, y fueron traspasados de muchos dolores.","vcita":"1 Timoteo 6:10","pista":"«No es la moneda: es el amor desordenado hacia ella.»"}],"2 Timoteo":[{"pregunta":"¿En quiénes residió primero la fe no fingida que había en Timoteo?","opciones":["En su abuela Loida y en su madre Eunice","En su padre griego y en su tía de Listra","En la profetisa Ana y en su hermana","En Priscila y en Aquila, sus maestros"],"dato":"Pablo recuerda una fe heredada en casa: primero en la abuela Loida, después en la madre Eunice, y está cierto de que también vive en Timoteo.","cita":"2 Timoteo 1:5","versiculo":"Trayendo á la memoria la fe no fingida que hay en ti, la cual residió primero en tu abuela Loida, y en tu madre Eunice; y estoy cierto que en ti también.","vcita":"2 Timoteo 1:5","pista":"«Son dos mujeres de su propia familia, de dos generaciones.»"},{"pregunta":"¿Qué le aconseja Pablo a Timoteo despertar o avivar en 1:6?","opciones":["El don de Dios que está en él por la imposición de las manos de Pablo","El estudio de las leyes romanas","El celo contra los judíos de Éfeso","El deseo de volver a su casa en Listra"],"dato":"El don recibido no debía enfriarse: como un fuego cubierto de ceniza, Timoteo tenía que despertarlo y mantenerlo ardiendo.","cita":"2 Timoteo 1:6","versiculo":"Por lo cual te aconsejo que despiertes el don de Dios, que está en ti por la imposición de mis manos.","vcita":"2 Timoteo 1:6","pista":"«Es como avivar las brasas de un fuego que ya tienes.»"},{"pregunta":"Según 2 Timoteo 1:7, ¿qué espíritu NO nos ha dado Dios, y cuál sí?","opciones":["No de temor, sino de fortaleza, de amor y de templanza","No de valentía, sino de prudencia humana","No de palabra, sino de silencio y retiro","No de gozo, sino de tristeza y luto"],"dato":"Frente a la tentación de avergonzarse del evangelio, Pablo recuerda que el Espíritu recibido no produce cobardía, sino fortaleza, amor y templanza.","cita":"2 Timoteo 1:7","versiculo":"Porque no nos ha dado Dios el espíritu de temor, sino [el] de fortaleza, y de amor, y de templanza.","vcita":"2 Timoteo 1:7","pista":"«El espíritu dado produce poder, cariño y dominio propio.»"},{"pregunta":"¿Qué afirma Pablo con plena certeza en 2 Timoteo 1:12, mientras padece por el evangelio?","opciones":["Que sabe a quién ha creído, y que Dios es poderoso para guardar su depósito","Que pronto saldrá libre de la cárcel de Roma","Que los creyentes nunca pasarán aflicciones","Que Timoteo será el próximo apóstol de Jerusalén"],"dato":"En cadenas y sin avergonzarse, la seguridad de Pablo no está en su suerte, sino en la persona en quien creyó y en su poder para guardar lo encomendado.","cita":"2 Timoteo 1:12","versiculo":"Por lo cual asimismo padezco esto: mas no me avergüenzo; porque yo sé á quien he creído, y estoy cierto que es poderoso para guardar mi depósito para aquel día.","vcita":"2 Timoteo 1:12","pista":"«Su confianza tiene nombre propio: sabe a Quién creyó.»"},{"pregunta":"¿Cómo debe presentarse el obrero ante Dios, según 2 Timoteo 2:15?","opciones":["Aprobado, sin tener de qué avergonzarse, trazando bien la palabra de verdad","Con muchos títulos y cartas de recomendación","Habiendo ganado primero riquezas y honores","Callado, sin atreverse nunca a enseñar"],"dato":"El obrero aprobado se esfuerza con diligencia y maneja la palabra de verdad con rectitud, como quien corta derecho y no se avergüenza de su trabajo.","cita":"2 Timoteo 2:15","versiculo":"Procura con diligencia presentarte á Dios aprobado, [como] obrero que no tiene de qué avergonzarse, que traza bien la palabra de verdad.","vcita":"2 Timoteo 2:15","pista":"«Buen obrero: trabajo examinado por Dios y palabra bien trazada.»"},{"pregunta":"¿Qué afirma Pablo de toda la Escritura en 2 Timoteo 3:16?","opciones":["Que es inspirada divinamente y útil para enseñar, redargüir, corregir e instituir en justicia","Que solo sirve para los sacerdotes del templo","Que fue escrita únicamente para los antiguos","Que debe leerse solo en las fiestas solemnes"],"dato":"La Escritura entera tiene origen divino y utilidad práctica completa: enseña, convence de error, corrige y forma en la justicia.","cita":"2 Timoteo 3:16","versiculo":"Toda Escritura [es] inspirada divinamente y útil para enseñar, para redargüir, para corregir, para instituir en justicia,","vcita":"2 Timoteo 3:16","pista":"«Toda ella viene de Dios... y toda ella sirve.»"},{"pregunta":"¿Qué debe predicar Timoteo, y cuándo debe instar, según el encargo solemne de 4:2?","opciones":["La palabra, a tiempo y fuera de tiempo","Solo consuelos, cuando la gente lo pida","Las genealogías, en cada reunión","Sus experiencias, una vez al año"],"dato":"El encargo es urgente y constante: predicar la palabra insistiendo en toda ocasión, oportuna o no, redarguyendo, reprendiendo y exhortando con paciencia y doctrina.","cita":"2 Timoteo 4:2","versiculo":"Que prediques la palabra; que instes á tiempo y fuera de tiempo; redarguye, reprende, exhorta con toda paciencia y doctrina.","vcita":"2 Timoteo 4:2","pista":"«Convenza o no convenza el momento: la palabra se predica.»"},{"pregunta":"¿Qué tres cosas declara Pablo de sí mismo al acercarse su partida, en 4:7?","opciones":["Peleó la buena batalla, acabó la carrera y guardó la fe","Fundó tres iglesias, escribió tres cartas y ganó tres veces su libertad","Viajó por mar, por tierra y por el desierto entero","Dejó discípulos, dejó cartas y dejó una gran fortuna"],"dato":"El apóstol resume su vida con tres imágenes: el combate peleado, la carrera terminada y la fe guardada intacta hasta el final.","cita":"2 Timoteo 4:7","versiculo":"He peleado la buena batalla, he acabado la carrera, he guardado la fe.","vcita":"2 Timoteo 4:7","pista":"«Un luchador, un corredor y un guardián fiel: todo en una frase.»"},{"pregunta":"¿A quién debe traer Timoteo consigo, porque le es útil a Pablo para el ministerio?","opciones":["A Marcos","A Demas","A Crescente","A Tíquico"],"dato":"Aquel Marcos que años atrás se había apartado del equipo, ahora Pablo lo pide de vuelta: restaurado, le es útil para el ministerio. Lucas era el único que permanecía con él.","cita":"2 Timoteo 4:11","versiculo":"Lucas solo está conmigo. Toma á Marcos, y tráele contigo; porque me es útil para el ministerio.","vcita":"2 Timoteo 4:11","pista":"«Tuvo una segunda oportunidad: antes se apartó, ahora es útil.»"}],"Tito":[{"pregunta":"¿Para qué dejó Pablo a Tito en Creta?","opciones":["Para corregir lo que faltaba y poner ancianos por las villas","Para cobrar las ofrendas de la isla y llevarlas a Roma","Para esconderse de las autoridades por un tiempo","Para aprender el idioma y las costumbres de los cretenses"],"dato":"Tito quedó con una misión de orden: completar lo que faltaba en las jóvenes iglesias de la isla y establecer ancianos en cada ciudad.","cita":"Tito 1:5","versiculo":"Por esta causa te dejé en Creta, para que corrigieses lo que falta, y pusieses ancianos por las villas, así como yo te mandé:","vcita":"Tito 1:5","pista":"«Su tarea era de organización: corregir y establecer líderes.»"},{"pregunta":"¿Cómo describió a los cretenses uno de sus propios profetas, citado por Pablo?","opciones":["Siempre mentirosos, malas bestias, vientres perezosos","Grandes navegantes, poetas dulces y valientes","Sabios filósofos, justos y hospitalarios","Pastores humildes, fieles y trabajadores"],"dato":"Pablo cita al poeta cretense Epiménides contra su propia gente; y añade: «este testimonio es verdadero». La iglesia debía ser sana en la fe en medio de esa cultura.","cita":"Tito 1:12","versiculo":"Dijo uno de ellos, propio profeta de ellos: Los Cretenses, siempre mentirosos, malas bestias, vientres perezosos.","vcita":"Tito 1:12","pista":"«La frase no la dice un enemigo: la dice un profeta de ellos mismos.»"},{"pregunta":"Según Tito 1:15, ¿para quiénes son limpias todas las cosas?","opciones":["Para los limpios","Para los que guardan las fiestas","Para los sacerdotes solamente","Para los que no comen carne"],"dato":"La pureza no depende de ritos externos: para los limpios todo es limpio; para los contaminados e infieles, hasta su alma y conciencia están contaminadas.","cita":"Tito 1:15","versiculo":"Todas las cosas son limpias á los limpios; mas á los contaminados é infieles nada es limpio: antes su alma y conciencia están contaminadas.","vcita":"Tito 1:15","pista":"«La limpieza verdadera empieza por dentro, no por el plato.»"},{"pregunta":"¿Qué hacen con sus hechos algunos que profesan conocer a Dios, según Tito 1:16?","opciones":["Lo niegan, siendo reprobados para toda buena obra","Lo honran en todo lo que emprenden","Lo ocultan solo por miedo a los romanos","Lo sirven en secreto, de noche"],"dato":"Hay una contradicción fatal: de boca conocen a Dios, pero su conducta lo niega; son reprobados en cuanto a toda buena obra.","cita":"Tito 1:16","versiculo":"Profésanse conocer á Dios; mas con los hechos lo niegan, siendo abominables y rebeldes, reprobados para toda buena obra.","vcita":"Tito 1:16","pista":"«Sus palabras dicen una cosa y sus hechos dicen lo contrario.»"},{"pregunta":"¿Qué deben enseñar las mujeres ancianas a las jóvenes, según Tito 2:4?","opciones":["A ser prudentes, amar a sus maridos y amar a sus hijos","A predicar en las plazas de cada villa","A administrar los negocios de los gentiles","A memorizar las genealogías de Israel"],"dato":"La sana doctrina se transmite también en casa: las ancianas forman a las jóvenes en prudencia y en amor a su esposo y a sus hijos.","cita":"Tito 2:4","versiculo":"Que enseñen á las mujeres jóvenes á ser prudentes, á que amen á sus maridos, á que amen á sus hijos,","vcita":"Tito 2:4","pista":"«La lección principal gira alrededor de su propio hogar.»"},{"pregunta":"¿Qué se manifestó trayendo salvación a todos los hombres, según Tito 2:11?","opciones":["La gracia de Dios","La ley renovada de Moisés","El edicto de un emperador","Una señal en el cielo de Creta"],"dato":"La gracia de Dios apareció como una luz para todos: no salva a un grupo reducido, sino que trae salvación a todos los hombres.","cita":"Tito 2:11","versiculo":"Porque la gracia de Dios que trae salvación á todos los hombres, se manifestó,","vcita":"Tito 2:11","pista":"«No apareció una ley nueva: apareció su favor inmerecido.»"},{"pregunta":"¿Qué esperanza aguardamos según Tito 2:13?","opciones":["La esperanza bienaventurada y la manifestación gloriosa del gran Dios y Salvador Jesucristo","La llegada de un nuevo apóstol a Creta","La reconstrucción del templo de Jerusalén","El perdón general del emperador romano"],"dato":"El creyente vive mirando hacia adelante: espera la aparición gloriosa de Jesucristo, llamado aquí gran Dios y Salvador nuestro.","cita":"Tito 2:13","versiculo":"Esperando aquella esperanza bienaventurada, y la manifestación gloriosa del gran Dios y Salvador nuestro Jesucristo,","vcita":"Tito 2:13","pista":"«Es una esperanza dichosa... y una manifestación gloriosa.»"},{"pregunta":"¿Para qué se dio Cristo a sí mismo por nosotros, según Tito 2:14?","opciones":["Para redimirnos de toda iniquidad y limpiar para sí un pueblo propio, celoso de buenas obras","Para enriquecernos con bienes temporales","Para librarnos de todo trabajo y esfuerzo","Para fundar un reino solo en la isla de Creta"],"dato":"La redención no termina en el perdón: Cristo se entregó para purificar un pueblo que le pertenece y arde en celo por las buenas obras.","cita":"Tito 2:14","versiculo":"Que se dió á sí mismo por nosotros para redimirnos de toda iniquidad, y limpiar para sí un pueblo propio, celoso de buenas obras.","vcita":"Tito 2:14","pista":"«Su pueblo se reconoce por una marca: el celo de hacer el bien.»"},{"pregunta":"¿Cómo nos salvó Dios, según Tito 3:5?","opciones":["No por obras de justicia nuestras, sino por su misericordia, por el lavacro de la regeneración y la renovación del Espíritu Santo","Por las obras de justicia que habíamos acumulado","Por los méritos de nuestros padres creyentes","Por guardar perfectamente las fiestas y sábados"],"dato":"La salvación no fue un premio a nuestras obras: fue misericordia pura, obrada por el nuevo nacimiento y la renovación del Espíritu Santo.","cita":"Tito 3:5","versiculo":"No por obras de justicia que nosotros habíamos hecho, mas por su misericordia nos salvó, por el lavacro de la regeneración, y de la renovación del Espíritu Santo;","vcita":"Tito 3:5","pista":"«Dos palabras lo resumen: misericordia, no méritos.»"},{"pregunta":"¿Qué debe evitar Tito según Tito 3:9?","opciones":["Las cuestiones necias, genealogías, contenciones y debates acerca de la ley","El trato con los marineros del puerto","La predicación a los gentiles de la isla","Toda lectura de los profetas antiguos"],"dato":"Esas discusiones son «sin provecho y vanas»: consumen la energía que debe gastarse en las buenas obras y en la sana enseñanza.","cita":"Tito 3:9","versiculo":"Mas las cuestiones necias, y genealogías, y contenciones, y debates acerca de la ley, evita; porque son sin provecho y vanas.","vcita":"Tito 3:9","pista":"«Son pleitos de palabras que no aprovechan a nadie.»"},{"pregunta":"¿En qué ciudad había determinado Pablo pasar el invierno (invernar)?","opciones":["En Nicópolis","En Corinto","En Alejandría","En Tarso, su ciudad natal"],"dato":"Pablo pide a Tito que, cuando llegue su relevo (Artemas o Tíquico), procure ir a verlo a Nicópolis, donde pasaría el invierno.","cita":"Tito 3:12","versiculo":"Cuando enviare á ti á Artemas, ó á Tichîco, procura venir á mí, á Nicópolis: porque allí he determinado invernar.","vcita":"Tito 3:12","pista":"«Es una ciudad griega cuyo nombre significa «ciudad de la victoria».»"}],"Filemón":[{"pregunta":"¿Cómo se presenta Pablo a sí mismo al abrir esta carta, en lugar de llamarse apóstol?","opciones":["Prisionero de Jesucristo","Apóstol de los gentiles","Siervo de la iglesia de Roma","Anciano de Jerusalén"],"dato":"En esta carta personal Pablo suaviza su autoridad: no firma como apóstol, sino como prisionero de Jesucristo, junto al hermano Timoteo.","cita":"Filemón 1:1","versiculo":"PABLO, prisionero de Jesucristo, y el hermano Timoteo, á Filemón amado, y coadjutor nuestro;","vcita":"Filemón 1:1","pista":"«Su título aquí no es su cargo, sino su condición en la cárcel.»"},{"pregunta":"¿Cómo llama Pablo a Arquipo en el saludo de la carta?","opciones":["Compañero de nuestra milicia","Hijo mío en la fe","El médico amado","Mayordomo de la iglesia"],"dato":"El saludo va dirigido a Filemón, a la amada Apia, a Arquipo —llamado compañero de milicia— y a la iglesia que se reúne en casa de Filemón.","cita":"Filemón 1:2","versiculo":"Y á la amada Apphia, y á Archîpo, compañero de nuestra milicia, y á la iglesia [que está] en tu casa:","vcita":"Filemón 1:2","pista":"«El título suena a soldado que pelea en la misma tropa.»"},{"pregunta":"¿Qué dos cosas oye Pablo de Filemón y da gracias por ellas?","opciones":["Su caridad y su fe en el Señor Jesús y para con todos los santos","Su riqueza y su generosidad con los pobres de Judea","Su conocimiento y su celo por la ley","Sus muchos viajes y sus cartas a las iglesias"],"dato":"La fama de Filemón era doble: amor en acción y fe firme, tanto hacia el Señor Jesús como hacia todos los santos.","cita":"Filemón 1:5","versiculo":"Oyendo tu caridad, y la fe que tienes en el Señor Jesús, y para con todos los santos;","vcita":"Filemón 1:5","pista":"«Una mira a Cristo y la otra se vuelca sobre los santos.»"},{"pregunta":"¿Qué efecto tenía la caridad de Filemón sobre los santos, según el versículo 7?","opciones":["Por él habían sido recreadas (refrescadas) las entrañas de los santos","Los santos habían decidido ayunar cada semana","Los santos habían reunido dinero para Roma","Los santos le habían nombrado obispo de la ciudad"],"dato":"Filemón era un refrigerio para los creyentes: su amor generoso confortaba y refrescaba el corazón de los santos, y eso daba a Pablo gran gozo y consolación.","cita":"Filemón 1:7","versiculo":"Porque tenemos gran gozo y consolación de tu caridad, de que por ti, oh hermano, han sido recreadas las entrañas de los santos.","vcita":"Filemón 1:7","pista":"«Su bondad funcionaba como un vaso de agua fresca para todos.»"},{"pregunta":"¿Cómo se describe Pablo a sí mismo al hacer su ruego en el versículo 9?","opciones":["Pablo viejo (anciano), y ahora prisionero de Jesucristo","Apóstol joven y lleno de libertad en Cristo","Fariseo de fariseos, celoso de la ley","Ciudadano romano en espera de juicio"],"dato":"Pablo podría mandar con autoridad apostólica, pero prefiere rogar por amor, presentándose como un anciano que además está preso por Jesucristo.","cita":"Filemón 1:9","versiculo":"Ruégo[te] más bien por amor, siendo tal cual [soy], Pablo viejo, y aun ahora prisionero de Jesucristo:","vcita":"Filemón 1:9","pista":"«No apela a su rango: apela a su edad y a sus cadenas.»"},{"pregunta":"¿A quién llama Pablo «mi hijo, que he engendrado en mis prisiones»?","opciones":["A Onésimo","A Tito","A Arquipo","A Apolos"],"dato":"Onésimo, esclavo fugitivo de Filemón, conoció el evangelio junto al preso Pablo y llegó a ser como un hijo para él en la fe.","cita":"Filemón 1:10","versiculo":"Ruégote por mi hijo Onésimo, que he engendrado en mis prisiones,","vcita":"Filemón 1:10","pista":"«Es el esclavo por quien Pablo escribe toda esta carta.»"},{"pregunta":"¿Qué juego de palabras hace Pablo con Onésimo en el versículo 11?","opciones":["Que antes le fue inútil, pero ahora le es útil a Filemón y a Pablo","Que antes era veloz, pero ahora camina despacio","Que antes era rico, pero ahora sirve como pobre","Que antes era fariseo, y ahora es publicano"],"dato":"«Onésimo» significa «útil» o «provechoso»: Pablo juega con su nombre — el fugitivo que parecía inútil ha vuelto transformado y ahora sí hace honor a su nombre.","cita":"Filemón 1:11","versiculo":"El cual en otro tiempo te fué inútil, mas ahora á ti y á mí es útil;","vcita":"Filemón 1:11","pista":"«Su propio nombre significa «útil»... y por fin lo es.»"},{"pregunta":"¿Cómo debe recibir ahora Filemón a Onésimo, según el versículo 16?","opciones":["No ya como siervo, sino más que siervo: como hermano amado","Como siervo castigado con doble trabajo","Como un huésped que paga su hospedaje","Como un extraño al que solo se saluda"],"dato":"El evangelio cambió la relación: Onésimo vuelve a casa, pero ya no solo como esclavo; en la carne y en el Señor, es un hermano muy amado.","cita":"Filemón 1:16","versiculo":"No ya como siervo, antes más que siervo, [como] hermano amado, mayormente de mí, pero cuánto más de ti, en la carne y en el Señor.","vcita":"Filemón 1:16","pista":"«Regresa con el mismo nombre, pero con una relación nueva: hermano.»"},{"pregunta":"Si Onésimo dañó en algo a Filemón o le debe algo, ¿qué pide Pablo?","opciones":["Que lo ponga a su cuenta, porque él lo pagará","Que lo cobre con intereses dobles","Que lo perdone sin que nadie pague nada","Que lo venda para saldar la deuda"],"dato":"Pablo firma un pagaré personal: «si en algo te dañó, o te debe, ponlo a mi cuenta», y en el versículo siguiente añade que lo escribió de su mano y que él lo pagará.","cita":"Filemón 1:18","versiculo":"Y si en algo te dañó, ó te debe, ponlo á mi cuenta.","vcita":"Filemón 1:18","pista":"«El apóstol ofrece su propio bolsillo como garantía.»"},{"pregunta":"¿Qué pide Pablo que le preparen en casa de Filemón, según el versículo 22?","opciones":["Alojamiento, porque espera serles concedido por sus oraciones","Una fiesta de bienvenida con toda la iglesia","Un barco para seguir viaje a España","Copias de la carta para las iglesias vecinas"],"dato":"Con delicadeza y presión amable a la vez, Pablo anuncia su visita: espera salir libre gracias a las oraciones de ellos, y espera quedarse en casa de Filemón.","cita":"Filemón 1:22","versiculo":"Y asimismo prepárame también alojamiento; porque espero que por vuestras oraciones os tengo de ser concedido.","vcita":"Filemón 1:22","pista":"«Irás preparando el cuarto de huéspedes... el apóstol viene en camino.»"},{"pregunta":"¿Quién saluda a Filemón como «compañero en la prisión» de Pablo por Cristo Jesús?","opciones":["Epafras","Aristarco","Demas","Tíquico"],"dato":"Epafras, el mismo que había llevado el evangelio a Colosos, compartía entonces la prisión con Pablo y encabeza los saludos finales de la carta.","cita":"Filemón 1:23","versiculo":"Te saludan Epafras, mi compañero en la prisión por Cristo Jesús,","vcita":"Filemón 1:23","pista":"«Es el fiel ministro que evangelizó a los colosenses.»"}],"Hebreos":[{"pregunta":"Según Hebreos 1, ¿por medio de quién nos ha hablado Dios en estos postreros días?","opciones":["Por su Hijo, a quien constituyó heredero de todo","Por los profetas, como en los tiempos antiguos","Por medio de sueños dados a los sacerdotes","Por la voz de los ángeles en el monte"],"dato":"En otro tiempo Dios habló por los profetas; en estos postreros días nos ha hablado por el Hijo, por quien también hizo el universo.","cita":"Hebreos 1:2","versiculo":"En estos postreros días nos ha hablado por el Hijo, al cual constituyó heredero de todo, por el cual asimismo hizo el universo:","vcita":"Hebreos 1:2","pista":"«Ya no es un mensajero más: es el Heredero mismo.»"},{"pregunta":"¿Con qué compara Hebreos a la palabra de Dios por ser viva y eficaz?","opciones":["Con una espada de dos filos","Con un martillo que quebranta la piedra","Con una lámpara en la oscuridad","Con un río de aguas vivas"],"dato":"La palabra de Dios es viva y eficaz, más penetrante que toda espada de dos filos: alcanza hasta partir el alma y el espíritu, y discierne los pensamientos del corazón.","cita":"Hebreos 4:12","versiculo":"Porque la palabra de Dios es viva y eficaz, y más penetrante que toda espada de dos filos: y que alcanza hasta partir el alma, y aun el espíritu, y las coyunturas y tuétanos, y discierne los pensamientos y las intenciones del corazón.","vcita":"Hebreos 4:12","pista":"«Corta por los dos lados y llega hasta los tuétanos.»"},{"pregunta":"¿Qué afirma Hebreos 4:15 de nuestro sumo sacerdote?","opciones":["Que fue tentado en todo según nuestra semejanza, pero sin pecado","Que nunca conoció la debilidad humana","Que solo intercede por los que no pecan","Que fue un ángel enviado a la tierra"],"dato":"No tenemos un sumo sacerdote que no pueda compadecerse de nuestras flaquezas: fue tentado en todo como nosotros, pero sin pecado.","cita":"Hebreos 4:15","versiculo":"Porque no tenemos un Pontífice que no se pueda compadecer de nuestras flaquezas; mas tentado en todo según nuestra semejanza, pero sin pecado.","vcita":"Hebreos 4:15","pista":"«Probado en todo… y salió limpio.»"},{"pregunta":"Al interpretar el nombre de Melquisedec, ¿qué significa que sea «Rey de Salem»?","opciones":["Rey de paz","Rey de justicia","Rey de los sacerdotes","Rey de Jerusalén"],"dato":"Melquisedec se interpreta primero Rey de justicia, y luego también Rey de Salem, que es Rey de paz; Abraham le dio los diezmos de todo.","cita":"Hebreos 7:2","versiculo":"Al cual asimismo dio Abraham los diezmos de todo, primeramente él se interpreta Rey de justicia; y luego también Rey de Salem, que es, Rey de paz;","vcita":"Hebreos 7:2","pista":"«Salem suena a shalom: piensa en lo contrario de la guerra.»"},{"pregunta":"¿Por qué puede Cristo salvar eternamente a los que por él se acercan a Dios?","opciones":["Porque vive siempre para interceder por ellos","Porque su sacerdocio es según el orden de Aarón","Porque ofreció sacrificios cada año","Porque nunca salió del santuario terrenal"],"dato":"Cristo puede salvar eternamente a los que por él se allegan a Dios, porque vive siempre para interceder por ellos: su sacerdocio no se interrumpe con la muerte.","cita":"Hebreos 7:25","versiculo":"Por lo cual puede también salvar eternamente a los que por él se allegan a Dios, viviendo siempre para interceder por ellos.","vcita":"Hebreos 7:25","pista":"«Su intercesión nunca se toma vacaciones.»"},{"pregunta":"Según Hebreos 9:22, ¿qué NO se hace sin derramamiento de sangre?","opciones":["La remisión de los pecados","La purificación del tabernáculo","La celebración de la Pascua","La unción de los sacerdotes"],"dato":"Casi todo era purificado según la ley con sangre; y sin derramamiento de sangre no se hace remisión: el perdón requirió la sangre de Cristo.","cita":"Hebreos 9:22","versiculo":"Y casi todo es purificado según la ley con sangre; y sin derramamiento de sangre no se hace remisión.","vcita":"Hebreos 9:22","pista":"«Perdón sin sangre derramada: no existe, dice el texto.»"},{"pregunta":"Según Hebreos 9:27, ¿qué viene después de que el hombre muere una vez?","opciones":["El juicio","Otra vida en la tierra","El sueño eterno sin despertar","La purificación por fuego"],"dato":"Está establecido a los hombres que mueran una vez, y después de esto, el juicio: no hay segundas vueltas en esta vida.","cita":"Hebreos 9:27","versiculo":"Y de la manera que está establecido a los hombres que mueran una vez, y después el juicio;","vcita":"Hebreos 9:27","pista":"«Una sola muerte, y luego a rendir cuentas.»"},{"pregunta":"¿Qué costumbre de algunos reprueba Hebreos 10:25?","opciones":["Dejar de congregarse","Ayunar sin orar","Diezmar solo una vez al año","Enseñar sin ser enviados"],"dato":"Hebreos manda a no dejar nuestra congregación, como algunos tienen por costumbre, sino a exhortarnos unos a otros, y más al ver que el día se acerca.","cita":"Hebreos 10:25","versiculo":"No dejando nuestra congregación, como algunos tienen por costumbre, mas exhortándonos; y tanto más, cuanto veis que aquel día se acerca.","vcita":"Hebreos 10:25","pista":"«Tiene que ver con reunirse… o con faltar a la reunión.»"},{"pregunta":"Completa la definición de Hebreos 11:1: «Es, pues, la fe la sustancia de las cosas que se esperan, la ______ de las cosas que no se ven».","opciones":["Demostración","Convicción","Esperanza segura","Sombra fiel"],"dato":"Hebreos 11:1 define la fe como la sustancia de las cosas que se esperan y la demostración de las cosas que no se ven: el capítulo entero ilustra esa definición.","cita":"Hebreos 11:1","versiculo":"Es pues la fe la sustancia de las cosas que se esperan, la demostración de las cosas que no se ven.","vcita":"Hebreos 11:1","pista":"«No es un deseo: es una prueba, una demostración.»"},{"pregunta":"Según Hebreos 11:6, ¿qué es imposible sin fe?","opciones":["Agradar a Dios","Conocer la ley de Moisés","Guardar el día de reposo","Ofrecer sacrificios aceptables"],"dato":"Sin fe es imposible agradar a Dios, porque el que se allega a Dios debe creer que le hay, y que es galardonador de los que le buscan.","cita":"Hebreos 11:6","versiculo":"Empero sin fe es imposible agradar a Dios; porque es menester que el que a Dios se allega, crea que le hay, y que es galardonador de los que le buscan.","vcita":"Hebreos 11:6","pista":"«La fe no es opcional para agradarle: es la puerta.»"},{"pregunta":"¿Qué rehusó Moisés, ya grande, por la fe, según Hebreos 11:24?","opciones":["Ser llamado hijo de la hija de Faraón","Ser llamado dios por los egipcios","Recibir la corona de Egipto en vida","Guiar a Israel sin pasar por el desierto"],"dato":"Por la fe, Moisés ya grande rehusó ser llamado hijo de la hija de Faraón, escogiendo ser maltratado con el pueblo de Dios antes que gozar los deleites temporales del pecado.","cita":"Hebreos 11:24","versiculo":"Por la fe Moisés, hecho ya grande, rehusó ser llamado hijo de la hija de Faraón;","vcita":"Hebreos 11:24","pista":"«Cambió el palacio por el pueblo de Dios.»"},{"pregunta":"¿Qué se afirma de Jesucristo en Hebreos 13:8?","opciones":["Que es el mismo ayer, y hoy, y por los siglos","Que fue el primero de los profetas","Que cambia según la madurez de su pueblo","Que dejó de interceder tras ascender"],"dato":"Jesucristo es el mismo ayer, y hoy, y por los siglos: en un mundo que cambia, Él no cambia.","cita":"Hebreos 13:8","versiculo":"Jesucristo es el mismo ayer, y hoy, y por los siglos.","vcita":"Hebreos 13:8","pista":"«Tres tiempos, una sola palabra: el mismo.»"}],"Santiago":[{"pregunta":"Según Santiago 1:5, ¿qué debe hacer el que tiene falta de sabiduría?","opciones":["Pedírsela a Dios, que da a todos abundantemente","Buscarla en los ancianos de su tierra","Esperar a que llegue con los años","Estudiar los libros de los sabios"],"dato":"Si alguno tiene falta de sabiduría, demándela a Dios, el cual da a todos abundantemente y sin reproche; y le será dada.","cita":"Santiago 1:5","versiculo":"Y si alguno de vosotros tiene falta de sabiduría, demándela a Dios, el cual da a todos abundantemente, y no zahiere; y le será dada.","vcita":"Santiago 1:5","pista":"«No viene de los años: se pide hacia arriba.»"},{"pregunta":"Cuando alguien es tentado, ¿qué NO debe decir, según Santiago 1:13?","opciones":["«Soy tentado de Dios»","«El diablo me ha vencido»","«Mi pecado no tiene remedio»","«Nadie conoce mi lucha»"],"dato":"Dios no puede ser tentado por el mal, ni él tienta a alguno: la tentación nace de la propia concupiscencia del hombre, no de Dios.","cita":"Santiago 1:13","versiculo":"Cuando alguno es tentado, no diga que es tentado de Dios: porque Dios no puede ser tentado de los malos, ni él tienta a alguno:","vcita":"Santiago 1:13","pista":"«Echarle la culpa a Dios: eso es lo prohibido.»"},{"pregunta":"¿De quién desciende toda buena dádiva y todo don perfecto, según Santiago 1:17?","opciones":["Del Padre de las luces, en quien no hay mudanza","De los ángeles que sirven en el cielo","Del esfuerzo del hombre justo","De la generosidad de los gobernantes"],"dato":"Toda buena dádiva y todo don perfecto es de lo alto, que desciende del Padre de las luces, en el cual no hay mudanza ni sombra de variación.","cita":"Santiago 1:17","versiculo":"Toda buena dádiva y todo don perfecto es de lo alto, que desciende del Padre de las luces, en el cual no hay mudanza, ni sombra de variación.","vcita":"Santiago 1:17","pista":"«Todo lo bueno baja del mismo lugar: del Padre.»"},{"pregunta":"¿Qué manda Santiago 1:22 acerca de la palabra?","opciones":["Ser hacedores de ella, y no tan solamente oidores","Memorizarla antes que obedecerla","Escucharla solo en el día de reposo","Enseñarla antes de practicarla"],"dato":"Santiago ordena ser hacedores de la palabra y no tan solamente oidores, porque oír sin obedecer es engañarse a uno mismo.","cita":"Santiago 1:22","versiculo":"Mas sed hacedores de la palabra, y no tan solamente oidores, engañándoos a vosotros mismos.","vcita":"Santiago 1:22","pista":"«Oír es la mitad; la otra mitad es hacer.»"},{"pregunta":"¿Qué es la religión pura y sin mácula delante de Dios, según Santiago 1:27?","opciones":["Visitar a los huérfanos y a las viudas en sus tribulaciones, y guardarse sin mancha del mundo","Ayunar dos veces por semana y diezmarlo todo","No trabajar en día de reposo","Peregrinar cada año a Jerusalén"],"dato":"La religión pura delante de Dios es esta: visitar los huérfanos y las viudas en sus tribulaciones, y guardarse sin mancha de este mundo.","cita":"Santiago 1:27","versiculo":"La religión pura y sin mácula delante de Dios y Padre es esta: Visitar los huérfanos y las viudas en sus tribulaciones, y guardarse sin mancha de este mundo.","vcita":"Santiago 1:27","pista":"«Menos ritual, más visita a quien sufre.»"},{"pregunta":"Completa Santiago 2:17: «Así también la fe, si no tuviere ______, es muerta en sí misma».","opciones":["Obras","Palabras elocuentes","Testigos","Sentimientos"],"dato":"La fe sin obras es muerta en sí misma: la fe verdadera se demuestra con hechos, no solo con confesiones.","cita":"Santiago 2:17","versiculo":"Así también la fe, si no tuviere obras, es muerta en sí misma.","vcita":"Santiago 2:17","pista":"«Fe con las manos vacías: fe muerta.»"},{"pregunta":"¿Qué dice Santiago 2:19 que también hacen los demonios?","opciones":["Creen que Dios es uno, y tiemblan","Oran sin cesar por los hombres","Guardan los mandamientos antiguos","Confiesan sus pecados y se arrepienten"],"dato":"Creer que Dios es uno no basta: también los demonios creen, y tiemblan; la diferencia está en obedecer, no solo en creer.","cita":"Santiago 2:19","versiculo":"Tú crees que Dios es uno; bien haces: también los demonios creen, y tiemblan.","vcita":"Santiago 2:19","pista":"«Hasta los demonios «creen»… y tiemblan.»"},{"pregunta":"¿Qué título hermoso recibió Abraham según Santiago 2:23?","opciones":["Amigo de Dios","Padre de reyes","Príncipe de la paz","Varón conforme al corazón de Dios"],"dato":"Abraham creyó a Dios, y le fue imputado a justicia, y fue llamado amigo de Dios: su fe se vio en su obediencia.","cita":"Santiago 2:23","versiculo":"Y fue cumplida la Escritura que dice: Abraham creyó a Dios, y le fue imputado a justicia, y fue llamado amigo de Dios.","vcita":"Santiago 2:23","pista":"«No siervo, no rey: amigo.»"},{"pregunta":"¿Qué miembro del cuerpo dice Santiago que ningún hombre puede domar?","opciones":["La lengua","La mano","El ojo","El oído"],"dato":"Ningún hombre puede domar la lengua, un mal que no puede ser refrenado y está llena de veneno mortal; por eso hay que guardar lo que se dice.","cita":"Santiago 3:8","versiculo":"Pero ningún hombre puede domar la lengua, que es un mal que no puede ser refrenado; llena de veneno mortal.","vcita":"Santiago 3:8","pista":"«Pequeña, veloz y con veneno: está en la boca.»"},{"pregunta":"Completa Santiago 4:7: «Someteos, pues, a Dios; resistid al diablo, y ______».","opciones":["De vosotros huirá","Será avergonzado para siempre","No podrá tocar a vuestros hijos","Confesará sus maldades"],"dato":"La receta de Santiago es doble: someterse a Dios y resistir al diablo; el resultado prometido es que el diablo huirá.","cita":"Santiago 4:7","versiculo":"Someteos pues a Dios; resistid al diablo, y de vosotros huirá.","vcita":"Santiago 4:7","pista":"«Primero rendirse a Dios; después, plantar cara.»"},{"pregunta":"¿En quién está el pecado, según Santiago 4:17?","opciones":["En el que sabe hacer lo bueno, y no lo hace","En el que duda de su salvación","En el que no conoce la ley","En el que peca sin darse cuenta"],"dato":"Santiago enseña el pecado de omisión: el pecado está en aquel que sabe hacer lo bueno y no lo hace.","cita":"Santiago 4:17","versiculo":"El pecado, pues, está en aquel que sabe hacer lo bueno, y no lo hace.","vcita":"Santiago 4:17","pista":"«No hizo nada malo… y ese fue el problema.»"},{"pregunta":"Completa Santiago 5:16: «La oración del justo, obrando eficazmente, ______».","opciones":["Puede mucho","Rompe cadenas","Mueve montañas","Abre los cielos"],"dato":"Santiago manda a confesar las faltas unos a otros y a orar los unos por los otros; la oración del justo, obrando eficazmente, puede mucho.","cita":"Santiago 5:16","versiculo":"Confesaos vuestras faltas unos a otros, y rogad los unos por los otros, para que seáis sanos; la oración del justo, obrando eficazmente, puede mucho.","vcita":"Santiago 5:16","pista":"«Dos palabras bastan: puede… ¿qué?»"}],"1 Pedro":[{"pregunta":"¿Para qué nos hizo renacer Dios según su grande misericordia, según 1 Pedro 1:3?","opciones":["Para una esperanza viva, por la resurrección de Jesucristo de los muertos","Para heredar riquezas en esta vida","Para no pasar jamás por pruebas","Para juzgar a las naciones con Él"],"dato":"El Dios y Padre de nuestro Señor Jesucristo, según su grande misericordia, nos ha regenerado en esperanza viva por la resurrección de Jesucristo.","cita":"1 Pedro 1:3","versiculo":"Bendito el Dios y Padre de nuestro Señor Jesucristo, que según su grande misericordia nos ha regenerado en esperanza viva, por la resurrección de Jesucristo de los muertos,","vcita":"1 Pedro 1:3","pista":"«Una esperanza que no está muerta: está viva.»"},{"pregunta":"¿Con qué fuimos rescatados de nuestra vana conversación, según 1 Pedro 1:19?","opciones":["Con la sangre preciosa de Cristo, como de un cordero sin mancha","Con oro y plata corruptibles","Con sacrificios de animales sin defecto","Con las buenas obras de nuestros padres"],"dato":"No fuimos rescatados con cosas corruptibles, como oro o plata, sino con la sangre preciosa de Cristo, como de un cordero sin mancha y sin contaminación.","cita":"1 Pedro 1:19","versiculo":"Sino con la sangre preciosa de Cristo, como de un cordero sin mancha y sin contaminación:","vcita":"1 Pedro 1:19","pista":"«El precio no fue metal: fue sangre.»"},{"pregunta":"Según 1 Pedro 1:25, ¿qué permanece perpetuamente?","opciones":["La palabra del Señor","La hierba de los campos","La hermosura del hombre","Las riquezas de los reyes"],"dato":"Toda carne es como hierba y se seca; mas la palabra del Señor permanece perpetuamente, y esa es la palabra anunciada por el evangelio.","cita":"1 Pedro 1:25","versiculo":"Mas la palabra del Señor permanece perpetuamente. Y esta es la palabra que por el evangelio os ha sido anunciada.","vcita":"1 Pedro 1:25","pista":"«La hierba se seca; esto otro, jamás.»"},{"pregunta":"¿Qué debemos desear como niños recién nacidos, según 1 Pedro 2:2?","opciones":["La leche espiritual, sin engaño","Los manjares de los adultos","La alabanza de los hombres","Los dones más vistosos"],"dato":"Pedro manda a desear, como niños recién nacidos, la leche espiritual sin engaño, para crecer por ella en salud.","cita":"1 Pedro 2:2","versiculo":"Desead, como niños recién nacidos, la leche espiritual, sin engaño, para que por ella crezcáis en salud:","vcita":"1 Pedro 2:2","pista":"«Para crecer, el alimento más sencillo y puro.»"},{"pregunta":"¿Cómo piedras de qué clase somos edificados en casa espiritual, según 1 Pedro 2:5?","opciones":["Como piedras vivas","Como piedras talladas por hombres","Como piedras del antiguo templo","Como piedras preciosas del sumo sacerdote"],"dato":"Acercándonos a Cristo, la piedra viva, nosotros también, como piedras vivas, somos edificados en una casa espiritual y un sacerdocio santo.","cita":"1 Pedro 2:5","versiculo":"Vosotros también, como piedras vivas, sed edificados una casa espiritual, y un sacerdocio santo, para ofrecer sacrificios espirituales, agradables a Dios por Jesucristo.","vcita":"1 Pedro 2:5","pista":"«En esta casa, las piedras respiran.»"},{"pregunta":"¿Qué cuatro títulos da Pedro al pueblo de Dios en 1 Pedro 2:9?","opciones":["Linaje escogido, real sacerdocio, gente santa, pueblo adquirido","Profetas, reyes, jueces y levitas","Apóstoles, pastores, maestros y evangelistas","Peregrinos, esclavos, siervos y desterrados"],"dato":"Vosotros sois linaje escogido, real sacerdocio, gente santa, pueblo adquirido, para anunciar las virtudes del que nos llamó de las tinieblas a su luz admirable.","cita":"1 Pedro 2:9","versiculo":"Mas vosotros sois linaje escogido, real sacerdocio, gente santa, pueblo adquirido, para que anunciéis las virtudes de aquel que os ha llamado de las tinieblas a su luz admirable:","vcita":"1 Pedro 2:9","pista":"«Son cuatro títulos de honor, todos en un versículo.»"},{"pregunta":"Completa 1 Pedro 2:24: «Él llevó nuestros pecados en su cuerpo sobre el madero… por la herida del cual ______».","opciones":["Habéis sido sanados","Habéis sido ocultados","Habéis sido probados","Habéis sido llamados"],"dato":"Cristo mismo llevó nuestros pecados en su cuerpo sobre el madero, para que nosotros, muertos a los pecados, vivamos a la justicia; por su herida fuimos sanados.","cita":"1 Pedro 2:24","versiculo":"El cual mismo llevó nuestros pecados en su cuerpo sobre el madero, para que nosotros siendo muertos a los pecados, vivamos a la justicia: por la herida del cual habéis sido sanados.","vcita":"1 Pedro 2:24","pista":"«Su herida produjo nuestra sanidad.»"},{"pregunta":"¿Para qué debemos estar siempre preparados, según 1 Pedro 3:15?","opciones":["Para responder con mansedumbre a quien demande razón de la esperanza que hay en nosotros","Para debatir con los filósofos de la ciudad","Para huir en tiempo de persecución","Para guardar silencio ante los incrédulos"],"dato":"Pedro manda a santificar al Señor en el corazón y estar siempre aparejados para responder con mansedumbre y reverencia a quien pida razón de nuestra esperanza.","cita":"1 Pedro 3:15","versiculo":"Sino santificad al Señor Dios en vuestros corazones, y estad siempre aparejados para responder con mansedumbre y reverencia a cada uno que os demande razón de la esperanza que hay en vosotros:","vcita":"1 Pedro 3:15","pista":"«Siempre listos… pero con mansedumbre.»"},{"pregunta":"Según 1 Pedro 3:18, ¿quién padeció una vez por los pecados, el justo por los injustos, para llevarnos a Dios?","opciones":["Cristo","Pedro","Un ángel del cielo","El sumo sacerdote Caifás"],"dato":"También Cristo padeció una vez por los pecados, el justo por los injustos, para llevarnos a Dios: muerto en la carne, pero vivificado en espíritu.","cita":"1 Pedro 3:18","versiculo":"Porque también Cristo padeció una vez por los pecados, el justo por los injustos, para llevarnos a Dios, siendo a la verdad muerto en la carne, pero vivificado en espíritu;","vcita":"1 Pedro 3:18","pista":"«Una sola vez, un justo, por muchos injustos.»"},{"pregunta":"Completa 1 Pedro 4:8: «Tened entre vosotros ferviente caridad; porque la caridad ______ multitud de pecados».","opciones":["Cubrirá","Olvidará","Juzgará","Revelará"],"dato":"Sobre todo, Pedro manda a tener ferviente caridad entre nosotros, porque la caridad cubrirá multitud de pecados.","cita":"1 Pedro 4:8","versiculo":"Y sobre todo, tened entre vosotros ferviente caridad; porque la caridad cubrirá multitud de pecados.","vcita":"1 Pedro 4:8","pista":"«El amor no cuenta los pecados: los cubre.»"},{"pregunta":"¿Por qué debemos echar toda nuestra solicitud sobre Dios, según 1 Pedro 5:7?","opciones":["Porque él tiene cuidado de nosotros","Porque Él castiga a los descuidados","Porque así lo ordenó la ley de Moisés","Porque los ángeles llevan la cuenta"],"dato":"Echando toda vuestra solicitud en él, porque él tiene cuidado de vosotros: la ansiedad se entrega, no se carga.","cita":"1 Pedro 5:7","versiculo":"Echando toda vuestra solicitud en él, porque él tiene cuidado de vosotros.","vcita":"1 Pedro 5:7","pista":"«Suelta la carga: alguien se ocupa de ti.»"},{"pregunta":"¿Cómo describe 1 Pedro 5:8 a nuestro adversario el diablo?","opciones":["Cual león rugiente, anda alrededor buscando a quien devore","Como serpiente escondida en el polvo","Como lobo vestido de oveja","Como tormenta que viene de lejos"],"dato":"Sed templados y velad, porque vuestro adversario el diablo, cual león rugiente, anda alrededor buscando a quien devore.","cita":"1 Pedro 5:8","versiculo":"Sed templados, y velad; porque vuestro adversario el diablo, cual león rugiente, anda alrededor buscando a quien devore:","vcita":"1 Pedro 5:8","pista":"«Ruge y ronda: hay que estar despiertos.»"}],"2 Pedro":[{"pregunta":"¿De qué somos hechos participantes por las preciosas y grandísimas promesas, según 2 Pedro 1:4?","opciones":["De la naturaleza divina","De los sufrimientos de los apóstoles","De la herencia de Abraham","Del sacerdocio levítico"],"dato":"Por las preciosas y grandísimas promesas somos hechos participantes de la naturaleza divina, habiendo huido de la corrupción que está en el mundo por concupiscencia.","cita":"2 Pedro 1:4","versiculo":"Por las cuales nos son dadas preciosas y grandísimas promesas, para que por ellas fueseis hechos participantes de la naturaleza divina, habiendo huído de la corrupción que está en el mundo por concupiscencia.","vcita":"2 Pedro 1:4","pista":"«No es poca cosa: participar de la naturaleza de Dios.»"},{"pregunta":"En la cadena de 2 Pedro 1, ¿qué debe mostrarse primero en la fe, con toda diligencia?","opciones":["Virtud","Ciencia","Templanza","Amor fraternal"],"dato":"Pedro ordena poner toda diligencia: mostrar en la fe virtud, y en la virtud ciencia; la cadena sigue hasta llegar al amor.","cita":"2 Pedro 1:5","versiculo":"Vosotros también, poniendo toda diligencia por esto mismo, mostrad en vuestra fe virtud, y en la virtud ciencia;","vcita":"2 Pedro 1:5","pista":"«La cadena empieza en la fe; el primer eslabón es carácter.»"},{"pregunta":"¿Con qué compara Pedro la palabra profética más permanente en 2 Pedro 1:19?","opciones":["Con una antorcha que alumbra en lugar oscuro","Con una espada junto al altar","Con un río que no se seca","Con una semilla guardada en tierra buena"],"dato":"Hacemos bien en estar atentos a la palabra profética como a una antorcha que alumbra en lugar oscuro, hasta que el día esclarezca y el lucero de la mañana salga en nuestros corazones.","cita":"2 Pedro 1:19","versiculo":"Tenemos también la palabra profética más permanente, a la cual hacéis bien de estar atentos como a una antorcha que alumbra en lugar oscuro hasta que el día esclarezca, y el lucero de la mañana salga en vuestros corazones:","vcita":"2 Pedro 1:19","pista":"«En la oscuridad, la profecía funciona como una lámpara.»"},{"pregunta":"¿Cómo hablaron los santos hombres de Dios, según 2 Pedro 1:21?","opciones":["Siendo inspirados del Espíritu Santo","Por su propia voluntad e ingenio","Copiando las tradiciones de los ancianos","Según los sueños que interpretaban"],"dato":"La profecía no fue traída por voluntad humana, sino que los santos hombres de Dios hablaron siendo inspirados del Espíritu Santo.","cita":"2 Pedro 1:21","versiculo":"Porque la profecía no fue en los tiempos pasados traída por voluntad humana, sino los santos hombres de Dios hablaron siendo inspirados del Espíritu Santo.","vcita":"2 Pedro 1:21","pista":"«No fue ocurrencia humana: hubo un Inspirador.»"},{"pregunta":"¿Qué insólito suceso usó Dios para reprender la iniquidad de Balaam, según 2 Pedro 2:16?","opciones":["Una muda bestia de carga habló con voz de hombre","Un ángel cerró el camino con una espada","La tierra se abrió bajo sus pies","Un cuervo le quitó el habla por tres días"],"dato":"Balaam fue reprendido por su iniquidad: una muda bestia de carga, hablando con voz de hombre, refrenó la locura del profeta.","cita":"2 Pedro 2:16","versiculo":"Y fue reprendido por su iniquidad: una muda bestia de carga, hablando en voz de hombre, refrenó la locura del profeta.","vcita":"2 Pedro 2:16","pista":"«El burro de Balaam tiene el sermón más breve y famoso.»"},{"pregunta":"¿Qué doble proverbio cita Pedro en 2 Pedro 2:22 para los que vuelven atrás?","opciones":["El perro se volvió a su vómito, y la puerca lavada a revolcarse en el cieno","La zorra vuelve a su madriguera, y el águila a su nido","El pez vuelve al río, y el pájaro a su rama","La cabra vuelve al monte, y la oveja al redil"],"dato":"Les ha acontecido lo del verdadero proverbio: el perro se volvió a su vómito, y la puerca lavada a revolcarse en el cieno.","cita":"2 Pedro 2:22","versiculo":"Pero les ha acontecido lo del verdadero proverbio: El perro se volvió a su vómito, y la puerca lavada a revolcarse en el cieno.","vcita":"2 Pedro 2:22","pista":"«Dos animales, dos regresos lamentables.»"},{"pregunta":"¿Quiénes vendrán en los postrimeros días, según 2 Pedro 3:3?","opciones":["Burladores, andando según sus propias concupiscencias","Falsos profetas con señales y prodigios","Reyes de oriente con grandes ejércitos","Ángeles caídos en forma de hombres"],"dato":"Sabiendo primero esto: en los postrimeros días vendrán burladores, andando según sus propias concupiscencias, que se burlan de la promesa de su venida.","cita":"2 Pedro 3:3","versiculo":"Sabiendo primero esto, que en los postrimeros días vendrán burladores, andando según sus propias concupiscencias,","vcita":"2 Pedro 3:3","pista":"«Se reirán de la promesa: Pedro ya lo avisó.»"},{"pregunta":"¿Cómo es un día delante del Señor, según 2 Pedro 3:8?","opciones":["Como mil años, y mil años como un día","Como un abrir y cerrar de ojos","Como la hierba que florece y se seca","Como un reloj de arena sin fin"],"dato":"No ignoréis esta una cosa: un día delante del Señor es como mil años, y mil años como un día; el reloj de Dios no es el nuestro.","cita":"2 Pedro 3:8","versiculo":"Mas, oh amados, no ignoréis esta una cosa: que un día delante del Señor es como mil años y mil años como un día.","vcita":"2 Pedro 3:8","pista":"«Para Dios, mil años caben en un día.»"},{"pregunta":"¿Por qué el Señor no tarda su promesa, según 2 Pedro 3:9?","opciones":["Porque es paciente, no queriendo que ninguno perezca, sino que todos procedan al arrepentimiento","Porque aún faltan señales por cumplirse en el cielo","Porque los ángeles no están preparados","Porque su venida depende de los reyes de la tierra"],"dato":"El Señor no tarda su promesa, como algunos la tienen por tardanza; es paciente para con nosotros, no queriendo que ninguno perezca, sino que todos procedan al arrepentimiento.","cita":"2 Pedro 3:9","versiculo":"El Señor no tarda su promesa, como algunos la tienen por tardanza; sino que es paciente para con nosotros, no queriendo que ninguno perezca, sino que todos procedan al arrepentimiento.","vcita":"2 Pedro 3:9","pista":"«Si «tarda», es por paciencia, no por olvido.»"},{"pregunta":"¿Cómo vendrá el día del Señor, según 2 Pedro 3:10?","opciones":["Como ladrón en la noche","Con trompetas anunciadas por los profetas","Después de siete años de señales visibles","Cuando todos los pueblos lo esperen"],"dato":"El día del Señor vendrá como ladrón en la noche; en él los cielos pasarán con grande estruendo y los elementos ardiendo serán deshechos.","cita":"2 Pedro 3:10","versiculo":"Mas el día del Señor vendrá como ladrón en la noche; en el cual los cielos pasarán con grande estruendo, y los elementos ardiendo serán deshechos, y la tierra y las obras que en ella están serán quemadas.","vcita":"2 Pedro 3:10","pista":"«Sin aviso y sin ruido de llaves: como un ladrón.»"},{"pregunta":"¿Qué esperamos según las promesas, en 2 Pedro 3:13?","opciones":["Cielos nuevos y tierra nueva, en los cuales mora la justicia","El regreso del antiguo Edén en esta misma tierra","Un reino de mil años sobre el monte Sion","La restauración del templo de Salomón"],"dato":"Esperamos cielos nuevos y tierra nueva, según sus promesas, en los cuales mora la justicia.","cita":"2 Pedro 3:13","versiculo":"Bien que esperamos cielos nuevos y tierra nueva, según sus promesas, en los cuales mora la justicia.","vcita":"2 Pedro 3:13","pista":"«Todo nuevo, y la justicia viviendo ahí.»"},{"pregunta":"¿En qué manda crecer Pedro al cerrar su carta, en 2 Pedro 3:18?","opciones":["En la gracia y el conocimiento de nuestro Señor y Salvador Jesucristo","En número de iglesias y discípulos","En riquezas para ayudar a los pobres","En el conocimiento de las profecías solamente"],"dato":"La despedida de Pedro es un mandato de crecimiento: creced en la gracia y el conocimiento de nuestro Señor y Salvador Jesucristo.","cita":"2 Pedro 3:18","versiculo":"Mas creced en la gracia y conocimiento de nuestro Señor y Salvador Jesucristo. A él sea gloria ahora y hasta el día de la eternidad. Amén.","vcita":"2 Pedro 3:18","pista":"«La última orden de la carta: creced.»"}],"1 Juan":[{"pregunta":"¿Qué gran verdad sobre Dios anuncia Juan al comenzar su primera carta?","opciones":["Dios es luz, y en él no hay ningunas tinieblas","Dios es un fuego que nadie puede mirar","Dios es un misterio que nadie puede conocer","Dios es viento, y nadie sabe de dónde viene"],"dato":"Juan presenta a Dios como luz pura: en él no existe ni una sombra de tinieblas.","cita":"1 Juan 1:5","versiculo":"Y este es el mensaje que oímos de él, y os anunciamos: Que Dios es luz, y en él no hay ningunas tinieblas.","vcita":"1 Juan 1:5","pista":"«Sin luz no se ve nada; en Dios no cabe ni una sombra.»"},{"pregunta":"Si alguno hubiere pecado, ¿a quién tenemos por abogado para con el Padre?","opciones":["A Jesucristo el justo","Al arcángel Miguel","A Juan el apóstol","A un sacerdote de la ley"],"dato":"Juan escribe para que no pequemos, pero si alguien peca, Jesucristo el justo es nuestro abogado ante el Padre.","cita":"1 Juan 2:1","versiculo":"Hijitos míos, estas cosas os escribo, para que no pequéis; y si alguno hubiere pecado, abogado tenemos para con el Padre, á Jesucristo el justo.","vcita":"1 Juan 2:1","pista":"«Es el mismo que dio su vida por nosotros: nadie nos defiende mejor.»"},{"pregunta":"Jesucristo es la propiciación por nuestros pecados, ¿y por los de quiénes más?","opciones":["Por los de todo el mundo","Solo por los de los apóstoles","Solo por los de Israel","Solo por los de los que ya murieron"],"dato":"La propiciación de Cristo no es exclusiva de un grupo: alcanza a los pecados de todo el mundo.","cita":"1 Juan 2:2","versiculo":"Y él es la propiciación por nuestros pecados: y no solamente por los nuestros, sino también por los de todo el mundo.","vcita":"1 Juan 2:2","pista":"«El alcance es tan grande como el planeta entero.»"},{"pregunta":"¿Qué tres cosas dice Juan que hay en el mundo y no vienen del Padre?","opciones":["La concupiscencia de la carne, la concupiscencia de los ojos y la soberbia de la vida","La guerra, la peste y el hambre","El oro, la plata y las piedras preciosas","La mentira, el robo y el homicidio"],"dato":"Todo lo que el mundo ofrece se resume en deseos de la carne, deseos de los ojos y orgullo de la vida; nada de eso procede del Padre.","cita":"1 Juan 2:16","versiculo":"Porque todo lo que hay en el mundo, la concupiscencia de la carne, y la concupiscencia de los ojos, y la soberbia de la vida, no es del Padre, mas es del mundo.","vcita":"1 Juan 2:16","pista":"«Dos son deseos que entran por el cuerpo y la vista; la tercera es orgullo.»"},{"pregunta":"¿Qué tienen los creyentes, recibido del Santo, por lo cual conocen todas las cosas?","opciones":["La unción","Una carta sellada","Una señal en la frente","El don de lenguas"],"dato":"La unción del Santo mora en los creyentes y les enseña; por ella distinguen la verdad del engaño.","cita":"1 Juan 2:20","versiculo":"Mas vosotros tenéis la unción del Santo, y conocéis todas las cosas.","vcita":"1 Juan 2:20","pista":"«Piensa en el aceite con que se consagraba a reyes y sacerdotes.»"},{"pregunta":"Cuando Cristo aparezca, ¿por qué seremos semejantes a él?","opciones":["Porque le veremos como él es","Porque llevaremos su nombre en la frente","Porque juzgaremos a los ángeles","Porque comeremos del árbol de la vida"],"dato":"Aún no se ha manifestado lo que hemos de ser, pero al ver a Cristo tal como es, seremos transformados a su semejanza.","cita":"1 Juan 3:2","versiculo":"Muy amados, ahora somos hijos de Dios, y aun no se ha manifestado lo que hemos de ser; pero sabemos que cuando él apareciere, seremos semejantes á él, porque le veremos como él es.","vcita":"1 Juan 3:2","pista":"«La clave está en la vista: al verlo, seremos como él.»"},{"pregunta":"Según 1 Juan, ¿por qué mató Caín a su hermano Abel?","opciones":["Porque sus obras eran malas, y las de su hermano justas","Porque Abel se quedó con su herencia","Porque Abel lo acusó ante Adán","Porque disputaban por una mujer"],"dato":"Juan usa a Caín como advertencia: mató a Abel no por una herencia, sino porque sus propias obras eran malas frente a las justas de su hermano.","cita":"1 Juan 3:12","versiculo":"No como Caín, que era del maligno, y mató á su hermano. ¿Y por qué causa le mató? Porque sus obras eran malas, y las de su hermano justas.","vcita":"1 Juan 3:12","pista":"«No fue por un objeto: fue por el contraste entre dos clases de obras.»"},{"pregunta":"¿Cómo sabemos que hemos pasado de muerte a vida?","opciones":["Porque amamos a los hermanos","Porque guardamos el día de reposo","Porque hemos visto una señal","Porque hablamos en lenguas"],"dato":"La señal de la vida nueva no es un rito, sino el amor real a los hermanos; quien no ama permanece en muerte.","cita":"1 Juan 3:14","versiculo":"Nosotros sabemos que hemos pasado de muerte á vida, en que amamos á los hermanos. El que no ama á su hermano, está en muerte.","vcita":"1 Juan 3:14","pista":"«La prueba de la vida nueva se mira en cómo tratas a tu hermano.»"},{"pregunta":"¿Cómo manda Juan que sea nuestro amor, en contraste con amar solo de palabra?","opciones":["De obra y en verdad","Con grandes discursos","Solo en los días de fiesta","En secreto y sin que nadie lo note"],"dato":"El amor verdadero no se queda en palabras bonitas ni en la lengua: se demuestra con hechos y en verdad.","cita":"1 Juan 3:18","versiculo":"Hijitos míos, no amemos de palabra ni de lengua, sino de obra y en verdad.","vcita":"1 Juan 3:18","pista":"«Menos hablar y más hacer: dos palabras lo resumen, obra y verdad.»"},{"pregunta":"¿Cómo se conoce al Espíritu de Dios, según la prueba que da Juan?","opciones":["Todo espíritu que confiesa que Jesucristo ha venido en carne es de Dios","Todo espíritu que hace grandes señales es de Dios","Todo espíritu que habla con voz fuerte es de Dios","Todo espíritu que aparece de noche es de Dios"],"dato":"Juan manda probar los espíritus: la prueba decisiva es confesar que Jesucristo ha venido en carne.","cita":"1 Juan 4:2","versiculo":"En esto conoced el Espíritu de Dios: todo espíritu que confiesa que Jesucristo es venido en carne es de Dios:","vcita":"1 Juan 4:2","pista":"«La prueba no es el espectáculo, sino lo que confiesa acerca de Jesús.»"},{"pregunta":"¿Qué echa fuera el perfecto amor, según Juan?","opciones":["El temor","El sueño","La tristeza de los demás","La memoria del pasado"],"dato":"En el amor no hay temor: el amor perfecto expulsa el miedo, porque el temor lleva castigo consigo.","cita":"1 Juan 4:18","versiculo":"En amor no hay temor; mas el perfecto amor echa fuera el temor: porque el temor tiene pena.","vcita":"1 Juan 4:18","pista":"«Es lo contrario del amor maduro: empieza con «te» y paraliza.»"},{"pregunta":"¿Cuáles son los tres que dan testimonio en la tierra?","opciones":["El Espíritu, el agua y la sangre","El Padre, el Hijo y el Espíritu Santo","La ley, los profetas y los salmos","La fe, la esperanza y el amor"],"dato":"Tres testigos concurren en la tierra acerca del Hijo: el Espíritu, el agua y la sangre, y los tres concuerdan en uno.","cita":"1 Juan 5:8","versiculo":"Y tres son los que dan testimonio en la tierra, el Espíritu, y el agua, y la sangre: y estos tres concuerdan en uno.","vcita":"1 Juan 5:8","pista":"«Uno es Persona divina; los otros dos recuerdan el bautismo y la cruz.»"}],"2 Juan":[{"pregunta":"¿A quién está dirigida la segunda carta de Juan?","opciones":["A la señora elegida y a sus hijos","A la iglesia de Éfeso","A Gaio, el muy amado","A la viuda de Sarepta"],"dato":"El anciano escribe a «la señora elegida y a sus hijos», a quienes ama en verdad junto con todos los que han conocido la verdad.","cita":"2 Juan 1:1","versiculo":"El anciano á la señora elegida y á sus hijos, á los cuales yo amo en verdad; y no yo solo, sino también todos los que han conocido la verdad.","vcita":"2 Juan 1:1","pista":"«No es una iglesia con nombre de ciudad: es una señora y su familia.»"},{"pregunta":"¿Qué tres bendiciones desea Juan que sean con los destinatarios en su saludo?","opciones":["Gracia, misericordia y paz","Fe, esperanza y amor","Salud, dinero y larga vida","Gozo, paciencia y bondad"],"dato":"El saludo de 2 Juan reúne gracia, misericordia y paz de Dios Padre y del Señor Jesucristo, en verdad y en amor.","cita":"2 Juan 1:3","versiculo":"Sea con vosotros gracia, misericordia, y paz de Dios Padre, y del Señor Jesucristo, Hijo del Padre, en verdad y en amor.","vcita":"2 Juan 1:3","pista":"«La del medio es la que Dios nos da cuando más la necesitamos: misericordia.»"},{"pregunta":"¿Qué hallazgo acerca de los hijos de la señora le causó mucho gozo a Juan?","opciones":["Que andaban en la verdad","Que habían prosperado en negocios","Que habían escapado de una persecución","Que habían aprendido las Escrituras de memoria"],"dato":"El anciano se gozó mucho al saber que algunos de los hijos de la señora caminaban en la verdad, como el Padre mandó.","cita":"2 Juan 1:4","versiculo":"Mucho me he gozado, porque he hallado de tus hijos, que andan en verdad, como nosotros hemos recibido el mandamiento del Padre.","vcita":"2 Juan 1:4","pista":"«Andar es la palabra clave: no solo conocer, sino caminar en ella.»"},{"pregunta":"¿Cuál es el mandamiento que Juan ruega que se cumpla, aclarando que no es nuevo sino tenido desde el principio?","opciones":["Que nos amemos unos a otros","Que se guarde el día séptimo","Que se construya un altar","Que se ayune dos veces por semana"],"dato":"Juan no trae un mandamiento nuevo: ruega que se viva el de siempre, amarnos unos a otros.","cita":"2 Juan 1:5","versiculo":"Y ahora te ruego, señora, no como escribiéndote un nuevo mandamiento, sino aquel que nosotros hemos tenido desde el principio, que nos amemos unos á otros.","vcita":"2 Juan 1:5","pista":"«Es tan antiguo como el evangelio mismo: tiene que ver con el prójimo.»"},{"pregunta":"¿Cómo define Juan el amor en su segunda carta?","opciones":["Que andemos según sus mandamientos","Que sintamos paz en el corazón","Que nunca discutamos con nadie","Que demos todo lo que tenemos"],"dato":"Para Juan, el amor no es solo un sentimiento: es caminar según los mandamientos de Dios, como se oyó desde el principio.","cita":"2 Juan 1:6","versiculo":"Y este es amor, que andemos según sus mandamientos. Este es el mandamiento: Que andéis en él, como vosotros habéis oído desde el principio.","vcita":"2 Juan 1:6","pista":"«El amor se mide caminando, y el camino está marcado por los mandamientos.»"},{"pregunta":"Según 2 Juan, ¿quién es «el engañador y el anticristo»?","opciones":["El que no confiesa que Jesucristo ha venido en carne","El que discute con los ancianos","El que llega tarde a las reuniones","El que no saluda al entrar"],"dato":"Muchos engañadores han salido al mundo; el que niega que Jesucristo vino en carne es el engañador y el anticristo.","cita":"2 Juan 1:7","versiculo":"Porque muchos engañadores son entrados en el mundo, los cuales no confiesan que Jesucristo ha venido en carne. Este tal el engañador es, y el anticristo.","vcita":"2 Juan 1:7","pista":"«La negación clave tiene que ver con el cuerpo real de Jesús.»"},{"pregunta":"¿Para qué debían mirar por sí mismos los creyentes, según 2 Juan 1:8?","opciones":["Para no perder lo obrado y recibir galardón cumplido","Para que nadie les quitara sus bienes","Para escapar de la ciudad a tiempo","Para ser reconocidos como apóstoles"],"dato":"Juan advierte que se puede echar a perder lo ya trabajado; la meta es recibir el galardón completo, no una parte.","cita":"2 Juan 1:8","versiculo":"Mirad por vosotros mismos, porque no perdamos las cosas que hemos obrado, sino que recibamos galardón cumplido.","vcita":"2 Juan 1:8","pista":"«Es como cuidar una cosecha ya sembrada para cobrarla entera.»"},{"pregunta":"Según 2 Juan, ¿quién tiene al Padre y al Hijo?","opciones":["El que persevera en la doctrina de Cristo","El que conoce muchos idiomas","El que ha visitado Jerusalén","El que ayuna todos los viernes"],"dato":"Quien se rebela y no persevera en la doctrina de Cristo no tiene a Dios; quien persevera en ella tiene al Padre y al Hijo.","cita":"2 Juan 1:9","versiculo":"Cualquiera que se rebela, y no persevera en la doctrina de Cristo, no tiene á Dios: el que persevera en la doctrina de Cristo, el tal tiene al Padre y al Hijo.","vcita":"2 Juan 1:9","pista":"«La palabra clave es perseverar, no solo empezar.»"},{"pregunta":"Si alguien viene a vosotros y no trae la doctrina de Cristo, ¿qué ordena Juan hacer?","opciones":["No recibirlo en casa, ni decirle: ¡bienvenido!","Escucharlo tres días antes de decidir","Darle comida y dejar que enseñe","Llevarlo ante los ancianos para debatir"],"dato":"La hospitalidad no debía abrir la puerta a la falsa doctrina: ni recibir en casa ni dar la bienvenida al que no trae la doctrina de Cristo.","cita":"2 Juan 1:10","versiculo":"Si alguno viene á vosotros, y no trae esta doctrina, no lo recibáis en casa, ni le digáis: ¡bienvenido!","vcita":"2 Juan 1:10","pista":"«Ni la casa ni el saludo: la puerta y la boca se cierran a la falsa doctrina.»"},{"pregunta":"¿Por qué no se debe decir «bienvenido» al que trae otra doctrina?","opciones":["Porque el que le dice bienvenido participa en sus malas obras","Porque es de mala educación saludar a extraños","Porque Juan quería probarlos primero","Porque los saludos se reservaban para el sábado"],"dato":"Saludar con aprobación a un falso maestro convierte al que saluda en partícipe de sus malas obras.","cita":"2 Juan 1:11","versiculo":"Porque el que le dice bienvenido, comunica con sus malas obras.","vcita":"2 Juan 1:11","pista":"«Un saludo parece poco, pero Juan lo cuenta como complicidad.»"},{"pregunta":"¿Por qué Juan prefirió no comunicar todo por medio de papel y tinta?","opciones":["Esperaba ir y hablar boca a boca, para que el gozo fuera cumplido","Porque se le había acabado la tinta","Porque el camino era peligroso para mensajeros","Porque temía que la carta se perdiera"],"dato":"El anciano tenía mucho más que decir, pero prefería la visita en persona: hablar boca a boca haría el gozo completo.","cita":"2 Juan 1:12","versiculo":"Aunque tengo muchas cosas que escribiros, no he querido [comunicarlas] por medio de papel y tinta; mas espero ir á vosotros, y hablar boca á boca, para que nuestro gozo sea cumplido.","vcita":"2 Juan 1:12","pista":"«Hay conversaciones que no caben en una carta: requieren presencia.»"},{"pregunta":"¿Quiénes envían saludos al final de la segunda carta de Juan?","opciones":["Los hijos de su hermana elegida","Los apóstoles desde Jerusalén","Los hermanos de la iglesia de Roma","Los hijos de Zebedeo"],"dato":"La carta cierra con los saludos de los hijos de la «hermana elegida» de la destinataria: dos familias en la misma verdad.","cita":"2 Juan 1:13","versiculo":"Los hijos de tu hermana elegida te saludan. Amén.","vcita":"2 Juan 1:13","pista":"«Son parientes de la destinataria: los hijos de su hermana.»"}],"3 Juan":[{"pregunta":"¿A quién está dirigida la tercera carta de Juan?","opciones":["A Gaio, el muy amado","A la señora elegida","A Diótrefes, el principal","A Filemón, el colaborador"],"dato":"El anciano escribe a Gaio, su muy amado en la verdad, ejemplo de hospitalidad y fidelidad.","cita":"3 Juan 1:1","versiculo":"El anciano al muy amado Gaio, al cual yo amo en verdad.","vcita":"3 Juan 1:1","pista":"«Su nombre empieza con G y es famoso por recibir bien a los hermanos.»"},{"pregunta":"¿Qué deseo expresa Juan para Gaio al principio de la carta?","opciones":["Que sea prosperado en todas las cosas y tenga salud, así como prospera su alma","Que llegue a ser anciano de la iglesia","Que viaje pronto a Jerusalén","Que escriba también una carta a las iglesias"],"dato":"Juan desea para Gaio una prosperidad integral: en todo, y con salud del cuerpo, al nivel de la prosperidad de su alma.","cita":"3 Juan 1:2","versiculo":"Amado, yo deseo que tú seas prosperado en todas cosas, y que tengas salud, así como tu alma está en prosperidad.","vcita":"3 Juan 1:2","pista":"«Es un deseo doble: por fuera salud, por dentro un alma que ya prospera.»"},{"pregunta":"¿Cuál es el mayor gozo de Juan, según su tercera carta?","opciones":["Oír que sus hijos andan en la verdad","Ver crecer el número de iglesias","Recibir cartas de los apóstoles","Saber que los falsos maestros se fueron"],"dato":"Nada alegra más al anciano que saber que sus hijos en la fe caminan en la verdad.","cita":"3 Juan 1:4","versiculo":"No tengo yo mayor gozo que éste, el oir que mis hijos andan en la verdad.","vcita":"3 Juan 1:4","pista":"«No es un gozo por cosas, sino por personas caminando bien.»"},{"pregunta":"¿Por qué obra fiel se destaca Gaio, según los hermanos que lo visitaron?","opciones":["Por todo lo que hacía a favor de los hermanos y de los extranjeros","Por los himnos que componía para la iglesia","Por haber construido la casa de reunión","Por memorizar los Salmos completos"],"dato":"Los hermanos dieron testimonio de que Gaio servía fielmente tanto a los conocidos como a los extranjeros que llegaban.","cita":"3 Juan 1:5","versiculo":"Amado, fielmente haces todo lo que haces para con los hermanos, y con los extranjeros.","vcita":"3 Juan 1:5","pista":"«Su fidelidad se veía con dos grupos: los de casa y los de fuera.»"},{"pregunta":"¿Cómo habían salido a servir los obreros que Gaio ayudaba?","opciones":["Partieron por amor del Nombre, sin tomar nada de los gentiles","Con una carta de recomendación del concilio","Escoltados por soldados romanos","Con fondos reunidos por tres iglesias"],"dato":"Aquellos hermanos salieron por causa del Nombre de Cristo sin aceptar ayuda de los gentiles; por eso la iglesia debía sostenerlos.","cita":"3 Juan 1:7","versiculo":"Porque ellos partieron por amor de su nombre, no tomando nada de los Gentiles.","vcita":"3 Juan 1:7","pista":"«Salieron con las manos vacías de los de fuera, confiando en el Nombre.»"},{"pregunta":"¿Para qué debemos recibir y apoyar a los obreros como los que ayudaba Gaio?","opciones":["Para ser cooperadores de la verdad","Para que la iglesia sea más numerosa","Para competir con otras iglesias","Para cumplir una tradición anual"],"dato":"Apoyar a los que salen a servir hace al creyente socio y cooperador de la verdad misma.","cita":"3 Juan 1:8","versiculo":"Nosotros, pues, debemos recibir á los tales, para que seamos cooperadores á la verdad.","vcita":"3 Juan 1:8","pista":"«Al abrir tu puerta, te vuelves socio de la misión.»"},{"pregunta":"¿Quién no recibía a Juan ni a sus enviados porque amaba tener el primado?","opciones":["Diótrefes","Demetrio","Gaio","Alejandro el calderero"],"dato":"Diótrefes, que amaba ser el primero entre los hermanos, rechazaba al apóstol y a sus enviados: el orgullo cerrado, en contraste con la hospitalidad de Gaio.","cita":"3 Juan 1:9","versiculo":"Yo he escrito á la iglesia: mas Diótrefes, que ama tener el primado entre ellos, no nos recibe.","vcita":"3 Juan 1:9","pista":"«Su problema cabía en una frase: quería ser el primero.»"},{"pregunta":"Además de no recibir a los hermanos, ¿qué más hacía Diótrefes contra ellos?","opciones":["Prohibía a los que querían recibirlos y los echaba de la iglesia","Les cobraba por entrar a las reuniones","Los denunciaba ante las autoridades romanas","Quemaba las cartas de los apóstoles"],"dato":"Diótrefes no solo cerraba su puerta: parlaba con palabras maliciosas contra Juan, impedía la hospitalidad de otros y expulsaba de la iglesia a los que la practicaban.","cita":"3 Juan 1:10","versiculo":"Por esta causa, si yo viniere, recordaré las obras que hace parlando con palabras maliciosas contra nosotros; y no contento con estas cosas, no recibe á los hermanos, y prohibe á los que los quieren [recibir], y los echa de la iglesia.","vcita":"3 Juan 1:10","pista":"«No contento con cerrar su puerta, cerraba también la de los demás.»"},{"pregunta":"¿Qué consejo da Juan a Gaio frente al mal ejemplo de Diótrefes?","opciones":["No sigas lo que es malo, sino lo que es bueno","Aléjate de la ciudad por un tiempo","Escribe una carta de protesta a la iglesia","No vuelvas a recibir a ningún extranjero"],"dato":"El consejo es de imitación: seguir lo bueno, no lo malo; porque el que hace bien es de Dios, y el que hace mal no ha visto a Dios.","cita":"3 Juan 1:11","versiculo":"Amado, no sigas lo que es malo, sino lo que es bueno. El que hace bien es de Dios: mas el que hace mal, no ha visto á Dios.","vcita":"3 Juan 1:11","pista":"«Es un asunto de a quién imitas: lo bueno o lo malo.»"},{"pregunta":"¿De quién dan testimonio todos, y aun la misma verdad, según 3 Juan?","opciones":["De Demetrio","De Diótrefes","De Gaio","Del anciano Juan"],"dato":"Demetrio tiene buen testimonio de todos y de la verdad misma; Juan también testifica de él y asegura que su testimonio es verdadero.","cita":"3 Juan 1:12","versiculo":"Todos dan testimonio de Demetrio, y [aun] la misma verdad: y también nosotros damos testimonio; y vosotros habéis conocido que nuestro testimonio es verdadero.","vcita":"3 Juan 1:12","pista":"«Es el contraste de Diótrefes: todos hablan bien de él.»"},{"pregunta":"¿Qué esperaba Juan en breve, en lugar de seguir escribiendo con tinta y pluma?","opciones":["Ver a Gaio y hablar boca a boca","Enviar a Demetrio como mensajero","Recibir la respuesta de la iglesia","Visitar las siete iglesias de Asia"],"dato":"Juan tenía mucho más que escribir, pero confiaba en ver pronto a Gaio y conversar cara a cara.","cita":"3 Juan 1:14","versiculo":"Porque espero verte en breve, y hablaremos boca á boca. Paz [sea] contigo. Los amigos te saludan. Saluda tú á los amigos por nombre.","vcita":"3 Juan 1:14","pista":"«Como en 2 Juan: hay cosas que se dicen mejor en persona.»"},{"pregunta":"¿Ante quiénes dieron testimonio del amor de Gaio los hermanos que él había ayudado?","opciones":["En presencia de la iglesia","Ante el gobernador romano","En el templo de Jerusalén","Delante de los ancianos de otra ciudad"],"dato":"Los viajeros ayudados por Gaio contaron su amor delante de toda la iglesia; por eso Juan anima a seguir apoyándolos como conviene según Dios.","cita":"3 Juan 1:6","versiculo":"Los cuales han dado testimonio de tu amor en presencia de la iglesia: á los cuales si ayudares como conviene según Dios, harás bien.","vcita":"3 Juan 1:6","pista":"«Su amor no quedó en privado: se contó frente a toda la congregación.»"}],"Judas":[{"pregunta":"¿Cómo se presenta Judas, el autor de la carta, en el saludo?","opciones":["Siervo de Jesucristo y hermano de Jacobo","Apóstol y testigo de la resurrección","Anciano de la iglesia de Jerusalén","Discípulo amado del Señor"],"dato":"Judas no se presenta como medio hermano del Señor, sino con humildad: siervo de Jesucristo y hermano de Jacobo.","cita":"Judas 1:1","versiculo":"JUDAS, siervo de Jesucristo, y hermano de Jacobo, á los llamados, santificados en Dios Padre, y conservados en Jesucristo:","vcita":"Judas 1:1","pista":"«Su credencial es doble: siervo de Cristo y hermano de Jacobo.»"},{"pregunta":"¿Qué tema quería escribir Judas con gran solicitud, antes de cambiar el enfoque de su carta?","opciones":["De la común salud (la salvación compartida)","De los dones del Espíritu Santo","De la cronología del fin del mundo","De los levitas y el sacerdocio"],"dato":"Judas deseaba escribir sobre la salvación que comparten los creyentes, pero la urgencia lo obligó a escribir exhortando a defender la fe.","cita":"Judas 1:3","versiculo":"Amados, por la gran solicitud que tenía de escribiros de la común salud, me ha sido necesario escribiros amonestándoos que contendáis eficazmente por la fe que ha sido una vez dada á los santos.","vcita":"Judas 1:3","pista":"«Era el tema bonito y compartido por todos: la salvación común.»"},{"pregunta":"¿Qué hacían los hombres impíos que habían entrado encubiertamente, según Judas?","opciones":["Convertían la gracia de Dios en disolución y negaban al Señor","Vendían indulgencias a los hermanos","Enseñaban que no había resurrección","Prohibían casarse y comer ciertos alimentos"],"dato":"Los infiltrados torcían la gracia convirtiéndola en libertinaje y negaban al único Soberano y Señor, Jesucristo.","cita":"Judas 1:4","versiculo":"Porque algunos hombres han entrado encubiertamente, los cuales desde antes habían estado ordenados para esta condenación, hombres impíos, convirtiendo la gracia de nuestro Dios en disolución, y negando á Dios que solo es el que tiene dominio, y á nuestro Señor Jesucristo.","vcita":"Judas 1:4","pista":"«Torcer la gracia en permiso para pecar: esa era su maniobra secreta.»"},{"pregunta":"¿Qué primer ejemplo del pasado recuerda Judas para advertir a los creyentes?","opciones":["El Señor salvó al pueblo de Egipto y después destruyó a los que no creyeron","Nínive se arrepintió con la predicación de Jonás","Israel cruzó el Jordán entrando a Canaán","David perdonó la vida a Saúl en la cueva"],"dato":"Ser rescatado una vez no basta: el pueblo salvado de Egipto fue después destruido en su incredulidad.","cita":"Judas 1:5","versiculo":"Os quiero pues amonestar, [ya] que alguna vez habéis sabido esto, que el Señor habiendo salvado al pueblo de Egipto, después destruyó á los que no creían:","vcita":"Judas 1:5","pista":"«Salvados de un imperio famoso por sus pirámides, pero no por eso a salvo.»"},{"pregunta":"¿Qué ha reservado Dios para los ángeles que no guardaron su dignidad y dejaron su habitación?","opciones":["Oscuridad y prisiones eternas hasta el juicio del gran día","Ser enviados a un desierto sin fin","Servir como mensajeros sin descanso","Ser convertidos en estrellas erráticas"],"dato":"Los ángeles caídos están guardados bajo oscuridad, en prisiones eternas, esperando el juicio del gran día.","cita":"Judas 1:6","versiculo":"Y á los ángeles que no guardaron su dignidad, mas dejaron su habitación, los ha reservado debajo de oscuridad en prisiones eternas hasta el juicio del gran día:","vcita":"Judas 1:6","pista":"«Su castigo combina dos cosas: oscuridad y cadenas que no se rompen.»"},{"pregunta":"Según Judas, Sodoma y Gomorra fueron puestas por ejemplo, ¿sufriendo qué juicio?","opciones":["El juicio del fuego eterno","Ser cubiertas por las aguas del mar","Ser convertidas en sal y ceniza solamente","Ser olvidadas por todas las naciones"],"dato":"Las ciudades de la llanura quedaron como advertencia visible, sufriendo el castigo del fuego eterno.","cita":"Judas 1:7","versiculo":"Como Sodoma y Gomorra, y las ciudades comarcanas, las cuales de la misma manera que ellos habían fornicado, y habían seguido la carne extraña, fueron puestas por ejemplo, sufriendo el juicio del fuego eterno.","vcita":"Judas 1:7","pista":"«El elemento del juicio es el fuego, y su alcance es eterno.»"},{"pregunta":"Cuando el arcángel Miguel disputaba con el diablo sobre el cuerpo de Moisés, ¿qué dijo en lugar de maldecirlo?","opciones":["«El Señor te reprenda»","«Apártate de mí, Satanás»","«Por la espada de Dios caerás»","«Sea tu nombre borrado del libro»"],"dato":"Ni el arcángel Miguel se atrevió a proferir juicio de maldición contra el diablo; dejó la reprensión en manos del Señor.","cita":"Judas 1:9","versiculo":"Pero cuando el arcángel Miguel contendía con el diablo, disputando sobre el cuerpo de Moisés, no se atrevió á usar de juicio de maldición contra él, sino que dijo: El Señor te reprenda.","vcita":"Judas 1:9","pista":"«La frase tiene solo cuatro palabras y pone al Señor por delante.»"},{"pregunta":"En el «¡Ay de ellos!», ¿qué tres malos caminos dice Judas que siguieron los falsos maestros?","opciones":["El camino de Caín, el error de Balaam por recompensa y la contradicción de Coré","El camino de Esaú, el error de Saúl y la rebelión de Absalón","El camino de la serpiente, el error de Eva y la torre de Babel","El camino de Judas Iscariote, el error de Simón el mago y la queja de Diótrefes"],"dato":"Tres figuras del Antiguo Testamento resumen su conducta: Caín por odio, Balaam por ganancia y Coré por rebelión.","cita":"Judas 1:11","versiculo":"¡Ay de ellos! porque han seguido el camino de Caín, y se lanzaron en el error de Balaam por recompensa, y perecieron en la contradicción de Coré.","vcita":"Judas 1:11","pista":"«Un fratricida, un profeta vendido y un rebelde contra Moisés.»"},{"pregunta":"¿Con qué imágenes de la naturaleza compara Judas a los falsos maestros?","opciones":["Nubes sin agua llevadas por los vientos y árboles otoñales sin fruto","Lobos vestidos de ovejas y sepulcros blanqueados","Serpientes en el camino y leones al acecho","Ríos secos y montes que se derrumban"],"dato":"Prometen lluvia y no dan nada: nubes sin agua, árboles dos veces muertos y desarraigados, ondas bravas y estrellas erráticas.","cita":"Judas 1:12","versiculo":"Estos son manchas en vuestros convites, que banquetean juntamente, apacentándose á sí mismos sin temor alguno: nubes sin agua, las cuales son llevadas de acá para allá de los vientos: árboles marchitos como en otoño, sin fruto, dos veces muertos y desarraigados;","vcita":"Judas 1:12","pista":"«Una promete lluvia y no moja; el otro promete cosecha y no da fruto.»"},{"pregunta":"¿Quién, siendo el séptimo desde Adán, profetizó que el Señor viene con sus santos millares?","opciones":["Enoc","Matusalén","Noé","Elías"],"dato":"Judas cita la profecía de Enoc, el séptimo desde Adán, sobre la venida del Señor con decenas de millares de sus santos para hacer juicio.","cita":"Judas 1:14","versiculo":"De los cuales también profetizó Enoc, séptimo desde Adam, diciendo: He aquí, el Señor es venido con sus santos millares.","vcita":"Judas 1:14","pista":"«Es el hombre que caminó con Dios y no vio muerte en Génesis.»"},{"pregunta":"¿Cómo debían edificarse los amados, según la exhortación de Judas?","opciones":["Sobre su santísima fe, orando en el Espíritu Santo","Ayunando dos veces por semana","Separándose de todos los demás creyentes","Memorizando las genealogías"],"dato":"Frente a los burladores, la respuesta es constructiva: edificarse sobre la fe santísima y orar en el Espíritu Santo, conservándose en el amor de Dios.","cita":"Judas 1:20","versiculo":"Mas vosotros, oh amados, edificándoos sobre vuestra santísima fe, orando por el Espíritu Santo.","vcita":"Judas 1:20","pista":"«La imagen es de construcción: el cimiento es la fe y la herramienta es la oración.»"},{"pregunta":"Según la doxología final de Judas, ¿qué es poderoso para hacer Dios con los suyos?","opciones":["Guardarlos sin caída y presentarlos irreprensibles delante de su gloria, con grande alegría","Darles riquezas en esta vida","Hacerlos jueces sobre las naciones desde ahora","Librarlos de toda prueba en este mundo"],"dato":"La carta que denuncia tantos peligros termina en alabanza: Dios puede guardar sin tropiezo y presentar a los suyos sin mancha, con gran alegría.","cita":"Judas 1:24","versiculo":"A aquel, pues, que es poderoso para guardaros sin caída, y presentaros delante de su gloria irreprensibles, con grande alegría.","vcita":"Judas 1:24","pista":"«La carta termina mirando a Dios: Él guarda el paso y presenta sin mancha.»"}],"Apocalipsis":[{"pregunta":"¿Cuántos fueron los señalados (sellados) de todas las tribus de los hijos de Israel?","opciones":["Ciento cuarenta y cuatro mil","Doce mil","Setecientos cuarenta y cuatro mil","Veinticuatro mil"],"dato":"Juan oyó el número de los sellados: 144.000, doce mil de cada tribu de Israel, marcados antes de que se desate el juicio sobre la tierra.","cita":"Apocalipsis 7:4","versiculo":"Y oí el número de los señalados: ciento cuarenta y cuatro mil señalados de todas las tribus de los hijos de Israel.","vcita":"Apocalipsis 7:4","pista":"«Es doce por doce mil: haz la cuenta de las tribus.»"},{"pregunta":"¿Cómo responde el apóstol (y la iglesia) cuando el Señor dice: «Ciertamente, vengo en breve»?","opciones":["«Amén, sea así. Ven, Señor Jesús»","«Todavía no, Señor, espera un poco»","«Que se haga tu voluntad en el cielo»","«Envía primero a tus ángeles»"],"dato":"La Biblia termina con un diálogo de anhelo: Cristo promete venir pronto y su pueblo responde con la última oración de las Escrituras.","cita":"Apocalipsis 22:20","versiculo":"El que da testimonio de estas cosas, dice: Ciertamente, vengo en breve. Amén, sea así. Ven, Señor Jesús.","vcita":"Apocalipsis 22:20","pista":"«Son las últimas palabras de respuesta de toda la Biblia: un «ven» dirigido al Señor.»"}]};
var BANCO_NUEVO_EN = {"Exodus":[{"pregunta":"What were the names of the two Hebrew midwives who refused to obey Pharaoh's order to kill the baby boys?","opciones":["Shiphrah and Puah","Miriam and Zipporah","Deborah and Jael","Hannah and Peninnah"],"dato":"Pharaoh ordered the midwives to kill the Hebrew boys at birth, but they feared God and let the children live.","cita":"Exodus 1:15","versiculo":"The king of Egypt spoke to the Hebrew midwives, of whom the name of the one was Shiphrah, and the name of the other Puah.","vcita":"Exodus 1:15","pista":"\"Two brave women who served the Hebrew mothers.\""},{"pregunta":"What did the Israelites gather on the sixth day concerning the manna?","opciones":["A double portion, because the next day was a day of rest","Nothing, because they fasted that day","Only half, to share it with the Egyptians","Three times as much, to store for the whole month"],"dato":"On the sixth day they gathered two omers per person, because on the seventh day, the Sabbath, no manna fell on the ground.","cita":"Exodus 16:22","versiculo":"On the sixth day, they gathered twice as much bread, two omers for each one. All the rulers of the congregation came and told Moses.","vcita":"Exodus 16:22","pista":"\"Think of the Sabbath: that day there was no manna in the field.\""},{"pregunta":"Whose advice did Moses follow to appoint helpers who would judge the people and lighten his load?","opciones":["Jethro's, his father-in-law","Aaron's, his brother","Joshua's, his servant","Korah's and the elders'"],"dato":"Jethro, Moses' father-in-law and priest of Midian, saw Moses wearing himself out judging alone from morning to evening and advised him to set chiefs over the people.","cita":"Exodus 18:24","versiculo":"So Moses listened to his father-in-law's voice, and did all that he had said.","vcita":"Exodus 18:24","pista":"\"He was Moses' father-in-law, a priest of Midian.\""}],"Leviticus":[{"pregunta":"Which great commandment, quoted centuries later by Jesus, already appears in Leviticus?","opciones":["You shall love your neighbor as yourself","Honor your father and your mother","You shall not covet your neighbor's house","Remember the Sabbath day"],"dato":"Leviticus 19:18 commands not to bear a grudge but to love one's neighbor as oneself; Jesus set it beside the love of God as a summary of the Law.","cita":"Leviticus 19:18","versiculo":"You shall not take vengeance, nor bear any grudge against the children of your people; but you shall love your neighbor as yourself. I am Yahweh.","vcita":"Leviticus 19:18","pista":"\"It is the commandment that looks toward your neighbor, not yourself.\""},{"pregunta":"Why were the Israelites to be holy, according to Leviticus 19?","opciones":["Because God, their Lord, is holy","To look different in their clothing","Because the priest preferred it that way","So they could trade with the nations"],"dato":"The reason for the people's holiness is not their merit but God's character: 'for I, Yahweh your God, am holy.'","cita":"Leviticus 19:2","versiculo":"Speak to all the congregation of the children of Israel, and tell them, 'You shall be holy; for I, Yahweh your God, am holy.'","vcita":"Leviticus 19:2","pista":"\"The answer lies in who God is, not in who they were.\""},{"pregunta":"On the Day of Atonement, which animal was sent alive into the wilderness, symbolically carrying the people's sins?","opciones":["The goat for Azazel","A lamb without defect","A young bull","Two turtledoves"],"dato":"Of two goats, one was offered for sin and the other, over which the people's iniquities were confessed, was released alive in the wilderness.","cita":"Leviticus 16:22","versiculo":"The goat shall carry all their iniquities on himself to a solitary land, and he shall release the goat in the wilderness.","vcita":"Leviticus 16:22","pista":"\"It walked away into the desert with all the sins on it.\""},{"pregunta":"Every how many years was the year of jubilee celebrated, when liberty was proclaimed throughout the land?","opciones":["Every 50 years","Every 7 years","Every 40 years","Every 100 years"],"dato":"After seven cycles of seven years came the fiftieth year: liberty was proclaimed, and everyone returned to his property and his family.","cita":"Leviticus 25:10","versiculo":"You shall make the fiftieth year holy, and proclaim liberty throughout the land to all its inhabitants. It shall be a jubilee to you.","vcita":"Leviticus 25:10","pista":"\"Seven times seven years... plus one more.\""},{"pregunta":"What was to happen to the farmland in the seventh year?","opciones":["It rested: no sowing and no pruning","It was sold to the poorest families","It was burned completely","It was plowed twice as much as usual"],"dato":"The sabbatical year was a Sabbath of rest for the land itself: a year without sowing or pruning, trusting in God's provision.","cita":"Leviticus 25:4","versiculo":"but in the seventh year there shall be a Sabbath of solemn rest for the land, a Sabbath to Yahweh. You shall not sow your field or prune your vineyard.","vcita":"Leviticus 25:4","pista":"\"Even the land had its day of rest... but a whole year long.\""},{"pregunta":"Which feast was celebrated on the fourteenth day of the first month?","opciones":["Yahweh's Passover","The Feast of Booths","The Day of Atonement","The Feast of Weeks"],"dato":"The feast calendar of Leviticus 23 opens with the weekly Sabbath and then Passover, on the fourteenth of the first month, 'in the evening.'","cita":"Leviticus 23:5","versiculo":"In the first month, on the fourteenth day of the month in the evening, is Yahweh's Passover.","vcita":"Leviticus 23:5","pista":"\"It is the feast that remembers the exodus from Egypt.\""},{"pregunta":"Where were the Israelites to live during the seven days of the Feast of Booths?","opciones":["In booths","In the court of the tabernacle","In tents made of skins","In the priests' houses"],"dato":"Living a week in booths reminded every generation that Israel lived in booths when God brought them out of Egypt.","cita":"Leviticus 23:42","versiculo":"You shall dwell in booths seven days. All who are native-born in Israel shall dwell in booths.","vcita":"Leviticus 23:42","pista":"\"The name of the feast already tells you.\""},{"pregunta":"According to Leviticus, where is the life of the flesh?","opciones":["In the blood","In the heart","In the liver","In the breath of the bones"],"dato":"That is why blood was not to be eaten and was what made atonement on the altar: 'it is the blood that makes atonement.'","cita":"Leviticus 17:11","versiculo":"For the life of the flesh is in the blood. I have given it to you on the altar to make atonement for your souls; for it is the blood that makes atonement by reason of the life.","vcita":"Leviticus 17:11","pista":"\"That is why eating it was forbidden.\""},{"pregunta":"Why was the pig counted among the unclean animals?","opciones":["It has a split hoof but does not chew the cud","Because it wallows in the mud","Because it is a night animal","Because it has no scales"],"dato":"The rule for clean land animals in Leviticus 11 combined two signs: the animal had to chew the cud and have a split hoof; the pig lacks one of the two.","cita":"Leviticus 11:7","versiculo":"The pig, because it has a split hoof, and is cloven-footed, but doesn't chew the cud, is unclean to you.","vcita":"Leviticus 11:7","pista":"\"It had one of the two signs the law required.\""},{"pregunta":"If someone could not afford to offer a lamb, what could they offer instead?","opciones":["Two turtledoves or two young pigeons","Just a handful of flour, no animals","Nothing: they were left out of worship","A two-year-old goat"],"dato":"The law scaled the offerings to each person's means: even the poorest had an offering within reach.","cita":"Leviticus 12:8","versiculo":"If she cannot afford a lamb, then she shall take two turtledoves or two young pigeons: the one for a burnt offering, and the other for a sin offering.","vcita":"Leviticus 12:8","pista":"\"Mary offered exactly this when she presented Jesus at the temple.\""},{"pregunta":"How many days were counted until the Feast of Weeks, the harvest feast?","opciones":["Fifty days","Forty days","Seven days","One hundred days"],"dato":"Seven full Sabbaths were counted from the firstfruits, and on the next day, the fiftieth, the new meal offering was presented; hence the Greek name 'Pentecost.'","cita":"Leviticus 23:16","versiculo":"You shall count fifty days to the day after the seventh Sabbath. Then you shall present a new meal offering to Yahweh.","vcita":"Leviticus 23:16","pista":"\"That count is where the name 'Pentecost' comes from.\""},{"pregunta":"To whom did the tithe of the land and of the fruit of the trees belong?","opciones":["To Yahweh: it was holy to him","To the king of Israel","To the temple merchants","To each family, to keep at home"],"dato":"The tithe is not described as a fee for an institution, but as God's own property: 'is Yahweh's. It is holy to Yahweh.'","cita":"Leviticus 27:30","versiculo":"All the tithe of the land, whether of the seed of the land or of the fruit of the trees, is Yahweh's. It is holy to Yahweh.","vcita":"Leviticus 27:30","pista":"\"The tenth part already had an owner before it was harvested.\""}],"Numbers":[{"pregunta":"How does the blessing with which Aaron and his sons were to bless the people begin?","opciones":["\"Yahweh bless you, and keep you\"","\"Peace be with you\"","\"Hear, Israel: Yahweh is one\"","\"Blessed is he who comes in Yahweh's name\""],"dato":"God himself gave Moses the exact words of the priestly blessing with which Aaron would put Yahweh's name on the people.","cita":"Numbers 6:24","versiculo":"Yahweh bless you, and keep you. Yahweh make his face to shine on you, and be gracious to you.","vcita":"Numbers 6:24-25","pista":"\"It is the most famous blessing in the book of Numbers.\""},{"pregunta":"How did the spies say they looked in their own eyes next to the giants of Canaan?","opciones":["As grasshoppers","As ants in the dust","As little children","As sheep without a shepherd"],"dato":"The report of the ten spies exaggerated the danger this way and discouraged the whole people, while Joshua and Caleb trusted in God.","cita":"Numbers 13:33","versiculo":"There we saw the Nephilim, the sons of Anak, who come of the Nephilim. We were in our own sight as grasshoppers, and so we were in their sight.","vcita":"Numbers 13:33","pista":"\"They compared themselves to an insect.\""},{"pregunta":"What happened to Aaron's rod inside the tabernacle to confirm his priesthood?","opciones":["It sprouted, budded, blossomed and produced almonds","It split into two pieces","It turned into a snake","It was covered with gold overnight"],"dato":"Of the twelve rods of the tribes, only Aaron's came back to life in one night; it was kept in the tabernacle as a sign against the rebels.","cita":"Numbers 17:8","versiculo":"On the next day, Moses went into the Tent of the Testimony; and behold, Aaron's rod for the house of Levi had sprouted, budded, put out blossoms, and produced ripe almonds.","vcita":"Numbers 17:8","pista":"\"A dry stick bears no fruit... except this one.\""},{"pregunta":"What did Moses do with the bronze serpent so that bitten Israelites would be healed?","opciones":["He set it on a pole for them to look at","He burned it on the altar of burnt offering","He buried it next to the camp","He kept it inside the ark of the covenant"],"dato":"Whoever was bitten and looked at the bronze serpent lived; Jesus compared that scene with his own crucifixion in John 3.","cita":"Numbers 21:8","versiculo":"Yahweh said to Moses, \"Make a fiery serpent, and set it on a pole. It shall happen that everyone who is bitten, when he sees it, shall live.\"","vcita":"Numbers 21:8","pista":"\"You had to look up to be healed.\""},{"pregunta":"Which animal spoke to Balaam, reproaching him for striking it three times?","opciones":["His donkey","A horse from the escort","A desert camel","A sheep from his flock"],"dato":"The donkey saw Yahweh's angel with a sword in the road, while Balaam, blinded by greed, saw only a 'stubborn' animal.","cita":"Numbers 22:28","versiculo":"Yahweh opened the mouth of the donkey, and she said to Balaam, \"What have I done to you, that you have struck me these three times?\"","vcita":"Numbers 22:28","pista":"\"It is the humblest beast of burden in the story.\""},{"pregunta":"How many men did Moses send to spy out the land of Canaan?","opciones":["Twelve, one from each tribe","Seventy elders","Only two","Forty scouts"],"dato":"They were twelve chiefs, one per tribe; among them were Caleb of Judah and Hoshea son of Nun, whom Moses called Joshua.","cita":"Numbers 13:2","versiculo":"Send men, that they may spy out the land of Canaan, which I give to the children of Israel. You shall send a man from every tribe of their fathers, each one a prince among them.","vcita":"Numbers 13:2","pista":"\"One for each tribe of Israel.\""},{"pregunta":"For how many years did Israel wander in the wilderness as a consequence of their unbelief at the spies' report?","opciones":["Forty years","Seven years","Twenty years","One single year"],"dato":"For each day of the spying of the land, a year of wilderness: that generation would die without entering Canaan.","cita":"Numbers 14:33","versiculo":"Your children shall be wanderers in the wilderness for forty years, and shall bear your prostitution, until your dead bodies are consumed in the wilderness.","vcita":"Numbers 14:33","pista":"\"A year of wilderness for each day of spying.\""},{"pregunta":"What happened to Korah and those who rebelled with him against Moses and Aaron?","opciones":["The earth opened and swallowed them alive","They were stoned outside the camp","They fled toward Egypt by night","Lightning burned only their tents"],"dato":"Korah, a Levite, accused Moses of exalting himself; the ground split under their tents and they went down alive into Sheol.","cita":"Numbers 16:32","versiculo":"The earth opened its mouth, and swallowed them up, with their households, all of Korah's men, and all their goods.","vcita":"Numbers 16:32","pista":"\"The ground itself was the judge of the rebellion.\""},{"pregunta":"What were Miriam and Aaron speaking against Moses about in Numbers 12?","opciones":["The Cushite woman he had married","That he did not share the manna with them","That Joshua would be his successor","That the people asked for meat in the wilderness"],"dato":"Miriam and Aaron questioned whether God spoke only through Moses; Miriam became leprous, 'white as snow,' for a week.","cita":"Numbers 12:1","versiculo":"Miriam and Aaron spoke against Moses because of the Cushite woman whom he had married; for he had married a Cushite woman.","vcita":"Numbers 12:1","pista":"\"The complaint started with Moses' wife.\""},{"pregunta":"What did the daughters of Zelophehad ask for, so that God said they spoke rightly?","opciones":["To receive their father's inheritance, since he had no sons","To serve as priestesses in the tabernacle","To cross the Jordan at the front of the people","To keep the Sabbath manna"],"dato":"Their case changed the inheritance law in Israel: when there were no sons, the father's inheritance passed to the daughters.","cita":"Numbers 27:7","versiculo":"The daughters of Zelophehad speak right. You shall surely give them a possession of an inheritance among their father's brothers. You shall cause the inheritance of their father to pass to them.","vcita":"Numbers 27:7","pista":"\"Their father died with no sons, only daughters.\""},{"pregunta":"How many cities of refuge were to be set apart for someone who had killed a person unintentionally?","opciones":["Six cities","Three cities","Twelve cities","A single city"],"dato":"Of the forty-eight Levitical cities, six were cities of refuge: three on this side of the Jordan and three in Canaan.","cita":"Numbers 35:6","versiculo":"The cities which you shall give to the Levites, they shall be the six cities of refuge, which you shall give for the man slayer to flee to.","vcita":"Numbers 35:6","pista":"\"Three on one side of the Jordan and three on the other.\""}],"Deuteronomy":[{"pregunta":"How does Israel's great confession of faith that begins with 'Hear, Israel' continue?","opciones":["Yahweh is our God. Yahweh is one","Yahweh is my shepherd, I shall not lack","Holy, holy, holy is Yahweh","Blessed is he who comes in Yahweh's name"],"dato":"The Shema ('Hear') is the central declaration of Judaism: God is one, and it was to be repeated at home, on the road, when lying down and when rising up.","cita":"Deuteronomy 6:4","versiculo":"Hear, Israel: Yahweh is our God. Yahweh is one.","vcita":"Deuteronomy 6:4","pista":"\"All Israel recited it from memory, twice a day.\""},{"pregunta":"How is a person to love God according to the great commandment in Deuteronomy?","opciones":["With all his heart, with all his soul, and with all his might","With weekly fasts","Only on the Sabbath day","In silence and without witnesses"],"dato":"This is the commandment Jesus called the first and greatest; in Hebrew it asks for heart, soul and 'muchness' (might).","cita":"Deuteronomy 6:5","versiculo":"You shall love Yahweh your God with all your heart, with all your soul, and with all your might.","vcita":"Deuteronomy 6:5","pista":"\"Heart, soul and might: nothing held back.\""},{"pregunta":"What did Israel learn in the wilderness about what sustains human life?","opciones":["That man does not live by bread only, but by everything that proceeds out of God's mouth","That manna is enough without obeying","That gold buys years of life","That the water from the rock never runs out"],"dato":"Jesus quoted this very sentence in the wilderness when the devil tempted him to turn stones into bread.","cita":"Deuteronomy 8:3","versiculo":"He humbled you, and allowed you to be hungry, and fed you with manna, which you didn't know, neither did your fathers know, that he might teach you that man does not live by bread only, but by everything that proceeds out of Yahweh's mouth does man live.","vcita":"Deuteronomy 8:3","pista":"\"Jesus quoted it against the devil in the wilderness.\""},{"pregunta":"What promise accompanies the command 'Be strong and courageous' before entering the land?","opciones":["That God goes with you; he will not fail you nor forsake you","That the Jordan will dry up forever","That there will never be war in the land","That the enemies will flee that very day"],"dato":"Moses repeated it to the people and then to Joshua at his commissioning: Israel's courage rested on God's presence, not on their strength.","cita":"Deuteronomy 31:6","versiculo":"Be strong and courageous. Don't be afraid or scared of them; for Yahweh your God himself is who goes with you. He will not fail you nor forsake you.","vcita":"Deuteronomy 31:6","pista":"\"Their courage came from not going alone.\""},{"pregunta":"How old was Moses when he died, according to the end of Deuteronomy?","opciones":["One hundred twenty years old","Ninety years old","Eighty years old","Forty years old"],"dato":"The account adds that at 120 'his eye was not dim, nor his natural force abated,' and that God himself buried him in Moab.","cita":"Deuteronomy 34:7","versiculo":"Moses was one hundred twenty years old when he died. His eye was not dim, nor his natural force abated.","vcita":"Deuteronomy 34:7","pista":"\"His life divides into three stages of forty years.\""},{"pregunta":"What did Moses promise God would raise up from among Israel's brothers?","opciones":["A prophet like Moses","A king like David","A priest like Aaron","A judge like Samson"],"dato":"Peter and Stephen quoted this prophecy in Acts, applying it to Jesus Christ: 'You shall listen to him.'","cita":"Deuteronomy 18:15","versiculo":"Yahweh your God will raise up to you a prophet from among you, of your brothers, like me. You shall listen to him.","vcita":"Deuteronomy 18:15","pista":"\"The apostles applied it to Jesus in the book of Acts.\""},{"pregunta":"What does God require of Israel in Deuteronomy 10: fear him, walk in his ways, love him, and...?","opciones":["Serve him with all the heart and all the soul","Offer him tithes every week","Build altars in every city","Keep silence for a year"],"dato":"God's list is surprisingly short: fear, walk, love and serve; and the next verse adds keeping his commandments 'for your good.'","cita":"Deuteronomy 10:12","versiculo":"Now, Israel, what does Yahweh your God require of you, but to fear Yahweh your God, to walk in all his ways, to love him, and to serve Yahweh your God with all your heart and with all your soul,","vcita":"Deuteronomy 10:12","pista":"\"Four verbs: fear, walk, love, and...\""},{"pregunta":"Between which two paths did God set Israel to choose, calling heaven and earth as witnesses?","opciones":["Life and death, the blessing and the curse","The sea and the desert","War and peace","Exile and return"],"dato":"God's counsel is explicit: 'Therefore choose life, that you may live, you and your descendants'; the choice had generational consequences.","cita":"Deuteronomy 30:19","versiculo":"I call heaven and earth to witness against you today, that I have set before you life and death, the blessing and the curse. Therefore choose life, that you may live, you and your descendants.","vcita":"Deuteronomy 30:19","pista":"\"And the divine counsel was: choose the first one.\""},{"pregunta":"Why was Israel a special people to God, according to Deuteronomy 7?","opciones":["Because God chose them to be a people for his own possession","Because they were the most numerous people on earth","Because they had never disobeyed him","Because they were the most feared army"],"dato":"The chapter rules out pride: they were not chosen for being great or righteous, but because of God's love and his oath to the patriarchs.","cita":"Deuteronomy 7:6","versiculo":"For you are a holy people to Yahweh your God. Yahweh your God has chosen you to be a people for his own possession, above all peoples who are on the face of the earth.","vcita":"Deuteronomy 7:6","pista":"\"Not for being great, but for being loved and chosen.\""},{"pregunta":"When was the poor laborer's wage to be paid, according to the law in Deuteronomy?","opciones":["The same day, before the sun went down","At the end of each month","At the harvest feast","Whenever the master had the money"],"dato":"Withholding wages was a cry that reached God: the laborer 'sets his heart on it,' and delaying it was counted as sin.","cita":"Deuteronomy 24:15","versiculo":"You shall give him his hire on the day he earns it, neither shall the sun go down on it; for he is poor, and sets his heart on it; lest he cry against you to Yahweh, and it be sin to you.","vcita":"Deuteronomy 24:15","pista":"\"The sun was not to set on an unpaid wage.\""},{"pregunta":"What prohibition did Moses give concerning the word God commanded?","opciones":["Not to add to it nor diminish from it","To write it only on stone","To read it in public once a year","To keep it secret until the jubilee"],"dato":"The same warning closes the whole Bible in Revelation 22: do not add or take away, so as to keep intact what God commanded.","cita":"Deuteronomy 4:2","versiculo":"You shall not add to the word which I command you, neither shall you diminish from it, that you may keep the commandments of Yahweh your God which I command you.","vcita":"Deuteronomy 4:2","pista":"\"The same warning reappears at the end of Revelation.\""}],"Matthew":[{"pregunta":"Before ascending to heaven, what did Jesus command his disciples concerning all nations?","opciones":["Go and make disciples of all nations, baptizing them in the name of the Father, the Son and the Holy Spirit","Go and build a temple in every city","Go and collect offerings from every people","Go and write the law on new tablets"],"dato":"This is the Great Commission, the risen Jesus' last instructions in Matthew, together with the promise 'I am with you always.'","cita":"Matthew 28:19","versiculo":"Go and make disciples of all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,","vcita":"Matthew 28:19","pista":"\"It comes with a promise: 'I am with you always.'\""}],"Mark":[{"pregunta":"What did Jesus promise to make of Simon and Andrew if they followed him by the Sea of Galilee?","opciones":["Fishers for men","Kings over Galilee","Teachers of the law","Guardians of the temple"],"dato":"They were fishermen by trade; Jesus changed the object of their fishing, and they, 'leaving their nets, followed him.'","cita":"Mark 1:17","versiculo":"Jesus said to them, \"Come after me, and I will make you into fishers for men.\"","vcita":"Mark 1:17","pista":"\"The same nets, but a different kind of catch.\""},{"pregunta":"What did the voice from heaven say when Jesus came up out of the water at his baptism?","opciones":["You are my beloved Son, in whom I am well pleased","This is the prophet who was to come","Listen to him every day","Behold the Lamb of God"],"dato":"At the baptism the Trinity was manifested: the Son in the water, the Spirit descending like a dove, and the Father's voice from the sky.","cita":"Mark 1:11","versiculo":"A voice came out of the sky, \"You are my beloved Son, in whom I am well pleased.\"","vcita":"Mark 1:11","pista":"\"Three key words: Son, beloved, well pleased.\""},{"pregunta":"Whom did Jesus say he had come to call, as he ate with tax collectors and sinners?","opciones":["Sinners, not the righteous","Only the Pharisees","The priests of the temple","The children of Bethlehem"],"dato":"His illustration was medical: 'Those who are healthy have no need for a physician, but those who are sick.'","cita":"Mark 2:17","versiculo":"When Jesus heard it, he said to them, \"Those who are healthy have no need for a physician, but those who are sick. I came not to call the righteous, but sinners to repentance.\"","vcita":"Mark 2:17","pista":"\"He used the example of a doctor and his patients.\""},{"pregunta":"According to Jesus, what good is it for a man to gain the whole world if he forfeits...?","opciones":["His life (his soul)","His family","His good health","His good name"],"dato":"The question is followed by the price of a soul: 'For what will a man give in exchange for his life?'; no wealth can buy it back.","cita":"Mark 8:36","versiculo":"For what does it profit a man, to gain the whole world, and forfeit his life?","vcita":"Mark 8:36","pista":"\"It is the one thing that cannot be bought back.\""},{"pregunta":"What did Jesus say when the disciples rebuked those who brought children to him?","opciones":["Allow the little children to come to me, for God's Kingdom belongs to such as these","Take them to the synagogue first","Let them come when they are older","Feed them before bringing them near"],"dato":"Mark says Jesus was indignant with the disciples, took the children in his arms, and blessed them, laying his hands on them.","cita":"Mark 10:14","versiculo":"Allow the little children to come to me! Don't forbid them, for God's Kingdom belongs to such as these.","vcita":"Mark 10:14","pista":"\"The little ones became the example of the kingdom.\""},{"pregunta":"\"With men it is impossible, but not with God.\" To which question was Jesus answering with that statement?","opciones":["Who can be saved","Who will enter Jerusalem first","Who will inherit the land of Canaan","Who will see the temple rebuilt"],"dato":"The conversation came from the rich young ruler: humanly no one can save himself, 'for all things are possible with God.'","cita":"Mark 10:27","versiculo":"Jesus, looking at them, said, \"With men it is impossible, but not with God, for all things are possible with God.\"","vcita":"Mark 10:27","pista":"\"It followed talk of a rich man and a camel through a needle's eye.\""},{"pregunta":"According to Jesus in Mark 11, what should be done with whatever is asked in prayer?","opciones":["Believe that you have received it","Ask for it in a very loud voice","Repeat it three times in a row","Ask for it only inside the temple"],"dato":"The teaching follows the episode of the withered fig tree: 'whatever you pray and ask for, believe that you have received them, and you shall have them.'","cita":"Mark 11:24","versiculo":"Therefore I tell you, all things whatever you pray and ask for, believe that you have received them, and you shall have them.","vcita":"Mark 11:24","pista":"\"Faith runs ahead of the answer.\""},{"pregunta":"What is the first and greatest commandment according to Jesus in the Gospel of Mark?","opciones":["You shall love the Lord your God with all your heart, soul, mind and strength","You shall not murder","Honor your father and your mother","Remember the Sabbath day to keep it holy"],"dato":"A scribe asked him which commandment was first of all; Jesus quoted the Shema and added the second: love your neighbor as yourself.","cita":"Mark 12:30","versiculo":"You shall love the Lord your God with all your heart, with all your soul, with all your mind, and with all your strength.' This is the first commandment.","vcita":"Mark 12:30","pista":"\"It begins with the words of the Shema from Deuteronomy.\""},{"pregunta":"According to Jesus, what will one day pass away, though his words will not pass away?","opciones":["Heaven and earth","The temple and the city","The sea and the stars","The kingdoms of this world"],"dato":"He said it in the Olivet discourse, speaking of the signs before the end and of his coming.","cita":"Mark 13:31","versiculo":"Heaven and earth will pass away, but my words will not pass away.","vcita":"Mark 13:31","pista":"\"The biggest and most stable things you see... will also pass away.\""},{"pregunta":"According to the end of Mark, what did the risen Jesus command his disciples?","opciones":["Go into all the world and preach the Good News to the whole creation","Stay in Jerusalem forever","Return to your nets in Galilee","Keep everything you saw a secret"],"dato":"It is Mark's version of the Great Commission, spoken to the eleven as they sat at the table, after he rebuked their unbelief.","cita":"Mark 16:15","versiculo":"He said to them, \"Go into all the world, and preach the Good News to the whole creation.\"","vcita":"Mark 16:15","pista":"\"The commission knows no borders: all the world.\""}],"Luke":[{"pregunta":"What did the angel Gabriel say to Mary to close his announcement about the birth of Jesus?","opciones":["That nothing spoken by God is impossible","That she had to flee to Egypt that night","That she should keep silent until the birth","That the child would be just another priest"],"dato":"Gabriel had just told her that her relative Elizabeth, barren and old, was also pregnant: the living example of that statement.","cita":"Luke 1:37","versiculo":"For nothing spoken by God is impossible.","vcita":"Luke 1:37","pista":"\"The example was Elizabeth, pregnant in her old age.\""},{"pregunta":"What did the angel announce to the shepherds on the night of Jesus' birth?","opciones":["That a Savior, who is Christ the Lord, had been born","That Herod had given up the throne","That they had to leave for Egypt","That the wise men had already arrived in Bethlehem"],"dato":"The announcement was 'good news of great joy' for all the people, and the sign was a baby wrapped in swaddling clothes, lying in a feeding trough.","cita":"Luke 2:11","versiculo":"For there is born to you today, in David's city, a Savior, who is Christ the Lord.","vcita":"Luke 2:11","pista":"\"The sign: a baby in a manger, in David's city.\""},{"pregunta":"In the synagogue at Nazareth, for what did Jesus say the Spirit of the Lord had anointed him?","opciones":["To preach good news to the poor","To judge the Pharisees of the city","To build a new synagogue","To write the book of Isaiah"],"dato":"Jesus read from Isaiah 61, rolled up the scroll and declared: 'Today, this Scripture has been fulfilled in your hearing.'","cita":"Luke 4:18","versiculo":"The Spirit of the Lord is on me, because he has anointed me to preach good news to the poor. He has sent me to heal the brokenhearted,","vcita":"Luke 4:18","pista":"\"He was reading from the prophet Isaiah... and the text was about him.\""},{"pregunta":"How does Jesus sum up how to treat others in the so-called 'golden rule'?","opciones":["As you would like people to do to you, do exactly so to them","An eye for an eye and a tooth for a tooth","Let each one look out only for himself","Treat only your friends well"],"dato":"In Luke it belongs to the same sermon that commands loving your enemies and lending, expecting nothing in return.","cita":"Luke 6:31","versiculo":"As you would like people to do to you, do exactly so to them.","vcita":"Luke 6:31","pista":"\"Put yourself in the other person's place... and act first.\""},{"pregunta":"What did the father do when he saw his prodigal son coming from far away?","opciones":["He ran to him, fell on his neck, and kissed him","He waited at the door for him to ask forgiveness","He sent him a servant with a new robe","He shut the door until he had worked for a year"],"dato":"The father saw him 'while he was still far off': he had been watching the road; moved with compassion, he ran, something beneath a patriarch's dignity in that culture.","cita":"Luke 15:20","versiculo":"He arose, and came to his father. But while he was still far off, his father saw him, and was moved with compassion, and ran, and fell on his neck, and kissed him.","vcita":"Luke 15:20","pista":"\"The father did not wait at home: he ran out.\""},{"pregunta":"Why did the Son of Man come, according to his own declaration at Zacchaeus' house?","opciones":["To seek and to save that which was lost","To judge the tax collectors of Jericho","To crown himself king in Jerusalem","To abolish the law of Moses"],"dato":"He said it after entering the house of Zacchaeus, the tax collector who had climbed a sycamore tree to see him pass by.","cita":"Luke 19:10","versiculo":"For the Son of Man came to seek and to save that which was lost.","vcita":"Luke 19:10","pista":"\"Two verbs: seek and save. And a short host.\""}],"John":[{"pregunta":"According to John 3:16, what did God give the world because of his great love?","opciones":["His one and only Son, so that whoever believes in him may have eternal life","The law engraved on stone tablets","The manna that came down from heaven","An immediate earthly kingdom"],"dato":"It is perhaps the most quoted verse in the Bible; Jesus said it at night, talking with Nicodemus, a ruler of the Jews.","cita":"John 3:16","versiculo":"For God so loved the world, that he gave his one and only Son, that whoever believes in him should not perish, but have eternal life.","vcita":"John 3:16","pista":"\"The conversation was with Nicodemus, and at night.\""}],"Joshua":[{"pregunta":"What was Joshua to do with the book of the law so that his way would prosper?","opciones":["Meditate on it day and night","Keep it locked inside the ark forever","Read it aloud only once a year","Teach it to the priests only"],"dato":"God charged Joshua not to let the law depart from his mouth: he was to meditate on it day and night and obey it carefully — that was the key to his success in conquering Canaan.","cita":"Joshua 1:8","versiculo":"This book of the law shall not depart from your mouth, but you shall meditate on it day and night, that you may observe to do according to all that is written in it; for then you shall make your way prosperous, and then you shall have good success.","vcita":"Joshua 1:8","pista":"\"The command comes at the very start of the book: the law always on his lips and in his mind.\""},{"pregunta":"What confession had the people of Jericho made, according to Rahab's report to the spies?","opciones":["That Yahweh is God in heaven above and on earth beneath","That the gods of Canaan were stronger than Yahweh","That Israel would be defeated at Jericho's gates","That the Jordan River could never be crossed"],"dato":"Rahab said the hearts of the Canaanites had melted when they heard what God had done for Israel at the Red Sea and against the Amorite kings, and she confessed that Yahweh is God in heaven above and on earth beneath.","cita":"Joshua 2:11","versiculo":"As soon as we heard it, our hearts melted, neither did there remain any more spirit in any man, because of you: for Yahweh your God, he is God in heaven above, and on earth beneath.","vcita":"Joshua 2:11","pista":"\"It was said by the woman who hid the spies under stalks of flax on her roof.\""},{"pregunta":"Where did the priests carrying the ark stand firm while all Israel crossed over on dry ground?","opciones":["In the middle of the Jordan","On the bank next to Jericho","On the summit of Mount Nebo","In the camp at Gilgal"],"dato":"As soon as the priests' feet touched the water, the Jordan stopped like a wall; they stood firm on dry ground in the middle of the river until the whole nation had completely crossed over.","cita":"Joshua 3:17","versiculo":"The priests who bore the ark of Yahweh's covenant stood firm on dry ground in the middle of the Jordan; and all Israel crossed over on dry ground, until all the nation had passed completely over the Jordan.","vcita":"Joshua 3:17","pista":"\"The people crossed as if on dry land, just as at the Red Sea a generation earlier.\""},{"pregunta":"Why did Joshua command that twelve stones be taken from the Jordan and set up at Gilgal?","opciones":["As a sign, so that children would ask what they meant","To build an altar for burnt offerings","To mark the spot of Moses' tomb","To count the fighting men of Israel"],"dato":"The twelve stones, one for each tribe, were to be a lasting memorial: when children asked what the stones meant, their parents would tell how God had cut off the waters of the Jordan.","cita":"Joshua 4:6","versiculo":"that this may be a sign among you, that when your children ask in time to come, saying, 'What do you mean by these stones?'","vcita":"Joshua 4:6","pista":"\"Each stone stood for one of the twelve tribes.\""},{"pregunta":"What did Joshua read before all Israel on Mount Ebal, after the victory over Ai?","opciones":["All the words of the law, the blessing and the curse","Only the Ten Commandments","A psalm he had composed himself","The census of the men of every tribe"],"dato":"Just as Moses had commanded, Joshua read the whole law before men, women and children, with the ark and the Levites in the middle, between Mount Gerizim and Mount Ebal.","cita":"Joshua 8:34","versiculo":"Afterward he read all the words of the law, the blessing and the curse, according to all that is written in the book of the law.","vcita":"Joshua 8:34","pista":"\"Half the people stood facing one mountain and half facing the other.\""},{"pregunta":"What did Joshua do with all the land he had conquered?","opciones":["He gave it to the Israelites as an inheritance, divided by tribes","He left it undivided until the next generation","He consecrated all of it as a single sanctuary","He returned it to the Canaanites in exchange for tribute"],"dato":"Joshua took the land according to all that Yahweh had spoken to Moses and divided it by lot among the tribes; then the land had rest from war.","cita":"Joshua 11:23","versiculo":"So Joshua took the whole land, according to all that Yahweh spoke to Moses; and Joshua gave it for an inheritance to Israel according to their divisions by their tribes. The land had rest from war.","vcita":"Joshua 11:23","pista":"\"The division of the land closes the conquest stage of the book.\""},{"pregunta":"What did Caleb ask Joshua for as his inheritance, even though he was already 85 years old?","opciones":["The hill country where the Anakim giants lived","The coastal plain of the Philistines","The Jordan valley next to Jericho","The walled city of Jerusalem"],"dato":"Caleb, one of the two faithful spies, asked for the hill country inhabited by the Anakim, trusting he could drive them out with God's help; Joshua blessed him and gave him Hebron as his inheritance.","cita":"Joshua 14:12","versiculo":"Now therefore give me this hill country, of which Yahweh spoke in that day; for you heard in that day how the Anakim were there, and great fortified cities. It may be that Yahweh will be with me, and I shall drive them out, as Yahweh said.","vcita":"Joshua 14:12","pista":"\"It was the land of the giants that had frightened the other spies forty years before.\""},{"pregunta":"What is said about all the good words Yahweh had spoken to the house of Israel?","opciones":["None of them failed: all came to pass","Half of them were left for the future","Only those spoken to Moses were fulfilled","Only Judah's promises were fulfilled"],"dato":"At the end of the conquest account, the book underlines God's absolute faithfulness: not one of his good promises to Israel failed to come to pass.","cita":"Joshua 21:45","versiculo":"Nothing failed of any good thing which Yahweh had spoken to the house of Israel. All came to pass.","vcita":"Joshua 21:45","pista":"\"It is the closing line about God's promises: not a single one failed.\""},{"pregunta":"What decision did Joshua set before the people gathered at Shechem at the end of his life?","opciones":["To choose whom they would serve: Yahweh or the other gods","To elect a king from among the tribes","To return to Egypt in search of food","To build a permanent temple at Shiloh"],"dato":"Joshua renewed the covenant at Shechem and declared his own choice in the book's most famous words: \"As for me and my house, we will serve Yahweh.\" The people answered that they too would serve God.","cita":"Joshua 24:15","versiculo":"If it seems evil to you to serve Yahweh, choose today whom you will serve; whether the gods which your fathers served that were beyond the River, or the gods of the Amorites, in whose land you dwell; but as for me and my house, we will serve Yahweh.","vcita":"Joshua 24:15","pista":"\"His answer boils down to one line: he and his house would serve Yahweh.\""}],"Judges":[{"pregunta":"Whom did Yahweh raise up to save Israel out of the hand of those who plundered them?","opciones":["Judges","Hereditary kings","Foreign governors","Captains of mercenaries"],"dato":"The book shows a repeating cycle: Israel sinned, was oppressed, cried out to God, and Yahweh raised up judges who saved them from their enemies.","cita":"Judges 2:16","versiculo":"Yahweh raised up judges, who saved them out of the hand of those who plundered them.","vcita":"Judges 2:16","pista":"\"This whole book of the Bible takes its name from them.\""},{"pregunta":"With what tool did Shamgar strike down six hundred men of the Philistines?","opciones":["An ox goad","The jawbone of a freshly killed donkey","A sling and five smooth stones","The sword of a Philistine captain"],"dato":"Shamgar, one of the minor judges, struck down six hundred Philistines with an ox goad, the pointed stick used to drive cattle: he too saved Israel.","cita":"Judges 3:31","versiculo":"After him was Shamgar the son of Anath, who struck six hundred men of the Philistines with an ox goad. He also saved Israel.","vcita":"Judges 3:31","pista":"\"It was a farm tool, not a weapon of war.\""},{"pregunta":"How did Yahweh's angel greet Gideon as he threshed wheat in hiding from the Midianites?","opciones":["\"Yahweh is with you, you mighty man of valor\"","\"Peace be with you, future king of Israel\"","\"Arise, prophet among the nations\"","\"Blessed are you, judge of the tribes\""],"dato":"The angel called Gideon a \"mighty man of valor,\" although he was hiding to thresh wheat and considered himself the least in his father's house; God chose him to deliver Israel.","cita":"Judges 6:12","versiculo":"Yahweh's angel appeared to him, and said to him, 'Yahweh is with you, you mighty man of valor!'","vcita":"Judges 6:12","pista":"\"Gideon was threshing in the wine press to hide the grain.\""},{"pregunta":"What vow did Jephthah make to Yahweh before going out to fight the children of Ammon?","opciones":["To offer as a burnt offering whoever came out of his house to meet him on his return in peace","Not to cut his hair until the war was over","To raise an altar of twelve stones at Mizpah","To fast with his whole army for seven days"],"dato":"Jephthah promised that, if God delivered the Ammonites into his hand, whatever came out of the doors of his house to meet him would be Yahweh's and be offered as a burnt offering; on his triumphant return his only daughter came out, and the vow cost him immense sorrow.","cita":"Judges 11:30","versiculo":"Jephthah vowed a vow to Yahweh, and said, \"If you will indeed deliver the children of Ammon into my hand, then it shall be, that whatever comes out of the doors of my house to meet me, when I return in peace from the children of Ammon, it shall be Yahweh's, and I will offer it up for a burnt offering.\"","vcita":"Judges 11:30-31","pista":"\"The vow turned tragic when his only daughter came out to meet him with tambourines and dancing.\""},{"pregunta":"What son was born to Manoah's wife, announced beforehand by the angel, and blessed by Yahweh as he grew?","opciones":["Samson","Samuel","Abdon","Elon"],"dato":"Manoah's wife was barren, but the angel announced a son who would be a Nazirite from the womb; Samson was born, and the child grew, and Yahweh blessed him, and his Spirit began to move him.","cita":"Judges 13:24","versiculo":"The woman bore a son, and named him Samson. The child grew, and Yahweh blessed him.","vcita":"Judges 13:24","pista":"\"His birth was announced to a barren woman from the town of Zorah.\""},{"pregunta":"What animal did Samson tear apart with his bare hands, with nothing in his hand?","opciones":["A young lion that came roaring against him","A bear attacking his father's flock","A wolf prowling the vineyards of Timnah","A wild Philistine bull"],"dato":"Going down to Timnah, a young lion came roaring against Samson; Yahweh's Spirit came mightily on him and he tore it as one tears a young goat, telling neither his father nor his mother.","cita":"Judges 14:6","versiculo":"Yahweh's Spirit came mightily on him, and he tore him as he would have torn a young goat. He had nothing in his hand, but he didn't tell his father or his mother what he had done.","vcita":"Judges 14:6","pista":"\"Days later he found honey in that same animal's body, and from that came his riddle.\""},{"pregunta":"What did Samson ask God in his final prayer, in the temple of Dagon?","opciones":["To strengthen him just this once to be avenged on the Philistines for his two eyes","To restore his sight before he died","To send an earthquake over all Gaza","To forgive Delilah and her household"],"dato":"Blind, shaved and chained between the pillars, Samson called out: \"Lord Yahweh, remember me, please,\" asking for strength once more to be avenged on the Philistines for his two eyes; and God heard him.","cita":"Judges 16:28","versiculo":"Samson called to Yahweh, and said, \"Lord Yahweh, remember me, please, and strengthen me, please, only this once, God, that I may be at once avenged of the Philistines for my two eyes.\"","vcita":"Judges 16:28","pista":"\"He prayed while leaning between the two central pillars of the temple.\""},{"pregunta":"What is said about the Philistines Samson killed when he died, compared with those he killed during his life?","opciones":["Those he killed at his death were more than those he killed in his life","They were exactly the same number","He killed no one at his death","Only the five lords of the Philistines died"],"dato":"Pushing the pillars, the temple of Dagon fell on the lords and on all the people gathered for the feast; so the dead Samson killed at his death were more than those he killed in his life.","cita":"Judges 16:30","versiculo":"Samson said, \"Let me die with the Philistines!\" He bowed himself with all his might; and the house fell on the lords, and on all the people who were in it. So the dead that he killed at his death were more than those who he killed in his life.","vcita":"Judges 16:30","pista":"\"Just before pushing, he cried: let me die with the Philistines.\""},{"pregunta":"What sentence, repeated at the end of the book, sums up the spiritual anarchy of the days of the judges?","opciones":["\"There was no king in Israel: everyone did what was right in his own eyes\"","\"And the land had rest from war for forty years\"","\"The people served Yahweh all the days of the elders\"","\"And there was peace between Israel and the Philistines\""],"dato":"With no king and no firm direction, every Israelite did whatever seemed right to him: that sentence explains the cycle of sin, oppression, crying out and deliverance running through the whole book.","cita":"Judges 21:25","versiculo":"In those days there was no king in Israel. Everyone did that which was right in his own eyes.","vcita":"Judges 21:25","pista":"\"It is literally the last verse of the book.\""}],"Ruth":[{"pregunta":"Why did Elimelech leave Bethlehem with his wife and his two sons for the country of Moab?","opciones":["Because there was a famine in the land","Because a judge had banished him from Israel","To sell wheat to the Moabites","To escape a Philistine invasion"],"dato":"In the days when the judges ruled there was a famine in the land, and Elimelech of Bethlehem Judah went to live in the country of Moab with Naomi and their sons Mahlon and Chilion.","cita":"Ruth 1:1","versiculo":"It happened in the days when the judges judged, that there was a famine in the land. A certain man of Bethlehem Judah went to live in the country of Moab, he, and his wife, and his two sons.","vcita":"Ruth 1:1","pista":"\"Bethlehem means 'house of bread' — and yet the bread ran out.\""},{"pregunta":"What name did Naomi ask to be called when she returned to Bethlehem, instead of Naomi?","opciones":["Mara, because the Almighty had dealt very bitterly with her","Sarah, because God had laughed with her","Rachel, because she had wept for her children","Dinah, because she had been judged by the women"],"dato":"Naomi means \"pleasant,\" but she asked to be called Mara, which sounds like \"bitter\": she had gone out full, and Yahweh had brought her back empty, without husband and without sons.","cita":"Ruth 1:20","versiculo":"She said to them, \"Don't call me Naomi. Call me Mara; for the Almighty has dealt very bitterly with me.\"","vcita":"Ruth 1:20","pista":"\"The new name speaks of bitterness, the opposite of Naomi's sweetness.\""},{"pregunta":"In what harvest season did Naomi and Ruth arrive in Bethlehem?","opciones":["At the beginning of the barley harvest","In the middle of the grape vintage","At the end of the wheat threshing","During the olive picking"],"dato":"They returned from the country of Moab just as the barley harvest was beginning; that is why Ruth could go out right away to glean behind the reapers.","cita":"Ruth 1:22","versiculo":"So Naomi returned, and Ruth the Moabitess, her daughter-in-law, with her, who returned out of the country of Moab. They came to Bethlehem at the beginning of barley harvest.","vcita":"Ruth 1:22","pista":"\"They arrived just as the first grain harvest of the year was starting.\""},{"pregunta":"What permission did Ruth ask Naomi in order to go out to the field?","opciones":["To glean among the ears of grain after the one in whose sight she found favor","To work as a cook in Boaz's house","To sell barley at the city gate","To harvest a plot of Elimelech's own land"],"dato":"God's law let the poor gather the fallen ears behind the reapers; Ruth asked to go, and by providence she came to the field of Boaz, a relative of Elimelech.","cita":"Ruth 2:2","versiculo":"Ruth the Moabitess said to Naomi, \"Let me now go to the field, and glean among the ears of grain after him in whose sight I shall find favor.\" She said to her, \"Go, my daughter.\"","vcita":"Ruth 2:2","pista":"\"It was the right the law reserved for the poor, widows and foreigners.\""},{"pregunta":"What did Ruth ask Boaz, bowing to the ground, when he treated her with kindness?","opciones":["Why she had found favor in his eyes, since she was a foreigner","Whether she could also glean in the neighboring fields","How much barley she could take home to Naomi","Whether Boaz had known her late husband"],"dato":"Boaz invited her to glean only in his field and to drink from his servants' water; Ruth, astonished and humble, acknowledged that she had no claim at all, being a foreigner.","cita":"Ruth 2:10","versiculo":"Then she fell on her face, and bowed herself to the ground, and said to him, \"Why have I found favor in your sight, that you should take knowledge of me, since I am a foreigner?\"","vcita":"Ruth 2:10","pista":"\"Her surprise was that she had no rights at all: she came from Moab.\""},{"pregunta":"With what image did Boaz bless Ruth for coming to take refuge in the God of Israel?","opciones":["The wings of Yahweh, under which she had come to take refuge","The shade of a cedar planted by the waters","The walls of Bethlehem in time of war","The mantle of the priests in the sanctuary"],"dato":"Boaz asked that Yahweh repay her work with a full reward, for she had left her land and her family to take refuge under the wings of the God of Israel, like a chick under its mother's wings.","cita":"Ruth 2:12","versiculo":"May Yahweh repay your work, and a full reward be given to you by Yahweh, the God of Israel, under whose wings you have come to take refuge.","vcita":"Ruth 2:12","pista":"\"The picture is of a bird sheltering its young under its wings.\""},{"pregunta":"What did Ruth ask Boaz at the threshing floor, presenting herself at night as his servant?","opciones":["To spread his skirt over her, because he was a near kinsman","To give her ten measures of barley for Naomi","To present her before the elders that very night","To let her sleep by the grain heaps all winter"],"dato":"Spreading one's garment over someone was a gesture of covering and commitment; with those words Ruth asked Boaz to act as her kinsman-redeemer and take her as his wife.","cita":"Ruth 3:9","versiculo":"He said, \"Who are you?\" She answered, \"I am Ruth your servant. Spread your skirt over your servant, for you are a near kinsman.\"","vcita":"Ruth 3:9","pista":"\"The gesture with the garment was a request for redemption and marriage.\""},{"pregunta":"What reputation did Ruth have among all the people of Bethlehem, according to Boaz?","opciones":["All the city knew that she was a worthy woman","They called her the fortunate Moabitess","They said she was a prophetess like Deborah","They knew her only as Mahlon's widow"],"dato":"Boaz promised not to fear and to do all she asked, because all the city of his people knew that Ruth was a worthy woman: her loyalty to Naomi had proven her before everyone.","cita":"Ruth 3:11","versiculo":"Now, my daughter, don't be afraid. I will do to you all that you say; for all the city of my people knows that you are a worthy woman.","vcita":"Ruth 3:11","pista":"\"Her fame was not for riches, but for virtue and faithfulness.\""},{"pregunta":"Why did the nearer kinsman refuse before the elders to redeem Elimelech's inheritance?","opciones":["Because redeeming it would endanger his own inheritance","Because he could not pay the price of the field","Because he was already married to a woman of Judah","Because he lived far away in the land of Moab"],"dato":"The kinsman first agreed to redeem the field, but when he learned he must also take Ruth as wife to raise up the name of the dead, he backed out lest he endanger his own inheritance, and yielded his right to Boaz by taking off his shoe.","cita":"Ruth 4:6","versiculo":"The near kinsman said, \"I can't redeem it for myself, lest I endanger my own inheritance. Take my right of redemption for yourself; for I can't redeem it.\"","vcita":"Ruth 4:6","pista":"\"The condition that made him give up was having to marry the Moabite widow.\""},{"pregunta":"What gift did Yahweh grant Ruth after Boaz took her as his wife?","opciones":["That she conceived and bore a son","That she saw her mother again in Moab","That her name was written in the temple","That she inherited all of Boaz's fields"],"dato":"Boaz took Ruth, and Yahweh enabled her to conceive, and she bore a son; the birth filled Naomi and the women of Bethlehem with joy.","cita":"Ruth 4:13","versiculo":"So Boaz took Ruth, and she became his wife. He went in to her, and Yahweh enabled her to conceive, and she bore a son.","vcita":"Ruth 4:13","pista":"\"The child restored joy to Naomi, who took him into her arms.\""},{"pregunta":"What name did the neighbor women give Ruth's son, and of what great king was he an ancestor?","opciones":["Obed, grandfather of David","Solomon, father of Rehoboam","Jesse, grandfather of Saul","Boaz, father of the judges"],"dato":"The women named him Obed; he was the father of Jesse, and Jesse the father of David. So faithful Ruth the Moabitess entered the genealogy of King David and, centuries later, of the Messiah.","cita":"Ruth 4:17","versiculo":"The women, her neighbors, gave him a name, saying, \"A son is born to Naomi!\" They named him Obed. He is the father of Jesse, the father of David.","vcita":"Ruth 4:17","pista":"\"Of the child it is said: he is the father of Jesse, the father of David.\""}],"1 Samuel":[{"pregunta":"What did Hannah proclaim about Yahweh in her song of thanksgiving?","opciones":["That there is no one holy like Yahweh, no one besides him, and no rock like our God","That Yahweh wounds with sword and spear","That the heaven of heavens cannot contain him","That he raises kings and levels mountains only"],"dato":"Bringing little Samuel to the house at Shiloh, Hannah sang that there is no one holy like Yahweh, no one besides him, and no rock like our God, who humbles and exalts.","cita":"1 Samuel 2:2","versiculo":"There is no one as holy as Yahweh, for there is no one besides you, nor is there any rock like our God.","vcita":"1 Samuel 2:2","pista":"\"Her song opens by declaring that no one is holy like him.\""},{"pregunta":"What did Samuel answer when he finally understood that Yahweh was calling him in the night?","opciones":["\"Speak, for your servant hears\"","\"Here I am, send me\"","\"Lord, here I am for the battle\"","\"Your servant will sleep and watch your house\""],"dato":"Three times Samuel ran to Eli thinking the old man had called him; the fourth time, instructed by the priest, he answered, \"Speak, for your servant hears,\" and received God's message against Eli's house.","cita":"1 Samuel 3:10","versiculo":"Yahweh came, and stood, and called as at other times, \"Samuel! Samuel!\" Then Samuel said, \"Speak, for your servant hears.\"","vcita":"1 Samuel 3:10","pista":"\"Three times before, he thought it was old Eli calling him.\""},{"pregunta":"What did Yahweh explain to Samuel when the people asked for a king?","opciones":["That they had not rejected Samuel, but God himself, so he would not be king over them","That the king had to come from the tribe of Levi","That they first had to build a palace at Ramah","That Samuel himself should accept the crown"],"dato":"Samuel was displeased at the request, but Yahweh made clear the rejection was not against the prophet but against himself as Israel's King; even so, he warned them what a human king would cost them.","cita":"1 Samuel 8:7","versiculo":"Yahweh said to Samuel, \"Listen to the voice of the people in all that they tell you; for they have not rejected you, but they have rejected me, that I should not be king over them.\"","vcita":"1 Samuel 8:7","pista":"\"The people wanted to be 'like all the nations.'\""},{"pregunta":"What did Samuel tell Saul is better than burnt offerings and sacrifices?","opciones":["Obeying the voice of Yahweh","Offering ten thousand lambs at Gilgal","Fasting three days before the battle","Multiplying altars throughout Israel"],"dato":"Saul had disobeyed by sparing the best of Amalek's livestock \"to sacrifice it\"; Samuel pronounced the sentence: to obey is better than sacrifice, and to listen than the fat of rams.","cita":"1 Samuel 15:22","versiculo":"Samuel said, \"Has Yahweh as great delight in burnt offerings and sacrifices, as in obeying Yahweh's voice? Behold, to obey is better than sacrifice, and to listen than the fat of rams.\"","vcita":"1 Samuel 15:22","pista":"\"The sentence compares obeying with the fat of rams.\""},{"pregunta":"What does Yahweh look at in a man, unlike man who looks at the outward appearance?","opciones":["The heart","Height and good looks","The strength of his arms","The wealth of his house"],"dato":"Samuel was ready to anoint imposing Eliab, Jesse's eldest, but God taught him that he does not see as man sees — man looks at the outward appearance, but Yahweh looks at the heart; so David, the youngest, was chosen.","cita":"1 Samuel 16:7","versiculo":"But Yahweh said to Samuel, \"Don't look on his face, or on the height of his stature, because I have rejected him; for I see not as man sees. For man looks at the outward appearance, but Yahweh looks at the heart.\"","vcita":"1 Samuel 16:7","pista":"\"By this rule the eldest brother was passed over and the shepherd boy was chosen.\""},{"pregunta":"In whose name did David declare to Goliath that he came against him?","opciones":["In the name of Yahweh of Armies","In the name of King Saul and his crown","In the name of the three thousand men of Judah","In the name of his father Jesse of Bethlehem"],"dato":"The Philistine came with sword, spear and javelin; David, a shepherd without armor, answered that he came in the name of Yahweh of Armies, the God of the armies of Israel, whom the giant had defied.","cita":"1 Samuel 17:45","versiculo":"Then David said to the Philistine, \"You come to me with a sword, a spear, and a javelin, but I come to you in the name of Yahweh of Armies, the God of the armies of Israel, whom you have defied.\"","vcita":"1 Samuel 17:45","pista":"\"The giant carried three weapons; David carried a Name.\""},{"pregunta":"What great truth did David proclaim to all the assembly before facing Goliath?","opciones":["That the battle is Yahweh's and he does not save by sword and spear","That Israel had the largest army in the region","That Saul's armor had been blessed by Samuel","That the valley of Elah belonged to his family by inheritance"],"dato":"David declared that Yahweh does not save by sword or spear, for the battle is his; so all the assembly would know that there is a God in Israel.","cita":"1 Samuel 17:47","versiculo":"and that all this assembly may know that Yahweh doesn't save with sword and spear; for the battle is Yahweh's, and he will give you into our hand.","vcita":"1 Samuel 17:47","pista":"\"His confidence was not in the weapon, but in whose the battle is.\""},{"pregunta":"What did the women of Israel sing when David returned from defeating the Philistine?","opciones":["\"Saul has slain his thousands, and David his ten thousands\"","\"David shall reign over all Israel\"","\"The Lord has set a crown on the shepherd\"","\"The giant fell and Philistia fled\""],"dato":"The women came out dancing from all the cities, singing that Saul had slain his thousands and David his ten thousands; that song kindled Saul's jealousy, and from that day he eyed David with suspicion.","cita":"1 Samuel 18:7","versiculo":"The women sang to one another as they played, and said, \"Saul has slain his thousands, and David his ten thousands.\"","vcita":"1 Samuel 18:7","pista":"\"The refrain compared thousands with ten thousands, and that stung the king.\""}],"2 Samuel":[{"pregunta":"How did David go before the ark as it was brought up to Jerusalem?","opciones":["Dancing before Yahweh with all his might, clothed in a linen ephod","In silence, with his head covered and ashes on it","Riding in the new cart pulled by oxen","Wearing the crown and scepter that had been Saul's"],"dato":"David danced before Yahweh with all his might, clothed only in a linen ephod; Michal despised him for it, but he answered that his joy was before God, not to show off before men.","cita":"2 Samuel 6:14","versiculo":"David danced before Yahweh with all his might; and David was clothed in a linen ephod.","vcita":"2 Samuel 6:14","pista":"\"His wife Michal watched from a window and despised him in her heart.\""},{"pregunta":"What did Yahweh promise David, through Nathan, concerning his offspring?","opciones":["That he would set up his offspring after him and establish his kingdom","That his eldest son would reign only seven years","That the kingdom would pass forever to the tribe of Benjamin","That none of his descendants would ever sin again"],"dato":"David wanted to build God a house, but God announced that he would build David a house: he would raise up his offspring after him, who would come from his own body, and establish his kingdom. It is the great promise of the Davidic covenant.","cita":"2 Samuel 7:12","versiculo":"When your days are fulfilled, and you sleep with your fathers, I will set up your offspring after you, who will proceed out of your body, and I will establish his kingdom.","vcita":"2 Samuel 7:12","pista":"\"The king wanted to build God a house, and God promised him a house instead.\""},{"pregunta":"What did David confess in his prayer of gratitude after receiving the covenant?","opciones":["That there is no one like Yahweh, and no God besides him","That Israel was the most numerous people on earth","That the temple would be finished within a year","That he would never go out to war again"],"dato":"Amazed, David went in and sat before Yahweh asking, \"Who am I?\", and confessed: \"There is no one like you, neither is there any God besides you,\" according to all they had heard with their ears.","cita":"2 Samuel 7:22","versiculo":"Therefore you are great, Yahweh God. For there is no one like you, neither is there any God besides you, according to all that we have heard with our ears.","vcita":"2 Samuel 7:22","pista":"\"His prayer begins by asking: who am I, and what is my house?\""},{"pregunta":"What did kings usually do at the season when David sent Joab against the Ammonites… and what did David do?","opciones":["They went out to battle; but David stayed at Jerusalem","They celebrated the Passover feast at Shiloh","They took the census of all the men","They divided the conquered lands among the tribes"],"dato":"At the return of the year, the time when kings go out to campaign, David sent Joab and the army against Rabbah, but he stayed at Jerusalem; from that idle walk on the rooftop came his fall with Bathsheba.","cita":"2 Samuel 11:1","versiculo":"At the return of the year, at the time when kings go out, David sent Joab, his servants with him, and all Israel; and they destroyed the children of Ammon, and besieged Rabbah. But David stayed at Jerusalem.","vcita":"2 Samuel 11:1","pista":"\"The key line of the story is: but David stayed at Jerusalem.\""},{"pregunta":"What did David confess to the prophet Nathan after being confronted over his sin?","opciones":["\"I have sinned against Yahweh\"","\"The people are to blame for tempting me\"","\"Uriah deserved to die at the front\"","\"I will leave the throne and return to Bethlehem\""],"dato":"David made no excuses: he confessed, \"I have sinned against Yahweh.\" Nathan announced that God had put away his sin and he would not die, though the child who was born would die and the sword would not depart from his house.","cita":"2 Samuel 12:13","versiculo":"David said to Nathan, \"I have sinned against Yahweh.\" Nathan said to David, \"Yahweh also has put away your sin. You will not die.\"","vcita":"2 Samuel 12:13","pista":"\"His confession was only a few words, but it changed his story.\""},{"pregunta":"By what ascent did David go up fleeing from his son Absalom, weeping, with his head covered and barefoot?","opciones":["The ascent of the Mount of Olives","The road from Jericho down to the Jordan","The descent of Mount Gilboa","The Kidron valley toward the wilderness of En Gedi, on horseback only"],"dato":"During Absalom's rebellion, David crossed the Kidron brook and went up the ascent of the Mount of Olives weeping, barefoot and with his head covered, in mourning and humiliation, and all the people went up weeping with him.","cita":"2 Samuel 15:30","versiculo":"David went up by the ascent of the Mount of Olives, and wept as he went up; and he had his head covered, and went barefoot. All the people who were with him covered every man his head, and they went up, weeping as they went up.","vcita":"2 Samuel 15:30","pista":"\"Centuries later, his greatest Descendant also prayed and wept on that same mount.\""},{"pregunta":"What did David wish, weeping in the room over the gate, when he heard that Absalom was dead?","opciones":["That he had died instead of his son","That Joab be executed that very night","That the kingdom pass at once to Adonijah","To be anointed again at Hebron before the people"],"dato":"The king was deeply moved and went up to weep, saying: \"My son Absalom! My son, my son Absalom! I wish I had died for you, Absalom, my son, my son!\"; his grief was so great that victory turned to mourning for the army.","cita":"2 Samuel 18:33","versiculo":"The king was much moved, and went up to the room over the gate, and wept. As he went, he said, \"My son Absalom! My son, my son Absalom! I wish I had died for you, Absalom, my son, my son!\"","vcita":"2 Samuel 18:33","pista":"\"He kept repeating: my son, my son.\""},{"pregunta":"With what three titles did David call Yahweh at the opening of his song of deliverance?","opciones":["My rock, my fortress and my deliverer","My shepherd, my light and my salvation","My shield, my banner and my strong tower","My father, my judge and my crown"],"dato":"In the song of 2 Samuel 22 — practically the same text as Psalm 18 — David celebrates the day Yahweh delivered him from Saul and from all his enemies, calling him his rock, his fortress and his deliverer.","cita":"2 Samuel 22:2","versiculo":"and he said, \"Yahweh is my rock, my fortress, and my deliverer, even mine;\"","vcita":"2 Samuel 22:2","pista":"\"This song also appears, nearly identical, as a very well-known psalm.\""},{"pregunta":"What longing did David express that led three of his mighty men to break through the Philistine camp at the risk of their lives?","opciones":["To drink water from the well of Bethlehem by the gate","To eat of the showbread at Nob","To hear once more the songs of his youth","To gaze at the ark before dying"],"dato":"David longed for the water of his native Bethlehem, held by the Philistines; three mighty men brought it, but David would not drink it and poured it out before Yahweh, calling it the blood of the men who went at the risk of their lives.","cita":"2 Samuel 23:15","versiculo":"David longed, and said, \"Oh that one would give me water to drink from the well of Bethlehem, which is by the gate!\"","vcita":"2 Samuel 23:15","pista":"\"When he received it, he did not drink it: he poured it out as an offering to Yahweh.\""}],"1 Kings":[{"pregunta":"What did Solomon acknowledge in his prayer of dedication about the heaven of heavens?","opciones":["That not even they can contain God, much less the house he had built","That God would dwell forever only in the Most Holy Place","That the temple would never suffer any harm","That the heavens are the footstool of the king"],"dato":"Solomon prayed with humility: if even heaven and the heaven of heavens cannot contain God, how much less the house he had built? He asked God to hear from heaven, his dwelling place, and forgive.","cita":"1 Kings 8:27","versiculo":"But will God in very deed dwell on the earth? Behold, heaven and the heaven of heavens can't contain you; how much less this house that I have built!","vcita":"1 Kings 8:27","pista":"\"The temple was grand, but the king admitted that God cannot be contained.\""},{"pregunta":"What did Elijah announce to Ahab the first time he appeared before the king of Israel?","opciones":["That there would be neither dew nor rain those years except by his word","That fire would consume Samaria's palace that very night","That Jezebel would die before the month ended","That Syria would hand over its cities without a fight"],"dato":"Elijah the Tishbite burst in before Ahab swearing by Yahweh, the God of Israel, that there would be no dew or rain in those years except by his word; thus began the great drought of three and a half years.","cita":"1 Kings 17:1","versiculo":"Elijah the Tishbite, who was one of the settlers of Gilead, said to Ahab, \"As Yahweh, the God of Israel, lives, before whom I stand, there shall not be dew nor rain these years, but according to my word.\"","vcita":"1 Kings 17:1","pista":"\"His announcement shut the heavens over Israel for years.\""},{"pregunta":"What did all the people cry out, falling on their faces, when Yahweh's fire consumed the offering on Carmel?","opciones":["\"Yahweh, he is God! Yahweh, he is God!\"","\"Great is Baal, lord of the rain!\"","\"Let the prophet be king over us!\"","\"Flee, the mountain is burning!\""],"dato":"When the fire fell and consumed the burnt offering, the wood, the stones and even the water in the trench, the people fell on their faces and confessed twice: \"Yahweh, he is God!\", turning their hearts back to the Lord.","cita":"1 Kings 18:39","versiculo":"When all the people saw it, they fell on their faces. They said, \"Yahweh, he is God! Yahweh, he is God!\"","vcita":"1 Kings 18:39","pista":"\"The cry is repeated twice in the same verse.\""},{"pregunta":"In what did Yahweh make himself known to Elijah on Mount Horeb, after the wind, the earthquake and the fire?","opciones":["In a still small voice","In the fire that came down on the rock","In the earthquake that split the rocks","In the great wind that broke the mountains"],"dato":"Yahweh was not in the great wind, nor in the earthquake, nor in the fire; he spoke in the still small voice, and Elijah, hearing it, wrapped his face in his mantle and stood at the entrance of the cave.","cita":"1 Kings 19:12","versiculo":"After the earthquake a fire passed; but Yahweh was not in the fire. After the fire, there was a still small voice.","vcita":"1 Kings 19:12","pista":"\"It was not a roar, but a gentle, quiet whisper.\""}],"2 Kings":[{"pregunta":"What did Elisha ask Elijah when he knew his master was about to be taken from him?","opciones":["That a double portion of his spirit be on him","That he write down Israel's future for him","That he hand him the keys of the Jordan","That he let him stay in Bethel"],"dato":"Elisha asked for the firstborn's portion: a double share of Elijah's spirit. The master answered that he had asked a hard thing, but that if he saw him when he was taken, it would be so; and he did see him go up in the whirlwind.","cita":"2 Kings 2:9","versiculo":"When they had gone over, Elijah said to Elisha, \"Ask what I shall do for you, before I am taken from you.\" Elisha said, \"Please let a double portion of your spirit be on me.\"","vcita":"2 Kings 2:9","pista":"\"He asked for the eldest son's inheritance: a double portion.\""},{"pregunta":"What did the Shunammite's son do just before opening his eyes when Elisha raised him?","opciones":["He sneezed seven times","He called out loudly for his mother","He asked for a little water","He sat up and hugged the prophet"],"dato":"Elisha prayed and stretched himself on the child twice; the second time, the boy sneezed seven times and opened his eyes, alive, and the prophet gave him to his mother, who fell at his feet.","cita":"2 Kings 4:35","versiculo":"Then he returned, and walked in the house once back and forth, then went up and stretched himself on him. Then the child sneezed seven times, and the child opened his eyes.","vcita":"2 Kings 4:35","pista":"\"Seven times he did something very ordinary before opening his eyes.\""},{"pregunta":"What lost object did Elisha make float on the water with a stick he cut and threw in?","opciones":["The iron head of a borrowed axe","A captain's bronze sword","The stone of a hand mill","A steward's golden ring"],"dato":"One of the sons of the prophets lost in the Jordan the axe he had borrowed; Elisha cut down a stick, threw it in at the spot, and made the iron float to the surface, and the man reached out and took it.","cita":"2 Kings 6:6","versiculo":"The man of God asked, \"Where did it fall?\" He showed him the place. He cut down a stick, threw it in there, and made the iron float.","vcita":"2 Kings 6:6","pista":"\"The owner was distressed because the axe was not his — it was borrowed.\""},{"pregunta":"What did Elisha's servant see when Yahweh opened his eyes at Dothan?","opciones":["The mountain full of horses and chariots of fire around Elisha","An army of ten thousand Israelites descending from heaven","The king of Syria fleeing with his army","A wall of fire surrounding his own house"],"dato":"The Syrian army surrounded the city to seize Elisha; the prophet prayed for his terrified servant, and he saw that those with them were far more: the mountain was full of horses and chariots of fire.","cita":"2 Kings 6:17","versiculo":"Elisha prayed, and said, \"Yahweh, please open his eyes, that he may see.\" Yahweh opened the eyes of the young man, and he saw; and behold, the mountain was full of horses and chariots of fire around Elisha.","vcita":"2 Kings 6:17","pista":"\"The prophet had told him: don't be afraid, for those with us are more than those with them.\""},{"pregunta":"What miracle happened when a dead man touched Elisha's bones in his tomb?","opciones":["He revived and stood up on his feet","The tomb opened and light shone from it","The approaching Moabites fled in terror","The earth shook and split the rock"],"dato":"Some Israelites burying a man saw a Moabite raiding band and threw the corpse into Elisha's tomb; as soon as it touched the prophet's bones, the man revived and stood up: God's power kept working even after his servant's death.","cita":"2 Kings 13:21","versiculo":"As they were burying a man, behold, they saw a troop, and cast the man into the tomb of Elisha. As soon as the man touched Elisha's bones, he revived, and stood up on his feet.","vcita":"2 Kings 13:21","pista":"\"The dead man came back to life by simply touching the prophet's bones.\""},{"pregunta":"What did the king of Assyria do with the Israelites after taking Samaria in the ninth year of Hoshea?","opciones":["He carried them away to Assyria and placed them in Halah, on the Habor and in the cities of the Medes","He sold them as slaves to the Phoenicians","He left them in Samaria paying a yearly tribute","He took them captive to Babylon by the river Chebar"],"dato":"So ended the northern kingdom after years of idolatry: Samaria fell and its people were deported to distant lands of Assyria, while foreigners were brought in to inhabit its cities.","cita":"2 Kings 17:6","versiculo":"In the ninth year of Hoshea, the king of Assyria took Samaria, and carried Israel away to Assyria, and placed them in Halah, and on the Habor, the river of Gozan, and in the cities of the Medes.","vcita":"2 Kings 17:6","pista":"\"It was the end of the kingdom of the ten northern tribes.\""},{"pregunta":"How many men of the Assyrian camp did Yahweh's angel strike in a single night, delivering Jerusalem?","opciones":["One hundred eighty-five thousand","Exactly one hundred thousand","Fifty thousand horsemen","Ten thousand of the king's guard"],"dato":"Hezekiah had prayed, spreading Sennacherib's threatening letter before Yahweh; that very night Yahweh's angel went out and struck one hundred eighty-five thousand Assyrians, and the enemy king withdrew to his land in disgrace.","cita":"2 Kings 19:35","versiculo":"That night, Yahweh's angel went out, and struck one hundred eighty-five thousand in the camp of the Assyrians. When men arose early in the morning, behold, these were all dead bodies.","vcita":"2 Kings 19:35","pista":"\"The number is over one hundred eighty thousand, in a single night.\""},{"pregunta":"What sign did Hezekiah receive on the steps of Ahaz as confirmation that he would be healed and live fifteen more years?","opciones":["The shadow went back ten steps","The sun stood still in mid-sky","Rain fell in midsummer over Jerusalem","The Jordan flowed backward for an hour"],"dato":"The king asked for a sign, and Isaiah cried to Yahweh: the shadow that had gone down on the steps of Ahaz went back ten steps, confirming that God would heal him and add fifteen years to his life.","cita":"2 Kings 20:11","versiculo":"Isaiah the prophet cried to Yahweh; and he brought the shadow ten steps backward, by which it had gone down on the steps of Ahaz.","vcita":"2 Kings 20:11","pista":"\"Hezekiah chose the shadow going backward — the harder of the two options.\""},{"pregunta":"What was burned when Jerusalem fell into the hands of the Chaldeans?","opciones":["Yahweh's house, the king's house and all the houses of Jerusalem","Only Zedekiah's palace","Just the gates and walls of the city","The orchards and vineyards round about"],"dato":"Nebuzaradan, captain of Nebuchadnezzar's guard, burned the temple, the royal palace and every great house, broke down the walls and carried off the remnant captive: so ended the kingdom of Judah, as the prophets had announced.","cita":"2 Kings 25:9","versiculo":"He burned Yahweh's house, the king's house, and all the houses of Jerusalem, even every great house, he burned with fire.","vcita":"2 Kings 25:9","pista":"\"With the temple's burning, Judah's kingdom fell too, as the northern one had before.\""}],"1 Chronicles":[{"pregunta":"What did Jabez ask God for in his famous prayer?","opciones":["That God would bless him, enlarge his border, and keep him from evil","Many children and great riches","To be made king over Israel","The destruction of all his enemies"],"dato":"Jabez prayed asking for blessing and protection, and God granted him what he requested.","cita":"1 Chronicles 4:10","versiculo":"Jabez called on the God of Israel, saying, 'Oh that you would bless me indeed, and enlarge my border! May your hand be with me, and may you keep me from evil, that I may not cause pain!' God granted him that which he requested.","vcita":"1 Chronicles 4:10","pista":"«His prayer is one of the most famous in the Bible: it starts by asking for blessing.»"},{"pregunta":"What happened to Uzzah when he touched the ark of God?","opciones":["He died on the spot because of Yahweh's anger","He was blinded for life","He was banished from Israel","He became a priest"],"dato":"Uzzah put out his hand to the ark when the oxen stumbled, and God struck him down right there.","cita":"1 Chronicles 13:10","versiculo":"Yahweh's anger burned against Uzza, and he struck him, because he put his hand on the ark; and he died there before God.","vcita":"1 Chronicles 13:10","pista":"«The ark was not to be touched — not even with good intentions.»"},{"pregunta":"Which three names open the genealogy in 1 Chronicles?","opciones":["Adam, Seth, and Enosh","Noah, Shem, and Ham","Abraham, Isaac, and Jacob","Saul, David, and Solomon"],"dato":"The book opens with the genealogy from Adam, sweeping through the whole history of Israel.","cita":"1 Chronicles 1:1","versiculo":"Adam, Seth, Enosh,","vcita":"1 Chronicles 1:1","pista":"«The first man, his son, and his grandson: that's how the book begins.»"},{"pregunta":"Who moved David to take a census of Israel?","opciones":["Satan","Joab","Saul","Absalom"],"dato":"The census brought grave consequences on Israel, and David acknowledged his sin.","cita":"1 Chronicles 21:1","versiculo":"Satan stood up against Israel, and moved David to take a census of Israel.","vcita":"1 Chronicles 21:1","pista":"«It wasn't a general or a visible enemy who pushed him.»"},{"pregunta":"How much did David pay Ornan for the threshing floor where he built an altar?","opciones":["Six hundred shekels of gold","Fifty shekels of silver","One thousand shekels of gold","Thirty pieces of silver"],"dato":"David refused to offer God something that cost him nothing, and paid the full price.","cita":"1 Chronicles 21:25","versiculo":"So David gave to Ornan six hundred shekels of gold by weight for the place.","vcita":"1 Chronicles 21:25","pista":"«He wouldn't take the land for free: offerings to God should cost something.»"},{"pregunta":"Why did God not allow David to build the temple?","opciones":["Because he had shed much blood in wars","Because he was too old","Because he was not a priest","Because he lived in Jerusalem"],"dato":"The task of building the house fell to Solomon, David's son.","cita":"1 Chronicles 22:8","versiculo":"But Yahweh's word came to me, saying, 'You have shed blood abundantly, and have made great wars. You shall not build a house to my name, because you have shed much blood on the earth in my sight.'","vcita":"1 Chronicles 22:8","pista":"«The warrior prepared everything, but his son would be the builder.»"},{"pregunta":"Who alone were to carry the ark of God, according to David?","opciones":["The Levites","Only the sons of Aaron","David's mighty men","The elders of Israel"],"dato":"After what happened to Uzzah, David ordered that only the Levites should carry the ark.","cita":"1 Chronicles 15:2","versiculo":"Then David said, 'No one ought to carry God's ark but the Levites. For Yahweh has chosen them to carry God's ark, and to minister to him forever.'","vcita":"1 Chronicles 15:2","pista":"«A painful lesson: the ark had its appointed carriers.»"},{"pregunta":"What did David do before going up against the Philistines?","opciones":["He inquired of God","He counted his soldiers","He sent out spies","He offered sacrifices"],"dato":"David sought God's direction before every battle.","cita":"1 Chronicles 14:10","versiculo":"David inquired of God, saying, 'Shall I go up against the Philistines? Will you deliver them into my hand?' Yahweh said to him, 'Go up; for I will deliver them into your hand.'","vcita":"1 Chronicles 14:10","pista":"«Before the sword, the question.»"},{"pregunta":"Why should Yahweh be thanked, according to 1 Chronicles 16:34?","opciones":["Because he is good and his loving kindness endures forever","Because he gives riches to his servants","Because he destroys the enemies","Because he dwells in the temple"],"dato":"David's song of thanksgiving celebrates God's goodness and everlasting mercy.","cita":"1 Chronicles 16:34","versiculo":"Oh give thanks to Yahweh, for he is good, for his loving kindness endures forever.","vcita":"1 Chronicles 16:34","pista":"«Two reasons are enough: his goodness and a mercy that never runs out.»"},{"pregunta":"Who reigned in Israel after David's death?","opciones":["Solomon his son","Joab","Absalom","Nathan"],"dato":"David died in a good old age, full of days, riches, and honor.","cita":"1 Chronicles 29:28","versiculo":"He died in a good old age, full of days, riches, and honor; and Solomon his son reigned in his place.","vcita":"1 Chronicles 29:28","pista":"«The son of promise took the throne in peace.»"},{"pregunta":"Whose sons did David set apart for the music ministry in the temple?","opciones":["The sons of Asaph, Heman, and Jeduthun","The sons of Aaron, Moses, and Joshua","The sons of Judah, Benjamin, and Levi","The sons of Samuel, Nathan, and Gad"],"dato":"The musicians prophesied with harps, stringed instruments, and cymbals.","cita":"1 Chronicles 25:1","versiculo":"Moreover, David and the captains of the army set apart for the service certain of the sons of Asaph, and of Heman, and of Jeduthun, who should prophesy with harps, with stringed instruments, and with cymbals.","vcita":"1 Chronicles 25:1","pista":"«Three families, three worship leaders.»"},{"pregunta":"According to David's prayer in 1 Chronicles 29:12, from whom do riches and honor come?","opciones":["From God, who rules over all","From the king's own effort","From the tribute of the nations","From the mines of Ophir"],"dato":"David acknowledged that everything Israel had came from God's hand.","cita":"1 Chronicles 29:12","versiculo":"Both riches and honor come from you, and you rule over all! In your hand is power and might! It is in your hand to make great, and to give strength to all!","vcita":"1 Chronicles 29:12","pista":"«Neither the crown nor the gold belongs to the king: it all comes from above.»"}],"2 Chronicles":[{"pregunta":"What did Solomon ask God for at the beginning of his reign?","opciones":["Wisdom and knowledge to govern the people","Riches and a long life","Victory over all his enemies","A temple larger than the tabernacle"],"dato":"Solomon didn't ask for wealth or long life, but for wisdom to govern a great people.","cita":"2 Chronicles 1:10","versiculo":"Now give me wisdom and knowledge, that I may go out and come in before this people; for who can judge this your great people?","vcita":"2 Chronicles 1:10","pista":"«What he asked for wasn't for himself, but for his people.»"},{"pregunta":"What kept the priests from ministering at the dedication of the temple?","opciones":["The cloud of Yahweh's glory that filled the house","The smoke of the sacrifice","The multitude singing","A mighty wind"],"dato":"God's glory was revealed in the house, and the priests could not stand to serve.","cita":"2 Chronicles 5:14","versiculo":"so that the priests could not stand to minister by reason of the cloud; for Yahweh's glory filled God's house.","vcita":"2 Chronicles 5:14","pista":"«The temple was so full, the priests couldn't even serve.»"},{"pregunta":"According to 2 Chronicles 7:14, what must the people do for God to heal their land?","opciones":["Humble themselves, pray, seek God's face, and turn from evil","Offer a thousand burnt offerings","Fast for forty days","Rebuild the temple"],"dato":"It is God's promise after the temple dedication: humility and prayer come before forgiveness.","cita":"2 Chronicles 7:14","versiculo":"if my people, who are called by my name, will humble themselves, pray, seek my face, and turn from their wicked ways, then I will hear from heaven, will forgive their sin, and will heal their land.","vcita":"2 Chronicles 7:14","pista":"«Four steps: humility, prayer, seeking, and turning.»"},{"pregunta":"How many talents of gold did the queen of Sheba give Solomon?","opciones":["One hundred twenty talents","Sixty talents","Three hundred talents","One thousand talents"],"dato":"The queen of Sheba arrived with spices and precious stones the like of which had never been seen.","cita":"2 Chronicles 9:9","versiculo":"She gave the king one hundred and twenty talents of gold, spices in great abundance, and precious stones. There was never anything like the spices which the queen of Sheba gave to King Solomon.","vcita":"2 Chronicles 9:9","pista":"«More than a hundred: a gift worthy of Solomon's fame.»"},{"pregunta":"What happened to Israel after Rehoboam's harshness?","opciones":["It rebelled against the house of David","It united with Egypt","It destroyed the temple in Jerusalem","It crowned Rehoboam by force"],"dato":"Rehoboam's harsh answer triggered the division of the kingdom.","cita":"2 Chronicles 10:19","versiculo":"So Israel rebelled against David's house to this day.","vcita":"2 Chronicles 10:19","pista":"«Ten tribes took another road.»"},{"pregunta":"What message did the prophet Azariah give King Asa?","opciones":["To be strong, because his work would be rewarded","To flee to Egypt","To destroy Jerusalem","To take another census of the people"],"dato":"Encouraged by that message, Asa removed the idolatry and repaired Yahweh's altar.","cita":"2 Chronicles 15:7","versiculo":"But as for you, be strong, and don't let your hands be slack; for your work will be rewarded.","vcita":"2 Chronicles 15:7","pista":"«A divine push: don't let your hands go slack.»"},{"pregunta":"Whose battle did God say the war against the great multitude was?","opciones":["God's, not Judah's","King Jehoshaphat's","The Levites'","Moab's and Ammon's"],"dato":"Jehoshaphat only had to witness Yahweh's salvation: the battle was not his.","cita":"2 Chronicles 20:15","versiculo":"Don't be afraid, nor be dismayed by reason of this great multitude; for the battle is not yours, but God's.","vcita":"2 Chronicles 20:15","pista":"«Some wars aren't yours to fight: God fights them.»"},{"pregunta":"What did Jehoshaphat place in front of the army to face the enemy?","opciones":["Singers who praised Yahweh","His best archers","Chariots of war","The ark of the covenant"],"dato":"The singers marched ahead of the army giving thanks to Yahweh, and God set ambushes against the enemies.","cita":"2 Chronicles 20:21","versiculo":"When he had taken counsel with the people, he appointed those who were to sing to Yahweh and give praise in holy array, as they went out before the army, and say, 'Give thanks to Yahweh, for his loving kindness endures forever.'","vcita":"2 Chronicles 20:21","pista":"«Instead of an armed vanguard: a choir.»"},{"pregunta":"How did Hezekiah reign, according to 2 Chronicles 29:2?","opciones":["He did what was right in Yahweh's eyes, like David his father","He worshiped at the high places","He allied himself with Assyria against God","He shut the doors of the temple"],"dato":"Hezekiah opened the doors of Yahweh's house and restored the worship his father had abandoned.","cita":"2 Chronicles 29:2","versiculo":"He did that which was right in Yahweh's eyes, according to all that David his father had done.","vcita":"2 Chronicles 29:2","pista":"«The best praise for a king: like David.»"},{"pregunta":"What did Hezekiah tell the people in the face of Sennacherib's army?","opciones":["That Assyria had an arm of flesh, but God was with Judah","That Jerusalem should surrender","That the people should flee to the desert","That a large tribute should be paid"],"dato":"Hezekiah's words gave the people confidence in the face of the Assyrian threat.","cita":"2 Chronicles 32:8","versiculo":"With him is an arm of flesh, but with us is Yahweh our God to help us and to fight our battles. The people rested themselves on the words of Hezekiah king of Judah.","vcita":"2 Chronicles 32:8","pista":"«Human strength on one side; God on the other.»"},{"pregunta":"At what age did Josiah begin to seek the God of David?","opciones":["At eight years old","At twelve years old","At sixteen years old","At twenty years old"],"dato":"While still a boy, Josiah sought God and later cleansed Judah of idolatry.","cita":"2 Chronicles 34:3","versiculo":"For in the eighth year of his reign, while he was yet young, he began to seek after the God of David his father; and in the twelfth year he began to purge Judah and Jerusalem from the high places, the Asherah poles, the engraved images, and the molten images.","vcita":"2 Chronicles 34:3","pista":"«He didn't wait to grow up to seek God.»"},{"pregunta":"What did Hilkiah the priest find in Yahweh's house in Josiah's days?","opciones":["The book of the law","The ark of the covenant","The temple treasure","The stone tablets of Moses"],"dato":"Finding the book of the law sparked Josiah's great reform.","cita":"2 Chronicles 34:15","versiculo":"Hilkiah answered and said to Shaphan the scribe, 'I have found the book of the law in Yahweh's house.' Hilkiah delivered the book to Shaphan.","vcita":"2 Chronicles 34:15","pista":"«It was lost inside God's own house.»"}],"Ezra":[{"pregunta":"What did Cyrus, king of Persia, invite the Jews to do in his decree?","opciones":["Go up to Jerusalem and build Yahweh's house","Stay in Babylon serving the empire","Build a temple in Persia","Send only the priests back"],"dato":"Cyrus's decree fulfilled Yahweh's word spoken by Jeremiah and opened the return from captivity.","cita":"Ezra 1:3","versiculo":"Whoever there is among you of all his people, may his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of Yahweh, the God of Israel (he is God), which is in Jerusalem.","vcita":"Ezra 1:3","pista":"«A pagan king blew the trumpet of the journey home.»"},{"pregunta":"How many people did the whole assembly that returned from captivity number?","opciones":["Forty-two thousand three hundred sixty","Exactly ten thousand","One hundred thousand people","Twenty-four thousand five hundred"],"dato":"The list in Ezra 2 records families, priests, Levites, and servants who returned with Zerubbabel.","cita":"Ezra 2:64","versiculo":"The whole assembly together was forty-two thousand three hundred sixty,","vcita":"Ezra 2:64","pista":"«More than forty thousand came back as one man.»"},{"pregunta":"How many singers, children of Asaph, were counted among those who returned?","opciones":["One hundred twenty-eight","Two hundred","Seventy-five","Three hundred"],"dato":"Even the singers were counted in the list of the return: praise was coming back to the temple.","cita":"Ezra 2:41","versiculo":"The singers: the children of Asaph, one hundred twenty-eight.","vcita":"Ezra 2:41","pista":"«More than a hundred voices brought the music home.»"},{"pregunta":"What did the people sing when the foundation of the temple was laid?","opciones":["That God is good and his loving kindness endures forever","A new song of war","The song of Moses","The blessing of Aaron"],"dato":"When they saw the foundation laid, all the people shouted with a great shout.","cita":"Ezra 3:11","versiculo":"They sang to one another in praising and giving thanks to Yahweh, 'For he is good, for his loving kindness endures forever toward Israel.' All the people shouted with a great shout, when they praised Yahweh, because the foundation of Yahweh's house was laid.","vcita":"Ezra 3:11","pista":"«It was only the foundation, and the cymbals were already sounding.»"},{"pregunta":"What did the people of the land do to hinder the building of the temple?","opciones":["They weakened the hands of the people and troubled them in building","They stole the materials at night","They burned the foundation","They bribed the king of Persia"],"dato":"The local opposition even managed to halt the work for a time.","cita":"Ezra 4:4","versiculo":"Then the people of the land weakened the hands of the people of Judah, and troubled them in building.","vcita":"Ezra 4:4","pista":"«Discouragement is also used to stop God's works.»"},{"pregunta":"Who began to build God's house when the work resumed?","opciones":["Zerubbabel and Jeshua, encouraged by the prophets","Nehemiah and Ezra","The kings of Persia","The repentant Samaritans"],"dato":"The prophets Haggai and Zechariah spurred the restart of the construction.","cita":"Ezra 5:2","versiculo":"Then rose up Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and began to build God's house which is at Jerusalem; and with them were the prophets of God, helping them.","vcita":"Ezra 5:2","pista":"«A governor and a priest, with prophets at their side.»"},{"pregunta":"Under whose reign was God's house finished?","opciones":["In the reign of Darius, in his sixth year","In the reign of Cyrus","In the twentieth year of Artaxerxes","In the reign of Ahasuerus"],"dato":"The house was finished on the third day of the month Adar, after the decrees of Cyrus, Darius, and Artaxerxes.","cita":"Ezra 6:15","versiculo":"This house was finished on the third day of the month Adar, which was in the sixth year of the reign of Darius the king.","vcita":"Ezra 6:15","pista":"«Three Persian kings signed, but God finished the house.»"},{"pregunta":"How did the building of the temple prosper, according to Ezra 6:14?","opciones":["Through the prophesying of Haggai and Zechariah","Thanks to Egypt's gold","By the army of Persia","With the help of the Samaritans"],"dato":"The elders of the Jews built and prospered under the word of the prophets.","cita":"Ezra 6:14","versiculo":"The elders of the Jews built and prospered, through the prophesying of Haggai the prophet and Zechariah the son of Iddo. They built and finished it, according to the commandment of the God of Israel, and according to the decree of Cyrus, Darius, and Artaxerxes king of Persia.","vcita":"Ezra 6:14","pista":"«Brick by brick, prophecy in hand.»"},{"pregunta":"How does the book describe Ezra when he came up from Babylon?","opciones":["A skilled scribe in the law of Moses","Prince of the priests","Captain of the army","The king's cupbearer"],"dato":"Yahweh's hand was on Ezra, and the king granted him all his request.","cita":"Ezra 7:6","versiculo":"this Ezra went up from Babylon. He was a skilled scribe in the law of Moses, which Yahweh, the God of Israel, had given; and the king granted him all his request, according to Yahweh his God's hand on him.","vcita":"Ezra 7:6","pista":"«An expert in the law with God's hand on him.»"},{"pregunta":"Where did Ezra proclaim a fast to seek a straight way from God?","opciones":["At the river Ahava","In the wilderness of Judah","At the gates of the temple","On Mount Moriah"],"dato":"Ezra was ashamed to ask the king for an escort: the fast was his declaration of trust in God.","cita":"Ezra 8:21","versiculo":"Then I proclaimed a fast there at the river Ahava, that we might humble ourselves before our God, to seek from him a straight way for us, for our little ones, and for all our possessions.","vcita":"Ezra 8:21","pista":"«No armed escort: a fast by the riverbank.»"},{"pregunta":"How did Ezra feel as he prayed for the people's sins?","opciones":["Ashamed and blushing to lift up his face to God","Sure of the people's innocence","Angry with the enemies","Tired from the journey"],"dato":"Ezra confessed that the people's iniquities had increased over his head.","cita":"Ezra 9:6","versiculo":"I said, 'My God, I am ashamed and blush to lift up my face to you, my God; for our iniquities have increased over our head, and our guiltiness has grown up to the heavens.'","vcita":"Ezra 9:6","pista":"«True intercession carries others' sin as its own.»"},{"pregunta":"What hope did Shecaniah point out when the mixed marriages were discovered?","opciones":["That there was still hope for Israel","That the king would annul the law","That the people would return to Babylon","That the temple would be closed"],"dato":"Shecaniah acknowledged the people's trespass and still encouraged Ezra to act.","cita":"Ezra 10:2","versiculo":"Shecaniah the son of Jehiel, one of the sons of Elam, answered Ezra, 'We have trespassed against our God, and have married foreign women of the peoples of the land. Yet now there is hope for Israel concerning this thing.'","vcita":"Ezra 10:2","pista":"«Even in the worst diagnosis, he left a door open.»"}],"Nehemiah":[{"pregunta":"What news did Nehemiah receive about those who had returned to Jerusalem?","opciones":["That they were in great affliction, with the wall broken down","That the temple was already finished","That the king had made them governors","That they had defeated the Samaritans"],"dato":"The report broke Nehemiah's heart: the wall was broken down and the gates burned with fire.","cita":"Nehemiah 1:3","versiculo":"They said to me, 'The remnant who are left of the captivity there in the province are in great affliction and reproach. The wall of Jerusalem also is broken down, and its gates are burned with fire.'","vcita":"Nehemiah 1:3","pista":"«News that produces weeping, not indifference.»"},{"pregunta":"What office did Nehemiah hold at the king's court?","opciones":["Cupbearer to the king","Chief scribe","Captain of the guard","Palace steward"],"dato":"Nehemiah served as cupbearer to King Artaxerxes, yet his heart was in Jerusalem.","cita":"Nehemiah 1:11","versiculo":"Lord, I beg you, let your ear be attentive now to the prayer of your servant, and to the prayer of your servants who delight to fear your name. Please prosper your servant today, and grant him mercy in the sight of this man.' (Now I was cupbearer to the king.)","vcita":"Nehemiah 1:11","pista":"«He served the cup of the most powerful king of the age.»"},{"pregunta":"What did Nehemiah do when the king asked what he requested?","opciones":["He prayed to the God of heaven","He wept before the king","He asked the queen for advice","He stayed silent for a day"],"dato":"His prayer was brief and silent, in the very moment of the conversation with the king.","cita":"Nehemiah 2:4","versiculo":"Then the king said to me, 'What is your request?' So I prayed to the God of heaven.","vcita":"Nehemiah 2:4","pista":"«A lightning-fast prayer between question and answer.»"},{"pregunta":"What did Nehemiah do at night after arriving in Jerusalem?","opciones":["He went out to view the broken walls and burned gates","He called a public assembly","He began building alone","He slept in the temple"],"dato":"Nehemiah secretly inspected the ruin before announcing his plan to the people.","cita":"Nehemiah 2:13","versiculo":"I went out by night by the valley gate, even toward the jackal's well, and to the dung gate, and viewed the walls of Jerusalem, which were broken down, and its gates were consumed with fire.","vcita":"Nehemiah 2:13","pista":"«First, see the wall with your own eyes.»"},{"pregunta":"What did the people answer when Nehemiah told them of God's hand on him?","opciones":["Let's rise up and build!","We must wait another year","We have no materials","Let's go back to Persia"],"dato":"The people strengthened their hands for the good work: the shared vision ignited the task.","cita":"Nehemiah 2:18","versiculo":"I told them of the hand of my God which was good on me, and also of the king's words that he had spoken to me. They said, 'Let's rise up and build!' So they strengthened their hands for the good work.","vcita":"Nehemiah 2:18","pista":"«Four words were enough to move a whole city.»"},{"pregunta":"What did Sanballat, Tobiah, and Geshem do when they heard about the work on the wall?","opciones":["They ridiculed and despised the Jews","They offered their help","They attacked that very night","They wrote to the king in their favor"],"dato":"The enemies accused the Jews of rebelling against the king to try to stop them.","cita":"Nehemiah 2:19","versiculo":"But when Sanballat the Horonite, Tobiah the Ammonite servant, and Geshem the Arabian heard it, they ridiculed us and despised us, and said, 'What is this thing that you are doing? Will you rebel against the king?'","vcita":"Nehemiah 2:19","pista":"«When strength is lacking, mockery abounds.»"},{"pregunta":"Whom did Nehemiah tell the people to remember before the confrontation?","opciones":["The Lord, who is great and awesome","Moses and his staff","David and his army","The walls of Persia"],"dato":"Nehemiah urged the people to fight for their brothers, sons, daughters, wives, and houses.","cita":"Nehemiah 4:14","versiculo":"I looked, and rose up, and said to the nobles, to the rulers, and to the rest of the people, 'Don't be afraid of them! Remember the Lord, who is great and awesome, and fight for your brothers, your sons, your daughters, your wives, and your houses.'","vcita":"Nehemiah 4:14","pista":"«Remembering who God is defeats fear.»"},{"pregunta":"How did those who built the wall work under threat?","opciones":["With one hand on the work and the other holding a weapon","Only at night","Singing psalms without tools","Guarded by Persian soldiers"],"dato":"Every worker loaded and labored without letting go of his weapon: the work advanced under permanent guard.","cita":"Nehemiah 4:17","versiculo":"Those who built the wall, and those who bore burdens, loaded themselves; everyone with one of his hands did the work, and with the other held his weapon.","vcita":"Nehemiah 4:17","pista":"«Trowel in one hand, defense in the other.»"},{"pregunta":"In how many days was the wall of Jerusalem finished?","opciones":["In fifty-two days","In a full year","In one hundred days","In seven months"],"dato":"The wall was finished on the twenty-fifth day of Elul, astonishing the enemies.","cita":"Nehemiah 6:15","versiculo":"So the wall was finished on the twenty-fifth day of Elul, in fifty-two days.","vcita":"Nehemiah 6:15","pista":"«Less than two months to enclose a whole city.»"},{"pregunta":"Where was the book of the law read before all the people?","opciones":["In the square in front of the Water Gate","On the Mount of Olives","In the palace's upper room","At the Valley Gate"],"dato":"Ezra read the law from early morning until midday, and the ears of all the people were attentive.","cita":"Nehemiah 8:3","versiculo":"He read from it before the square that was in front of the Water Gate from early morning until midday, in the presence of the men and the women, and of those who could understand. The ears of all the people were attentive to the book of the law.","vcita":"Nehemiah 8:3","pista":"«Six hours of public reading, and nobody moved.»"},{"pregunta":"According to Nehemiah 8:10, what is the strength of God's people?","opciones":["The joy of Yahweh","The newly built wall","The abundance of food","The army of volunteers"],"dato":"Instead of sorrow over the law they had heard, the people received joy: it was a holy day to their Lord.","cita":"Nehemiah 8:10","versiculo":"Then he said to them, 'Go your way. Eat the fat, drink the sweet, and send portions to those for whom nothing is prepared, for today is holy to our Lord. Don't be grieved, for the joy of Yahweh is your strength.'","vcita":"Nehemiah 8:10","pista":"«Not the wall nor the sword: joy.»"}],"Esther":[{"pregunta":"Why was the king angry with Queen Vashti?","opciones":["Because she refused to come at his command through the eunuchs","Because she arrived late to the banquet","Because she defended the Jews","Because she refused to wear the crown"],"dato":"Vashti refused to appear before the king and his princes, and his anger burned in him.","cita":"Esther 1:12","versiculo":"But the queen Vashti refused to come at the king's commandment by the eunuchs. Therefore the king was very angry, and his anger burned in him.","vcita":"Esther 1:12","pista":"«A refusal in the middle of a banquet changed history.»"},{"pregunta":"What did the king do with Esther when he loved her above the other young women?","opciones":["He set the royal crown on her head and made her queen","He gave her a whole province","He sent her back home","He gave her half the kingdom"],"dato":"Esther obtained favor and kindness in the king's sight more than all the virgins.","cita":"Esther 2:17","versiculo":"The king loved Esther above all the women, and she obtained favor and kindness in his sight more than all the virgins; so he set the royal crown on her head, and made her queen instead of Vashti.","vcita":"Esther 2:17","pista":"«From Jewish orphan to the crown of Persia.»"},{"pregunta":"What did Mordecai NOT do before Haman, despite the king's command?","opciones":["He did not bow down or pay him homage","He did not pay him the tribute","He did not attend the banquets","He did not deliver his letters"],"dato":"Mordecai's refusal filled Haman with wrath and unleashed his plot against all the Jews.","cita":"Esther 3:2","versiculo":"All the king's servants who were in the king's gate bowed down and paid homage to Haman, for the king had so commanded concerning him. But Mordecai didn't bow down or pay him homage.","vcita":"Esther 3:2","pista":"«Only one man stayed standing at the king's gate.»"},{"pregunta":"What did the letters sent by Haman to all the provinces order?","opciones":["To destroy, kill, and exterminate all the Jews in one day","To expel the Jews from the kingdom within a year","To burn the synagogues of every city","To confiscate half of their goods"],"dato":"The appointed day was the thirteenth day of the twelfth month, the month of Adar.","cita":"Esther 3:13","versiculo":"Letters were sent by couriers into all the king's provinces, to destroy, to kill, and to cause to perish, all Jews, both young and old, little children and women, in one day, even on the thirteenth day of the twelfth month, which is the month Adar, and to plunder their possessions.","vcita":"Esther 3:13","pista":"«A decree with a death date for a whole people.»"},{"pregunta":"What famous question did Mordecai ask Esther in his message?","opciones":["Who knows if you haven't come to the kingdom for such a time as this?","Why didn't you tell the king you are a Jew?","Will you come with us to Shushan?","Have you forgotten your people?"],"dato":"Mordecai warned her that if she stayed silent, deliverance would come from another place, but she and her house would perish.","cita":"Esther 4:14","versiculo":"For if you remain silent now, then relief and deliverance will come to the Jews from another place, but you and your father's house will perish. Who knows if you haven't come to the kingdom for such a time as this?","vcita":"Esther 4:14","pista":"«Maybe the crown wasn't a prize, but a mission.»"},{"pregunta":"What words did Esther say before entering the king uninvited?","opciones":["If I perish, I perish","God has abandoned me","Let Mordecai come with me","I will wait one more year"],"dato":"Before risking her life, Esther asked all the Jews of Shushan for three days of fasting.","cita":"Esther 4:16","versiculo":"Go, gather together all the Jews who are present in Shushan, and fast for me, and neither eat nor drink three days, night or day. I and my maidens will also fast the same way. Then I will go in to the king, which is against the law; and if I perish, I perish.","vcita":"Esther 4:16","pista":"«First the fast; then, face the law of the court.»"},{"pregunta":"What did the king do when he saw Esther in the court?","opciones":["He held out the golden scepter in his hand toward her","He ordered her out of the palace","He called the guards","He stood up and withdrew"],"dato":"Holding out the scepter was the sign of pardon: Esther touched its top and her life was spared.","cita":"Esther 5:2","versiculo":"It was so, when the king saw Esther the queen standing in the court, that she obtained favor in his sight; and the king held out to Esther the golden scepter that was in his hand. So Esther came near and touched the top of the scepter.","vcita":"Esther 5:2","pista":"«An extended scepter was worth a life.»"},{"pregunta":"How did Haman, the enemy of the Jews, end?","opciones":["Hanged on the gallows he had prepared for Mordecai","Banished to a distant island","Locked in Shushan's prison","Killed in battle against the Jews"],"dato":"The fifty-cubit gallows Haman raised for Mordecai became his own end.","cita":"Esther 7:10","versiculo":"So they hanged Haman on the gallows that he had prepared for Mordecai. Then the king's wrath was pacified.","vcita":"Esther 7:10","pista":"«The trap he prepared closed on him.»"},{"pregunta":"How were the Jews to celebrate the days of their deliverance, according to Esther 9:22?","opciones":["As days of feasting and gladness, sending portions and gifts to the poor","With fasting and total silence","By burning Haman's letters","By traveling to Jerusalem every year"],"dato":"That is how the feast of Purim was born: from sorrow to gladness, and from mourning into a good day.","cita":"Esther 9:22","versiculo":"as the days in which the Jews had rest from their enemies, the month which was turned to them from sorrow to gladness, and from mourning into a good day; that they should make them days of feasting and gladness, of sending portions to one another, and gifts to the poor.","vcita":"Esther 9:22","pista":"«Joy is celebrated by sharing, also with the poor.»"},{"pregunta":"What place did Mordecai hold in the kingdom at the end of the book?","opciones":["Second only to King Ahasuerus","Governor of Shushan only","High priest of the Jews","Judge over the province of Judah"],"dato":"Mordecai was great among the Jews, seeking the good of his people and speaking peace to all his offspring.","cita":"Esther 10:3","versiculo":"For Mordecai the Jew was next to King Ahasuerus, and great among the Jews, and accepted by the multitude of his brothers, seeking the good of his people, and speaking peace to all his offspring.","vcita":"Esther 10:3","pista":"«From the king's gate to his right hand.»"}],"Job":[{"pregunta":"In what land did Job live, the blameless and upright man who feared God?","opciones":["Uz","Ur of the Chaldeans","The land of Moab","The country of Edom"],"dato":"Job lived in the land of Uz; the Bible presents him as blameless and upright, one who feared God and turned away from evil.","cita":"Job 1:1","versiculo":"There was a man in the land of Uz, whose name was Job. That man was blameless and upright, and one who feared God, and turned away from evil.","vcita":"Job 1:1","pista":"«A short land name: the land of U_.»"},{"pregunta":"How many sons and daughters did Job have at the beginning of his story?","opciones":["Seven sons and three daughters","Three sons and seven daughters","Ten sons and two daughters","Five sons and five daughters"],"dato":"Before the trial, Job had seven sons and three daughters, and was the greatest of all the men of the east.","cita":"Job 1:2","versiculo":"There were born to him seven sons and three daughters.","vcita":"Job 1:2","pista":"«Seven plus three: ten children in all.»"},{"pregunta":"Who presented himself among the sons of God and challenged Job's faithfulness?","opciones":["Satan","The angel Gabriel","A cherub named Azazel","The king of Tyre"],"dato":"One day God's sons came to present themselves before the LORD, and Satan also came among them, accusing Job of serving God only for what he received.","cita":"Job 1:6","versiculo":"Now on the day when God's sons came to present themselves before the LORD, Satan also came among them.","vcita":"Job 1:6","pista":"«The adversary, the accuser of the brothers.»"},{"pregunta":"What did Job say after losing his possessions and his children in a single day?","opciones":["«The LORD gave, and the LORD has taken away; blessed be the LORD's name»","«I curse my fate and stop praying»","«I ask God to take my life»","«God has been unjust to me»"],"dato":"Job fell to the ground, worshiped, and blessed the name of the LORD without charging him with any wrong.","cita":"Job 1:21","versiculo":"He said, “Naked I came out of my mother's womb, and naked will I return there. The LORD gave, and the LORD has taken away. Blessed be the LORD's name.”","vcita":"Job 1:21","pista":"«He neither cursed nor renounced: he blessed.»"},{"pregunta":"What did Job's wife urge him to do when he was sick and ruined?","opciones":["Renounce God and die","Flee to her parents' house","Sell what little was left","Find a priest in Jerusalem"],"dato":"In despair she said, “Do you still maintain your integrity? Renounce God, and die.” Job rebuked her for speaking as a foolish woman speaks.","cita":"Job 2:9","versiculo":"Then his wife said to him, “Do you still maintain your integrity? Renounce God, and die.”","vcita":"Job 2:9","pista":"«A desperate piece of advice that Job rejected at once.»"},{"pregunta":"What was the name of Job's friend who came from Teman?","opciones":["Eliphaz","Bildad","Zophar","Elihu"],"dato":"The three friends were Eliphaz the Temanite, Bildad the Shuhite, and Zophar the Naamathite; they came to sympathize with Job and to comfort him.","cita":"Job 2:11","versiculo":"Now when Job's three friends heard of all this evil that had come on him, they each came from his own place: Eliphaz the Temanite, Bildad the Shuhite, and Zophar the Naamathite; and they made an appointment together to come to sympathize with him and to comfort him.","vcita":"Job 2:11","pista":"«The trio is E-B-Z: the first is Eliphaz.»"},{"pregunta":"Who is the young man who spoke after Job's three friends fell silent?","opciones":["Elihu","Barak","Eliab","Elisha"],"dato":"Elihu, son of Barachel the Buzite, was young and had waited out of respect for the elders; at last he spoke because the friends had failed to answer Job.","cita":"Job 32:6","versiculo":"Elihu the son of Barachel the Buzite answered, “I am young, and you are very old. Therefore I held back, and didn't dare show you my opinion.”","vcita":"Job 32:6","pista":"«The youngest speaker; his father was Barachel.»"},{"pregunta":"Complete Job's confession of faith in the middle of his suffering: “I know that my ______ lives; in the end, he will stand upon the earth.”","opciones":["Redeemer","Defender","Comforter","Savior"],"dato":"At his lowest point, Job confessed that his Redeemer lives and that in the end he would stand upon the earth: one of the great declarations of hope in the Old Testament.","cita":"Job 19:25","versiculo":"But as for me, I know that my Redeemer lives. In the end, he will stand upon the earth.","vcita":"Job 19:25","pista":"«The title of the one who rescues us: our R…»"},{"pregunta":"According to Job 28, what is wisdom?","opciones":["The fear of the Lord","Knowing all science","Living many years","Finding gold and silver in the earth"],"dato":"After searching for wisdom like a hidden treasure, Job concludes that it cannot be bought with gold: the fear of the Lord is wisdom, and to depart from evil is understanding.","cita":"Job 28:28","versiculo":"To man he said, ‘Behold, the fear of the Lord, that is wisdom. To depart from evil is understanding.’","vcita":"Job 28:28","pista":"«Not in the mines: in the heart that fears God.»"},{"pregunta":"From where did the LORD answer Job when he finally spoke to him?","opciones":["Out of a whirlwind","From a cloud on Mount Sinai","From the temple sanctuary","In a dream at night"],"dato":"After chapters of silence, the LORD answered Job out of the whirlwind, showing him his greatness in creation.","cita":"Job 38:1","versiculo":"Then the LORD answered Job out of the whirlwind, and said:","vcita":"Job 38:1","pista":"«God spoke from the whirling wind, not from a temple.»"},{"pregunta":"What mighty creature does God describe in Job 41, impossible to draw out with a fish hook?","opciones":["Leviathan","Behemoth","The unicorn","The serpent of Eden"],"dato":"God describes Leviathan, a creature of impenetrable scales, to show Job that some things are far beyond his strength and his judgment.","cita":"Job 41:1","versiculo":"Can you draw out Leviathan with a fish hook, or press down his tongue with a cord?","vcita":"Job 41:1","pista":"«The creature of chapter 41, with impenetrable scales.»"},{"pregunta":"How much did God give back to Job at the end of his trial, after he prayed for his friends?","opciones":["Twice as much as he had before","Exactly the same amount","Ten times more","Only his health, without possessions"],"dato":"When Job prayed for his friends, the LORD restored his prosperity and gave him twice as much as he had before; and he lived one hundred forty more years.","cita":"Job 42:10","versiculo":"The LORD restored Job's prosperity when he prayed for his friends. The LORD gave Job twice as much as he had before.","vcita":"Job 42:10","pista":"«Not the same, nor half: twice as much!»"}],"Psalms":[{"pregunta":"Whom does Psalm 1, the first of the psalms, call “blessed”?","opciones":["The man who doesn't walk in the counsel of the wicked","The king who wins the battle","The priest who offers sacrifices","The rich and powerful man"],"dato":"The book of Psalms opens by calling blessed the one who doesn't follow the counsel of the wicked nor sit with scoffers, but delights in the law of the LORD.","cita":"Psalms 1:1","versiculo":"Blessed is the man who doesn't walk in the counsel of the wicked, nor stand on the path of sinners, nor sit in the seat of scoffers;","vcita":"Psalms 1:1","pista":"«The man who does not sit with scoffers.»"},{"pregunta":"What declares the glory of God, according to Psalm 19?","opciones":["The heavens","The mountains","The rivers","The falling stars"],"dato":"David says the heavens declare the glory of God and the expanse shows his handiwork: all creation speaks of its Maker.","cita":"Psalms 19:1","versiculo":"The heavens declare the glory of God. The expanse shows his handiwork.","vcita":"Psalms 19:1","pista":"«Look up on a clear night.»"},{"pregunta":"Complete Psalm 23: “The LORD is my ______; I shall lack nothing.”","opciones":["shepherd","king","shield","judge"],"dato":"David compares the LORD to a shepherd who guides, feeds, and protects his sheep: with him, nothing is lacking.","cita":"Psalms 23:1","versiculo":"The LORD is my shepherd; I shall lack nothing.","vcita":"Psalms 23:1","pista":"«The one who guides the sheep: the s…»"},{"pregunta":"In the valley of the shadow of death, which two things of the shepherd comfort the psalmist?","opciones":["His rod and his staff","His cloak and his sandal","His sling and his bag","His trumpet and his harp"],"dato":"The rod defends against danger and the staff guides and rescues the sheep; so, even in the darkest valley, the psalmist fears no evil.","cita":"Psalms 23:4","versiculo":"Even though I walk through the valley of the shadow of death, I will fear no evil, for you are with me. Your rod and your staff, they comfort me.","vcita":"Psalms 23:4","pista":"«One defends and one guides: rod and s…»"},{"pregunta":"Complete Psalm 46: “God is our refuge and ______, a very present help in trouble.”","opciones":["strength","hope","joy","song"],"dato":"This psalm of the sons of Korah confesses that God is refuge and strength: a help always present in the middle of trouble.","cita":"Psalms 46:1","versiculo":"God is our refuge and strength, a very present help in trouble.","vcita":"Psalms 46:1","pista":"«Refuge and s…: God's might.»"},{"pregunta":"What does David ask of God in Psalm 51, after acknowledging his sin?","opciones":["To create in him a clean heart","To be made invisible to his enemies","To get his kingdom back at once","To erase everyone's memory"],"dato":"Repentant, David prays: “Create in me a clean heart, O God. Renew a right spirit within me.” It is the great psalm of repentance.","cita":"Psalms 51:10","versiculo":"Create in me a clean heart, O God. Renew a right spirit within me.","vcita":"Psalms 51:10","pista":"«A new clean heart, not a new kingdom.»"},{"pregunta":"With what should we enter God's gates, according to Psalm 100?","opciones":["With thanksgiving","With offerings of gold","In absolute silence","With drums and weapons"],"dato":"Psalm 100 invites us to enter his gates with thanksgiving and his courts with praise, blessing his name.","cita":"Psalms 100:4","versiculo":"Enter into his gates with thanksgiving, and into his courts with praise. Give thanks to him, and bless his name.","vcita":"Psalms 100:4","pista":"«You enter giving thanks, not tiptoeing.»"},{"pregunta":"Complete Psalm 118: “This is the day that the LORD has made. We will ______ and be glad in it!”","opciones":["rejoice","rest","mourn","hide"],"dato":"The psalmist celebrates the day the LORD has made as a gift to rejoice and be glad in.","cita":"Psalms 118:24","versiculo":"This is the day that the LORD has made. We will rejoice and be glad in it!","vcita":"Psalms 118:24","pista":"«We will r… in it: pure joy.»"},{"pregunta":"Where does the psalmist's help come from in Psalm 121?","opciones":["From the LORD, who made heaven and earth","From the high mountains","From Israel's army","From travelers on the road"],"dato":"The psalmist lifts his eyes to the hills and answers: his help comes from the LORD, the Maker of heaven and earth.","cita":"Psalms 121:2","versiculo":"My help comes from the LORD, who made heaven and earth.","vcita":"Psalms 121:2","pista":"«Not from the hills: from the Maker of the hills.»"},{"pregunta":"Complete Psalm 122: “I was glad when they said to me, ‘Let's go to the LORD's ______!’”","opciones":["house","mountain","city","tent"],"dato":"It is the joy of the pilgrim going up to Jerusalem: “Let's go to the LORD's house!”","cita":"Psalms 122:1","versiculo":"I was glad when they said to me, “Let's go to the LORD's house!”","vcita":"Psalms 122:1","pista":"«Let's go to the LORD's h…!»"}],"Proverbs":[{"pregunta":"What is the beginning of wisdom, according to Proverbs?","opciones":["The fear of the LORD","Much reading","Long experience","The counsel of the rich"],"dato":"Proverbs opens by affirming that the fear of the LORD is the beginning of knowledge, and that the foolish despise wisdom and instruction.","cita":"Proverbs 1:7","versiculo":"The fear of the LORD is the beginning of knowledge, but the foolish despise wisdom and instruction.","vcita":"Proverbs 1:7","pista":"«Everything starts with the fear of the LORD.»"},{"pregunta":"On what should you NOT lean, according to Proverbs 3:5?","opciones":["On your own understanding","On your father's counsel","On the teaching of the wise","On the strength of your friends"],"dato":"The instruction is to trust in the LORD with all your heart and not lean on your own understanding, acknowledging him in all your ways.","cita":"Proverbs 3:5","versiculo":"Trust in the LORD with all your heart, and don't lean on your own understanding.","vcita":"Proverbs 3:5","pista":"«Not on your understanding: trust in the LORD.»"},{"pregunta":"Complete the proverb: “Keep your ______ with all diligence, for out of it is the wellspring of life.”","opciones":["heart","treasure","word","house"],"dato":"The heart is the wellspring of life: from it flow our decisions and character, so it must be guarded above all things.","cita":"Proverbs 4:23","versiculo":"Keep your heart with all diligence, for out of it is the wellspring of life.","vcita":"Proverbs 4:23","pista":"«Keep your h…: life springs from it.»"},{"pregunta":"To what creature does Proverbs send the sluggard to learn wisdom?","opciones":["The ant","The bee","The ox","The dove"],"dato":"The ant, having no captain or ruler, prepares her food in the summer: an example of diligence for the lazy.","cita":"Proverbs 6:6","versiculo":"Go to the ant, you sluggard. Consider her ways, and be wise;","vcita":"Proverbs 6:6","pista":"«She works without a boss, preparing for summer.»"},{"pregunta":"What covers all wrongs, according to Proverbs 10?","opciones":["Love","Silence","Forgetfulness","Money"],"dato":"Hatred stirs up strife, but love covers all wrongs instead of exposing them.","cita":"Proverbs 10:12","versiculo":"Hatred stirs up strife, but love covers all wrongs.","vcita":"Proverbs 10:12","pista":"«The opposite of hatred that stirs up strife.»"},{"pregunta":"What turns away wrath, according to Proverbs 15?","opciones":["A gentle answer","A louder shout","A threat","Proud silence"],"dato":"A gentle answer turns away wrath, but a harsh word stirs up anger: meekness puts out the fire of conflict.","cita":"Proverbs 15:1","versiculo":"A gentle answer turns away wrath, but a harsh word stirs up anger.","vcita":"Proverbs 15:1","pista":"«A gentle answer, not a harsh word.»"},{"pregunta":"What goes before destruction and a fall, according to Proverbs 16?","opciones":["Pride and an arrogant spirit","Poverty","Sickness","Old age"],"dato":"Pride goes before destruction, and an arrogant spirit before a fall: pride announces ruin.","cita":"Proverbs 16:18","versiculo":"Pride goes before destruction, and an arrogant spirit before a fall.","vcita":"Proverbs 16:18","pista":"«Pride first… then the fall.»"},{"pregunta":"Complete the proverb: “A ______ loves at all times; and a brother is born for adversity.”","opciones":["friend","neighbor","king","servant"],"dato":"A friend loves at all times, not only in prosperity; and a brother proves his worth in adversity.","cita":"Proverbs 17:17","versiculo":"A friend loves at all times; and a brother is born for adversity.","vcita":"Proverbs 17:17","pista":"«The one who loves at all times: the f…»"},{"pregunta":"To what is the LORD's name compared in Proverbs 18?","opciones":["A strong tower","A flowing river","A rock in the desert","A bronze shield"],"dato":"The LORD's name is a strong tower: the righteous run to him and are safe, like someone taking refuge in a fortress.","cita":"Proverbs 18:10","versiculo":"The LORD's name is a strong tower: the righteous run to him, and are safe.","vcita":"Proverbs 18:10","pista":"«The righteous run to it like a fortress.»"},{"pregunta":"Complete the proverb: “Train up a ______ in the way he should go, and when he is old he will not depart from it.”","opciones":["child","disciple","nation","apprentice"],"dato":"Early training sets the course of a life: train up a child in the way he should go, and even when he is old he will not depart from it.","cita":"Proverbs 22:6","versiculo":"Train up a child in the way he should go, and when he is old he will not depart from it.","vcita":"Proverbs 22:6","pista":"«Train up a c… in his way, from childhood.»"},{"pregunta":"With what is iron sharpened, according to Proverbs 27?","opciones":["With iron","With stone","With fire","With water"],"dato":"Iron sharpens iron; so a man sharpens his friend's countenance: friends make each other better.","cita":"Proverbs 27:17","versiculo":"Iron sharpens iron; so a man sharpens his friend's countenance.","vcita":"Proverbs 27:17","pista":"«Iron with i… sharpens.»"},{"pregunta":"The value of the worthy woman of Proverbs 31 is far above…","opciones":["Rubies","Fine gold","Pearls of the sea","The treasures of Egypt"],"dato":"The final chapter of Proverbs describes the worthy, God-fearing woman: her value is far above rubies.","cita":"Proverbs 31:10","versiculo":"Who can find a worthy woman? For her value is far above rubies.","vcita":"Proverbs 31:10","pista":"«Far above rubies.»"}],"Ecclesiastes":[{"pregunta":"What does the author of Ecclesiastes call himself, the son of David and king in Jerusalem?","opciones":["The Preacher","The Prophet","The Singer","The Scribe"],"dato":"The book opens with the words of the Preacher, the son of David, king in Jerusalem: traditionally Solomon reflecting on the meaning of life.","cita":"Ecclesiastes 1:1","versiculo":"The words of the Preacher, the son of David, king in Jerusalem:","vcita":"Ecclesiastes 1:1","pista":"«He calls himself 'the P…'.»"},{"pregunta":"What phrase does the Preacher repeat as he opens his discourse?","opciones":["Vanity of vanities; all is vanity","Time flies and never returns","Eat, drink, and be merry","Remember your Creator"],"dato":"“Vanity of vanities” is the heartbeat of the whole book: without God, every human effort is a vapor that vanishes.","cita":"Ecclesiastes 1:2","versiculo":"“Vanity of vanities,” says the Preacher; “Vanity of vanities, all is vanity.”","vcita":"Ecclesiastes 1:2","pista":"«All is v…: his signature phrase.»"},{"pregunta":"Complete Ecclesiastes 1: “…and there is no ______ thing under the sun.”","opciones":["new","eternal","hidden","perfect"],"dato":"That which has been is that which shall be; what has been done is what shall be done: human history turns in circles under the sun.","cita":"Ecclesiastes 1:9","versiculo":"That which has been is that which shall be, and that which has been done is that which shall be done; and there is no new thing under the sun.","vcita":"Ecclesiastes 1:9","pista":"«No n… thing under the sun.»"},{"pregunta":"Complete Ecclesiastes 3: “For everything there is a season, and a ______ for every purpose under heaven.”","opciones":["time","prize","owner","end"],"dato":"The famous poem of the seasons: everything under heaven has its season and its appointed moment.","cita":"Ecclesiastes 3:1","versiculo":"For everything there is a season, and a time for every purpose under heaven:","vcita":"Ecclesiastes 3:1","pista":"«Everything has its t…»"},{"pregunta":"According to the poem of Ecclesiastes 3, there is “a time to be born, and a time to ______.”","opciones":["die","plant","weep","keep silence"],"dato":"The poem walks through life in pairs: a time to be born and a time to die, a time to plant and a time to pluck up what is planted.","cita":"Ecclesiastes 3:2","versiculo":"a time to be born, and a time to die; a time to plant, and a time to pluck up that which is planted;","vcita":"Ecclesiastes 3:2","pista":"«To be born… and to d…: life's pair.»"},{"pregunta":"Complete Ecclesiastes 4: “______ are better than one, because they have a good reward for their labor.”","opciones":["Two","Three","Many","Ten"],"dato":"Two are better than one: they help each other up and defend one another; companionship multiplies the reward of labor.","cita":"Ecclesiastes 4:9","versiculo":"Two are better than one, because they have a good reward for their labor.","vcita":"Ecclesiastes 4:9","pista":"«T… are better than one.»"},{"pregunta":"What is not quickly broken, according to Ecclesiastes 4?","opciones":["A threefold cord","An iron chain","A linen rope","A warrior's bow"],"dato":"If one is overpowered, two shall withstand him; and a threefold cord is not quickly broken: a picture of the strength of unity.","cita":"Ecclesiastes 4:12","versiculo":"If a man prevails against one who is alone, two shall withstand him; and a threefold cord is not quickly broken.","vcita":"Ecclesiastes 4:12","pista":"«Threefold: almost impossible to break.»"},{"pregunta":"What is better than fine perfume, according to Ecclesiastes 7?","opciones":["A good name","Much gold","A long life","A beautiful palace"],"dato":"A good name is better than fine perfume: a good reputation perfumes a whole life and remains even after death.","cita":"Ecclesiastes 7:1","versiculo":"A good name is better than fine perfume; and the day of death better than the day of one's birth.","vcita":"Ecclesiastes 7:1","pista":"«A good n… is better than perfume.»"},{"pregunta":"How should we do whatever our hand finds to do, according to Ecclesiastes 9?","opciones":["With all our might","Slowly and without effort","Only if there are witnesses","Waiting for a better time"],"dato":"Whatever your hand finds to do, do it with your might, for in Sheol there is no work, nor plan, nor knowledge, nor wisdom.","cita":"Ecclesiastes 9:10","versiculo":"Whatever your hand finds to do, do it with your might; for there is no work, nor plan, nor knowledge, nor wisdom, in Sheol, where you are going.","vcita":"Ecclesiastes 9:10","pista":"«Do it with your m…: with all your strength.»"},{"pregunta":"Whom should we remember in the days of our youth, according to Ecclesiastes 12?","opciones":["Our Creator","Only our parents","The feast days","Our enemies"],"dato":"The final counsel to the young: remember your Creator in the days of your youth, before the evil days come.","cita":"Ecclesiastes 12:1","versiculo":"Remember also your Creator in the days of your youth, before the evil days come, and the years draw near, when you will say, “I have no pleasure in them.”","vcita":"Ecclesiastes 12:1","pista":"«Your C…: remember him in your youth.»"},{"pregunta":"What is the conclusion of the whole matter in Ecclesiastes?","opciones":["Fear God and keep his commandments","Enjoy life without thinking at all","Seek riches and honor","Withdraw from everyone"],"dato":"This is the end of the matter: fear God and keep his commandments, for this is the whole duty of man.","cita":"Ecclesiastes 12:13","versiculo":"This is the end of the matter. All has been heard. Fear God and keep his commandments; for this is the whole duty of man.","vcita":"Ecclesiastes 12:13","pista":"«Fear God and keep his c…»"}],"Song of Solomon":[{"pregunta":"To whom is the Song of Songs, “the song of songs,” attributed?","opciones":["Solomon","David","Asaph","Moses"],"dato":"The book presents itself as Solomon's Song of songs: the most beautiful of songs, devoted to love.","cita":"Song of Solomon 1:1","versiculo":"The Song of songs, which is Solomon's.","vcita":"Song of Solomon 1:1","pista":"«The wise king, David's son.»"},{"pregunta":"How does the beloved describe herself in Song of Solomon 1?","opciones":["I am dark, but lovely","Fair as the full moon","Golden as ripe wheat","Tall as the palm trees"],"dato":"The beloved says to the daughters of Jerusalem: “I am dark, but lovely,” like the tents of Kedar and the curtains of Solomon.","cita":"Song of Solomon 1:5","versiculo":"I am dark, but lovely, you daughters of Jerusalem, like Kedar's tents, like Solomon's curtains.","vcita":"Song of Solomon 1:5","pista":"«Dark… but lovely.»"},{"pregunta":"How is the beloved described in Song of Solomon 2:1?","opciones":["A rose of Sharon, a lily of the valleys","A dove in the clefts of the rock","A tower of ivory","The morning star"],"dato":"“I am a rose of Sharon, a lily of the valleys”: the beloved presents herself with the simple beauty of the flowers of the field.","cita":"Song of Solomon 2:1","versiculo":"I am a rose of Sharon, a lily of the valleys.","vcita":"Song of Solomon 2:1","pista":"«A rose of Sharon and a lily.»"},{"pregunta":"What must not be stirred up or awakened “until it so desires,” in the refrain of the Song?","opciones":["Love","The king","The maidens","The winter"],"dato":"Three times the refrain returns: “Do not stir up nor awaken love, until it so desires”: love has its own time.","cita":"Song of Solomon 2:7","versiculo":"I adjure you, daughters of Jerusalem, by the roes, or by the hinds of the field, that you not stir up, nor awaken love, until it so desires.","vcita":"Song of Solomon 2:7","pista":"«Do not awaken l… until it desires.»"},{"pregunta":"What has already passed, according to the beloved when he invites his love to come away in Song 2?","opciones":["The winter","The night","The harvest","The exile"],"dato":"“Behold, the winter is past, the rain is over and gone”: spring has come, the time of singing and flowers.","cita":"Song of Solomon 2:11","versiculo":"For behold, the winter is past. The rain is over and gone.","vcita":"Song of Solomon 2:11","pista":"«The w… is past: spring has come.»"},{"pregunta":"What little animals spoil the vineyards in blossom, in Song of Solomon 2?","opciones":["The little foxes","The locusts","The ravens","The ants"],"dato":"“Catch for us the foxes, the little foxes that spoil the vineyards”: small neglects ruin a blossoming love.","cita":"Song of Solomon 2:15","versiculo":"Catch for us the foxes, the little foxes that plunder the vineyards; for our vineyards are in blossom.","vcita":"Song of Solomon 2:15","pista":"«Little f…: small but harmful.»"},{"pregunta":"Complete Song of Solomon 2: “My beloved is mine, and I am ______; he browses among the lilies.”","opciones":["his","free","his servant","his crown"],"dato":"It is the declaration of mutual belonging: “My beloved is mine, and I am his,” while he browses among the lilies.","cita":"Song of Solomon 2:16","versiculo":"My beloved is mine, and I am his. He browses among the lilies.","vcita":"Song of Solomon 2:16","pista":"«My beloved is mine, and I am h…»"},{"pregunta":"Whom did the beloved seek on her bed at night, and not find?","opciones":["Him whom her soul loves","Her younger brother","The king in his palace","The watchmen of the city"],"dato":"“By night on my bed I sought him whom my soul loves. I sought him, but I didn't find him”; then she rose to seek him through the city.","cita":"Song of Solomon 3:1","versiculo":"By night on my bed, I sought him whom my soul loves. I sought him, but I didn't find him.","vcita":"Song of Solomon 3:1","pista":"«Him whom her s… loves.»"},{"pregunta":"What does the beloved declare about his love in Song of Solomon 4:7?","opciones":["You are all beautiful; there is no spot in you","You are strong as an army","You are wise as a queen","You are tall as the cedars"],"dato":"The beloved beholds her entirely: “You are all beautiful, my love. There is no spot in you.”","cita":"Song of Solomon 4:7","versiculo":"You are all beautiful, my love. There is no spot in you.","vcita":"Song of Solomon 4:7","pista":"«No spot: all b…»"},{"pregunta":"What does the beloved call his love, unique to him, in Song of Solomon 6?","opciones":["My dove, my perfect one","My rose, my star","My tower, my shield","My vineyard, my garden"],"dato":"Among queens and concubines, only one is his dove and his perfect one, her mother's only daughter, and all call her blessed.","cita":"Song of Solomon 6:9","versiculo":"My dove, my perfect one, is unique. She is her mother's only daughter. She is the favorite one of her who bore her.","vcita":"Song of Solomon 6:9","pista":"«My dove, my p… one.»"},{"pregunta":"As what does the beloved ask to be set on her beloved's heart and arm?","opciones":["As a seal","As a jewel","As a crown","As a golden ring"],"dato":"“Set me as a seal on your heart, as a seal on your arm; for love is strong as death.”","cita":"Song of Solomon 8:6","versiculo":"Set me as a seal on your heart, as a seal on your arm; for love is strong as death. Jealousy is as cruel as Sheol. Its flashes are flashes of fire, a very flame of the LORD.","vcita":"Song of Solomon 8:6","pista":"«As a s… on the heart.»"},{"pregunta":"What can't many waters quench, according to Song of Solomon 8?","opciones":["Love","Faith","Hope","Joy"],"dato":"Many waters can't quench love, neither can floods drown it: true love cannot be bought or destroyed.","cita":"Song of Solomon 8:7","versiculo":"Many waters can't quench love, neither can floods drown it.","vcita":"Song of Solomon 8:7","pista":"«Floods can't drown it: l…»"}],"Isaiah":[{"pregunta":"What did the seraph use to touch Isaiah's lips and take away his guilt in the temple vision?","opciones":["A burning coal taken from the altar","Ashes mixed with holy water","A hot stone from the incense censer","The hem of his robe"],"dato":"One of the seraphim flew to Isaiah with a live coal in his hand, taken with tongs from the altar, and touching his mouth declared his iniquity taken away.","cita":"Isaiah 6:6–7","versiculo":"He touched my mouth with it, and said, “Behold, this has touched your lips; and your iniquity is taken away, and your sin forgiven.”","vcita":"Isaiah 6:7","pista":"\"It came flying from the altar, held with tongs.\""},{"pregunta":"According to Isaiah 7, what name would be given to the son born of the virgin?","opciones":["Immanuel","Maher Shalal Hash Baz","Prince of Peace","Lo-Ammi"],"dato":"The sign given to king Ahaz: the virgin would conceive and bear a son called Immanuel, which means “God with us.”","cita":"Isaiah 7:14","versiculo":"Therefore the Lord himself will give you a sign. Behold, the virgin will conceive, and bear a son, and shall call his name Immanuel.","vcita":"Isaiah 7:14","pista":"\"His name means: God with us.\""},{"pregunta":"What did God command Isaiah to name the son born to him and the prophetess?","opciones":["Maher Shalal Hash Baz","Shear-Jashub","Immanuel","Jezreel"],"dato":"The name was a prophetic sign: Maher Shalal Hash Baz means “the spoil hurries, the prey speeds,” announcing the soon fall of Damascus and Samaria.","cita":"Isaiah 8:3","versiculo":"I went to the prophetess, and she conceived, and bore a son. Then the LORD said to me, “Call his name ‘Maher Shalal Hash Baz.’","vcita":"Isaiah 8:3","pista":"\"Almost a tongue-twister: it speaks of plunder in a hurry.\""},{"pregunta":"Which of these titles did Isaiah give to the child to be born, in chapter 9?","opciones":["Prince of Peace","King of kings","Good Shepherd","Bright Morning Star"],"dato":"Wonderful Counselor, Mighty God, Everlasting Father, and Prince of Peace: the titles of the child of Isaiah 9, whose government and peace would have no end.","cita":"Isaiah 9:6","versiculo":"For a child is born to us. A son is given to us; and the government will be on his shoulders. His name will be called Wonderful Counselor, Mighty God, Everlasting Father, Prince of Peace.","vcita":"Isaiah 9:6","pista":"\"His rule brings what the world seeks most: it ends in peace.\""},{"pregunta":"In the taunt of Isaiah 14, against whom is the saying of the “shining one, son of the dawn” who fell from heaven directed?","opciones":["Against the king of Babylon","Against Pharaoh of Egypt","Against the king of Tyre","Against Sennacherib of Assyria"],"dato":"Chapter 14 is a prophetic taunt against the king of Babylon: the “shining one” who wanted to rise above the stars of God. Tradition has also read it as a figure of Satan's fall.","cita":"Isaiah 14:12","versiculo":"How you have fallen from heaven, shining one, son of the dawn! How you are cut down to the ground, who laid the nations low!","vcita":"Isaiah 14:12","pista":"\"The chapter begins: “you will take up this proverb against the king of…”\""},{"pregunta":"How many years did God add to king Hezekiah's life after his tearful prayer?","opciones":["Fifteen years","Ten years","Seven years","Twenty years"],"dato":"Hezekiah became sick to death, prayed and wept bitterly; God added fifteen years to his life and gave as a sign that the shadow on the steps would go back ten steps.","cita":"Isaiah 38:5","versiculo":"“Go, and tell Hezekiah, ‘The LORD, the God of David your father, says, “I have heard your prayer. I have seen your tears. Behold, I will add fifteen years to your life.","vcita":"Isaiah 38:5","pista":"\"The shadow went back ten steps; the years were ten plus five.\""},{"pregunta":"According to Isaiah 40, like what birds will those who wait for the LORD mount up with wings?","opciones":["Like eagles","Like doves","Like ravens","Like swallows"],"dato":"Those who wait for the LORD will renew their strength: they will run and not be weary; they will walk and not faint.","cita":"Isaiah 40:31","versiculo":"but those who wait for the LORD will renew their strength. They will mount up with wings like eagles. They will run, and not be weary. They will walk, and not faint.","vcita":"Isaiah 40:31","pista":"\"The bird that soars highest, barely flapping its wings.\""}],"Jeremiah":[{"pregunta":"What did God do when he called Jeremiah, to give authority to his word?","opciones":["He touched his mouth and put his words in it","He gave him a scroll to eat","He anointed him with oil before the elders","He gave him an iron rod"],"dato":"Jeremiah excused himself saying he was only a youth and could not speak; the LORD stretched out his hand, touched his mouth, and put his words in it.","cita":"Jeremiah 1:9","versiculo":"Then the LORD stretched out his hand and touched my mouth. Then the LORD said to me, “Behold, I have put my words in your mouth.","vcita":"Jeremiah 1:9","pista":"\"The prophet kept saying: “I don't know how to speak, I am too young.”\""},{"pregunta":"What was the first thing Jeremiah saw in a vision at the start of his ministry?","opciones":["A branch of an almond tree","A flowering olive branch","A fig tree with two baskets","A scroll written on both sides"],"dato":"God showed him a branch of an almond tree and explained the wordplay: “You have seen well; for I watch over my word to perform it.”","cita":"Jeremiah 1:11","versiculo":"Moreover the LORD’s word came to me, saying, “Jeremiah, what do you see?” I said, “I see a branch of an almond tree.”","vcita":"Jeremiah 1:11","pista":"\"The tree that blossoms first, as if “watching” over the word.\""},{"pregunta":"To whose house did God send Jeremiah to teach him the lesson of the spoiled clay made over again?","opciones":["To the potter's house","To the blacksmith's house","To the weaver's house","To the scribe's house"],"dato":"On the potter's wheel, the clay vessel was spoiled and he made it again into another vessel: so is Israel in God's hand, says the LORD.","cita":"Jeremiah 18:3","versiculo":"Then I went down to the potter’s house, and behold, he was making something on the wheels.","vcita":"Jeremiah 18:3","pista":"\"He works with clay and a turning wheel.\""},{"pregunta":"For how much silver did Jeremiah buy his cousin Hanamel's field in Anathoth, while Jerusalem was under siege?","opciones":["Seventeen shekels of silver","Thirty pieces of silver","Ten shekels of gold","One hundred shekels of silver"],"dato":"Confined in the court of the guard, with the city about to fall, Jeremiah bought the field as a sign that “houses and fields shall again be bought in this land.”","cita":"Jeremiah 32:9","versiculo":"I bought the field that was in Anathoth of Hanamel my uncle’s son, and weighed him the money, even seventeen shekels of silver.","vcita":"Jeremiah 32:9","pista":"\"Ten plus seven: weighed on the scales, coin by coin.\""},{"pregunta":"What did the Rechabites refuse to do, because of the command their ancestor Jonadab had left them?","opciones":["Drink wine, they and their children, forever","Eat bread during the siege of the city","Live inside Jerusalem","Cut their hair like the Nazirites"],"dato":"For generations the Rechabites obeyed Jonadab son of Rechab: they drank no wine, sowed no seed, and built no houses. God set them as an example against Judah's disobedience.","cita":"Jeremiah 35:6","versiculo":"But they said, “We will drink no wine; for Jonadab the son of Rechab, our father, commanded us, saying, ‘You shall drink no wine, neither you nor your children, forever.","vcita":"Jeremiah 35:6","pista":"\"Not one cup — neither they nor their children, for generations.\""},{"pregunta":"Who wrote on a scroll, at Jeremiah's dictation, the words that king Jehoiakim later burned piece by piece?","opciones":["Baruch, the son of Neriah","Gemariah, the son of Shaphan","Elishama, the king's scribe","Pashhur, the priest"],"dato":"Baruch wrote from Jeremiah's mouth and read the scroll in the temple. The king cut it with a penknife and threw it into the fire, but Jeremiah dictated another scroll with even more words.","cita":"Jeremiah 36:4","versiculo":"Then Jeremiah called Baruch the son of Neriah; and Baruch wrote from the mouth of Jeremiah all the LORD’s words, which he had spoken to him, on a scroll of a book.","vcita":"Jeremiah 36:4","pista":"\"The faithful secretary of the weeping prophet.\""},{"pregunta":"Who pleaded with king Zedekiah and got Jeremiah pulled out of the cistern where he was sinking in the mud?","opciones":["Ebedmelech the Ethiopian","Baruch, the son of Neriah","Gedaliah, the governor","Hanamel, the prophet's cousin"],"dato":"Ebedmelech, an Ethiopian eunuch of the king's house, spoke up for Jeremiah and returned with thirty men and old rags to lift him out of the cistern without hurting him.","cita":"Jeremiah 38:7","versiculo":"Now when Ebedmelech the Ethiopian, a eunuch, who was in the king’s house, heard that they had put Jeremiah in the dungeon (the king was then sitting in Benjamin’s gate),","vcita":"Jeremiah 38:7","pista":"\"A foreigner at court, whose name starts with E.\""},{"pregunta":"The promise “thoughts of peace, and not of evil, to give you hope and a future” was in a letter from Jeremiah addressed to whom?","opciones":["To the Israelites already exiled in Babylon","To the priests remaining in Jerusalem","To king Hezekiah and his court","To the Jews who had fled to Egypt"],"dato":"Jeremiah wrote from Jerusalem to the captives Nebuchadnezzar had carried to Babylon, telling them to build houses, plant gardens, and seek the peace of the city.","cita":"Jeremiah 29:11","versiculo":"For I know the thoughts that I think toward you,” says the LORD, “thoughts of peace, and not of evil, to give you hope and a future.","vcita":"Jeremiah 29:11","pista":"\"The recipients already lived far away, by the rivers of Babylon.\""}],"Lamentations":[{"pregunta":"How does the first poem describe Jerusalem, the city that once was full of people?","opciones":["As a widow, sitting solitary","As a queen crowned with gold","As a bride waiting for her husband","As a dove without a nest"],"dato":"“She who was great among the nations has become as a widow”: the crowded city was left alone and made a slave after falling to Babylon.","cita":"Lamentations 1:1","versiculo":"How the city sits solitary, that was full of people! She has become as a widow, who was great among the nations! She who was a princess among the provinces has become a slave!","vcita":"Lamentations 1:1","pista":"\"Left alone, like one who lost her husband.\""},{"pregunta":"“Look, and see if there is any sorrow like…” — what does the grieving city ask all who pass by?","opciones":["If there is any sorrow like her sorrow","If there is any city richer than she was","If anyone remembers her glory","If God has already forgiven her"],"dato":"The lament of Lamentations 1 presents Jerusalem speaking in the first person, with no one to comfort her, on the day of the LORD's fierce anger.","cita":"Lamentations 1:12","versiculo":"“Is it nothing to you, all you who pass by? Look, and see if there is any sorrow like my sorrow, which is brought on me, with which the LORD has afflicted me in the day of his fierce anger.","vcita":"Lamentations 1:12","pista":"\"She compares her suffering and finds none equal.\""},{"pregunta":"Who were swooning in the streets of the city, according to the weeping of chapter 2?","opciones":["The young children and the infants","The elders and the widows","The priests and the Levites","The soldiers wounded on the wall"],"dato":"The prophet says his eyes failed with tears over the destruction of his people: even the little children fainted from hunger in the streets.","cita":"Lamentations 2:11","versiculo":"My eyes fail with tears. My heart is troubled. My bile is poured on the earth, because of the destruction of the daughter of my people, because the young children and the infants swoon in the streets of the city.","vcita":"Lamentations 2:11","pista":"\"The smallest ones, still nursing at the breast.\""},{"pregunta":"Chapter 3 is a triple acrostic — each letter of the Hebrew alphabet opens three verses — and is the longest in the book. How many verses does it have?","opciones":["66 verses","22 verses","44 verses","50 verses"],"dato":"Almost all of Lamentations is arranged by the 22 Hebrew letters; chapter 3 goes through them three times: 22 × 3 = 66 verses, and right at its center stand the book's most famous words of hope.","cita":"Lamentations 3:1","versiculo":"I am the man who has seen affliction by the rod of his wrath.","vcita":"Lamentations 3:1","pista":"\"Twenty-two letters times three rounds: do the math.\""},{"pregunta":"According to Lamentations 3, what is “great” and new every morning?","opciones":["The LORD's faithfulness","The patience of the besieged","The number of the survivors","The rebuilt wall"],"dato":"In the center of the saddest book of the Bible shines this confession: the LORD's mercies never fail; they are new every morning, and great is his faithfulness.","cita":"Lamentations 3:23","versiculo":"They are new every morning. Great is your faithfulness.","vcita":"Lamentations 3:23","pista":"\"It starts with N: new every morning.\""},{"pregunta":"“The LORD is my portion, says my soul; therefore I will hope in him.” What does the prophet say the LORD is to him?","opciones":["His portion, his share and inheritance","His judge and his executioner","His crown of gold","His memory and his forgetting"],"dato":"In the middle of the ruin, the prophet declares that the LORD himself is his portion — his inheritance — and therefore he puts his hope in him.","cita":"Lamentations 3:24","versiculo":"“The LORD is my portion,” says my soul. “Therefore I will hope in him.”","vcita":"Lamentations 3:24","pista":"\"His share, his lot — not things, but God himself.\""},{"pregunta":"According to chapter 3, what is it “good” to do while waiting for the salvation of the LORD?","opciones":["To wait quietly, in silence","To cry out against the enemies day and night","To take revenge on those who destroyed the city","To abandon the land and flee"],"dato":"“It is good that a man should hope and quietly wait”: quiet hope replaces desperate lament.","cita":"Lamentations 3:26","versiculo":"It is good that a man should hope and quietly wait for the salvation of the LORD.","vcita":"Lamentations 3:26","pista":"\"No noise, no claims: just wait.\""},{"pregunta":"What does the prophet invite his people to do in the midst of mourning, in Lamentations 3:40?","opciones":["To search and try their ways, and turn again to the LORD","To count the dead of the city","To swear revenge against Babylon","To stop singing forever"],"dato":"The way out of the lament is repentance: examine our ways, search, and turn back to the LORD, lifting heart and hands to God.","cita":"Lamentations 3:40","versiculo":"Let us search and try our ways, and turn again to the LORD.","vcita":"Lamentations 3:40","pista":"\"First look inside, then go back.\""},{"pregunta":"To what are the precious sons of Zion compared after the fall, according to chapter 4?","opciones":["To earthen pitchers, the work of a potter's hands","To burned wooden cups","To rolling stones on the road","To worthless bronze jars"],"dato":"The sons of Zion, valued more than fine gold, came to be esteemed as clay jars: the fall completely changed their honor.","cita":"Lamentations 4:2","versiculo":"The precious sons of Zion, comparable to fine gold, how they are esteemed as earthen pitchers, the work of the hands of the potter!","vcita":"Lamentations 4:2","pista":"\"From worth more than gold, to fragile as baked clay.\""},{"pregunta":"What does the final poem affirm “remains forever,” from generation to generation?","opciones":["The LORD and his throne","The temple of Solomon","The wall of Jerusalem","The kingdom of David's house"],"dato":"Though everything else fell, the book ends looking upward: “You, LORD, remain forever. Your throne is from generation to generation.”","cita":"Lamentations 5:19","versiculo":"You, LORD, remain forever. Your throne is from generation to generation.","vcita":"Lamentations 5:19","pista":"\"The city fell; the throne above did not.\""},{"pregunta":"What is the petition with which the book closes its final prayer?","opciones":["“Turn us to yourself, LORD, and we will be turned”","“Destroy our enemies forever”","“Forget our sins and look away”","“Give us back the kingdom this very year”"],"dato":"The last chapter is a prayer: it asks God to turn them back to himself and renew their days as of old, acknowledging that only God can restore them.","cita":"Lamentations 5:21","versiculo":"Turn us to yourself, LORD, and we will be turned. Renew our days as of old.","vcita":"Lamentations 5:21","pista":"\"They do not ask for things: they ask to come back themselves.\""}],"Ezekiel":[{"pregunta":"What four faces did the living creatures have in Ezekiel's first vision by the river Chebar?","opciones":["Of a man, a lion, an ox, and an eagle","Of a man, a lion, a horse, and a dove","Of a lion, an ox, a serpent, and an eagle","Of a man, a bull, an eagle, and a winged cherub"],"dato":"Each living creature had four faces and four wings, beside wheels full of eyes: the vision of the glory of the LORD that called Ezekiel among the exiles in Babylon.","cita":"Ezekiel 1:10","versiculo":"As for the likeness of their faces, they had the face of a man. The four of them had the face of a lion on the right side. The four of them had the face of an ox on the left side. The four of them also had the face of an eagle.","vcita":"Ezekiel 1:10","pista":"\"A king of the wild, a king of the field, and a king of the sky join the man.\""},{"pregunta":"What did the scroll that God told Ezekiel to eat taste like?","opciones":["As sweet as honey","Bitter as gall","Sour as vinegar","Dry as dust"],"dato":"The scroll was written on front and back with lamentations, mourning, and woe; yet in the prophet's mouth it was as sweet as honey.","cita":"Ezekiel 3:3","versiculo":"He said to me, “Son of man, eat this scroll that I give you and fill your belly and your bowels with it.” Then I ate it. It was as sweet as honey in my mouth.","vcita":"Ezekiel 3:3","pista":"\"Full of laments, but it tasted like a honeycomb.\""},{"pregunta":"With what office did God commission Ezekiel over the house of Israel?","opciones":["Watchman, the sentinel who warns of danger","High priest of the temple","Chief scribe of the king","Captain of Jerusalem's guard"],"dato":"As a watchman, Ezekiel had to hear the word from God's mouth and warn the people: if he failed to warn the wicked, their blood would be required at his hand.","cita":"Ezekiel 3:17","versiculo":"“Son of man, I have made you a watchman to the house of Israel. Therefore hear the word from my mouth, and warn them from me.","vcita":"Ezekiel 3:17","pista":"\"The one who watches from the tower and sounds the alarm.\""},{"pregunta":"For how many days did Ezekiel lie on his left side, symbolically bearing the iniquity of Israel?","opciones":["390 days","40 days","300 days","430 days"],"dato":"God turned the years of Israel's iniquity into days for the prophet: 390 on his left side for Israel, and then 40 for Judah.","cita":"Ezekiel 4:5","versiculo":"For I have appointed the years of their iniquity to be to you a number of days, even three hundred ninety days. So you shall bear the iniquity of the house of Israel.","vcita":"Ezekiel 4:5","pista":"\"Almost thirteen months: three hundred plus ninety. The 40 were for Judah.\""},{"pregunta":"Who was to receive the mark on the forehead, to be protected from the judgment on Jerusalem?","opciones":["The men who sighed and cried over the city's abominations","All the priests and Levites","The children under seven years old","Those who offered a sacrifice that morning"],"dato":"Before the destroyers went out, a man with a scribe's inkhorn marked the foreheads of those who grieved over the city's sin: only they would be spared.","cita":"Ezekiel 9:4","versiculo":"The LORD said to him, “Go through the middle of the city, through the middle of Jerusalem, and set a mark on the foreheads of the men that sigh and that cry over all the abominations that are done within it.”","vcita":"Ezekiel 9:4","pista":"\"Not the powerful: those who wept over others' sin.\""},{"pregunta":"What did God announce he would suddenly take from Ezekiel, forbidding him to mourn publicly?","opciones":["The desire of his eyes: his wife","His firstborn son","His house by the river Chebar","The scroll of his prophecies"],"dato":"Ezekiel's wife died in the evening, and in the morning he did as commanded, without weeping or covering himself: it was a sign to Israel that God would profane the sanctuary, the desire of their eyes, and they would not be able to mourn.","cita":"Ezekiel 24:16","versiculo":"“Son of man, behold, I will take away from you the desire of your eyes with one stroke; yet you shall neither mourn nor weep, neither shall your tears run down.","vcita":"Ezekiel 24:16","pista":"\"The dearest person he had at home.\""},{"pregunta":"In the chapter against the false shepherds, what does God himself promise to do with the lost and the broken sheep?","opciones":["Seek the lost and bind up the broken","Leave it until it learns to return alone","Hand it over to other human shepherds","Mark it and separate it from the flock"],"dato":"Israel's shepherds fed themselves; so God announces that he himself will seek the lost, bring back the strayed, bind up the broken, and strengthen the sick.","cita":"Ezekiel 34:16","versiculo":"“I will seek that which was lost, and will bring back that which was driven away, and will bind up that which was broken, and will strengthen that which was sick; but I will destroy the fat and the strong. I will feed them in justice.”","vcita":"Ezekiel 34:16","pista":"\"The true Shepherd works the shift the others skipped.\""},{"pregunta":"What heart does God promise to take away, and what heart to give, in Ezekiel 36?","opciones":["He takes the heart of stone and gives a heart of flesh","He takes the heart of flesh and gives one of stone","He takes the heart of clay and gives one of gold","He takes the child's heart and gives an elder's"],"dato":"Together with the new heart, God promises to put his Spirit within his people and sprinkle clean water on them: the great promise of renewal in Ezekiel 36.","cita":"Ezekiel 36:26","versiculo":"I will also give you a new heart, and I will put a new spirit within you. I will take away the stony heart out of your flesh, and I will give you a heart of flesh.","vcita":"Ezekiel 36:26","pista":"\"Out with the hard and unfeeling; in with one alive that feels.\""},{"pregunta":"What does Ezekiel 18 teach, against the saying that children pay for their fathers' sins?","opciones":["The soul who sins shall die: each one answers for his own sin","Children always pay for their fathers","The righteous automatically save their whole house","Sin is inherited for three generations"],"dato":"Israel kept repeating: “The fathers have eaten sour grapes, and the children's teeth are set on edge.” God answers that all souls are his, and the son shall not bear the father's iniquity.","cita":"Ezekiel 18:20","versiculo":"The soul who sins, he shall die. The son shall not bear the iniquity of the father, neither shall the father bear the iniquity of the son. The righteousness of the righteous shall be on him, and the wickedness of the wicked shall be on him.","vcita":"Ezekiel 18:20","pista":"\"No inherited guilt: personal accounts.\""},{"pregunta":"What happens wherever the river flowing from the sanctuary reaches, in the vision of chapter 47?","opciones":["Everything lives: even the waters of the sea are healed","The waters dry up and leave salt","The river splits into seven dry branches","The fish die in the current"],"dato":"The stream rising under the temple threshold grows into a river too deep to cross; where it enters, the sea is healed and filled with fish, and on its banks grow trees whose leaves are for healing.","cita":"Ezekiel 47:9","versiculo":"It will happen that every living creature which swarms, in every place where the rivers come, will live. Then there will be a very great multitude of fish; for these waters have come there, and the waters of the sea will be healed, and everything will live wherever the river comes.","vcita":"Ezekiel 47:9","pista":"\"It reaches the Dead Sea… and brings it to life.\""}],"Daniel":[{"pregunta":"What new name did the prince of the eunuchs give Daniel in Babylon?","opciones":["Belteshazzar","Shadrach","Meshach","Abednego"],"dato":"The four Hebrew youths were given new names: Daniel received Belteshazzar; Hananiah, Shadrach; Mishael, Meshach; and Azariah, Abednego.","cita":"Daniel 1:7","versiculo":"The prince of the eunuchs gave names to them: to Daniel he gave the name Belteshazzar; to Hananiah, Shadrach; to Mishael, Meshach; and to Azariah, Abednego.","vcita":"Daniel 1:7","pista":"\"His starts with B, much like a king of Babylon's name.\""},{"pregunta":"What diet did Daniel request for himself and his friends in the ten-day test at the palace?","opciones":["Vegetables to eat and water to drink","Only unleavened bread and fruit","Fish and honey once a day","The king's food, but eaten fasting"],"dato":"Daniel resolved not to defile himself with the king's food: ten days of vegetables and water. In the end, their appearance was better and fatter than that of all the other youths.","cita":"Daniel 1:12","versiculo":"“Test your servants, I beg you, ten days; and let them give us vegetables to eat and water to drink.","vcita":"Daniel 1:12","pista":"\"Nothing from the king's table: simple garden food and clear water.\""},{"pregunta":"Which part of the great statue in Nebuchadnezzar's dream represented the king himself, according to Daniel?","opciones":["The head of gold","The breast of silver","The belly of bronze","The feet of iron and clay"],"dato":"Daniel told him face to face: “You are the head of gold.” The statue announced a succession of kingdoms, each metal less valuable than the one before.","cita":"Daniel 2:38","versiculo":"Wherever the children of men dwell, he has given the animals of the field and the birds of the sky into your hand, and has made you rule over them all. You are the head of gold.","vcita":"Daniel 2:38","pista":"\"The most valuable metal, at the very top of the statue.\""},{"pregunta":"When Nebuchadnezzar looked into the fiery furnace, how did he describe the fourth man walking with the three youths?","opciones":["Like a son of the gods","Like an ancient of days seated on a throne","Like an angel with a sword of fire","Like a fourth prisoner crying for help"],"dato":"Only three men had been thrown bound into the furnace, but the king saw four, loose and unharmed; so he called Shadrach, Meshach, and Abednego out and blessed their God.","cita":"Daniel 3:25","versiculo":"He answered, “Look, I see four men loose, walking in the middle of the fire, and they are unharmed. The appearance of the fourth is like a son of the gods.”","vcita":"Daniel 3:25","pista":"\"They threw in three… and the king counted four.\""},{"pregunta":"In the vision of the ram and the male goat, what king does the male goat represent, according to Gabriel's explanation?","opciones":["The king of Greece","The king of Persia","The king of Babylon","The king of Egypt"],"dato":"The two-horned ram was the kings of Media and Persia, and the male goat that struck it down was the kingdom of Greece, whose great horn would be its first king.","cita":"Daniel 8:21","versiculo":"The rough male goat is the king of Greece. The great horn that is between his eyes is the first king.","vcita":"Daniel 8:21","pista":"\"In Hebrew his name is Javan — Greece.\""}],"Hosea":[{"pregunta":"What was the name of the woman God told Hosea to marry as a sign to Israel?","opciones":["Gomer","Jezebel","Athaliah","Vashti"],"dato":"God told Hosea to marry Gomer, the daughter of Diblaim, as a living sign of Israel's unfaithfulness and of God's persistent love.","cita":"Hosea 1:2–3","versiculo":"So he went and took Gomer the daughter of Diblaim; and she conceived, and bore him a son.","vcita":"Hosea 1:3","pista":"\"Her story is in the first chapter; her husband had to go and bring her back.\""},{"pregunta":"What name did Hosea give his first son, at God's command?","opciones":["Jezreel","Lo-Ammi","Maher-Shalal-Hash-Baz","Shear-Jashub"],"dato":"The firstborn was named Jezreel: God announced he would punish the house of Jehu for the blood shed at Jezreel and bring the kingdom of Israel to an end.","cita":"Hosea 1:4","versiculo":"The LORD said to him, “Call his name Jezreel, for yet a little while, and I will avenge the blood of Jezreel on the house of Jehu, and will cause the kingdom of the house of Israel to cease.","vcita":"Hosea 1:4","pista":"\"He bears the name of a valley famous for Israel's battles.\""},{"pregunta":"What does the name \"Lo-Ammi,\" which Hosea gave his third child, mean?","opciones":["\"Not my people\"","\"Not pitied\"","\"God sows\"","\"The Lord judges\""],"dato":"\"Lo-Ammi\" literally means \"not my people\": it was God's sentence on Israel, which had broken the covenant. His sister was named Lo-Ruhamah, \"not pitied.\"","cita":"Hosea 1:9","versiculo":"He said, “Call his name Lo-Ammi, for you are not my people, and I will not be yours.","vcita":"Hosea 1:9","pista":"\"The name is a Hebrew sentence denying the relationship between God and his people.\""},{"pregunta":"With what did Hosea buy back his unfaithful wife, as a picture of Israel's rescue?","opciones":["Fifteen pieces of silver and barley","Thirty pieces of silver","A talent of gold","One hundred lambs"],"dato":"Hosea bought her for fifteen pieces of silver and a homer and a half of barley: a picture of how God rescues his unfaithful people by paying the price.","cita":"Hosea 3:2","versiculo":"So I bought her for myself for fifteen pieces of silver and a homer and a half of barley.","vcita":"Hosea 3:2","pista":"\"He paid half in coins and half in grain, like the price of a slave.\""},{"pregunta":"According to Hosea 4, why were God's people destroyed?","opciones":["For lack of knowledge","Because they lost a war","Because they had no king","Because they stopped offering sacrifices"],"dato":"\"My people are destroyed for lack of knowledge\": the people rejected the knowledge of God, and the priests forgot his law.","cita":"Hosea 4:6","versiculo":"My people are destroyed for lack of knowledge. Because you have rejected knowledge, I will also reject you, that you may be no priest to me. Because you have forgotten your God’s law, I will also forget your children.","vcita":"Hosea 4:6","pista":"\"The problem was not a lack of rituals, but of knowing God.\""},{"pregunta":"What does God say he desires, according to Hosea 6:6?","opciones":["Mercy, and not sacrifice","Fasts, and not feasts","Silence, and not prayers","Justice from kings, and not worship"],"dato":"\"For I desire mercy, and not sacrifice; and the knowledge of God more than burnt offerings\": Jesus quoted this sentence twice in the Gospels.","cita":"Hosea 6:6","versiculo":"For I desire mercy, and not sacrifice; and the knowledge of God more than burnt offerings.","vcita":"Hosea 6:6","pista":"\"Jesus repeats it in Matthew: Go and learn what this means.\""},{"pregunta":"Which valley does God promise to turn into a \"door of hope\" for Israel?","opciones":["The valley of Achor","The valley of Jezreel","The valley of Hebron","The Jordan valley"],"dato":"The valley of Achor, scene of Achan's disobedience in Joshua's day, will become a door of hope: the place of judgment will become the place of a new beginning.","cita":"Hosea 2:15","versiculo":"I will give her vineyards from there, and the valley of Achor for a door of hope; and she will respond there as in the days of her youth, and as in the day when she came up out of the land of Egypt.","vcita":"Hosea 2:15","pista":"\"It is the same valley where Achan was punished in the book of Joshua.\""},{"pregunta":"According to Hosea, on what terms will God betroth his people to himself forever?","opciones":["In righteousness, justice and compassion","In power, wealth and glory","In silence and fear","In burnt offerings and sacrifices"],"dato":"God promises an everlasting betrothal founded on righteousness and compassion, not on past unfaithfulness: a new covenant of faithful love.","cita":"Hosea 2:19","versiculo":"I will betroth you to me forever. Yes, I will betroth you to me in righteousness, in justice, in loving kindness, and in compassion.","vcita":"Hosea 2:19","pista":"\"It is like a new wedding after unfaithfulness: the ring is righteousness and mercy.\""},{"pregunta":"To what animal does Hosea compare Ephraim, wandering without understanding between Egypt and Assyria?","opciones":["A silly dove","A young lion","A lost sheep","A wild donkey"],"dato":"Ephraim, like an easily deceived dove without understanding, called to Egypt and went to Assyria looking for help instead of returning to God.","cita":"Hosea 7:11","versiculo":"Ephraim is like an easily deceived dove, without understanding. They call to Egypt. They go to Assyria.","vcita":"Hosea 7:11","pista":"\"It flutters from one side to the other, seeking help from the wrong empires.\""},{"pregunta":"What moving question does God ask, unable to give Ephraim up, in Hosea 11?","opciones":["\"How can I give you up, Ephraim?\"","\"Where are you, Ephraim?\"","\"Who is like you, Ephraim?\"","\"How long, Ephraim?\""],"dato":"Though Israel deserved judgment, God's heart turns within him: \"My heart is turned within me, my compassion is aroused.\"","cita":"Hosea 11:8","versiculo":"How can I give you up, Ephraim? How can I hand you over, Israel? How can I make you like Admah? How can I make you like Zeboiim? My heart is turned within me, my compassion is aroused.","vcita":"Hosea 11:8","pista":"\"It is the lament of a father who cannot bring himself to let go of his son.\""},{"pregunta":"What does God promise to do with his people's waywardness in Hosea's final chapter?","opciones":["Heal it and love them freely","Forget it if they pay tribute","Punish it with eternal exile","Hide it from the nations"],"dato":"The book closes with hope: \"I will heal their waywardness. I will love them freely; for my anger is turned away from them.\"","cita":"Hosea 14:4","versiculo":"I will heal their waywardness. I will love them freely; for my anger is turned away from them.","vcita":"Hosea 14:4","pista":"\"God presents himself as the physician of his people's apostasy.\""}],"Joel":[{"pregunta":"Who was the father of the prophet Joel?","opciones":["Pethuel","Amittai","Beeri","Buzi"],"dato":"The book begins this way: \"The LORD's word that came to Joel, the son of Pethuel.\" Joel's own name means \"the LORD is God.\"","cita":"Joel 1:1","versiculo":"The LORD’s word that came to Joel, the son of Pethuel.","vcita":"Joel 1:1","pista":"\"His name opens the book: Joel, son of…\""},{"pregunta":"According to Joel 1:4, what plague devoured the land in stages, leaving everything stripped bare?","opciones":["The locust in its stages","Hail","Drought","Fire"],"dato":"What the swarming locust left, the great locust ate; what that left, the grasshopper ate; and what that left, the caterpillar ate: an invasion in waves that left the land naked.","cita":"Joel 1:4","versiculo":"What the swarming locust has left, the great locust has eaten. What the great locust has left, the grasshopper has eaten. What the grasshopper has left, the caterpillar has eaten.","vcita":"Joel 1:4","pista":"\"Four names of insects, one single catastrophe for Judah's fields.\""},{"pregunta":"How does Joel announce the day of the LORD in his first chapter?","opciones":["It is at hand, and comes as destruction from the Almighty","It is far off, a thousand years away","It already passed in Moses' time","It is hidden, and no one will know it"],"dato":"\"Alas for the day! For the day of the LORD is at hand\": Joel repeats that the day of the LORD is great, terrible, and at the door.","cita":"Joel 1:15","versiculo":"Alas for the day! For the day of the LORD is at hand, and it will come as destruction from the Almighty.","vcita":"Joel 1:15","pista":"\"It is not a warning for a remote future: Joel says you can already hear it coming.\""},{"pregunta":"What does Joel command the people to tear in order to return to God, instead of their garments?","opciones":["Their heart","Their nets","The temple veil","The books of the law"],"dato":"\"Tear your heart and not your garments\": God does not want outward signs of mourning, but true and deep repentance.","cita":"Joel 2:13","versiculo":"Tear your heart and not your garments, and turn to the LORD, your God; for he is gracious and merciful, slow to anger, and abundant in loving kindness, and relents from sending calamity.","vcita":"Joel 2:13","pista":"\"Tearing garments was a custom of mourning; Joel asks for something unseen.\""},{"pregunta":"What had to be blown in Zion to sanctify a fast and call a solemn assembly, according to Joel?","opciones":["The trumpet","The harp","The cymbals","The temple bell"],"dato":"\"Blow the trumpet in Zion! Sanctify a fast. Call a solemn assembly\": facing the day of the LORD, the whole people had to gather in a solemn fast.","cita":"Joel 2:15","versiculo":"Blow the trumpet in Zion! Sanctify a fast. Call a solemn assembly.","vcita":"Joel 2:15","pista":"\"It was the sound of alarm and of gathering in Israel.\""},{"pregunta":"What does God promise to restore to his people after the locust plague?","opciones":["The years that the locust has eaten","The lost cities","The ark of the covenant","The stolen tithes"],"dato":"God promises to give back the lost years: \"I will restore to you the years that the swarming locust has eaten… my great army, which I sent among you.\"","cita":"Joel 2:25","versiculo":"I will restore to you the years that the swarming locust has eaten, the great locust, the grasshopper, and the caterpillar, my great army, which I sent among you.","vcita":"Joel 2:25","pista":"\"God does not only pardon the future: he also redeems lost time.\""},{"pregunta":"What does God promise to pour out \"on all flesh\" in Joel's prophecy, fulfilled at Pentecost?","opciones":["His Spirit","The early rain","Fiery judgment","Anointing oil"],"dato":"Peter quoted Joel 2 on the day of Pentecost: sons and daughters will prophesy, old men will dream dreams, and young men will see visions.","cita":"Joel 2:28","versiculo":"It will happen afterward, that I will pour out my Spirit on all flesh; and your sons and your daughters will prophesy. Your old men will dream dreams. Your young men will see visions.","vcita":"Joel 2:28","pista":"\"Acts chapter 2 explains it: This is what was spoken by the prophet Joel.\""},{"pregunta":"According to Joel, what signs in the sun and the moon will announce the great and terrible day of the LORD?","opciones":["The sun will turn to darkness and the moon to blood","The sun will stand still and the moon will shine by day","The sun will fall and the moon will split","A bow will appear in the clouds"],"dato":"Before the great and terrible day of the LORD comes, there will be wonders: the sun turned to darkness and the moon to blood, as Peter also quoted.","cita":"Joel 2:31","versiculo":"The sun will be turned into darkness, and the moon into blood, before the great and terrible day of the LORD comes.","vcita":"Joel 2:31","pista":"\"They are the heavenly signs that go before the day of the LORD.\""},{"pregunta":"According to Joel 2:32, who will be saved?","opciones":["Whoever will call on the LORD's name","Only the priests","Whoever offers the most sacrifices","Whoever climbs Mount Zion armed"],"dato":"\"Whoever will call on the LORD's name shall be saved\": Paul quotes this promise in Romans 10:13, open to everyone who believes.","cita":"Joel 2:32","versiculo":"It will happen that whoever will call on the LORD’s name shall be saved; for in Mount Zion and in Jerusalem there will be those who escape, as the LORD has said, and among the remnant, those whom the LORD calls.","vcita":"Joel 2:32","pista":"\"It is the same sentence Paul uses in Romans 10.\""},{"pregunta":"In Joel 3:10, into what must the nations beat their plowshares, preparing for judgment?","opciones":["Into swords","Into plows","Into shields","Into trumpets"],"dato":"The reverse of Isaiah and Micah: here the nations are summoned to the war of judgment: \"Beat your plowshares into swords, and your pruning hooks into spears. Let the weak say, 'I am strong.'\"","cita":"Joel 3:10","versiculo":"Beat your plowshares into swords, and your pruning hooks into spears. Let the weak say, ‘I am strong.’","vcita":"Joel 3:10","pista":"\"It is the reverse order of turning swords into plowshares.\""},{"pregunta":"Up to which valley will the nations come to be judged by God, according to Joel?","opciones":["The valley of Jehoshaphat","The valley of Jezreel","The valley of Eshcol","The valley of Shittim"],"dato":"In the valley of Jehoshaphat —which means \"the LORD judges\"— God will sit to judge all the nations that divided his land and oppressed his people.","cita":"Joel 3:12","versiculo":"Let the nations arouse themselves, and come up to the valley of Jehoshaphat; for there I will sit to judge all the surrounding nations.","vcita":"Joel 3:12","pista":"\"The valley's name means: the LORD has judged.\""}],"Amos":[{"pregunta":"Two years before what event did Amos date the message he saw concerning Israel?","opciones":["The earthquake","The Assyrian invasion","The death of King Uzziah","An eclipse of the sun"],"dato":"Amos dates his words \"in the days of Uzziah king of Judah and in the days of Jeroboam the son of Joash, king of Israel, two years before the earthquake,\" a quake still remembered centuries later.","cita":"Amos 1:1","versiculo":"The words of Amos, who was among the herdsmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah and in the days of Jeroboam the son of Joash, king of Israel, two years before the earthquake.","vcita":"Amos 1:1","pista":"\"Zechariah still mentions it as the great quake of Uzziah's days.\""},{"pregunta":"According to Amos, for what miserable price did they sell the needy in Israel?","opciones":["For a pair of sandals","For a shekel of silver","For a field of barley","For a measure of wheat"],"dato":"Judgment falls because \"they have sold the righteous for silver, and the needy for a pair of sandals\": a needy person's life was worth less than footwear.","cita":"Amos 2:6","versiculo":"The LORD says: “For three transgressions of Israel, yes, for four, I will not turn away its punishment, because they have sold the righteous for silver, and the needy for a pair of sandals;","vcita":"Amos 2:6","pista":"\"A rich man's footwear was worth more than a poor man's freedom.\""},{"pregunta":"What rhetorical question opens the cause-and-effect sayings of Amos 3?","opciones":["\"Do two walk together, unless they have agreed?\"","\"What does the LORD require of you?\"","\"Where does my help come from?\"","\"Who is wise and will keep these things?\""],"dato":"Amos strings together common-sense questions: nothing happens without a cause, and if the prophet announces judgment, it is because judgment is truly coming.","cita":"Amos 3:3","versiculo":"Do two walk together, unless they have agreed?","vcita":"Amos 3:3","pista":"\"It is about walking in agreement: two people, one same step.\""},{"pregunta":"With what solemn call does God end his warning to Israel in Amos 4?","opciones":["\"Prepare to meet your God\"","\"Return to your land\"","\"Offer tithes at Bethel\"","\"Be silent before the Lord\""],"dato":"Since the punishments did not turn the people back, God concludes: \"Prepare to meet your God, Israel,\" a call to give an account.","cita":"Amos 4:12","versiculo":"Therefore I will do this to you, Israel; because I will do this to you, prepare to meet your God, Israel.","vcita":"Amos 4:12","pista":"\"Five times before, God said: Yet you haven't returned to me.\""},{"pregunta":"What does Amos say the day of the LORD will be for those who desire it without repenting?","opciones":["Darkness, and not light","Joy and feasting","Rest from their enemies","The day of their crowning"],"dato":"\"Woe to you who desire the day of the LORD!\": for impenitent Israel it will not be light but darkness, like fleeing a lion and meeting a bear.","cita":"Amos 5:18","versiculo":"Woe to you who desire the day of the LORD! Why do you long for the day of the LORD? It is darkness, and not light.","vcita":"Amos 5:18","pista":"\"They expected victory over their enemies; judgment on themselves awaits them.\""},{"pregunta":"What does God say about Israel's feasts and solemn assemblies in Amos 5?","opciones":["\"I hate, I despise your feasts\"","\"Multiply your feasts\"","\"I accept your burnt offerings\"","\"Keep silence in my courts\""],"dato":"God rejects a worship full of feasts but empty of justice: he despises the solemn assemblies of a people that oppresses the poor.","cita":"Amos 5:21","versiculo":"I hate, I despise your feasts, and I can’t stand your solemn assemblies.","vcita":"Amos 5:21","pista":"\"The problem was not the worship calendar, but the people's heart.\""},{"pregunta":"Like what does God ask that justice roll on, in Amos's most famous sentence?","opciones":["Like rivers, and righteousness like a mighty stream","Like the desert wind","Like a consuming fire","Like a river of oil"],"dato":"\"But let justice roll on like rivers, and righteousness like a mighty stream\": God wants a constant, flowing justice, not empty rites.","cita":"Amos 5:24","versiculo":"But let justice roll on like rivers, and righteousness like a mighty stream.","vcita":"Amos 5:24","pista":"\"It is the picture of a river that never dries up, applied to justice.\""},{"pregunta":"Which priest of Bethel accused Amos of conspiring against King Jeroboam?","opciones":["Amaziah","Jeroboam","Uzziah","Jehoiada"],"dato":"Amaziah, priest of the royal sanctuary at Bethel, sent to Jeroboam: \"Amos has conspired against you in the middle of the house of Israel. The land is not able to bear all his words.\"","cita":"Amos 7:10","versiculo":"Then Amaziah the priest of Bethel sent to Jeroboam king of Israel, saying, “Amos has conspired against you in the middle of the house of Israel. The land is not able to bear all his words.","vcita":"Amos 7:10","pista":"\"He was the priest of the royal sanctuary at Bethel, serving the king.\""},{"pregunta":"What did Amos see in the vision that announced Israel's end: a basket of what?","opciones":["Of summer fruit","Of bad figs","Of unleavened bread","Of trodden grapes"],"dato":"The basket of summer fruit is a Hebrew wordplay: ripe fruit sounds like \"end\": \"The end has come on my people Israel.\"","cita":"Amos 8:2","versiculo":"He said, “Amos, what do you see?” I said, “A basket of summer fruit.” Then the LORD said to me, “The end has come on my people Israel. I will not again pass by them any more.","vcita":"Amos 8:2","pista":"\"The fruit is ripe… and so is the judgment: in Hebrew they sound alike.\""},{"pregunta":"What kind of famine will God send on the land, according to Amos 8?","opciones":["Of hearing the LORD's words","Of bread and water","Of oil and wine","Of the early rain"],"dato":"The worst famine is not of bread: God will send a famine \"of hearing the LORD's words,\" and people will wander from sea to sea seeking it without finding it.","cita":"Amos 8:11","versiculo":"Behold, the days come,” says the Lord GOD, “that I will send a famine in the land, not a famine of bread, nor a thirst for water, but of hearing the LORD’s words.","vcita":"Amos 8:11","pista":"\"God's silence is the punishment the prophet fears most.\""},{"pregunta":"What does God promise to raise up \"in that day,\" according to the close of Amos?","opciones":["The fallen tent of David","The wall of Jerusalem","The altar of Bethel","The tower of Siloam"],"dato":"God will raise up the tent of David, close up its breaches and build it as in the days of old; James quoted this prophecy at the Jerusalem council (Acts 15).","cita":"Amos 9:11","versiculo":"In that day I will raise up the tent of David who is fallen and close up its breaches, and I will raise up its ruins, and I will build it as in the days of old,","vcita":"Amos 9:11","pista":"\"The book ends with restoration, not ruin: a fallen royal tent is raised again.\""}],"Obadiah":[{"pregunta":"What distinction does the book of Obadiah have among all the books of the Old Testament?","opciones":["It is the shortest book, with a single chapter","It is the only one written in poetry","It was the last one written","It is the only one without a known author"],"dato":"Obadiah has only 21 verses in a single chapter: it is the shortest book of the Old Testament, and all of it deals with Edom.","cita":"Obadiah 1:1","versiculo":"The vision of Obadiah. This is what the Lord GOD says about Edom. We have heard news from the LORD, and an ambassador is sent among the nations, saying, “Arise, and let’s rise up against her in battle.","vcita":"Obadiah 1:1","pista":"\"His name means 'servant of the LORD,' and his book fits on one page.\""},{"pregunta":"From which son of Isaac did the people of Edom descend, against whom Obadiah prophesies?","opciones":["From Esau","From Jacob","From Ishmael","From Lot"],"dato":"Edom is the nation of Esau, Jacob's twin brother; that is why Obadiah calls Jacob \"your brother\" when rebuking Edom's violence.","cita":"Obadiah 1:8","versiculo":"Won’t I in that day”, says the LORD, “destroy the wise men out of Edom, and understanding out of the mountain of Esau?","vcita":"Obadiah 1:8","pista":"\"He was the twin who sold his birthright for a stew.\""},{"pregunta":"Where did the Edomites dwell, trusting in their lofty home, according to Obadiah?","opciones":["In the clefts of the rock","In tents of the desert","On the shores of the Dead Sea","In the plain of Moab"],"dato":"\"The pride of your heart has deceived you, you who dwell in the clefts of the rock\": cities carved into the cliffs made Edom feel untouchable.","cita":"Obadiah 1:3","versiculo":"The pride of your heart has deceived you, you who dwell in the clefts of the rock, whose habitation is high, who says in his heart, ‘Who will bring me down to the ground?’","vcita":"Obadiah 1:3","pista":"\"Its capital was carved into rock cliffs.\""},{"pregunta":"Even if Edom set its nest among the stars like the eagle, what does God say he will do?","opciones":["\"I will bring you down from there\"","\"There I will bless you\"","\"I will give you greater wings\"","\"No one will ever find you\""],"dato":"Neither height nor fortresses can save the proud: \"Though you mount on high as the eagle, and though your nest is set among the stars, I will bring you down from there,\" says the LORD.","cita":"Obadiah 1:4","versiculo":"Though you mount on high as the eagle, and though your nest is set among the stars, I will bring you down from there,” says the LORD.","vcita":"Obadiah 1:4","pista":"\"Not even the highest nest is out of God's reach.\""},{"pregunta":"What will happen to Esau's hidden treasures, according to Obadiah 1:6?","opciones":["They will be ransacked and sought out","They will stay hidden forever","Judah will inherit them peacefully","The wise men of Teman will guard them"],"dato":"\"How Esau will be ransacked! How his hidden treasures are sought out!\": not even his hoards hidden in the caves will escape the plunder.","cita":"Obadiah 1:6","versiculo":"How Esau will be ransacked! How his hidden treasures are sought out!","vcita":"Obadiah 1:6","pista":"\"Not even the deepest hiding place in the mountain will go unsearched.\""},{"pregunta":"Who deceived Edom and prevailed against him, according to Obadiah?","opciones":["His own allies and men of peace","The Philistines","The children of Jacob","Only the Chaldeans"],"dato":"The peoples who ate his bread and made peace with Edom laid a snare under him: \"The men who were at peace with you have deceived you, and prevailed against you.\"","cita":"Obadiah 1:7","versiculo":"All the men of your alliance have brought you on your way, even to the border. The men who were at peace with you have deceived you, and prevailed against you. Friends who eat your bread lay a snare under you. There is no understanding in him.”","vcita":"Obadiah 1:7","pista":"\"The betrayal came from the shared table, not from the battlefield.\""},{"pregunta":"Why will shame cover Edom, and he be cut off forever, according to Obadiah?","opciones":["For the violence done to his brother Jacob","For worshiping Baal","For not keeping the Sabbath","For selling his own children"],"dato":"\"For the violence done to your brother Jacob, shame will cover you\": instead of defending his brother on the day Jerusalem fell, Edom mocked and plundered.","cita":"Obadiah 1:10","versiculo":"For the violence done to your brother Jacob, shame will cover you, and you will be cut off forever.","vcita":"Obadiah 1:10","pista":"\"His sin was not against a stranger, but against his own twin brother.\""},{"pregunta":"What should Edom NOT have done on the day his brother was carried away, according to Obadiah?","opciones":["Look down on him or rejoice over Judah's destruction","Send him messengers of peace","Weep at Jerusalem's gates","Offer sacrifices for him"],"dato":"\"Don't look down on your brother in the day of his disaster, and don't rejoice over the children of Judah in the day of their destruction\": rejoicing at a brother's misfortune is also a sin.","cita":"Obadiah 1:12","versiculo":"But don’t look down on your brother in the day of his disaster, and don’t rejoice over the children of Judah in the day of their destruction. Don’t speak proudly in the day of distress.","vcita":"Obadiah 1:12","pista":"\"God also judges the smile at another's fall.\""},{"pregunta":"What cruel action does Obadiah rebuke in Edom at the crossroads, in Judah's day of distress?","opciones":["Standing to cut off those who escaped and deliver up the survivors","Closing the water springs","Stealing the ark of the covenant","Burning the temple of Jerusalem"],"dato":"Edom posted himself at the crossroads to cut off Jerusalem's fugitives and hand over the survivors: active complicity with the invader.","cita":"Obadiah 1:14","versiculo":"Don’t stand in the crossroads to cut off those of his who escape. Don’t deliver up those of his who remain in the day of distress.","vcita":"Obadiah 1:14","pista":"\"He did not just watch: he blocked the only way out for those fleeing.\""},{"pregunta":"What principle of payback does Obadiah announce for Edom on the day of the LORD?","opciones":["\"As you have done, it will be done to you\"","\"An eye for an eye and a tooth for a tooth\"","\"Whoever kills by iron will die by iron\"","\"Each one will bear his own sin\""],"dato":"\"As you have done, it will be done to you. Your deeds will return upon your own head\": the measure Edom used on Judah will be the measure of his own judgment.","cita":"Obadiah 1:15","versiculo":"For the day of the LORD is near all the nations! As you have done, it will be done to you. Your deeds will return upon your own head.","vcita":"Obadiah 1:15","pista":"\"It is the rule of sowing and reaping applied to the nations.\""},{"pregunta":"What will there be on Mount Zion while Edom is judged, according to Obadiah?","opciones":["Those who escape, and holiness","An army of Chaldeans","The lost ark","A new Edomite king"],"dato":"\"But in Mount Zion, there will be those who escape, and it will be holy. The house of Jacob will possess their possessions\": God's mountain and Esau's mountain have opposite destinies.","cita":"Obadiah 1:17","versiculo":"But in Mount Zion, there will be those who escape, and it will be holy. The house of Jacob will possess their possessions.","vcita":"Obadiah 1:17","pista":"\"Two mountains face to face: Zion and the mountain of Esau.\""},{"pregunta":"How does the book of Obadiah end, in its last verse?","opciones":["\"And the kingdom will be the LORD's\"","\"And Edom was destroyed\"","\"And Jacob inherited the land\"","\"And there will be no more prophets\""],"dato":"Saviors will go up on Mount Zion to judge the mountains of Esau, \"and the kingdom will be the LORD's\": the last word of the shortest book is God's kingdom.","cita":"Obadiah 1:21","versiculo":"Saviors will go up on Mount Zion to judge the mountains of Esau, and the kingdom will be the LORD’s.","vcita":"Obadiah 1:21","pista":"\"The briefest book closes with the greatest sentence: the kingdom is God's.\""}],"Jonah":[{"pregunta":"Who was the father of the prophet Jonah?","opciones":["Amittai","Pethuel","Beeri","Amoz"],"dato":"The book opens this way: \"Now the LORD's word came to Jonah the son of Amittai\"; that same Jonah had prophesied in the days of Jeroboam II (2 Kings 14).","cita":"Jonah 1:1","versiculo":"Now the LORD’s word came to Jonah the son of Amittai, saying,","vcita":"Jonah 1:1","pista":"\"His name opens the book, right before the order to go to Nineveh.\""},{"pregunta":"To which port did Jonah go down to board the ship bound for Tarshish?","opciones":["To Joppa","To Tyre","To Sidon","To Caesarea"],"dato":"Jonah went down to Joppa, found a ship going to Tarshish, paid its fare and went down into it, to flee \"from the presence of the LORD.\"","cita":"Jonah 1:3","versiculo":"But Jonah rose up to flee to Tarshish from the presence of the LORD. He went down to Joppa, and found a ship going to Tarshish; so he paid its fare, and went down into it, to go with them to Tarshish from the presence of the LORD.","vcita":"Jonah 1:3","pista":"\"It is the port of Joppa, the same one from which Peter would travel centuries later.\""},{"pregunta":"How did the sailors discover that the storm had come because of Jonah?","opciones":["They cast lots, and the lot fell on Jonah","Jonah confessed as soon as he boarded","The captain dreamed it the night before","A fish kept striking the ship's hull"],"dato":"In the middle of the storm the sailors said: \"Come! Let's cast lots, that we may know who is responsible for this evil that is on us. So they cast lots, and the lot fell on Jonah.\"","cita":"Jonah 1:7","versiculo":"They all said to each other, “Come! Let’s cast lots, that we may know who is responsible for this evil that is on us.” So they cast lots, and the lot fell on Jonah.","vcita":"Jonah 1:7","pista":"\"It was like pointing a finger… but with ancient lots.\""},{"pregunta":"When the sailors asked who he was, how did Jonah introduce himself?","opciones":["\"I am a Hebrew, and I fear the LORD, the God of heaven\"","\"I am a prophet sent to Tarshish\"","\"I am a merchant from Joppa\"","\"I am a servant of Israel's king\""],"dato":"Jonah confessed his identity and his faith at the worst moment: \"I am a Hebrew, and I fear the LORD, the God of heaven, who has made the sea and the dry land\" — the same sea that was raging against them.","cita":"Jonah 1:9","versiculo":"He said to them, “I am a Hebrew, and I fear the LORD, the God of heaven, who has made the sea and the dry land.”","vcita":"Jonah 1:9","pista":"\"While fleeing from God, he ended up telling pagan sailors about God.\""},{"pregunta":"What did Jonah ask the sailors to do so the sea would calm down?","opciones":["Take him up and throw him into the sea","Row harder toward shore","Throw the other passengers overboard too","Sacrifice a lamb on deck"],"dato":"\"Take me up, and throw me into the sea. Then the sea will be calm for you; for I know that because of me this great storm is on you\": Jonah accepted bearing the blame.","cita":"Jonah 1:12","versiculo":"He said to them, “Take me up, and throw me into the sea. Then the sea will be calm for you; for I know that because of me this great storm is on you.”","vcita":"Jonah 1:12","pista":"\"He chose the bottom of the sea rather than keep endangering innocent people.\""},{"pregunta":"In his prayer from the fish's belly, what does Jonah say he did when his soul fainted within him?","opciones":["He remembered the LORD, and his prayer came into the holy temple","He cursed the day he was born","He promised never to prophesy again","He fell fast asleep inside the fish"],"dato":"From the depths Jonah prayed: \"When my soul fainted within me, I remembered the LORD. My prayer came in to you, into your holy temple.\"","cita":"Jonah 2:7","versiculo":"When my soul fainted within me, I remembered the LORD. My prayer came in to you, into your holy temple.","vcita":"Jonah 2:7","pista":"\"Not even the bottom of the sea could stop a prayer.\""},{"pregunta":"How big was Nineveh, according to the book of Jonah?","opciones":["An exceedingly great city, three days' journey across","A small fishing village","So small it could be crossed in an hour","As large as Jerusalem and Damascus together"],"dato":"\"Now Nineveh was an exceedingly great city, three days' journey across\": preaching through the whole city took three days, and Jonah was only one day in when the city was already repenting.","cita":"Jonah 3:3","versiculo":"So Jonah arose, and went to Nineveh, according to the LORD’s word. Now Nineveh was an exceedingly great city, three days’ journey across.","vcita":"Jonah 3:3","pista":"\"You could not preach through it in a single day of street preaching.\""},{"pregunta":"What was the exact message Jonah cried out through the streets of Nineveh?","opciones":["\"In forty days, Nineveh will be overthrown!\"","\"Repent within seven days, or fire will fall\"","\"Burn your idols before the month ends\"","\"Assyria's king will fall this very year\""],"dato":"A sermon of few words and no promises: \"In forty days, Nineveh will be overthrown!\" And the people of Nineveh believed God.","cita":"Jonah 3:4","versiculo":"Jonah began to enter into the city a day’s journey, and he cried out, and said, “In forty days, Nineveh will be overthrown!”","vcita":"Jonah 3:4","pista":"\"Forty days of deadline… and not one word of hope in the announcement.\""},{"pregunta":"What did the king of Nineveh do when Jonah's message reached him?","opciones":["He arose from his throne, covered himself with sackcloth and sat in ashes","He ordered Jonah to be jailed","He fled the city during the night","He offered a great banquet to his princes"],"dato":"The king took off his royal robe, covered himself with sackcloth and sat in ashes, and then proclaimed a fast for the whole city, even for the animals.","cita":"Jonah 3:6","versiculo":"The news reached the king of Nineveh, and he arose from his throne, took off his royal robe, covered himself with sackcloth, and sat in ashes.","vcita":"Jonah 3:6","pista":"\"The throne stood empty: the king preferred the ash heap.\""},{"pregunta":"Why didn't God destroy Nineveh when the deadline came?","opciones":["Because he saw that they turned from their evil way","Because Jonah interceded for the city","Because the king paid a great ransom","Because the city was too large"],"dato":"\"God saw their works, that they turned from their evil way. God relented of the disaster which he said he would do to them, and he didn't do it\": repentance changed the city's destiny.","cita":"Jonah 3:10","versiculo":"God saw their works, that they turned from their evil way. God relented of the disaster which he said he would do to them, and he didn’t do it.","vcita":"Jonah 3:10","pista":"\"The sermon worked too well… and that made the preacher angry.\""},{"pregunta":"According to God, how many people who cannot tell their right hand from their left lived in Nineveh?","opciones":["More than one hundred twenty thousand","Twelve thousand","Seventy thousand","More than a million"],"dato":"God closes the book with a question to Jonah: \"Shouldn't I be concerned for Nineveh, that great city, in which are more than one hundred twenty thousand persons… and also many animals?\"","cita":"Jonah 4:11","versiculo":"Shouldn’t I be concerned for Nineveh, that great city, in which are more than one hundred twenty thousand persons who can’t discern between their right hand and their left hand, and also many animals?”","vcita":"Jonah 4:11","pista":"\"God even counted the animals when doing the math of his mercy.\""}],"Micah":[{"pregunta":"From what town was the prophet Micah?","opciones":["From Moresheth","From Tekoa","From Bethlehem","From Anathoth"],"dato":"\"The LORD's word that came to Micah of Morasheth in the days of Jotham, Ahaz, and Hezekiah\": Micah came from a humble town in Judah and was a contemporary of Isaiah.","cita":"Micah 1:1","versiculo":"The LORD’s word that came to Micah of Morasheth in the days of Jotham, Ahaz, and Hezekiah, kings of Judah, which he saw concerning Samaria and Jerusalem.","vcita":"Micah 1:1","pista":"\"He was not from the capital: he came from a small country town in Judah.\""},{"pregunta":"According to Micah 2:13, who will go up before the remnant of Israel, breaking open the way?","opciones":["The one who breaks open the way","The king of Assyria","An angel with a fiery sword","The high priest"],"dato":"\"He who breaks open the way goes up before them. They break through the gate, and go out… with the LORD at their head\": God himself opens the breach so his people can go out.","cita":"Micah 2:13","versiculo":"He who breaks open the way goes up before them. They break through the gate, and go out. Their king passes on before them, with the LORD at their head.","vcita":"Micah 2:13","pista":"\"He is the one who breaks down the wall so the others can pass through.\""},{"pregunta":"With what does Micah say he is filled, unlike the lying prophets?","opciones":["With power by the LORD's Spirit","With visions and dreams every night","With the law of Moses alone","With the riches of Judah"],"dato":"\"But as for me, I am full of power by the LORD's Spirit, and of judgment, and of might, to declare to Jacob his disobedience\": his authority came not from kings but from the Spirit.","cita":"Micah 3:8","versiculo":"But as for me, I am full of power by the LORD’s Spirit, and of judgment, and of might, to declare to Jacob his disobedience, and to Israel his sin.","vcita":"Micah 3:8","pista":"\"The others prophesied for money; he, by the Spirit.\""},{"pregunta":"What did Micah predict would happen to Zion because of the sins of its leaders?","opciones":["It would be plowed like a field","It would be covered by the sea","It would be split into two kingdoms","It would be handed over to the Philistines"],"dato":"Micah announced: \"Zion for your sake will be plowed like a field, and Jerusalem will become heaps of rubble.\" A century later, the elders quoted this prophecy to defend Jeremiah (Jeremiah 26).","cita":"Micah 3:12","versiculo":"Therefore Zion for your sake will be plowed like a field, and Jerusalem will become heaps of rubble, and the mountain of the temple like the high places of a forest.","vcita":"Micah 3:12","pista":"\"The temple hill will end up with plow furrows.\""},{"pregunta":"In Micah 4's vision, into what will the nations beat their swords and their spears?","opciones":["Swords into plowshares and spears into pruning hooks","Swords into trumpets and spears into torches","Spears into temple pillars","Swords into golden crowns"],"dato":"\"They will beat their swords into plowshares, and their spears into pruning hooks. Nation will not lift up sword against nation, neither will they learn war any more\": the peace of the coming kingdom.","cita":"Micah 4:3","versiculo":"and he will judge between many peoples, and will decide concerning strong nations afar off. They will beat their swords into plowshares, and their spears into pruning hooks. Nation will not lift up sword against nation, neither will they learn war any more.","vcita":"Micah 4:3","pista":"\"Weapons of war become farming tools.\""},{"pregunta":"According to Micah 5, in what will the ruler who comes from Bethlehem shepherd?","opciones":["In the strength of the LORD and the majesty of his name","With a rod of iron alone","With the armies of Judah","With the wisdom of Solomon"],"dato":"\"He shall stand, and shall shepherd in the strength of the LORD, in the majesty of the name of the LORD his God\": the shepherd-king will be great to the ends of the earth.","cita":"Micah 5:4","versiculo":"He shall stand, and shall shepherd in the strength of the LORD, in the majesty of the name of the LORD his God. They will live, for then he will be great to the ends of the earth.","vcita":"Micah 5:4","pista":"\"It is the chapter right after the Bethlehem announcement: the small town and the great shepherd.\""},{"pregunta":"Like what will the remnant of Jacob be among many peoples, according to Micah?","opciones":["Like dew from the LORD","Like the sand of the sea","Like cedars of Lebanon","Like stars of heaven"],"dato":"\"The remnant of Jacob will be among many peoples like dew from the LORD, like showers on the grass\": a blessing that comes from God and does not wait for man.","cita":"Micah 5:7","versiculo":"The remnant of Jacob will be among many peoples like dew from the LORD, like showers on the grass, that don’t wait for man nor wait for the sons of men.","vcita":"Micah 5:7","pista":"\"It arrives in silence, by night, and makes everything green again: it comes from heaven.\""},{"pregunta":"With what question does God open his case against his people in Micah 6?","opciones":["\"My people, what have I done to you?\"","\"Where are your gods?\"","\"Why did you build altars?\"","\"Who taught you to sin?\""],"dato":"God calls the mountains as witnesses and asks in pain: \"My people, what have I done to you? How have I burdened you? Answer me!\"","cita":"Micah 6:3","versiculo":"My people, what have I done to you? How have I burdened you? Answer me!","vcita":"Micah 6:3","pista":"\"It is a trial where the Judge asks like a wounded father.\""},{"pregunta":"What does Micah affirm even if he has to sit in darkness?","opciones":["\"The LORD will be a light to me\"","\"My enemies will leave me alone\"","\"The temple will be rebuilt\"","\"Days of vengeance will come\""],"dato":"\"When I fall, I will arise. When I sit in darkness, the LORD will be a light to me\": Micah's confession of faith in the middle of announced judgment.","cita":"Micah 7:8","versiculo":"Don’t rejoice against me, my enemy. When I fall, I will arise. When I sit in darkness, the LORD will be a light to me.","vcita":"Micah 7:8","pista":"\"Fallen, but not extinguished: God himself is his lamp.\""},{"pregunta":"What admiring question opens Micah's final hymn, and echoes the prophet's own name?","opciones":["\"Who is a God like you, who pardons iniquity?\"","\"What people is like Israel?\"","\"What king is like David?\"","\"What mountain is like Zion?\""],"dato":"Micah means \"Who is like the LORD?\", and the book almost closes with that wordplay: \"Who is a God like you, who pardons iniquity… because he delights in loving kindness.\"","cita":"Micah 7:18","versiculo":"Who is a God like you, who pardons iniquity, and passes over the disobedience of the remnant of his heritage? He doesn’t retain his anger forever, because he delights in loving kindness.","vcita":"Micah 7:18","pista":"\"The hidden answer is inside the prophet's own name.\""},{"pregunta":"According to Micah 7:19, where will God cast all his people's sins?","opciones":["Into the depths of the sea","Behind his back","Into the desert of Sin","Under the temple altar"],"dato":"\"He will again have compassion on us… You will cast all their sins into the depths of the sea.\"","cita":"Micah 7:19","versiculo":"He will again have compassion on us. He will tread our iniquities under foot. You will cast all their sins into the depths of the sea.","vcita":"Micah 7:19","pista":"\"So deep that no one will ever fish them back out.\""}],"Nahum":[{"pregunta":"Which city does Nahum call the «bloody city», full of lies and robbery?","opciones":["Nineveh","Babylon","Tyre","Damascus"],"dato":"Nahum prophesied the fall of Nineveh, Assyria's cruel capital, about a hundred years after Jonah preached there.","cita":"Nahum 3:1","versiculo":"Woe to the bloody city! It is all full of lies and robbery—no end to the prey.","vcita":"Nahum 3:1","pista":"«It is the same city Jonah did not want to go and preach to.»"},{"pregunta":"Where was the prophet Nahum from?","opciones":["Elkosh","Tekoa","Anathoth","Moresheth"],"dato":"The book introduces itself as «the vision of Nahum the Elkoshite»; the exact location of that town is unknown.","cita":"Nahum 1:1","versiculo":"A revelation about Nineveh. The book of the vision of Nahum the Elkoshite.","vcita":"Nahum 1:1","pista":"«His hometown label sounds a lot like his own name.»"},{"pregunta":"According to Nahum, the LORD is a stronghold in what day?","opciones":["In the day of trouble","On the feast day","On the day of rest","In the day of harvest"],"dato":"In the middle of a chapter about God's wrath against Nineveh, Nahum comforts Judah: God is a refuge for those who trust in him.","cita":"Nahum 1:7","versiculo":"The LORD is good, a stronghold in the day of trouble; and he knows those who take refuge in him.","vcita":"Nahum 1:7","pista":"«The day when everything goes wrong and you need him most.»"},{"pregunta":"According to Nahum 1:3, the LORD is slow to anger and great in what?","opciones":["In power","In years","In riches","In armies"],"dato":"God is slow to anger, but his power is immense: his way is in the whirlwind and the storm, and the clouds are the dust of his feet.","cita":"Nahum 1:3","versiculo":"The LORD is slow to anger, and great in power, and will by no means leave the guilty unpunished. The LORD has his way in the whirlwind and in the storm, and the clouds are the dust of his feet.","vcita":"Nahum 1:3","pista":"«Not weak patience: it is strength held back.»"},{"pregunta":"According to Nahum 1:15, whose feet are seen on the mountains?","opciones":["Of him who brings good news and publishes peace","Of the fleeing king of Assyria","Of the spies of Judah","Of the shepherds of Bethlehem"],"dato":"Nineveh's fall was good news for Judah: the messenger announces that the wicked one will pass through their land no more.","cita":"Nahum 1:15","versiculo":"Behold, on the mountains the feet of him who brings good news, who publishes peace! Keep your feasts, Judah! Perform your vows, for the wicked one will no more pass through you. He is utterly cut off.","vcita":"Nahum 1:15","pista":"«Isaiah uses the same picture of the messenger announcing peace.»"},{"pregunta":"According to Nahum's prophecy, what would be opened, and Nineveh's palace dissolved?","opciones":["The gates of the rivers","The gates of the city","The floodgates of heaven","The gates of the temple"],"dato":"Nineveh fell when the river running through it flooded and undermined its defenses, just as the prophecy announced.","cita":"Nahum 2:6","versiculo":"The gates of the rivers are opened, and the palace is dissolved.","vcita":"Nahum 2:6","pista":"«Nineveh's enemy would arrive... by water!»"},{"pregunta":"Nahum ironically asks where the den of what animals had gone, a symbol of the Assyrian kings?","opciones":["Of the lions","Of the bears","Of the eagles","Of the wolves"],"dato":"Assyria's kings pictured themselves as hunting lions; their den would be left empty, with no cubs at all.","cita":"Nahum 2:11","versiculo":"Where is the den of the lions, and the feeding place of the young lions, where the lion and the lioness walked with the lion’s cubs, and no one made them afraid?","vcita":"Nahum 2:11","pista":"«The king of the jungle, who filled his caves with prey.»"},{"pregunta":"Which Egyptian city, situated among rivers, does Nahum use as an example that not even she could be saved?","opciones":["No-Amon (Thebes)","Memphis","Alexandria","Tanis"],"dato":"No-Amon is Thebes, the mighty city of the Nile that had already fallen to Assyria; Nineveh would be no better than her.","cita":"Nahum 3:8","versiculo":"Are you better than No-Amon, who was situated among the rivers, who had the waters around her, whose rampart was the sea, and her wall was of the sea?","vcita":"Nahum 3:8","pista":"«Her rampart was water: rivers on every side.»"},{"pregunta":"According to Nahum 3:4, Nineveh, the alluring prostitute, was the mistress of what?","opciones":["Of witchcraft","Of trade","Of war","Of music"],"dato":"With her sorceries and political seduction, Nineveh sold entire nations; that is why her public shame would come.","cita":"Nahum 3:4","versiculo":"because of the multitude of the prostitution of the alluring prostitute, the mistress of witchcraft, who sells nations through her prostitution, and families through her witchcraft.","vcita":"Nahum 3:4","pista":"«She sold whole peoples through her spells.»"},{"pregunta":"Nahum ends by announcing that the shepherds of which king would slumber, and his people be scattered on the mountains?","opciones":["Of the king of Assyria","Of the king of Babylon","Of the king of Egypt","Of the king of Judah"],"dato":"With no shepherds to gather it, the Assyrian empire would scatter forever: its wound would have no cure.","cita":"Nahum 3:18","versiculo":"Your shepherds slumber, king of Assyria. Your nobles lie down. Your people are scattered on the mountains, and there is no one to gather them.","vcita":"Nahum 3:18","pista":"«It is the same empire whose capital was Nineveh.»"},{"pregunta":"In Nahum 1:13, what does the LORD promise to break off Judah?","opciones":["Assyria's yoke","Israel's bow","Moses' staff","The tablets of the law"],"dato":"«Now I will break his yoke from off you, and will burst your bonds apart»: Judah would be free from Assyrian oppression for good.","cita":"Nahum 1:13","versiculo":"Now I will break his yoke from off you, and will burst your bonds apart.”","vcita":"Nahum 1:13","pista":"«What an ox wears on its neck to pull the plow.»"},{"pregunta":"According to Nahum 2:3, what color would the shields and clothing of the army attacking Nineveh be?","opciones":["Red, scarlet","White as snow","Black as night","Blue as the sky"],"dato":"The mighty attackers were dressed in scarlet and their shields were made red; their chariots flashed like torches in the streets.","cita":"Nahum 2:3","versiculo":"The shield of his mighty men is made red. The valiant men are in scarlet. The chariots flash with steel in the day of his preparation, and the pine spears are brandished.","vcita":"Nahum 2:3","pista":"«One single color covers both shields and uniforms.»"}],"Habakkuk":[{"pregunta":"How will the righteous live, according to Habakkuk 2:4's famous line, later quoted by Paul and in Hebrews?","opciones":["By his faith","By his riches","By his strength","By his many works"],"dato":"«The righteous will live by his faith» is one of the most quoted lines of the Old Testament: it appears in Romans, Galatians and Hebrews.","cita":"Habakkuk 2:4","versiculo":"Behold, his soul is puffed up. It is not upright in him, but the righteous will live by his faith.","vcita":"Habakkuk 2:4","pista":"«Not by sight nor by works: it is by believing.»"},{"pregunta":"Which nation did God announce he would raise up to punish Judah, a «bitter and hasty» people?","opciones":["The Chaldeans (Babylonians)","The Egyptians","The Philistines","The Syrians"],"dato":"The Chaldeans were the people of Babylon; their army would sweep through the land taking dwellings that were not theirs, and that left Habakkuk perplexed.","cita":"Habakkuk 1:6","versiculo":"For, behold, I am raising up the Chaldeans, that bitter and hasty nation who march through the width of the earth, to possess dwelling places that are not theirs.","vcita":"Habakkuk 1:6","pista":"«Their capital was Babylon, the city of King Nebuchadnezzar.»"},{"pregunta":"What did the LORD command Habakkuk to write, making it plain on tablets so the reader could run?","opciones":["The vision","A new law","The list of the kings","The census of the people"],"dato":"The vision had to be written clearly on tablets, like a public billboard: even if it lingered, it would surely come.","cita":"Habakkuk 2:2","versiculo":"The LORD answered me, “Write the vision, and make it plain on tablets, that he who runs may read it.","vcita":"Habakkuk 2:2","pista":"«It was what God had shown the prophet.»"},{"pregunta":"According to Habakkuk 2:14, the earth will be filled with what, as the waters cover the sea?","opciones":["With the knowledge of the LORD's glory","With enemy armies","With wheat and wine","With new cities"],"dato":"In the middle of the five «woes» against the oppressor, God promises that his glory will be known over all the earth.","cita":"Habakkuk 2:14","versiculo":"For the earth will be filled with the knowledge of the LORD’s glory, as the waters cover the sea.","vcita":"Habakkuk 2:14","pista":"«Not a material good: it is knowing how glorious God is.»"},{"pregunta":"«The LORD is in his holy temple»: what should all the earth do before him, according to Habakkuk 2:20?","opciones":["Be silent","Sing","Flee","Build altars"],"dato":"Unlike the mute idols, which have no breath in them, the living God is in his temple and all the earth keeps reverent silence.","cita":"Habakkuk 2:20","versiculo":"But the LORD is in his holy temple. Let all the earth be silent before him!”","vcita":"Habakkuk 2:20","pista":"«The opposite of making noise: total reverence.»"},{"pregunta":"Even if the fig tree does not blossom and there is no fruit on the vines, what does Habakkuk decide to do?","opciones":["Rejoice in the LORD, the God of his salvation","Quit his office as prophet","Curse the barren land","Move away to Egypt"],"dato":"Habakkuk 3:17-18 is one of the greatest declarations of faith in the Bible: joy in God even with no harvest, no cattle, nothing.","cita":"Habakkuk 3:18","versiculo":"yet I will rejoice in the LORD. I will be joyful in the God of my salvation!","vcita":"Habakkuk 3:18","pista":"«His joy did not depend on the harvest, but on God.»"},{"pregunta":"According to Habakkuk 3:19, God will make the prophet's feet like the feet of what mountain animal?","opciones":["Of a deer","Of a mountain goat","Of an eagle","Of a desert gazelle"],"dato":"A deer steps surely on the most dangerous cliffs; so God would make his prophet walk on his high places.","cita":"Habakkuk 3:19","versiculo":"GOD, the Lord, is my strength. He makes my feet like deer’s feet, and enables me to go in high places. For the music director, on my stringed instruments.","vcita":"Habakkuk 3:19","pista":"«An animal with sure footing on the rocky heights.»"},{"pregunta":"In his prayer, Habakkuk asks God: «In wrath, remember...» what?","opciones":["Mercy","The ancient covenants","The sacrifices","The poor"],"dato":"The prophet trembled at hearing God's fame and asked that, even in the midst of judgment, God would renew his work and remember mercy.","cita":"Habakkuk 3:2","versiculo":"LORD, I have heard of your fame. I stand in awe of your deeds, LORD. Renew your work in the middle of the years. In the middle of the years make it known. In wrath, you remember mercy.","vcita":"Habakkuk 3:2","pista":"«It is what every sinner needs when God is angry.»"},{"pregunta":"By what name does Habakkuk call God in his complaint: «You, O ____, have established him to punish»?","opciones":["Rock","Shepherd","Eternal King","Potter"],"dato":"Habakkuk cannot understand why God uses a more wicked nation to punish Judah, yet he leans on the fact that God is his Rock and his Holy One.","cita":"Habakkuk 1:12","versiculo":"Aren’t you from everlasting, LORD my God, my Holy One? We will not die. LORD, you have appointed them for judgment. You, Rock, have established him to punish.","vcita":"Habakkuk 1:12","pista":"«Firm and unmoving, like a giant stone.»"},{"pregunta":"Where did Habakkuk station himself to watch for God's answer to his complaint?","opciones":["At his watch post, on the ramparts","On Mount Carmel","On the roof of his house","On the wall of Jerusalem"],"dato":"Like a sentry at his post, Habakkuk kept watch until he could see what God would say to him; the answer was the vision of the tablets.","cita":"Habakkuk 2:1","versiculo":"I will stand at my watch and set myself on the ramparts, and will look out to see what he will say to me, and what I will answer concerning my complaint.","vcita":"Habakkuk 2:1","pista":"«He did what a watchman does in his tower.»"},{"pregunta":"According to Habakkuk 1:5, the work God would do in their days was so astonishing that, even if told, what would happen?","opciones":["They would not believe it","Everyone would flee","Kings would tremble","No one would ever understand it"],"dato":"God announces something unbelievable: he would raise up the Chaldeans as an instrument of judgment, and the people would not believe it even when told.","cita":"Habakkuk 1:5","versiculo":"“Look among the nations, watch, and wonder marvelously; for I am working a work in your days which you will not believe though it is told you.","vcita":"Habakkuk 1:5","pista":"«Paul quoted this verse in his sermon at Antioch.»"},{"pregunta":"What is chapter 3 of Habakkuk's book, «set to victorious music»?","opciones":["A prayer of the prophet in the form of a psalm","A letter to the exiles","The list of the woes","A vision of animals"],"dato":"The book ends with a prayer-song that even carries musical directions: «For the music director, on my stringed instruments.»","cita":"Habakkuk 3:1","versiculo":"A prayer of Habakkuk, the prophet, set to victorious music.","vcita":"Habakkuk 3:1","pista":"«He starts the book complaining... and ends it singing to God.»"}],"Zephaniah":[{"pregunta":"In the days of which king of Judah did Zephaniah prophesy, according to the first verse of his book?","opciones":["Josiah","Hezekiah","Manasseh","Zedekiah"],"dato":"Zephaniah prophesied in the days of Josiah; his genealogy goes back four generations, to a certain Hezekiah, perhaps King Hezekiah himself.","cita":"Zephaniah 1:1","versiculo":"The LORD’s word which came to Zephaniah, the son of Cushi, the son of Gedaliah, the son of Amariah, the son of Hezekiah, in the days of Josiah, the son of Amon, king of Judah.","vcita":"Zephaniah 1:1","pista":"«The boy king who later led a great reform and found the book of the law.»"},{"pregunta":"Zephaniah describes the day of the LORD as «a day of wrath, a day of distress and...» what else?","opciones":["Anguish, trouble and darkness","Feasting and rest","Harvest and plenty","Singing and dancing"],"dato":"Zephaniah chapter 1 is the most complete portrait of the «day of the LORD»: wrath, darkness, gloom and the trumpet of war.","cita":"Zephaniah 1:15","versiculo":"That day is a day of wrath, a day of distress and anguish, a day of trouble and ruin, a day of darkness and gloom, a day of clouds and blackness,","vcita":"Zephaniah 1:15","pista":"«No celebration at all: it is the day of judgment.»"},{"pregunta":"According to Zephaniah 1:18, what will NOT be able to deliver people in the day of the LORD's wrath?","opciones":["Neither their silver nor their gold","Neither their armies","Neither their city walls","Neither their wooden idols"],"dato":"Not all the riches in the world can ransom anyone when the fire of God's jealousy comes on the land.","cita":"Zephaniah 1:18","versiculo":"Neither their silver nor their gold will be able to deliver them in the day of the LORD’s wrath, but the whole land will be devoured by the fire of his jealousy; for he will make an end, yes, a terrible end, of all those who dwell in the land.","vcita":"Zephaniah 1:18","pista":"«The two precious metals of all ages.»"},{"pregunta":"«Seek the LORD»: to whom is that command addressed in Zephaniah 2:3, so they might be hidden in the day of anger?","opciones":["To all the humble of the land","To the priests of the temple","To the armies of Judah","To the rich of Jerusalem"],"dato":"Zephaniah's recipe for escaping judgment is threefold: seek the LORD, seek righteousness and seek humility.","cita":"Zephaniah 2:3","versiculo":"Seek the LORD, all you humble of the land, who have kept his ordinances. Seek righteousness. Seek humility. It may be that you will be hidden in the day of the LORD’s anger.","vcita":"Zephaniah 2:3","pista":"«The lowly in heart, not the proud.»"},{"pregunta":"According to Zephaniah 2:9, Moab would be like Sodom, and the children of Ammon like which city?","opciones":["Like Gomorrah","Like Nineveh","Like Tyre","Like Babylon"],"dato":"Moab and Ammon taunted God's people and magnified themselves against them; their end would be like that of the cities of the plain.","cita":"Zephaniah 2:9","versiculo":"Therefore, as I live, says the LORD of Armies, the God of Israel, surely Moab will be as Sodom, and the children of Ammon as Gomorrah, a possession of nettles and salt pits, and a perpetual desolation. The remnant of my people will plunder them, and the survivors of my nation will inherit them.","vcita":"Zephaniah 2:9","pista":"«Sodom's inseparable twin city since Genesis.»"},{"pregunta":"According to Zephaniah 3:17, the LORD will rejoice over his people with singing and will calm them in his... what?","opciones":["Love","Joy","Patience","Mercy"],"dato":"The book that opened with the day of wrath ends with God singing for joy over his restored people: a God who saves and delights.","cita":"Zephaniah 3:17","versiculo":"The LORD, your God, is among you, a mighty one who will save. He will rejoice over you with joy. He will calm you in his love. He will rejoice over you with singing.","vcita":"Zephaniah 3:17","pista":"«The greatest feeling of all toward his people.»"},{"pregunta":"According to Zephaniah 1:12, with what will God search Jerusalem, to punish the complacent men settled on their dregs?","opciones":["With lamps","With torches of war","With the eyes of angels","With trumpets"],"dato":"Like someone searching every corner with a lamp, God would find those who said in their hearts, «The LORD will not do good, neither will he do evil.»","cita":"Zephaniah 1:12","versiculo":"It will happen at that time, that I will search Jerusalem with lamps, and I will punish the men who are settled on their dregs, who say in their heart, “The LORD will not do good, neither will he do evil.”","vcita":"Zephaniah 1:12","pista":"«What you use to look for something in the dark.»"},{"pregunta":"According to Zephaniah 2:13, which city would be made a desolation, as dry as the wilderness?","opciones":["Nineveh","Jerusalem","Tyre","Gaza"],"dato":"God would stretch out his hand against the north, destroy Assyria, and flocks and wild beasts would rest in proud Nineveh.","cita":"Zephaniah 2:13","versiculo":"He will stretch out his hand against the north, destroy Assyria, and will make Nineveh a desolation, as dry as the wilderness.","vcita":"Zephaniah 2:13","pista":"«Nahum wrote a whole book about that city's fall.»"},{"pregunta":"According to Zephaniah 3:9, what will God purify for the peoples, so they may all call on his name and serve him shoulder to shoulder?","opciones":["Their lips","Their language back to Hebrew","Their ancient sacrifices","Their solemn feasts"],"dato":"After judgment would come purification: purified lips to call on the LORD's name and serve him with one accord.","cita":"Zephaniah 3:9","versiculo":"For then I will purify the lips of the peoples, that they may all call on the LORD’s name, to serve him shoulder to shoulder.","vcita":"Zephaniah 3:9","pista":"«The very opposite of the confusion of Babel.»"},{"pregunta":"According to Zephaniah 3:12, God will leave among Jerusalem a people with what two qualities?","opciones":["Afflicted and poor","Numerous and rich","Wise and brave","Pure and fearsome"],"dato":"Out of the judgment a humble, afflicted remnant would remain, taking refuge in the LORD's name, doing no wrong and telling no lies.","cita":"Zephaniah 3:12","versiculo":"But I will leave among you an afflicted and poor people, and they will take refuge in the LORD’s name.","vcita":"Zephaniah 3:12","pista":"«The opposite of the proud who were removed.»"},{"pregunta":"According to Zephaniah 1:4, God would cut off from Jerusalem the remnant of which pagan god?","opciones":["Of Baal","Of Dagon","Of Molech","Of Ashtoreth"],"dato":"Judgment would fall on the remnant of Baal, on those who bowed to the starry host on the rooftops and swore by the LORD and by their king at the same time.","cita":"Zephaniah 1:4","versiculo":"I will stretch out my hand against Judah and against all the inhabitants of Jerusalem. I will cut off the remnant of Baal from this place—the name of the idolatrous and pagan priests,","vcita":"Zephaniah 1:4","pista":"«The Canaanite god Elijah had already faced on Mount Carmel.»"},{"pregunta":"«Sing, daughter of ____! Shout, Israel!»: which name completes the song of Zephaniah 3:14?","opciones":["Zion","Jacob","Judah","Ephraim"],"dato":"The book ends in celebration: the LORD, King of Israel in her midst, cleared away the judgments and turned away her enemies.","cita":"Zephaniah 3:14","versiculo":"Sing, daughter of Zion! Shout, Israel! Be glad and rejoice with all your heart, daughter of Jerusalem.","vcita":"Zephaniah 3:14","pista":"«The poetic name of God's hill and city.»"}],"Haggai":[{"pregunta":"Haggai's first message came on the twenty-fourth day of the sixth month, in the second year of which king?","opciones":["King Darius","King Cyrus","King Artaxerxes","King Nebuchadnezzar"],"dato":"Haggai is one of the best-dated books of the Bible: its messages fall in the second year of Darius of Persia, around 520 B.C.","cita":"Haggai 1:15","versiculo":"in the twenty-fourth day of the month, in the sixth month, in the second year of Darius the king.","vcita":"Haggai 1:15","pista":"«A Persian king, not a Babylonian or a Jewish one.»"},{"pregunta":"To which two leaders did the LORD's word come through Haggai?","opciones":["To Zerubbabel, governor of Judah, and to Joshua, the high priest","To Ezra and Nehemiah","To David and Solomon","To Elijah and Elisha"],"dato":"Zerubbabel was the governor, a descendant of David, and Joshua son of Jehozadak was the high priest: civil and religious leadership received the word together.","cita":"Haggai 1:1","versiculo":"In the second year of Darius the king, in the sixth month, in the first day of the month, the LORD’s word came by Haggai the prophet, to Zerubbabel the son of Shealtiel, governor of Judah, and to Joshua the son of Jehozadak, the high priest, saying,","vcita":"Haggai 1:1","pista":"«One ruled the people and the other served in the temple.»"},{"pregunta":"«These people say, The time hasn't yet come»: the time for what, according to Haggai 1:2?","opciones":["For the LORD's house to be built","To return from exile","To celebrate the Passover","To anoint a king in Judah"],"dato":"The Jews had returned from exile but left the temple in ruins for years, always postponing the work with that excuse.","cita":"Haggai 1:2","versiculo":"“This is what the LORD of Armies says: These people say, ‘The time hasn’t yet come, the time for the LORD’s house to be built.’”","vcita":"Haggai 1:2","pista":"«For their own houses there was always plenty of time.»"},{"pregunta":"God confronts them: you dwell in paneled houses, «while this house...» what?","opciones":["Lies waste","Is full of glory","Is not yet paid for","Is full of idols"],"dato":"Paneled houses for themselves and ruins for God: that is why the harvest failed and nothing was ever enough.","cita":"Haggai 1:4","versiculo":"“Is it a time for you yourselves to dwell in your paneled houses, while this house lies waste?","vcita":"Haggai 1:4","pista":"«The opposite of inhabited and cared for.»"},{"pregunta":"According to Haggai 1:6, the wage earner puts his wages where, so they never last?","opciones":["Into a bag with holes in it","Into counterfeit coins","Into the hands of thieves","Into a bottomless pit"],"dato":"Sowing much and harvesting little, eating without being filled, and earning wages to drop them into a pierced bag: such was life with the temple abandoned.","cita":"Haggai 1:6","versiculo":"You have sown much, and bring in little. You eat, but you don’t have enough. You drink, but you aren’t filled with drink. You clothe yourselves, but no one is warm; and he who earns wages earns wages to put them into a bag with holes in it.’","vcita":"Haggai 1:6","pista":"«Like keeping coins in a pocket full of holes.»"},{"pregunta":"«Go up to the mountain, bring...» what, and build the house of the LORD?","opciones":["Wood","Precious stones","Flour and oil","Gold and silver"],"dato":"The command was practical: go up the mountain, cut wood and get building; God would take pleasure in the house and be glorified.","cita":"Haggai 1:8","versiculo":"Go up to the mountain, bring wood, and build the house. I will take pleasure in it, and I will be glorified,” says the LORD.","vcita":"Haggai 1:8","pista":"«It comes from the trees on the mountain.»"},{"pregunta":"What short message did Haggai deliver to the people from the LORD, according to Haggai 1:13?","opciones":["«I am with you»","«Go back to Babylon»","«Stop the work»","«Fear king Darius»"],"dato":"With those words God encouraged the leaders and the people, and stirred up everyone's spirit to get to work on his house.","cita":"Haggai 1:13","versiculo":"Then Haggai, the LORD’s messenger, spoke the LORD’s message to the people, saying, “I am with you,” says the LORD.","vcita":"Haggai 1:13","pista":"«The promise of God's company repeated all through the Bible.»"},{"pregunta":"«The silver is mine, and...» what other metal does God declare his own in Haggai 2:8?","opciones":["The gold","The bronze","The iron","The copper"],"dato":"The new temple looked poor compared with Solomon's, but the Owner of all the silver and all the gold would fill that house with glory.","cita":"Haggai 2:8","versiculo":"The silver is mine, and the gold is mine,’ says the LORD of Armies.","vcita":"Haggai 2:8","pista":"«Silver's classic partner: the yellow metal.»"},{"pregunta":"According to Haggai 2:9, how will the latter glory of this house compare with the former?","opciones":["It will be greater than the former","It will be the same as the former","It will be smaller, but enough","Only spiritual, with no visible glory"],"dato":"Though the second temple seemed like nothing to the elders who had seen the first, God promises greater glory and peace in that place.","cita":"Haggai 2:9","versiculo":"‘The latter glory of this house will be greater than the former,’ says the LORD of Armies; ‘and in this place I will give peace,’ says the LORD of Armies.”","vcita":"Haggai 2:9","pista":"«The last will surpass the first.»"},{"pregunta":"According to Haggai 2:7, when God shakes all nations, what will come in, and the house will be filled with glory? (Note: the WEB renders it as «the treasure of all nations».)","opciones":["The treasure — the Desire — of all nations","The king of Persia","The exiles from Egypt","An army from the north"],"dato":"Known in Spanish as «el Deseado de todas las gentes», this is one of Haggai's best-known messianic prophecies, tied to the glory of the latter temple.","cita":"Haggai 2:7","versiculo":"and I will shake all nations. The treasure of all nations will come, and I will fill this house with glory, says the LORD of Armies.","vcita":"Haggai 2:7","pista":"«All peoples long for it, even if they don't know it.»"},{"pregunta":"At the end of the book, God promises to take Zerubbabel and make him like what, because he has chosen him?","opciones":["Like a signet ring","Like a crown of gold","Like a cornerstone","Like the morning star"],"dato":"The signet ring was the king's personal signature; Zerubbabel, grandson of King Jeconiah, is restored as a sign of the messianic line.","cita":"Haggai 2:23","versiculo":"In that day, says the LORD of Armies, I will take you, Zerubbabel my servant, the son of Shealtiel,’ says the LORD, ‘and will make you like a signet ring, for I have chosen you,’ says the LORD of Armies.”","vcita":"Haggai 2:23","pista":"«Worn on the finger, used to sign with authority.»"},{"pregunta":"In Haggai 2:4, God says «be strong» three times: to whom does he say it?","opciones":["To Zerubbabel, to Joshua, and to all the people of the land","To the kings of the nations","To the prophets only","To the priests and the Levites"],"dato":"Governor, high priest and the whole people receive the same command: be strong and work, for the LORD is with them.","cita":"Haggai 2:4","versiculo":"Yet now be strong, Zerubbabel,’ says the LORD. ‘Be strong, Joshua son of Jehozadak, the high priest. Be strong, all you people of the land,’ says the LORD, ‘and work, for I am with you,’ says the LORD of Armies.","vcita":"Haggai 2:4","pista":"«The two leaders of chapter 1... plus everybody else.»"}],"Zechariah":[{"pregunta":"Complete the LORD's word to Zerubbabel: «Not by might, nor by power, but by...»","opciones":["My Spirit","Many prayers","The sword of Judah","The help of Persia"],"dato":"The temple work would not be finished by human power, but by the Spirit of God: it is Zechariah's most famous verse.","cita":"Zechariah 4:6","versiculo":"Then he answered and spoke to me, saying, “This is the LORD’s word to Zerubbabel, saying, ‘Not by might, nor by power, but by my Spirit,’ says the LORD of Armies.","vcita":"Zechariah 4:6","pista":"«No soldiers and no muscle: the third Person of the Trinity.»"},{"pregunta":"According to Zechariah 9:9, the King will come righteous and having salvation, lowly, riding on what animal?","opciones":["On a donkey, on a colt, the foal of a donkey","On a white horse","On a war chariot","On a royal camel"],"dato":"This prophecy was fulfilled when Jesus entered Jerusalem riding on a colt, and the Gospels quote it directly.","cita":"Zechariah 9:9","versiculo":"Rejoice greatly, daughter of Zion! Shout, daughter of Jerusalem! Behold, your King comes to you! He is righteous, and having salvation; lowly, and riding on a donkey, even on a colt, the foal of a donkey.","vcita":"Zechariah 9:9","pista":"«Not the warrior's horse: the humble mount of the King of peace.»"},{"pregunta":"In Zechariah 11's acted-out prophecy, how many pieces of silver did they weigh out as his wages?","opciones":["Thirty pieces of silver","Forty pieces of silver","Twelve pieces of silver","A hundred pieces of silver"],"dato":"The prophet threw that «lordly price» into the house of the LORD, to the potter; Judas would receive the same amount for betraying Jesus.","cita":"Zechariah 11:12","versiculo":"I said to them, “If you think it best, give me my wages; and if not, keep them.” So they weighed for my wages thirty pieces of silver.","vcita":"Zechariah 11:12","pista":"«The same amount Judas received for handing over Jesus.»"},{"pregunta":"In the vision of Zechariah 3, Joshua the high priest stood before the angel wearing what kind of garments, which were then taken off him?","opciones":["Filthy garments","Garments of mourning","A foreigner's garments","Torn battle clothes"],"dato":"Satan stood at his right hand to accuse him, but God defended him: the filthy clothes were removed and rich clothing put on, a symbol of forgiveness.","cita":"Zechariah 3:4","versiculo":"He answered and spoke to those who stood before him, saying, “Take the filthy garments off him.” To him he said, “Behold, I have caused your iniquity to pass from you, and I will clothe you with rich clothing.”","vcita":"Zechariah 3:4","pista":"«They represent the sin God took away from him.»"},{"pregunta":"According to Zechariah 2:5, what would the LORD be for Jerusalem, since the city would be inhabited without walls?","opciones":["A wall of fire around her","A tower of stone","An army of angels camped around","A river surrounding her"],"dato":"Jerusalem would grow so much that she would overflow any walls; her defense and her glory would be the LORD himself in her midst.","cita":"Zechariah 2:5","versiculo":"For I,’ says the LORD, ‘will be to her a wall of fire around it, and I will be the glory in the middle of her.","vcita":"Zechariah 2:5","pista":"«A wall no enemy can touch: it burns.»"},{"pregunta":"«Behold, the man whose name is...»: what name does Zechariah 6:12 give to the one who will build the LORD's temple?","opciones":["The Branch","The Lion of Judah","The Suffering Servant","The Son of Man"],"dato":"The Branch would grow up out of his place, build the temple, bear the glory, and be a priest on his throne.","cita":"Zechariah 6:12","versiculo":"and speak to him, saying, ‘The LORD of Armies says, “Behold, the man whose name is the Branch! He will grow up out of his place; and he will build the LORD’s temple.","vcita":"Zechariah 6:12","pista":"«The fresh shoot that grows out of the cut-down stump.»"},{"pregunta":"In his first night vision, Zechariah saw a man riding a red horse, standing among what plants?","opciones":["Among the myrtle trees","Among the palm trees","Among the cedars of Lebanon","Among the fig trees"],"dato":"Behind the man were red, brown and white horses: they were the ones the LORD had sent to patrol the earth, which was still and at rest.","cita":"Zechariah 1:8","versiculo":"“I had a vision in the night, and behold, a man riding on a red horse, and he stood among the myrtle trees that were in a ravine; and behind him there were red, brown, and white horses.","vcita":"Zechariah 1:8","pista":"«Fragrant shrubs down in the ravine.»"},{"pregunta":"The flying scroll in Zechariah 5's vision: what were its measurements?","opciones":["Twenty cubits long and ten cubits wide","Ten cubits long and five wide","A hundred cubits long and one wide","Seven cubits long and seven wide"],"dato":"That scroll was the curse going out over the land against the thief and the one who swears falsely: its size matched the porch of the temple.","cita":"Zechariah 5:2","versiculo":"He said to me, “What do you see?” I answered, “I see a flying scroll; its length is twenty cubits, and its width ten cubits.”","vcita":"Zechariah 5:2","pista":"«The length is exactly twice the width.»"},{"pregunta":"According to Zechariah 14:9, in that day the LORD will be King over what extent?","opciones":["Over all the earth","Only over Judah","Over the twelve tribes","Over Jerusalem and its surroundings"],"dato":"Chapter 14 closes with the universal kingdom: «The LORD will be one, and his name one» over all the earth.","cita":"Zechariah 14:9","versiculo":"The LORD will be King over all the earth. In that day the LORD will be one, and his name one.","vcita":"Zechariah 14:9","pista":"«Not a local kingdom: the whole planet.»"},{"pregunta":"According to Zechariah 8:23, how many men from all languages will take hold of the skirt of a Jew, saying «we will go with you»?","opciones":["Ten men","Seventy men","Twelve men","Three men"],"dato":"The nations would seek the LORD in Jerusalem and grab hold of a Jew because they had heard that God was with his people.","cita":"Zechariah 8:23","versiculo":"The LORD of Armies says: “In those days, ten men out of all the languages of the nations will take hold of the skirt of him who is a Jew, saying, ‘We will go with you, for we have heard that God is with you.’”","vcita":"Zechariah 8:23","pista":"«The number of fingers on both hands.»"},{"pregunta":"According to Zechariah 13:9, the remaining third will be brought into the fire and tested like which precious metal?","opciones":["Like gold is tested","Like bronze is melted","Like iron is polished","Like steel is tempered"],"dato":"God would refine the remnant as silver is refined and test them like gold; they would call on his name and he would say, «It is my people.»","cita":"Zechariah 13:9","versiculo":"I will bring the third part into the fire, and will refine them as silver is refined, and will test them like gold is tested. They will call on my name, and I will hear them. I will say, ‘It is my people;’ and they will say, ‘The LORD is my God.’”","vcita":"Zechariah 13:9","pista":"«The yellow metal that comes out of the crucible pure.»"}],"Malachi":[{"pregunta":"Bringing the whole tithe into the storehouse, God challenges his people to test him: what does he promise to open?","opciones":["The windows of heaven","The gates of the temple","The floodgates of the rivers","The granaries of Egypt"],"dato":"It is the one place where God invites people to test him: he would pour out a blessing until there is not enough room for it.","cita":"Malachi 3:10","versiculo":"Bring the whole tithe into the storehouse, that there may be food in my house, and test me now in this,” says the LORD of Armies, “if I will not open you the windows of heaven, and pour you out a blessing, that there will not be enough room for.","vcita":"Malachi 3:10","pista":"«Not keys or doors: what opens is up in heaven.»"},{"pregunta":"«Will a man rob God?» According to Malachi 3:8, in what had the people robbed him?","opciones":["In tithes and offerings","In animal sacrifices","In uncelebrated feasts","In the wood for the temple"],"dato":"The whole nation withheld what belonged to God; that is why the curse weighed on their harvests and the devourer ruined the fruit.","cita":"Malachi 3:8","versiculo":"Will a man rob God? Yet you rob me! But you say, ‘How have we robbed you?’ In tithes and offerings.","vcita":"Malachi 3:8","pista":"«The tenth part... and the offerings.»"},{"pregunta":"According to Malachi 4:2, for those who fear the LORD's name, what will arise with healing in its wings?","opciones":["The sun of righteousness","The morning star","The harvest full moon","The rainbow of the covenant"],"dato":"While the proud will be stubble in the oven of the coming day, those who fear God will leap like calves of the stall under that Sun.","cita":"Malachi 4:2","versiculo":"But to you who fear my name shall the sun of righteousness arise with healing in its wings. You will go out and leap like calves of the stall.","vcita":"Malachi 4:2","pista":"«It shines by day, brings righteousness... and heals.»"},{"pregunta":"Whom does God promise to send before the great and terrible day of the LORD comes, according to Malachi 4:5?","opciones":["Elijah the prophet","A new Moses","King David","Elisha, his successor"],"dato":"The prophecy literally names Elijah; Jesus taught that John the Baptist came in the spirit of Elijah to prepare the way.","cita":"Malachi 4:5","versiculo":"Behold, I will send you Elijah the prophet before the great and terrible day of the LORD comes.","vcita":"Malachi 4:5","pista":"«The prophet of Carmel and of the Kerith ravine.»"},{"pregunta":"According to Malachi 4:6, that sent prophet will turn the hearts of the fathers to whom?","opciones":["To the children","To the temple","To the ancient law","To the priests"],"dato":"The Old Testament closes with a promise of family reconciliation: fathers and children turned to each other before the great day.","cita":"Malachi 4:6","versiculo":"He will turn the hearts of the fathers to the children and the hearts of the children to their fathers, lest I come and strike the earth with a curse.”","vcita":"Malachi 4:6","pista":"«Reconciliation between two generations of the family.»"},{"pregunta":"What kind of animals were the priests offering on the altar, which God rejected in Malachi 1:8?","opciones":["The blind, the lame and the sick","Only the fattest ones","Animals from other nations","Firstfruits of the harvest"],"dato":"God challenged them: «Present it to your governor! Will he be pleased with you?» The defective, the stolen and the damaged do not honor the Great King.","cita":"Malachi 1:8","versiculo":"When you offer the blind for sacrifice, isn’t that evil? And when you offer the lame and sick, isn’t that evil? Present it now to your governor! Will he be pleased with you? Or will he accept your person?” says the LORD of Armies.","vcita":"Malachi 1:8","pista":"«They gave God what nobody else would want to receive.»"},{"pregunta":"According to Malachi 2:7, the priest's lips should keep what?","opciones":["Knowledge","Absolute silence","The people's offerings","The king's secrets"],"dato":"The priest is the messenger of the LORD of Armies: people should seek the law at his mouth; Malachi's priests, instead, made many stumble.","cita":"Malachi 2:7","versiculo":"For the priest’s lips should keep knowledge, and they should seek the law at his mouth; for he is the messenger of the LORD of Armies.","vcita":"Malachi 2:7","pista":"«From his mouth the people were to seek the law.»"},{"pregunta":"According to Malachi 3:1, what will the messenger God sends do before him?","opciones":["Prepare the way","Build the temple","Defeat the armies","Write a new book"],"dato":"This prophecy paves the way into the New Testament: the messenger is John the Baptist, and the Lord would then come to his temple.","cita":"Malachi 3:1","versiculo":"“Behold, I send my messenger, and he will prepare the way before me! The Lord, whom you seek, will suddenly come to his temple. Behold, the messenger of the covenant, whom you desire, is coming!” says the LORD of Armies.","vcita":"Malachi 3:1","pista":"«Mark opens his gospel by quoting this announcement.»"},{"pregunta":"According to Malachi 3:16, what was written before God for those who fear him and honor his name?","opciones":["A book of memory","A new law","The list of the priests","A song of victory"],"dato":"While some said serving God was useless, those who feared him spoke with one another, and God listened and had it recorded.","cita":"Malachi 3:16","versiculo":"Then those who feared the LORD spoke one with another; and the LORD listened and heard, and a book of memory was written before him for those who feared the LORD and who honored his name.","vcita":"Malachi 3:16","pista":"«God keeps a written record of his own.»"},{"pregunta":"According to Malachi 3:17, those who fear the LORD will be what special thing to him in the day he makes?","opciones":["His own possession (special treasure)","His chosen army","His eternal priests","His most numerous people"],"dato":"God will spare them as a man spares his own son who serves him; then the difference between the righteous and the wicked will be seen again.","cita":"Malachi 3:17","versiculo":"They shall be mine,” says the LORD of Armies, “my own possession in the day that I make. I will spare them, as a man spares his own son who serves him.","vcita":"Malachi 3:17","pista":"«The most valuable thing a king keeps in his house.»"},{"pregunta":"The book opens with God saying «I have loved you». Whom did he love, and whom did he hate, according to Malachi 1:2-3?","opciones":["He loved Jacob and hated Esau","He loved Esau and hated Jacob","He loved Judah and hated Israel","He loved Levi and hated Judah"],"dato":"Jacob and Esau were twin brothers; God chose Jacob, and Esau's descendants, Edom, would be laid waste despite their efforts to rebuild.","cita":"Malachi 1:2-3","versiculo":"“I have loved you,” says the LORD. Yet you say, “How have you loved us?” “Wasn’t Esau Jacob’s brother?” says the LORD, “Yet I loved Jacob; but Esau I hated, and made his mountains a desolation, and gave his heritage to the jackals of the wilderness.”","vcita":"Malachi 1:2-3","pista":"«Two twins from Genesis: the younger was the one chosen.»"}],"Romans":[{"pregunta":"According to Romans 1, what does Paul say he is not ashamed of, because it is God's power for salvation?","opciones":["The Good News of Christ","His chains in Rome","His Roman citizenship","The law of Moses"],"dato":"Paul opens his letter declaring that he is not ashamed of the Good News: it is the power of God for salvation to everyone who believes, to the Jew first and also to the Greek.","cita":"Romans 1:16","versiculo":"For I am not ashamed of the Good News of Christ, because it is the power of God for salvation for everyone who believes, for the Jew first, and also for the Greek.","vcita":"Romans 1:16","pista":"«It is the good news Paul carried all across the empire.»"},{"pregunta":"What is, according to Paul, the condition of ALL people before God?","opciones":["All have sinned and fall short of the glory of God","Only Gentiles fall short of the glory of God","Those who keep the law reach God's glory by themselves","Each person will be judged only by good works"],"dato":"Paul levels Jew and Gentile alike: all have sinned and fall short of the glory of God; no one can be justified by personal merit.","cita":"Romans 3:23","versiculo":"for all have sinned, and fall short of the glory of God;","vcita":"Romans 3:23","pista":"«No one is left out: neither Jew nor Greek.»"},{"pregunta":"According to Romans 4, what was credited to Abraham as righteousness?","opciones":["That he believed God","That he offered his son Isaac","That he kept the law perfectly","That he built altars in Canaan"],"dato":"Paul quotes Genesis 15:6 to show that Abraham was justified by faith, long before the law and before circumcision.","cita":"Romans 4:3","versiculo":"For what does the Scripture say? “Abraham believed God, and it was accounted to him for righteousness.”","vcita":"Romans 4:3","pista":"«He is the example of the father of faith.»"},{"pregunta":"How did God demonstrate his love toward us, according to Romans 5?","opciones":["In that while we were yet sinners, Christ died for us","By sparing us from every earthly suffering","By promising riches and health to all","By never allowing us to be tested"],"dato":"God's love did not wait until we were good: Christ died for us while we were still sinners.","cita":"Romans 5:8","versiculo":"But God commends his own love toward us, in that while we were yet sinners, Christ died for us.","vcita":"Romans 5:8","pista":"«He did not wait until we were good.»"},{"pregunta":"According to Paul, what are the wages of sin, and what is God's free gift?","opciones":["The wages are death; the gift, eternal life in Christ Jesus","The wages are sickness; the gift, prosperity","The wages are shame; the gift, a good reputation","The wages are labor; the gift, temporary rest"],"dato":"Sin pays a wage that is earned: death. God, instead, freely gives what no one can earn: eternal life in Christ Jesus our Lord.","cita":"Romans 6:23","versiculo":"For the wages of sin is death, but the free gift of God is eternal life in Christ Jesus our Lord.","vcita":"Romans 6:23","pista":"«An earned salary versus an undeserved gift.»"},{"pregunta":"According to Romans 8, what is there NONE of for those who are in Christ Jesus?","opciones":["No condemnation","No trials","No weaknesses","No enemies"],"dato":"Romans 8 opens by removing the sentence: there is now no condemnation to those who are in Christ Jesus.","cita":"Romans 8:1","versiculo":"There is therefore now no condemnation to those who are in Christ Jesus, who don’t walk according to the flesh, but according to the Spirit.","vcita":"Romans 8:1","pista":"«The chapter begins by erasing the verdict.»"},{"pregunta":"According to the promise of Romans 8, for whom do all things work together for good?","opciones":["For those who love God, who are called according to his purpose","For those who never suffer losses","Only for apostles and prophets","For those who keep the law perfectly"],"dato":"The promise does not say everything that happens is good, but that God makes all things work together for good for those who love him.","cita":"Romans 8:28","versiculo":"We know that all things work together for good for those who love God, for those who are called according to his purpose.","vcita":"Romans 8:28","pista":"«It doesn't say everything is good — it says everything works for good.»"},{"pregunta":"According to Paul, which things is he persuaded will NOT be able to separate us from God's love?","opciones":["Neither death, nor life, nor angels, nor principalities","Neither hunger, nor thirst, nor cold","Neither kings, nor the armies of the earth","Neither night, nor day, nor the seasons"],"dato":"Paul goes down the list in Romans 8: neither death nor life, angels nor powers, things present nor things to come can separate us from God's love.","cita":"Romans 8:38","versiculo":"For I am persuaded that neither death, nor life, nor angels, nor principalities, nor things present, nor things to come, nor powers,","vcita":"Romans 8:38","pista":"«Paul reads the list, and nothing manages to separate us.»"},{"pregunta":"According to Romans 12, how should the believer be transformed instead of being conformed to this world?","opciones":["By the renewing of the mind","By moving to another city and culture","By quitting all secular work","By keeping feasts and Sabbaths"],"dato":"The believer's transformation starts on the inside: be transformed by the renewing of the mind, to prove what God's good will is.","cita":"Romans 12:2","versiculo":"Don’t be conformed to this world, but be transformed by the renewing of your mind, so that you may prove what is the good, well-pleasing, and perfect will of God.","vcita":"Romans 12:2","pista":"«The transformation starts with the mind.»"},{"pregunta":"What was the name of the servant of the assembly at Cenchreae whom Paul commends at the end of Romans?","opciones":["Phoebe","Priscilla","Lydia","Mary Magdalene"],"dato":"Phoebe, our sister and a servant of the assembly at Cenchreae, heads the greetings of Romans 16; many believe she herself carried the letter to Rome.","cita":"Romans 16:1","versiculo":"I commend to you Phoebe, our sister, who is a servant of the assembly that is at Cenchreae,","vcita":"Romans 16:1","pista":"«She probably carried this very letter all the way to Rome.»"}],"1 Corinthians":[{"pregunta":"At the start of 1 Corinthians, Paul rebukes the divisions: besides Paul and Christ, whose names were some claiming, saying “I follow…”?","opciones":["Apollos and Cephas","Barnabas and Silas","Timothy and Titus","John and James"],"dato":"The church in Corinth had split into factions, each boasting in a favorite teacher: Paul, Apollos, Cephas or even Christ himself.","cita":"1 Corinthians 1:12","versiculo":"Now I mean this, that each one of you says, “I follow Paul,” “I follow Apollos,” “I follow Cephas,” and, “I follow Christ.”","vcita":"1 Corinthians 1:12","pista":"«One watered in Corinth; the other was Simon Peter.»"},{"pregunta":"Complete what is written in 1 Corinthians 2: “Things which an eye didn't see, and an ear didn't hear… are what God has prepared for…”","opciones":["Those who love him","The wise of this world","Those who keep the law","The prophets of old"],"dato":"Paul quotes this text to speak of what the Spirit reveals: what God prepared for those who love him goes beyond what eye and ear can reach.","cita":"1 Corinthians 2:9","versiculo":"But as it is written, “Things which an eye didn’t see, and an ear didn’t hear, which didn’t enter into the heart of man, these God has prepared for those who love him.”","vcita":"1 Corinthians 2:9","pista":"«The measure is not wisdom, but love for God.»"},{"pregunta":"Using the picture of a field, who does Paul say WATERED what he had planted in Corinth?","opciones":["Apollos","Peter","Timothy","Aquila"],"dato":"“I planted. Apollos watered. But God gave the increase”: both are servants; the growth is God's work.","cita":"1 Corinthians 3:6","versiculo":"I planted. Apollos watered. But God gave the increase.","vcita":"1 Corinthians 3:6","pista":"«The same one some were claiming to follow.»"},{"pregunta":"What picture does Paul use for how a little sin contaminates the whole church?","opciones":["A little yeast that leavens the whole lump","A rotten apple inside the basket","A drop of ink in clean water","A small fox spoiling the vines"],"dato":"Facing a grave case of immorality, Paul warns that a little yeast leavens the whole lump; that is why the church had to act without boasting.","cita":"1 Corinthians 5:6","versiculo":"Your boasting is not good. Don’t you know that a little yeast leavens the whole lump?","vcita":"1 Corinthians 5:6","pista":"«It puffs up the whole loaf with just a tiny bit.»"},{"pregunta":"According to 1 Corinthians 6, what is the believer's body?","opciones":["A temple of the Holy Spirit","A prison the soul escapes from","Each person's absolute property","A disposable vessel of no value"],"dato":"Paul teaches that the believer's body is a temple of the Holy Spirit who is in him, and that he is not his own.","cita":"1 Corinthians 6:19","versiculo":"Or don’t you know that your body is a temple of the Holy Spirit who is in you, whom you have from God? You are not your own,","vcita":"1 Corinthians 6:19","pista":"«A sanctuary that walks.»"},{"pregunta":"In the picture of the games, what kind of crown do athletes strive for, compared with the believer's?","opciones":["They, a corruptible one; we, an incorruptible one","They, one of gold; we, one of silver","They, one of olive leaves; we, one of precious stones","They, a temporary one; we, no crown at all"],"dato":"Paul compares the athlete's self-control with the Christian life: they restrain themselves for a fading crown; the believer, for an incorruptible one.","cita":"1 Corinthians 9:25","versiculo":"Every man who strives in the games exercises self-control in all things. Now they do it to receive a corruptible crown, but we an incorruptible.","vcita":"1 Corinthians 9:25","pista":"«One withers in days; the other lasts forever.»"},{"pregunta":"According to 1 Corinthians 10, what does God always provide along with temptation?","opciones":["The way of escape, so we can endure it","A visible sign in the sky","The visit of an angel","The immediate end of every hardship"],"dato":"God is faithful: he will not allow us to be tempted above what we are able, and with the temptation he will also make the way of escape.","cita":"1 Corinthians 10:13","versiculo":"No temptation has taken you except what is common to man. God is faithful, who will not allow you to be tempted above what you are able, but will with the temptation also make the way of escape, that you may be able to endure it.","vcita":"1 Corinthians 10:13","pista":"«There is never a temptation without an exit door.»"},{"pregunta":"According to Paul, what do we do as often as we eat the bread and drink the cup in the Lord's Supper?","opciones":["We proclaim the Lord's death until he comes","We remember only the exodus from Egypt","We celebrate the birth of Christ","We bless the day's food"],"dato":"The Lord's Supper is a proclamation: as often as we take part, we proclaim the Lord's death until he comes.","cita":"1 Corinthians 11:26","versiculo":"For as often as you eat this bread and drink this cup, you proclaim the Lord’s death until he comes.","vcita":"1 Corinthians 11:26","pista":"«A sermon that is eaten and drunk.»"},{"pregunta":"In the picture of the body, which member does Paul say cannot tell the hand, “I have no need for you”?","opciones":["The eye","The ear","The foot","The mouth"],"dato":"No member can despise another: not the eye to the hand, nor the head to the feet; all are needed in the body of Christ.","cita":"1 Corinthians 12:21","versiculo":"The eye can’t tell the hand, “I have no need for you,” or again the head to the feet, “I have no need for you.”","vcita":"1 Corinthians 12:21","pista":"«It can see, but without the hand it cannot grasp anything.»"},{"pregunta":"According to 1 Corinthians 15, what is the sting of death?","opciones":["Sin","Sickness","Old age","Human fear"],"dato":"“The sting of death is sin, and the power of sin is the law”: that is why Christ's resurrection takes the venom out of death.","cita":"1 Corinthians 15:56","versiculo":"The sting of death is sin, and the power of sin is the law.","vcita":"1 Corinthians 15:56","pista":"«It is what gives death its deadly sting.»"},{"pregunta":"What word does Paul use to close 1 Corinthians, a cry meaning “Come, Lord!”?","opciones":["Maranatha","Talitha cumi","Raca","Ephphatha"],"dato":"Paul closes with a warning and a hope: if anyone doesn't love the Lord Jesus Christ, let him be cursed; and he proclaims “Maranatha”: the Lord is coming.","cita":"1 Corinthians 16:22","versiculo":"If any man doesn’t love the Lord Jesus Christ, let him be cursed. Come, Lord!","vcita":"1 Corinthians 16:22","pista":"«It was the hope-filled greeting of the early church.»"}],"2 Corinthians":[{"pregunta":"With what double title does Paul bless God at the opening of 2 Corinthians?","opciones":["Father of mercies and God of all comfort","Judge of all the earth and King of kings","Creator of heaven and earth","The God of Abraham, Isaac and Jacob"],"dato":"God comforts his people in all their affliction, so that they may also comfort others with the very comfort they received.","cita":"2 Corinthians 1:3","versiculo":"Blessed be the God and Father of our Lord Jesus Christ, the Father of mercies and God of all comfort,","vcita":"2 Corinthians 1:3","pista":"«His comfort is not for keeping: it's for sharing.»"},{"pregunta":"According to 2 Corinthians 4, where do we carry the treasure of the Good News?","opciones":["In clay vessels","In chests of gold","On tablets of stone","In temples of marble"],"dato":"The treasure travels in clay vessels so that the exceeding greatness of the power may be of God and not from ourselves.","cita":"2 Corinthians 4:7","versiculo":"But we have this treasure in clay vessels, that the exceeding greatness of the power may be of God and not from ourselves.","vcita":"2 Corinthians 4:7","pista":"«The container is fragile on purpose.»"},{"pregunta":"Complete Paul's sentence: “for we walk by faith, not by…”","opciones":["Sight","Works of the law","Feelings","Traditions"],"dato":"While away from the Lord in the body, we walk by faith and not by sight, trusting in what we do not yet see.","cita":"2 Corinthians 5:7","versiculo":"for we walk by faith, not by sight.","vcita":"2 Corinthians 5:7","pista":"«Walking by believing what the eyes cannot yet reach.»"},{"pregunta":"According to Paul, what is anyone who is in Christ?","opciones":["A new creation: the old things have passed away","One more proselyte of the Jews","A renewed slave of the law","A Roman citizen with privileges"],"dato":"If anyone is in Christ, he is a new creation: the old things have passed away, and all things have become new.","cita":"2 Corinthians 5:17","versiculo":"Therefore if anyone is in Christ, he is a new creation. The old things have passed away. Behold, all things have become new.","vcita":"2 Corinthians 5:17","pista":"«Not a repair of the past: a brand-new start.»"},{"pregunta":"In 2 Corinthians 5, what does Paul call those who announce reconciliation with God?","opciones":["Ambassadors on behalf of Christ","Heralds of the Roman empire","Scribes skilled in the law","Guards of the temple in Jerusalem"],"dato":"God gave us the word of reconciliation; we are ambassadors as though God were entreating through us: “Be reconciled to God.”","cita":"2 Corinthians 5:20","versiculo":"We are therefore ambassadors on behalf of Christ, as though God were entreating by us: we beg you on behalf of Christ, be reconciled to God.","vcita":"2 Corinthians 5:20","pista":"«Representatives carrying an urgent message from the King.»"},{"pregunta":"According to 2 Corinthians 7, what does the sorrow of the world produce?","opciones":["Death","Repentance leading to salvation","Lasting joy","Patience and wisdom"],"dato":"There are two kinds of sorrow: godly sorrow produces repentance leading to salvation; the sorrow of the world only produces death.","cita":"2 Corinthians 7:10","versiculo":"For godly sorrow produces repentance leading to salvation, which brings no regret. But the sorrow of the world produces death.","vcita":"2 Corinthians 7:10","pista":"«One sorrow leads to life; the other, to the opposite.»"},{"pregunta":"Which churches set the great example of giving generously in the midst of their deep poverty?","opciones":["The assemblies of Macedonia","The assemblies of Galatia","The seven assemblies of Asia","The assembly in Antioch"],"dato":"The Macedonians, in a severe ordeal of affliction, overflowed in generosity and begged Paul for the favor of taking part in the offering.","cita":"2 Corinthians 8:2","versiculo":"how in a severe ordeal of affliction, the abundance of their joy and their deep poverty abounded to the riches of their generosity.","vcita":"2 Corinthians 8:2","pista":"«Philippi and Thessalonica were in that region.»"},{"pregunta":"According to 2 Corinthians 9, what kind of giver does God love?","opciones":["A cheerful giver","The one who gives the largest amount","The one who gives under obligation","The one who gives expecting more back"],"dato":"Each one should give as he has determined in his heart, not grudgingly or under compulsion, for God loves a cheerful giver.","cita":"2 Corinthians 9:7","versiculo":"Let each man give according as he has determined in his heart, not grudgingly or under compulsion, for God loves a cheerful giver.","vcita":"2 Corinthians 9:7","pista":"«The heart's attitude is worth more than the amount.»"},{"pregunta":"According to 2 Corinthians 11, what does Satan himself masquerade as in order to deceive?","opciones":["An angel of light","A gentle lamb","An aged prophet","A star from heaven"],"dato":"Paul unmasks the false apostles: it is no wonder their servants disguise themselves, since Satan himself masquerades as an angel of light.","cita":"2 Corinthians 11:14","versiculo":"And no wonder, for even Satan masquerades as an angel of light.","vcita":"2 Corinthians 11:14","pista":"«The most dangerous deception comes dressed in brightness.»"},{"pregunta":"What was given to Paul so that the greatness of the revelations would not exalt him too much?","opciones":["A thorn in the flesh, a messenger of Satan","Permanent blindness since his conversion","An order not to leave Corinth","A companion who watched over his writings"],"dato":"Paul pleaded three times for his thorn in the flesh —a messenger of Satan to torment him— to be removed; the answer was grace that is sufficient.","cita":"2 Corinthians 12:7","versiculo":"By reason of the exceeding greatness of the revelations, that I should not be exalted excessively, a thorn in the flesh was given to me: a messenger of Satan to torment me, that I should not be exalted excessively.","vcita":"2 Corinthians 12:7","pista":"«A thorn that reminded him of his weakness every day.»"},{"pregunta":"What did the Lord answer Paul when he pleaded for the thorn to be removed?","opciones":["“My grace is sufficient for you, for my power is made perfect in weakness”","“Wait, you will be healed within a year”","“Ask the church to fast for you”","“The thorn will leave when your mission ends”"],"dato":"The answer was not to remove the thorn, but to promise sufficient grace: God's power is made perfect in human weakness.","cita":"2 Corinthians 12:9","versiculo":"He has said to me, “My grace is sufficient for you, for my power is made perfect in weakness.” Most gladly therefore I will rather glory in my weaknesses, that the power of Christ may rest on me.","vcita":"2 Corinthians 12:9","pista":"«Grace is enough, even if the thorn stays.»"}],"Galatians":[{"pregunta":"According to Galatians 1, what should even an angel from heaven be if he preaches a different “good news”?","opciones":["Let him be cursed","He should be heard with respect","He should be tested with new signs","He should be forgiven for his ignorance"],"dato":"Paul is uncompromising: even if we or an angel from heaven should preach any other good news than the one preached, let him be cursed.","cita":"Galatians 1:8","versiculo":"But even though we, or an angel from heaven, should preach to you any “good news” other than that which we preached to you, let him be cursed.","vcita":"Galatians 1:8","pista":"«Not even a heavenly messenger can change the message.»"},{"pregunta":"Which apostle did Paul resist to his face in Antioch for withdrawing from the Gentiles?","opciones":["Peter (Cephas)","John, son of Zebedee","Barnabas","James, the Lord's brother"],"dato":"Peter used to eat with the Gentiles, but when certain men arrived he withdrew out of fear; Paul resisted him publicly because he was not walking uprightly.","cita":"Galatians 2:11","versiculo":"But when Peter came to Antioch, I resisted him to his face, because he stood condemned.","vcita":"Galatians 2:11","pista":"«The same one Jesus called Cephas: a rock.»"},{"pregunta":"Complete Paul's confession: “I have been crucified with Christ, and it is no longer I who live, but…”","opciones":["Christ lives in me","The law lives in me","My old life all over again","Only my spirit, without the body"],"dato":"The life Paul now lives in the flesh, he lives by faith in the Son of God, who loved him and gave himself up for him.","cita":"Galatians 2:20","versiculo":"I have been crucified with Christ, and it is no longer I who live, but Christ lives in me. That life which I now live in the flesh, I live by faith in the Son of God, who loved me and gave himself up for me.","vcita":"Galatians 2:20","pista":"«It is no longer Paul living his own life.»"},{"pregunta":"According to Galatians 3, from what did Christ redeem us by becoming a curse for us?","opciones":["From the curse of the law","From the rule of the Roman empire","From all physical pain in this life","From daily work and weariness"],"dato":"Christ redeemed us from the curse of the law, having become a curse for us, for it is written: “Cursed is everyone who hangs on a tree.”","cita":"Galatians 3:13","versiculo":"Christ redeemed us from the curse of the law, having become a curse for us. For it is written, “Cursed is everyone who hangs on a tree,”","vcita":"Galatians 3:13","pista":"«He took upon himself the curse that belonged to us.»"},{"pregunta":"According to Galatians 3, which differences disappear because we are all one in Christ Jesus?","opciones":["There is neither Jew nor Greek, neither slave nor free, neither male nor female","There are neither rich nor poor only","There are neither old nor young","There are neither teachers nor disciples"],"dato":"All who were baptized into Christ have put on Christ: in him there is neither Jew nor Greek, slave nor free man, male nor female.","cita":"Galatians 3:28","versiculo":"There is neither Jew nor Greek, there is neither slave nor free man, there is neither male nor female; for you are all one in Christ Jesus.","vcita":"Galatians 3:28","pista":"«Before Christ, the labels of this world fall away.»"},{"pregunta":"According to Galatians 4, when did God send out his Son, born to a woman?","opciones":["When the fullness of the time came","Only after the fall of the Roman empire","Before creation, in visible person","When Israel voted to ask for him"],"dato":"When the fullness of the time came, God sent out his Son, born to a woman, born under the law, to redeem those under the law.","cita":"Galatians 4:4","versiculo":"But when the fullness of the time came, God sent out his Son, born to a woman, born under the law,","vcita":"Galatians 4:4","pista":"«Not a day early, not a day late: at the exact moment.»"},{"pregunta":"According to Galatians 4, what does the Spirit of the Son cry out in our hearts because we are children?","opciones":["“Abba, Father!”","“Holy, holy, holy”","“Here I am, send me”","“Glory in the highest”"],"dato":"Because we are children, God sent out the Spirit of his Son into our hearts, crying with a child's trust: Abba, Father!","cita":"Galatians 4:6","versiculo":"And because you are children, God sent out the Spirit of his Son into your hearts, crying, “Abba, Father!”","vcita":"Galatians 4:6","pista":"«It's the Aramaic word a child uses for “daddy”.»"},{"pregunta":"Which of these virtues is NOT part of the fruit of the Spirit in the list of Galatians 5?","opciones":["Wisdom","Love","Self-control","Gentleness"],"dato":"The fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faith, gentleness and self-control; wisdom does not appear in that list.","cita":"Galatians 5:22–23","versiculo":"But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faith, gentleness, and self-control. Against such things there is no law.","vcita":"Galatians 5:22–23","pista":"«There are nine marks, and that word is not among them.»"},{"pregunta":"Complete Paul's farming principle: “Whatever a man sows, that he will also…”","opciones":["Reap","Eat","Sell","Give away"],"dato":"God is not mocked: the harvest always matches the sowing; whoever sows to the flesh reaps corruption, and whoever sows to the Spirit reaps eternal life.","cita":"Galatians 6:7","versiculo":"Don’t be deceived. God is not mocked, for whatever a man sows, that he will also reap.","vcita":"Galatians 6:7","pista":"«If you sow corn, you won't harvest grapes.»"},{"pregunta":"In what does Paul say he will boast, and only in that?","opciones":["In the cross of our Lord Jesus Christ","In his journeys and the churches he founded","In his mastery of the Jewish law","In the visions he received in Arabia"],"dato":"“Far be it from me to boast except in the cross of our Lord Jesus Christ”: through it the world has been crucified to Paul, and he to the world.","cita":"Galatians 6:14","versiculo":"But far be it from me to boast except in the cross of our Lord Jesus Christ, through which the world has been crucified to me, and I to the world.","vcita":"Galatians 6:14","pista":"«His only trophy was shaped like a cross.»"}],"Ephesians":[{"pregunta":"According to Ephesians 1, with what has God blessed us in the heavenly places in Christ?","opciones":["With every spiritual blessing","With guaranteed material riches","With long life free of sickness","With authority over the nations"],"dato":"The letter opens by blessing the Father, who has blessed us with every spiritual blessing in the heavenly places in Christ.","cita":"Ephesians 1:3","versiculo":"Blessed be the God and Father of our Lord Jesus Christ, who has blessed us with every spiritual blessing in the heavenly places in Christ,","vcita":"Ephesians 1:3","pista":"«The account already comes full from heaven.»"},{"pregunta":"According to Ephesians 1, the Holy Spirit is the ______ of our inheritance.","opciones":["Pledge","Public deed","Golden key","Written firstfruits in stone"],"dato":"Sealed with the Holy Spirit of promise, who is a pledge —the guarantee and down payment— of our inheritance, until the redemption of God's own possession.","cita":"Ephesians 1:14","versiculo":"who is a pledge of our inheritance, to the redemption of God’s own possession, to the praise of his glory.","vcita":"Ephesians 1:14","pista":"«He is the “down payment” that guarantees the rest.»"},{"pregunta":"Complete the great declaration of Ephesians 2: “for by grace you have been saved through faith, and that not of yourselves; it is…”","opciones":["The gift of God","Man's accumulated merit","A work of the law fulfilled","The fruit of personal effort"],"dato":"Salvation is by grace through faith; and even that is not of ourselves: it is the gift of God, not of works, so that no one may boast.","cita":"Ephesians 2:8","versiculo":"for by grace you have been saved through faith, and that not of yourselves; it is the gift of God,","vcita":"Ephesians 2:8","pista":"«It cannot be bought or earned: it is received.»"},{"pregunta":"According to Ephesians 2, we are God's “workmanship”, created in Christ Jesus for what?","opciones":["For good works, which God prepared beforehand","To stop making every effort","To judge those who do not believe","To keep the ceremonial law"],"dato":"We are not saved BY good works, but FOR good works: God prepared them beforehand so that we would walk in them.","cita":"Ephesians 2:10","versiculo":"For we are his workmanship, created in Christ Jesus for good works, which God prepared before that we would walk in them.","vcita":"Ephesians 2:10","pista":"«Works are not the root: they are the destination.»"},{"pregunta":"According to Ephesians 2, Christ is our peace because he broke down what between Jew and Gentile?","opciones":["The middle wall of separation","The city wall of Jerusalem","The veil at the sanctuary entrance","The tower of the Antonia fortress"],"dato":"Christ made both one: he broke down the middle wall of separation and created in himself one new man, making peace.","cita":"Ephesians 2:14","versiculo":"For he is our peace, who made both one, and broke down the middle wall of separation,","vcita":"Ephesians 2:14","pista":"«Where there was a wall, Christ opened a door.»"},{"pregunta":"According to the doxology of Ephesians 3, God is able to do things how, compared with all we ask or think?","opciones":["Exceedingly abundantly above all that we ask or think","Exactly to the measure of our asking","Only when the whole church fasts","A little less than we imagine"],"dato":"Paul closes his prayer for the Ephesians looking to him who is able to do exceedingly abundantly above all that we ask or think.","cita":"Ephesians 3:20","versiculo":"Now to him who is able to do exceedingly abundantly above all that we ask or think, according to the power that works in us,","vcita":"Ephesians 3:20","pista":"«His answer always exceeds our calculation.»"},{"pregunta":"According to Ephesians 4, why were apostles, prophets, evangelists, pastors and teachers given to the church?","opciones":["For the perfecting of the saints, to the work of serving","To do all the work by themselves","To rule over the saints with lordship","To replace the reading of Scripture"],"dato":"The ministries were given for the perfecting of the saints and the building up of the body of Christ: the work of serving belongs to all the people, not a few.","cita":"Ephesians 4:12","versiculo":"for the perfecting of the saints, to the work of serving, to the building up of the body of Christ,","vcita":"Ephesians 4:12","pista":"«They are coaches of a whole team, not the only players.»"},{"pregunta":"According to Ephesians 4, what must not go down on our wrath?","opciones":["The sun","The day of rest","The end of the year","The news reaching the whole church"],"dato":"“Be angry, and don't sin. Don't let the sun go down on your wrath, and don't give place to the devil”: anger must be settled the same day.","cita":"Ephesians 4:26","versiculo":"“Be angry, and don’t sin.” Don’t let the sun go down on your wrath,","vcita":"Ephesians 4:26","pista":"«The deadline to reconcile expires at sunset.»"},{"pregunta":"According to Ephesians 4, how should we treat one another, imitating what God did for us in Christ?","opciones":["Kind and tender hearted, forgiving each other","Demanding payment for every offense","Avoiding each other in polite silence","Correcting each other harshly in public"],"dato":"God in Christ forgave us; therefore we should be kind to one another, tender hearted, forgiving each other.","cita":"Ephesians 4:32","versiculo":"And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.","vcita":"Ephesians 4:32","pista":"«We forgive because we were forgiven first.»"},{"pregunta":"Instead of being drunk with wine, what does Paul command us to be filled with in Ephesians 5?","opciones":["The Spirit","Earthly pleasures","Human knowledge only","Good intentions without deeds"],"dato":"“Don't be drunken with wine, in which is dissipation, but be filled with the Spirit”: that fullness is expressed with psalms, hymns and spiritual songs.","cita":"Ephesians 5:18","versiculo":"Don’t be drunken with wine, in which is dissipation, but be filled with the Spirit,","vcita":"Ephesians 5:18","pista":"«Two possible fillings: one scatters, the other builds up.»"},{"pregunta":"According to Ephesians 5, how did Christ love the assembly (the church)?","opciones":["He gave himself up for her","He sent messengers from heaven","He demanded perfection before loving her","He covered her with material riches"],"dato":"Christ's love for the church is the measure of love in the home: he gave himself up for her to sanctify her.","cita":"Ephesians 5:25","versiculo":"Husbands, love your wives, even as Christ also loved the assembly and gave himself up for her,","vcita":"Ephesians 5:25","pista":"«True love is measured by self-giving.»"}],"Philippians":[{"pregunta":"What confidence does Paul express about the work God began in the Philippians?","opciones":["That he will complete it until the day of Jesus Christ","That it depends on their never failing","That it ended the day he left Philippi","That it was completed the moment he wrote the letter"],"dato":"Paul prays for them with confidence: he who began a good work in them will complete it until the day of Jesus Christ.","cita":"Philippians 1:6","versiculo":"being confident of this very thing, that he who began a good work in you will complete it until the day of Jesus Christ.","vcita":"Philippians 1:6","pista":"«God never leaves his works half-finished.»"},{"pregunta":"Complete Paul's sentence between life and death: “For to me to live is Christ, and to die is…”","opciones":["Gain","Loss","Uncertainty","A sleep without waking"],"dato":"In chains, Paul loses with neither outcome: if he lives, it is Christ; if he dies, it is gain, because departing would mean being with Christ.","cita":"Philippians 1:21","versiculo":"For to me to live is Christ, and to die is gain.","vcita":"Philippians 1:21","pista":"«A balance sheet where even losing is winning.»"},{"pregunta":"According to the hymn of Philippians 2, how far did Christ's obedience go when he humbled himself?","opciones":["To the point of death, yes, the death of the cross","To the wilderness of temptation","To his baptism in the Jordan","To his entry into Jerusalem"],"dato":"Found in human form, Christ humbled himself, becoming obedient to the point of death, yes, the death of the cross: the lowest point before his exaltation.","cita":"Philippians 2:8","versiculo":"And being found in human form, he humbled himself, becoming obedient to the point of death, yes, the death of the cross.","vcita":"Philippians 2:8","pista":"«He descended to the most humiliating place: a cross.»"},{"pregunta":"According to Philippians 2, what will every tongue confess at Christ's exaltation?","opciones":["That Jesus Christ is Lord","That Rome will rule forever","That the law saves man","That Paul was a true apostle"],"dato":"God gave him the name above every name: at his name every knee will bow and every tongue confess that Jesus Christ is Lord.","cita":"Philippians 2:11","versiculo":"and that every tongue should confess that Jesus Christ is Lord, to the glory of God the Father.","vcita":"Philippians 2:11","pista":"«Bent knees and one single universal confession.»"},{"pregunta":"How did Paul count all his former gains after knowing Christ?","opciones":["As loss, counting them as refuse in order to gain Christ","As his greatest pride before God","As merits he needed for his salvation","As an inheritance he gave to the poor"],"dato":"Circumcised, a Pharisee, blameless under the law as a persecutor: Paul counted all of that as loss for the excellency of knowing Christ Jesus.","cita":"Philippians 3:8","versiculo":"Yes most certainly, and I count all things to be a loss for the excellency of the knowledge of Christ Jesus, my Lord, for whom I suffered the loss of all things, and count them nothing but refuse, that I may gain Christ","vcita":"Philippians 3:8","pista":"«His whole résumé in the trash, for a greater treasure.»"},{"pregunta":"Forgetting what lies behind and stretching forward to what lies ahead, where does Paul press on to?","opciones":["Toward the goal, for the prize of the high calling of God","Toward Jerusalem to be judged","Toward his final retirement in Rome","Toward the synagogue of his childhood in Tarsus"],"dato":"Not claiming to have already attained it, Paul presses on toward the goal: the prize of the high calling of God in Christ Jesus.","cita":"Philippians 3:14","versiculo":"I press on toward the goal for the prize of the high calling of God in Christ Jesus.","vcita":"Philippians 3:14","pista":"«A runner who never looks back.»"},{"pregunta":"According to Philippians 4, instead of being anxious, how should we make our requests known to God?","opciones":["By prayer and petition, with thanksgiving","With repeated complaints every hour","Only at the Sunday gathering","In absolute silence, with no words"],"dato":"In nothing be anxious: requests are made known to God by prayer and petition with thanksgiving, and God's peace guards our hearts.","cita":"Philippians 4:6","versiculo":"In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.","vcita":"Philippians 4:6","pista":"«Anxiety is traded for thankful prayer.»"},{"pregunta":"What condition makes Paul's famous “I can do all things” possible?","opciones":["Through Christ, who strengthens me","With enough money saved up","Only with the Philippians' help","By sheer force of will"],"dato":"Paul had learned to be content in lack and in abundance: he can do all things, but not alone — through Christ who strengthens him.","cita":"Philippians 4:13","versiculo":"I can do all things through Christ who strengthens me.","vcita":"Philippians 4:13","pista":"«The sentence doesn't end at “can do”: the how comes next.»"}],"Colossians":[{"pregunta":"How does Paul describe Christ in Colossians 1:15?","opciones":["He is the image of the invisible God, the firstborn of all creation","He is the first of the angels created by God","He is a prophet greater than Moses and Elijah","He is high priest after the order of Aaron"],"dato":"Christ perfectly reveals the God no one can see; as firstborn of all creation, He holds supremacy over everything created.","cita":"Colossians 1:15","versiculo":"He is the image of the invisible God, the firstborn of all creation.","vcita":"Colossians 1:15","pista":"«It tells how Christ lets us see the invisible God.»"},{"pregunta":"From whom did the Colossians learn the Good News, according to the letter's greeting?","opciones":["From Epaphras, a beloved fellow servant and faithful servant of Christ","From Paul himself, who preached to them in person","From Timothy, a true child in the faith","From Barnabas, Paul's traveling companion"],"dato":"Paul had not founded that church in person: Epaphras brought them the Good News and told Paul about their love in the Spirit.","cita":"Colossians 1:7","versiculo":"even as you learned from Epaphras our beloved fellow servant, who is a faithful servant of Christ on your behalf,","vcita":"Colossians 1:7","pista":"«His name shows up again at the end of Philemon.»"},{"pregunta":"What is hidden in Christ, according to Colossians 2:3?","opciones":["All the treasures of wisdom and knowledge","The names written in the book of life","The day and hour of the end","The original tablets of the law of Moses"],"dato":"Against those who chased a secret, superior wisdom, Paul insists that every treasure of wisdom and knowledge is found in Christ.","cita":"Colossians 2:3","versiculo":"in whom all the treasures of wisdom and knowledge are hidden.","vcita":"Colossians 2:3","pista":"«Not gold: two treasures that enrich the mind.»"},{"pregunta":"What did God wipe out and nail to the cross, according to Colossians 2:14?","opciones":["The handwriting in ordinances that was against us","The stone tablets given to Moses","The veil of the temple in Jerusalem","The book of curses from Deuteronomy"],"dato":"The «handwriting» was like a debt record standing against us; God canceled it, took it out of the way, and nailed it to Christ's cross.","cita":"Colossians 2:14","versiculo":"wiping out the handwriting in ordinances which was against us. He has taken it out of the way, nailing it to the cross.","vcita":"Colossians 2:14","pista":"«Picture a debt note nailed up and canceled for good.»"},{"pregunta":"Where does Paul tell believers to set their mind in Colossians 3:2?","opciones":["On the things that are above, not on things on the earth","On the temple and its sacrifices","On promises of future riches","On the traditions of the fathers"],"dato":"Because believers were raised with Christ, their minds belong above, where Christ sits at the right hand of God.","cita":"Colossians 3:2","versiculo":"Set your mind on the things that are above, not on the things that are on the earth.","vcita":"Colossians 3:2","pista":"«The opposite of living with your eyes glued to earth.»"},{"pregunta":"What must dwell richly in believers, according to Colossians 3:16?","opciones":["The word of Christ","Fear of what people think","The wisdom of Greek philosophers","Zeal for genealogies"],"dato":"Christ's word should live richly in the believer, flowing out in mutual teaching and in singing psalms, hymns, and spiritual songs.","cita":"Colossians 3:16","versiculo":"Let the word of Christ dwell in you richly; in all wisdom teaching and admonishing one another with psalms, hymns, and spiritual songs, singing with grace in your heart to the Lord.","vcita":"Colossians 3:16","pista":"«It's what teaches and makes the heart sing.»"},{"pregunta":"What must fathers not do to their children, according to Colossians 3:21?","opciones":["Provoke them, so that they won't be discouraged","Teach them the family trade","Bring them to hear the Word","Correct them when they do wrong"],"dato":"Paul balances the children's obedience with the fathers' gentleness: constant harshness discourages and crushes a child's spirit.","cita":"Colossians 3:21","versiculo":"Fathers, don’t provoke your children, so that they won’t be discouraged.","vcita":"Colossians 3:21","pista":"«Too much harshness can snuff out a child's heart.»"},{"pregunta":"How does Paul command us to do everything we do, in Colossians 3:23?","opciones":["Heartily, as for the Lord and not for men","Only when someone important is watching","Quickly, without stopping to think","Always seeking everyone's applause first"],"dato":"A believer's work changes meaning: even when serving human masters, he is really working for the Lord, from whom he will receive the reward.","cita":"Colossians 3:23","versiculo":"And whatever you do, work heartily, as for the Lord and not for men,","vcita":"Colossians 3:23","pista":"«Even if no one sees you, there is a Lord you work for.»"},{"pregunta":"Whom does Paul call «the beloved physician» in the closing greetings?","opciones":["Luke","Timothy","Demas","Epaphras"],"dato":"Luke, author of the third Gospel and of Acts, was traveling with the imprisoned Paul and is greeted with that affectionate title.","cita":"Colossians 4:14","versiculo":"Luke the beloved physician and Demas greet you.","vcita":"Colossians 4:14","pista":"«He wrote a Gospel and also the book of Acts.»"},{"pregunta":"In which other church was the letter to the Colossians also to be read?","opciones":["In the assembly of the Laodiceans","In the church at Ephesus","In the church at Jerusalem","In the church at Antioch"],"dato":"Paul ordered that once read among the Colossians, the letter should also be read in Laodicea, and that they in turn should read the letter sent there.","cita":"Colossians 4:16","versiculo":"When this letter has been read among you, cause it to be read also in the assembly of the Laodiceans, and that you also read the letter from Laodicea.","vcita":"Colossians 4:16","pista":"«A neighboring city, one of the seven churches of Revelation.»"}],"1 Thessalonians":[{"pregunta":"What three things does Paul remember without ceasing about the Thessalonians in the letter's opening?","opciones":["Their work of faith, labor of love, and perseverance of hope","Their great wealth, their fame, and their large numbers","Their long fasts, their vigils, and their many alms","Their knowledge of the law, their eloquence, and their gifts"],"dato":"Paul opens with thanks for a church marked by faith that works, love that labors, and hope that endures with patience.","cita":"1 Thessalonians 1:3","versiculo":"remembering without ceasing your work of faith and labor of love and perseverance of hope in our Lord Jesus Christ, before our God and Father.","vcita":"1 Thessalonians 1:3","pista":"«The classic trio: faith, love, and one more that looks ahead.»"},{"pregunta":"From what did the Thessalonians turn to God when they received the Good News?","opciones":["From idols, to serve a living and true God","From country life to city life","From Jerusalem's Judaism to that of the Dispersion","From their trades, to live only off preaching"],"dato":"Their conversion was a complete turnaround: they left idols behind and turned to God, to serve Him and wait for His Son from heaven.","cita":"1 Thessalonians 1:9","versiculo":"For they themselves report concerning us what kind of a reception we had from you, and how you turned to God from idols to serve a living and true God,","vcita":"1 Thessalonians 1:9","pista":"«They left dead images to serve a living God.»"},{"pregunta":"To whom does Paul compare his gentle care for the Thessalonians in 2:7?","opciones":["To a nursing mother cherishing her own children","To a father disciplining with a firm rod","To a shepherd defending the flock from wolves","To a teacher demanding much of his disciples"],"dato":"Far from throwing his weight around, Paul was gentle among them, like a mother feeding and warming her own children.","cita":"1 Thessalonians 2:7","versiculo":"But we were gentle among you, like a nursing mother cherishes her own children.","vcita":"1 Thessalonians 2:7","pista":"«Think of the tenderest care inside a family.»"},{"pregunta":"Why did Paul work night and day while preaching in Thessalonica?","opciones":["So that he might not burden any of them","To grow rich from his tentmaking trade","Because Roman law required it of Jews","To flee from the city authorities"],"dato":"Paul supported himself with his own manual work so the new believers would not be financially burdened while he preached the Good News to them.","cita":"1 Thessalonians 2:9","versiculo":"For you remember, brothers, our labor and travail; for working night and day, that we might not burden any of you, we preached to you the Good News of God.","vcita":"1 Thessalonians 2:9","pista":"«He didn't want the Good News to cost them a single coin.»"},{"pregunta":"Whom did Paul send back to Thessalonica to establish and comfort the believers concerning their faith?","opciones":["Timothy, his brother and God's servant in the Good News of Christ","Titus, to set the church in order","Luke, the beloved physician","John Mark, Barnabas's cousin"],"dato":"Unable to bear the suspense any longer, Paul stayed alone in Athens and sent Timothy to strengthen the persecuted church.","cita":"1 Thessalonians 3:2","versiculo":"and sent Timothy, our brother and God’s servant in the Good News of Christ, to establish you and to comfort you concerning your faith,","vcita":"1 Thessalonians 3:2","pista":"«He's the young recipient of two pastoral letters.»"},{"pregunta":"What kind of life does Paul urge the Thessalonians to pursue in 4:11?","opciones":["To lead a quiet life, mind their own business, and work with their own hands","To withdraw completely to the desert","To spend the whole day debating in the squares","To stop working and be supported entirely by the church"],"dato":"Against restless idleness, Paul commands a quiet life, each one minding his own business and earning his bread with his own hands.","cita":"1 Thessalonians 4:11","versiculo":"and that you make it your ambition to lead a quiet life, and to do your own business, and to work with your own hands, even as we instructed you,","vcita":"1 Thessalonians 4:11","pista":"«Quietness, your own business, and busy hands.»"},{"pregunta":"According to 1 Thessalonians 4:16, who will rise first when the Lord descends from heaven?","opciones":["The dead in Christ","Those who are alive at His coming","The martyrs of the last days","The apostles and prophets"],"dato":"With a shout, the voice of the archangel, and God's trumpet, the Lord will descend; the dead in Christ rise first, then the living are caught up with them.","cita":"1 Thessalonians 4:16","versiculo":"For the Lord himself will descend from heaven with a shout, with the voice of the archangel and with God’s trumpet. The dead in Christ will rise first,","vcita":"1 Thessalonians 4:16","pista":"«Those asleep in Christ go first.»"},{"pregunta":"How will the day of the Lord come, according to 1 Thessalonians 5:2?","opciones":["Like a thief in the night","Announced by signs for forty days","After a great trumpet heard for years","Only after everyone is expecting it"],"dato":"His coming will surprise a world saying «peace and safety»; so the believer must watch and be sober, not asleep.","cita":"1 Thessalonians 5:2","versiculo":"For you yourselves know well that the day of the Lord comes like a thief in the night.","vcita":"1 Thessalonians 5:2","pista":"«It arrives when nobody is expecting it.»"},{"pregunta":"What is the very short command of 1 Thessalonians 5:17?","opciones":["Pray without ceasing","Fast every week","Sing at all times","Read without resting"],"dato":"In the middle of a string of short exhortations, Paul sums up a life of constant prayer in just three words.","cita":"1 Thessalonians 5:17","versiculo":"Pray without ceasing.","vcita":"1 Thessalonians 5:17","pista":"«It's talking with God... always, without stopping.»"},{"pregunta":"What must we not quench, according to 1 Thessalonians 5:19?","opciones":["The Spirit","The lamp of the sanctuary","Zeal for traditions","The memory of the martyrs"],"dato":"The picture is of a fire that must not be smothered: do not choke the work or the manifestations of the Holy Spirit.","cita":"1 Thessalonians 5:19","versiculo":"Don’t quench the Spirit.","vcita":"1 Thessalonians 5:19","pista":"«It's a flame that must keep burning in the church.»"},{"pregunta":"What does Paul command us to test, and what to hold firmly, in 5:21?","opciones":["Test all things, and hold firmly that which is good","Accept everything without asking questions","Reject everything new on principle","Test only what the elders say"],"dato":"Neither gullibility nor contempt: everything is put to the test, and what proves good is kept and held fast.","cita":"1 Thessalonians 5:21","versiculo":"Test all things, and hold firmly that which is good.","vcita":"1 Thessalonians 5:21","pista":"«First you test it... then you keep what is worth keeping.»"}],"2 Thessalonians":[{"pregunta":"What does Paul boast about concerning the Thessalonians in the assemblies of God?","opciones":["Their perseverance and faith in all their persecutions and afflictions","How quickly they built their temple","That they had never suffered for the Good News","Their generous gifts to the churches of Judea"],"dato":"Paul brags about them to other churches: persecuted and afflicted, they stood firm with perseverance and faith.","cita":"2 Thessalonians 1:4","versiculo":"so that we ourselves boast about you in the assemblies of God for your perseverance and faith in all your persecutions and in the afflictions which you endure.","vcita":"2 Thessalonians 1:4","pista":"«What stood out wasn't their comfort, but their firmness while suffering.»"},{"pregunta":"According to 2 Thessalonians 1:6, what is a righteous thing for God to do to those who afflict His people?","opciones":["Repay them with affliction","Forget their evil completely","Send them to preach in other lands","Take away only their riches"],"dato":"God's justice comforts the afflicted: He will repay with affliction those who now unjustly trouble them.","cita":"2 Thessalonians 1:6","versiculo":"For it is a righteous thing with God to repay affliction to those who afflict you,","vcita":"2 Thessalonians 1:6","pista":"«Retribution measured out in the same coin of suffering.»"},{"pregunta":"Who must be revealed before the coming of the Lord, together with the rebellion, according to 2:3?","opciones":["The man of sin, the son of destruction","A new prophet sent from Jerusalem","The angel Michael with his armies","The king of the north with his empire"],"dato":"Paul corrects the idea that the day of the Lord had already come: first the rebellion will come, and the man of sin will be revealed.","cita":"2 Thessalonians 2:3","versiculo":"Let no one deceive you in any way. For it will not be unless the rebellion comes first, and the man of sin is revealed, the son of destruction.","vcita":"2 Thessalonians 2:3","pista":"«He carries two sinister titles in a single verse.»"},{"pregunta":"What is already at work in Paul's own days, according to 2 Thessalonians 2:7?","opciones":["The mystery of lawlessness","The rebuilding of the temple","The mark of the beast on foreheads","The judgment of the nations"],"dato":"Final wickedness does not appear out of nowhere: its «mystery» is already secretly at work, though restrained by the one who now holds it back.","cita":"2 Thessalonians 2:7","versiculo":"For the mystery of lawlessness already works. Only there is one who restrains now, until he is taken out of the way.","vcita":"2 Thessalonians 2:7","pista":"«It works in secret, like a mystery, already now.»"},{"pregunta":"How will the Lord Jesus destroy the lawless one at His coming, according to 2:8?","opciones":["With the breath of His mouth and by the manifestation of His coming","With an army of ten thousand armed angels","With fire falling from heaven on the earth","By locking him in a sealed pit for a thousand years first"],"dato":"The lawless one does not fall in an even fight: the mere breath of the Lord's mouth and the brightness of His appearing will destroy him.","cita":"2 Thessalonians 2:8","versiculo":"Then the lawless one will be revealed, whom the Lord will kill with the breath of his mouth and destroy by the manifestation of his coming;","vcita":"2 Thessalonians 2:8","pista":"«He needs no sword: His breath and His presence are enough.»"},{"pregunta":"What must the brothers hold fast to, according to 2 Thessalonians 2:15?","opciones":["The traditions they were taught, whether by word or by letter","The customs inherited from the Pharisees","The money gathered for the poor of Jerusalem","The names of the false teachers"],"dato":"Facing doctrinal confusion, the order is to stand firm and keep the apostolic teaching received both by spoken word and by letter.","cita":"2 Thessalonians 2:15","versiculo":"So then, brothers, stand firm and hold the traditions which you were taught by us, whether by word or by letter.","vcita":"2 Thessalonians 2:15","pista":"«What was taught is not up for trade: hold it firm.»"},{"pregunta":"What will the Lord, who is faithful, do according to 2 Thessalonians 3:3?","opciones":["Establish the believers and guard them from the evil one","Take them out of the city immediately","Give them riches so they never work again","Reveal to them the exact day of His coming"],"dato":"Even when men are unfaithful, the Lord is faithful: He establishes His own and protects them from the evil one.","cita":"2 Thessalonians 3:3","versiculo":"But the Lord is faithful, who will establish you and guard you from the evil one.","vcita":"2 Thessalonians 3:3","pista":"«His faithfulness does two things: establishes and guards.»"},{"pregunta":"Into what two things does Paul pray the Lord would direct the Thessalonians' hearts?","opciones":["Into God's love and into the perseverance of Christ","Into Greek wisdom and the law of Moses","Into fear of men and worldly prudence","Into spiritual riches and total rest"],"dato":"Paul asks for hearts directed, like a straight road, into the love of God and into the patient perseverance of Christ.","cita":"2 Thessalonians 3:5","versiculo":"May the Lord direct your hearts into God’s love and into the perseverance of Christ.","vcita":"2 Thessalonians 3:5","pista":"«A well-directed heart points to love... and to Someone's perseverance.»"},{"pregunta":"What was Paul's rule about anyone not willing to work?","opciones":["Don't let him eat","Let him eat only half a ration","Let the elders support him","Let him fast until he changes"],"dato":"Paul had commanded it while he was with them: whoever refuses to work has no right to demand food from other people's labor.","cita":"2 Thessalonians 3:10","versiculo":"For even when we were with you, we commanded you this: “If anyone is not willing to work, don’t let him eat.”","vcita":"2 Thessalonians 3:10","pista":"«It's this letter's most famous line about work.»"},{"pregunta":"What were some disorderly Thessalonians busy doing, according to 3:11?","opciones":["Working at nothing, but being busybodies","Trading through the northern ports","Teaching Gentile doctrines","Building a house of prayer"],"dato":"They did no work of their own, yet kept meddling in everyone else's: plenty of curiosity and no fruit at all.","cita":"2 Thessalonians 3:11","versiculo":"For we hear of some who walk among you in rebellion, who don’t work at all, but are busybodies.","vcita":"2 Thessalonians 3:11","pista":"«Idle hands, but eyes and ears in everyone else's house.»"},{"pregunta":"What must the brothers not grow weary of, according to 2 Thessalonians 3:13?","opciones":["Doing what is right","Correcting the idle ones","Waiting for Paul's next letter","Gathering offerings every week"],"dato":"Even surrounded by disorder, the faithful must not give up the constant practice of doing good.","cita":"2 Thessalonians 3:13","versiculo":"But you, brothers, don’t be weary in doing what is right.","vcita":"2 Thessalonians 3:13","pista":"«Weariness is no excuse to stop doing... what is right.»"},{"pregunta":"By what title does Paul call the Lord in the closing blessing of 3:16?","opciones":["The Lord of peace","The Lord of the heavenly hosts","The God of all vengeance","The Lord of the harvest"],"dato":"The letter dealing with unrest and disorder closes with the «Lord of peace» who gives peace at all times and in all ways.","cita":"2 Thessalonians 3:16","versiculo":"Now may the Lord of peace himself give you peace at all times in all ways. The Lord be with you all.","vcita":"2 Thessalonians 3:16","pista":"«His title here is exactly what the restless need.»"}],"1 Timothy":[{"pregunta":"What does Paul call Timothy in the greeting of this letter?","opciones":["My true child in faith","My fellow soldier","My brother in the flesh","My disciple since childhood"],"dato":"Timothy was not Paul's physical son, but his spiritual one: Paul won him to the Good News and shaped him as a close co-worker.","cita":"1 Timothy 1:2","versiculo":"to Timothy, my true child in faith: Grace, mercy, and peace from God our Father and Christ Jesus our Lord.","vcita":"1 Timothy 1:2","pista":"«They don't share blood; they share something stronger: faith.»"},{"pregunta":"According to the «faithful saying» of 1 Timothy 1:15, why did Christ Jesus come into the world?","opciones":["To save sinners, of whom Paul calls himself chief","To found a political kingdom in Jerusalem","To teach only the pious Jews","To condemn sinners without remedy"],"dato":"Paul presents his own case as proof: if Christ saved him, the chief of sinners, there is hope for anyone.","cita":"1 Timothy 1:15","versiculo":"The saying is faithful and worthy of all acceptance, that Christ Jesus came into the world to save sinners, of whom I am chief.","vcita":"1 Timothy 1:15","pista":"«And the apostle puts himself at the front of the line.»"},{"pregunta":"What does God desire for all people, according to 1 Timothy 2:4?","opciones":["That they be saved and come to full knowledge of the truth","That they all withdraw to live in deserts","That they keep the feasts of Israel","That they first pay for their sins"],"dato":"God's saving desire is universal: it reaches all people, who must come to know the truth of the Good News.","cita":"1 Timothy 2:4","versiculo":"who desires all people to be saved and come to full knowledge of the truth.","vcita":"1 Timothy 2:4","pista":"«Two desires joined together: salvation and knowledge of something.»"},{"pregunta":"Who is the one mediator between God and men, according to 1 Timothy 2:5?","opciones":["The man Christ Jesus","The high priest of Jerusalem","The apostle Paul","The angel Gabriel"],"dato":"There is one God and one mediator: the man Christ Jesus, who gave Himself as a ransom for all.","cita":"1 Timothy 2:5","versiculo":"For there is one God and one mediator between God and men, the man Christ Jesus,","vcita":"1 Timothy 2:5","pista":"«Only one stands in the middle between God and mankind.»"},{"pregunta":"What must an overseer be, according to the list in 1 Timothy 3:2?","opciones":["Without reproach, the husband of one wife, temperate, and good at teaching","Rich, of noble family, and a fine street orator","Single, always traveling, and without a home of his own","Advanced in years, even if unable to teach"],"dato":"The overseer's qualifications are mostly about character: blameless, faithful at home, temperate, sensible, hospitable, and able to teach.","cita":"1 Timothy 3:2","versiculo":"The overseer therefore must be without reproach, the husband of one wife, temperate, sensible, modest, hospitable, good at teaching;","vcita":"1 Timothy 3:2","pista":"«The list starts with his reputation and his own household.»"},{"pregunta":"What is the great mystery of godliness confessed in 1 Timothy 3:16?","opciones":["God was revealed in the flesh","The secret location of the ark of the covenant","The hidden name of the beast","The concealed date of the resurrection"],"dato":"The hymn of 3:16 sums up the Good News: God revealed in the flesh, justified in the spirit, seen by angels, preached among the nations, believed on in the world, received up in glory.","cita":"1 Timothy 3:16","versiculo":"Without controversy, the mystery of godliness is great: God was revealed in the flesh, justified in the spirit, seen by angels, preached among the nations, believed on in the world, and received up in glory.","vcita":"1 Timothy 3:16","pista":"«God Himself became visible... and that is the great mystery.»"},{"pregunta":"What has value in all things and holds promise for this life and the next, according to 4:8?","opciones":["Godliness","Bodily exercise","The study of languages","The practice of fasts"],"dato":"Paul does not despise physical exercise, but he compares: it has some value; godliness, by contrast, has value in all things and a double promise.","cita":"1 Timothy 4:8","versiculo":"For bodily exercise has some value, but godliness has value in all things, having the promise of the life which is now and of that which is to come.","vcita":"1 Timothy 4:8","pista":"«It pays off in this life... and in the one to come.»"},{"pregunta":"What does Paul command Timothy about his youth in 4:12?","opciones":["Let no one despise it, being an example to the believers","Hide it by pretending to be older","Wait until he is an elder to begin teaching","Use it only to travel and visit churches"],"dato":"Young Timothy's authority would not come from his age, but from his example: in word, conduct, love, faith, and purity.","cita":"1 Timothy 4:12","versiculo":"Let no man despise your youth; but be an example to those who believe, in word, in your way of life, in love, in spirit, in faith, and in purity.","vcita":"1 Timothy 4:12","pista":"«The answer to those who look down on his youth is one word: example.»"},{"pregunta":"What is a root of all kinds of evil, according to 1 Timothy 6:10?","opciones":["The love of money","Extreme poverty","Working with one's hands","The desire to learn"],"dato":"Not money itself, but the love of money: in their greed for it, some were led astray from the faith and pierced themselves with many sorrows.","cita":"1 Timothy 6:10","versiculo":"For the love of money is a root of all kinds of evil. Some have been led astray from the faith in their greed, and have pierced themselves through with many sorrows.","vcita":"1 Timothy 6:10","pista":"«It's not the coin: it's the disordered love for it.»"}],"2 Timothy":[{"pregunta":"In whom did the sincere faith that was in Timothy live first?","opciones":["In his grandmother Lois and his mother Eunice","In his Greek father and his aunt from Lystra","In the prophetess Anna and her sister","In Priscilla and Aquila, his teachers"],"dato":"Paul remembers a faith handed down at home: first in grandmother Lois, then in mother Eunice, and he is persuaded it lives in Timothy too.","cita":"2 Timothy 1:5","versiculo":"having been reminded of the sincere faith that is in you, which lived first in your grandmother Lois and your mother Eunice and, I am persuaded, in you also.","vcita":"2 Timothy 1:5","pista":"«Two women of his own family, from two generations.»"},{"pregunta":"What does Paul remind Timothy to stir up in 1:6?","opciones":["The gift of God which is in him through the laying on of Paul's hands","The study of Roman laws","Zeal against the Jews of Ephesus","The desire to return home to Lystra"],"dato":"The gift received must not grow cold: like a fire covered with ashes, Timothy had to stir it up and keep it burning.","cita":"2 Timothy 1:6","versiculo":"For this cause, I remind you that you should stir up the gift of God which is in you through the laying on of my hands.","vcita":"2 Timothy 1:6","pista":"«It's like fanning the embers of a fire you already have.»"},{"pregunta":"According to 2 Timothy 1:7, what spirit did God NOT give us, and what did He give?","opciones":["Not a spirit of fear, but of power, love, and self-control","Not of courage, but of human prudence","Not of speech, but of silence and retreat","Not of joy, but of sadness and mourning"],"dato":"Facing the temptation to be ashamed of the Good News, Paul recalls that the Spirit given does not produce cowardice, but power, love, and self-control.","cita":"2 Timothy 1:7","versiculo":"For God didn’t give us a spirit of fear, but of power, love, and self-control.","vcita":"2 Timothy 1:7","pista":"«The spirit given produces power, affection, and self-control.»"},{"pregunta":"What does Paul affirm with full persuasion in 2 Timothy 1:12, while suffering for the Good News?","opciones":["That he knows whom he has believed, and that God is able to guard what he committed to Him","That he will soon walk free from the Roman prison","That believers will never face afflictions","That Timothy will be Jerusalem's next apostle"],"dato":"In chains and unashamed, Paul's security is not in his luck, but in the Person he believed and in His power to guard what was entrusted to Him.","cita":"2 Timothy 1:12","versiculo":"For this cause I also suffer these things. Yet I am not ashamed, for I know him whom I have believed, and I am persuaded that he is able to guard that which I have committed to him against that day.","vcita":"2 Timothy 1:12","pista":"«His confidence has a name: he knows Whom he believed.»"},{"pregunta":"How must the workman present himself before God, according to 2 Timothy 2:15?","opciones":["Approved, a workman who doesn't need to be ashamed, properly handling the Word of Truth","With many titles and letters of recommendation","Having first gained riches and honors","Silent, never daring to teach"],"dato":"The approved workman gives diligence and handles the word of truth rightly, like one who cuts straight and is not ashamed of his work.","cita":"2 Timothy 2:15","versiculo":"Give diligence to present yourself approved by God, a workman who doesn’t need to be ashamed, properly handling the Word of Truth.","vcita":"2 Timothy 2:15","pista":"«A good workman: work approved by God and the word handled straight.»"},{"pregunta":"What does Paul affirm about every Scripture in 2 Timothy 3:16?","opciones":["That it is God-breathed and profitable for teaching, reproof, correction, and instruction in righteousness","That it is only for the priests of the temple","That it was written only for the ancients","That it should be read only at solemn feasts"],"dato":"The whole Scripture has a divine origin and a complete practical use: it teaches, reproves, corrects, and trains in righteousness.","cita":"2 Timothy 3:16","versiculo":"Every Scripture is God-breathed and profitable for teaching, for reproof, for correction, and for instruction in righteousness,","vcita":"2 Timothy 3:16","pista":"«All of it comes from God... and all of it is profitable.»"},{"pregunta":"What must Timothy preach, and when must he be urgent, according to the solemn charge of 4:2?","opciones":["The word; in season and out of season","Only comforts, whenever people ask for them","The genealogies, at every meeting","His experiences, once a year"],"dato":"The charge is urgent and constant: preach the word, being ready at every occasion, welcome or not, reproving, rebuking, and exhorting with patience and teaching.","cita":"2 Timothy 4:2","versiculo":"preach the word; be urgent in season and out of season; reprove, rebuke, and exhort with all patience and teaching.","vcita":"2 Timothy 4:2","pista":"«Whether the moment suits or not: the word gets preached.»"},{"pregunta":"What three things does Paul declare about himself as his departure nears, in 4:7?","opciones":["He fought the good fight, finished the course, and kept the faith","He founded three churches, wrote three letters, and won his freedom three times","He traveled by sea, by land, and across the whole desert","He left disciples, left letters, and left a great fortune"],"dato":"The apostle sums up his life with three images: the fight fought, the race finished, and the faith kept intact to the end.","cita":"2 Timothy 4:7","versiculo":"I have fought the good fight. I have finished the course. I have kept the faith.","vcita":"2 Timothy 4:7","pista":"«A fighter, a runner, and a faithful keeper: all in one sentence.»"},{"pregunta":"Whom must Timothy bring with him, because he is useful to Paul for service?","opciones":["Mark","Demas","Crescens","Tychicus"],"dato":"The Mark who years earlier had withdrawn from the team is now asked for by name: restored, he is useful for service. Luke was the only one still with Paul.","cita":"2 Timothy 4:11","versiculo":"Only Luke is with me. Take Mark and bring him with you, for he is useful to me for service.","vcita":"2 Timothy 4:11","pista":"«He got a second chance: he once withdrew, now he is useful.»"}],"Titus":[{"pregunta":"Why did Paul leave Titus in Crete?","opciones":["To set in order the things that were lacking and appoint elders in every city","To collect the island's offerings and take them to Rome","To hide from the authorities for a while","To learn the language and customs of the Cretans"],"dato":"Titus stayed with a mission of order: complete what was lacking in the young churches of the island and appoint elders in every city.","cita":"Titus 1:5","versiculo":"I left you in Crete for this reason, that you would set in order the things that were lacking and appoint elders in every city, as I directed you—","vcita":"Titus 1:5","pista":"«His task was organizational: set in order and appoint leaders.»"},{"pregunta":"How did one of the Cretans' own prophets describe them, as quoted by Paul?","opciones":["Always liars, evil beasts, and idle gluttons","Great sailors, sweet poets, and brave men","Wise philosophers, just and hospitable","Humble shepherds, faithful and hardworking"],"dato":"Paul quotes the Cretan poet Epimenides against his own people; and adds, «this testimony is true». The church had to be sound in the faith within that culture.","cita":"Titus 1:12","versiculo":"One of them, a prophet of their own, said, “Cretans are always liars, evil beasts, and idle gluttons.”","vcita":"Titus 1:12","pista":"«It's not an enemy saying it: it's a prophet of their own.»"},{"pregunta":"According to Titus 1:15, to whom are all things pure?","opciones":["To the pure","To those who keep the feasts","To the priests only","To those who eat no meat"],"dato":"Purity does not depend on outward rites: to the pure all things are pure; to the defiled and unbelieving, nothing is pure — even their mind and conscience are defiled.","cita":"Titus 1:15","versiculo":"To the pure, all things are pure, but to those who are defiled and unbelieving, nothing is pure; but both their mind and their conscience are defiled.","vcita":"Titus 1:15","pista":"«True cleanness starts on the inside, not on the plate.»"},{"pregunta":"What do some who profess to know God do by their deeds, according to Titus 1:16?","opciones":["They deny Him, being unfit for any good work","They honor Him in everything they undertake","They hide Him only out of fear of the Romans","They serve Him secretly, at night"],"dato":"There is a fatal contradiction: with the mouth they know God, but their conduct denies Him; they are unfit for any good work.","cita":"Titus 1:16","versiculo":"They profess that they know God, but by their deeds they deny him, being abominable, disobedient, and unfit for any good work.","vcita":"Titus 1:16","pista":"«Their words say one thing and their deeds say the opposite.»"},{"pregunta":"What must the older women train the young wives in, according to Titus 2:4?","opciones":["To love their husbands and to love their children","To preach in the squares of every city","To manage the business of the Gentiles","To memorize the genealogies of Israel"],"dato":"Sound teaching is also passed on at home: the older women train the younger ones in prudence and in love for their husbands and children.","cita":"Titus 2:4","versiculo":"that they may train the young wives to love their husbands, to love their children,","vcita":"Titus 2:4","pista":"«The main lesson revolves around her own household.»"},{"pregunta":"What appeared, bringing salvation to all men, according to Titus 2:11?","opciones":["The grace of God","The renewed law of Moses","An emperor's edict","A sign in the sky over Crete"],"dato":"God's grace appeared like a light for everyone: it does not save a small group only, but brings salvation to all men.","cita":"Titus 2:11","versiculo":"For the grace of God has appeared, bringing salvation to all men,","vcita":"Titus 2:11","pista":"«No new law appeared: His unmerited favor did.»"},{"pregunta":"What hope are we looking for, according to Titus 2:13?","opciones":["The blessed hope and appearing of the glory of our great God and Savior, Jesus Christ","The arrival of a new apostle in Crete","The rebuilding of the temple in Jerusalem","A general pardon from the Roman emperor"],"dato":"The believer lives looking forward: he awaits the glorious appearing of Jesus Christ, here called our great God and Savior.","cita":"Titus 2:13","versiculo":"looking for the blessed hope and appearing of the glory of our great God and Savior, Jesus Christ,","vcita":"Titus 2:13","pista":"«A blessed hope... and a glorious appearing.»"},{"pregunta":"Why did Christ give Himself for us, according to Titus 2:14?","opciones":["To redeem us from all iniquity and purify for Himself a people of His own, zealous for good works","To enrich us with earthly goods","To free us from all work and effort","To found a kingdom only on the island of Crete"],"dato":"Redemption does not end with forgiveness: Christ gave Himself to purify a people who belong to Him and burn with zeal for good works.","cita":"Titus 2:14","versiculo":"who gave himself for us, that he might redeem us from all iniquity and purify for himself a people for his own possession, zealous for good works.","vcita":"Titus 2:14","pista":"«His people are known by one mark: zeal for doing good.»"},{"pregunta":"How did God save us, according to Titus 3:5?","opciones":["Not by our works of righteousness, but by His mercy, through the washing of regeneration and renewing by the Holy Spirit","By the works of righteousness we had stored up","By the merits of our believing parents","By perfectly keeping the feasts and Sabbaths"],"dato":"Salvation was no prize for our works: it was pure mercy, worked by the new birth and the renewing of the Holy Spirit.","cita":"Titus 3:5","versiculo":"not by works of righteousness which we did ourselves, but according to his mercy, he saved us through the washing of regeneration and renewing by the Holy Spirit,","vcita":"Titus 3:5","pista":"«Two words sum it up: mercy, not merits.»"},{"pregunta":"What must Titus shun, according to Titus 3:9?","opciones":["Foolish questionings, genealogies, strife, and disputes about the law","All contact with the port's sailors","Preaching to the island's Gentiles","All reading of the ancient prophets"],"dato":"Such arguments are «unprofitable and vain»: they consume the energy that should be spent on good works and sound teaching.","cita":"Titus 3:9","versiculo":"but shun foolish questionings, genealogies, strife, and disputes about the law; for they are unprofitable and vain.","vcita":"Titus 3:9","pista":"«Word fights that profit nobody.»"},{"pregunta":"In which city had Paul determined to spend the winter?","opciones":["Nicopolis","Corinth","Alexandria","Tarsus, his hometown"],"dato":"Paul asks Titus that, once his replacement arrives (Artemas or Tychicus), he make every effort to come to him at Nicopolis, where he would winter.","cita":"Titus 3:12","versiculo":"When I send Artemas to you, or Tychicus, be diligent to come to me to Nicopolis, for I have determined to winter there.","vcita":"Titus 3:12","pista":"«A Greek city whose name means «city of victory».»"}],"Philemon":[{"pregunta":"How does Paul introduce himself at the opening of this letter, instead of calling himself an apostle?","opciones":["A prisoner of Christ Jesus","Apostle to the Gentiles","Servant of the church in Rome","Elder of Jerusalem"],"dato":"In this personal letter Paul softens his authority: he signs not as an apostle, but as a prisoner of Christ Jesus, together with brother Timothy.","cita":"Philemon 1:1","versiculo":"Paul, a prisoner of Christ Jesus, and Timothy our brother, to Philemon, our beloved fellow worker,","vcita":"Philemon 1:1","pista":"«His title here is not his office, but his condition in prison.»"},{"pregunta":"What does Paul call Archippus in the letter's greeting?","opciones":["Our fellow soldier","My child in the faith","The beloved physician","Steward of the church"],"dato":"The greeting reaches Philemon, beloved Apphia, Archippus — called a fellow soldier — and the assembly meeting in Philemon's house.","cita":"Philemon 1:2","versiculo":"to the beloved Apphia, to Archippus our fellow soldier, and to the assembly in your house:","vcita":"Philemon 1:2","pista":"«The title sounds like a soldier fighting in the same troop.»"},{"pregunta":"What two things does Paul hear about Philemon and give thanks for?","opciones":["His love, and the faith he has toward the Lord Jesus and toward all the saints","His wealth and his generosity to the poor of Judea","His knowledge and his zeal for the law","His many journeys and his letters to the churches"],"dato":"Philemon's fame was twofold: love in action and firm faith, both toward the Lord Jesus and toward all the saints.","cita":"Philemon 1:5","versiculo":"hearing of your love and of the faith which you have toward the Lord Jesus and toward all the saints,","vcita":"Philemon 1:5","pista":"«One looks to Christ and the other pours out on the saints.»"},{"pregunta":"What effect did Philemon's love have on the saints, according to verse 7?","opciones":["Through him, the hearts of the saints had been refreshed","The saints decided to fast every week","The saints gathered money for Rome","The saints named him bishop of the city"],"dato":"Philemon was a refreshment to the believers: his generous love comforted and refreshed the hearts of the saints, and that gave Paul much joy and comfort.","cita":"Philemon 1:7","versiculo":"For we have much joy and comfort in your love, because the hearts of the saints have been refreshed through you, brother.","vcita":"Philemon 1:7","pista":"«His kindness worked like a glass of fresh water for everyone.»"},{"pregunta":"How does Paul describe himself as he makes his appeal in verse 9?","opciones":["Paul, the aged, and also a prisoner of Jesus Christ","A young apostle full of freedom in Christ","A Pharisee of Pharisees, zealous for the law","A Roman citizen awaiting trial"],"dato":"Paul could command with apostolic authority, but he prefers to appeal for love's sake, presenting himself as an old man who is also a prisoner for Jesus Christ.","cita":"Philemon 1:9","versiculo":"yet for love’s sake I rather appeal to you, being such a one as Paul, the aged, but also a prisoner of Jesus Christ.","vcita":"Philemon 1:9","pista":"«He appeals not to his rank, but to his age and his chains.»"},{"pregunta":"Whom does Paul call «my child, whom I have become the father of in my chains»?","opciones":["Onesimus","Titus","Archippus","Apollos"],"dato":"Onesimus, Philemon's runaway slave, came to know the Good News beside the imprisoned Paul and became like a son to him in the faith.","cita":"Philemon 1:10","versiculo":"I appeal to you for my child Onesimus, whom I have become the father of in my chains,","vcita":"Philemon 1:10","pista":"«He is the slave for whom Paul writes this whole letter.»"},{"pregunta":"What play on words does Paul make with Onesimus in verse 11?","opciones":["That he once was useless, but now is useful to Philemon and to Paul","That he once was swift, but now walks slowly","That he once was rich, but now serves as a poor man","That he once was a Pharisee, and now is a tax collector"],"dato":"«Onesimus» means «useful» or «profitable»: Paul plays with his name — the runaway who seemed useless has returned transformed and now truly lives up to his name.","cita":"Philemon 1:11","versiculo":"who once was useless to you, but now is useful to you and to me.","vcita":"Philemon 1:11","pista":"«His very name means «useful»... and at last he is.»"},{"pregunta":"How must Philemon receive Onesimus now, according to verse 16?","opciones":["No longer as a slave, but more than a slave: a beloved brother","As a slave punished with double labor","As a guest who pays for his lodging","As a stranger who is only greeted"],"dato":"The Good News changed the relationship: Onesimus comes home, but no longer merely as a slave; in the flesh and in the Lord, he is a beloved brother.","cita":"Philemon 1:16","versiculo":"no longer as a slave, but more than a slave, a beloved brother—especially to me, but how much rather to you, both in the flesh and in the Lord.","vcita":"Philemon 1:16","pista":"«He returns with the same name, but with a new relationship: brother.»"},{"pregunta":"If Onesimus wronged Philemon at all or owes him anything, what does Paul ask?","opciones":["To put it to his account, because he will repay it","To charge it back with double interest","To forgive it with no one paying anything","To sell Onesimus to settle the debt"],"dato":"Paul signs a personal note: «if he has wronged you at all or owes you anything, put that to my account», adding in his own handwriting that he will repay it.","cita":"Philemon 1:18","versiculo":"But if he has wronged you at all or owes you anything, put that to my account.","vcita":"Philemon 1:18","pista":"«The apostle offers his own purse as the guarantee.»"},{"pregunta":"What does Paul ask to be prepared for him at Philemon's house, according to verse 22?","opciones":["A guest room, for he hopes to be restored to them through their prayers","A welcome feast with the whole church","A ship to continue his journey to Spain","Copies of the letter for the neighboring churches"],"dato":"With delicacy and gentle pressure at once, Paul announces his visit: he hopes to be set free through their prayers, and expects to stay at Philemon's house.","cita":"Philemon 1:22","versiculo":"Also, prepare a guest room for me, for I hope that through your prayers I will be restored to you.","vcita":"Philemon 1:22","pista":"«Start preparing the guest room... the apostle is on his way.»"},{"pregunta":"Who greets Philemon as Paul's «fellow prisoner» in Christ Jesus?","opciones":["Epaphras","Aristarchus","Demas","Tychicus"],"dato":"Epaphras, the same man who had carried the Good News to Colossae, was then sharing prison with Paul and heads the letter's closing greetings.","cita":"Philemon 1:23","versiculo":"Epaphras, my fellow prisoner in Christ Jesus, greets you,","vcita":"Philemon 1:23","pista":"«He is the faithful servant who evangelized the Colossians.»"}],"Hebrews":[{"pregunta":"According to Hebrews 1, through whom has God spoken to us in these last days?","opciones":["Through his Son, whom he appointed heir of all things","Through the prophets, as in the ancient times","Through dreams given to the priests","Through the voice of angels on the mountain"],"dato":"Long ago God spoke through the prophets; in these last days he has spoken through his Son, through whom he also made the worlds.","cita":"Hebrews 1:2","versiculo":"has at the end of these days spoken to us by his Son, whom he appointed heir of all things, through whom also he made the worlds.","vcita":"Hebrews 1:2","pista":"«No longer just a messenger: the Heir himself.»"},{"pregunta":"To what does Hebrews compare the word of God, because it is living and active?","opciones":["To a two-edged sword","To a hammer that breaks the rock","To a lamp in the darkness","To a river of living waters"],"dato":"The word of God is living and active, sharper than any two-edged sword: it pierces to the dividing of soul and spirit, and discerns the thoughts and intentions of the heart.","cita":"Hebrews 4:12","versiculo":"For the word of God is living and active, and sharper than any two-edged sword, piercing even to the dividing of soul and spirit, of both joints and marrow, and is able to discern the thoughts and intentions of the heart.","vcita":"Hebrews 4:12","pista":"«It cuts on both sides and reaches the marrow.»"},{"pregunta":"What does Hebrews 4:15 affirm about our high priest?","opciones":["That he was tempted in all points like we are, yet without sin","That he never knew human weakness","That he intercedes only for those who do not sin","That he was an angel sent to earth"],"dato":"We do not have a high priest who cannot be touched with the feeling of our infirmities: he was tempted in all points like we are, yet without sin.","cita":"Hebrews 4:15","versiculo":"For we don’t have a high priest who can’t be touched with the feeling of our infirmities, but one who has been in all points tempted like we are, yet without sin.","vcita":"Hebrews 4:15","pista":"«Tested in everything… and came out clean.»"},{"pregunta":"In interpreting Melchizedek's name, what does it mean that he is “king of Salem”?","opciones":["King of peace","King of righteousness","King of the priests","King of Jerusalem"],"dato":"Melchizedek is first, by interpretation, king of righteousness, and then also king of Salem, which means king of peace; Abraham divided him a tenth of all.","cita":"Hebrews 7:2","versiculo":"to whom also Abraham divided a tenth part of all (being first, by interpretation, “king of righteousness”, and then also “king of Salem”, which means “king of peace”,","vcita":"Hebrews 7:2","pista":"«Salem echoes shalom: think of the opposite of war.»"},{"pregunta":"Why is Christ able to save to the uttermost those who draw near to God through him?","opciones":["Because he lives forever to make intercession for them","Because his priesthood is after the order of Aaron","Because he offered sacrifices every year","Because he never left the earthly sanctuary"],"dato":"Christ is able to save to the uttermost those who draw near to God through him, seeing that he lives forever to make intercession for them: his priesthood is never interrupted by death.","cita":"Hebrews 7:25","versiculo":"Therefore he is also able to save to the uttermost those who draw near to God through him, seeing that he lives forever to make intercession for them.","vcita":"Hebrews 7:25","pista":"«His intercession never takes a day off.»"},{"pregunta":"According to Hebrews 9:22, what is there NONE of apart from shedding of blood?","opciones":["Remission of sins","Purification of the tabernacle","Celebration of the Passover","Anointing of the priests"],"dato":"According to the law, nearly everything was cleansed with blood, and apart from shedding of blood there is no remission: forgiveness required the blood of Christ.","cita":"Hebrews 9:22","versiculo":"According to the law, nearly everything is cleansed with blood, and apart from shedding of blood there is no remission.","vcita":"Hebrews 9:22","pista":"«Forgiveness without shed blood: the text says it does not exist.»"},{"pregunta":"According to Hebrews 9:27, what comes after man dies once?","opciones":["Judgment","Another life on earth","An eternal sleep with no awakening","Purification by fire"],"dato":"It is appointed for men to die once, and after this, judgment: there are no return trips in this life.","cita":"Hebrews 9:27","versiculo":"Inasmuch as it is appointed for men to die once, and after this, judgment,","vcita":"Hebrews 9:27","pista":"«One single death, and then an account to give.»"},{"pregunta":"What habit of some people does Hebrews 10:25 warn against?","opciones":["Forsaking the assembling together","Fasting without praying","Tithing only once a year","Teaching without being sent"],"dato":"Hebrews commands us not to forsake our own assembling together, as the custom of some is, but to exhort one another — and so much the more as the Day approaches.","cita":"Hebrews 10:25","versiculo":"not forsaking our own assembling together, as the custom of some is, but exhorting one another, and so much the more as you see the Day approaching.","vcita":"Hebrews 10:25","pista":"«It has to do with gathering… or skipping the gathering.»"},{"pregunta":"Complete the definition in Hebrews 11:1: “Now faith is assurance of things hoped for, ______ of things not seen.”","opciones":["Proof","Conviction","Sure hope","A faithful shadow"],"dato":"Hebrews 11:1 defines faith as the assurance of things hoped for and the proof of things not seen; the whole chapter illustrates that definition.","cita":"Hebrews 11:1","versiculo":"Now faith is assurance of things hoped for, proof of things not seen.","vcita":"Hebrews 11:1","pista":"«Not a wish: it is evidence, a proof.»"},{"pregunta":"According to Hebrews 11:6, what is impossible without faith?","opciones":["To be well pleasing to God","To know the law of Moses","To keep the Sabbath day","To offer acceptable sacrifices"],"dato":"Without faith it is impossible to be well pleasing to God, for whoever comes to him must believe that he exists, and that he is a rewarder of those who seek him.","cita":"Hebrews 11:6","versiculo":"Without faith it is impossible to be well pleasing to him, for he who comes to God must believe that he exists, and that he is a rewarder of those who seek him.","vcita":"Hebrews 11:6","pista":"«Faith is not optional to please him: it is the door.»"},{"pregunta":"What did Moses, when he had grown up, refuse by faith, according to Hebrews 11:24?","opciones":["To be called the son of Pharaoh’s daughter","To be called a god by the Egyptians","To receive the crown of Egypt in his lifetime","To lead Israel without crossing the desert"],"dato":"By faith, Moses, when he had grown up, refused to be called the son of Pharaoh’s daughter, choosing rather to share ill treatment with God’s people than to enjoy the pleasures of sin for a time.","cita":"Hebrews 11:24","versiculo":"By faith Moses, when he had grown up, refused to be called the son of Pharaoh’s daughter,","vcita":"Hebrews 11:24","pista":"«He traded the palace for the people of God.»"},{"pregunta":"What is affirmed about Jesus Christ in Hebrews 13:8?","opciones":["That he is the same yesterday, today, and forever","That he was the first of the prophets","That he changes as his people mature","That he stopped interceding after ascending"],"dato":"Jesus Christ is the same yesterday, today, and forever: in a changing world, he does not change.","cita":"Hebrews 13:8","versiculo":"Jesus Christ is the same yesterday, today, and forever.","vcita":"Hebrews 13:8","pista":"«Three tenses, one single word: the same.»"}],"James":[{"pregunta":"According to James 1:5, what should the one who lacks wisdom do?","opciones":["Ask it of God, who gives to all liberally","Seek it from the elders of his land","Wait for it to come with the years","Study the books of the wise men"],"dato":"If any of you lacks wisdom, let him ask of God, who gives to all liberally and without reproach; and it will be given to him.","cita":"James 1:5","versiculo":"But if any of you lacks wisdom, let him ask of God, who gives to all liberally and without reproach, and it will be given to him.","vcita":"James 1:5","pista":"«It does not come with birthdays: you ask upward.»"},{"pregunta":"When someone is tempted, what must he NOT say, according to James 1:13?","opciones":["“I am tempted by God”","“The devil has defeated me”","“My sin has no remedy”","“No one knows my struggle”"],"dato":"God cannot be tempted by evil, and he himself tempts no one: temptation is born of man's own lust, not of God.","cita":"James 1:13","versiculo":"Let no man say when he is tempted, “I am tempted by God,” for God can’t be tempted by evil, and he himself tempts no one.","vcita":"James 1:13","pista":"«Blaming God: that is the forbidden line.»"},{"pregunta":"From whom does every good and perfect gift come down, according to James 1:17?","opciones":["From the Father of lights, with whom there is no variation","From the angels who serve in heaven","From the effort of the righteous man","From the generosity of rulers"],"dato":"Every good gift and every perfect gift is from above, coming down from the Father of lights, with whom there is no variation nor turning shadow.","cita":"James 1:17","versiculo":"Every good gift and every perfect gift is from above, coming down from the Father of lights, with whom can be no variation nor turning shadow.","vcita":"James 1:17","pista":"«Everything good comes down from the same place: the Father.»"},{"pregunta":"What does James 1:22 command concerning the word?","opciones":["To be doers of it, and not only hearers","To memorize it before obeying it","To hear it only on the Sabbath","To teach it before practicing it"],"dato":"James commands us to be doers of the word and not only hearers, for hearing without obeying is deluding ourselves.","cita":"James 1:22","versiculo":"But be doers of the word, and not only hearers, deluding your own selves.","vcita":"James 1:22","pista":"«Hearing is half of it; the other half is doing.»"},{"pregunta":"What is pure religion before God, according to James 1:27?","opciones":["To visit the fatherless and widows in their affliction, and to keep oneself unstained by the world","To fast twice a week and tithe everything","To do no work on the Sabbath","To make a pilgrimage to Jerusalem every year"],"dato":"Pure religion and undefiled before God is this: to visit the fatherless and widows in their affliction, and to keep oneself unstained by the world.","cita":"James 1:27","versiculo":"Pure religion and undefiled before our God and Father is this: to visit the fatherless and widows in their affliction, and to keep oneself unstained by the world.","vcita":"James 1:27","pista":"«Less ritual, more visiting those who suffer.»"},{"pregunta":"Complete James 2:17: “Even so faith, if it has no ______, is dead in itself.”","opciones":["Works","Eloquent words","Witnesses","Feelings"],"dato":"Faith without works is dead in itself: true faith shows itself in deeds, not only in confessions.","cita":"James 2:17","versiculo":"Even so faith, if it has no works, is dead in itself.","vcita":"James 2:17","pista":"«Faith with empty hands: dead faith.»"},{"pregunta":"What does James 2:19 say the demons also do?","opciones":["They believe God is one—and shudder","They pray without ceasing for men","They keep the ancient commandments","They confess their sins and repent"],"dato":"Believing that God is one is not enough: the demons also believe—and shudder; the difference is in obeying, not merely believing.","cita":"James 2:19","versiculo":"You believe that God is one. You do well. The demons also believe—and shudder.","vcita":"James 2:19","pista":"«Even demons “believe”… and tremble.»"},{"pregunta":"What beautiful title did Abraham receive, according to James 2:23?","opciones":["Friend of God","Father of kings","Prince of peace","A man after God's own heart"],"dato":"Abraham believed God, and it was accounted to him as righteousness, and he was called the friend of God: his faith was seen in his obedience.","cita":"James 2:23","versiculo":"So the Scripture was fulfilled which says, “Abraham believed God, and it was accounted to him as righteousness,” and he was called the friend of God.","vcita":"James 2:23","pista":"«Not servant, not king: friend.»"},{"pregunta":"What member of the body does James say nobody can tame?","opciones":["The tongue","The hand","The eye","The ear"],"dato":"Nobody can tame the tongue; it is a restless evil, full of deadly poison — that is why we must guard what we say.","cita":"James 3:8","versiculo":"but nobody can tame the tongue. It is a restless evil, full of deadly poison.","vcita":"James 3:8","pista":"«Small, quick, and poisonous: it lives in the mouth.»"},{"pregunta":"Complete James 4:7: “Be subject therefore to God. Resist the devil, and ______.”","opciones":["He will flee from you","He will be shamed forever","He will not touch your children","He will confess his wicked deeds"],"dato":"James's recipe is double: be subject to God and resist the devil; the promised result is that the devil will flee.","cita":"James 4:7","versiculo":"Be subject therefore to God. Resist the devil, and he will flee from you.","vcita":"James 4:7","pista":"«First surrender to God; then stand your ground.»"},{"pregunta":"In whom is sin, according to James 4:17?","opciones":["In him who knows to do good and does not do it","In him who doubts his salvation","In him who does not know the law","In him who sins without realizing it"],"dato":"James teaches the sin of omission: to him who knows to do good and doesn't do it, to him it is sin.","cita":"James 4:17","versiculo":"To him therefore who knows to do good and doesn’t do it, to him it is sin.","vcita":"James 4:17","pista":"«He did nothing wrong… and that was the problem.»"},{"pregunta":"Complete James 5:16: “The insistent prayer of a righteous person is ______.”","opciones":["Powerfully effective","Chain-breaking","Mountain-moving","Heaven-opening"],"dato":"James commands us to confess our sins to one another and pray for one another; the insistent prayer of a righteous person is powerfully effective.","cita":"James 5:16","versiculo":"Confess your sins to one another and pray for one another, that you may be healed. The insistent prayer of a righteous person is powerfully effective.","vcita":"James 5:16","pista":"«In this version the key word means: it works, powerfully.»"}],"1 Peter":[{"pregunta":"To what did God cause us to be born again according to his great mercy, in 1 Peter 1:3?","opciones":["To a living hope, through the resurrection of Jesus Christ from the dead","To inherit riches in this life","To never go through trials again","To judge the nations with him"],"dato":"The God and Father of our Lord Jesus Christ, according to his great mercy, caused us to be born again to a living hope through the resurrection of Jesus Christ from the dead.","cita":"1 Peter 1:3","versiculo":"Blessed be the God and Father of our Lord Jesus Christ, who according to his great mercy caused us to be born again to a living hope through the resurrection of Jesus Christ from the dead,","vcita":"1 Peter 1:3","pista":"«A hope that is not dead: it is living.»"},{"pregunta":"With what were we ransomed from our futile way of life, according to 1 Peter 1:19?","opciones":["With the precious blood of Christ, as of a lamb without blemish","With corruptible gold and silver","With sacrifices of spotless animals","With the good works of our fathers"],"dato":"We were ransomed not with corruptible things like gold or silver, but with precious blood, as of a lamb without blemish or spot, the blood of Christ.","cita":"1 Peter 1:19","versiculo":"but with precious blood, as of a lamb without blemish or spot, the blood of Christ,","vcita":"1 Peter 1:19","pista":"«The price was not metal: it was blood.»"},{"pregunta":"According to 1 Peter 1:25, what endures forever?","opciones":["The Lord’s word","The grass of the fields","The beauty of man","The riches of kings"],"dato":"All flesh is like grass and withers; but the Lord’s word endures forever — and this is the word of Good News that was preached to us.","cita":"1 Peter 1:25","versiculo":"but the Lord’s word endures forever.” This is the word of Good News which was preached to you.","vcita":"1 Peter 1:25","pista":"«The grass withers; this other thing, never.»"},{"pregunta":"What should we long for as newborn babies, according to 1 Peter 2:2?","opciones":["The pure spiritual milk","The solid food of the grown-ups","The praise of men","The showiest gifts"],"dato":"Peter commands us, as newborn babies, to long for the pure spiritual milk, that with it we may grow.","cita":"1 Peter 2:2","versiculo":"as newborn babies, long for the pure spiritual milk, that with it you may grow,","vcita":"1 Peter 2:2","pista":"«To grow: the simplest, purest food.»"},{"pregunta":"As what kind of stones are we built up as a spiritual house, according to 1 Peter 2:5?","opciones":["As living stones","As stones carved by men","As stones of the old temple","As precious stones of the high priest"],"dato":"Coming to Christ, the living stone, we also, as living stones, are built up as a spiritual house, to be a holy priesthood.","cita":"1 Peter 2:5","versiculo":"You also as living stones are built up as a spiritual house, to be a holy priesthood, to offer up spiritual sacrifices, acceptable to God through Jesus Christ.","vcita":"1 Peter 2:5","pista":"«In this house, the stones breathe.»"},{"pregunta":"What four titles does Peter give to God’s people in 1 Peter 2:9?","opciones":["A chosen race, a royal priesthood, a holy nation, a people for God’s own possession","Prophets, kings, judges and Levites","Apostles, pastors, teachers and evangelists","Sojourners, slaves, servants and exiles"],"dato":"You are a chosen race, a royal priesthood, a holy nation, a people for God’s own possession, to proclaim the excellence of him who called us out of darkness into his marvelous light.","cita":"1 Peter 2:9","versiculo":"But you are a chosen race, a royal priesthood, a holy nation, a people for God’s own possession, that you may proclaim the excellence of him who called you out of darkness into his marvelous light.","vcita":"1 Peter 2:9","pista":"«Four titles of honor, all in one verse.»"},{"pregunta":"Complete 1 Peter 2:24: “He himself bore our sins in his body on the tree… You were ______ by his wounds.”","opciones":["Healed","Hidden","Tested","Called"],"dato":"Christ himself bore our sins in his body on the tree, that we, having died to sins, might live to righteousness; by his wounds we were healed.","cita":"1 Peter 2:24","versiculo":"He himself bore our sins in his body on the tree, that we, having died to sins, might live to righteousness. You were healed by his wounds.","vcita":"1 Peter 2:24","pista":"«His wounds produced our healing.»"},{"pregunta":"For what must we always be ready, according to 1 Peter 3:15?","opciones":["To give an answer to everyone who asks a reason for the hope that is in us","To debate the philosophers of the city","To flee in time of persecution","To keep silence before unbelievers"],"dato":"Peter commands us to sanctify the Lord God in our hearts and always be ready to give an answer, with humility and fear, to everyone who asks a reason concerning our hope.","cita":"1 Peter 3:15","versiculo":"But sanctify the Lord God in your hearts. Always be ready to give an answer to everyone who asks you a reason concerning the hope that is in you, with humility and fear,","vcita":"1 Peter 3:15","pista":"«Always ready… but with humility.»"},{"pregunta":"According to 1 Peter 3:18, who suffered once for sins, the righteous for the unrighteous, to bring us to God?","opciones":["Christ","Peter","An angel from heaven","The high priest Caiaphas"],"dato":"Christ also suffered for sins once, the righteous for the unrighteous, that he might bring us to God, being put to death in the flesh, but made alive in the Spirit.","cita":"1 Peter 3:18","versiculo":"Because Christ also suffered for sins once, the righteous for the unrighteous, that he might bring you to God, being put to death in the flesh, but made alive in the Spirit,","vcita":"1 Peter 3:18","pista":"«Once only, one righteous man, for many unrighteous.»"},{"pregunta":"Complete 1 Peter 4:8: “Be earnest in your love among yourselves, for love ______ a multitude of sins.”","opciones":["Covers","Forgets","Judges","Reveals"],"dato":"Above all things, Peter commands us to be earnest in our love among ourselves, for love covers a multitude of sins.","cita":"1 Peter 4:8","versiculo":"And above all things be earnest in your love among yourselves, for love covers a multitude of sins.","vcita":"1 Peter 4:8","pista":"«Love does not count sins: it covers them.»"},{"pregunta":"Why should we cast all our worries on God, according to 1 Peter 5:7?","opciones":["Because he cares for us","Because he punishes the careless","Because the law of Moses ordered it","Because the angels keep the count"],"dato":"Casting all your worries on him, because he cares for you: anxiety is handed over, not carried.","cita":"1 Peter 5:7","versiculo":"casting all your worries on him, because he cares for you.","vcita":"1 Peter 5:7","pista":"«Drop the load: someone is looking after you.»"},{"pregunta":"How does 1 Peter 5:8 describe our adversary, the devil?","opciones":["He walks around like a roaring lion, seeking whom he may devour","As a serpent hidden in the dust","As a wolf dressed as a sheep","As a storm coming from far away"],"dato":"Be sober and watchful: your adversary, the devil, walks around like a roaring lion, seeking whom he may devour.","cita":"1 Peter 5:8","versiculo":"Be sober and self-controlled. Be watchful. Your adversary, the devil, walks around like a roaring lion, seeking whom he may devour.","vcita":"1 Peter 5:8","pista":"«He roars and prowls: stay awake.»"}],"2 Peter":[{"pregunta":"Of what are we made partakers through the precious and exceedingly great promises, according to 2 Peter 1:4?","opciones":["Of the divine nature","Of the apostles’ sufferings","Of Abraham’s inheritance","Of the Levitical priesthood"],"dato":"Through his precious and exceedingly great promises we become partakers of the divine nature, having escaped from the corruption that is in the world by lust.","cita":"2 Peter 1:4","versiculo":"by which he has granted to us his precious and exceedingly great promises; that through these you may become partakers of the divine nature, having escaped from the corruption that is in the world by lust.","vcita":"2 Peter 1:4","pista":"«No small thing: partakers of God’s own nature.»"},{"pregunta":"In the ladder of 2 Peter 1, what must first be supplied in our faith, with all diligence?","opciones":["Moral excellence","Knowledge","Self-control","Brotherly affection"],"dato":"Peter commands us to add all diligence: in our faith supply moral excellence, and in moral excellence, knowledge; the ladder climbs all the way to love.","cita":"2 Peter 1:5","versiculo":"Yes, and for this very cause adding on your part all diligence, in your faith supply moral excellence; and in moral excellence, knowledge;","vcita":"2 Peter 1:5","pista":"«The ladder starts at faith; the first rung is character.»"},{"pregunta":"To what does Peter compare the more sure word of prophecy in 2 Peter 1:19?","opciones":["To a lamp shining in a dark place","To a sword beside the altar","To a river that never dries up","To a seed stored in good soil"],"dato":"We do well to heed the word of prophecy as to a lamp shining in a dark place, until the day dawns and the morning star arises in our hearts.","cita":"2 Peter 1:19","versiculo":"We have the more sure word of prophecy; and you do well that you heed it as to a lamp shining in a dark place, until the day dawns and the morning star arises in your hearts,","vcita":"2 Peter 1:19","pista":"«In the darkness, prophecy works like a lamp.»"},{"pregunta":"How did holy men of God speak, according to 2 Peter 1:21?","opciones":["Being moved by the Holy Spirit","By their own will and cleverness","Copying the traditions of the elders","According to the dreams they interpreted"],"dato":"No prophecy ever came by the will of man, but holy men of God spoke, being moved by the Holy Spirit.","cita":"2 Peter 1:21","versiculo":"For no prophecy ever came by the will of man, but holy men of God spoke, being moved by the Holy Spirit.","vcita":"2 Peter 1:21","pista":"«Not a human invention: there was a Mover behind it.»"},{"pregunta":"What unusual event did God use to rebuke Balaam’s disobedience, according to 2 Peter 2:16?","opciones":["A speechless donkey spoke with a man’s voice","An angel blocked the road with a sword","The ground opened beneath his feet","A raven took away his speech for three days"],"dato":"Balaam was rebuked for his own disobedience: a speechless donkey spoke with a man’s voice and stopped the madness of the prophet.","cita":"2 Peter 2:16","versiculo":"but he was rebuked for his own disobedience. A speechless donkey spoke with a man’s voice and stopped the madness of the prophet.","vcita":"2 Peter 2:16","pista":"«Balaam’s donkey preaches the shortest famous sermon.»"},{"pregunta":"What double proverb does Peter quote in 2 Peter 2:22 for those who turn back?","opciones":["The dog turns to his own vomit again, and the washed sow to wallowing in the mire","The fox returns to its den, and the eagle to its nest","The fish returns to the river, and the bird to its branch","The goat returns to the mountain, and the sheep to the fold"],"dato":"It has happened to them according to the true proverb: “The dog turns to his own vomit again,” and “the sow that has washed to wallowing in the mire.”","cita":"2 Peter 2:22","versiculo":"But it has happened to them according to the true proverb, “The dog turns to his own vomit again,” and “the sow that has washed to wallowing in the mire.”","vcita":"2 Peter 2:22","pista":"«Two animals, two pitiful returns.»"},{"pregunta":"Who will come in the last days, according to 2 Peter 3:3?","opciones":["Mockers, walking after their own lusts","False prophets with signs and wonders","Kings from the east with great armies","Fallen angels in the form of men"],"dato":"Knowing this first: in the last days mockers will come, walking after their own lusts, scoffing at the promise of his coming.","cita":"2 Peter 3:3","versiculo":"knowing this first, that in the last days mockers will come, walking after their own lusts","vcita":"2 Peter 3:3","pista":"«They will laugh at the promise: Peter warned us.»"},{"pregunta":"How is one day with the Lord, according to 2 Peter 3:8?","opciones":["As a thousand years, and a thousand years as one day","As the twinkling of an eye","Like grass that blooms and withers","Like an hourglass without end"],"dato":"Do not forget this one thing: one day is with the Lord as a thousand years, and a thousand years as one day; God’s clock is not ours.","cita":"2 Peter 3:8","versiculo":"But don’t forget this one thing, beloved, that one day is with the Lord as a thousand years, and a thousand years as one day.","vcita":"2 Peter 3:8","pista":"«With God, a thousand years fit inside a day.»"},{"pregunta":"Why is the Lord not slow concerning his promise, according to 2 Peter 3:9?","opciones":["Because he is patient, not wishing that anyone should perish, but that all should come to repentance","Because signs in heaven are still unfulfilled","Because the angels are not yet prepared","Because his coming depends on the kings of the earth"],"dato":"The Lord is not slow concerning his promise, as some count slowness; he is patient with us, not wishing that anyone should perish, but that all should come to repentance.","cita":"2 Peter 3:9","versiculo":"The Lord is not slow concerning his promise, as some count slowness; but he is patient with us, not wishing that anyone should perish, but that all should come to repentance.","vcita":"2 Peter 3:9","pista":"«If he “delays,” it is out of patience, not forgetfulness.»"},{"pregunta":"How will the day of the Lord come, according to 2 Peter 3:10?","opciones":["As a thief in the night","With trumpets announced by the prophets","After seven years of visible signs","When all peoples are expecting it"],"dato":"The day of the Lord will come as a thief in the night, in which the heavens will pass away with a great noise and the elements will be dissolved with fervent heat.","cita":"2 Peter 3:10","versiculo":"But the day of the Lord will come as a thief in the night, in which the heavens will pass away with a great noise, and the elements will be dissolved with fervent heat; and the earth and the works that are in it will be burned up.","vcita":"2 Peter 3:10","pista":"«No warning, no jingling keys: like a thief.»"},{"pregunta":"What do we look for, according to his promise, in 2 Peter 3:13?","opciones":["New heavens and a new earth, in which righteousness dwells","The return of the old Eden on this same earth","A thousand-year kingdom on Mount Zion","The rebuilding of Solomon’s temple"],"dato":"According to his promise, we look for new heavens and a new earth, in which righteousness dwells.","cita":"2 Peter 3:13","versiculo":"But, according to his promise, we look for new heavens and a new earth, in which righteousness dwells.","vcita":"2 Peter 3:13","pista":"«Everything new, and righteousness living there.»"},{"pregunta":"In what does Peter command us to grow as he closes his letter, in 2 Peter 3:18?","opciones":["In the grace and knowledge of our Lord and Savior Jesus Christ","In number of churches and disciples","In riches to help the poor","In the knowledge of prophecies alone"],"dato":"Peter’s farewell is a command to grow: grow in the grace and knowledge of our Lord and Savior Jesus Christ.","cita":"2 Peter 3:18","versiculo":"But grow in the grace and knowledge of our Lord and Savior Jesus Christ. To him be the glory both now and forever. Amen.","vcita":"2 Peter 3:18","pista":"«The letter’s last command: grow.»"}],"1 John":[{"pregunta":"What great truth about God does John announce near the beginning of his first letter?","opciones":["God is light, and in him is no darkness at all","God is a fire that no one can look upon","God is a mystery that no one can know","God is wind, and no one knows where he comes from"],"dato":"John presents God as pure light: in him there is not a single shadow of darkness.","cita":"1 John 1:5","versiculo":"This is the message which we have heard from him and announce to you, that God is light, and in him is no darkness at all.","vcita":"1 John 1:5","pista":"«Without light nothing can be seen; in God there is room for no shadow.»"},{"pregunta":"If anyone sins, whom do we have as a Counselor with the Father?","opciones":["Jesus Christ, the righteous","Michael the archangel","John the apostle","A priest of the law"],"dato":"John writes so that we may not sin, but if anyone does sin, Jesus Christ the righteous is our Counselor with the Father.","cita":"1 John 2:1","versiculo":"My little children, I write these things to you so that you may not sin. If anyone sins, we have a Counselor with the Father, Jesus Christ, the righteous.","vcita":"1 John 2:1","pista":"«He is the very one who gave his life for us: no one defends us better.»"},{"pregunta":"Jesus Christ is the atoning sacrifice for our sins — and for whose sins besides ours?","opciones":["Also for the sins of the whole world","Only for the apostles' sins","Only for the sins of Israel","Only for the sins of those who have already died"],"dato":"Christ's atoning sacrifice is not limited to one group: it reaches the sins of the whole world.","cita":"1 John 2:2","versiculo":"And he is the atoning sacrifice for our sins, and not for ours only, but also for the whole world.","vcita":"1 John 2:2","pista":"«Its reach is as wide as the entire planet.»"},{"pregunta":"What three things does John say are in the world and are not of the Father?","opciones":["The lust of the flesh, the lust of the eyes, and the pride of life","War, plague, and famine","Gold, silver, and precious stones","Lying, stealing, and murder"],"dato":"Everything the world offers boils down to lust of the flesh, lust of the eyes, and the pride of life; none of it comes from the Father.","cita":"1 John 2:16","versiculo":"For all that is in the world—the lust of the flesh, the lust of the eyes, and the pride of life—isn't the Father's, but is the world's.","vcita":"1 John 2:16","pista":"«Two are desires entering through body and sight; the third is pride.»"},{"pregunta":"What do believers have, received from the Holy One, by which they know all things?","opciones":["The anointing","A sealed letter","A mark on the forehead","The gift of tongues"],"dato":"The anointing from the Holy One remains in believers and teaches them; by it they tell truth from deception.","cita":"1 John 2:20","versiculo":"You have an anointing from the Holy One, and you all have knowledge.","vcita":"1 John 2:20","pista":"«Think of the oil used to consecrate kings and priests.»"},{"pregunta":"When Christ is revealed, why will we be like him?","opciones":["Because we will see him just as he is","Because we will bear his name on our foreheads","Because we will judge the angels","Because we will eat from the tree of life"],"dato":"What we will be has not yet been revealed, but seeing Christ as he is will transform us into his likeness.","cita":"1 John 3:2","versiculo":"Beloved, now we are children of God. It is not yet revealed what we will be; but we know that when he is revealed, we will be like him, for we will see him just as he is.","vcita":"1 John 3:2","pista":"«The key is in the seeing: when we see him, we become like him.»"},{"pregunta":"According to 1 John, why did Cain kill his brother Abel?","opciones":["Because his deeds were evil, and his brother's righteous","Because Abel took his inheritance","Because Abel accused him before Adam","Because they quarreled over a woman"],"dato":"John uses Cain as a warning: he killed Abel not over an inheritance, but because his own deeds were evil compared with his brother's righteous ones.","cita":"1 John 3:12","versiculo":"unlike Cain, who was of the evil one and killed his brother. Why did he kill him? Because his deeds were evil, and his brother's righteous.","vcita":"1 John 3:12","pista":"«It was not about a thing: it was the contrast between two kinds of deeds.»"},{"pregunta":"How do we know that we have passed out of death into life?","opciones":["Because we love the brothers","Because we keep the day of rest","Because we have seen a sign","Because we speak in tongues"],"dato":"The sign of new life is not a rite but real love for the brothers; whoever does not love remains in death.","cita":"1 John 3:14","versiculo":"We know that we have passed out of death into life, because we love the brothers. He who doesn't love his brother remains in death.","vcita":"1 John 3:14","pista":"«The proof of new life shows in how you treat your brother.»"},{"pregunta":"How does John command us to love, instead of loving only in word?","opciones":["In deed and truth","With great speeches","Only on feast days","In secret, so no one notices"],"dato":"True love does not stay in fine words or on the tongue: it is shown in deeds and in truth.","cita":"1 John 3:18","versiculo":"My little children, let's not love in word only, or with the tongue only, but in deed and truth.","vcita":"1 John 3:18","pista":"«Less talking, more doing: two words sum it up — deed and truth.»"},{"pregunta":"How is the Spirit of God known, according to the test John gives?","opciones":["Every spirit who confesses that Jesus Christ has come in the flesh is of God","Every spirit who performs great signs is of God","Every spirit who speaks with a loud voice is of God","Every spirit who appears at night is of God"],"dato":"John commands us to test the spirits: the decisive test is confessing that Jesus Christ has come in the flesh.","cita":"1 John 4:2","versiculo":"By this you know the Spirit of God: every spirit who confesses that Jesus Christ has come in the flesh is of God,","vcita":"1 John 4:2","pista":"«The test is not the spectacle, but what it confesses about Jesus.»"},{"pregunta":"What does perfect love cast out, according to John?","opciones":["Fear","Sleep","Other people's sadness","The memory of the past"],"dato":"There is no fear in love: perfect love drives fear out, because fear has to do with punishment.","cita":"1 John 4:18","versiculo":"There is no fear in love; but perfect love casts out fear, because fear has punishment. He who fears is not made perfect in love.","vcita":"1 John 4:18","pista":"«It is the opposite of mature love: it starts with «fe» and it paralyzes.»"},{"pregunta":"Which three testify on earth, according to 1 John 5?","opciones":["The Spirit, the water, and the blood","The Father, the Son, and the Holy Spirit","The law, the prophets, and the psalms","Faith, hope, and love"],"dato":"Three witnesses agree on earth concerning the Son: the Spirit, the water, and the blood, and the three agree as one.","cita":"1 John 5:8","versiculo":"the Spirit, the water, and the blood; and the three agree as one.","vcita":"1 John 5:8","pista":"«One is a divine Person; the other two recall the baptism and the cross.»"}],"2 John":[{"pregunta":"To whom is John's second letter addressed?","opciones":["To the chosen lady and her children","To the church in Ephesus","To Gaius the beloved","To the widow of Zarephath"],"dato":"The elder writes to «the chosen lady and her children», whom he loves in truth together with all who know the truth.","cita":"2 John 1:1","versiculo":"The elder, to the chosen lady and her children, whom I love in truth, and not I only, but also all those who know the truth,","vcita":"2 John 1:1","pista":"«Not a church named by city: it is a lady and her family.»"},{"pregunta":"What three blessings does John wish upon the recipients in his greeting?","opciones":["Grace, mercy, and peace","Faith, hope, and love","Health, money, and long life","Joy, patience, and kindness"],"dato":"The greeting of 2 John gathers grace, mercy, and peace from God the Father and from the Lord Jesus Christ, in truth and love.","cita":"2 John 1:3","versiculo":"Grace, mercy, and peace will be with us, from God the Father and from the Lord Jesus Christ, the Son of the Father, in truth and love.","vcita":"2 John 1:3","pista":"«The middle one is what God gives us when we need it most: mercy.»"},{"pregunta":"What did John find about the lady's children that made him rejoice greatly?","opciones":["That some of them were walking in truth","That they had prospered in business","That they had escaped a persecution","That they had memorized the Scriptures"],"dato":"The elder rejoiced greatly to learn that some of the lady's children were walking in truth, as the Father commanded.","cita":"2 John 1:4","versiculo":"I rejoice greatly that I have found some of your children walking in truth, even as we have been commanded by the Father.","vcita":"2 John 1:4","pista":"«Walking is the key word: not only knowing it, but living in it.»"},{"pregunta":"Which commandment does John plead for, making clear it is not new but the one had from the beginning?","opciones":["That we love one another","That the seventh day be kept","That an altar be built","That everyone fast twice a week"],"dato":"John brings no new commandment: he pleads that the old one be lived — that we love one another.","cita":"2 John 1:5","versiculo":"Now I beg you, dear lady, not as though I wrote to you a new commandment, but that which we had from the beginning, that we love one another.","vcita":"2 John 1:5","pista":"«It is as old as the gospel itself: it concerns your neighbor.»"},{"pregunta":"How does John define love in his second letter?","opciones":["That we should walk according to his commandments","That we feel peace in our hearts","That we never argue with anyone","That we give away everything we have"],"dato":"For John, love is not merely a feeling: it is walking according to God's commandments, as was heard from the beginning.","cita":"2 John 1:6","versiculo":"This is love, that we should walk according to his commandments. This is the commandment, even as you heard from the beginning, that you should walk in it.","vcita":"2 John 1:6","pista":"«Love is measured by walking, and the path is marked by the commandments.»"},{"pregunta":"According to 2 John, who is «the deceiver and the Antichrist»?","opciones":["The one who doesn't confess that Jesus Christ came in the flesh","The one who argues with the elders","The one who arrives late to the meetings","The one who doesn't greet others when entering"],"dato":"Many deceivers have gone out into the world; whoever denies that Jesus Christ came in the flesh is the deceiver and the Antichrist.","cita":"2 John 1:7","versiculo":"For many deceivers have gone out into the world, those who don't confess that Jesus Christ came in the flesh. This is the deceiver and the Antichrist.","vcita":"2 John 1:7","pista":"«The key denial concerns the real body of Jesus.»"},{"pregunta":"Why were believers to watch themselves, according to 2 John 1:8?","opciones":["So as not to lose what they had accomplished, but receive a full reward","So no one would take their belongings","So they could escape the city in time","So they would be recognized as apostles"],"dato":"John warns that what has been worked for can be lost; the goal is to receive the full reward, not just part of it.","cita":"2 John 1:8","versiculo":"Watch yourselves, that we don't lose the things which we have accomplished, but that we receive a full reward.","vcita":"2 John 1:8","pista":"«It is like guarding a harvest already planted, to collect it in full.»"},{"pregunta":"According to 2 John, who has both the Father and the Son?","opciones":["He who remains in the teaching of Christ","He who knows many languages","He who has visited Jerusalem","He who fasts every Friday"],"dato":"Whoever transgresses and doesn't remain in the teaching of Christ doesn't have God; whoever remains in it has both the Father and the Son.","cita":"2 John 1:9","versiculo":"Whoever transgresses and doesn't remain in the teaching of Christ doesn't have God. He who remains in the teaching has both the Father and the Son.","vcita":"2 John 1:9","pista":"«The key word is remain, not just start.»"},{"pregunta":"If someone comes to you and doesn't bring the teaching of Christ, what does John command?","opciones":["Don't receive him into your house, and don't welcome him","Listen to him for three days before deciding","Feed him and let him teach","Take him before the elders for a debate"],"dato":"Hospitality was not to open the door to false teaching: neither receive into the house nor welcome the one who doesn't bring the teaching of Christ.","cita":"2 John 1:10","versiculo":"If anyone comes to you and doesn't bring this teaching, don't receive him into your house, and don't welcome him,","vcita":"2 John 1:10","pista":"«Neither the house nor the greeting: door and mouth close to false teaching.»"},{"pregunta":"Why must the false teacher not be welcomed?","opciones":["Because he who welcomes him participates in his evil deeds","Because it is rude to greet strangers","Because John wanted to test them first","Because greetings were reserved for the Sabbath"],"dato":"Welcoming a false teacher with approval makes the welcomer a participant in his evil deeds.","cita":"2 John 1:11","versiculo":"for he who welcomes him participates in his evil deeds.","vcita":"2 John 1:11","pista":"«A greeting seems small, but John counts it as complicity.»"},{"pregunta":"Why did John prefer not to communicate everything with paper and ink?","opciones":["He hoped to come and speak face to face, so that their joy may be full","Because he had run out of ink","Because the road was dangerous for messengers","Because he feared the letter would be lost"],"dato":"The elder had much more to write, but he preferred the personal visit: speaking face to face would make their joy full.","cita":"2 John 1:12","versiculo":"Having many things to write to you, I don't want to do so with paper and ink, but I hope to come to you and to speak face to face, that our joy may be made full.","vcita":"2 John 1:12","pista":"«Some conversations don't fit in a letter: they require presence.»"},{"pregunta":"Who sends greetings at the end of John's second letter?","opciones":["The children of your chosen sister","The apostles from Jerusalem","The brothers of the church in Rome","The sons of Zebedee"],"dato":"The letter closes with greetings from the children of the recipient's «chosen sister»: two families in the same truth.","cita":"2 John 1:13","versiculo":"The children of your chosen sister greet you. Amen.","vcita":"2 John 1:13","pista":"«They are relatives of the recipient: her sister's children.»"}],"3 John":[{"pregunta":"To whom is John's third letter addressed?","opciones":["To Gaius the beloved","To the chosen lady","To Diotrephes, the one who loved to be first","To Philemon, the fellow worker"],"dato":"The elder writes to Gaius, his beloved in truth, an example of hospitality and faithfulness.","cita":"3 John 1:1","versiculo":"The elder to Gaius the beloved, whom I love in truth.","vcita":"3 John 1:1","pista":"«His name starts with G and he is famous for welcoming the brothers well.»"},{"pregunta":"What wish does John express for Gaius at the start of the letter?","opciones":["That he may prosper in all things and be healthy, even as his soul prospers","That he would become an elder of the church","That he would travel to Jerusalem soon","That he would also write a letter to the churches"],"dato":"John wishes Gaius whole prosperity: in all things, and health of body, matching the prosperity of his soul.","cita":"3 John 1:2","versiculo":"Beloved, I pray that you may prosper in all things and be healthy, even as your soul prospers.","vcita":"3 John 1:2","pista":"«It is a double wish: health outside, and a soul already prospering inside.»"},{"pregunta":"What is John's greatest joy, according to his third letter?","opciones":["To hear about his children walking in truth","To see the number of churches grow","To receive letters from the apostles","To know the false teachers had left"],"dato":"Nothing gladdens the elder more than hearing that his children in the faith walk in truth.","cita":"3 John 1:4","versiculo":"I have no greater joy than this: to hear about my children walking in truth.","vcita":"3 John 1:4","pista":"«It is not joy over things, but over people walking well.»"},{"pregunta":"For what faithful work does Gaius stand out, according to the brothers who visited him?","opciones":["For whatever he accomplished for the brothers and for strangers","For the hymns he composed for the church","For having built the meeting house","For memorizing the Psalms in full"],"dato":"The brothers testified that Gaius faithfully served both those he knew and the strangers who arrived.","cita":"3 John 1:5","versiculo":"Beloved, you do a faithful work in whatever you accomplish for those who are brothers and strangers.","vcita":"3 John 1:5","pista":"«His faithfulness showed toward two groups: those at home and those from outside.»"},{"pregunta":"How had the workers gone out whom Gaius helped?","opciones":["They went out for the sake of the Name, taking nothing from the Gentiles","With a letter of recommendation from the council","Escorted by Roman soldiers","With funds gathered by three churches"],"dato":"Those brothers went out for the sake of Christ's Name without accepting help from the Gentiles; therefore the church was to support them.","cita":"3 John 1:7","versiculo":"because for the sake of the Name they went out, taking nothing from the Gentiles.","vcita":"3 John 1:7","pista":"«They set out empty-handed from outsiders, trusting in the Name.»"},{"pregunta":"Why should we receive and support workers like those Gaius helped?","opciones":["So that we may be fellow workers for the truth","So that the church becomes more numerous","So we can compete with other churches","To keep an annual tradition"],"dato":"Supporting those who go out to serve makes the believer a partner and fellow worker of the truth itself.","cita":"3 John 1:8","versiculo":"We therefore ought to receive such, that we may be fellow workers for the truth.","vcita":"3 John 1:8","pista":"«By opening your door, you become a partner in the mission.»"},{"pregunta":"Who refused to accept John and his messengers because he loved to be first?","opciones":["Diotrephes","Demetrius","Gaius","Alexander the coppersmith"],"dato":"Diotrephes, who loved to be first among the brothers, rejected the apostle and his messengers: closed pride, in contrast with Gaius's hospitality.","cita":"3 John 1:9","versiculo":"I wrote to the assembly, but Diotrephes, who loves to be first among them, doesn't accept what we say.","vcita":"3 John 1:9","pista":"«His problem fits in one sentence: he wanted to be first.»"},{"pregunta":"Besides not receiving the brothers, what else did Diotrephes do against them?","opciones":["He forbade those who would receive them and threw them out of the assembly","He charged them to enter the meetings","He reported them to the Roman authorities","He burned the apostles' letters"],"dato":"Diotrephes not only closed his own door: he unjustly accused John with wicked words, blocked others' hospitality, and expelled from the church those who practiced it.","cita":"3 John 1:10","versiculo":"Therefore, if I come, I will call attention to his deeds which he does, unjustly accusing us with wicked words. Not content with this, he doesn't receive the brothers himself, and those who would, he forbids and throws out of the assembly.","vcita":"3 John 1:10","pista":"«Not content with closing his own door, he closed everyone else's too.»"},{"pregunta":"What counsel does John give Gaius in the face of Diotrephes's bad example?","opciones":["Don't imitate that which is evil, but that which is good","Leave the city for a while","Write a letter of protest to the church","Never receive any stranger again"],"dato":"The counsel is about imitation: follow what is good, not what is evil; for he who does good is of God, and he who does evil hasn't seen God.","cita":"3 John 1:11","versiculo":"Beloved, don't imitate that which is evil, but that which is good. He who does good is of God. He who does evil hasn't seen God.","vcita":"3 John 1:11","pista":"«It is a matter of whom you imitate: the good or the evil.»"},{"pregunta":"Of whom do all testify, and even the truth itself, according to 3 John?","opciones":["Of Demetrius","Of Diotrephes","Of Gaius","Of the elder John"],"dato":"Demetrius has a good testimony from everyone and from the truth itself; John also testifies of him and assures that his testimony is true.","cita":"3 John 1:12","versiculo":"Demetrius has the testimony of all, and of the truth itself; yes, we also testify, and you know that our testimony is true.","vcita":"3 John 1:12","pista":"«He is the contrast to Diotrephes: everyone speaks well of him.»"},{"pregunta":"What did John hope would happen soon, instead of going on writing with ink and pen?","opciones":["To see Gaius and speak face to face","To send Demetrius as messenger","To receive the church's reply","To visit the seven churches of Asia"],"dato":"John had many more things to write, but he hoped to see Gaius soon and talk face to face.","cita":"3 John 1:14","versiculo":"but I hope to see you soon. Then we will speak face to face. Peace be to you. The friends greet you. Greet the friends by name.","vcita":"3 John 1:14","pista":"«As in 2 John: some things are better said in person.»"},{"pregunta":"Before whom did the brothers Gaius had helped testify about his love?","opciones":["Before the assembly (the church)","Before the Roman governor","In the temple at Jerusalem","Before the elders of another city"],"dato":"The travelers helped by Gaius told of his love before the whole assembly; so John encourages him to keep sending them forward in a way worthy of God.","cita":"3 John 1:6","versiculo":"They have testified about your love before the assembly. You will do well to send them forward on their journey in a way worthy of God,","vcita":"3 John 1:6","pista":"«His love didn't stay private: it was told before the whole congregation.»"}],"Jude":[{"pregunta":"How does Jude, the letter's author, introduce himself in the greeting?","opciones":["A servant of Jesus Christ, and brother of James","An apostle and witness of the resurrection","An elder of the church in Jerusalem","The beloved disciple of the Lord"],"dato":"Jude doesn't introduce himself as the Lord's half-brother, but with humility: a servant of Jesus Christ and brother of James.","cita":"Jude 1:1","versiculo":"Jude, a servant of Jesus Christ, and brother of James, to those who are called, sanctified by God the Father, and kept for Jesus Christ:","vcita":"Jude 1:1","pista":"«His credentials are double: servant of Christ and brother of James.»"},{"pregunta":"What subject was Jude very eager to write about, before he changed the focus of his letter?","opciones":["Our common salvation","The gifts of the Holy Spirit","The chronology of the end of the world","The Levites and the priesthood"],"dato":"Jude longed to write about the salvation believers share, but urgency constrained him to write exhorting them to defend the faith.","cita":"Jude 1:3","versiculo":"Beloved, while I was very eager to write to you about our common salvation, I was constrained to write to you exhorting you to contend earnestly for the faith which was once for all delivered to the saints.","vcita":"Jude 1:3","pista":"«It was the pleasant subject shared by all: our common salvation.»"},{"pregunta":"What were the ungodly men who had crept in secretly doing, according to Jude?","opciones":["Turning the grace of God into indecency and denying the Lord","Selling indulgences to the brothers","Teaching that there is no resurrection","Forbidding marriage and certain foods"],"dato":"The infiltrators twisted grace into a license for immorality and denied our only Master and Lord, Jesus Christ.","cita":"Jude 1:4","versiculo":"For there are certain men who crept in secretly, even those who were long ago written about for this condemnation: ungodly men, turning the grace of our God into indecency, and denying our only Master, God, and Lord, Jesus Christ.","vcita":"Jude 1:4","pista":"«Twisting grace into permission to sin: that was their secret maneuver.»"},{"pregunta":"What first example from the past does Jude recall to warn the believers?","opciones":["The Lord saved a people out of Egypt and afterward destroyed those who didn't believe","Nineveh repented at Jonah's preaching","Israel crossed the Jordan into Canaan","David spared Saul's life in the cave"],"dato":"Being rescued once is not enough: the people saved out of Egypt were afterward destroyed in their unbelief.","cita":"Jude 1:5","versiculo":"Now I desire to remind you, though you already know this, that the Lord, having saved a people out of the land of Egypt, afterward destroyed those who didn't believe.","vcita":"Jude 1:5","pista":"«Saved from an empire famous for its pyramids, yet not safe for that reason.»"},{"pregunta":"What has God kept in store for the angels who didn't keep their first domain but deserted their dwelling?","opciones":["Everlasting bonds under darkness, for the judgment of the great day","To be sent to an endless desert","To serve as messengers without rest","To be turned into wandering stars"],"dato":"The fallen angels are kept under darkness, in everlasting bonds, awaiting the judgment of the great day.","cita":"Jude 1:6","versiculo":"Angels who didn't keep their first domain, but deserted their own dwelling place, he has kept in everlasting bonds under darkness for the judgment of the great day.","vcita":"Jude 1:6","pista":"«Their punishment combines two things: darkness and unbreakable chains.»"},{"pregunta":"According to Jude, Sodom and Gomorrah were shown as an example, suffering what punishment?","opciones":["The punishment of eternal fire","Being covered by the waters of the sea","Being turned into salt and ashes only","Being forgotten by all nations"],"dato":"The cities of the plain stood as a visible warning, suffering the punishment of eternal fire.","cita":"Jude 1:7","versiculo":"Even as Sodom and Gomorrah and the cities around them, having in the same way as these given themselves over to sexual immorality and gone after strange flesh, are shown as an example, suffering the punishment of eternal fire.","vcita":"Jude 1:7","pista":"«The element of the judgment is fire, and its reach is eternal.»"},{"pregunta":"When Michael the archangel contended with the devil over the body of Moses, what did he say instead of condemning him?","opciones":["«May the Lord rebuke you!»","«Get away from me, Satan»","«By God's sword you will fall»","«May your name be blotted from the book»"],"dato":"Not even Michael the archangel dared bring an abusive condemnation against the devil; he left the rebuke in the Lord's hands.","cita":"Jude 1:9","versiculo":"But Michael, the archangel, when contending with the devil and arguing about the body of Moses, dared not bring against him an abusive condemnation, but said, “May the Lord rebuke you!”","vcita":"Jude 1:9","pista":"«The sentence is short and puts the Lord first.»"},{"pregunta":"In the «Woe to them!», what three evil paths does Jude say the false teachers followed?","opciones":["The way of Cain, the error of Balaam for hire, and Korah's rebellion","The way of Esau, the error of Saul, and Absalom's rebellion","The way of the serpent, Eve's error, and the tower of Babel","The way of Judas Iscariot, Simon the sorcerer's error, and Diotrephes's complaint"],"dato":"Three Old Testament figures sum up their conduct: Cain for hatred, Balaam for gain, and Korah for rebellion.","cita":"Jude 1:11","versiculo":"Woe to them! For they went in the way of Cain, and ran riotously in the error of Balaam for hire, and perished in Korah's rebellion.","vcita":"Jude 1:11","pista":"«A fratricide, a prophet who sold himself, and a rebel against Moses.»"},{"pregunta":"With what images from nature does Jude compare the false teachers?","opciones":["Clouds without water carried along by winds, and autumn trees without fruit","Wolves in sheep's clothing and whitewashed tombs","Snakes on the path and lions lying in wait","Dry rivers and crumbling mountains"],"dato":"They promise rain and give nothing: waterless clouds, trees twice dead and uprooted, wild waves, and wandering stars.","cita":"Jude 1:12","versiculo":"These are hidden rocky reefs in your love feasts when they feast with you, shepherds who without fear feed themselves; clouds without water, carried along by winds; autumn trees without fruit, twice dead, plucked up by the roots;","vcita":"Jude 1:12","pista":"«One promises rain and never rains; the other promises a harvest and bears no fruit.»"},{"pregunta":"Who, being the seventh from Adam, prophesied that the Lord came with ten thousands of his holy ones?","opciones":["Enoch","Methuselah","Noah","Elijah"],"dato":"Jude quotes the prophecy of Enoch, the seventh from Adam, about the Lord's coming with ten thousands of his saints to execute judgment.","cita":"Jude 1:14","versiculo":"About these also Enoch, the seventh from Adam, prophesied, saying, “Behold, the Lord came with ten thousands of his holy ones,","vcita":"Jude 1:14","pista":"«He is the man who walked with God and didn't see death in Genesis.»"},{"pregunta":"How were the beloved to build themselves up, according to Jude's exhortation?","opciones":["On their most holy faith, praying in the Holy Spirit","Fasting twice a week","Separating from all other believers","Memorizing the genealogies"],"dato":"In the face of mockers, the answer is constructive: build yourselves up on the most holy faith and pray in the Holy Spirit, keeping yourselves in God's love.","cita":"Jude 1:20","versiculo":"But you, beloved, keep building up yourselves on your most holy faith, praying in the Holy Spirit.","vcita":"Jude 1:20","pista":"«The image is construction: faith is the foundation and prayer the tool.»"},{"pregunta":"According to Jude's closing doxology, what is God able to do for his own?","opciones":["Keep them from stumbling and present them faultless before his glory in great joy","Give them riches in this life","Make them judges over the nations right now","Free them from every trial in this world"],"dato":"The letter that denounces so many dangers ends in praise: God is able to keep us from stumbling and to present us faultless, in great joy.","cita":"Jude 1:24","versiculo":"Now to him who is able to keep them from stumbling, and to present you faultless before the presence of his glory in great joy,","vcita":"Jude 1:24","pista":"«The letter ends looking at God: he guards the step and presents without blemish.»"}],"Revelation":[{"pregunta":"How many were sealed out of every tribe of the children of Israel?","opciones":["One hundred forty-four thousand","Twelve thousand","Seven hundred forty-four thousand","Twenty-four thousand"],"dato":"John heard the number of those who were sealed: 144,000, twelve thousand from each tribe of Israel, marked before judgment is unleashed on the earth.","cita":"Revelation 7:4","versiculo":"I heard the number of those who were sealed, one hundred forty-four thousand, sealed out of every tribe of the children of Israel:","vcita":"Revelation 7:4","pista":"«It is twelve times twelve thousand: count it by the tribes.»"},{"pregunta":"How does the apostle (and the church) respond when the Lord says, «Yes, I am coming soon»?","opciones":["«Amen! Yes, come, Lord Jesus!»","«Not yet, Lord, wait a little»","«Your will be done in heaven»","«Send your angels first»"],"dato":"The Bible ends with a dialogue of longing: Christ promises to come soon, and his people answer with the last prayer of Scripture.","cita":"Revelation 22:20","versiculo":"He who testifies these things says, “Yes, I am coming soon.” Amen! Yes, come, Lord Jesus!","vcita":"Revelation 22:20","pista":"«They are the last answering words of the whole Bible: a «come» addressed to the Lord.»"}]};
